const app = new Hono();
app.use("/api/*", cors());

// An unhandled throw was reaching the browser as a bare 500 with an empty
// body, which is the least useful thing a server can say: indistinguishable,
// from the outside, from a network failure. Every one of these is a bug here,
// so name it.
//
// The message goes in the response as well as the log. These are a real
// user's own API calls, not a public surface, and what comes back is a D1 or
// runtime error string -- the difference between a diagnosable failure and a
// mystery is worth more than keeping column names to ourselves. Revisit if
// any of this becomes reachable unauthenticated.
app.onError((err, c) => {
  console.error("[unhandled]", c.req.method, c.req.path, err?.stack || err?.message || err);

  // A migration that has not been run is not a bug in the server, and
  // "server_error" about one sends whoever reads it looking for one. Routes
  // that expect to outrun the schema already catch this themselves; this is
  // for every route that does not, which is most of them -- GET
  // /api/my-company threw a bare 500 for want of the connect_code column and
  // said nothing about which file to run.
  //
  // missingSchema() answers "unknown" when it recognises the shape of the
  // complaint but not the name in it. That is still worth saying -- the
  // database is behind the code -- so it goes out with no migration named
  // rather than with a guess, and `detail` carries the wording either way.
  //
  // The cost, taken deliberately: a column name mistyped in a query here is
  // indistinguishable from a column a migration has not added yet, and now
  // reports as the second. `detail` still carries SQLite's own words, which
  // name the column, so the mistake is one look away rather than hidden --
  // and an operator who can act is worth more than a developer who is told
  // the truth in a way nobody can use.
  const migration = missingSchema(err);
  if (migration) {
    return c.json({
      error: "migration_needed",
      migration: migration === "unknown" ? null : migration,
      detail: String(err?.message || err).slice(0, 300),
    }, 503);
  }

  return c.json({
    error: "server_error",
    // Kept in the response as well as the log because these are a signed-in
    // person's own API calls, and it turns an afternoon of guessing into one
    // look. It is not shown on screen -- the interface says what to do; this
    // is for whoever is reading the console or the network tab.
    detail: String(err?.message || err).slice(0, 300),
  }, 500);
});

// ---------------------------------------------------------------------------
// Field ownership — mirrors COMPANY_FIELDS / ENGAGEMENT_FIELDS in the UI.
// splitPatch() routes a flat "sub" patch to the right table; composeSub()
// flattens a company+engagement row back into that same flat shape.
// ---------------------------------------------------------------------------
const ENGAGEMENT_FIELDS = new Set([
  "docReview", "categories", "caps",
  "rating", "ratedJobs", "accepted", "declined", "autoSchedule", "notes", "status",
  // Per-account and never on the shared company row: one account's handyman
  // is another account's contractor.
  "engagedAs",
]);

const companyRowToJs = (r) => ({
  id: r.id, company: r.company, contact: r.contact, phone: r.phone, email: r.email,
  license: r.license, ubi: r.ubi,
  licenseCheck: checkView(parseJson(r.license_check), r.license),
  city: r.city, state: r.state, zip: r.zip,
  mailStreet: r.mail_street, mailCity: r.mail_city, mailState: r.mail_state, mailZip: r.mail_zip,
  crews: parseJson(r.crews, []),
  coverage: parseJson(r.coverage, {}),
  available: !!r.available,
  unavailableDays: parseJson(r.unavailable_days, []),
  warranty: parseJson(r.warranty),
  insurance: !!r.insurance, bond: !!r.bond, contract: !!r.contract, w9: !!r.w9,
  docFiles: parseJson(r.doc_files, {}),
  notify: parseJson(r.notify, { email: true, sms: false }),
});

const engagementRowToJs = (r) => ({
  engagementId: r.id, accountId: r.account_id, companyId: r.company_id,
  status: r.status,
  docReview: parseJson(r.doc_review, {}),
  categories: parseJson(r.categories, []),
  caps: parseJson(r.caps, []),
  rating: r.rating, ratedJobs: r.rated_jobs, accepted: r.accepted, declined: r.declined,
  autoSchedule: !!r.auto_schedule, notes: r.notes,
  // 058. What they are to THIS account. Read through `engagedAs` rather than
  // handed over raw, so NULL -- which is every row written before the column
  // existed -- reads as `subcontractor` on the screen exactly as it does in
  // every rule, instead of the browser having to know what an absent value
  // means and getting it wrong somewhere.
  engagedAs: engagedAs(r.engaged_as),
  // Which properties this vendor is scoped to. Empty = every property on the
  // account, which is how a general contractor uses it.
  propertyIds: r.property_ids ? String(r.property_ids).split(",") : [],
});

function composeSub(companyRow, engagementRow) {
  return { ...companyRowToJs(companyRow), ...engagementRowToJs(engagementRow), id: companyRow.id };
}

function parseJson(v, fallback = null) {
  if (v == null) return fallback;
  try { return JSON.parse(v); } catch { return fallback; }
}

const uid = () => crypto.randomUUID();

// SubSub's cut of a release now lives in shared/fee.js -- 0.5%, at most $500 a
// payment, charged to the hiring account on top -- because the screen that
// shows it and the route that charges it must read one number. The rate is
// still STAMPED onto each release at the moment it is made rather than read at
// report time, so changing it next year cannot rewrite what was charged this
// year.

// Today, UTC, as an ISO day. Waivers cover work through a date and dates
// compare as strings; no Date arithmetic, no timezone, no midnight bug.
const dayKeyUtc = () => new Date().toISOString().slice(0, 10);

// ---------------------------------------------------------------------------
// Auth — real when SUPABASE_URL/SUPABASE_ANON_KEY are configured (see
// wrangler.toml and app/README.md), a dev stub otherwise. The dev stub
// trusts a plain X-User-Id header with zero verification — fine for local
// development, never for anything reachable from the internet. Neither
// mode has been exercised against a live network from this environment
// (see README) — the Supabase branch in particular needs a real check
// once deployed.
// ---------------------------------------------------------------------------
// Verifies a `Bearer <token>` header against Supabase itself (no
// crypto/JWKS handling needed in the Worker — costs one extra fetch per
// request; swap for local JWKS verification later if that latency ever
// matters) and resolves it to an internal users row, linking by email on
// first login if one exists but auth_id hasn't been set yet. Returns null
// on any failure — every caller turns that into its own 401/403.
async function verifySupabaseToken(env, authHeader) {
  if (!authHeader?.startsWith("Bearer ")) return null;
  const supaRes = await fetch(`${env.SUPABASE_URL}/auth/v1/user`, {
    headers: { Authorization: authHeader, apikey: env.SUPABASE_ANON_KEY },
  });
  if (!supaRes.ok) return null;
  return supaRes.json(); // { id, email, ... } — Supabase's own user object
}

async function resolveSupabaseUser(env, authHeader) {
  const supaUser = await verifySupabaseToken(env, authHeader);
  if (!supaUser) return null;

  let user = await env.DB.prepare(`SELECT * FROM users WHERE auth_id = ?`).bind(supaUser.id).first();
  if (!user && supaUser.email) {
    // First real login for someone who already has an internal users row
    // (seeded, or added via the invite flow before they'd signed up) —
    // link it by email instead of requiring a separate provisioning step.
    user = await env.DB.prepare(`SELECT * FROM users WHERE lower(email) = lower(?)`).bind(supaUser.email).first();
    if (user) await env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ?`).bind(supaUser.id, user.id).run();
  }
  return user;
}

app.use("/api/*", async (c, next) => {
  // A brand logo has to render on the login screen, before anyone is
  // authenticated — so this one route is intentionally public. Never do
  // this for compliance documents: a route that serves a document by an
  // account or company id is a document served to anybody who can guess an
  // id, and those stay behind auth.
  //
  // /api/pack/* is NOT that, and the difference is the whole of why it is
  // allowed here. Nothing about it is addressable by an id: it is reached by
  // a 32-byte random token the SUBCONTRACTOR minted to send their own
  // paperwork to one person who asked for it, it expires, they can withdraw
  // it, and the document id in the URL is checked to be a current row of the
  // company that token names and of a kind the link may carry. The W-9 never
  // is, because it carries a TIN. Adding a compliance document to this
  // exemption any other way is the thing the paragraph above forbids.
  // /api/account-by-subdomain/* is the same idea: the login screen for
  // e.g. outerhome.subsub.work needs to know which account that subdomain
  // belongs to (for its branding) before anyone has signed in.
  // /api/auth/me and /api/auth/dev-login are also exempted: both exist
  // specifically to discover which accounts a person can choose from
  // *before* any X-Account-Id is known, so they can't require one — they
  // do their own (lighter) verification inline instead. /api/cron/* is a
  // Cron Trigger target with no user session at all — it does its own
  // CRON_SECRET bearer check inline instead (was dead code behind this
  // middleware until this exemption: every call 401'd before reaching it).
  // /api/apply/* is the public subcontractor-application form — genuinely
  // unauthenticated, since the applicant has no session at all yet (that's
  // exactly what a successful application eventually leads to).
  if (c.req.path === "/api/auth/dev-login" || c.req.path === "/api/auth/me" || c.req.path === "/api/signup"
    || c.req.path.startsWith("/api/platform/")
    || c.req.path.startsWith("/api/apply/")
    // Booking a demo, from the marketing site. Nobody has an account yet --
    // getting one is what the meeting is for.
    || c.req.path.startsWith("/api/demo/")
    || c.req.path.startsWith("/api/invite/")
    // 074. A claim link from a work order: the sub holding it has no account
    // -- getting a free one is the point -- and the 32-byte token is the whole
    // of the auth, exactly as for the invite above. The verify step proves the
    // phone with Supabase before it writes anything. The trailing slash
    // matters: /api/work-orders/:id/claim-link is a signed-in read and stays
    // behind this middleware.
    || c.req.path.startsWith("/api/claim/")
    // The tenant equivalent, and public for the same reason: somebody
    // holding the link has no account yet -- getting one is the point. The
    // trailing slash matters: /api/tenants, the manager's roster, stays
    // behind auth, and so would any other path beginning the same way.
    || c.req.path.startsWith("/api/tenant-invite/")
    // The same for somebody added to the account itself: they hold a link
    // and no session, and the link is how they get one.
    || c.req.path.startsWith("/api/user-invite/")
    // Somebody a subcontractor sent their paperwork to. They have no account
    // -- not having to get one is the point -- and the token is the auth.
    || c.req.path.startsWith("/api/pack/")
    // A lien waiver asked of somebody by link -- most often the supply house
    // at the bottom of a chain, which has no account and no reason to want
    // one. Same shape as the pack: 32 random bytes naming one waiver, emailed
    // to the party being asked, nothing addressable by an id. The trailing
    // slash matters -- /api/waivers/* is the paying side's and stays behind
    // auth.
    || c.req.path.startsWith("/api/waiver/")
    // The inbox is the same exemption for the same reason: the token is the
    // whole of the auth, nothing is addressable by an id, and a page that
    // needs an account is a page somebody with no account will not read.
    || /^\/api\/inbox\/[^/]+$/.test(c.req.path)
    // Asking for a way back in. By definition nobody calling this has a
    // session, and it answers identically whatever it finds, so there is
    // nothing here to authenticate and nothing to learn from the reply.
    // The CRM API. It authenticates with its own bearer token against
    // api_tokens rather than a user session -- there is no person here, and a
    // CRM cannot hold one. It does the whole check inline (token, plan, kind,
    // rate limit) rather than being merely exempt: skipping this middleware
    // is not the same as being unauthenticated, and the comment above is the
    // rule this must not break.
    || c.req.path.startsWith("/api/v1/")
    // A referral link opened on the marketing site. Counts the arrival and
    // names whose code it is; nothing about the visitor is kept.
    || c.req.path === "/api/referrals/touch"
    // The marketing site's free tools: a licence lookup against the state's
    // own public data and the handyman-limit calculator. Nobody using them
    // has an account; both are rate-limited per IP inline.
    || c.req.path.startsWith("/api/public/")
    || c.req.path === "/api/password-help"
    || c.req.path === "/api/stripe/webhook"
    // Connect events, same reasoning: Stripe holds no session and the
    // signature over the raw body is the whole of the authentication.
    || c.req.path === "/api/stripe/connect-webhook"
    || c.req.path === "/api/impersonation/end"
    // A liveness answer and nothing else: no database, no account, nothing
    // about anybody. The console's health light reads it through the public
    // hostname, and an uptime monitor can too.
    || c.req.path === "/api/ping"
    || c.req.path.startsWith("/api/logo/") || c.req.path.startsWith("/api/cron/") || c.req.path.startsWith("/api/account-by-subdomain/")) return next();

  // Staff sitting in a customer's seat. Checked before anything else and
  // taken from the row rather than the request: the caller says which token,
  // never which account or which identity, so a stale or tampered header
  // cannot widen what it reaches. An expired or handed-back session stops
  // working the moment it is looked up, which is the reason this is a table
  // and not a signed blob nobody can take back.
  const impToken = c.req.header("X-Impersonation-Token");
  if (impToken) {
    const sess = await c.env.DB.prepare(
      `SELECT account_id, act_as_user_id, staff_user_id FROM impersonation_sessions
        WHERE token = ? AND ended_at IS NULL AND expires_at > datetime('now')`
    ).bind(impToken).first();
    if (!sess) return c.json({ error: "impersonation_expired" }, 401);

    const seat = await c.env.DB.prepare(
      `SELECT * FROM memberships WHERE user_id = ? AND account_id = ?`
    ).bind(sess.act_as_user_id, sess.account_id).first();
    // The seat can be removed while somebody is in it.
    if (!seat) return c.json({ error: "forbidden" }, 403);

    // STANDING IN FOR AN ADMIN THE ACCOUNT HAS NOT GOT. The rule and the
    // reasoning are in shared/seats.js; what it needs here is whether an
    // admin exists at all, which the seat row cannot answer. One narrow
    // indexed read, on the one session type that can need it.
    const admin = await c.env.DB.prepare(
      `SELECT role FROM memberships WHERE account_id = ? AND role = 'admin' LIMIT 1`
    ).bind(sess.account_id).first();
    const runs = staffStandsIn(seat.role, admin ? [admin] : []);

    c.set("auth", {
      userId: sess.act_as_user_id, accountId: sess.account_id,
      role: runs ? "admin" : seat.role, companyId: seat.company_id,
      membershipId: seat.id,
      // Staff sitting in an owner's seat see the owner's buildings and no
      // others. Support is not a reason to widen somebody's access.
      //
      // The scope goes with the role when the session is standing in,
      // because a scope narrows a PERSON and there is no person here: an
      // admin still scoped to four of a hundred buildings is the hybrid
      // `runsTheAccount` refuses anyway, so leaving it would re-create the
      // half-shut account this is fixing one layer down.
      propertyIds: runs ? null : await propertyScope(c.env.DB, seat),
      jobIds: runs ? null : await jobScope(c.env.DB, seat),
      // The seat's own role, when the session is standing in over it. Kept
      // because an auth context whose role is not the membership's role is
      // the one thing that would be unrecoverable afterwards.
      stoodInFor: runs ? seat.role : null,
      // Who is really here. Read by `staffMayWriteShared`, which lets staff
      // correct a company row an ordinary account may not, and by
      // `mintDetailFor`, which hands Stripe's words about OUR configuration to
      // the only party who can act on them. Set in the first place because a
      // session whose real actor is unrecoverable is the one thing this table
      // exists to prevent -- and the comment said "nothing reads it yet" for
      // two features after that stopped being true, which is the
      // screen-that-lies rule with nothing on screen to contradict it.
      impersonatedBy: sess.staff_user_id,
    });
    return next();
  }

  const accountId = c.req.header("X-Account-Id");
  let userId;

  if (c.env.SUPABASE_URL && c.env.SUPABASE_ANON_KEY) {
    if (!accountId) return c.json({ error: "unauthenticated" }, 401);
    const user = await resolveSupabaseUser(c.env, c.req.header("Authorization"));
    if (!user) return c.json({ error: "unauthenticated" }, 401);
    userId = user.id;
  } else {
    userId = c.req.header("X-User-Id");
    if (!userId || !accountId) return c.json({ error: "unauthenticated" }, 401);
  }

  const membership = await c.env.DB.prepare(
    `SELECT * FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(userId, accountId).first();
  if (!membership) return c.json({ error: "forbidden" }, 403);

  c.set("auth", {
    userId, accountId, role: membership.role, companyId: membership.company_id,
    membershipId: membership.id,
    propertyIds: await propertyScope(c.env.DB, membership),
    jobIds: await jobScope(c.env.DB, membership),
  });
  await next();
});

// Which properties a seat may see, and therefore which jobs, which
// contractors and which of anything else hangs off a building.
//
// `null` means no restriction -- an admin or a project manager sees the whole
// account, which is what every membership was before building owners existed.
// An array means exactly those, and an EMPTY array means nothing: an owner
// nobody has granted a building to must not fall through to seeing them all.
// That asymmetry is the whole point, so it is decided here once rather than
// at each call site, where "no rows" reads like "no filter".
// The roles whose view of the account is limited to named buildings. A
// building owner sees theirs and can ask for work; a scoped property manager
// runs the work at theirs. Both are restricted the same way -- what differs is
// what they may do inside the restriction, which requireRole decides.
// Roles that are ALWAYS limited to named buildings, and for which an empty
// list means access to nothing. A property manager is deliberately not one of
// them: theirs is optional, and empty means the whole account -- see
// propertyScope, where that asymmetry lives.

async function propertyScope(db, membership) {
  const role = membership.role;
  // A property manager's list is optional. Most firms have one or two people
  // who see the whole book; a big one assigns each manager to named buildings
  // and wants them to see only those. Same role either way -- the buildings
  // are the difference, not the job.
  if (!isPropertyScopedRole(role)) return null;

  const { results } = await db.prepare(
    `SELECT property_id FROM membership_properties WHERE membership_id = ?`
  ).bind(membership.id).all();
  const ids = (results || []).map((r) => r.property_id);

  // Here is the asymmetry, and it is deliberate. For a manager, no rows means
  // nobody narrowed them, so they see everything -- which is what every
  // membership was before any of this existed, and what an upgrade must leave
  // untouched. For an owner or a tenant, no rows means nobody has given them
  // a building, and they must see nothing rather than fall through to all.
  if (!ids.length && role === "pm") return null;
  return ids;
}

// The same thing one axis over: a PROJECT manager narrowed to named jobs.
//
// A general contractor has no buildings, so `propertyScope` above gives their
// pm seat nothing to be scoped by -- see shared/jobscope.js. Same asymmetry,
// for the same reason: no rows means nobody narrowed them, so an existing seat
// is untouched by this shipping.
//
// Owners and tenants are deliberately NOT job-scoped. Their jobs already
// follow their buildings, and a second, emptier list would narrow them to
// nothing -- which is why `jobScopeFrom` answers null for every role but pm.
async function jobScope(db, membership) {
  if (!JOB_SCOPED_ROLES.includes(membership.role)) return null;
  try {
    const { results } = await db.prepare(
      `SELECT job_id FROM membership_jobs WHERE membership_id = ?`
    ).bind(membership.id).all();
    return jobScopeFrom(membership.role, (results || []).map((r) => r.job_id));
  } catch (err) {
    // A database without 053 has no such table, and a seat nobody has
    // narrowed is exactly what "unrestricted" means -- so this fails in the
    // direction that leaves the product working as it did.
    if (missingSchema(err)) return null;
    throw err;
  }
}

// Guards a single property id against the seat's scope.
const maySeeProperty = (auth, propertyId) =>
  !auth.propertyIds || (propertyId != null && auth.propertyIds.includes(propertyId));

// Guards a single job id. `auth.jobIds` null means unrestricted.
const maySeeJob = (auth, jobId) => maySeeJobIds(auth.jobIds, jobId);

// THE ONE DOOR ONTO A JOB, and the reason it exists rather than a check
// pasted into each route: there are twenty-odd routes that load a job by id
// and eleven of them wrote `FROM jobs WHERE id = ? AND account_id = ?` by
// hand. A scope added to twenty places is a scope missing from the
// twenty-first, which is how the work-order response route ended up answering
// "no, let them through" for a role that did not exist when it was written.
//
// It answers NOT FOUND rather than forbidden, which is the rule every other
// id-keyed route here follows: a job on this account that this seat is not
// assigned to, and a job id that does not exist, give the same reply, so the
// list cannot be walked to find out what else the account is running.
async function jobInScope(env, auth, jobId, cols = "*") {
  const job = await env.DB.prepare(
    `SELECT ${cols} FROM jobs WHERE id = ? AND account_id = ?`
  ).bind(jobId, auth.accountId).first();
  if (!job) return null;
  if (!maySeeJob(auth, jobId)) return null;
  return job;
}

// A `WHERE` fragment plus its bindings, for the scoped list endpoints. Written
// as `IN ()` with no members when the scope is empty, which SQLite reads as
// false -- the safe direction.
// The job equivalent, for the list endpoints.
function jobScopeClause(auth, column) {
  if (!auth.jobIds) return { sql: "", vals: [] };
  if (!auth.jobIds.length) return { sql: ` AND 0 `, vals: [] };
  return {
    sql: ` AND ${column} IN (${auth.jobIds.map(() => "?").join(",")}) `,
    vals: auth.jobIds,
  };
}

function scopeClause(auth, column) {
  if (!auth.propertyIds) return { sql: "", vals: [] };
  if (!auth.propertyIds.length) return { sql: ` AND 0 `, vals: [] };
  return {
    sql: ` AND ${column} IN (${auth.propertyIds.map(() => "?").join(",")}) `,
    vals: auth.propertyIds,
  };
}

// What a building owner may reach. An allowlist, not a deny-list, and that is
// deliberate: the routes here were all written when an account had three roles
// and some of them reason about the caller by elimination. The work-order
// response route, for instance, asks "is this a contractor working on someone
// else's order" -- a question that silently answers "no, let them through" for
// a role that did not exist when it was written. A deny-list would have to be
// amended every time a route is added, by somebody who remembers this exists.
// This way a new route refuses owners until somebody decides otherwise, which
// is the direction a mistake should fail in.
//
// Everything listed is either scoped to the owner's own buildings inside the
// handler, or carries nothing account-specific at all.
const OWNER_ALLOWED = [
  [/^\/api\/account$/, ["GET"]],
  [/^\/api\/account-by-subdomain\/[^/]+$/, ["GET"]],
  // One's own notification choices. The route only ever writes its caller's
  // row, so there is nothing here a narrow seat could reach that is not theirs.
  [/^\/api\/me$/, ["PATCH"]],
  [/^\/api\/logo\/[^/]+$/, ["GET"]],
  [/^\/api\/auth\/me$/, ["GET"]],
  [/^\/api\/account-users$/, ["GET"]],     // scoped: themselves only
  // Letting themselves out. The route refuses any id but their own, which is
  // what makes this safe to allow from a guest seat: an owner who has fired
  // their property manager must not need that manager to release them.
  [/^\/api\/account-users\/[^/]+$/, ["DELETE"]],
  // Asking for their own building back, and answering an offer of it. Every
  // one of these re-checks the seat's own property scope server-side.
  [/^\/api\/properties\/[^/]+\/transfer$/, ["POST"]],
  [/^\/api\/property-transfers$/, ["GET"]],
  [/^\/api\/property-transfers\/[^/]+\/(decide|cancel)$/, ["POST"]],
  [/^\/api\/properties\/[^/]+\/history$/, ["GET"]],
  [/^\/api\/properties$/, ["GET"]],        // scoped: their buildings
  // THE MOVE-IN AND MOVE-OUT RECORD OF THEIR OWN UNITS, read only. A deposit
  // argument is run from these two documents and the owner of the building is
  // the one person besides the agent who has to be able to produce them.
  //
  // GET only, and that is the whole of what makes it safe to list here: every
  // write route behind it is INSPECTION_WRITE_ROLES, so an owner is refused
  // twice -- once by the method not being on this line, and once by the role.
  // `inspectionFor` then applies the seat's property scope and refuses a
  // DRAFT, because a half-walked document says nothing while looking like it
  // says everything.
  //
  // AND THIS LIST IS WHY THE ROLE CAPABILITY WAS NOT ENOUGH. An owner's seat
  // gained `INSPECTION_READ_ROLES` on the route and the Inspections tab on
  // the screen, and every one of those reads still answered 403 -- because
  // what a guest seat may reach is recorded HERE as well, in a second
  // vocabulary. Correct pieces with no way in, for the tenth time, and this
  // is the shape: a role list and a path allowlist are two records of one
  // fact, and a new route refuses a guest until BOTH of them say otherwise.
  [/^\/api\/inspections$/, ["GET"]],                  // scoped: their buildings
  [/^\/api\/inspections\/[^/]+$/, ["GET"]],           // scoped, and finished only
  [/^\/api\/inspections\/[^/]+\/photos\/[^/]+$/, ["GET"]],
  // 072. The weather and the notices on their buildings, both read only.
  [/^\/api\/weather$/, ["GET"]],
  [/^\/api\/notices$/, ["GET"]],
  [/^\/api\/jobs$/, ["GET", "POST"]],      // scoped; POST creates a request
  [/^\/api\/subs$/, ["GET"]],              // scoped: who works their buildings
  [/^\/api\/service-calls$/, ["GET"]],     // scoped: on their own jobs
  [/^\/api\/visits$/, ["GET"]],
  [/^\/api\/jobs\/[^/]+\/withdraw$/, ["POST"]],
  [/^\/api\/jobs\/[^/]+\/report$/, ["PATCH"]],
  // Photos on their own report: attach after uploading, view, take one off.
  // A photo is reached by job and photo id, never by R2 key.
  [/^\/api\/jobs\/[^/]+\/photos$/, ["POST"]],
  [/^\/api\/jobs\/[^/]+\/photos\/[^/]+$/, ["GET", "DELETE"]],
  // The upload itself. Narrowed to this one kind: the generic route would
  // otherwise let a tenant write any prefix under the account.
  [/^\/api\/uploads\/report-photo\/.+$/, ["PUT"]],
  // Their own profile picture: the upload (checked kind, like a report
  // photo), setting it on their own row, and reading it back. The read is
  // narrowed to their OWN picture in the handler -- a guest seat has no
  // business fetching everybody else's face on the account.
  [/^\/api\/uploads\/avatar\/.+$/, ["PUT"]],
  [/^\/api\/me\/avatar$/, ["PATCH"]],
  [/^\/api\/account-users\/[^/]+\/avatar$/, ["GET"]],
];

// A tenant's is narrower again. They report problems and watch what happens
// to them; there is no portfolio to look at, no contractor list, and no
// building-wide view -- other people's repairs are not their business any
// more than theirs are other people's.
const TENANT_ALLOWED = [
  [/^\/api\/account$/, ["GET"]],
  [/^\/api\/account-by-subdomain\/[^/]+$/, ["GET"]],
  // One's own notification choices. The route only ever writes its caller's
  // row, so there is nothing here a narrow seat could reach that is not theirs.
  [/^\/api\/me$/, ["PATCH"]],
  [/^\/api\/logo\/[^/]+$/, ["GET"]],
  [/^\/api\/auth\/me$/, ["GET"]],
  [/^\/api\/account-users$/, ["GET"]],     // scoped: themselves only
  // Letting themselves out. The route refuses any id but their own, which is
  // what makes this safe to allow from a guest seat: an owner who has fired
  // their property manager must not need that manager to release them.
  [/^\/api\/account-users\/[^/]+$/, ["DELETE"]],
  [/^\/api\/properties$/, ["GET"]],        // scoped: their building
  [/^\/api\/jobs$/, ["GET", "POST"]],      // scoped: their own reports
  // Their own report: taken back, or corrected within ten minutes.
  [/^\/api\/jobs\/[^/]+\/withdraw$/, ["POST"]],
  [/^\/api\/jobs\/[^/]+\/report$/, ["PATCH"]],
  // Photos on their own report: attach after uploading, view, take one off.
  // A photo is reached by job and photo id, never by R2 key.
  [/^\/api\/jobs\/[^/]+\/photos$/, ["POST"]],
  [/^\/api\/jobs\/[^/]+\/photos\/[^/]+$/, ["GET", "DELETE"]],
  // The upload itself. Narrowed to this one kind: the generic route would
  // otherwise let a tenant write any prefix under the account.
  [/^\/api\/uploads\/report-photo\/.+$/, ["PUT"]],
  // The proposed time for a repair of theirs, and their answer to it.
  [/^\/api\/visits$/, ["GET"]],
  [/^\/api\/visits\/[^/]+\/respond$/, ["POST"]],
  // Proposing a time for their own report. The route checks it is the job
  // they have to be in for; this line only lets the request reach it.
  [/^\/api\/jobs\/[^/]+\/visits$/, ["POST"]],
  // And, once the window has been and gone, whether anybody actually came.
  [/^\/api\/visits\/[^/]+\/outcome$/, ["POST"]],
  // 072. Their dashboard: the weather where their building is, the notices
  // posted to it, and how they would like to be reached. The weather route
  // names a town and nothing else; the notices route is scoped to their
  // building; the contact route only ever reads and writes the caller's own
  // row on this account.
  [/^\/api\/weather$/, ["GET"]],
  [/^\/api\/notices$/, ["GET"]],
  [/^\/api\/me\/contact$/, ["GET", "PUT"]],
  // Who runs their building: the account's own managers, by name and how to
  // reach them. Read-only, and it answers nothing about anybody else here.
  [/^\/api\/my-manager$/, ["GET"]],
  // 073. How the crew gets in to their own repair: the meeting point, the
  // window and the first name and number of whoever is coming. The routes
  // check they are the tenant who has to be let in; the PUT is the sentence
  // saying which door, which is theirs to say on a job they open.
  [/^\/api\/jobs\/[^/]+\/access$/, ["GET"]],
  [/^\/api\/jobs\/[^/]+\/access-how$/, ["PUT"]],
  // Their own profile picture: the upload (checked kind, like a report
  // photo), setting it on their own row, and reading it back. The read is
  // narrowed to their OWN picture in the handler -- a guest seat has no
  // business fetching everybody else's face on the account.
  [/^\/api\/uploads\/avatar\/.+$/, ["PUT"]],
  [/^\/api\/me\/avatar$/, ["PATCH"]],
  [/^\/api\/account-users\/[^/]+\/avatar$/, ["GET"]],
];

app.use("/api/*", async (c, next) => {
  const auth = c.get("auth");
  const list = auth?.role === "owner" ? OWNER_ALLOWED
    : auth?.role === "tenant" ? TENANT_ALLOWED
    : null;
  if (!list) return next();
  const path = new URL(c.req.url).pathname;
  const ok = list.some(([re, methods]) => re.test(path) && methods.includes(c.req.method));
  if (!ok) return c.json({ error: "forbidden" }, 403);
  await next();
});

// Everything a scoped seat does to a named job, work order or service call,
// checked in one place.
//
// The list endpoints filter, so a scoped seat is never SHOWN another
// building's job. That is not the same as being unable to act on one: the id
// is in the URL, and guessing or remembering one is all it would take. Doing
// this per handler would mean getting it right in a dozen places and in every
// route added later, so it happens here, before any of them run.
app.use("/api/*", async (c, next) => {
  const auth = c.get("auth");
  // Two scopes ride through here, and a seat may carry either, both or
  // neither. `propertyIds` narrows an owner, a tenant or a property manager to
  // named buildings; `jobIds` narrows a PROJECT manager to named jobs, which
  // is what a general contractor has instead of buildings. Returning early on
  // the first one alone is what would leave the second enforced only by the
  // list endpoints -- which is not enforcement, because the id is in the URL.
  if (!auth?.propertyIds && !auth?.jobIds) return next();   // an unrestricted seat
  const path = new URL(c.req.url).pathname;

  // A building named directly: editing or removing one that is not theirs.
  const prop = path.match(/^\/api\/properties\/([^/]+)$/);
  if (prop) {
    if (!maySeeProperty(auth, prop[1])) return c.json({ error: "forbidden" }, 403);
    return next();
  }
  // A job-scoped seat is not a building-scoped one: a general contractor has
  // no buildings, so the property branches below have nothing to say about
  // them and must not start answering.
  if (!auth.propertyIds && path.startsWith("/api/properties")) return next();
  // Adding one is not narrowing work at a building, it is changing the
  // portfolio, and somebody given five buildings to run is not the person who
  // decides there is a sixth. They would not be able to see it afterwards
  // either, which is its own kind of wrong.
  if (path === "/api/properties" && c.req.method === "POST") {
    return c.json({ error: "forbidden" }, 403);
  }

  // The three ways a request names work: directly, through the work order
  // issued for it, or through a service call raised against it.
  const job = path.match(/^\/api\/jobs\/([^/]+)(?:\/|$)/);
  const wo = path.match(/^\/api\/work-orders\/([^/]+)(?:\/|$)/);
  const sc = path.match(/^\/api\/service-calls\/([^/]+)(?:\/|$)/);
  // /api/jobs/all-bookings is a collection, not a job.
  const jobId = job && job[1] !== "all-bookings" ? job[1] : null;
  if (!jobId && !wo && !sc) return next();

  const row = jobId
    ? await c.env.DB.prepare(`SELECT id AS job_id, property_id FROM jobs WHERE id = ? AND account_id = ?`)
        .bind(jobId, auth.accountId).first()
    : wo
    ? await c.env.DB.prepare(
        `SELECT j.id AS job_id, j.property_id FROM work_orders w JOIN jobs j ON j.id = w.job_id
          WHERE w.id = ? AND j.account_id = ?`).bind(wo[1], auth.accountId).first()
    : await c.env.DB.prepare(
        `SELECT j.id AS job_id, j.property_id FROM service_calls s JOIN jobs j ON j.id = s.job_id
          WHERE s.id = ? AND j.account_id = ?`).bind(sc[1], auth.accountId).first();

  // A missing row is reported as missing rather than forbidden: it is one or
  // the other and the caller learns nothing either way, but "not found" is
  // what it actually is.
  if (!row) return c.json({ error: "not_found" }, 404);
  if (!maySeeProperty(auth, row.property_id)) return c.json({ error: "forbidden" }, 403);
  // And the job scope, on the same row. A work order and a service call are
  // reached through the job they belong to, so a narrowed project manager
  // cannot act on one by naming it directly either.
  //
  // NOT FOUND, never forbidden, and the difference is an oracle: `forbidden`
  // on a real job beside `not_found` on a made-up one tells a narrowed seat
  // which ids exist, so the account's whole job list can be walked one guess
  // at a time. Same rule every id-keyed route here follows. The property
  // branch directly above answers 403 and has since it was written -- it has
  // the same shape and the same leak, and changing it is a separate decision
  // about owner and tenant seats with its own tests.
  if (!maySeeJob(auth, row.job_id)) return c.json({ error: "not_found" }, 404);
  await next();
});

function requireRole(...roles) {
  return async (c, next) => {
    const auth = c.get("auth");
    if (!roles.includes(auth.role)) return c.json({ error: "forbidden" }, 403);
    await next();
  };
}

// The per-account stream the console reads. Separate from `events`: that is a
// machine audit log keyed by subject id, this is the rendered sentence a human
// reads in support. Store the text at write time — the rows it refers to
// change, so rebuilding the sentence later from foreign keys gives the wrong
// answer. Never let a logging failure fail the request that caused it.
const companyName = async (db, id) =>
  (await db.prepare(`SELECT company FROM companies WHERE id = ?`).bind(id).first())?.company || "a subcontractor";

// ---------------------------------------------------------------------------
// Documents, and what they say
// ---------------------------------------------------------------------------
// `companies.insurance` and friends answer "is there a file". `company_docs`
// answers "what does it say, and until when" -- see migration 037. Both are
// kept: every screen already written against the booleans goes on working,
// and nothing had to be migrated for this to start being true.
//
// The certificate is the COMPANY's, shared by every account that engages
// them -- one COI, uploaded once. The verdict on it is the engagement's,
// because GC A may require $2M aggregate where GC B accepts $1M. So the facts
// captured here go on company_docs and the approval stays on
// engagements.doc_review. Putting the expiry on the engagement would mean the
// same certificate expiring on different days for different accounts.
//
// The current row per kind is the one nothing has superseded.
async function currentDocRows(db, companyId) {
  const { results } = await db.prepare(
    `SELECT * FROM company_docs
      WHERE company_id = ? AND superseded_at IS NULL
      ORDER BY kind, uploaded_at DESC`
  ).bind(companyId).all();
  const byKind = {};
  for (const r of results || []) if (!byKind[r.kind]) byKind[r.kind] = r;
  return byKind;
}

// The shape shared/docs.js reads. `fileName` is what makes a document present
// rather than missing, and a NULL expires_on stays null on purpose: in that
// module null means "does not expire", never "unknown".
function docShape(rows) {
  const out = {};
  for (const k of DOC_KINDS) {
    const r = rows[k];
    if (!r) continue;
    out[k] = {
      fileName: r.file_name, fileKey: r.file_key,
      issuer: r.issuer, policyNo: r.policy_no,
      coverageCents: r.coverage_cents, effectiveOn: r.effective_on,
      expiresOn: r.expires_on,
      approvedAt: r.approved_at, uploadedAt: r.uploaded_at,
    };
  }
  return out;
}

// Falls back to the booleans for a company whose files all predate 037.
// Without this every existing roster would read as "missing" the moment this
// shipped -- the files are there, we simply have no row describing them, and
// saying "no insurance" about a company that handed one over is worse than
// saying nothing new.
function docShapeWithLegacy(rows, company) {
  const out = docShape(rows);
  const files = parseJson(company?.doc_files, {});
  for (const k of DOC_KINDS) {
    if (out[k]) continue;
    if (!company?.[k]) continue;
    out[k] = { fileName: files[k] || "on file", legacy: true, expiresOn: null };
  }
  return out;
}

// Supersede whatever is current for this kind. Never deleted: the question in
// a dispute is whether they were insured on the day of that job, which the
// certificate current today cannot answer.
async function supersedeDoc(db, companyId, kind) {
  await db.prepare(
    `UPDATE company_docs SET superseded_at = CURRENT_TIMESTAMP
      WHERE company_id = ? AND kind = ? AND superseded_at IS NULL`
  ).bind(companyId, kind).run();
}

// A day string or null. Anything that is not an ISO day is dropped rather
// than stored badly -- shared/docs.js compares these as strings, so a
// "12/03/2027" in the column would silently sort wrong for ever.
const isoDay = (v) => {
  const t = String(v || "").trim().slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null;
};
const centsOf = (v) => {
  if (v === null || v === undefined || v === "") return null;
  const n = Math.round(Number(String(v).replace(/[^0-9.]/g, "")) * 100);
  return Number.isFinite(n) && n >= 0 ? n : null;
};

async function logActivity(env, accountId, userId, kind, text, meta) {
  if (!accountId || !text) return;
  try {
    await env.DB.prepare(
      `INSERT INTO activity (id, account_id, at, user_id, kind, text, meta)
       VALUES (?, ?, datetime('now'), ?, ?, ?, ?)`
    ).bind(crypto.randomUUID(), accountId, userId ?? null, kind, text,
      meta ? JSON.stringify(meta) : null).run();
  } catch (err) {
    console.error("[activity] write failed:", err?.message || err);
  }
}

async function logEvent(env, accountId, actorId, kind, subjectId, payload) {
  await env.DB.prepare(
    `INSERT INTO events (account_id, actor_id, kind, subject_id, payload) VALUES (?, ?, ?, ?, ?)`
  ).bind(accountId, actorId ?? null, kind, subjectId ?? null, payload ? JSON.stringify(payload) : null).run();
}

// ---------------------------------------------------------------------------
// Dev login — looks up a user by email, returns their id + memberships.
// The frontend stores userId + a chosen accountId and sends them as headers.
// Replace with real session auth (Clerk/Supabase) before shipping.
// ---------------------------------------------------------------------------
// A person's own notification choices. Subcontractors choose on the company
// row; a tenant has no company, so the choice is theirs and lives on the
// person. NULL is the defaults: told by email when a report moves, which is
// what they would expect, and able to turn it off.
const DEFAULT_NOTIFY = { email: true, sms: false, statusChanges: true };
const notifyOf = (user) => ({ ...DEFAULT_NOTIFY, ...(parseJson(user?.notify, {}) || {}) });

async function loginResponse(db, user) {
  const { results: memberships } = await db.prepare(
    `SELECT m.*, a.name as account_name, a.subdomain, a.kind, a.plan, a.billing, a.logo_key,
            a.use_default_mark, a.theme, a.trades, a.subscription_status, a.current_period_end,
            a.comped, a.hostname_status, a.cancel_at_period_end
     FROM memberships m JOIN accounts a ON a.id = m.account_id WHERE m.user_id = ?`
  ).bind(user.id).all();
  return {
    user: { id: user.id, name: user.name, email: user.email, phone: user.phone, notify: notifyOf(user) },
    memberships: memberships.map((m) => ({
      accountId: m.account_id, accountName: m.account_name, subdomain: m.subdomain,
      role: m.role, companyId: m.company_id,
      kind: m.kind, plan: m.plan, billing: m.billing, logoKey: m.logo_key, useDefaultMark: !!m.use_default_mark,
      theme: parseJson(m.theme), trades: parseJson(m.trades),
      subscriptionStatus: m.subscription_status, currentPeriodEnd: m.current_period_end,
      comped: !!m.comped, cancelAtPeriodEnd: !!m.cancel_at_period_end,
      hostnameStatus: m.hostname_status || null,
    })),
  };
}

app.post("/api/auth/dev-login", async (c) => {
  // Local development only. With real auth configured this must be closed:
  // it takes an email in the request body and hands back that user's identity
  // and every account they belong to, with no credential at all. Harmless
  // against a local seed database, an unauthenticated disclosure endpoint
  // against a real one.
  if (c.env.SUPABASE_URL && c.env.SUPABASE_ANON_KEY) {
    return c.json({ error: "not_available" }, 404);
  }
  const { email } = await c.req.json();
  const user = await c.env.DB.prepare(`SELECT * FROM users WHERE lower(email) = lower(?)`).bind(email).first();
  if (!user) return c.json({ error: "not_found" }, 404);
  return c.json(await loginResponse(c.env.DB, user));
});

// Real-auth equivalent: identity comes from a verified Supabase bearer
// token, not a trusted request body. Exempted from the main auth
// middleware above for the same reason dev-login is — discovering which
// accounts to offer has to work before any of them is chosen yet.
app.get("/api/auth/me", async (c) => {
  if (!c.env.SUPABASE_URL || !c.env.SUPABASE_ANON_KEY) return c.json({ error: "auth_not_configured" }, 501);
  const user = await resolveSupabaseUser(c.env, c.req.header("Authorization"));
  if (!user) return c.json({ error: "unauthenticated" }, 401);
  return c.json(await loginResponse(c.env.DB, user));
});

// Public subcontractor application (POST /api/apply/:subdomain): the
// SubSignup form a GC links from their own site, before anyone has an
// account at all — no Supabase token, no session, nothing. Creates a bare
// company profile (documents incomplete, same starting state as an admin's
// minimal "add a sub") + an 'invited' engagement + an internal users row
// (auth_id left null), so "Already invited? Create your password" on the
// login page links a real Supabase signup to this row by email later —
// resolveSupabaseUser() already does that linking, so nothing more is
// needed here. Dedupes the company by license number exactly like the
// admin's own POST /api/subs, so a contractor who's already on SubSub for
// another GC doesn't get a duplicate profile.
// ---------------------------------------------------------------------------
// Account signup — public, unauthenticated. This is how a customer creates
// their own workspace from the marketing site's get-started page.
// ---------------------------------------------------------------------------
// Creates three rows together: the account, its first user, and an admin
// membership joining them. In real-auth mode the Supabase user is created
// first, because a failure there must not leave an orphan account behind.
app.post("/api/signup", async (c) => {
  // Two ceilings, because they guard different things. The loose one bounds
  // probing (a rejected request writes nothing, and somebody mistyping their
  // subdomain three times is normal). The tight one bounds actual creation,
  // which is the expensive, abusable half.
  const attempts = await rateLimit(c.env, "signup-attempt", clientIp(c), { limit: 20, windowMinutes: 60 });
  if (!attempts.ok) return c.json({ error: "rate_limited" }, 429);

  const b = await c.req.json().catch(() => null);
  if (!b) return c.json({ error: "bad_request" }, 400);

  const kind = ACCOUNT_KINDS.includes(b.kind) ? b.kind : "general_contractor";
  const company = String(b.company || "").trim();
  const personName = String(b.name || "").trim();
  const email = String(b.email || "").trim().toLowerCase();
  const phoneRaw = String(b.phone || "").trim();
  const phone = phoneRaw ? normalizePhone(phoneRaw) : null;
  const subdomain = validSubdomain(b.subdomain);
  const plan = b.plan === "scale" ? "scale" : "basic";
  const billing = b.billing === "annual" ? "annual" : "monthly";
  // Absent is fine (an older page, or a caller that does not collect them);
  // present but wrong is not, because it would store ids nothing can render.
  const trades = b.trades === undefined ? [] : validTrades(b.trades);
  // A general contractor is a company that can be HIRED, so they are asked
  // for exactly what a subcontractor is asked for. Anything less and the
  // first thing a bigger contractor sees of them is a profile that cannot
  // be verified -- the same paperwork gap they themselves refuse to hire on.
  const hireable = HIREABLE_KINDS.includes(kind);
  const license = String(b.license || "").trim().slice(0, 60);
  const ubi = String(b.ubi || "").trim().slice(0, 40);
  const city = String(b.city || "").trim().slice(0, 120) || null;
  // Normalised, not trimmed: a state that is not a state becomes empty
  // rather than two characters that look like data and match no registry.
  // Silent rather than a refusal -- somebody is signing up, and "TX" typed
  // as "TZ" is not worth stopping them over. The licence check reports that
  // it could not verify, which is the honest outcome.
  const state = normalizeState(b.state);
  const zip = String(b.zip || "").trim().slice(0, 20) || null;

  if (!company) return c.json({ error: "company_required" }, 400);
  // Neither a licence nor a UBI is required to sign up, for any kind.
  //
  // This used to refuse a hireable signup without both, and the form has said
  // "optional ... never required to sign up" the whole time -- so the screen
  // promised one thing and the server refused. Worse, a UBI is Washington's
  // Unified Business Identifier: there is no such number to give in the other
  // fifty jurisdictions, so the gate was unsatisfiable for most of the country
  // rather than merely annoying.
  //
  // The decision it was contradicting is an old one: several states license no
  // contractors at all, so it was a question a real general contractor could
  // not answer, and it cost signups for nothing. Credentials are asked for
  // inside the account, in the set-up checklist, where they buy something --
  // being hireable, and later being eligible for overflow. A licence GIVEN here
  // is still deduped and still verified; only the refusal is gone.
  if (!personName) return c.json({ error: "name_required" }, 400);
  if (!EMAIL_RE.test(email)) return c.json({ error: "invalid_email" }, 400);
  // Mobile stays optional, but a half-typed one is worse than none: it reads
  // as reachable and never is.
  if (phoneRaw && !phone) return c.json({ error: "invalid_phone" }, 400);
  if (trades === null) return c.json({ error: "invalid_trades" }, 400);
  if (!subdomain) return c.json({ error: "invalid_subdomain" }, 400);

  const realAuth = !!(c.env.SUPABASE_URL && c.env.SUPABASE_ANON_KEY);
  // A password is OPTIONAL here, and the form no longer asks for one.
  //
  // It used to be required, and then the confirmation email's link asked for a
  // new one twice -- so somebody signing up chose a password, never used it,
  // and was asked to choose again before they could get in. Three password
  // boxes for one password.
  //
  // Confirming by email is the step that cannot be skipped (the address has to
  // be proved before the account is usable), and that link lands on a screen
  // that already takes a password properly, with a repeat. So that is where it
  // is set, and signup mints a random one nobody is ever told -- Supabase needs
  // a value, and one that is never transmitted back cannot be used by anybody.
  // The way in is the emailed link, or the reset form; both end at the same
  // screen.
  const chosen = String(b.password || "");
  if (realAuth && chosen && chosen.length < 8) {
    return c.json({ error: "weak_password" }, 400);
  }
  const authPassword = chosen || randomSecret();

  // Check both uniqueness constraints up front, so the caller gets a field
  // name back instead of a bare constraint violation.
  const [subTaken, emailTaken] = await Promise.all([
    c.env.DB.prepare(`SELECT id FROM accounts WHERE subdomain = ?`).bind(subdomain).first(),
    c.env.DB.prepare(`SELECT id FROM users WHERE lower(email) = lower(?)`).bind(email).first(),
  ]);
  if (subTaken) return c.json({ error: "subdomain_taken" }, 409);
  if (emailTaken) {
    // "You already have an account" is not always true, and when it is wrong
    // it is a dead end. Somebody holding a GUEST seat -- a building owner or a
    // tenant invited by somebody else -- has no account of their own; they have
    // access to another company's. Telling them to sign in drops them into that
    // company's scoped view, which is not remotely the thing they were trying
    // to create, and nothing on that screen offers a way out.
    //
    // So say which it is. The distinction is the difference between "use the
    // password reset" and "you will need a different address, or take your
    // building with you first".
    const { results: seats } = await c.env.DB.prepare(
      `SELECT m.role FROM memberships m JOIN users u ON u.id = m.user_id
        WHERE lower(u.email) = lower(?)`
    ).bind(email).all();
    const roles = (seats || []).map((r) => r.role);
    const onlyGuest = roles.length > 0 && roles.every((r) => ALWAYS_SCOPED_ROLES.includes(r));
    return c.json({
      error: onlyGuest ? "email_is_a_guest_seat" : "email_in_use",
      // Which kind of guest, so the wording can name it. Never which account:
      // whose building they are attached to is not something an unauthenticated
      // signup form gets to confirm about an address somebody typed.
      seat: onlyGuest ? (roles.includes("owner") ? "owner" : "tenant") : null,
    }, 409);
  }
  // companies.license is unique across the whole table, so this number may
  // already be on a contractor row somebody typed in. Adopting that row
  // would hand whoever knows a public licence number the documents on it,
  // so it is refused and said plainly instead.
  if (hireable && license) {
    const licTaken = await c.env.DB.prepare(
      `SELECT id FROM companies WHERE license = ?`).bind(license).first();
    if (licTaken) return c.json({ error: "license_taken" }, 409);
  }

  let authId = null, needsConfirmation = false;
  if (realAuth) {
    const signed = await supabaseSignUp(c.env, email, authPassword);
    if (!signed.ok) {
      const status = signed.error === "email_in_use" ? 409
        : signed.error === "auth_unreachable" ? 502 : 400;
      return c.json({ error: signed.error, detail: signed.detail }, status);
    }
    authId = signed.authId;
    needsConfirmation = !signed.session;
  }

  const creations = await rateLimit(c.env, "signup-created", clientIp(c), { limit: 3, windowMinutes: 60 });
  if (!creations.ok) return c.json({ error: "rate_limited" }, 429);

  const accountId = uid(), userId = uid(), membershipId = uid();
  try {
    await c.env.DB.batch([
      c.env.DB.prepare(
        `INSERT INTO accounts (id, name, subdomain, kind, plan, billing, trades, use_default_mark)
         VALUES (?, ?, ?, ?, ?, ?, ?, 1)`
      ).bind(accountId, company, subdomain, kind, plan, billing, JSON.stringify(trades)),
      c.env.DB.prepare(
        `INSERT INTO users (id, auth_id, name, email, phone) VALUES (?, ?, ?, ?, ?)`
      ).bind(userId, authId, personName, email, phone),
      c.env.DB.prepare(
        `INSERT INTO memberships (id, user_id, account_id, role) VALUES (?, ?, ?, 'admin')`
      ).bind(membershipId, userId, accountId),
    ]);
    // The company they are, for the kinds that can be hired. Written here
    // rather than left to ensureAccountCompany so a general contractor is
    // findable from the moment they finish signing up, with the licence and
    // the address they just typed rather than a name and nothing else.
    if (hireable) {
      try {
        await c.env.DB.prepare(
          `INSERT OR IGNORE INTO companies (id, company, contact, email, phone, license, ubi, city, state, zip)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(ownCompanyId(accountId), company, personName, email, phone,
          license || null, ubi || null, city, state, zip).run();
        await c.env.DB.prepare(`UPDATE accounts SET company_id = ? WHERE id = ?`)
          .bind(ownCompanyId(accountId), accountId).run();
      } catch (err) {
        // A database without 031 still signs people up; they get their row
        // the first time they open the panel that needs it.
        if (!missingSchema(err)) throw err;
      }
    }
  } catch (err) {
    // Two signups racing on the same subdomain or email land here.
    console.error("[signup] insert failed:", err?.message || err);
    return c.json({ error: "signup_conflict" }, 409);
  }

  // A Scale signup gets its address started immediately; a Basic one has
  // none to start. Either way this does not hold up the response.
  if (plan === "scale") {
    syncHostnameAfter(c, { id: accountId, subdomain, plan }, { reason: "signup" });
  }

  // WHO BROUGHT THEM IN, from the last touch before now: a code typed on the
  // form, or the one the cookie carried from a link, a claim or a Passport.
  // Recorded once and never fails the signup.
  const referredBy = await recordReferral(c.env, {
    subjectKind: "account", subjectId: accountId,
    cookie: b.referral && typeof b.referral === "object" ? b.referral : null,
    typed: b.refCode || null,
    notCode: (row) => (row.kind === "gc" && row.account_id === accountId)
      || (row.kind === "sub" && row.company_id === ownCompanyId(accountId)),
  });

  await logEvent(c.env, accountId, userId, "account.created", accountId,
    { kind, plan, subdomain, viaAuth: realAuth, referredBy: referredBy?.code || null });
  await logActivity(c.env, accountId, userId, "account_created",
    `${personName} created this account on the ${plan === "scale" ? "Scale" : "Basic"} plan`);

  return c.json({
    ok: true, accountId, userId, subdomain, kind,
    // Whether they chose one. False means the only way in is the emailed
    // link, which the closing screen has to say rather than telling somebody
    // to "sign in with the password you just chose".
    hasPassword: !!chosen,
    // The app is reached at the account's own subdomain once DNS is pointed
    // at it; the caller decides whether to send them there or to app.*.
    // Branding, and with it a company hostname, is a Scale feature. A Basic
    // account still reserves its subdomain, but signs in at the shared
    // address. Sending a Basic customer to their own subdomain is how they
    // end up staring at a certificate warning, because that hostname has no
    // certificate until someone adds it as a custom domain.
    // Always the shared address at this moment, even on Scale: provisioning
    // the branded hostname started a few lines above and its certificate is
    // a minute or two away. Sending somebody to an address that is not live
    // yet is how they meet a certificate warning on their first visit.
    signInUrl: "https://app.subsub.work",
    // Creating an account never signs anyone in. The address has not been
    // proved yet, and an account usable before anyone has opened the mailbox
    // it names is an account that can be opened on somebody else's address.
    // The person confirms by email, then signs in; this flag only tells the
    // signup page which of those two things to say.
    needsConfirmation,
  }, 201);
});

// The body of an application, shared by the two ways one can arrive: the
// public form at a customer's own subdomain, and a one-time link the
// customer generated and sent themselves. Identical work either way -- only
// how the applicant got here differs, which is what `note` records.
async function createApplication(env, account, body, note,
  { boundCompanyId = null, engagedAs: wantAs = null } = {}) {
  const licenseKey = (body.license || "").trim().toUpperCase();

  let company = null;
  // An invite raised from a contractor's own card names the company it is for.
  // That beats every guess below: deduping by licence or email only lands back
  // on the right row if the applicant retypes what the account already holds,
  // and "close enough, usually" is how a roster grows a second copy of
  // somebody.
  if (boundCompanyId) {
    company = await env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(boundCompanyId).first();
  }
  if (!company && licenseKey) {
    company = await env.DB.prepare(`SELECT * FROM companies WHERE UPPER(TRIM(license)) = ?`).bind(licenseKey).first();
  }
  if (!company && body.email) {
    company = await env.DB.prepare(`SELECT * FROM companies WHERE lower(email) = lower(?)`).bind(body.email).first();
  }

  let companyId;
  if (company) {
    companyId = company.id;
  } else {
    companyId = uid();
    await env.DB.prepare(
      `INSERT INTO companies (id, company, contact, phone, email, license, ubi, city, state, zip)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(companyId, body.company, body.contact, normalizePhone(body.phone), body.email,
      body.license || null, body.ubi || null, body.city || null, body.state || null, body.zip || null).run();
  }

  let engagementId = (await env.DB.prepare(
    `SELECT id FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(account.id, companyId).first())?.id;
  if (!engagementId) {
    engagementId = uid();
    await env.DB.prepare(
      `INSERT INTO engagements (id, account_id, company_id, status, categories, notes)
       VALUES (?, ?, ?, 'invited', ?, ?)`
    ).bind(engagementId, account.id, companyId, JSON.stringify(body.categories || []), note).run();
    // 059. WHAT THE ACCOUNT SAID THEY WOULD BE, carried from the invite.
    //
    // Its own statement rather than a column on the insert, so a database
    // without 058 still lets somebody redeem an invite -- which is the whole
    // application, and losing it over a classification would be the worse
    // half by far.
    //
    // ONLY ON A NEW ENGAGEMENT, never over an existing one: a company already
    // on this roster has a relationship somebody set, and an invite raised
    // afterwards must not silently reclassify it. Same rule the profile write
    // below follows for a deduped company.
    //
    // And never trusted from the applicant. `wantAs` comes off the invite row
    // the account created; `body` is typed by whoever opened the link, and a
    // contractor naming themselves a handyman would be excusing their own
    // insurance.
    if (isHandyman(wantAs) && mayEngageHandyman(account.kind)) {
      try {
        await env.DB.prepare(`UPDATE engagements SET engaged_as = ? WHERE id = ?`)
          .bind("handyman", engagementId).run();
      } catch (err) {
        if (!missingSchema(err)) throw err;
        console.warn("[apply] 058_engaged_as not applied - joined as a subcontractor");
      }
    }
  }

  // Only for a genuinely new company — an existing (deduped) one keeps its
  // established profile, same rule POST /api/subs follows.
  if (!company) {
    await applySubPatch(env.DB, companyId, engagementId, {
      crews: [],
      coverage: { mode: "cities", cities: body.city ? [body.city] : [] },
      warranty: body.warranty || null,
      notify: { email: !!body.notifyEmail, sms: !!body.notifySms },
    });
  }

  let user = await env.DB.prepare(`SELECT id FROM users WHERE lower(email) = lower(?)`).bind(body.email).first();
  if (!user) {
    const userId = uid();
    await env.DB.prepare(`INSERT INTO users (id, name, email, phone) VALUES (?, ?, ?, ?)`)
      .bind(userId, body.contact, body.email, normalizePhone(body.phone)).run();
    user = { id: userId };
  }
  const existingMembership = await env.DB.prepare(
    `SELECT id FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(user.id, account.id).first();
  if (!existingMembership) {
    await env.DB.prepare(
      `INSERT INTO memberships (id, user_id, account_id, role, company_id) VALUES (?, ?, ?, 'contractor', ?)`
    ).bind(uid(), user.id, account.id, companyId).run();
  }

  await logEvent(env, account.id, user.id, "engagement.applied", engagementId, { companyId, reused: !!company });

  // Confirm it landed, and say what happens next. Public entry point, so a
  // failure here must never turn a successful application into an error.
  if (body.email) {
    const mail = applicationReceivedEmail({
      companyName: body.company, contact: body.contact, account,
    });
    const result = await sendEmail(env, { to: body.email, subject: mail.subject,
      text: mail.text, html: mail.html });
    await logMail(env, { accountId: account.id, companyId, to: body.email,
      kind: "application_received", subject: mail.subject, result, sentBy: null });
  }
  return { companyId, engagementId, userId: user.id };
}

// A login for somebody who has just applied, set from the same form.
//
// This was the actual gap on the contractor side: applying created the
// company, the engagement and a users row, and left them with no way in --
// there is no password anywhere in that. They had to notice "Already
// invited? Create your password" on the sign-in page and work out that it
// meant them.
//
// Never fails the request. By the time this runs the application is saved
// and any invite is spent, so throwing here would tell somebody their
// application did not go through when it did. It reports what happened to
// the login and nothing else; "forgot password" is the way back if it went
// wrong.
// A way in, whichever way they came. applicantLogin() sets a password from
// the form when they typed one -- but the password box is optional, and
// somebody who skipped it used to end up with a company, an engagement, a
// seat and no login at all, holding an email that said "thanks, we've got
// it" and nothing else.
//
// So when no login was made, the invite goes instead. Nobody joins this
// system without a way back into it.
async function applicantWayIn(c, { account, userId, email, password }) {
  const login = await applicantLogin(c, { account, userId, email, password });
  if (login?.created) return { login };
  const user = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(userId).first();
  // Already has a login from somewhere else -- another account, an earlier
  // application. Sending "choose a password" to somebody who has one is a
  // phishing lesson in reverse, and inviteAccountUser refuses it for us.
  const invite = await inviteAccountUser(c, { accountId: account.id, user,
    role: "contractor", invitedBy: null });
  return { login, invite };
}

async function applicantLogin(c, { account, userId, email, password }) {
  const pw = String(password || "");
  if (!pw) return null;
  const to = String(email || "").trim().toLowerCase();
  if (!to) return { created: false, error: "no_email" };

  const signed = await supabaseSignUp(c.env, to, pw, { redirectTo: `${accountOrigin(account)}/` });
  if (!signed.ok && signed.error !== "email_in_use") {
    console.error("[apply] application saved, login not created:", signed.error, signed.detail || "");
    return { created: false, error: signed.error || "signup_failed" };
  }
  // Supabase's enumeration guard showing through: an address it already
  // knows answers 200 with a fabricated id and no identities, and writing
  // that id would point auth_id at nobody.
  const already = signed.error === "email_in_use" || signed.existed;
  if (signed.ok && !signed.existed && signed.authId && userId) {
    await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ? AND auth_id IS NULL`)
      .bind(signed.authId, userId).run();
  }
  return { created: true, existed: already, needsConfirmation: signed.ok && !signed.session && !already };
}

// Requires the three fields nothing downstream can do without. Returns an
// error code, or null when the body is usable.
function applicationProblem(body) {
  if (!body.company?.trim() || !body.contact?.trim() || !body.email?.trim()) return "missing_fields";
  if (!EMAIL_RE.test(String(body.email).trim())) return "invalid_email";
  if (String(body.phone || "").trim() && !normalizePhone(body.phone)) return "invalid_phone";
  return null;
}

app.post("/api/apply/:subdomain", async (c) => {
  const rl = await rateLimit(c.env, "apply", clientIp(c), { limit: 10, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);
  const subdomain = c.req.param("subdomain").trim().toLowerCase();
  // name and subdomain are needed by the confirmation email, which says who
  // the application went to and where they will eventually sign in.
  const account = await c.env.DB.prepare(
    `SELECT id, name, subdomain FROM accounts WHERE subdomain = ?`).bind(subdomain).first();
  if (!account) return c.json({ error: "unknown_account" }, 404);

  const body = await c.req.json().catch(() => ({}));
  const problem = applicationProblem(body);
  if (problem) return c.json({ error: problem }, 400);

  const password = String(body.password || "");
  if (password && password.length < 8) return c.json({ error: "weak_password" }, 400);

  const { userId } = await createApplication(c.env, account, body,
    "Applied through the public application form.");
  // Same as the invited path. Applying already creates this person a
  // contractor membership on the account, so letting them choose a password
  // while they are here grants nothing the application did not already
  // grant -- and it is what lets the sign-in page stop carrying a link that
  // explains how to do it afterwards.
  return c.json({ ok: true, ...(await applicantWayIn(c, { account, userId, email: body.email, password })) });
});

// ---------------------------------------------------------------------------
// Billing (Stripe)
// ---------------------------------------------------------------------------
// Two doors out to Stripe and one door back in. Nothing here decides what a
// customer owes or whether they have paid -- Stripe decides, and the webhook
// records the answer. The accounts table is a cache of Stripe's last word,
// never an independent opinion about money.

const APP_ORIGIN = "https://app.subsub.work";

// Start an upgrade. Returns a Stripe Checkout URL for the browser to follow.
app.post("/api/billing/checkout", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);

  const b = await c.req.json().catch(() => ({}));
  const cycle = b.cycle === "annual" ? "annual" : "monthly";
  const price = priceFor(c.env, cycle);
  if (!price) return c.json({ error: "billing_not_configured" }, 501);

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account) return c.json({ error: "not_found" }, 404);
  const user = await c.env.DB.prepare(`SELECT email FROM users WHERE id = ?`).bind(userId).first();

  // Embedded renders Stripe's form inside our own page; hosted sends the
  // browser to stripe.com. The caller asks for embedded only when it has a
  // publishable key to mount it with, so a build without one still works
  // rather than showing an empty box.
  const wantsEmbedded = b.mode === "embedded";

  // Everything that does not depend on where the form is drawn.
  const base = {
    mode: "subscription",
    line_items: [{ price, quantity: 1 }],
    client_reference_id: accountId,
    allow_promotion_codes: true,
    // Reuse the customer if this account has ever paid, so a second
    // subscription does not arrive under a second customer with the same
    // email and split their billing history in two.
    ...(account.stripe_customer_id
      ? { customer: account.stripe_customer_id }
      : { customer_email: user?.email || undefined }),
    // Stamped in two places because the webhook may see either object
    // first, depending on which event arrives.
    metadata: { account_id: accountId },
    subscription_data: { metadata: { account_id: accountId } },
  };

  // Stripe renamed this value: `embedded` is refused now in favour of
  // `embedded_page`. Older API versions still want the old spelling, so both
  // are tried -- and if neither is accepted, the hosted page is. Where the
  // form is drawn is a preference; being able to pay is not, and a rename at
  // Stripe must never be the reason a customer cannot hand over money.
  const attempts = wantsEmbedded
    ? [
        { mode: "embedded", ui_mode: "embedded_page" },
        { mode: "embedded", ui_mode: "embedded" },
        { mode: "hosted" },
      ]
    : [{ mode: "hosted" }];

  let lastErr = null;
  try {
    for (const attempt of attempts) {
      const embedded = attempt.mode === "embedded";
      try {
        const session = await stripeCall(c.env, "/checkout/sessions", {
          params: {
            ...base,
            ...(embedded
              // Stripe substitutes the real id into this placeholder; it must
              // survive form-encoding as a literal, which it does, because the
              // value is decoded again at the other end.
              ? { ui_mode: attempt.ui_mode,
                  return_url: `${APP_ORIGIN}/?billing=done&session_id={CHECKOUT_SESSION_ID}` }
              : { success_url: `${APP_ORIGIN}/?billing=done`,
                  cancel_url: `${APP_ORIGIN}/?billing=cancelled` }),
          },
          // A double-tapped button within the same minute is one checkout, not
          // two. The spelling is part of the key: a retry after a refusal is a
          // different request, and reusing the key would replay the refusal.
          idempotencyKey: `checkout:${accountId}:${cycle}:${embedded ? attempt.ui_mode : "h"}:${Math.floor(Date.now() / 60000)}`,
        });
        if (attempt !== attempts[0]) {
          console.warn("[billing] checkout fell back to",
            attempt.ui_mode || "hosted", "--", lastErr?.message || "");
        }
        return c.json(embedded ? { clientSecret: session.client_secret } : { url: session.url });
      } catch (err) {
        lastErr = err;
        // Only a quarrel about ui_mode is worth another attempt. A declined
        // card or a missing price fails the same way every time, and retrying
        // it only delays the message that would have helped.
        if (!/ui_mode/i.test(String(err?.message || ""))) throw err;
      }
    }
    throw lastErr;
  } catch (err) {
    console.error("[billing] checkout failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// Moving an account down to the free Basic plan, without leaving SubSub.
//
// "Cancel" is Stripe's word for it and this does call Stripe's cancel, but
// the product meaning is a downgrade: the account stays open, the data stays
// put, and only the paid features stop. Saying "cancel" to the customer
// reads as losing the account, which is not what happens and not what
// anybody wants to be told.
//
// Stripe's billing portal is a hosted page -- there is no embedded version
// of it -- so sending somebody there to cancel undoes the whole point of an
// embedded checkout: the last thing they see of us before they leave is
// somebody else's website. Cancelling is one API call, so it happens here.
//
// At period end, never immediately. They paid for the period; taking it away
// early is both wrong and the kind of thing that turns a quiet cancellation
// into a chargeback. The account keeps Scale until the date it was paid to.
app.post("/api/billing/cancel", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);

  const account = await c.env.DB.prepare(
    `SELECT stripe_subscription_id FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account?.stripe_subscription_id) return c.json({ error: "no_subscription" }, 409);

  try {
    const sub = await stripeCall(c.env, `/subscriptions/${account.stripe_subscription_id}`, {
      params: { cancel_at_period_end: true },
    });
    // Write through rather than waiting for the webhook: the customer is
    // looking at the screen now, and "did that work?" should not depend on
    // how quickly Stripe calls back.
    const full = await accountRow(c.env, accountId);
    if (full) await applySubscription(c.env, full, sub);
    await logActivity(c.env, accountId, c.get("auth").userId, "plan_changed",
      "Scheduled to move to the free Basic plan at the end of the period");
    return c.json({ ok: true, endsAt: stripeTime(sub.items?.data?.[0]?.current_period_end ?? sub.current_period_end) });
  } catch (err) {
    console.error("[billing] cancel failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// And changing their mind, which is the same call in reverse. Worth having:
// somebody who cancels by accident should not have to buy the plan again.
app.post("/api/billing/resume", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);

  const account = await c.env.DB.prepare(
    `SELECT stripe_subscription_id FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account?.stripe_subscription_id) return c.json({ error: "no_subscription" }, 409);

  try {
    const sub = await stripeCall(c.env, `/subscriptions/${account.stripe_subscription_id}`, {
      params: { cancel_at_period_end: false },
    });
    const full = await accountRow(c.env, accountId);
    if (full) await applySubscription(c.env, full, sub);
    await logActivity(c.env, accountId, c.get("auth").userId, "plan_changed",
      "Staying on Scale — the move to Basic was called off");
    return c.json({ ok: true });
  } catch (err) {
    console.error("[billing] resume failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// Stripe's own billing portal: card changes, invoices, cancellation. Building
// any of that ourselves would mean handling card details, which is the one
// thing worth never touching.
app.post("/api/billing/portal", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);

  const account = await c.env.DB.prepare(
    `SELECT stripe_customer_id FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account?.stripe_customer_id) return c.json({ error: "no_subscription" }, 409);

  try {
    const session = await stripeCall(c.env, "/billing_portal/sessions", {
      params: { customer: account.stripe_customer_id, return_url: `${APP_ORIGIN}/` },
    });
    return c.json({ url: session.url });
  } catch (err) {
    console.error("[billing] portal failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// What the app shows on the billing panel. Read from our own cache rather
// than Stripe, so opening a settings page is not an API call to a third party.
app.get("/api/billing", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const a = await c.env.DB.prepare(
    `SELECT plan, billing, subscription_status, current_period_end, stripe_customer_id
     FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!a) return c.json({ error: "not_found" }, 404);

  const { results: invoices } = await c.env.DB.prepare(
    `SELECT id, amount_cents, status, period_start, period_end, paid_at, attempt_count
     FROM invoices WHERE account_id = ? ORDER BY period_start DESC LIMIT 12`
  ).bind(accountId).all();

  // Text messages: what is included this month, what is gone, what the next
  // bill will carry for it so far, and last month's charge -- read from the
  // same function that decides whether a text goes, so the panel and the
  // decision cannot disagree.
  let sms = null;
  try {
    const u = await smsUsage(c.env, accountId);
    const blocks = u.billable ? smsOverageBlocks({ allowance: u.allowance, used: u.used }) : 0;
    let last = null;
    try {
      last = await c.env.DB.prepare(
        `SELECT month, used, blocks, amount_cents, status FROM sms_overage
          WHERE account_id = ? AND month = ?`).bind(accountId, previousMonth().month).first();
    } catch (err) { if (!missingSchema(err)) throw err; }
    sms = {
      used: u.used, allowance: u.allowance, included: u.onScale ? SMS_INCLUDED_SCALE : 0,
      billable: u.billable, overageBlocks: blocks, overageCents: smsOverageCents(blocks),
      blockMessages: SMS_BLOCK_MESSAGES, blockPriceCents: SMS_BLOCK_PRICE_CENTS,
      maxBlocks: SMS_OVERAGE_MAX_BLOCKS, configured: !!smsConfig(c.env), off: u.off,
      lastMonth: last && last.status !== "not_billable" ? { month: last.month, used: last.used,
        blocks: last.blocks, amountCents: last.amount_cents, status: last.status } : null,
    };
  } catch (err) {
    console.error("[billing] sms usage failed:", err?.message || err);
  }

  return c.json({
    plan: a.plan, cycle: a.billing,
    status: a.subscription_status,
    currentPeriodEnd: a.current_period_end,
    hasCustomer: !!a.stripe_customer_id,
    configured: !!c.env.STRIPE_SECRET_KEY,
    sms,
    invoices: invoices.map((i) => ({
      id: i.id, amountCents: i.amount_cents, status: i.status,
      periodStart: i.period_start, periodEnd: i.period_end,
      paidAt: i.paid_at, attemptCount: i.attempt_count,
    })),
  });
});
// Turn the account's text messages off, or back on. Admin only, because it is
// a decision about what the account is charged for: past 2,500 a month texts
// are billed automatically, and this is the way out of that. Emails are
// untouched, and an emergency call-out still goes -- see shared/smsquota.js.
app.put("/api/billing/sms", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  if (typeof b.off !== "boolean") return c.json({ error: "off_required" }, 400);
  try {
    await c.env.DB.prepare(
      `INSERT INTO account_sms_settings (account_id, sms_off, updated_by, updated_at)
       VALUES (?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(account_id) DO UPDATE SET sms_off = excluded.sms_off,
         updated_by = excluded.updated_by, updated_at = CURRENT_TIMESTAMP`
    ).bind(accountId, b.off ? 1 : 0, userId ?? null).run();
  } catch (err) {
    if (missingSchema(err)) return c.json({ error: "migration_needed", migration: "070_sms_overage" }, 503);
    throw err;
  }
  await logActivity(c.env, accountId, userId ?? null, "sms_setting",
    b.off ? "Turned text messages off. Emails still go, and emergency call-outs are still texted."
      : "Turned text messages back on.").catch(() => {});
  return c.json({ ok: true, off: b.off });
});


// Find the account a Stripe object belongs to. The metadata is stamped at
// checkout, but a subscription changed from Stripe's own dashboard may
// arrive without it, so the customer id is the fallback.
async function accountForStripe(env, { accountId, customerId }) {
  if (accountId) {
    const a = await env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
    if (a) return a;
  }
  if (customerId) {
    return env.DB.prepare(`SELECT * FROM accounts WHERE stripe_customer_id = ?`).bind(customerId).first();
  }
  return null;
}

// Write the plan change and the row that explains it. mrr_delta is signed, so
// the platform console can sum a month without re-deriving who moved where.
const accountRow = (env, id) =>
  env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(id).first();

async function applySubscription(env, account, sub) {
  const status = sub.status;
  const entitled = ENTITLED.has(status);
  const item = sub.items?.data?.[0];
  const cycle = item?.price?.recurring?.interval === "year" ? "annual" : "monthly";
  // A comped account keeps Scale whatever Stripe says. Somebody who was given
  // the plan should not lose it because a card they never entered expired,
  // or because a cancelled trial from months ago finally reported in.
  const plan = (entitled || account.comped) ? "scale" : "basic";
  // Stripe moved current_period_end off the subscription and onto its items,
  // so reading only the old place returned nothing and the app fell back to
  // "renews annually" with no date -- which is exactly what it looked like.
  // Both are read, newest first, so this works either side of that change.
  const periodEnd = stripeTime(item?.current_period_end ?? sub.current_period_end);
  // Status stays `active` on a subscription that is cancelling, so this is
  // the only thing that distinguishes "renews on" from "ends on".
  const cancelAtEnd = sub.cancel_at_period_end ? 1 : 0;

  const was = account.plan;
  // The cancel flag lives in a column added by migration 013. A deploy can
  // land before somebody runs the migration, and if that makes this write
  // throw then every webhook fails -- payments succeed at Stripe and never
  // reach the account, which is the worst failure this file has. So the
  // newer shape is tried and the older one is the fallback: a missing column
  // costs one field, not the whole subscription.
  try {
    await env.DB.prepare(
      `UPDATE accounts SET plan = ?, billing = ?, stripe_subscription_id = ?,
              stripe_customer_id = COALESCE(stripe_customer_id, ?),
              subscription_status = ?, current_period_end = ?, cancel_at_period_end = ?
       WHERE id = ?`
    ).bind(plan, cycle, sub.id, sub.customer, status, periodEnd, cancelAtEnd, account.id).run();
  } catch (err) {
    if (!/no such column/i.test(String(err?.message || err))) throw err;
    console.warn("[billing] cancel_at_period_end column missing -- run migration 013");
    await env.DB.prepare(
      `UPDATE accounts SET plan = ?, billing = ?, stripe_subscription_id = ?,
              stripe_customer_id = COALESCE(stripe_customer_id, ?),
              subscription_status = ?, current_period_end = ?
       WHERE id = ?`
    ).bind(plan, cycle, sub.id, sub.customer, status, periodEnd, account.id).run();
  }

  if (was !== plan) {
    const monthly = cycle === "annual" ? 8250 : 9900;   // $990/yr and $99/mo, in cents
    const kind = plan === "scale" ? "upgraded" : (status === "canceled" ? "canceled" : "downgraded");
    await env.DB.prepare(
      `INSERT INTO subscription_events (id, account_id, at, kind, from_plan, to_plan, cycle, mrr_delta_cents, source)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'stripe')`
    ).bind(uid(), account.id, new Date().toISOString(), kind, was, plan, cycle,
      plan === "scale" ? monthly : -monthly).run();

    await logActivity(env, account.id, null, "plan_changed",
      plan === "scale" ? `Upgraded to Scale (${cycle})` : "Moved to Basic");

    // Paying for Scale is the moment the branded address is owed, and
    // stopping is the moment it is not. No ctx here -- the webhook handler
    // awaits this, which is right: Stripe retries a failed webhook, and a
    // hostname left unprovisioned because the response beat it is worse
    // than a webhook that took another second.
    await syncHostname(env, { id: account.id, subdomain: account.subdomain, plan },
      { reason: "stripe" });
  }
}

// Stripe's way in. Unauthenticated by necessity -- Stripe has no session --
// so the signature is the only thing establishing that this is real, and a
// failed check must stop everything.
app.post("/api/stripe/webhook", async (c) => {
  const secret = c.env.STRIPE_WEBHOOK_SECRET;
  if (!secret) return c.json({ error: "billing_not_configured" }, 501);

  // The raw bytes, before any parsing: the signature is over exactly what
  // Stripe sent, and re-serialising JSON would not reproduce it.
  const raw = await c.req.text();
  const event = await verifyStripeWebhook(raw, c.req.header("stripe-signature"), secret);
  if (!event) {
    console.error("[stripe] rejected an unsigned or stale webhook");
    return c.json({ error: "bad_signature" }, 400);
  }

  // Stripe retries until it gets a 2xx and can deliver the same event twice
  // on its own, so every handler below runs at most once per event id.
  try {
    await c.env.DB.prepare(`INSERT INTO stripe_events (id, type) VALUES (?, ?)`)
      .bind(event.id, event.type).run();
  } catch {
    return c.json({ ok: true, duplicate: true });
  }

  try {
    const obj = event.data?.object || {};
    switch (event.type) {
      case "checkout.session.completed": {
        const account = await accountForStripe(c.env, {
          accountId: obj.client_reference_id || obj.metadata?.account_id,
          customerId: obj.customer,
        });
        if (!account) break;
        // Record the customer immediately, so the portal works even if the
        // subscription events arrive late or out of order.
        await c.env.DB.prepare(`UPDATE accounts SET stripe_customer_id = ? WHERE id = ?`)
          .bind(obj.customer, account.id).run();
        if (obj.subscription) {
          const sub = await stripeCall(c.env, `/subscriptions/${obj.subscription}`, { method: "GET" });
          await applySubscription(c.env, account, sub);
        }
        break;
      }

      case "customer.subscription.created":
      case "customer.subscription.updated":
      case "customer.subscription.deleted": {
        const account = await accountForStripe(c.env, {
          accountId: obj.metadata?.account_id, customerId: obj.customer,
        });
        if (!account) break;
        await applySubscription(c.env, account, obj);
        break;
      }

      case "invoice.paid":
      case "invoice.payment_failed": {
        const account = await accountForStripe(c.env, {
          accountId: obj.subscription_details?.metadata?.account_id, customerId: obj.customer,
        });
        if (!account) break;
        // Keyed by Stripe's invoice id, so a retry overwrites rather than
        // duplicating, and a failed invoice later paid updates in place.
        await c.env.DB.prepare(
          `INSERT OR REPLACE INTO invoices
             (id, account_id, amount_cents, status, period_start, period_end, paid_at, attempt_count)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(obj.id, account.id, obj.amount_due ?? obj.amount_paid ?? 0, obj.status,
          stripeTime(obj.period_start) || new Date().toISOString(),
          stripeTime(obj.period_end) || new Date().toISOString(),
          obj.status === "paid" ? stripeTime(obj.status_transitions?.paid_at) : null,
          obj.attempt_count ?? 0).run();
        // A referred account's first PAID invoice is what earns the referral.
        // An invoice the account's own credit covered in full is not paying.
        if (event.type === "invoice.paid" && Number(obj.amount_paid) > 0) {
          await referralOnPaid(c.env, account, obj.id);
        }
        break;
      }

      // ---- 051. Work-order funding and the transfers that spend it -------
      //
      // These are PLATFORM events, not connected-account ones: the charge is
      // taken on our own account (separate charges and transfers), so they
      // arrive here and not at the Connect endpoint.
      //
      // The browser confirms funding too, through /fund/confirm, and both
      // write the same row. That is deliberate rather than redundant: the
      // browser is what redraws the screen somebody is standing on, and this
      // is what is correct when they close the tab mid-payment -- which is
      // the case where nothing else would ever mark the money as arrived.
      case "payment_intent.succeeded": {
        const woId = obj.metadata?.work_order_id;
        if (!woId) break;                       // a subscription charge, not ours
        const charge = typeof obj.latest_charge === "string" ? obj.latest_charge : obj.latest_charge?.id;
        const landed = Math.round(Number(obj.amount_received ?? obj.amount) || 0);
        // Keyed on the intent, so this cannot invent a row for a funding
        // attempt no route ever started.
        await c.env.DB.prepare(
          `UPDATE wo_funding SET status = 'funded', amount_cents = ?, processor_charge_id = ?,
             error = NULL, funded_at = COALESCE(funded_at, CURRENT_TIMESTAMP)
           WHERE processor_intent_id = ? AND status <> 'funded'`
        ).bind(landed, charge || null, obj.id).run();
        break;
      }

      case "payment_intent.payment_failed": {
        if (!obj.metadata?.work_order_id) break;
        await c.env.DB.prepare(
          `UPDATE wo_funding SET status = 'failed', error = ?
             WHERE processor_intent_id = ? AND status = 'pending'`
        ).bind(String(obj.last_payment_error?.message || "declined").slice(0, 500), obj.id).run();
        break;
      }

      // A transfer that comes back weeks later. The release has to stop reading
      // as paid, or the roster says somebody was paid while the money is in our
      // balance -- and the only record of it was the release that still says
      // paid, which is the reconciliation nobody can do. It goes back to `due`,
      // which is what it is.
      //
      // REVERSAL IS THE ONLY WEBHOOK CASE, and that is worth stating because the
      // obvious thing is to also handle a "transfer failed" event. A transfer
      // Stripe refuses fails SYNCHRONOUSLY on the API call, which /pay already
      // catches and marks `failed` with Stripe's own words -- so there is nothing
      // for a webhook to tell us. And a failed PAYOUT is a different object
      // entirely: that is money leaving the subcontractor's Stripe balance for
      // their bank, which is between them and Stripe, and reopening our release
      // over it would say the transfer did not happen when it did.
      //
      // Still open, and bigger than this: a funding charge DISPUTED or refunded
      // after its transfers have gone. The money is out and the charge is
      // reversed, and nothing here handles it.
      case "transfer.reversed": {
        const t = await c.env.DB.prepare(
          `SELECT * FROM wo_transfers WHERE processor = 'stripe' AND processor_transfer_id = ?`
        ).bind(obj.id).first();
        if (!t) break;                          // not one of ours
        await c.env.DB.prepare(
          `UPDATE wo_transfers SET status = 'reversed', reversed_at = CURRENT_TIMESTAMP,
             error = COALESCE(error, ?) WHERE id = ?`
        ).bind(`Stripe ${event.type}`, t.id).run();
        await c.env.DB.prepare(
          `UPDATE wo_releases SET status = 'due', method = NULL, reference = NULL,
             settled_at = NULL, settled_by = NULL
           WHERE id = ? AND status = 'paid' AND reference = ?`
        ).bind(t.release_id, obj.id).run();
        // Append-only, so the reversal is its own line rather than an edit to
        // the one that said it was paid. "Who said this was paid, and what
        // happened to it" has to stay answerable.
        //
        // Written directly rather than through `woEvent`, which reads the seat
        // off `c.get("auth")` -- a webhook has none, and there is no person to
        // name here anyway. Same reasoning as `job_sources.created_by` being
        // NULL: naming somebody would put a sentence in the audit trail saying
        // they did a thing they did not do.
        await c.env.DB.prepare(
          `INSERT INTO wo_events (id, work_order_id, account_id, kind, payload, idem_key)
           VALUES (?, ?, ?, ?, ?, ?)`
        ).bind(uid(), t.work_order_id, t.account_id, "release.reversed",
          JSON.stringify({ releaseId: t.release_id, transferId: t.id, reference: obj.id,
            amountCents: t.amount_cents, type: event.type }),
          `reversed:${obj.id}`).run().catch(() => {});
        break;
      }

      default:
        break;   // Stripe sends a great deal we have no opinion about.
    }
  } catch (err) {
    // Forget the event so Stripe's retry gets a real second attempt rather
    // than being deduplicated against a run that failed halfway.
    console.error("[stripe] handler failed:", event.type, err?.message || err);
    await c.env.DB.prepare(`DELETE FROM stripe_events WHERE id = ?`).bind(event.id).run().catch(() => {});
    return c.json({ error: "handler_failed" }, 500);
  }

  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Managing the subscription without leaving
// ---------------------------------------------------------------------------
// Stripe's billing portal is a hosted page: there is no embedded component
// for it, so "manage payments" meant handing somebody to stripe.com in the
// middle of their own account screen. What the portal actually does is three
// things -- the card, the invoices, and cancelling -- and cancelling was
// already here. So the other two are here now too.
//
// The card itself is still never touched. A SetupIntent is confirmed in the
// browser by Stripe's own Payment Element, which means the number goes from
// the customer to Stripe and never past us; what comes back is an id.

const billingCustomer = async (c) => {
  const { accountId } = c.get("auth");
  const a = await c.env.DB.prepare(
    `SELECT stripe_customer_id, stripe_subscription_id FROM accounts WHERE id = ?`
  ).bind(accountId).first();
  return a?.stripe_customer_id ? a : null;
};

// What is on file, so the panel can say "Visa ending 4242" rather than
// offering to change something it cannot name.
app.get("/api/billing/card", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const a = await billingCustomer(c);
  if (!a) return c.json({ card: null });
  try {
    const cust = await stripeCall(c.env, `/customers/${a.stripe_customer_id}`,
      { method: "GET" });
    const pmId = cust?.invoice_settings?.default_payment_method;
    if (!pmId) return c.json({ card: null });
    const pm = await stripeCall(c.env, `/payment_methods/${pmId}`, { method: "GET" });
    // Four digits and an expiry, which is all anybody needs to recognise
    // their own card. Nothing else about it is ours to hold or to show.
    return c.json({ card: pm?.card
      ? { brand: pm.card.brand, last4: pm.card.last4,
          expMonth: pm.card.exp_month, expYear: pm.card.exp_year }
      : null });
  } catch (err) {
    console.error("[billing] card read failed:", err?.message || err);
    return c.json({ card: null });
  }
});

// Start changing it. The SetupIntent is confirmed in the browser, so this
// hands over a client secret and nothing else.
app.post("/api/billing/card-setup", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const a = await billingCustomer(c);
  if (!a) return c.json({ error: "no_subscription" }, 409);
  try {
    const si = await stripeCall(c.env, "/setup_intents", {
      params: {
        customer: a.stripe_customer_id,
        payment_method_types: ["card"],
        // The card is kept to charge a subscription nobody will be present
        // for, which is what this value means to Stripe.
        usage: "off_session",
      },
    });
    return c.json({ clientSecret: si.client_secret });
  } catch (err) {
    console.error("[billing] card setup failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// And finish. The browser has confirmed the SetupIntent; this reads which
// payment method came out of it and makes it the one that gets charged.
//
// BOTH the customer and the subscription, because they are two different
// settings and only changing the first leaves the next invoice on the old
// card -- a card somebody believes they have replaced, failing silently a
// month later.
app.post("/api/billing/card-confirm", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const a = await billingCustomer(c);
  if (!a) return c.json({ error: "no_subscription" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const siId = String(b.setupIntentId || "").trim();
  if (!/^seti_[A-Za-z0-9_]+$/.test(siId)) return c.json({ error: "bad_setup_intent" }, 400);

  try {
    // Read it back from Stripe rather than trusting a payment method id sent
    // by the browser: this route would otherwise point the account's billing
    // at any card whose id somebody could name.
    const si = await stripeCall(c.env, `/setup_intents/${siId}`, { method: "GET" });
    if (si?.customer !== a.stripe_customer_id) return c.json({ error: "not_found" }, 404);
    if (si?.status !== "succeeded") return c.json({ error: "not_confirmed", status: si?.status }, 409);
    const pm = si.payment_method;
    if (!pm) return c.json({ error: "not_confirmed" }, 409);

    await stripeCall(c.env, `/customers/${a.stripe_customer_id}`, {
      params: { invoice_settings: { default_payment_method: pm } },
    });
    if (a.stripe_subscription_id) {
      await stripeCall(c.env, `/subscriptions/${a.stripe_subscription_id}`, {
        params: { default_payment_method: pm },
      });
    }
    return c.json({ ok: true });
  } catch (err) {
    console.error("[billing] card confirm failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// What they have been charged. A list somebody can read here, rather than a
// reason to go and sign in somewhere else.
app.get("/api/billing/invoices", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const a = await billingCustomer(c);
  if (!a) return c.json({ invoices: [] });
  try {
    const list = await stripeCall(c.env,
      `/invoices?customer=${encodeURIComponent(a.stripe_customer_id)}&limit=24`,
      { method: "GET" });
    return c.json({ invoices: (list?.data || []).map((i) => ({
      id: i.id,
      number: i.number || null,
      created: i.created ? new Date(i.created * 1000).toISOString() : null,
      total: typeof i.total === "number" ? i.total : null,
      currency: i.currency || "usd",
      status: i.status || null,
      // The PDF is a document rather than a product surface, so a link to it
      // is not the thing this whole change is removing.
      pdf: i.invoice_pdf || null,
    })) });
  } catch (err) {
    console.error("[billing] invoices failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// ---------------------------------------------------------------------------
// Getting paid: connecting a Stripe account
// ---------------------------------------------------------------------------
// Onboarding only. A hireable company connects a Stripe connected account,
// Stripe does the identity checking, and `payout_accounts` remembers which
// account is theirs and whether money may move. Funding a work order and
// releasing against a milestone come later; see EASY-PAY.md.
//
// Nothing here is a bank detail. Account and routing numbers are Stripe's to
// hold and never reach this database -- `processor_account_id` is the whole
// of what is stored, and that is deliberate.
//
// Three things about this are easy to get wrong and are the reason most of
// the code below exists:
//
//   RETURNING FROM STRIPE DOES NOT MEAN FINISHED. Stripe sends somebody to
//   `return_url` whether they completed onboarding or abandoned it halfway,
//   so the return can never be read as success. The screen asks the server,
//   the server asks Stripe, and the answer is whatever Stripe says.
//
//   AN ACCOUNT LINK IS SINGLE-USE AND EXPIRES IN MINUTES. Storing one and
//   rendering it as a button hands somebody a dead link with nothing saying
//   why, so a fresh one is minted on every press and none is ever kept.
//
//   PAYABLE IS NOT A LATCH. Stripe asks for more as volume grows, so an
//   account that was payable last month can stop being. Every read re-derives
//   from a fresh account object and nothing is remembered once it was true.

// US only, for the same reason `shared/states.js` holds fifty states and DC:
// everything in this product -- the licence question, the UBI, the W-9 -- is
// written for one country, and an onboarding form offering others would be a
// question the rest of the account cannot answer.
const PAYOUT_COUNTRY = "US";

const payoutMigration = () => ({ error: "migration_needed", migration: "050_payout_accounts" });

async function payoutRow(env, companyId) {
  return await env.DB.prepare(
    `SELECT * FROM payout_accounts WHERE company_id = ? AND processor = 'stripe'`
  ).bind(companyId).first();
}

// One write path for what Stripe just said, so the create, the refresh and
// the webhook cannot record three different readings of the same account.
// `rowFromStripe` in shared/pay.js does the deriving; this only stores it.
async function savePayoutRow(env, { companyId, acctId, acct }) {
  const r = rowFromStripe(acct);
  await env.DB.prepare(
    `INSERT INTO payout_accounts
       (id, company_id, processor, processor_account_id, kyc_status,
        transfers_active, payouts_enabled, requirements, disabled_reason, updated_at)
     VALUES (?, ?, 'stripe', ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(company_id, processor) DO UPDATE SET
       processor_account_id = excluded.processor_account_id,
       kyc_status      = excluded.kyc_status,
       transfers_active = excluded.transfers_active,
       payouts_enabled = excluded.payouts_enabled,
       requirements    = excluded.requirements,
       disabled_reason = excluded.disabled_reason,
       updated_at      = CURRENT_TIMESTAMP`
  ).bind(uid(), companyId, acctId, r.kycStatus, r.transfersActive,
    r.payoutsEnabled, r.requirements, r.disabledReason).run();
}

// The caller's own company, or the reason they have not got one. Same shape
// as /api/my-company, because it is the same question.
async function payoutCompany(c) {
  const companyId = await seatCompany(c);
  if (companyId) return { companyId };
  const why = await noCompanyReason(c);
  return { res: why === "not_hireable"
    ? c.json({ error: "not_hireable" }, 409)
    : c.json({ error: "migration_needed", migration: "031_account_company" }, 503) };
}

// What the screen draws. Reads the row and nothing else -- deliberately no
// Stripe call, because this runs on every page load and a dashboard must not
// wait on a third party. `refresh` below is how a fresh reading is asked for.
app.get("/api/payouts/status", requireRole("admin"), async (c) => {
  const { companyId, res } = await payoutCompany(c);
  if (res) return res;
  try {
    return c.json({ ...payoutSummary(await payoutRow(c.env, companyId)),
      configured: !!c.env.STRIPE_SECRET_KEY });
  } catch (err) {
    if (missingSchema(err)) return c.json(payoutMigration(), 503);
    throw err;
  }
});

// Read a connected account as Stripe has it now, in whichever shape it was
// minted. Accounts made since the move to v2 are read through v2; one minted
// under v1 (test mode, before that move) answers v1's GET. A v2 read that
// Stripe refuses as a client error is the signal to ask the old way -- a 5xx
// is Stripe being down and is not retried, because asking a second endpoint
// will not fix that and would hide it.
async function readConnectedAccount(env, acctId) {
  try {
    return await stripeV2Call(env, `/v2/core/accounts/${acctId}`, {
      method: "GET", version: STRIPE_V2_VERSION,
      query: { include: ["configuration.recipient", "requirements"] },
    });
  } catch (err) {
    if (!(err?.status >= 400 && err?.status < 500)) throw err;
    return stripeCall(env, `/accounts/${acctId}`, { method: "GET" });
  }
}

// The connected account for this company, minted if there is not one yet.
//
// NOBODY CONNECTS ANYTHING. A hireable company needs a payee record to be
// paid, that record is not a decision they get to make differently, and a
// button saying "Connect a Stripe account" asks somebody to opt in to
// plumbing. So it is created the first time the screen is opened, and what
// is left for them is the part only they can answer: who they are and where
// the money goes.
//
// Returns { acctId } or { res } -- a refusal already shaped for the caller.
async function connectedAccount(c, companyId) {
  let row;
  try { row = await payoutRow(c.env, companyId); }
  catch (err) {
    if (missingSchema(err)) return { res: c.json(payoutMigration(), 503) };
    throw err;
  }

  if (row?.kyc_status === "rejected") {
    return { res: c.json({ error: "rejected", disabledReason: row.disabled_reason || null }, 409) };
  }
  if (row?.processor_account_id) return { acctId: row.processor_account_id, row };

  const co = await c.env.DB.prepare(`SELECT email, company FROM companies WHERE id = ?`)
    .bind(companyId).first();

  // One request, built once, so the retry below cannot send a different one.
  //
  // ACCOUNTS V2. Stripe closed v1 account creation to new platforms in live
  // mode; its API policy re-opening it reads "Available in test mode", which
  // is not a door a live product can use. `shared/pay.js` says what each field
  // carries over from the v1 controller, and `normalizeAccount` there reads
  // the answer back into the shape everything else already understands.
  const mint = (keySuffix = "") => stripeV2Call(c.env, "/v2/core/accounts", {
    version: STRIPE_V2_VERSION,
    body: {
      ...PAYOUT_ACCOUNT,
      ...(co?.email ? { contact_email: co.email } : {}),
      ...(co?.company ? { display_name: String(co.company).trim().slice(0, 100) } : {}),
      identity: { country: PAYOUT_COUNTRY.toLowerCase() },
      // Asked for on the reply, or the reply carries none of what
      // `rowFromStripe` reads and the first row written says nothing.
      include: ["configuration.recipient", "requirements"],
      metadata: { company_id: companyId, account_id: c.get("auth").accountId },
    },
    // Two connected accounts for one company is two places money could go
    // with nothing saying which. The unique index is the half that holds when
    // two requests race; this is the half that makes an ordinary double-press
    // -- or two tabs open on the same screen -- cost nothing.
    //
    // It carries the controller's shape, because Stripe replays a saved
    // REFUSAL as faithfully as a saved success and a key that is only the
    // company id would answer for terms we no longer send. `payoutAccountKey`
    // says why at length.
    idempotencyKey: payoutAccountKey(companyId) + keySuffix,
  });

  // EVERY WAY THIS CAN FAIL HERE IS OURS, which is why the whole block
  // answers with one code rather than letting Stripe's sentence reach the
  // screen. `shared/pay.js` says why at length: at mint time Stripe has been
  // told nothing about this company, so there is nothing of theirs to refuse.
  let acct;
  try {
    try {
      acct = await mint();
    } catch (err) {
      // A REFUSAL CREATED NOTHING, SO REPLAYING IT PROTECTS NOTHING.
      //
      // Stripe replays the saved status and body for 24 hours, and the shape
      // in the key only moves when OUR request changes. Half of what can
      // refuse this call is not ours at all -- a Stripe account setting, an
      // API policy, a capability being enabled -- and after fixing one of
      // those the next press is still answered by the refusal from before the
      // fix. That is a guaranteed day-long dead end on the one screen a
      // subcontractor cannot get paid without, and it has happened twice.
      //
      // The retry is safe precisely because the saved answer was a refusal: a
      // 4xx means Stripe created no account under that key, so a fresh key
      // cannot duplicate one. A replayed SUCCESS never reaches here -- it is
      // a 200, which is the double-press this mechanism exists to absorb.
      //
      // Re-read the row first: the press that got the refusal replayed to it
      // may have been racing one that succeeded.
      if (!err?.replayed || !(err?.status >= 400 && err?.status < 500)) throw err;
      const raced = await payoutRow(c.env, companyId);
      if (raced?.processor_account_id) return { acctId: raced.processor_account_id, row: raced };
      console.error("[payouts] Stripe replayed a refusal; asking again under a fresh key:", err?.message || err);
      acct = await mint(`:r${Date.now()}`);
    }
  } catch (err) {
    if (missingSchema(err)) return { res: c.json(payoutMigration(), 503) };
    // Loud, and naming the company, because the person who CAN act on this is
    // not the person looking at the screen -- so the log is the only place it
    // lands for them.
    console.error(`[payouts] PLATFORM CONFIGURATION refused the mint for company ${companyId}:`,
      err?.message || err, err?.replayed ? "(idempotent replay)" : "");
    return { res: c.json({
      error: PLATFORM_NOT_READY,
      // Staff standing in ARE the party who can go and change it. A
      // subcontractor is not, and handing them a dashboard link for an account
      // they have no access to is the screen-that-lies rule pointed at
      // somebody else's settings page.
      ...(mintDetailFor(c.get("auth")) ? { detail: String(err?.message || err) } : {}),
      replayed: !!err?.replayed,
    }, 502) };
  }

  await savePayoutRow(c.env, { companyId, acctId: acct.id, acct });
  return { acctId: acct.id, row: await payoutRow(c.env, companyId), minted: true };
}

// The embedded onboarding, which is the whole point: an Account Session is a
// short-lived key for ONE connected account and ONE set of components, and
// the browser renders Stripe's form inside our own page with it. Nobody is
// sent to stripe.com and nobody is asked to connect anything.
//
// It is a POST because it mints things -- the account on first call, a
// session on every call. The panel calls it on mount rather than on a press,
// so the form is simply there.
app.post("/api/payouts/session", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { companyId, res } = await payoutCompany(c);
  if (res) return res;

  try {
    const { acctId, minted, res: acctRes } = await connectedAccount(c, companyId);
    if (acctRes) return acctRes;

    // Opening the screen re-reads where Stripe has got to. Without it the
    // status here moves only on a webhook or a return from the hosted link --
    // and a v2 account's events arrive in a different shape from v1's, so this
    // is the reading that cannot be missed. Best effort: a failed read leaves
    // the row as it was rather than costing somebody the form.
    if (!minted) {
      try {
        const acct = await readConnectedAccount(c.env, acctId);
        await savePayoutRow(c.env, { companyId, acctId, acct });
      } catch (err) {
        console.error("[payouts] status re-read failed:", err?.message || err);
      }
    }

    const session = await stripeCall(c.env, "/account_sessions", {
      params: {
        account: acctId,
        components: {
          // Collecting who they are and where the money goes.
          account_onboarding: { enabled: "true" },
          // And afterwards: what Stripe still wants, and what it has paid
          // out. With `stripe_dashboard: none` there is no other screen
          // anywhere that can show them either, so withholding these would
          // leave somebody with money owed and nowhere to look.
          account_management: { enabled: "true" },
          payouts: { enabled: "true" },
          notification_banner: { enabled: "true" },
        },
      },
    });
    return c.json({ clientSecret: session.client_secret,
      ...payoutSummary(await payoutRow(c.env, companyId)) });
  } catch (err) {
    if (missingSchema(err)) return c.json(payoutMigration(), 503);
    console.error("[payouts] session failed:", err?.message || err, err?.replayed ? "(idempotent replay)" : "");
    return c.json({ error: "stripe_failed", detail: String(err?.message || err), replayed: !!err?.replayed }, 502);
  }
});

// The way through when the embedded component cannot load at all.
//
// Kept for the reason embedded checkout keeps a hosted attempt behind it:
// where the form is drawn is a preference, and being able to get paid is
// not. A blocked script or a Stripe change must not be the reason somebody
// cannot give us their bank details -- so this stays, and the panel reaches
// for it only when the embedded one has failed.
app.post("/api/payouts/connect", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { companyId, res } = await payoutCompany(c);
  if (res) return res;

  try {
    // Same helper the embedded route uses, so the two doors cannot mint
    // accounts with different `controller` settings -- which would be two
    // populations of subcontractor with different Stripe experiences,
    // decided by which door happened to work that day.
    const { acctId, res: acctRes } = await connectedAccount(c, companyId);
    if (acctRes) return acctRes;

    // Fresh every time, and never stored. Single-use, and it expires in
    // minutes.
    // v2's link for a v2 account, v1's for one minted before the move. Same
    // two addresses either way: Stripe sends them back to `refresh_url` when
    // the link has gone stale mid-flow (which lands on the same screen, which
    // mints another), and to `return_url` when they come back -- finished or
    // not, which is why the screen asks the server rather than believing it.
    const refresh_url = `${APP_ORIGIN}/?payouts=refresh`;
    const return_url = `${APP_ORIGIN}/?payouts=return`;
    let link;
    try {
      link = await stripeV2Call(c.env, "/v2/core/account_links", {
        version: STRIPE_V2_VERSION,
        body: { account: acctId,
          use_case: { type: "account_onboarding", account_onboarding: { refresh_url, return_url } } },
      });
    } catch (err) {
      if (!(err?.status >= 400 && err?.status < 500)) throw err;
      link = await stripeCall(c.env, "/account_links", {
        params: { account: acctId, type: "account_onboarding", refresh_url, return_url },
      });
    }
    return c.json({ url: link.url });
  } catch (err) {
    if (missingSchema(err)) return c.json(payoutMigration(), 503);
    console.error("[payouts] connect failed:", err?.message || err, err?.replayed ? "(idempotent replay)" : "");
    return c.json({ error: "stripe_failed", detail: String(err?.message || err), replayed: !!err?.replayed }, 502);
  }
});

// Ask Stripe where they actually got to.
//
// This is what the return from onboarding calls, because the return itself
// proves nothing: Stripe sends somebody back whether they finished or gave up
// on the second screen. The webhook says the same thing a moment later, and
// both write through `savePayoutRow` -- but waiting for a webhook to redraw
// the screen somebody is standing on reads as the button not having worked.
app.post("/api/payouts/refresh", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { companyId, res } = await payoutCompany(c);
  if (res) return res;

  let row;
  try { row = await payoutRow(c.env, companyId); }
  catch (err) {
    if (missingSchema(err)) return c.json(payoutMigration(), 503);
    throw err;
  }
  if (!row) return c.json({ error: "not_started" }, 409);

  try {
    const acct = await readConnectedAccount(c.env, row.processor_account_id);
    await savePayoutRow(c.env, { companyId, acctId: row.processor_account_id, acct });
    return c.json({ ...payoutSummary(await payoutRow(c.env, companyId)), configured: true });
  } catch (err) {
    if (missingSchema(err)) return c.json(payoutMigration(), 503);
    console.error("[payouts] refresh failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// Connect events, which arrive at their own endpoint with their own signing
// secret and carry an `account` naming whose they are.
//
// A separate route rather than a branch inside the billing webhook: mixing
// them would make every handler in that switch ask "is this ours or a
// connected account's", which is two records in one place. `stripe_events`
// is shared, because event ids are unique across both endpoints and a
// second dedupe table would be a second thing to get right.
app.post("/api/stripe/connect-webhook", async (c) => {
  const secret = c.env.STRIPE_CONNECT_WEBHOOK_SECRET;
  if (!secret) return c.json({ error: "connect_not_configured" }, 501);

  const raw = await c.req.text();
  const event = await verifyStripeWebhook(raw, c.req.header("stripe-signature"), secret);
  if (!event) {
    console.error("[stripe/connect] rejected an unsigned or stale webhook");
    return c.json({ error: "bad_signature" }, 400);
  }

  try {
    await c.env.DB.prepare(`INSERT INTO stripe_events (id, type) VALUES (?, ?)`)
      .bind(event.id, event.type).run();
  } catch {
    return c.json({ ok: true, duplicate: true });
  }

  try {
    // A v2 account's changes arrive as a THIN event: a type and the id of what
    // changed, with no object attached. So it is read back from Stripe rather
    // than trusted from the payload, which is the safer reading anyway.
    if (event.object === "v2.core.event" && /^v2\.core\.account/.test(event.type || "")
        && event.related_object?.id) {
      const acctId = event.related_object.id;
      const row = await c.env.DB.prepare(
        `SELECT company_id FROM payout_accounts WHERE processor = 'stripe' AND processor_account_id = ?`
      ).bind(acctId).first();
      if (row) {
        const acct = await readConnectedAccount(c.env, acctId);
        await savePayoutRow(c.env, { companyId: row.company_id, acctId, acct });
      }
    } else if (event.type === "account.updated") {
      const acct = event.data?.object || {};
      const row = acct.id ? await c.env.DB.prepare(
        `SELECT company_id FROM payout_accounts WHERE processor = 'stripe' AND processor_account_id = ?`
      ).bind(acct.id).first() : null;
      // An account we hold no row for is not an error. Stripe delivers for
      // every connected account on the platform, and answering 4xx would
      // make it retry something that will never succeed.
      if (row) await savePayoutRow(c.env, { companyId: row.company_id, acctId: acct.id, acct });
    }
  } catch (err) {
    if (!missingSchema(err)) {
      console.error("[stripe/connect] handler failed:", err?.message || err);
      // Stripe retries on a 5xx, which is what we want for a transient
      // failure -- and the event id has already been recorded, so the retry
      // would be deduped away. Remove it so the retry can do its job.
      try { await c.env.DB.prepare(`DELETE FROM stripe_events WHERE id = ?`).bind(event.id).run(); } catch { /* best effort */ }
      return c.json({ error: "handler_failed" }, 500);
    }
  }
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Subcontractor invite links
// ---------------------------------------------------------------------------
// The token is the credential: whoever holds the link can file an
// application against this account. So it is 32 bytes of CSPRNG output, it
// expires, and it is spent on first use. Nothing about the account is
// guessable from it and nothing else is needed to use it, which is the whole
// point -- a contractor with a phone and a text message should not have to
// be told a subdomain, an email address or a password first.
const INVITE_TTL_DAYS = 30;

function newInviteToken() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

// Where a holder of this token should be sent. A query string rather than a
// path, because the app is a single page served by Pages: an unknown path
// depends on SPA-fallback configuration to resolve, and a query string
// always does.
// A Scale account with its own address invites people to *their* page, not
// to SubSub's. Tenant invites already did this; subcontractor ones were
// hardcoded to app.subsub.work, so a contractor invited by a branded
// account landed somewhere that did not look like the company that asked.
const inviteUrl = (account, token) => `${accountOrigin(account)}/?invite=${token}`;

const inviteRowToJs = (r, account) => ({
  id: r.id, label: r.label, createdAt: r.created_at, expiresAt: r.expires_at,
  usedAt: r.used_at, revokedAt: r.revoked_at, companyId: r.company_id,
  email: r.email || null, phone: r.phone || null,
  contact: r.contact || null, companyName: r.company_name || null,
  // Null for a link the account made to hand over itself. "Created" and
  // "sent" are different facts and a list that conflates them is a list
  // that says a message went out when none did.
  sentAt: r.sent_at || null,
  // 059. What they will be once they arrive. Normalised through the same
  // helper the engagement reads, so a NULL column, a word nothing recognises
  // and a database without 059 all answer "subcontractor" -- one rule, and
  // the browser never derives a second.
  engagedAs: engagedAs(r.engaged_as),
  url: inviteUrl(account, r.token),
  status: r.revoked_at ? "revoked"
    : r.used_at ? "accepted"
    : new Date(r.expires_at) < new Date() ? "expired"
    : "open",
});

// Is there a real profile behind this invite, or a name somebody typed and
// nothing else? The email and the form it lands on have to agree about this.
// An email promising "a few minutes: your company details, the trades you
// cover" over a link that opens a single password box has told somebody the
// wrong thing about their own record -- and one saying "takes seconds" over a
// blank three-step form is worse. So both read this.
const inviteKnownEnough = (co) => !!(co && co.company && co.contact && co.email);

// Sending one, by both routes. Lifted out of the create route so that
// sending an invite again is the same act as sending it the first time --
// same token, same wording, same reporting -- rather than a second
// implementation that drifts from it.
//
// The token is deliberately reused. Reissuing would quietly break the link
// already sitting in somebody's inbox, which is the opposite of what
// "resend" means to whoever pressed it.
async function deliverSubInvite(env, { row, account, accountId, userId }) {
  const link = inviteUrl(account, row.token);
  const email = row.email || null, phone = row.phone || null;
  // Raised from a contractor already on the roster, so the account typed all
  // of this in and the link is only about a password.
  const bound = row.company_id
    ? await env.DB.prepare(`SELECT company, contact, email FROM companies WHERE id = ?`)
        .bind(row.company_id).first().catch(() => null)
    : null;
  const known = inviteKnownEnough(bound);
  let mailResult = null, smsResult = null;
  if (email) {
    const mail = subInviteEmail({ contact: row.contact, companyName: row.company_name, account, link, known });
    mailResult = await sendEmail(env, { to: email, subject: mail.subject, text: mail.text, html: mail.html });
    await logMail(env, { accountId, companyId: null, to: email, kind: "sub_invite",
      subject: mail.subject, result: mailResult, sentBy: userId });
  }
  if (phone) {
    smsResult = await sendAccountSms(env, { accountId, to: phone, kind: "sub_invite",
      body: subInviteSms({ companyName: row.company_name, account, link, known }) });
  }
  const emailed = !!mailResult?.ok, texted = !!smsResult?.ok;
  return {
    emailed, texted,
    emailError: email && !emailed ? (mailResult?.error || "send_failed") : null,
    // sms_not_configured is its own answer: nothing is wrong with the
    // number, SubSub simply cannot text yet, and telling somebody to check
    // the number would send them looking in the wrong place.
    textError: phone && !texted ? (smsResult?.error || "send_failed") : null,
    went: [emailed && email, texted && phone].filter(Boolean).join(" and "),
  };
}

// A PM can hand out links; only an admin should be able to revoke one, same
// split as everywhere else in the account.
app.post("/api/invites", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const label = String(b.label || "").trim().slice(0, 120) || null;
  const email = String(b.email || "").trim().toLowerCase();
  const contact = String(b.contact || "").trim().slice(0, 120) || null;
  const companyName = String(b.companyName || "").trim().slice(0, 160) || null;
  const phone = normalizePhone(b.phone) || null;
  if (email && !EMAIL_RE.test(email)) return c.json({ error: "bad_email" }, 400);
  // A half-typed number reads as reachable and never is, and this one is
  // about to be texted rather than filed.
  if (b.phone && String(b.phone).trim() && !toE164(phone)) return c.json({ error: "bad_phone" }, 400);

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();

  // 059. WHAT THEY WILL BE TO YOU, decided here because this is where the
  // relationship starts. The add-a-contractor form has asked since 058; this
  // door never did, and it is the one used for the person who has no SubSub
  // account -- which is exactly the person most likely to be a handyman. So
  // inviting the man who changes tap washers produced a subcontractor, whose
  // own portal then demanded a certificate of insurance and a surety bond he
  // will never hold.
  //
  // Refused rather than defaulted on an account kind that may not engage one,
  // the same answer the roster route gives: silence is only safe when nothing
  // was asked, and here something was and it was not understood.
  if (b.engagedAs !== undefined && !isEngagedAs(b.engagedAs)) {
    return c.json({ error: "bad_engaged_as" }, 400);
  }
  const wantAs = engagedAs(b.engagedAs);
  if (isHandyman(wantAs) && !mayEngageHandyman(account?.kind)) {
    return c.json({ error: "not_a_handyman_account" }, 403);
  }

  const id = uid(), token = newInviteToken();
  const expires = new Date(Date.now() + INVITE_TTL_DAYS * 86400_000).toISOString();

  // 027 only records who it went to. An account that has not had it yet must
  // still be able to make a link -- refusing to invite anybody over a
  // reporting column would be worse than the gap it fills.
  let recorded = true;
  try {
    await c.env.DB.prepare(
      `INSERT INTO sub_invites (id, account_id, token, label, email, phone, contact, company_name, created_by, expires_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, token, label, email || null, phone, contact, companyName, userId, expires).run();
  } catch (err) {
    if (!missingSchema(err)) throw err;
    console.warn("[invites] 027_sub_invite_email not applied - link made, recipient not recorded");
    recorded = false;
    await c.env.DB.prepare(
      `INSERT INTO sub_invites (id, account_id, token, label, created_by, expires_at)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, token, label, userId, expires).run();
  }

  // A SEPARATE STATEMENT, and deliberately not a column on the insert above.
  // That insert already carries a fallback for a database without 027, and
  // folding this into it would mean a database with 027 and not 059 dropping
  // the RECIPIENT as well -- losing the common case to record the rare one.
  // Here the degradation lands where it belongs: the invite still goes, the
  // address is still recorded, and only the relationship is lost, which is
  // said rather than assumed.
  //
  // Skipped entirely for a subcontractor, because NULL already means that --
  // so the ordinary invite touches no column 059 added and cannot fail on it.
  let asRecorded = true;
  if (isHandyman(wantAs)) {
    try {
      await c.env.DB.prepare(`UPDATE sub_invites SET engaged_as = ? WHERE id = ?`)
        .bind(wantAs, id).run();
    } catch (err) {
      if (!missingSchema(err)) throw err;
      console.warn("[invites] 059_invite_engaged_as not applied - invite made as a subcontractor");
      asRecorded = false;
    }
  }

  // Sent by SubSub, by both routes, because this trade answers a text and
  // opens email on Sunday night. Either link finishes the same invite --
  // whichever they pick up first -- so there is nothing to reconcile.
  //
  // The step that decides whether anybody is invited used to happen in the
  // account's own mail client, where nothing here could see it succeed or
  // fail. Now each route reports separately, and neither is assumed.
  const sent = await deliverSubInvite(c.env, {
    row: { token, email: email || null, phone, contact, company_name: companyName },
    account, accountId, userId,
  });
  const { emailed, texted } = sent;
  // Only when something actually left, by either route. An invite marked
  // sent that never went is worse than one marked nothing, because somebody
  // waits on it.
  if ((emailed || texted) && recorded) {
    await c.env.DB.prepare(`UPDATE sub_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(id).run();
  }

  await logActivity(c.env, accountId, userId, "invite_created",
    sent.went ? `Invite sent to ${sent.went}` : label ? `Invite link created for ${label}` : "Invite link created");

  const row = await c.env.DB.prepare(`SELECT * FROM sub_invites WHERE id = ?`).bind(id).first();
  return c.json({
    ...inviteRowToJs(row, account),
    // Each route on its own. "Invite sent" over a bounced email, or over a
    // text that could not go because texting is not switched on, is the
    // same class of lie as a booking page that confirms nothing.
    emailed, texted, emailError: sent.emailError, textError: sent.textError,
    // Said rather than assumed, the same rule `recorded` follows above: a
    // handyman invite that went out as a subcontractor is a thing the screen
    // has to be able to report, because the only other symptom arrives weeks
    // later as a maintenance worker being asked for a surety bond.
    engagedAsRecorded: asRecorded,
  }, 201);
});

// Guarded the same way as creating one. An invite token is a credential --
// whoever holds it can file an application against this account -- and a
// tenant or a contractor seat has no reason to read the account's outstanding
// ones. It was open to any authenticated seat in the account, which was only
// ever safe because nothing but the admin screen asked for it.
app.get("/api/invites", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  const { results } = await c.env.DB.prepare(
    `SELECT * FROM sub_invites WHERE account_id = ? ORDER BY created_at DESC LIMIT 100`
  ).bind(accountId).all();
  return c.json(results.map((r) => inviteRowToJs(r, account)));
});

// Send an outstanding invite again, to the address it was addressed to.
//
// The commonest reason an invite goes nowhere is that it was sent on a
// Tuesday and read on nothing. Without this the only recourse was to create
// a second invite, which leaves two live tokens for one contractor and a
// list that reads as two people.
app.post("/api/invites/:id/resend", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const row = await c.env.DB.prepare(
    `SELECT * FROM sub_invites WHERE id = ? AND account_id = ?`
  ).bind(c.req.param("id"), accountId).first();
  // Scoped by account, so an id from another account is a miss rather than a
  // way to make somebody else's invite go out again.
  if (!row) return c.json({ error: "not_found" }, 404);
  if (row.used_at) return c.json({ error: "already_accepted" }, 409);
  if (row.revoked_at) return c.json({ error: "revoked" }, 409);
  if (new Date(row.expires_at) < new Date()) return c.json({ error: "expired" }, 409);
  // A link made to hand over in person has nowhere to be sent. Saying so is
  // better than reporting a send that had no recipient.
  if (!row.email && !row.phone) return c.json({ error: "no_contact" }, 400);

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  const sent = await deliverSubInvite(c.env, { row, account, accountId, userId });
  // Same rule as the first send: sent_at moves only if something left.
  if (sent.emailed || sent.texted) {
    await c.env.DB.prepare(`UPDATE sub_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(row.id).run();
  }
  await logActivity(c.env, accountId, userId, "invite_resent",
    sent.went ? `Invite sent again to ${sent.went}` : "Invite could not be sent again");

  const after = await c.env.DB.prepare(`SELECT * FROM sub_invites WHERE id = ?`).bind(row.id).first();
  return c.json({
    ...inviteRowToJs(after, account),
    emailed: sent.emailed, texted: sent.texted,
    emailError: sent.emailError, textError: sent.textError,
  });
});

// CHANGE AN OUTSTANDING INVITE, which until now could only be revoked and
// retyped.
//
// The commonest thing wrong with an invite is a letter in the address: it
// went nowhere, nothing reports that it went nowhere, and the panel offered
// Copy link, Send again and Revoke -- so the only route from a typo to a
// working invite was to throw the record away and start again, losing when it
// was first raised and leaving the dashboard reading as though nobody had
// ever been asked.
//
// EDITABLE UNTIL THEY ACCEPT, and the boundary is exactly that. Once `used_at`
// is set the record is their `companies` row and `PATCH /api/subs/:companyId`
// is the door, with its own rule about whether this account may write a row
// somebody else answers for. Two doors onto one record is how the two come to
// disagree.
//
// An invite raised FROM a contractor's card is refused for the same reason
// one step earlier: it carries `company_id`, so their name and address are
// already on a row this account can edit from the roster, and writing the
// invite's copy would leave two answers to one question. The panel says so
// rather than offering a save the route will refuse.
//
// Same seats as creating and resending one. Revoking is admin-only because it
// destroys a live credential; correcting an address does not.
app.patch("/api/invites/:id", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const row = await c.env.DB.prepare(
    `SELECT * FROM sub_invites WHERE id = ? AND account_id = ?`
  ).bind(c.req.param("id"), accountId).first();
  // Scoped by account, so an id from another account is a miss rather than a
  // way to edit somebody else's invite -- the same answer resend gives.
  if (!row) return c.json({ error: "not_found" }, 404);
  if (row.used_at) return c.json({ error: "already_accepted" }, 409);
  if (row.revoked_at) return c.json({ error: "revoked" }, 409);
  if (row.company_id) return c.json({ error: "on_their_card", companyId: row.company_id }, 409);

  // Only what was sent. A screen that edits four fields must not blank a
  // fifth it has never heard of -- the shape that deleted a W-9 through
  // SubForm.
  const has = (k) => Object.prototype.hasOwnProperty.call(b, k);
  const next = {
    company_name: has("companyName")
      ? (String(b.companyName || "").trim().slice(0, 160) || null) : row.company_name,
    contact: has("contact")
      ? (String(b.contact || "").trim().slice(0, 120) || null) : row.contact,
    label: has("label") ? (String(b.label || "").trim().slice(0, 120) || null) : row.label,
    email: has("email") ? (String(b.email || "").trim().toLowerCase() || null) : row.email,
    phone: has("phone") ? (normalizePhone(b.phone) || null) : row.phone,
    // 059. CORRECTABLE FOR THE SAME REASON THE ADDRESS IS: nothing has
    // happened yet. The word is a held intention until somebody opens the
    // link, and getting it wrong is the commonest thing to get wrong about a
    // person you have met once on a job site. Stored NULL for a
    // subcontractor, which is what NULL means -- so switching back writes the
    // ordinary state rather than a second spelling of it.
    engaged_as: has("engagedAs")
      ? (isHandyman(b.engagedAs) ? "handyman" : null) : row.engaged_as,
  };
  if (next.email && !EMAIL_RE.test(next.email)) return c.json({ error: "bad_email" }, 400);
  if (has("phone") && String(b.phone || "").trim() && !next.phone) {
    return c.json({ error: "bad_phone" }, 400);
  }
  if (has("engagedAs") && !isEngagedAs(b.engagedAs)) {
    return c.json({ error: "bad_engaged_as" }, 400);
  }

  // Read before the write rather than after it, because the handyman check
  // needs the kind. The same refusal the create route gives, from the same
  // predicate -- a screen that could set it here and not there would be two
  // answers to one question.
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  if (next.engaged_as === "handyman" && !mayEngageHandyman(account?.kind)) {
    return c.json({ error: "not_a_handyman_account" }, 403);
  }

  const changed = Object.keys(next).filter((k) => (next[k] || null) !== (row[k] || null));
  if (!changed.length) return c.json({ error: "nothing_to_change" }, 400);

  // AN ADDRESS THAT IS BEING REPLACED HAS A LIVE CREDENTIAL SITTING IN IT.
  //
  // Resending deliberately reuses the token, because reissuing would break
  // the link already in somebody's inbox. That reasoning inverts here: the
  // whole reason to change an address is that the link went to the wrong
  // person, and leaving their copy working hands a stranger a way onto this
  // account's roster.
  //
  // REPLACED or REMOVED, never merely ADDED. An invite made as a link to hand
  // over has no address and was never sent by us -- but it may well have been
  // pasted into a message by hand, so adding an email to it must not kill the
  // link somebody is already holding.
  const replaced = (was, now) => !!was && (now || null) !== was;
  const reissue = replaced(row.email, next.email) || replaced(row.phone, next.phone);
  const token = reissue ? newInviteToken() : row.token;
  const expires = reissue
    ? new Date(Date.now() + INVITE_TTL_DAYS * 86400_000).toISOString()
    : row.expires_at;

  await c.env.DB.prepare(
    `UPDATE sub_invites SET company_name = ?, contact = ?, label = ?, email = ?, phone = ?,
            token = ?, expires_at = ?, sent_at = ?
      WHERE id = ? AND account_id = ?`
  ).bind(next.company_name, next.contact, next.label, next.email, next.phone,
    // Nothing has gone to the new address, so the status line must stop
    // saying it has. That is also what makes the panel offer Send again
    // rather than reading as finished.
    token, expires, reissue ? null : row.sent_at, row.id, accountId).run();

  // Its own statement, for the reason the create route gives: a database
  // without 059 must still be able to correct an address.
  let asRecorded = true;
  if ((next.engaged_as || null) !== (row.engaged_as || null)) {
    try {
      await c.env.DB.prepare(`UPDATE sub_invites SET engaged_as = ? WHERE id = ?`)
        .bind(next.engaged_as, row.id).run();
    } catch (err) {
      if (!missingSchema(err)) throw err;
      console.warn("[invites] 059_invite_engaged_as not applied - relationship not changed");
      asRecorded = false;
    }
  }

  await logActivity(c.env, accountId, userId, "invite_updated",
    reissue
      ? `Invite details changed and a new link issued${next.email ? ` for ${next.email}` : ""}`
      : "Invite details changed");

  const after = await c.env.DB.prepare(`SELECT * FROM sub_invites WHERE id = ?`).bind(row.id).first();
  // Said rather than inferred: the panel has to tell somebody the old link
  // has stopped working, and a browser working that out from the url it can
  // see would be a second implementation of this rule.
  return c.json({ ...inviteRowToJs(after, account), reissued: reissue,
    engagedAsRecorded: asRecorded });
});

// Invite a contractor who is ALREADY on the roster to get a login.
//
// Being on a roster and being able to sign in are two different records, and
// there was no way to get from the first to the second. The Contractors screen
// drew a company with no seat behind it exactly like one with a seat; the only
// invite flow started from an empty form; and "Forgot password" could only
// resend an invite that already existed. So a contractor an account had typed
// in, or one whose invite was never created, had no path to a login at all --
// not from their own card, not from the sign-in page, not from the console.
//
// This is the missing step, started from the record rather than from a blank
// form: no retyping a name and an address the account already holds, and no
// "you already have a contractor with this name" warning, because inviting
// this one is the whole point.
//
// The invite carries `company_id` from the moment it is made rather than only
// once it is spent, so redemption attaches the seat to THIS company instead of
// deduping its way back to it by email and hoping the applicant types the same
// one. Same column, one step earlier; no migration.
app.post("/api/subs/:companyId/invite", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const companyId = c.req.param("companyId");

  // Their own roster only. A company this account has no engagement with reads
  // as missing rather than forbidden, the same answer mayWriteCompanyDocs
  // gives, so this cannot be walked to find out which company ids are real.
  const engaged = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements
      WHERE account_id = ? AND company_id = ? AND status <> 'ended'`
  ).bind(accountId, companyId).first();
  if (!engaged) return c.json({ error: "not_found" }, 404);

  const company = await c.env.DB.prepare(
    `SELECT id, company, contact, email, phone FROM companies WHERE id = ?`).bind(companyId).first();
  if (!company) return c.json({ error: "not_found" }, 404);

  // Already has somebody who can sign in as them here. Sending another invite
  // would be inviting a company that has already arrived.
  const seat = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM memberships
      WHERE account_id = ? AND company_id = ? AND role = 'contractor'`
  ).bind(accountId, companyId).first();
  if (seat) return c.json({ error: "already_has_login" }, 409);

  const body = await c.req.json().catch(() => ({}));
  const email = String(body?.email ?? company.email ?? "").trim() || null;
  const phone = normalizePhone(String(body?.phone ?? company.phone ?? "").trim()) || null;
  if (!email && !phone) return c.json({ error: "no_contact" }, 400);

  // An invite already out to this company is RESENT, not replaced. A second
  // live token for one contractor is two links in one inbox and a list that
  // reads as two people -- the same reason the resend route reuses its token.
  //
  // Matched on the ADDRESS as well as the company id, because every invite
  // raised before this route existed came off the blank form and carries no
  // company_id at all: that is only written on redemption. Looking only at the
  // company id would have missed every one of them and minted a second live
  // token for a contractor who already had one sitting in their inbox -- which
  // is the exact thing this route refuses to do.
  const open = await c.env.DB.prepare(
    `SELECT * FROM sub_invites
      WHERE account_id = ? AND used_at IS NULL AND revoked_at IS NULL
        AND datetime(expires_at) > datetime('now')
        AND (company_id = ?
             OR (company_id IS NULL AND ? IS NOT NULL AND lower(email) = lower(?))
             OR (company_id IS NULL AND ? IS NOT NULL AND phone = ?))
      ORDER BY created_at DESC LIMIT 1`
  ).bind(accountId, companyId, email, email, phone, phone).first().catch(() => null);

  // Adopt it while we are here. From now on it names the company it is for, so
  // redeeming it attaches the seat to this record rather than deduping its way
  // back to it.
  if (open && !open.company_id) {
    await c.env.DB.prepare(`UPDATE sub_invites SET company_id = ? WHERE id = ?`)
      .bind(companyId, open.id).run();
    open.company_id = companyId;
  }

  let row = open;
  if (!row) {
    const id = uid();
    const token = newInviteToken();
    const expires = new Date(Date.now() + INVITE_TTL_DAYS * 864e5).toISOString();
    await c.env.DB.prepare(
      `INSERT INTO sub_invites (id, account_id, token, label, email, phone, contact,
                                company_name, company_id, created_by, expires_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, token, company.company, email, phone,
      company.contact || null, company.company, companyId, userId, expires).run();
    row = await c.env.DB.prepare(`SELECT * FROM sub_invites WHERE id = ?`).bind(id).first();
  }

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  const sent = await deliverSubInvite(c.env, { row, account, accountId, userId });
  if (sent.emailed || sent.texted) {
    await c.env.DB.prepare(`UPDATE sub_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`)
      .bind(row.id).run();
  }
  await logActivity(c.env, accountId, userId, open ? "invite_resent" : "invite_created",
    sent.went ? `Invite to ${company.company} sent to ${sent.went}`
      : `Invite to ${company.company} could not be sent`);

  const after = await c.env.DB.prepare(`SELECT * FROM sub_invites WHERE id = ?`).bind(row.id).first();
  return c.json({
    ...inviteRowToJs(after, account),
    resent: !!open,
    emailed: sent.emailed, texted: sent.texted,
    emailError: sent.emailError, textError: sent.textError,
  });
});

app.delete("/api/invites/:id", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  // Scoped by account, so an id from another account is a miss rather than a
  // revocation of somebody else's link.
  const res = await c.env.DB.prepare(
    `UPDATE sub_invites SET revoked_at = CURRENT_TIMESTAMP
     WHERE id = ? AND account_id = ? AND used_at IS NULL AND revoked_at IS NULL`
  ).bind(c.req.param("id"), accountId).run();
  if (!res.meta?.changes) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true });
});

// Public. Looks a token up so the application form can name who it is for and
// carry their branding, before the applicant has typed anything.
async function lookupInvite(env, token) {
  if (!token || !/^[0-9a-f]{64}$/.test(token)) return { error: "invalid" };
  const row = await env.DB.prepare(`SELECT * FROM sub_invites WHERE token = ?`).bind(token).first();
  if (!row) return { error: "invalid" };
  if (row.revoked_at) return { error: "revoked" };
  if (row.used_at) return { error: "used" };
  if (new Date(row.expires_at) < new Date()) return { error: "expired" };
  // `kind` IS NAMED OR IT IS SILENTLY DROPPED, and the direction it fails in
  // is the quiet one. `createApplication` re-asks `mayEngageHandyman` before
  // applying the invite's relationship -- an account can change kind between
  // being invited and being joined -- and with the column absent that answers
  // false for every account, so a handyman invite redeemed correctly as a
  // subcontractor and nothing anywhere said a word. The public route builds
  // its own `account` object field by field, so this reaches nobody.
  const account = await env.DB.prepare(
    `SELECT id, name, subdomain, kind, theme, logo_key, use_default_mark FROM accounts WHERE id = ?`
  ).bind(row.account_id).first();
  if (!account) return { error: "invalid" };
  return { invite: row, account };
}

app.get("/api/invite/:token", async (c) => {
  const { error, invite, account } = await lookupInvite(c.env, c.req.param("token"));
  // An invite raised from a contractor's own card names the company it is for,
  // and that company is already ON the roster with its details typed in. The
  // form then asked them to enter all of it again, which is asking somebody to
  // prove they read the email: what they actually need is a password.
  //
  // Their own record, answered to somebody holding a token that was emailed to
  // them. No new exposure -- the token already lets its holder BECOME this
  // company on this roster, which is strictly more than reading their own
  // phone number.
  let known = null;
  if (!error && invite?.company_id) {
    const co = await c.env.DB.prepare(
      `SELECT company, contact, email, phone, license, ubi, city, state, zip
         FROM companies WHERE id = ?`).bind(invite.company_id).first();
    const en = await c.env.DB.prepare(
      `SELECT categories FROM engagements WHERE account_id = ? AND company_id = ?`
    ).bind(invite.account_id, invite.company_id).first();
    if (co) {
      known = {
        company: co.company || null, contact: co.contact || null,
        email: co.email || null, phone: co.phone || null,
        license: co.license || null, ubi: co.ubi || null,
        city: co.city || null, state: co.state || null, zip: co.zip || null,
        categories: parseJson(en?.categories, []),
      };
    }
  }
  // Every failure reads the same from outside: a token that was never valid
  // and one that was spent an hour ago are not worth telling apart for
  // somebody probing, and the person holding a real dead link needs the same
  // instruction either way -- ask for a new one.
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);
  return c.json({
    label: invite.label,
    // What the account typed when inviting, so the form opens part-filled
    // rather than asking a contractor to retype what somebody already knew.
    // Not enforced: a link passed to the right person at the wrong desk is
    // still a real application, and locking the address would break that.
    invitedEmail: invite.email || null,
    phone: invite.phone || null,
    contact: invite.contact || null,
    companyName: invite.company_name || null,
    // What the account already holds about them, when this invite was raised
    // from their record. `enough` is the question the screen asks: is there a
    // real profile here, or a name somebody typed and nothing else? Decided
    // here rather than in the browser so the two cannot disagree about what
    // counts as already filled in.
    known,
    knownEnough: inviteKnownEnough(known),
    // 059. What the account said they would be, so the form can stop asking a
    // maintenance worker for a contractor licence and stop offering him
    // trades this account can never assign him -- `tradesAllowed` already
    // refuses those at the work order, so a grid that offers them is a screen
    // looser than the route. Answered for every invite, because "subcontractor"
    // is what the form has always assumed.
    engagedAs: engagedAs(invite.engaged_as),
    account: {
      name: account.name, subdomain: account.subdomain,
      theme: parseJson(account.theme),
      logoKey: account.logo_key, useDefaultMark: !!account.use_default_mark,
      id: account.id,
    },
  });
});

app.post("/api/invite/:token", async (c) => {
  const rl = await rateLimit(c.env, "apply", clientIp(c), { limit: 10, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const { error, invite, account } = await lookupInvite(c.env, c.req.param("token"));
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);

  const body = await c.req.json().catch(() => ({}));
  const problem = applicationProblem(body);
  if (problem) return c.json({ error: problem }, 400);

  // The password, if they set one here. Optional so the older flow -- apply
  // now, discover the password screen later -- still works for a link that
  // was already out when this shipped.
  const password = String(body.password || "");
  if (password && password.length < 8) return c.json({ error: "weak_password" }, 400);

  const { companyId, userId: applicantId } = await createApplication(c.env, account, body,
    invite.email ? `Invited by email to ${invite.email}.`
      : invite.label ? `Applied through an invite link sent to ${invite.label}.`
      : "Applied through an invite link.",
    // Set when the invite was raised from a contractor already on the roster,
    // so the seat lands on that record rather than on a near-match of it.
    { boundCompanyId: invite.company_id || null,
      // And what the account said they would be when they asked them in. The
      // invite is the only place that word exists until this moment -- the
      // engagement is created right here.
      engagedAs: engagedAs(invite.engaged_as) });

  // Spent, and only now -- an application that failed halfway should leave
  // the link usable rather than stranding somebody with a dead one.
  await c.env.DB.prepare(
    `UPDATE sub_invites SET used_at = CURRENT_TIMESTAMP, company_id = ? WHERE id = ?`
  ).bind(companyId, invite.id).run();

  await logActivity(c.env, account.id, null, "invite_accepted",
    `${body.company} joined through an invite link`);

  return c.json({ ok: true,
    ...(await applicantWayIn(c, { account, userId: applicantId, email: body.email, password })) });
});

// ---------------------------------------------------------------------------
// 074. "Sent via SubSub" -- the claim link on every work order
// ---------------------------------------------------------------------------
// Every work order a hiring account sends carries one line saying where it
// came from and a link, /claim/<token>, that opens the work order on the
// sub's phone and makes them a free login with their mobile and a texted
// code. The rules are in shared/claim.js; this is the database half.
//
// One link per work order, minted when it is issued and stamped with the
// account that sent it and the company it went to. "Which account brought
// this sub in" is written once, by the claim, and the first claim wins.

// Minted on issue, and lazily for any work order issued before 074 the first
// time somebody opens it. INSERT OR IGNORE on the work order's unique key, so
// two requests at once agree on one token rather than racing to two.
//
// A database without 074 answers null: the work order still goes, with the
// footer and no link, because losing the link costs a recruitment and refusing
// the work order costs the job.
async function ensureClaimLink(env, { woId, accountId, companyId }) {
  if (!woId || !accountId || !companyId) return null;
  try {
    const have = await env.DB.prepare(
      `SELECT token FROM wo_claim_links WHERE work_order_id = ?`).bind(woId).first();
    if (have?.token) return have.token;
    const token = [...crypto.getRandomValues(new Uint8Array(32))]
      .map((b) => b.toString(16).padStart(2, "0")).join("");
    await env.DB.prepare(
      `INSERT OR IGNORE INTO wo_claim_links (token, work_order_id, account_id, company_id)
       VALUES (?, ?, ?, ?)`).bind(token, woId, accountId, companyId).run();
    const row = await env.DB.prepare(
      `SELECT token FROM wo_claim_links WHERE work_order_id = ?`).bind(woId).first();
    return row?.token || null;
  } catch (err) {
    if (!missingSchema(err)) throw err;
    console.warn("[claim] 074_wo_claims not applied - work order sent without a claim link");
    return null;
  }
}

// Can anybody sign in as this company already? A contractor seat whose person
// has a login, anywhere -- or the company is an account's own, run by people
// who sign in to that account. Deliberately UNSCOPED, for the reason
// `companyAnswersForItself` is: a roofer whose login is on another general
// contractor's account is already on SubSub, and this account's work order
// reaching them is a sign-in, not a recruitment to credit to anybody.
async function companyLoginAuthIds(env, companyId) {
  const { results } = await env.DB.prepare(
    `SELECT DISTINCT u.auth_id FROM memberships m JOIN users u ON u.id = m.user_id
      WHERE m.company_id = ? AND m.role = 'contractor' AND u.auth_id IS NOT NULL`
  ).bind(companyId).all();
  const ids = (results || []).map((r) => r.auth_id);
  let ownAccount = false;
  try {
    ownAccount = !!(await env.DB.prepare(
      `SELECT 1 AS yes FROM accounts WHERE company_id = ? LIMIT 1`).bind(companyId).first());
  } catch (err) {
    if (!missingSchema(err)) throw err;
  }
  return { ids, ownAccount };
}

// The link, the work order behind it and the company, or a refusal. Shape is
// checked before any read, so a guessed path costs nothing; and an unknown
// token and a malformed one answer alike.
async function claimLookup(env, token) {
  if (!validClaimToken(token)) return { error: "invalid" };
  const link = await env.DB.prepare(`SELECT * FROM wo_claim_links WHERE token = ?`).bind(token).first();
  if (!link) return { error: "invalid" };
  const wo = await env.DB.prepare(
    `SELECT w.*, j.title, j.address, j.area, j.zip, j.date, j.time, j.scope AS job_scope,
            j.status AS job_status
       FROM work_orders w JOIN jobs j ON j.id = w.job_id WHERE w.id = ?`
  ).bind(link.work_order_id).first();
  const account = await env.DB.prepare(
    `SELECT id, name, subdomain, kind, theme, logo_key, use_default_mark FROM accounts WHERE id = ?`
  ).bind(link.account_id).first();
  const company = await env.DB.prepare(
    `SELECT id, company, contact, email, phone FROM companies WHERE id = ?`).bind(link.company_id).first();
  if (!wo || !account || !company) return { error: "invalid" };
  return { link, wo, account, company };
}

// THE WORK ORDER, AS THE SUB WAS SENT IT. What the email and the work order
// itself already carry -- the job, the address, the trade, the scope, the pay,
// the deadline -- and nothing about anybody else: not the other trades on the
// job, not the tenant, not the account's notes. A forwarded link shows exactly
// what a forwarded work order already shows.
function claimWorkOrderShape(wo) {
  return {
    number: wo.wo_number, trade: wo.trade, title: wo.title || null,
    address: wo.address || null, area: wo.area || null, zip: wo.zip || null,
    date: wo.date || null, time: wo.time || null,
    scope: wo.trade_scope || wo.job_scope || null,
    payKind: wo.pay_kind || "fixed",
    valueCents: wo.value_cents ?? null, rateCents: wo.rate_cents ?? null,
    capHours: wo.cap_hours ?? null,
    respondBy: wo.respond_by || null, status: wo.status,
    autoScheduled: !!wo.auto_scheduled,
    withdrawn: !!wo.voided_at,
  };
}

// WHAT SUPABASE WILL SEND A CODE BY. /auth/v1/settings with the anon key is
// read-only and says which providers are switched on: phone is on only once
// an SMS provider is configured, which is the whole question for the texted
// code. Best effort with a short timeout -- an answer that cannot be read
// offers email alone, which needs no SMS provider and is the default anyway.
// Never "phone on" by guess: a phone box that can never send a code is a dead
// end on the first SubSub screen a sub ever sees.
async function claimLoginMethods(env) {
  if (!env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) return { emailLogin: false, phoneLogin: false };
  try {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), 2500);
    const r = await fetch(`${env.SUPABASE_URL}/auth/v1/settings`,
      { headers: { apikey: env.SUPABASE_ANON_KEY }, signal: ctl.signal });
    clearTimeout(t);
    const j = r.ok ? await r.json().catch(() => ({})) : {};
    return { emailLogin: j?.external?.email !== false, phoneLogin: j?.external?.phone === true };
  } catch {
    return { emailLogin: true, phoneLogin: false };
  }
}

async function claimStateFor(env, link) {
  if (link.claimed_at) return "claimed";
  const { ids, ownAccount } = await companyLoginAuthIds(env, link.company_id);
  return claimState({ claimedAt: null, companyHasLogin: ids.length > 0 || ownAccount });
}

// Opened. Counted on the page load rather than anything later, because
// "the link was opened" is the event the funnel measures.
app.get("/api/claim/:token", async (c) => {
  const rl = await rateLimit(c.env, "claim-view", clientIp(c), { limit: 120, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);
  const found = await claimLookup(c.env, c.req.param("token"));
  if (found.error) return c.json({ error: "not_found" }, 404);
  const { link, wo, account, company } = found;
  await c.env.DB.prepare(
    `UPDATE wo_claim_links SET open_count = open_count + 1, last_opened_at = CURRENT_TIMESTAMP,
            first_opened_at = COALESCE(first_opened_at, CURRENT_TIMESTAMP)
      WHERE token = ?`).bind(link.token).run();
  return c.json({
    state: await claimStateFor(c.env, link),
    // Which ways in can actually send a code, read off Supabase's own
    // settings, so the page never offers a texted code before an SMS
    // provider exists behind it. Email is the default way in.
    ...(await claimLoginMethods(c.env)),
    emailHint: maskEmail(company.email),
    company: { name: company.company || null, contact: company.contact || null },
    // The last four digits of the number this account holds for them, never
    // the whole number: enough to say which phone to use, not enough to hand
    // somebody holding a forwarded link a phone number they did not have.
    phoneHint: maskPhone(company.phone),
    account: {
      id: account.id, name: account.name, subdomain: account.subdomain,
      theme: parseJson(account.theme), logoKey: account.logo_key,
      useDefaultMark: !!account.use_default_mark,
      signIn: `https://${portalUrl(account.subdomain)}/`,
    },
    workOrder: claimWorkOrderShape(wo),
  });
});

// Ask Supabase to text a code. Through the Worker rather than straight from
// the browser so the number can be checked against the one this account holds
// before anything is sent, and so it is rate-limited per link as well as per
// address -- a texted code costs money and lands on somebody's phone.
app.post("/api/claim/:token/code", async (c) => {
  const token = c.req.param("token");
  const rlIp = await rateLimit(c.env, "claim-code-ip", clientIp(c), { limit: 20, windowMinutes: 60 });
  const rlTok = await rateLimit(c.env, "claim-code", token, { limit: 5, windowMinutes: 60 });
  if (!rlIp.ok || !rlTok.ok) return c.json({ error: "rate_limited" }, 429);
  const found = await claimLookup(c.env, token);
  if (found.error) return c.json({ error: "not_found" }, 404);
  const state = await claimStateFor(c.env, found.link);
  if (state !== "claimable") return c.json({ error: state }, 409);
  const b = await c.req.json().catch(() => ({}));
  // BY EMAIL OR BY MOBILE, one at a time. Email works with no SMS provider at
  // all -- Supabase sends the code from the address it already sends
  // confirmations from -- which is what lets a sub claim before texting is set
  // up. The rule is the same for both: the one on record, or any real one.
  const byEmail = b.email != null && b.email !== "";
  const problem = byEmail
    ? claimEmailProblem({ entered: b.email, onRecord: found.company.email })
    : claimPhoneProblem({ entered: b.phone, onRecord: found.company.phone });
  if (problem) {
    return c.json({ error: problem,
      hint: byEmail ? maskEmail(found.company.email) : maskPhone(found.company.phone) },
    problem.startsWith("bad_") ? 400 : 409);
  }
  if (!c.env.SUPABASE_URL || !c.env.SUPABASE_ANON_KEY) {
    return c.json({ error: byEmail ? "email_login_unavailable" : "phone_login_unavailable" }, 501);
  }
  let res, body;
  try {
    res = await fetch(`${c.env.SUPABASE_URL}/auth/v1/otp`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: c.env.SUPABASE_ANON_KEY },
      body: JSON.stringify(byEmail
        ? { email: cleanEmail(b.email), create_user: true }
        : { phone: toE164(b.phone), create_user: true }),
    });
    body = await res.json().catch(() => ({}));
  } catch (err) {
    return c.json({ error: "auth_unreachable", detail: String(err?.message || err) }, 502);
  }
  if (!res.ok) {
    const msg = String(body?.msg || body?.error_description || body?.message || body?.error || "");
    // Phone sign-in switched off, or no SMS provider behind it, is OUR
    // configuration and nothing the person holding the phone can fix -- so it
    // is its own answer, and the page says to use the work order's own link
    // instead of "try again".
    if (/provider|disabled|not enabled|unsupported phone/i.test(msg)) {
      console.error("[claim] Supabase sign-in by code is not configured:", msg);
      return c.json({ error: byEmail ? "email_login_unavailable" : "phone_login_unavailable" }, 501);
    }
    if (res.status === 429) return c.json({ error: "rate_limited" }, 429);
    console.error("[claim] Supabase refused the code:", res.status, msg);
    return c.json({ error: "code_failed", detail: msg.slice(0, 200) }, 502);
  }
  return c.json({ ok: true, sentTo: byEmail ? maskEmail(b.email) : maskPhone(b.phone) });
});

// Check the code, make the login, record who brought them in.
//
// THE VERIFIED PHONE IS SUPABASE'S, NOT THE BODY'S. It comes back on the user
// Supabase returns for the code, and that is what is matched against the
// number on record -- so the check above is a courtesy and this is the gate.
//
// The session Supabase hands back is passed through to the browser, which
// stores it the way a password sign-in does. Nothing here keeps it.
app.post("/api/claim/:token/verify", async (c) => {
  const token = c.req.param("token");
  const rl = await rateLimit(c.env, "claim-verify", token, { limit: 10, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);
  const found = await claimLookup(c.env, token);
  if (found.error) return c.json({ error: "not_found" }, 404);
  const { link, wo, account, company } = found;
  const b = await c.req.json().catch(() => ({}));
  const byEmail = b.email != null && b.email !== "";
  if (!c.env.SUPABASE_URL || !c.env.SUPABASE_ANON_KEY) {
    return c.json({ error: byEmail ? "email_login_unavailable" : "phone_login_unavailable" }, 501);
  }
  const email = byEmail ? cleanEmail(b.email) : null;
  const phone = byEmail ? null : toE164(b.phone);
  const code = String(b.code || "").replace(/\D/g, "");
  if (byEmail && !email) return c.json({ error: "bad_email" }, 400);
  if (!byEmail && !phone) return c.json({ error: "bad_phone" }, 400);
  if (code.length < 4) return c.json({ error: "bad_code" }, 400);

  // Refused before the code is spent, so somebody told "already on SubSub"
  // has not burnt the code they will not need.
  const before = await claimStateFor(c.env, link);
  if (before === "on_subsub") return c.json({ error: "on_subsub" }, 409);

  let res, sess;
  try {
    res = await fetch(`${c.env.SUPABASE_URL}/auth/v1/verify`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: c.env.SUPABASE_ANON_KEY },
      body: JSON.stringify(byEmail
        ? { type: "email", email, token: code }
        : { type: "sms", phone, token: code }),
    });
    sess = await res.json().catch(() => ({}));
  } catch (err) {
    return c.json({ error: "auth_unreachable", detail: String(err?.message || err) }, 502);
  }
  if (!res.ok || !sess?.access_token || !sess?.user?.id) {
    return c.json({ error: "bad_code" }, 400);
  }
  const authId = sess.user.id;
  // What Supabase VERIFIED, never what the body named -- the gate is here.
  const verified = byEmail ? (sess.user.email || email) : (sess.user.phone || phone);
  const problem = byEmail
    ? claimEmailProblem({ entered: verified, onRecord: company.email })
    : claimPhoneProblem({ entered: verified, onRecord: company.phone });
  if (problem) {
    return c.json({ error: problem, hint: byEmail ? maskEmail(company.email) : maskPhone(company.phone) }, 409);
  }

  // Already used, by this person: a second press, or a refresh. Same answer,
  // nothing written twice.
  if (link.claimed_at) {
    const mine = link.claimed_user_id && (await c.env.DB.prepare(
      `SELECT 1 AS yes FROM users WHERE id = ? AND auth_id = ?`).bind(link.claimed_user_id, authId).first());
    if (!mine) return c.json({ error: "claimed" }, 409);
    return c.json({ ok: true, attributed: false, ...claimSessionReply(sess, account, link.claimed_user_id) });
  }

  // A login for the company already exists. If it is this person's own --
  // they had signed up by text before -- it is a sign-in and nothing is
  // credited; anybody else's, and the company is not theirs to claim.
  const holders = await companyLoginAuthIds(c.env, company.id);
  const already = holders.ids.length > 0 || holders.ownAccount;
  if (already && !holders.ids.includes(authId)) return c.json({ error: "on_subsub" }, 409);

  // THE PERSON. Their own row if this login is already linked to one; else the
  // company's unclaimed seat holder -- somebody the account added or invited
  // who never set up a login -- so one person does not become two; else a new
  // row. A phone login has no email, so the row takes the company's address
  // when nobody holds it, and the placeholder the rest of the product already
  // reads as "no real address" when somebody does.
  // An email login has proved the address, so the row already holding that
  // address with no login behind it -- added from the console, or invited and
  // never finished -- is theirs, and linking it is what keeps one person one
  // row. The same trust password-help extends when it mints a missing login.
  // A phone is recorded only when a phone was what was verified.
  const verifiedPhone = byEmail ? null : normalizePhone(verified);
  const verifiedEmail = byEmail ? cleanEmail(verified) : null;
  let user = await c.env.DB.prepare(`SELECT * FROM users WHERE auth_id = ?`).bind(authId).first();
  if (!user && verifiedEmail) {
    user = await c.env.DB.prepare(
      `SELECT * FROM users WHERE lower(email) = ? AND auth_id IS NULL ORDER BY created_at LIMIT 1`
    ).bind(verifiedEmail).first();
    if (user) await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ?`).bind(authId, user.id).run();
  }
  if (!user) {
    user = await c.env.DB.prepare(
      `SELECT u.* FROM memberships m JOIN users u ON u.id = m.user_id
        WHERE m.company_id = ? AND m.role = 'contractor' AND u.auth_id IS NULL
        ORDER BY (m.account_id = ?) DESC, u.created_at LIMIT 1`
    ).bind(company.id, account.id).first();
    if (user) {
      await c.env.DB.prepare(`UPDATE users SET auth_id = ?, phone = COALESCE(phone, ?) WHERE id = ?`)
        .bind(authId, verifiedPhone, user.id).run();
    }
  }
  if (!user) {
    const userId = uid();
    // The address they proved first, then the one this account holds for the
    // company, and the placeholder the product reads as "no real address" when
    // somebody else already holds it.
    const want = verifiedEmail || cleanEmail(company.email);
    const emailFree = want && !(await c.env.DB.prepare(
      `SELECT 1 AS yes FROM users WHERE lower(email) = lower(?)`).bind(want).first());
    await c.env.DB.prepare(
      `INSERT INTO users (id, auth_id, name, email, phone) VALUES (?, ?, ?, ?, ?)`
    ).bind(userId, authId, company.contact || company.company || "Contractor",
      emailFree ? want : `${userId}@no-email.invalid`, verifiedPhone).run();
    user = { id: userId };
  }

  // THE SEAT, on the account that sent the work order, so the work order they
  // just read is the first thing they can answer. A contractor seat is free:
  // nothing on any plan counts one.
  const seat = await c.env.DB.prepare(
    `SELECT id FROM memberships WHERE user_id = ? AND account_id = ?`).bind(user.id, account.id).first();
  if (!seat) {
    await c.env.DB.prepare(
      `INSERT INTO memberships (id, user_id, account_id, role, company_id) VALUES (?, ?, ?, 'contractor', ?)`
    ).bind(uid(), user.id, account.id, company.id).run();
  }

  // Claimed, and credited -- unless somebody already holds the credit, which
  // INSERT OR IGNORE leaves alone: the first account to bring a sub in is the
  // one that did. Not credited at all when the company had a login already.
  await c.env.DB.prepare(
    `UPDATE wo_claim_links SET claimed_at = CURRENT_TIMESTAMP, claimed_user_id = ?
      WHERE token = ? AND claimed_at IS NULL`).bind(user.id, link.token).run();
  let attributed = false;
  if (!already) {
    const r = await c.env.DB.prepare(
      `INSERT OR IGNORE INTO sub_attributions (company_id, account_id, work_order_id, token, user_id)
       VALUES (?, ?, ?, ?, ?)`).bind(company.id, account.id, wo.id, link.token, user.id).run();
    attributed = (r?.meta?.changes || 0) > 0;
  }
  // A claim is a sub signing up, and the work order they claimed is the touch
  // that brought them -- so the sending account's referral code is credited
  // with the company, beside 074's first-account record. Only for a company
  // that had no login anywhere before, for the same reason that row is.
  if (attributed && isGcKind(account.kind)) {
    try {
      const code = await ensureReferralCode(c.env, { kind: "gc", accountId: account.id });
      await logReferralTouch(c.env, code, "claim");
      await recordReferral(c.env, { subjectKind: "company", subjectId: company.id,
        cookie: { code, channel: "claim", at: new Date().toISOString() } });
    } catch (err) {
      if (!missingSchema(err)) console.error("[referral] claim:", err?.message || err);
    }
  }
  await logEvent(c.env, account.id, user.id, "sub.claimed", company.id,
    { workOrderId: wo.id, woNumber: wo.wo_number, attributed });
  if (attributed) {
    await logActivity(c.env, account.id, user.id, "sub_claimed",
      `${company.company} joined SubSub from ${wo.wo_number}`);
  }
  return c.json({ ok: true, attributed, ...claimSessionReply(sess, account, user.id) });
});

// What the browser needs to be signed in, and where to go. The tokens are the
// person's own, straight from Supabase.
function claimSessionReply(sess, account, userId = null) {
  return {
    userId,
    session: { access_token: sess.access_token, refresh_token: sess.refresh_token || null,
      expires_in: sess.expires_in || null },
    accountId: account.id, subdomain: account.subdomain,
  };
}

// The link for one work order, for the work order drawn in the app and its
// downloaded copy. Same door as the rest of the work order's reads, so a
// contractor gets their own and nobody else's.
app.get("/api/work-orders/:id/claim-link", async (c) => {
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const token = await ensureClaimLink(c.env,
    { woId: wo.id, accountId: wo.account_id, companyId: wo.company_id });
  return c.json({ url: claimUrl(token) });
});

// THE FUNNEL, PER SENDING ACCOUNT, for the staff console. Work orders sent is
// links minted; opened is links somebody opened at least once; claimed is the
// subs this account is credited with bringing onto SubSub. Staff route: it
// reads across every account, which is what the console is for and what no
// customer screen may borrow.
app.get("/api/platform/attribution", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  try {
    const { results: links } = await c.env.DB.prepare(
      `SELECT account_id, COUNT(*) AS sent,
              SUM(CASE WHEN first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened,
              SUM(open_count) AS opens
         FROM wo_claim_links GROUP BY account_id`).all();
    const { results: claims } = await c.env.DB.prepare(
      `SELECT account_id, COUNT(*) AS claimed FROM sub_attributions GROUP BY account_id`).all();
    const by = {};
    for (const r of links || []) by[r.account_id] = { sent: r.sent, opened: r.opened || 0, opens: r.opens || 0, claimed: 0 };
    for (const r of claims || []) (by[r.account_id] ||= { sent: 0, opened: 0, opens: 0, claimed: 0 }).claimed = r.claimed;
    return c.json({ accounts: Object.entries(by).map(([accountId, f]) => ({ accountId, ...claimFunnel(f), opens: f.opens })) });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ accounts: [], migration });
  }
});

// One account's funnel and the subs it brought in, by name, for the account's
// window in the console.
app.get("/api/platform/accounts/:id/attribution", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  const id = c.req.param("id");
  try {
    const f = await c.env.DB.prepare(
      `SELECT COUNT(*) AS sent,
              SUM(CASE WHEN first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened,
              SUM(open_count) AS opens
         FROM wo_claim_links WHERE account_id = ?`).bind(id).first();
    const { results } = await c.env.DB.prepare(
      `SELECT a.company_id, co.company, a.claimed_at, w.wo_number
         FROM sub_attributions a
         LEFT JOIN companies co ON co.id = a.company_id
         LEFT JOIN work_orders w ON w.id = a.work_order_id
        WHERE a.account_id = ? ORDER BY a.claimed_at DESC LIMIT 100`).bind(id).all();
    return c.json({
      ...claimFunnel({ sent: f?.sent || 0, opened: f?.opened || 0, claimed: (results || []).length }),
      opens: f?.opens || 0,
      subs: (results || []).map((r) => ({ companyId: r.company_id, company: r.company || null,
        claimedAt: r.claimed_at, woNumber: r.wo_number || null })),
    });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ ...claimFunnel(), opens: 0, subs: [], migration });
  }
});

// ===========================================================================
// 075. REFERRALS. Rules in shared/referral.js; this is the plumbing.
//
// A code is minted lazily, the first time anybody asks for theirs. A touch is
// counted whenever a link, a typed code, a claim or a Passport brings somebody
// in. Attribution is written ONCE, at signup (or at the claim that creates a
// sub's seat), from the last touch before it. A reward is written only when a
// referred account's first paid invoice arrives, and a month-free credit is
// handed to Stripe as a customer-balance credit the moment there is a
// customer to give it to.
// ===========================================================================

async function referralCodeRow(env, code) {
  const c = normalizeCode(code);
  if (!c) return null;
  const row = await env.DB.prepare(
    `SELECT r.*, a.name AS account_name, co.company AS company_name
       FROM referral_codes r
       LEFT JOIN accounts a ON a.id = r.account_id
       LEFT JOIN companies co ON co.id = r.company_id
      WHERE r.code = ?`).bind(c).first();
  return row || null;
}
const referrerName = (row) => (row?.kind === "sub" ? row.company_name : row?.account_name) || null;

async function ensureReferralCode(env, { kind, accountId = null, companyId = null }) {
  const lookup = () => (kind === "gc"
    ? env.DB.prepare(`SELECT code FROM referral_codes WHERE kind = 'gc' AND account_id = ?`).bind(accountId)
    : env.DB.prepare(`SELECT code FROM referral_codes WHERE kind = 'sub' AND company_id = ?`).bind(companyId)).first();
  const have = await lookup();
  if (have) return have.code;
  for (let i = 0; i < 6; i++) {
    const code = mintCode(crypto.getRandomValues(new Uint8Array(CODE_LENGTH)));
    try {
      await env.DB.prepare(
        `INSERT INTO referral_codes (code, kind, account_id, company_id) VALUES (?, ?, ?, ?)`
      ).bind(code, kind, kind === "gc" ? accountId : null, kind === "sub" ? companyId : null).run();
      return code;
    } catch (err) {
      if (missingSchema(err)) throw err;
      // Either the code collided (try another) or a second request minted
      // this owner's code first (use theirs). Re-reading tells which.
      const again = await lookup();
      if (again) return again.code;
    }
  }
  throw new Error("referral_code_mint_failed");
}

// Who this seat refers AS. A contractor seat speaks for its company; an admin
// or a project manager speaks for the account -- as a sub if the account is a
// subcontractor, as the hiring side otherwise. An owner or a tenant is a
// guest on somebody else's account and refers nobody.
async function referrerForSeat(c) {
  const { role, companyId, accountId } = c.get("auth");
  if (role === "contractor" && companyId) return { kind: "sub", companyId };
  if (role !== "admin" && role !== "pm") return null;
  const a = await c.env.DB.prepare(`SELECT kind FROM accounts WHERE id = ?`).bind(accountId).first();
  const kind = referrerKindForAccount(a?.kind);
  if (kind === "gc") return { kind: "gc", accountId };
  if (kind === "sub") {
    const own = await ensureAccountCompany(c.env, accountId);
    return own ? { kind: "sub", companyId: own } : null;
  }
  return null;
}

async function logReferralTouch(env, code, channel) {
  await env.DB.prepare(`INSERT INTO referral_touches (id, code, channel) VALUES (?, ?, ?)`)
    .bind(uid(), code, channel).run();
}

// Signup and claim both end here. `cookie` is what the browser carried (the
// last touch on subsub.work or app.subsub.work); `typed` is a code typed into
// the form, which is a touch made now and so beats any cookie. Never throws:
// a referral that cannot be recorded must not cost anybody their account.
async function recordReferral(env, { subjectKind, subjectId, cookie = null, typed = null, notCode = null }) {
  try {
    const now = new Date().toISOString();
    const touches = [];
    const typedCode = normalizeCode(typed);
    if (typedCode) touches.push({ code: typedCode, channel: "code", at: now, typed: true });
    if (cookie && typeof cookie === "object") {
      const at = String(cookie.at || "");
      const age = (Date.now() - Date.parse(at)) / 86400000;
      if (normalizeCode(cookie.code) && isChannel(cookie.channel) && age >= -1 && age <= REF_COOKIE_DAYS) {
        touches.push({ code: normalizeCode(cookie.code), channel: cookie.channel, at });
      }
    }
    // Last touch first; if it names a code that does not exist (a typo, a
    // stale cookie), fall back to the next one rather than to nothing.
    const ordered = touches.slice().sort((a, b) => String(b.at).localeCompare(String(a.at)));
    for (const t of ordered) {
      const row = await referralCodeRow(env, t.code);
      if (!row) continue;
      // Referring yourself earns nothing and records nothing.
      if (notCode && notCode(row)) continue;
      if (t.typed) await logReferralTouch(env, row.code, "code");
      const r = await env.DB.prepare(
        `INSERT OR IGNORE INTO referral_attributions (subject_kind, subject_id, code, channel, touched_at)
         VALUES (?, ?, ?, ?, ?)`).bind(subjectKind, subjectId, row.code, t.channel, t.at).run();
      return (r?.meta?.changes || 0) > 0 ? { code: row.code, channel: t.channel, kind: row.kind } : null;
    }
  } catch (err) {
    console.error("[referral] could not record:", err?.message || err);
  }
  return null;
}

// A month free, handed to Stripe. Applied as a CUSTOMER BALANCE credit, which
// Stripe takes off the next invoice automatically -- no coupon to configure,
// nothing that expires, and it works on either billing cycle. Keyed by the
// reward's id so a retry cannot credit twice. An account with no Stripe
// customer yet (on Basic) keeps the credit pending, and the nightly sweep
// applies it the day they subscribe.
async function applyReferralCredit(env, reward) {
  if (reward.kind !== "gc_credit" || reward.status !== "pending" || !reward.beneficiary_account_id) return false;
  const acct = await env.DB.prepare(`SELECT id, stripe_customer_id FROM accounts WHERE id = ?`)
    .bind(reward.beneficiary_account_id).first();
  if (!acct?.stripe_customer_id) {
    await env.DB.prepare(`UPDATE referral_rewards SET error = 'no_billing_yet' WHERE id = ?`).bind(reward.id).run();
    return false;
  }
  try {
    const txn = await stripeCall(env, `/customers/${acct.stripe_customer_id}/balance_transactions`, {
      params: { amount: -Math.abs(reward.amount_cents), currency: "usd",
        description: "SubSub referral: one month of Scale free",
        metadata: { referral_reward_id: reward.id } },
      idempotencyKey: `ref-credit:${reward.id}`,
    });
    const r = await env.DB.prepare(
      `UPDATE referral_rewards SET status = 'applied', processor_ref = ?, applied_at = CURRENT_TIMESTAMP, error = NULL
        WHERE id = ? AND status = 'pending'`).bind(txn?.id || null, reward.id).run();
    if ((r?.meta?.changes || 0) > 0) {
      await logActivity(env, acct.id, null, "referral_credit",
        `A referral credited a month of Scale (${formatCentsPlain(reward.amount_cents)}) to the next bill`).catch(() => {});
    }
    return true;
  } catch (err) {
    await env.DB.prepare(`UPDATE referral_rewards SET error = ? WHERE id = ?`)
      .bind(String(err?.message || err).slice(0, 300), reward.id).run();
    return false;
  }
}
const formatCentsPlain = (c) => "$" + (Math.round(c) / 100).toFixed(2).replace(/\.00$/, "");

async function applyPendingCreditsFor(env, accountIds) {
  for (const id of [...new Set(accountIds.filter(Boolean))]) {
    const { results } = await env.DB.prepare(
      `SELECT * FROM referral_rewards WHERE kind = 'gc_credit' AND status = 'pending' AND beneficiary_account_id = ?`
    ).bind(id).all();
    for (const r of results || []) await applyReferralCredit(env, r);
  }
}

// THE MOMENT A REFERRAL EARNS SOMETHING: a referred account's first PAID
// invoice. Idempotent by the unique index on (referred account, kind,
// beneficiary), so Stripe delivering invoice.paid twice -- or every month --
// writes the rewards once. Never throws; the nightly sweep is the safety net.
async function referralOnPaid(env, account, invoiceId = null) {
  try {
    const attr = await env.DB.prepare(
      `SELECT * FROM referral_attributions WHERE subject_kind = 'account' AND subject_id = ?`
    ).bind(account.id).first();
    const touched = [account.id];
    if (attr) {
      const code = await referralCodeRow(env, attr.code);
      const self = code && ((code.kind === "gc" && code.account_id === account.id)
        || (code.kind === "sub" && account.company_id && code.company_id === account.company_id));
      if (code && !self) {
        const referrer = code.kind === "gc"
          ? await env.DB.prepare(`SELECT billing FROM accounts WHERE id = ?`).bind(code.account_id).first()
          : null;
        const specs = rewardsFor({ codeKind: code.kind, referredKind: account.kind,
          referredBilling: account.billing, referrerBilling: referrer?.billing });
        for (const s of specs) {
          const benAccount = s.beneficiary === "referred" ? account.id : (code.kind === "gc" ? code.account_id : null);
          const benCompany = code.kind === "sub" && s.beneficiary === "referrer" ? code.company_id : null;
          const id = uid();
          const r = await env.DB.prepare(
            `INSERT OR IGNORE INTO referral_rewards
               (id, code, referred_account_id, kind, beneficiary, beneficiary_account_id, beneficiary_company_id,
                amount_cents, trigger_invoice_id)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
          ).bind(id, code.code, account.id, s.kind, s.beneficiary, benAccount, benCompany,
            s.amountCents, invoiceId).run();
          if ((r?.meta?.changes || 0) === 0) continue;
          await logEvent(env, null, null, "referral.reward_earned", id,
            { kind: s.kind, beneficiary: s.beneficiary, amountCents: s.amountCents,
              code: code.code, referredAccountId: account.id });
          if (s.kind === "sub_cash") {
            const co = await env.DB.prepare(`SELECT company, contact, email FROM companies WHERE id = ?`)
              .bind(code.company_id).first();
            if (co?.email) {
              const text = [
                `Hi${co.contact ? " " + String(co.contact).split(" ")[0] : ""},`, "",
                `${account.name} joined SubSub on your referral and has started paying for it.`,
                `That earns you $100 and the ${PREFERRED_SUB} badge on your profile.`, "",
                "The $100 is checked by a person at SubSub before it is paid, which usually takes a few days. We'll be in touch at this address about how you'd like it.", "",
                "Thanks for spreading the word.", "The SubSub team",
              ].join("\n");
              const res = await sendEmail(env, { to: co.email, subject: "You earned $100 for a SubSub referral", text });
              await logMail(env, { accountId: null, companyId: code.company_id, to: co.email,
                kind: "referral_reward", subject: "You earned $100 for a SubSub referral", result: res }).catch(() => {});
            }
          }
          if (s.kind === "gc_credit" && benAccount) touched.push(benAccount);
        }
      }
    }
    await applyPendingCreditsFor(env, touched);
  } catch (err) {
    if (!missingSchema(err)) console.error("[referral] on paid:", err?.message || err);
  }
}

// The safety net. Any attributed account with a paid invoice and no rewards
// (a webhook that died, or 075 pasted after somebody had already paid), and
// any month-free credit still waiting for its account to have billing.
async function referralSweep(env) {
  try {
    const { results: missed } = await env.DB.prepare(
      `SELECT a.* FROM referral_attributions ra JOIN accounts a ON a.id = ra.subject_id
        WHERE ra.subject_kind = 'account'
          AND EXISTS (SELECT 1 FROM invoices i WHERE i.account_id = a.id AND i.status = 'paid' AND i.amount_cents > 0)
          AND NOT EXISTS (SELECT 1 FROM referral_rewards r WHERE r.referred_account_id = a.id)
        LIMIT 200`).all();
    for (const a of missed || []) await referralOnPaid(env, a);
    const { results: waiting } = await env.DB.prepare(
      `SELECT r.* FROM referral_rewards r JOIN accounts a ON a.id = r.beneficiary_account_id
        WHERE r.kind = 'gc_credit' AND r.status = 'pending' AND a.stripe_customer_id IS NOT NULL LIMIT 200`).all();
    let applied = 0;
    for (const r of waiting || []) if (await applyReferralCredit(env, r)) applied++;
    return { missed: (missed || []).length, applied };
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { skipped: migration };
  }
}

// ---- the arrival ------------------------------------------------------------

// PUBLIC. A link opened, a Passport viewed. Counts the arrival and says whose
// code it is, so the landing page can say who invited them -- the referrer
// chose to put their name on that link. An unknown code is a plain 200 with
// ok:false rather than a 404, and the route is rate-limited per IP, because a
// code is eight characters from thirty and walking that space is not
// something this should help with.
app.post("/api/referrals/touch", async (c) => {
  const limit = await rateLimit(c.env, "referral-touch", clientIp(c), { limit: 60, windowMinutes: 10 });
  if (!limit.ok) return c.json({ ok: false, error: "slow_down" }, 429);
  const b = await c.req.json().catch(() => ({}));
  const channel = isChannel(b.channel) && b.channel !== "code" ? b.channel : "link";
  try {
    const row = await referralCodeRow(c.env, b.code);
    if (!row) return c.json({ ok: false });
    await logReferralTouch(c.env, row.code, channel);
    return c.json({ ok: true, code: row.code, kind: row.kind, from: referrerName(row) });
  } catch (err) {
    if (missingSchema(err)) return c.json({ ok: false });
    throw err;
  }
});

// ---- the referrer's own screen ----------------------------------------------

app.get("/api/referrals/mine", requireRole("admin", "pm", "contractor"), async (c) => {
  const { accountId } = c.get("auth");
  const who = await referrerForSeat(c);
  if (!who) return c.json({ available: false });
  try {
    const code = await ensureReferralCode(c.env, who);
    const row = await referralCodeRow(c.env, code);
    const { results: referred } = await c.env.DB.prepare(
      `SELECT ra.subject_id, ra.channel, ra.created_at, a.name, a.kind, a.plan, a.subscription_status
         FROM referral_attributions ra JOIN accounts a ON a.id = ra.subject_id
        WHERE ra.code = ? AND ra.subject_kind = 'account' ORDER BY ra.created_at DESC LIMIT 100`
    ).bind(code).all();
    const { results: rewards } = await c.env.DB.prepare(
      `SELECT r.*, a.name AS referred_name FROM referral_rewards r
         LEFT JOIN accounts a ON a.id = r.referred_account_id
        WHERE (r.code = ? AND r.beneficiary = 'referrer')
           OR (r.beneficiary = 'referred' AND r.beneficiary_account_id = ?)
        ORDER BY r.created_at DESC`
    ).bind(code, who.kind === "gc" ? accountId : "-").all();
    const today = new Date().toISOString().slice(0, 10);
    const inv = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM referral_invites WHERE code = ? AND created_at >= ?`).bind(code, today).first();
    const opens = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM referral_touches WHERE code = ?`).bind(code).first();
    const rewardFor = (accId) => (rewards || []).find((r) => r.referred_account_id === accId && r.beneficiary === "referrer");
    return c.json({
      available: true, kind: who.kind, code, link: referralLink(code), from: referrerName(row),
      preferredSub: who.kind === "sub" && isPreferredSub(rewards || []),
      opens: opens?.n || 0,
      invitesToday: inv?.n || 0, inviteLimit: INVITE_DAILY_LIMIT,
      referred: (referred || []).map((r) => {
        const rw = rewardFor(r.subject_id);
        return { name: r.name, kind: r.kind, joinedAt: r.created_at, via: r.channel,
          paying: !!rw || (r.plan === "scale" && ENTITLED.has(r.subscription_status)),
          reward: rw ? { kind: rw.kind, status: rw.status, amountCents: rw.amount_cents } : null };
      }),
      rewards: (rewards || []).map((r) => ({ id: r.id, kind: r.kind, beneficiary: r.beneficiary,
        status: r.status, amountCents: r.amount_cents, referredName: r.referred_name,
        createdAt: r.created_at, paidAt: r.paid_at, appliedAt: r.applied_at,
        waiting: r.status === "pending" && r.error === "no_billing_yet" })),
    });
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
});

// "Get your GCs on SubSub". Email goes from SubSub with the sender's name on
// it and their address as reply-to; a text goes from the sender's OWN phone
// (the browser opens it), so SubSub never texts a stranger on anybody's
// behalf and never sees the number -- those are only counted. Rate-limited per
// code per day, and an address emailed in the last month is not emailed again.
//
// An address that already belongs to somebody on SubSub is not emailed, and
// the reply does not say so: it reads exactly like a sent invite, because an
// invite screen that answered "already on SubSub" would be a way to ask which
// of a list of addresses is here.
app.post("/api/referrals/invites", requireRole("admin", "pm", "contractor"), async (c) => {
  const { userId } = c.get("auth");
  const who = await referrerForSeat(c);
  if (!who) return c.json({ error: "forbidden" }, 403);
  const b = await c.req.json().catch(() => ({}));
  const emails = [...new Set((Array.isArray(b.emails) ? b.emails : [])
    .map((e) => String(e || "").trim().toLowerCase()).filter(Boolean))].slice(0, INVITE_DAILY_LIMIT);
  const sms = Math.max(0, Math.min(INVITE_DAILY_LIMIT, Math.floor(Number(b.sms) || 0)));
  if (!emails.length && !sms) return c.json({ error: "nothing_to_send" }, 400);
  try {
    const code = await ensureReferralCode(c.env, who);
    const row = await referralCodeRow(c.env, code);
    const today = new Date().toISOString().slice(0, 10);
    const used = (await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM referral_invites WHERE code = ? AND created_at >= ?`).bind(code, today).first())?.n || 0;
    let room = INVITE_DAILY_LIMIT - used;
    const me = await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(userId).first();
    const link = referralLink(code);
    const mail = inviteEmail({ fromName: me?.name, company: referrerName(row), link });
    let sent = 0, texted = 0;
    const skipped = [];
    const since = new Date(Date.now() - INVITE_REPEAT_DAYS * 86400000).toISOString().slice(0, 10);
    for (const to of emails) {
      if (!validInviteEmail(to)) { skipped.push({ email: to, reason: "invalid" }); continue; }
      if (room <= 0) { skipped.push({ email: to, reason: "limit" }); continue; }
      const recent = await c.env.DB.prepare(
        `SELECT 1 AS yes FROM referral_invites WHERE code = ? AND to_email = ? AND created_at >= ?`
      ).bind(code, to, since).first();
      if (recent) { skipped.push({ email: to, reason: "recent" }); continue; }
      const id = uid();
      await c.env.DB.prepare(
        `INSERT INTO referral_invites (id, code, sent_by, channel, to_email) VALUES (?, ?, ?, 'email', ?)`
      ).bind(id, code, userId || null, to).run();
      room--; sent++;
      const known = await c.env.DB.prepare(`SELECT 1 AS yes FROM users WHERE lower(email) = ?`).bind(to).first();
      if (known) continue;
      const res = await sendEmail(c.env, { to, subject: mail.subject, text: mail.text, replyTo: me?.email || undefined });
      await logMail(c.env, { accountId: c.get("auth").accountId, companyId: who.companyId || null, to,
        kind: "referral_invite", subject: mail.subject, result: res, sentBy: userId }).catch(() => {});
      if (res?.ok) await c.env.DB.prepare(`UPDATE referral_invites SET emailed = 1 WHERE id = ?`).bind(id).run();
    }
    for (let i = 0; i < sms && room > 0; i++) {
      await c.env.DB.prepare(
        `INSERT INTO referral_invites (id, code, sent_by, channel) VALUES (?, ?, ?, 'sms')`
      ).bind(uid(), code, userId || null).run();
      room--; texted++;
    }
    return c.json({ ok: true, sent, texted, skipped, left: Math.max(0, room) });
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
});

// ---- the console ------------------------------------------------------------

// THE LEDGER, every reward with who earned it and from whom, plus the
// referrers bringing the most accounts in. Staff route.
app.get("/api/platform/referrals", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  try {
    const { results: rewards } = await c.env.DB.prepare(
      `SELECT r.*, ra.name AS referred_name, ra.kind AS referred_kind,
              ba.name AS beneficiary_account_name, bc.company AS beneficiary_company_name,
              bc.email AS beneficiary_company_email,
              au.name AS approved_by_name, pu.name AS paid_by_name
         FROM referral_rewards r
         LEFT JOIN accounts ra ON ra.id = r.referred_account_id
         LEFT JOIN accounts ba ON ba.id = r.beneficiary_account_id
         LEFT JOIN companies bc ON bc.id = r.beneficiary_company_id
         LEFT JOIN users au ON au.id = r.approved_by
         LEFT JOIN users pu ON pu.id = r.paid_by
        ORDER BY r.created_at DESC LIMIT 500`).all();
    const { results: top } = await c.env.DB.prepare(
      `SELECT rc.code, rc.kind, a.name AS account_name, co.company AS company_name,
              (SELECT COUNT(*) FROM referral_attributions x WHERE x.code = rc.code AND x.subject_kind = 'account') AS referred,
              (SELECT COUNT(*) FROM referral_rewards y WHERE y.code = rc.code AND y.beneficiary = 'referrer' AND y.status <> 'void') AS paying,
              (SELECT COUNT(*) FROM referral_touches t WHERE t.code = rc.code) AS opens,
              (SELECT COUNT(*) FROM referral_invites v WHERE v.code = rc.code) AS invites
         FROM referral_codes rc
         LEFT JOIN accounts a ON a.id = rc.account_id
         LEFT JOIN companies co ON co.id = rc.company_id
        ORDER BY referred DESC, paying DESC, opens DESC LIMIT 50`).all();
    return c.json({
      rewards: (rewards || []).map((r) => ({
        id: r.id, kind: r.kind, beneficiary: r.beneficiary, status: r.status, amountCents: r.amount_cents,
        code: r.code, referredAccountId: r.referred_account_id, referredName: r.referred_name, referredKind: r.referred_kind,
        to: r.beneficiary_company_name || r.beneficiary_account_name || null,
        toEmail: r.beneficiary_company_email || null,
        reference: r.reference, note: r.note, error: r.error, processorRef: r.processor_ref,
        createdAt: r.created_at, approvedAt: r.approved_at, approvedBy: r.approved_by_name,
        paidAt: r.paid_at, paidBy: r.paid_by_name, appliedAt: r.applied_at, voidedAt: r.voided_at,
      })),
      referrers: (top || []).filter((t) => t.referred > 0 || t.opens > 0 || t.invites > 0).map((t) => ({
        code: t.code, kind: t.kind, name: t.kind === "sub" ? t.company_name : t.account_name,
        referred: t.referred, paying: t.paying, opens: t.opens, invites: t.invites })),
    });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ rewards: [], referrers: [], migration });
  }
});

// Approve, mark paid, void, or retry a credit. Money, so finance access only,
// and every move is on the platform log with who made it. Marking paid needs a
// reference -- a check number, a transfer id -- because "how was it paid" is
// the question that gets asked; voiding needs a reason.
app.post("/api/platform/referrals/rewards/:id", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  if (!staff.finance) return c.json({ error: "finance_only" }, 403);
  const b = await c.req.json().catch(() => ({}));
  const action = String(b.action || "");
  const reference = String(b.reference || "").trim().slice(0, 200);
  const note = String(b.note || "").trim().slice(0, 500);
  try {
    const r = await c.env.DB.prepare(`SELECT * FROM referral_rewards WHERE id = ?`).bind(c.req.param("id")).first();
    if (!r) return c.json({ error: "not_found" }, 404);
    if (action === "retry") {
      if (r.kind !== "gc_credit" || r.status !== "pending") return c.json({ error: "wrong_status" }, 409);
      const ok = await applyReferralCredit(c.env, r);
      const now = await c.env.DB.prepare(`SELECT status, error FROM referral_rewards WHERE id = ?`).bind(r.id).first();
      return c.json({ ok, status: now?.status, error: now?.error || null });
    }
    const move = rewardMove(r, action);
    if (!move.ok) return c.json({ error: move.error }, 409);
    if (action === "pay" && !reference) return c.json({ error: "reference_required" }, 400);
    if (action === "void" && !note) return c.json({ error: "reason_required" }, 400);
    const sets = {
      approve: [`approved_at = CURRENT_TIMESTAMP, approved_by = ?`, [staff.userId]],
      pay: [`paid_at = CURRENT_TIMESTAMP, paid_by = ?, reference = ?`, [staff.userId, reference]],
      void: [`voided_at = CURRENT_TIMESTAMP, voided_by = ?, note = ?`, [staff.userId, note]],
    }[action];
    const res = await c.env.DB.prepare(
      `UPDATE referral_rewards SET status = ?, ${sets[0]} WHERE id = ? AND status = ?`
    ).bind(move.to, ...sets[1], r.id, r.status).run();
    if ((res?.meta?.changes || 0) === 0) return c.json({ error: "wrong_status" }, 409);
    await auditPlatform(c.env, staff, null, `referral.reward_${action}`,
      `Referral reward ${action}: ${formatCentsPlain(r.amount_cents)} (${r.kind})`,
      { rewardId: r.id, from: r.status, to: move.to, reference: reference || null, note: note || null });
    return c.json({ ok: true, status: move.to });
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
});

// NEW HIRING ACCOUNTS PER EXISTING ONE, BY WEEK AND BY METRO. The arithmetic
// is acquisitionByWeek in shared/referral.js; this is the read. Where an
// account is comes off its company row, and for the kinds that have none off
// its commonest building city -- the same order accountPlace uses -- and
// otherwise it says Unknown rather than guess.
app.get("/api/platform/referrals/acquisition", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  const weeks = Math.max(4, Math.min(52, Math.floor(Number(c.req.query("weeks")) || 12)));
  const { results: accounts } = await c.env.DB.prepare(
    `SELECT a.id, a.kind, a.created_at,
            COALESCE(NULLIF(TRIM(co.city), ''),
              (SELECT p.city FROM properties p WHERE p.account_id = a.id AND TRIM(COALESCE(p.city, '')) <> ''
                GROUP BY lower(TRIM(p.city)) ORDER BY COUNT(*) DESC, lower(TRIM(p.city)) LIMIT 1)) AS city,
            COALESCE(NULLIF(TRIM(co.state), ''),
              (SELECT p.state FROM properties p WHERE p.account_id = a.id AND TRIM(COALESCE(p.state, '')) <> ''
                GROUP BY upper(TRIM(p.state)) ORDER BY COUNT(*) DESC, upper(TRIM(p.state)) LIMIT 1)) AS state
       FROM accounts a LEFT JOIN companies co ON co.id = a.company_id`).all().catch(async (err) => {
    if (!missingSchema(err)) throw err;
    return c.env.DB.prepare(`SELECT id, kind, created_at, NULL AS city, NULL AS state FROM accounts`).all();
  });
  let attributions = {};
  let migration = null;
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT ra.subject_id, rc.kind FROM referral_attributions ra JOIN referral_codes rc ON rc.code = ra.code
        WHERE ra.subject_kind = 'account'`).all();
    attributions = Object.fromEntries((results || []).map((r) => [r.subject_id, r.kind]));
  } catch (err) {
    migration = missingSchema(err);
    if (!migration) throw err;
  }
  const out = acquisitionByWeek({
    accounts: (accounts || []).map((a) => ({ id: a.id, kind: a.kind, createdAt: a.created_at, city: a.city, state: a.state })),
    attributions, weeks,
  });
  return c.json({ ...out, migration });
});


// ---------------------------------------------------------------------------
// Connecting to a contractor who is already on SubSub
// ---------------------------------------------------------------------------
// The add-a-contractor form has always deduped on the way OUT: type an email
// or a licence that matches a company already here and the server quietly
// reuses that company rather than making a second one. Quietly is the
// problem. Whoever was typing had already filled in the trades, the crews,
// the coverage and the insurance -- all of it already on file, all of it
// discarded -- and the contractor was never told that a new company now had
// their documents.
//
// So the match is surfaced before the typing, and the connection is asked
// for rather than taken. Connecting hands a hiring account that
// contractor's profile, documents, crews and availability; it is not the
// hiring account's to grant.
//
// Two ways in, one mechanism. Either somebody types an address that matches,
// or a contractor shows the QR code in their portal and has it scanned.

// Crockford's alphabet minus the letters people mistype off a screen: no
// I, L, O or U. Ten characters is about 10^15 codes, which is not
// guessable, and it stays short enough to read aloud down a phone when the
// camera will not focus.
const CONNECT_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
function newConnectCode() {
  const bytes = new Uint8Array(10);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => CONNECT_ALPHABET[b % CONNECT_ALPHABET.length]).join("");
}

// A contractor's QR has to work whoever scans it, and the scanner is on
// their own company's address, not this one's -- so it points at the
// canonical app rather than at any account's branded origin.
const connectUrl = (code) => `${APP_ORIGIN}/?connect=${code}`;

// Read it, or mint one. Not backfilled by the migration: a code nobody has
// been told about is just a column, and this is the moment somebody asks
// to see theirs.
async function ensureConnectCode(env, companyId) {
  const row = await env.DB.prepare(`SELECT connect_code FROM companies WHERE id = ?`).bind(companyId).first();
  if (!row) return null;
  if (row.connect_code) return row.connect_code;
  for (let attempt = 0; attempt < 6; attempt++) {
    const code = newConnectCode();
    try {
      await env.DB.prepare(`UPDATE companies SET connect_code = ? WHERE id = ?`).bind(code, companyId).run();
      return code;
    } catch (err) {
      // The unique index doing its job. One in 10^15 is not the reason this
      // loop exists; a rotate racing a mint is.
      if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
    }
  }
  throw new Error("could not mint a connect code");
}

// The company row an account IS.
//
// A general contractor is a company that happens to hire other companies.
// Until 031 the two were separate kinds of thing and only a subcontractor
// had a company row, so a general contractor could not be looked up, could
// not be asked to connect, and had no QR code to show -- the one question
// somebody asked about their own account that the app had no answer to.
//
// 031 backfills one for every account. This is the safety net for an
// account created against a database that has not had it run yet, and for
// one created by a code path that forgot: derived id, so it is the same row
// every time and never a second one.
const ownCompanyId = (accountId) => `cmp_own_${accountId}`;
async function ensureAccountCompany(env, accountId) {
  let a;
  try {
    a = await env.DB.prepare(`SELECT id, name, kind, company_id FROM accounts WHERE id = ?`)
      .bind(accountId).first();
  } catch (err) {
    // No company_id column yet: this database has not had 031 run.
    if (missingSchema(err)) return null;
    throw err;
  }
  if (!a) return null;
  // Only a general contractor. The row exists to be hired; the other kinds
  // hire and are not hired, and a dormant listing for a landlord is one
  // careless join from a landlord on somebody's subcontractor roster.
  if (!HIREABLE_KINDS.includes(a.kind)) return null;
  if (a.company_id) return a.company_id;
  const id = ownCompanyId(accountId);
  try {
    await env.DB.prepare(`INSERT OR IGNORE INTO companies (id, company) VALUES (?, ?)`)
      .bind(id, a.name).run();
    await env.DB.prepare(`UPDATE accounts SET company_id = ? WHERE id = ? AND company_id IS NULL`)
      .bind(id, accountId).run();
  } catch (err) {
    // The column does not exist yet: this database has not had 031 run.
    // Say so the way every other route does rather than 500.
    if (missingSchema(err)) return null;
    throw err;
  }
  return id;
}

// Whether anybody can actually answer for this company. A company row is
// not the same thing as a contractor on SubSub: most of them were typed in
// by a hiring account and have no login behind them at all. Asking one of
// those to connect would be a request nobody could ever accept, so the
// lookup does not offer it -- the ordinary add-them-yourself path still
// works exactly as before.
// Is this company offering to be hired?
//
// Being findable used to be a side effect of filling a profile in: an email,
// a mobile or a licence on the row, and any account typing one of those whole
// values could ask you to connect. Right for a subcontractor, who is here to
// be hired. Wrong for a general contractor, who signed up to run a roster and
// may have no wish to work under anybody -- and was never asked.
//
// `open_to_hire` NULL means NOT ANSWERED, never "no", and the effective
// default is OPEN for everybody.
//
// The first version defaulted a general contractor to closed, on the reasoning
// that somebody who signed up to run a roster is not offering to work under
// anybody. That was the wrong way round. Since 031 every hireable account HAS
// a company row precisely so it can be hired, the whole growth loop is a
// contractor being found by somebody who already holds their address, and a
// general contractor who takes overflow work from another general contractor
// is the ordinary case rather than the odd one. Defaulting them out meant the
// product quietly did not work for them until they found a switch nobody told
// them about.
//
// So: open unless they say otherwise, which is what the column is for. Closing
// it is one tap and it is theirs to make.
async function openToHire(env, companyId) {
  let row;
  try {
    row = await env.DB.prepare(
      `SELECT co.open_to_hire AS flag, ac.kind AS kind
         FROM companies co LEFT JOIN accounts ac ON ac.company_id = co.id
        WHERE co.id = ?`
    ).bind(companyId).first();
  } catch (err) {
    // No column yet: a database without 047 behaves exactly as it did before,
    // which is open. Nothing silently disappears off a lookup mid-migration.
    if (missingSchema(err)) return true;
    throw err;
  }
  if (!row) return false;
  if (row.flag !== null && row.flag !== undefined) return !!row.flag;
  return true;
}

async function companyHasLogin(env, companyId) {
  const row = await env.DB.prepare(
    `SELECT 1 AS yes FROM memberships WHERE company_id = ? AND role = 'contractor' LIMIT 1`
  ).bind(companyId).first();
  if (row) return true;
  // Or it is an account's own company, and the people who can answer for it
  // are the people who run that account. Without this an account could be
  // found by the lookup and then refused as "nobody to ask", which is the
  // worst of both: visible and unreachable.
  try {
    const own = await env.DB.prepare(
      `SELECT 1 AS yes FROM memberships m JOIN accounts a ON a.id = m.account_id
        WHERE a.company_id = ? AND m.role IN ('admin', 'pm') LIMIT 1`
    ).bind(companyId).first();
    return !!own;
  } catch (err) {
    // Before 031 there is no accounts.company_id, and the old answer -- a
    // contractor seat or nothing -- is the right one.
    if (missingSchema(err)) return false;
    throw err;
  }
}

// Is this company the caller's own account? Its own question because it is
// asked from three places and the column may not exist yet.
async function isOwnCompany(env, accountId, companyId) {
  try {
    const a = await env.DB.prepare(`SELECT company_id FROM accounts WHERE id = ?`).bind(accountId).first();
    return !!a?.company_id && a.company_id === companyId;
  } catch (err) {
    if (missingSchema(err)) return false;
    throw err;
  }
}

// Which company this seat speaks for. A contractor seat speaks for the
// company it was seated with; an admin or a project manager speaks for the
// account they run, which is a company of its own since 031 -- but only if
// that account is a general contractor.
async function seatCompany(c) {
  const { role, companyId, accountId } = c.get("auth");
  if (role === "contractor" && companyId) return companyId;
  if ((role === "admin" || role === "pm") && accountId) return await ensureAccountCompany(c.env, accountId);
  return null;
}

// Why a seat has no company, for the routes that should say so rather than
// answer "forbidden" to a property manager who was never going to have one.
async function noCompanyReason(c) {
  const { accountId } = c.get("auth");
  if (!accountId) return "forbidden";
  try {
    const a = await c.env.DB.prepare(`SELECT kind, company_id FROM accounts WHERE id = ?`)
      .bind(accountId).first();
    if (a && !HIREABLE_KINDS.includes(a.kind)) return "not_hireable";
    if (a && !a.company_id) return "migration_needed";
  } catch (err) {
    if (missingSchema(err)) return "migration_needed";
    throw err;
  }
  return "forbidden";
}

// What a hiring account is allowed to learn about a company it does not
// work with: the name, roughly where they are, and what they do. Not the
// email it was found by, not the phone, not a document, not who else they
// work for. Enough to recognise the company standing in front of you and
// nothing that would make this worth scraping.
// What one lookup is allowed to tell you about a company you have no
// relationship with.
//
// SubSub is not a directory. It is for running the subcontractors you
// already have and for adding the ones you meet, so a lookup exists to stop
// you sending a "set up an account" invite to somebody who has one -- not to
// tell you about them. You already typed the address, the mobile or the
// licence; what you need back is which company it is, so you do not ask the
// wrong outfit to connect.
//
// So a stranger's match carries the company and roughly where they are, and
// nothing else. Their contact's name is a person, and you typed the address
// so you know who you were writing to. The licence number was going out with
// every match and NOTHING has ever read it -- a field about somebody you have
// never worked with, leaving the server for no reason at all.
//
// `full` is for the two cases where the company is not a stranger: one of
// your own contractors, where every one of these fields is already on their
// card, and a code somebody showed you in person, which is them choosing to
// identify themselves.
const connectMatchToJs = (co, { engaged, pending, full = false }) => ({
  companyId: co.id,
  company: co.company,
  contact: (full || engaged) ? (co.contact || null) : null,
  where: [co.city, co.state].filter(Boolean).join(", ") || null,
  engaged, pending,
});

const connectRequestToJs = (r) => ({
  id: r.id, status: r.status, via: r.via,
  companyId: r.company_id, company: r.company_name || null,
  contact: r.contact || null,
  where: [r.city, r.state].filter(Boolean).join(", ") || null,
  accountId: r.account_id, account: r.account_name || null,
  message: r.message || null,
  createdAt: r.created_at, respondedAt: r.responded_at || null,
});

// Is this company already on SubSub? Admin and PM only, and rate limited:
// it answers about an address the caller typed, which is exactly the shape
// of thing somebody would otherwise feed a list into.
//
// It tells them nothing they could not already learn by adding the
// contractor and reading `reused` off the answer -- that has been true
// since the dedupe was written. What is new is that they learn it BEFORE
// typing a profile that would have been thrown away.
// The weather where this account is, for the line at the top of the dashboard.
//
// Server-side rather than from the browser, for three reasons. The call is
// cacheable once for everybody on the account instead of once per tab; the
// browser never talks to a third party, so nothing about who is looking at
// SubSub leaves our origin; and an outbound host that goes down cannot take a
// dashboard with it.
//
// Open-Meteo: no key, no account, and it asks for a latitude and a longitude
// rather than an address, so what leaves here is a town and a state -- not a
// customer, not a person, not a building.
//
// It is DECORATION. Every failure answers {} and the screen shows a greeting
// with no chip. Nothing on this route may ever be the reason a dashboard does
// not load.
const weatherCache = new Map();

// Where an account IS, for the one purpose of naming a town to a weather API.
//
// This read `accounts.company_id -> companies.city` and nothing else, which is
// a column only HIREABLE kinds have: 031 mints a company row for a general
// contractor and a subcontractor, and CHECK.sql's m031_others_with forbids one
// for anybody else. So a property manager, a building owner and a portfolio
// manager did not get a failed lookup -- they got a join that could never
// match, and answered `{}` every time. Three of the five kinds, silently, and
// silently is the trap: every failure here answers `{}` on purpose, so "no
// weather" is indistinguishable from "no weather YET" and nothing ever said
// the query was wrong. The browser tests all drove a subcontractor.
//
// Their address is their BUILDINGS, which is the more honest answer for them
// anyway: a managing agent's weather is the weather where the work is. Most
// common town across the portfolio, tie-broken by name so one account always
// produces one cache key. OWNED as well as operated, because an owner who has
// appointed a manager still watches those buildings and watching them is the
// entire reason they are here.
//
// The general rule this is an instance of, and it is the one this file keeps
// relearning: `company_id` is what a hireable account has, not what an account
// has. Anything reading it to answer a question about the ACCOUNT is answering
// it for two kinds out of five.
async function accountPlace(env, accountId, propertyIds = null) {
  // 072. A seat narrowed to named buildings -- a tenant, a guest owner, a
  // scoped manager -- is asking about THEIR building, not the account's
  // commonest town. A tenant in Olympia on a Tacoma agent's books was told
  // Tacoma's weather, and "is it raining at home" is the one question this
  // line exists to answer. Their buildings only, the same tie-break.
  if (Array.isArray(propertyIds)) {
    if (!propertyIds.length) return null;
    try {
      const row = await env.DB.prepare(
        `SELECT city, state, COUNT(*) AS n, MIN(NULLIF(TRIM(zip), '')) AS zip
           FROM properties
          WHERE id IN (${propertyIds.map(() => "?").join(",")})
            AND city IS NOT NULL AND TRIM(city) <> ''
          GROUP BY lower(TRIM(city)), lower(TRIM(COALESCE(state, '')))
          ORDER BY n DESC, lower(TRIM(city)) ASC
          LIMIT 1`
      ).bind(...propertyIds).first();
      const city = String(row?.city || "").trim();
      // The ZIP rides along: it is what tells Ruston, WA from Ruston, LA when
      // the geocoder's list holds both.
      if (city) return { city, state: String(row.state || "").trim(), zip: String(row.zip || "").trim().slice(0, 5) };
      // A building typed in with a street and a ZIP and no town is common,
      // and a tenant's weather is the one place that cannot fall back to the
      // account's other buildings -- that would be somebody else's weather.
      // So the ZIP stands in, and it is the building's own.
      const z = await env.DB.prepare(
        `SELECT zip FROM properties
          WHERE id IN (${propertyIds.map(() => "?").join(",")})
            AND zip IS NOT NULL AND TRIM(zip) <> ''
          ORDER BY id LIMIT 1`
      ).bind(...propertyIds).first();
      const zip = String(z?.zip || "").trim().slice(0, 5);
      return /^\d{5}$/.test(zip) ? { city: "", state: "", zip } : null;
    } catch (err) {
      if (!missingSchema(err)) throw err;
      return null;
    }
  }
  // What they said about themselves, when there is a row that can hold it.
  try {
    const co = await env.DB.prepare(
      `SELECT co.city AS city, co.state AS state
         FROM accounts ac JOIN companies co ON co.id = ac.company_id
        WHERE ac.id = ?`
    ).bind(accountId).first();
    const city = String(co?.city || "").trim();
    if (city) return { city, state: String(co.state || "").trim() };
  } catch (err) {
    // A database without 031 has no company_id at all. Fall through to the
    // buildings rather than taking the dashboard's greeting with it.
    if (!missingSchema(err)) throw err;
  }

  // Otherwise the portfolio.
  try {
    const row = await env.DB.prepare(
      `SELECT city, state, COUNT(*) AS n
         FROM properties
        WHERE (account_id = ? OR owner_account_id = ?)
          AND city IS NOT NULL AND TRIM(city) <> ''
        GROUP BY lower(TRIM(city)), lower(TRIM(COALESCE(state, '')))
        ORDER BY n DESC, lower(TRIM(city)) ASC
        LIMIT 1`
    ).bind(accountId, accountId).first();
    const city = String(row?.city || "").trim();
    if (city) return { city, state: String(row.state || "").trim() };
  } catch (err) {
    // owner_account_id is 039.
    if (!missingSchema(err)) throw err;
  }

  return null;
}

app.get("/api/weather", async (c) => {
  const { accountId, propertyIds } = c.get("auth");
  try {
    const where = await accountPlace(c.env, accountId, propertyIds || null);
    // No address, no weather, and no apology: a dashboard that says "we do not
    // know where you are" has spent a line to say nothing.
    if (!where) return c.json({});
    const { city, state, zip = "" } = where;

    const key = city ? `${city.toLowerCase()}|${state.toLowerCase()}|${zip}` : `zip|${zip}`;
    const hit = weatherCache.get(key);
    if (hit && Date.now() - hit.at < WEATHER_TTL_MIN * 60_000) return c.json(hit.value);

    // The geocoder takes no state filter -- an `admin1` parameter is silently
    // ignored, which is how Ruston, WA got Ruston, LOUISIANA's weather. So
    // ask for several US matches and choose among them (shared/geopick.js),
    // then try the ZIP itself if the town gave nothing in the right state.
    const geocode = (name) => fetch(
      `https://geocoding-api.open-meteo.com/v1/search?count=20&language=en&format=json&countryCode=US`
      + `&name=${encodeURIComponent(name)}`
    ).then((r) => r.json()).catch(() => null);
    let place = null;
    if (city) place = pickPlace((await geocode(city))?.results, { city, state, zip });
    if (!place && /^\d{5}$/.test(zip)) place = pickPlace((await geocode(zip))?.results, { state, zip });
    if (!place) { weatherCache.set(key, { at: Date.now(), value: {} }); return c.json({}); }

    const wx = await fetch(
      `https://api.open-meteo.com/v1/forecast?current=temperature_2m,weather_code`
      // 072. Today's high and low, for the tenant's weather card. Same call,
      // so it costs nothing more; absent from a reply, the card shows only now.
      + `&daily=temperature_2m_max,temperature_2m_min&forecast_days=1&timezone=auto`
      + `&temperature_unit=fahrenheit&latitude=${place.latitude}&longitude=${place.longitude}`
    ).then((r) => r.json()).catch(() => null);
    const cur = wx?.current;
    if (!cur || typeof cur.temperature_2m !== "number" || weatherLabel(cur.weather_code) === null) {
      weatherCache.set(key, { at: Date.now(), value: {} });
      return c.json({});
    }

    const value = { tempF: cur.temperature_2m, code: cur.weather_code, place: city || place.name || zip };
    const hi = wx?.daily?.temperature_2m_max?.[0], lo = wx?.daily?.temperature_2m_min?.[0];
    if (typeof hi === "number" && typeof lo === "number") { value.hiF = hi; value.loF = lo; }
    weatherCache.set(key, { at: Date.now(), value });
    return c.json(value);
  } catch (err) {
    console.warn("[weather] not read:", err?.message || err);
    return c.json({});
  }
});

app.get("/api/connect/lookup", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const q = c.req.query();
  const email = String(q.email || "").trim().toLowerCase();
  const license = String(q.license || "").trim().toUpperCase();
  const phone = normalizePhone(q.phone) || "";
  if (!email && !license && !phone) return c.json({ error: "nothing_to_look_up" }, 400);
  // Whole values only. No prefixes, no LIKE, nothing that turns this into a
  // directory somebody can walk.
  if (email && !EMAIL_RE.test(email)) return c.json({ found: false });

  const limit = await rateLimit(c.env, "connect-lookup", accountId, { limit: 60, windowMinutes: 10 });
  if (!limit.ok) return c.json({ error: "slow_down" }, 429);

  let co = null;
  if (license) {
    co = await c.env.DB.prepare(`SELECT * FROM companies WHERE UPPER(TRIM(license)) = ?`).bind(license).first();
  }
  if (!co && email) {
    co = await c.env.DB.prepare(`SELECT * FROM companies WHERE lower(email) = ?`).bind(email).first();
  }
  if (!co && phone) {
    // normalizePhone() is what every write goes through, so the column holds
    // exactly one spelling of a number and this is a plain equality rather
    // than a scan with the punctuation stripped off in SQL.
    co = await c.env.DB.prepare(`SELECT * FROM companies WHERE phone = ?`).bind(phone).first();
  }
  if (!co) return c.json({ found: false });

  // Yourself. Since 031 an account is a company, so the address on your own
  // profile is findable by you -- and a form offering to connect you to
  // yourself is a form that has not understood the question.
  if (await isOwnCompany(c.env, accountId, co.id)) {
    return c.json({ found: false, reason: "own_company" });
  }

  // Their own contractor, first and regardless of anything else. Most
  // company rows here were typed in by a hiring account and have no login
  // behind them, and the login check below quite rightly refuses to offer
  // those for connecting -- but applying it first meant somebody typing the
  // address of a contractor ALREADY ON THEIR OWN LIST was told "nobody on
  // SubSub matches that". Nothing is being disclosed here that the account
  // did not type in itself.
  const engaged = !!(await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, co.id).first());
  if (engaged) return c.json({ found: true, match: connectMatchToJs(co, { engaged: true, pending: false }) });

  // Somebody else's company row with nobody behind it. Asking it to connect
  // would be a request no one could ever accept, so it is not offered and
  // the ordinary add-them-yourself path carries on as it always has.
  if (!(await companyHasLogin(c.env, co.id))) return c.json({ found: false, reason: "no_account" });

  // Not offering to be hired, which is a different answer from "nobody is
  // behind this row".
  //
  // It answers like an address nobody here has ever seen -- a bare
  // `found: false`, no reason -- and NOT like `no_account`. `no_account` says
  // "this address is on SubSub and nobody can answer for it", which is both
  // untrue here and a fact about them that a stranger typing addresses has no
  // business collecting. Not findable is not findable.
  if (!(await openToHire(c.env, co.id))) return c.json({ found: false });

  const pending = !!(await c.env.DB.prepare(
    `SELECT 1 AS yes FROM connect_requests WHERE account_id = ? AND company_id = ? AND status = 'pending'`
  ).bind(accountId, co.id).first());
  return c.json({ found: true, match: connectMatchToJs(co, { engaged: false, pending }) });
});

// The same question, asked by a scanned code rather than by an address.
// Separate from the lookup above because a code is a thing somebody chose
// to show you, so it does not need the address that found it kept secret.
app.get("/api/connect/code/:code", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const code = String(c.req.param("code") || "").trim().toUpperCase();
  if (!/^[0-9A-Z]{10}$/.test(code)) return c.json({ found: false });
  const limit = await rateLimit(c.env, "connect-code", accountId, { limit: 60, windowMinutes: 10 });
  if (!limit.ok) return c.json({ error: "slow_down" }, 429);

  const co = await c.env.DB.prepare(`SELECT * FROM companies WHERE connect_code = ?`).bind(code).first();
  if (!co) return c.json({ found: false });
  if (await isOwnCompany(c.env, accountId, co.id)) return c.json({ found: false, reason: "own_company" });
  const engaged = !!(await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, co.id).first());
  const pending = !!(await c.env.DB.prepare(
    `SELECT 1 AS yes FROM connect_requests WHERE account_id = ? AND company_id = ? AND status = 'pending'`
  ).bind(accountId, co.id).first());
  return c.json({ found: true, match: connectMatchToJs(co, { engaged, pending, full: true }) });
});

// Ask to connect. By company id (from the lookup) or by code (from a scan).
app.post("/api/connect-requests", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const code = String(b.code || "").trim().toUpperCase();
  const message = String(b.message || "").trim().slice(0, 500) || null;

  const co = code
    ? await c.env.DB.prepare(`SELECT * FROM companies WHERE connect_code = ?`).bind(code).first()
    : await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(String(b.companyId || "")).first();
  if (!co) return c.json({ error: "not_found" }, 404);

  // Same order as the lookup: already ours beats anything else, or a
  // contractor on our own list reads as a stranger with no account.
  const engaged = await c.env.DB.prepare(
    `SELECT id FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, co.id).first();
  if (engaged) return c.json({ error: "already_engaged", companyId: co.id }, 409);
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  // Since 031 an account is a company, which means an account can find
  // itself -- scan your own QR, or type in the address on your own profile.
  // Hiring yourself would seat your own team in your own account as
  // contractors and put you on your own roster.
  if (account?.company_id && account.company_id === co.id) {
    return c.json({ error: "own_company" }, 409);
  }
  if (!(await companyHasLogin(c.env, co.id))) return c.json({ error: "no_account" }, 409);

  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO connect_requests (id, account_id, company_id, via, requested_by, message)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, co.id, code ? "code" : "lookup", userId, message).run();
  } catch (err) {
    // The partial unique index. Asking twice is not an error worth a 500 --
    // it means somebody pressed it twice, or two people in the same office
    // did.
    if (/UNIQUE constraint failed/i.test(String(err?.message || err))) {
      return c.json({ error: "already_requested", companyId: co.id }, 409);
    }
    throw err;
  }

  // Tell them. A request sitting in a portal nobody has open is the same as
  // no request, and this trade answers a text.
  const link = `${APP_ORIGIN}/?connect-request=${id}`;
  const mail = connectRequestEmail({ account, company: co, message, link });
  let mailResult = null, smsResult = null;
  if (co.email) {
    mailResult = await sendEmail(c.env, { to: co.email, subject: mail.subject, text: mail.text, html: mail.html });
    await logMail(c.env, { accountId, companyId: co.id, to: co.email, kind: "connect_request",
      subject: mail.subject, result: mailResult, sentBy: userId });
  }
  if (co.phone) {
    smsResult = await sendAccountSms(c.env, { accountId, companyId: co.id, to: co.phone,
      kind: "connect_request", body: connectRequestSms({ account, link }) });
  }
  await logActivity(c.env, accountId, userId, "connect_requested",
    `Asked ${co.company} to connect`);

  const row = await c.env.DB.prepare(
    `SELECT cr.*, co.company AS company_name, co.contact, co.city, co.state, a.name AS account_name
       FROM connect_requests cr
       JOIN companies co ON co.id = cr.company_id
       JOIN accounts a ON a.id = cr.account_id
      WHERE cr.id = ?`
  ).bind(id).first();
  return c.json({
    ...connectRequestToJs(row),
    emailed: !!mailResult?.ok, texted: !!smsResult?.ok,
    emailError: co.email && !mailResult?.ok ? (mailResult?.error || "send_failed") : null,
    textError: co.phone && !smsResult?.ok ? (smsResult?.error || "send_failed") : null,
  }, 201);
});

// What this account has asked for and not yet had an answer to.
app.get("/api/connect-requests", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const { results } = await c.env.DB.prepare(
    `SELECT cr.*, co.company AS company_name, co.contact, co.city, co.state, a.name AS account_name
       FROM connect_requests cr
       JOIN companies co ON co.id = cr.company_id
       JOIN accounts a ON a.id = cr.account_id
      WHERE cr.account_id = ?
      ORDER BY cr.created_at DESC LIMIT 100`
  ).bind(accountId).all();
  return c.json(results.map(connectRequestToJs));
});

// Take it back. Only while it is still pending -- a declined or accepted
// one is a fact about what happened, not a row to tidy away.
app.delete("/api/connect-requests/:id", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const res = await c.env.DB.prepare(
    `UPDATE connect_requests SET status = 'cancelled', responded_at = CURRENT_TIMESTAMP
      WHERE id = ? AND account_id = ? AND status = 'pending'`
  ).bind(c.req.param("id"), accountId).run();
  if (!res.meta?.changes) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true });
});

// ---- the contractor's side ------------------------------------------------
// Scoped by the seat's own company rather than by the account header: a
// request comes from an account they have no engagement with, so it is not
// an account they can be "in" yet.
// The company this account IS: the details another general contractor sees
// when they look you up, and the ones that make you findable at all.
//
// A backfilled account-company has a name and nothing else, on purpose --
// inventing an address nobody chose and putting it in front of strangers
// is not a migration's business. This is where somebody chooses it.
//
// Admin and project manager only. It is the account's public face, not a
// seat's own contact card.
const myCompanyToJs = (co) => ({
  companyId: co.id,
  company: co.company || "",
  contact: co.contact || "",
  email: co.email || "",
  phone: co.phone || "",
  license: co.license || "",
  ubi: co.ubi || "",
  city: co.city || "",
  state: co.state || "",
  zip: co.zip || "",
  // Where they are willing to work. Same column and same shape the roster
  // uses for everybody else -- named cities, or travel radii from ZIPs -- so
  // an account's own coverage and a contractor they typed in are one record
  // type and not two.
  //
  // NORMALISED, not merely parsed. The column is `TEXT NOT NULL DEFAULT '{}'`,
  // so a company nobody has answered for reads back as `{}` -- which is
  // truthy, so every `coverage || <default>` downstream keeps it, and the
  // panel then indexes into `.cities` on an object that has none. Sending the
  // whole shape is the same rule `inheritedShape` follows for `assignments`:
  // empty, never absent.
  coverage: validCoverage(parseJson(co.coverage, null))
    || { mode: "cities", cities: [], radii: [] },
  // Their crews and the days each one is off. The same column the roster
  // carries for every contractor, so the account's own team and a hiring
  // account read one record. Normalised on the way out as well as in, for the
  // reason coverage is: a row written before validCrews existed must not hand
  // the availability grid a crew with no members array.
  crews: validCrews(parseJson(co.crews, [])) || [],
});

app.get("/api/my-company", requireRole("admin", "pm"), async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) {
    const why = await noCompanyReason(c);
    return why === "not_hireable"
      ? c.json({ error: "not_hireable" }, 409)
      : c.json({ error: "migration_needed", migration: "031_account_company" }, 503);
  }
  const co = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(companyId).first();
  if (!co) return c.json({ error: "not_found" }, 404);
  const code = await ensureConnectCode(c.env, companyId);
  // What it is worth filling in for: the lookup matches on these three and
  // nothing else, so a profile with none of them cannot be found by anybody.
  const findable = !!(co.email || co.phone || co.license);
  // And their own paperwork. A hireable account is asked for the same four
  // documents any other subcontractor is, and until now the only screen that
  // could upload them was the contractor portal -- which an admin does not
  // have, so an account that could be hired had no way to hold a certificate.
  let docs = {};
  try {
    docs = docShapeWithLegacy(await currentDocRows(c.env.DB, companyId), co);
  } catch (err) { if (!missingSchema(err)) throw err; }
  // How many packs this company has sent. A count, not the list -- the
  // set-up checklist needs to know whether the loop has been round once, and
  // the panel that manages shares fetches them properly when it is opened.
  // Tolerant of a database without 041, like everything else that reads it.
  let sharesSent = 0;
  try {
    sharesSent = (await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM doc_shares WHERE company_id = ?`).bind(companyId).first())?.n || 0;
  } catch (err) { if (!missingSchema(err)) throw err; }
  // The switch, as the SERVER works it out -- effective value, not the raw
  // column -- so the browser renders one answer rather than re-deriving the
  // default from the account kind and getting a third opinion.
  const open = await openToHire(c.env, companyId);
  return c.json({ ...myCompanyToJs(co), findable, code,
    openToHire: open, openAnswered: co.open_to_hire !== null && co.open_to_hire !== undefined,
    url: code ? connectUrl(code) : null, docs, sharesSent });
});

app.patch("/api/my-company", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const companyId = await seatCompany(c);
  if (!companyId) {
    const why = await noCompanyReason(c);
    return why === "not_hireable"
      ? c.json({ error: "not_hireable" }, 409)
      : c.json({ error: "migration_needed", migration: "031_account_company" }, 503);
  }
  const b = await c.req.json().catch(() => ({}));
  const str = (v, n) => v === undefined ? undefined : String(v || "").trim().slice(0, n) || null;

  const email = str(b.email, 200);
  if (email && !EMAIL_RE.test(email)) return c.json({ error: "invalid_email" }, 400);
  const phoneIn = str(b.phone, 40);
  const phone = phoneIn === undefined ? undefined : (phoneIn ? normalizePhone(phoneIn) : null);
  if (phoneIn && !phone) return c.json({ error: "invalid_phone" }, 400);
  const license = str(b.license, 60);
  // The licence column is the dedupe key across the whole table, so the
  // clash here is a real one: somebody else already holds this number.
  // Telling them that is better than a 500 from the unique index.
  if (license) {
    const taken = await c.env.DB.prepare(
      `SELECT id FROM companies WHERE license = ? AND id <> ?`).bind(license, companyId).first();
    if (taken) return c.json({ error: "license_taken" }, 409);
  }

  const fields = {
    company: str(b.company, 200), contact: str(b.contact, 200),
    email, phone, license, ubi: str(b.ubi, 40),
    city: str(b.city, 120),
    state: b.state === undefined ? undefined : normalizeState(b.state),
    zip: str(b.zip, 20),
  };
  // The switch. Its own write, because it is the one field here that can be
  // sent alone -- flipping it must not require a whole profile, and must not
  // trip "nothing_to_change" or "name_required" on the way.
  // Coverage, on its own like the switch: it is edited by its own panel and
  // must not need a whole profile sent with it.
  if (b.coverage !== undefined) {
    const cov = validCoverage(b.coverage);
    if (!cov) return c.json({ error: "invalid_coverage" }, 400);
    await c.env.DB.prepare(`UPDATE companies SET coverage = ? WHERE id = ?`)
      .bind(JSON.stringify(cov), companyId).run();
  }

  // Crews, and with them every crew's days off. Their own write for the
  // reason coverage has one: the availability grid saves a tap at a time and
  // must not need a whole profile sent with it. Checked on the way in, because
  // this lands on the shared row every hiring account's roster reads.
  if (b.crews !== undefined) {
    const crews = validCrews(b.crews);
    if (!crews) return c.json({ error: "invalid_crews" }, 400);
    await c.env.DB.prepare(`UPDATE companies SET crews = ? WHERE id = ?`)
      .bind(JSON.stringify(crews), companyId).run();
  }

  if (b.openToHire !== undefined) {
    try {
      await c.env.DB.prepare(`UPDATE companies SET open_to_hire = ? WHERE id = ?`)
        .bind(b.openToHire ? 1 : 0, companyId).run();
      await logEvent(c.env, accountId, userId,
        b.openToHire ? "company.open_to_hire" : "company.closed_to_hire", companyId, {});
    } catch (err) {
      if (missingSchema(err)) return c.json({ error: "migration_needed", migration: "047_open_to_hire" }, 503);
      throw err;
    }
  }

  const set = Object.entries(fields).filter(([, v]) => v !== undefined);
  if (!set.length) {
    // Answering only the switch is a complete request, not an empty one.
    if (b.openToHire !== undefined || b.coverage !== undefined || b.crews !== undefined) {
      const co = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(companyId).first();
      return c.json({ ok: true, ...myCompanyToJs(co) });
    }
    return c.json({ error: "nothing_to_change" }, 400);
  }
  // A company row with no name is not a thing anybody can be shown.
  if (fields.company === null) return c.json({ error: "name_required" }, 400);

  await c.env.DB.prepare(
    `UPDATE companies SET ${set.map(([k]) => `${k} = ?`).join(", ")} WHERE id = ?`
  ).bind(...set.map(([, v]) => v), companyId).run();
  await logActivity(c.env, accountId, userId, "company_profile",
    "Updated the company profile other contractors see");

  const co = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(companyId).first();
  const code = await ensureConnectCode(c.env, companyId);
  return c.json({ ...myCompanyToJs(co),
    findable: !!(co.email || co.phone || co.license), code, url: code ? connectUrl(code) : null });
});

// Their code, and the URL a QR of it should carry.
app.get("/api/connect/code", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  const code = await ensureConnectCode(c.env, companyId);
  if (!code) return c.json({ error: "not_found" }, 404);
  return c.json({ code, url: connectUrl(code) });
});

// Rotate it. A code is a standing offer to be asked, and the whole point of
// one printed on a van door is that it gets around -- so it has to be
// possible to stop the old one working.
app.post("/api/connect/code/rotate", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  await c.env.DB.prepare(`UPDATE companies SET connect_code = NULL WHERE id = ?`).bind(companyId).run();
  const code = await ensureConnectCode(c.env, companyId);
  return c.json({ code, url: connectUrl(code) });
});

// Who has asked to work with them.
app.get("/api/my-connect-requests", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: "forbidden" }, 403);
  const { results } = await c.env.DB.prepare(
    `SELECT cr.*, co.company AS company_name, co.contact, co.city, co.state, a.name AS account_name
       FROM connect_requests cr
       JOIN companies co ON co.id = cr.company_id
       JOIN accounts a ON a.id = cr.account_id
      WHERE cr.company_id = ?
      ORDER BY cr.created_at DESC LIMIT 100`
  ).bind(companyId).all();
  return c.json(results.map(connectRequestToJs));
});

// Who is asking, for the account that has to decide.
//
// Accept and Decline with nothing but a name on the card is a decision made
// blind: "they'll be able to send you work orders and see your documents" is
// the consequence, and the question it begs -- who ARE these people -- had no
// answer anywhere on the screen.
//
// This is not a directory and must never become one. Two things keep it from
// being one, and both are structural rather than a matter of care:
//
//   It is keyed by the REQUEST, not by the account. There is no route here
//   that takes an account id and describes it. The only way to see any of
//   this is for that account to have asked YOU, and to still be waiting on
//   your answer.
//
//   It is COUNTS AND AREAS, never lists. How many buildings and which towns,
//   never an address. How much work has gone through, never which jobs. Their
//   roster is not here at all: how many contractors a managing agent works
//   with is their book, and it tells the answering side nothing about whether
//   to say yes.
//
// The principle is the one overflow already runs on: answering an overflow
// post makes you known to the account that posted it, because you chose to
// answer. Asking to connect makes you known to the account you asked, for the
// same reason and for exactly as long as the question is open.
app.get("/api/my-connect-requests/:id/asker", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: "forbidden" }, 403);

  const row = await c.env.DB.prepare(
    `SELECT cr.*, a.name AS account_name, a.kind, a.created_at AS account_created,
            a.trades AS account_trades, u.name AS asked_by_name
       FROM connect_requests cr
       JOIN accounts a ON a.id = cr.account_id
       LEFT JOIN users u ON u.id = cr.requested_by
      WHERE cr.id = ? AND cr.company_id = ?`
  ).bind(c.req.param("id"), companyId).first();
  if (!row) return c.json({ error: "not_found" }, 404);
  // Only while it is theirs to answer. A declined request is finished
  // business, and an accepted one means they are working together -- at which
  // point this is not the screen that tells them about each other.
  if (row.status !== "pending") return c.json({ error: "already_answered" }, 409);

  // Where they work and how much of it there is. Counted, never listed.
  let buildings = 0, towns = [];
  try {
    const r = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM properties WHERE account_id = ?`).bind(row.account_id).first();
    buildings = r?.n || 0;
    const { results } = await c.env.DB.prepare(
      `SELECT DISTINCT city, state FROM properties
        WHERE account_id = ? AND city IS NOT NULL AND city != '' ORDER BY city LIMIT 8`
    ).bind(row.account_id).all();
    towns = (results || []).map((x) => [x.city, x.state].filter(Boolean).join(", "));
  } catch (err) { if (!missingSchema(err)) throw err; }

  let jobs = 0;
  try {
    const r = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM jobs WHERE account_id = ?`).bind(row.account_id).first();
    jobs = r?.n || 0;
  } catch (err) { if (!missingSchema(err)) throw err; }

  return c.json({
    id: row.id,
    account: row.account_name,
    kind: row.kind,
    since: row.account_created || null,
    askedBy: row.asked_by_name || null,
    via: row.via,
    message: row.message || null,
    createdAt: row.created_at,
    buildings, towns, jobs,
    // What the account says it hires. The reason this matters to the person
    // deciding: work that never comes is not worth the paperwork.
    trades: parseJson(row.account_trades, null) || [],
  });
});

// Answer one. Accepting is what creates the engagement -- there is no other
// way into this account's roster from here, which is the point of the whole
// exercise.
app.post("/api/my-connect-requests/:id/respond", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: "forbidden" }, 403);
  const { userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const accept = b.accept === true;

  const row = await c.env.DB.prepare(
    `SELECT * FROM connect_requests WHERE id = ? AND company_id = ?`
  ).bind(c.req.param("id"), companyId).first();
  if (!row) return c.json({ error: "not_found" }, 404);
  if (row.status !== "pending") return c.json({ error: "already_answered", status: row.status }, 409);

  if (!accept) {
    await c.env.DB.prepare(
      `UPDATE connect_requests SET status = 'declined', responded_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(row.id).run();
    await logActivity(c.env, row.account_id, null, "connect_declined",
      `${await companyName(c.env.DB, companyId)} declined the connection`);
    return c.json({ ok: true, status: "declined" });
  }

  // The trades and capabilities they already work under, copied from an
  // engagement they already have. Categories live on the engagement rather
  // than the company, so a connection made with empty ones produces a
  // contractor who matches no job and cannot be assigned to anything --
  // which would make "connect and they are ready" untrue in the one way
  // that matters. The hiring account can change them afterwards like any
  // other; this is only where they start.
  const prior = await c.env.DB.prepare(
    `SELECT categories, caps FROM engagements
      WHERE company_id = ? AND categories <> '[]'
      ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, invited_at DESC LIMIT 1`
  ).bind(companyId).first();

  // Active, not invited. "Invited" is for a company somebody typed in and
  // has not heard back from; this one has just said yes in person.
  const engagementId = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO engagements (id, account_id, company_id, status, categories, caps)
       VALUES (?, ?, ?, 'active', ?, ?)`
    ).bind(engagementId, row.account_id, companyId,
      prior?.categories || "[]", prior?.caps || "[]").run();
  } catch (err) {
    // They were added by hand in the meantime. The answer they wanted is
    // still the outcome they wanted, so record it and move on.
    if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
  }
  await c.env.DB.prepare(
    `UPDATE connect_requests SET status = 'accepted', responded_at = CURRENT_TIMESTAMP WHERE id = ?`
  ).bind(row.id).run();

  // Seats in that account, so they can see its jobs. Without this they have
  // accepted a connection they cannot switch to.
  //
  // Everyone at the company, not only whoever happened to tap yes. A
  // two-person outfit where the owner accepts and the estimator cannot see
  // the work is a connection that half exists, and the missing half is
  // invisible from both ends.
  const { results: seats } = await c.env.DB.prepare(
    `SELECT DISTINCT user_id FROM memberships WHERE company_id = ? AND role = 'contractor'`
  ).bind(companyId).all();
  // And, when the company IS an account, everyone who runs that account.
  // A general contractor accepting work has no contractor seats of their
  // own -- their people are admins and project managers on their own
  // subdomain -- so without this the whole team would accept a connection
  // none of them could switch to.
  //
  // Admin and PM only. A building owner or a tenant is a guest of the
  // accepting account and has no business being seated in a stranger's.
  let ownSeats = [];
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT DISTINCT m.user_id FROM memberships m JOIN accounts a ON a.id = m.account_id
        WHERE a.company_id = ? AND m.role IN ('admin', 'pm')`
    ).bind(companyId).all();
    ownSeats = results || [];
  } catch (err) { if (!missingSchema(err)) throw err; }
  const userIds = new Set([userId, ...seats.map((r) => r.user_id),
    ...ownSeats.map((r) => r.user_id)].filter(Boolean));
  for (const uidToSeat of userIds) {
    try {
      await c.env.DB.prepare(
        `INSERT INTO memberships (id, user_id, account_id, role, company_id) VALUES (?, ?, ?, 'contractor', ?)`
      ).bind(uid(), uidToSeat, row.account_id, companyId).run();
    } catch (err) {
      if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
    }
  }

  await logEvent(c.env, row.account_id, userId, "engagement.connected", engagementId, { companyId });
  await logActivity(c.env, row.account_id, null, "connect_accepted",
    `${await companyName(c.env.DB, companyId)} accepted the connection`);
  return c.json({ ok: true, status: "accepted", engagementId });
});

// This account's members (admin/pm/contractor), composed with the person's
// name/email/phone — what the UI calls `accountUsers`.
app.get("/api/account-users", async (c) => {
  const auth = c.get("auth");
  const { accountId } = auth;
  // A building owner is a guest in somebody else's account: who else has a
  // login there is not theirs to read. They still need their own row, which
  // is how the app knows which seat it is sitting in. A scoped property
  // manager does need the list -- they answer the owners who raise work, and
  // a request signed "an owner" is no use to them.
  const mine = (auth.role === "owner" || auth.role === "tenant") ? ` AND m.user_id = ? ` : "";
  const { results } = await c.env.DB.prepare(
    `SELECT u.*, m.role, m.company_id, m.unit FROM memberships m
     JOIN users u ON u.id = m.user_id WHERE m.account_id = ? ${mine}`
  ).bind(accountId, ...((auth.role === "owner" || auth.role === "tenant") ? [auth.userId] : [])).all();
  const { results: scopes } = await c.env.DB.prepare(
    `SELECT mp.property_id, m.user_id FROM membership_properties mp
       JOIN memberships m ON m.id = mp.membership_id WHERE m.account_id = ?`
  ).bind(accountId).all();
  const byUser = {};
  for (const r of scopes || []) (byUser[r.user_id] ||= []).push(r.property_id);
  // And the job lists, so the form can draw what is set rather than opening
  // empty over a seat that is narrowed -- which would read as unrestricted
  // and quietly widen somebody the next time it was saved.
  const jobsByUser = {};
  try {
    const { results: jscopes } = await c.env.DB.prepare(
      `SELECT mj.job_id, m.user_id FROM membership_jobs mj
         JOIN memberships m ON m.id = mj.membership_id WHERE m.account_id = ?`
    ).bind(accountId).all();
    for (const r of jscopes || []) (jobsByUser[r.user_id] ||= []).push(r.job_id);
  } catch (err) { if (!missingSchema(err)) throw err; }

  // The most recent live invite per person, if there is one. Missing table
  // means 028 is not applied, which is a roster without the extra column
  // rather than a roster that fails to load.
  const invites = {};
  try {
    const { results: inv } = await c.env.DB.prepare(
      `SELECT user_id, MAX(sent_at) AS sent_at FROM user_invites
        WHERE account_id = ? AND used_at IS NULL AND revoked_at IS NULL AND sent_at IS NOT NULL
        GROUP BY user_id`
    ).bind(accountId).all();
    for (const r of inv || []) invites[r.user_id] = r.sent_at;
  } catch (err) { if (!missingSchema(err)) throw err; }

  return c.json(results.map((r) => ({
    // A tenant added by phone alone carries a placeholder address. It exists
    // so the row has a unique key, and it is nobody's address: handing it to
    // the browser gets it printed next to a mailto: link that goes nowhere.
    id: r.id, name: r.name, email: realEmail(r.email), phone: r.phone, role: r.role, subId: r.company_id,
    propertyIds: byUser[r.id] || [], jobIds: jobsByUser[r.id] || [], unit: r.unit || null,
    // Whether this person can actually get in, and whether anybody has told
    // them they can. Both were invisible: an admin added somebody and the
    // roster looked identical whether they had signed in once or had never
    // heard of SubSub.
    hasLogin: !!r.auth_id,
    inviteSentAt: invites[r.id] || null,
    // Whether to go and fetch a face, not the key itself. The key is an R2
    // path; handing it to the browser invites somebody to ask for a
    // different one.
    hasAvatar: !!r.avatar_key,
  })));
});

// Add (or re-invite) a person to this account. Dedupes the person on email —
// same person can already exist as a user from another account.
// A role the API will accept on a membership. The database no longer carries
// a CHECK for this (see migration 014), so this is the constraint.
const MEMBER_ROLES = ["admin", "pm", "owner", "tenant", "contractor"];

// Replaces a membership's building list. Only an owner has one: giving an
// admin a list would read as a restriction the rest of the code does not
// apply, so the rows are cleared instead of written.
async function setMembershipProperties(db, membershipId, accountId, role, propertyIds) {
  const stmts = [db.prepare(`DELETE FROM membership_properties WHERE membership_id = ?`).bind(membershipId)];
  // A manager with no list is unrestricted, so an empty list is a real state
  // to store rather than a reason to skip the write -- clearing one is how
  // somebody gets widened back to the whole account.
  if (isPropertyScopedRole(role)) {
    for (const pid of [...new Set(propertyIds || [])]) {
      stmts.push(db.prepare(
        `INSERT OR IGNORE INTO membership_properties (membership_id, property_id)
         SELECT ?, id FROM properties WHERE id = ? AND account_id = ?`
      ).bind(membershipId, pid, accountId));
    }
  }
  await db.batch(stmts);
}

// The same, one axis over. A general contractor has no buildings, so their
// PROJECT manager is narrowed by job instead -- see shared/jobscope.js.
//
// The INSERT ... SELECT is what makes the id safe: a job id in the body is a
// claim, and joining it back to this account is the only thing that makes it
// true. A row naming another account's job would narrow this seat to a job it
// can never see, or -- depending which JOIN read it -- across accounts.
// CHECK.sql counts both shapes and both must read zero.
async function setMembershipJobs(db, membershipId, accountId, role, jobIds) {
  if (jobIds === undefined) return;
  try {
    const stmts = [db.prepare(`DELETE FROM membership_jobs WHERE membership_id = ?`).bind(membershipId)];
    // Only a pm is job-scoped, so changing somebody to any other role clears
    // the list rather than leaving one that narrows nobody and would start
    // narrowing them the day that role joined JOB_SCOPED_ROLES.
    if (JOB_SCOPED_ROLES.includes(role)) {
      for (const jid of [...new Set(jobIds || [])]) {
        stmts.push(db.prepare(
          `INSERT OR IGNORE INTO membership_jobs (membership_id, job_id)
           SELECT ?, id FROM jobs WHERE id = ? AND account_id = ?`
        ).bind(membershipId, jid, accountId));
      }
    }
    await db.batch(stmts);
  } catch (err) {
    // A database without 053. The seat stays unrestricted, which is what it
    // was before this shipped.
    if (!missingSchema(err)) throw err;
  }
}

const userInviteUrl = (account, token) => `${accountOrigin(account)}/?user=${token}`;

async function lookupUserInvite(env, token) {
  if (!token || !/^[0-9a-f]{64}$/.test(token)) return { error: "invalid" };
  let row;
  try {
    row = await env.DB.prepare(`SELECT * FROM user_invites WHERE token = ?`).bind(token).first();
  } catch (err) {
    if (missingSchema(err)) return { error: "invalid" };
    throw err;
  }
  if (!row) return { error: "invalid" };
  if (row.revoked_at) return { error: "revoked" };
  if (row.used_at) return { error: "used" };
  if (new Date(row.expires_at) < new Date()) return { error: "expired" };
  const [account, user] = await Promise.all([
    env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(row.account_id).first(),
    env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(row.user_id).first(),
  ]);
  if (!account || !user) return { error: "invalid" };
  return { invite: row, account, user };
}

// Public: the page has to show whose account this is, and their branding,
// before anybody has typed anything.
app.get("/api/user-invite/:token", async (c) => {
  const { error, invite, account, user } = await lookupUserInvite(c.env, c.req.param("token"));
  // A token that was never valid and one spent an hour ago read the same
  // from outside; the person holding a dead link needs the same instruction
  // either way, which is to ask for another.
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);
  const membership = await c.env.DB.prepare(
    `SELECT role FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(user.id, account.id).first();
  return c.json({
    name: user.name, email: realEmail(invite.email || user.email),
    role: membership?.role || null,
    account: {
      id: account.id, name: account.name, subdomain: account.subdomain,
      theme: parseJson(account.theme),
      logoKey: account.logo_key, useDefaultMark: !!account.use_default_mark,
    },
  });
});

// And the accept: a password, and nothing else. The membership was decided
// when the admin added them, so this cannot widen anything -- it proves the
// address and sets a way in.
app.post("/api/user-invite/:token", async (c) => {
  const rl = await rateLimit(c.env, "user-invite", clientIp(c), { limit: 20, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const { error, invite, account, user } = await lookupUserInvite(c.env, c.req.param("token"));
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);

  const b = await c.req.json().catch(() => ({}));
  const password = String(b.password || "");
  if (password.length < 8) return c.json({ error: "weak_password" }, 400);
  const email = realEmail(invite.email || user.email);
  if (!email) return c.json({ error: "no_email" }, 400);

  const signed = await supabaseSignUp(c.env, email, password, { redirectTo: `${accountOrigin(account)}/` });
  if (!signed.ok && signed.error !== "email_in_use") {
    return c.json({ error: signed.error, detail: signed.detail }, 400);
  }
  // Supabase's enumeration guard showing through: an address it already
  // knows answers 200 with a fabricated id and no identities, and writing
  // that id would point auth_id at nobody.
  const already = signed.error === "email_in_use" || signed.existed;
  if (signed.ok && !signed.existed && signed.authId && !user.auth_id) {
    await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ? AND auth_id IS NULL`)
      .bind(signed.authId, user.id).run();
  }
  await c.env.DB.prepare(`UPDATE user_invites SET used_at = CURRENT_TIMESTAMP WHERE id = ?`)
    .bind(invite.id).run();
  await logActivity(c.env, account.id, null, "user_joined", `${user.name} set up their login`);

  return c.json({
    ok: true, email,
    // Said, not guessed at. A project with email confirmation on will not
    // sign them in yet, and somebody typing a correct password into a screen
    // that keeps refusing it has no way to know why.
    needsConfirmation: signed.ok && !signed.session && !already,
    existed: already,
  });
});

// Make an invite for somebody on the account, and send it.
//
// Returns what happened rather than throwing: adding the person has already
// succeeded by the time this runs, and failing the whole request because an
// email bounced would tell an admin their colleague was not added when they
// were.
async function inviteAccountUser(c, { accountId, user, role, invitedBy }) {
  const email = realEmail(user.email);
  if (!email) return { invited: false, reason: "no_email" };
  // Already has a login: there is nothing to set up, and a "choose a
  // password" mail to somebody who has one is a phishing lesson in reverse.
  if (user.auth_id) return { invited: false, reason: "already_has_login" };

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  const id = uid(), token = newInviteToken();
  const expires = new Date(Date.now() + INVITE_TTL_DAYS * 86400_000).toISOString();
  try {
    await c.env.DB.prepare(
      `INSERT INTO user_invites (id, account_id, user_id, token, email, created_by, expires_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, user.id, token, email, invitedBy?.id || null, expires).run();
  } catch (err) {
    if (missingSchema(err)) {
      console.warn("[user-invite] 028_user_invites not applied - person added, invite not sent");
      return { invited: false, reason: "migration_needed", migration: "028_user_invites" };
    }
    throw err;
  }

  const mail = userInviteEmail({
    name: user.name, account, role, invitedBy: invitedBy?.name || null,
    link: userInviteUrl(account, token),
  });
  const link = userInviteUrl(account, token);
  const result = await sendEmail(c.env, { to: email, subject: mail.subject, text: mail.text, html: mail.html });
  await logMail(c.env, { accountId, companyId: null, to: email, kind: "user_invite",
    subject: mail.subject, result, sentBy: invitedBy?.id || null });

  // And a text, when there is a number. A roofer reads a text on a ladder
  // and opens email on Sunday night, if at all -- the same reason the
  // subcontractor invite grew a phone number. Either link finishes the same
  // invite, so there is nothing to reconcile.
  const phone = normalizePhone(user.phone) || null;
  let smsResult = null;
  if (phone) {
    smsResult = await sendAccountSms(c.env, { accountId, to: phone, kind: "user_invite",
      body: userInviteSms({ account, role, link }) });
  }
  const texted = !!smsResult?.ok;

  if (result?.ok || texted) {
    await c.env.DB.prepare(`UPDATE user_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(id).run();
    return { invited: true, to: email, emailed: !!result?.ok, texted };
  }
  return { invited: false, reason: "send_failed", error: result?.error || null, texted };
}

app.post("/api/account-users", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  const b = await c.req.json(); // { name, email, phone, role, subId, propertyIds }
  if (!MEMBER_ROLES.includes(b.role)) return c.json({ error: "invalid_role" }, 400);
  // An owner or tenant scoped to nothing can see nothing, which is a login
  // that does not work and a support call that follows. A manager with no
  // list is the ordinary case -- the whole account -- so it is not refused.
  if (ALWAYS_SCOPED_ROLES.includes(b.role) && !(b.propertyIds || []).length) {
    return c.json({ error: "properties_required" }, 400);
  }
  let user = await c.env.DB.prepare(`SELECT * FROM users WHERE lower(email) = lower(?)`).bind(b.email).first();
  const userId = user?.id ?? uid();
  if (!user) {
    await c.env.DB.prepare(`INSERT INTO users (id, name, email, phone) VALUES (?, ?, ?, ?)`)
      .bind(userId, b.name, b.email, b.phone || null).run();
  }
  const existingMembership = await c.env.DB.prepare(
    `SELECT id FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(userId, accountId).first();
  let membershipId;
  if (existingMembership) {
    membershipId = existingMembership.id;
    await c.env.DB.prepare(`UPDATE memberships SET role = ?, company_id = ? WHERE id = ?`)
      .bind(b.role, b.subId ?? null, membershipId).run();
  } else {
    membershipId = uid();
    await c.env.DB.prepare(`INSERT INTO memberships (id, user_id, account_id, role, company_id) VALUES (?, ?, ?, ?, ?)`)
      .bind(membershipId, userId, accountId, b.role, b.subId ?? null).run();
  }
  await setMembershipProperties(c.env.DB, membershipId, accountId, b.role, b.propertyIds);
  await setMembershipJobs(c.env.DB, membershipId, accountId, b.role, b.jobIds);

  // Tell them. This is the whole point: adding somebody used to write two
  // rows and send nothing, so the person added had no way to find out they
  // had an account, and no way in if they did.
  const row = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(userId).first();
  const me = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`)
    .bind(c.get("auth").userId).first();
  const invite = await inviteAccountUser(c, {
    accountId, user: row, role: b.role,
    invitedBy: { id: c.get("auth").userId, name: me?.name || null },
  });
  return c.json({ id: userId, ...invite }, 201);
});

// "They never got it." Same invite, sent again -- and any earlier one for
// this person is withdrawn, so a list of live links cannot outgrow the
// number of people waiting on one.
app.post("/api/account-users/:userId/invite", requireRole("admin"), async (c) => {
  const { accountId, userId: byId } = c.get("auth");
  const userId = c.req.param("userId");
  const member = await c.env.DB.prepare(
    `SELECT u.*, m.role FROM users u JOIN memberships m ON m.user_id = u.id
      WHERE u.id = ? AND m.account_id = ?`
  ).bind(userId, accountId).first();
  if (!member) return c.json({ error: "not_found" }, 404);

  try {
    await c.env.DB.prepare(
      `UPDATE user_invites SET revoked_at = CURRENT_TIMESTAMP
        WHERE account_id = ? AND user_id = ? AND used_at IS NULL AND revoked_at IS NULL`
    ).bind(accountId, userId).run();
  } catch (err) { if (!missingSchema(err)) throw err; }

  const me = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`).bind(byId).first();
  const invite = await inviteAccountUser(c, {
    accountId, user: member, role: member.role,
    invitedBy: { id: byId, name: me?.name || null },
  });
  return c.json(invite, invite.invited ? 200 : 409);
});

app.patch("/api/account-users/:userId", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  const userId = c.req.param("userId");
  const b = await c.req.json(); // { name, email, phone, role, subId }
  if (b.name != null || b.email != null || b.phone != null) {
    await c.env.DB.prepare(`UPDATE users SET name = COALESCE(?, name), email = COALESCE(?, email), phone = COALESCE(?, phone) WHERE id = ?`)
      .bind(b.name ?? null, b.email ?? null, b.phone ?? null, userId).run();
  }
  // A face. Separate from the name/email write above because it is the one
  // field on this route somebody is also allowed to change about themselves
  // -- see PATCH /api/me/avatar -- and because null is a real value here
  // (removing a picture) rather than "leave it alone", which is what
  // COALESCE means everywhere else in that statement.
  if (b.avatarKey !== undefined) {
    const key = b.avatarKey === null ? null : String(b.avatarKey);
    if (key !== null && !ownedKey(key, accountId)) return c.json({ error: "bad_key" }, 400);
    await c.env.DB.prepare(`UPDATE users SET avatar_key = ? WHERE id = ?`).bind(key, userId).run();
  }
  if (b.role != null) {
    if (!MEMBER_ROLES.includes(b.role)) return c.json({ error: "invalid_role" }, 400);
    await c.env.DB.prepare(`UPDATE memberships SET role = ?, company_id = ? WHERE user_id = ? AND account_id = ?`)
      .bind(b.role, b.subId ?? null, userId, accountId).run();
  }
  // The list travels with the role. Demoting somebody to owner without one
  // would leave them seeing nothing; promoting an owner to admin has to drop
  // theirs, or a stale list sits there looking like it means something.
  if (b.role != null || b.propertyIds !== undefined || b.jobIds !== undefined) {
    const m = await c.env.DB.prepare(
      `SELECT id, role FROM memberships WHERE user_id = ? AND account_id = ?`
    ).bind(userId, accountId).first();
    if (m) {
      if (b.role != null || b.propertyIds !== undefined) {
        await setMembershipProperties(c.env.DB, m.id, accountId, m.role, b.propertyIds);
      }
      // A role change clears the job list for the same reason it clears the
      // property one: a stale list sits there looking like it means something.
      if (b.role != null && b.jobIds === undefined) {
        await setMembershipJobs(c.env.DB, m.id, accountId, m.role, []);
      } else {
        await setMembershipJobs(c.env.DB, m.id, accountId, m.role, b.jobIds);
      }
    }
  }
  return c.json({ ok: true });
});

// An uploaded key is only acceptable if this account uploaded it.
//
// PUT /api/uploads writes to `${accountId}/${kind}/...`, so the prefix is
// the proof. Without this check an admin could patch in any path in the
// bucket and then read it back through the avatar route below -- turning a
// profile picture into a way to fetch another account's documents.
const ownedKey = (key, accountId) =>
  typeof key === "string" && key.startsWith(`${accountId}/`) && !key.includes("..");

// Somebody's face, for the people who work with them.
//
// Behind auth and scoped to a shared account, unlike the company logo,
// which is public because it has to render on a login page. A logo is a
// business's sign; this is a person's photograph, and the people entitled
// to see it are the ones on a roster with them.
//
// It serves the one key stored against that person's own row and never a
// path from the request, so it cannot be pointed at anything else in the
// bucket.
app.get("/api/account-users/:userId/avatar", async (c) => {
  const { accountId, userId: me, role } = c.get("auth");
  // A guest seat -- an owner or a tenant -- sees its own face and nobody
  // else's. Same answer as no picture, so it cannot be used to ask which
  // people on the account have one.
  if (ALWAYS_SCOPED_ROLES.includes(role) && c.req.param("userId") !== me) return c.notFound();
  const row = await c.env.DB.prepare(
    `SELECT u.avatar_key FROM users u
       JOIN memberships m ON m.user_id = u.id AND m.account_id = ?
      WHERE u.id = ?`
  ).bind(accountId, c.req.param("userId")).first();
  if (!row?.avatar_key) return c.notFound();
  const obj = await c.env.FILES.get(row.avatar_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": obj.httpMetadata?.contentType || "image/jpeg",
      // Private: it is one person's photograph, and a shared cache holding
      // it would serve it to whoever asked next.
      "Cache-Control": "private, max-age=300",
    },
  });
});

// Your own face. Any seat, not just an admin -- needing to ask an
// administrator to change your profile picture is not a permission model,
// it is an errand.
app.patch("/api/me/avatar", async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const key = b.avatarKey == null ? null : String(b.avatarKey);
  if (key !== null && !ownedKey(key, accountId)) return c.json({ error: "bad_key" }, 400);
  try {
    await c.env.DB.prepare(`UPDATE users SET avatar_key = ? WHERE id = ?`).bind(key, userId).run();
  } catch (err) {
    if (missingSchema(err)) return c.json({ error: "migration_needed", migration: "032_user_avatar" }, 503);
    throw err;
  }
  return c.json({ ok: true, hasAvatar: !!key });
});

// Drops the membership, not the person — they may still belong elsewhere.
//
// Admin-only, EXCEPT that a guest may let themselves out. A building owner is a
// guest in somebody else's account, and an owner who has just fired their
// property manager should not need that manager's cooperation to stop being
// attached to them -- the person they are trying to leave holds the only
// button, which is the wrong way round. A tenant is the same case.
//
// An admin still cannot remove themselves this way; that is account deletion
// wearing a disguise and is refused below.
app.delete("/api/account-users/:userId", async (c) => {
  const auth = c.get("auth");
  const { accountId } = auth;
  const target = c.req.param("userId");
  const leavingOwnSeat = target === auth.userId && ALWAYS_SCOPED_ROLES.includes(auth.role);
  if (!leavingOwnSeat && auth.role !== "admin") return c.json({ error: "forbidden" }, 403);
  // The last admin walking out would leave an account nobody can administer.
  if (target === auth.userId && auth.role === "admin") {
    return c.json({ error: "cannot_remove_self" }, 409);
  }

  const seat = await c.env.DB.prepare(
    `SELECT id, role FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(target, accountId).first();
  if (!seat) return c.json({ error: "not_found" }, 404);

  await c.env.DB.prepare(`DELETE FROM memberships WHERE user_id = ? AND account_id = ?`)
    .bind(target, accountId).run();

  // Said in the account's own feed either way. Somebody leaving is not a
  // silent event for the account they were attached to -- a property manager
  // whose client has walked needs to know without being told by the client.
  const who = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`).bind(target).first();
  await logActivity(c.env, accountId, leavingOwnSeat ? target : auth.userId,
    leavingOwnSeat ? "seat_left" : "user_removed",
    leavingOwnSeat
      ? `${who?.name || "Somebody"} removed their own access to this account`
      : `Removed ${who?.name || "a user"} from this account`);
  await logEvent(c.env, accountId, auth.userId,
    leavingOwnSeat ? "seat.left" : "seat.removed", target, { role: seat.role });
  return c.json({ ok: true, left: leavingOwnSeat });
});

// Current account's own info — lets a resumed session (page reload) rebuild
// its `accounts` state without needing to re-run dev-login.
app.get("/api/account", async (c) => {
  const { accountId, userId } = c.get("auth");
  const a = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!a) return c.json({ error: "not_found" }, 404);
  const user = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(userId).first();
  return c.json({
    id: a.id, name: a.name, subdomain: a.subdomain, kind: a.kind, plan: a.plan, billing: a.billing,
    logoKey: a.logo_key, useDefaultMark: !!a.use_default_mark, theme: parseJson(a.theme),
    // null when nobody has chosen yet -- which is the cue to ask, and is not
    // the same answer as an empty list.
    trades: parseJson(a.trades),
    // What Stripe last told us. The app shows the renewal date from this
    // rather than asking Stripe on every page load.
    subscriptionStatus: a.subscription_status,
    currentPeriodEnd: a.current_period_end,
    comped: !!a.comped,
    // Where their own address got to. The status only -- hostname_error is
    // Cloudflare's own words about our credentials or our zone, which is
    // staff's problem to read and nothing a customer can act on. Telling
    // them "dns: Authentication failed" would be alarming and useless.
    cancelAtPeriodEnd: !!a.cancel_at_period_end,
    hostnameStatus: a.hostname_status || null,
    hostnameCheckedAt: a.hostname_checked_at || null,
    // Who an urgent report goes straight to. Null means nothing dispatches
    // itself, which is how every account starts.
    emergencyCompanyId: a.emergency_company_id || null,
    // 065. Whether a move-in or move-out job schedules itself once it is
    // raised. NULL and 0 are both off, read as one answer here so the screen
    // does not have to know there are two.
    autoTurnaround: !!a.auto_turnaround,
    user: user ? { id: user.id, name: user.name, email: user.email, phone: user.phone, notify: notifyOf(user) } : null,
  });
});

// Public: serves an account's uploaded logo image. Only ever serves the one
// key stored against that account's own logo_key column — never an
// arbitrary path — so this can't be used to read anything else out of R2.
app.get("/api/logo/:accountId", async (c) => {
  const a = await c.env.DB.prepare(`SELECT logo_key FROM accounts WHERE id = ?`).bind(c.req.param("accountId")).first();
  if (!a?.logo_key) return c.notFound();
  const obj = await c.env.FILES.get(a.logo_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": obj.httpMetadata?.contentType || "image/png",
      "Cache-Control": "public, max-age=300",
    },
  });
});

// Public: the branding a hiring account's own subdomain shows before login
// (e.g. outerhome.subsub.work). Only exposes what a logged-out login screen
// needs — never anything else about the account.
app.get("/api/account-by-subdomain/:subdomain", async (c) => {
  const a = await c.env.DB.prepare(
    // kind is read back below and was never selected, so every branded
    // sign-in page thought it belonged to a general contractor.
    `SELECT id, name, subdomain, kind, plan, billing, logo_key, use_default_mark, theme
       FROM accounts WHERE subdomain = ?`
  ).bind(c.req.param("subdomain").toLowerCase()).first();
  if (!a) return c.notFound();
  return c.json({
    id: a.id, name: a.name, subdomain: a.subdomain, kind: a.kind, plan: a.plan, billing: a.billing,
    logoKey: a.logo_key, useDefaultMark: !!a.use_default_mark, theme: parseJson(a.theme),
  });
});

// Every value in a theme must be a plain 6-digit hex color. These get
// interpolated as CSS custom properties on a public, unauthenticated page
// (the login screen and the application form), so an unvalidated string is
// a stylesheet-injection vector — reject anything that isn't exactly this
// shape rather than trying to sanitize it.
const HEX_COLOR = /^#[0-9a-fA-F]{6}$/;
// ---------------------------------------------------------------------------
// Public-endpoint guards
// ---------------------------------------------------------------------------
// A Worker holds no state between requests, so the counter lives in D1. This
// is a floor, not a wall: it stops one script hammering an endpoint. It does
// not stop a distributed flood — put Cloudflare's own rate limiting rules and
// a CAPTCHA in front of these paths too before linking them publicly.
// ---------------------------------------------------------------------------
// Booking a demo. Public, because the whole point is that the person has no
// account yet.
//
// Unlike nearly everything else here these two are reachable by anyone, so
// they never let an error reach the global handler above -- that one puts
// the underlying message in the response on purpose, which is right for a
// signed-in person debugging their own account and wrong for a form on the
// open internet. Everything below answers in fixed words and logs the rest.
// ---------------------------------------------------------------------------

// Times that are actually free, from the calendar that actually owns them.
// The page used to offer eight fixed hours every weekday whether or not
// anybody was available, so half of what it promised could not be kept.
app.get("/api/demo/slots", async (c) => {
  if (!calConfigured(c.env)) return c.json({ error: "not_configured" }, 503);
  const rl = await rateLimit(c.env, "demo-slots", clientIp(c), { limit: 120, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const start = String(c.req.query("start") || "");
  const end = String(c.req.query("end") || "");
  const timeZone = String(c.req.query("timeZone") || "America/Los_Angeles");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start) || !/^\d{4}-\d{2}-\d{2}$/.test(end)) {
    return c.json({ error: "bad_range" }, 400);
  }
  try {
    const r = await fetchSlots(c.env, { start, end, timeZone });
    if (!r.ok) return c.json({ error: "unavailable" }, 502);
    return c.json({ timeZone, slots: r.slots });
  } catch (err) {
    console.error("[demo] slots failed:", err?.stack || err);
    return c.json({ error: "unavailable" }, 502);
  }
});

// And the booking itself. The answer to this call is the only thing that may
// put "You're booked" on the screen.
app.post("/api/demo/book", async (c) => {
  if (!calConfigured(c.env)) return c.json({ error: "not_configured" }, 503);
  // Twelve rather than a handful: a shared office comes from one address,
  // and turning a real prospect away is a worse outcome than a wasted
  // booking. It is still a wall against a script.
  const rl = await rateLimit(c.env, "demo-book", clientIp(c), { limit: 12, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const b = await c.req.json().catch(() => ({}));
  const name = String(b.name || "").trim();
  const email = String(b.email || "").trim();
  const start = String(b.start || "").trim();
  if (!name) return c.json({ error: "name_required" }, 400);
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return c.json({ error: "bad_email" }, 400);
  // An instant, not a day and a label. The browser sends the exact slot it
  // was given back, so there is no re-parsing of "2:00 pm" against a time
  // zone here -- which is where a demo lands an hour out.
  if (!/^\d{4}-\d{2}-\d{2}T[\d:.]+(Z|[+-]\d{2}:\d{2})$/.test(start)) {
    return c.json({ error: "bad_start" }, 400);
  }
  try {
    const r = await createBooking(c.env, {
      start, name, email,
      timeZone: String(b.timeZone || "America/Los_Angeles"),
      company: String(b.company || "").trim(),
      phone: String(b.phone || "").trim(),
      role: String(b.role || "").trim(),
      subs: String(b.subs || "").trim(),
      notes: String(b.notes || "").trim(),
    });
    if (!r.ok) return c.json({ error: r.reason === "taken" ? "slot_taken" : "unavailable" },
      r.reason === "taken" ? 409 : 502);
    console.log("[demo] booked", r.uid || "(no uid)", "for", email);
    return c.json({ booked: true, uid: r.uid }, 201);
  } catch (err) {
    console.error("[demo] booking failed:", err?.stack || err);
    return c.json({ error: "unavailable" }, 502);
  }
});

async function rateLimit(env, kind, key, { limit, windowMinutes }) {
  const now = new Date();
  const slot = Math.floor(now.getTime() / (windowMinutes * 60_000));
  const bucket = `${kind}:${key}`;
  const window = String(slot);
  try {
    await env.DB.prepare(
      `INSERT INTO rate_limits (bucket, window, hits) VALUES (?, ?, 1)
       ON CONFLICT (bucket, window) DO UPDATE SET hits = hits + 1`
    ).bind(bucket, window).run();
    const row = await env.DB.prepare(
      `SELECT hits FROM rate_limits WHERE bucket = ? AND window = ?`
    ).bind(bucket, window).first();
    return { ok: (row?.hits ?? 0) <= limit, hits: row?.hits ?? 0 };
  } catch (err) {
    // A missing table (migration not yet applied) must not take the endpoint
    // down — fail open and say so in the log rather than 500 on every signup.
    console.error("[rateLimit] unavailable, allowing request:", err?.message || err);
    return { ok: true, hits: 0 };
  }
}

const clientIp = (c) =>
  c.req.header("CF-Connecting-IP") || c.req.header("X-Forwarded-For") || "unknown";

// Subdomains become hostnames, so the rules are stricter than a slug: no
// leading/trailing dash, no double dash, 3-40 chars. The reserved list covers
// the hostnames the product itself uses plus the usual impersonation risks.
const SUBDOMAIN_RE = /^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$/;
const RESERVED_SUBDOMAINS = new Set([
  "app", "www", "admin", "api", "platform", "dashboard", "portal", "status",
  "mail", "smtp", "ftp", "cdn", "assets", "static", "help", "support",
  "docs", "blog", "billing", "account", "accounts", "login", "signup",
  "subsub", "test", "staging", "dev", "demo",
]);
function validSubdomain(sub) {
  const s = String(sub || "").trim().toLowerCase();
  if (!SUBDOMAIN_RE.test(s)) return null;
  if (s.includes("--")) return null;
  if (RESERVED_SUBDOMAINS.has(s)) return null;
  return s;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

// Ten digits, stored the way the forms display them, so the database doesn't
// end up holding four spellings of the same number and no way to match them.
// A leading US country code is dropped rather than rejected, because numbers
// pasted out of a contact card usually carry one. Returns null for anything
// that isn't ten digits -- callers decide whether that's empty or invalid.
const normalizePhone = (v) => {
  let d = String(v ?? "").replace(/\D/g, "");
  if (d.length === 11 && d[0] === "1") d = d.slice(1);
  if (d.length !== 10) return null;
  return `(${d.slice(0, 3)})${d.slice(3, 6)}-${d.slice(6)}`;
};

// Create the auth user with Supabase's own signup endpoint. The anon key is
// the public one and this is exactly what it is for, so no service_role key
// is needed anywhere in this codebase.
// `redirectTo` is where the confirmation link brings them back to. Without
// it Supabase uses the project's Site URL -- the shared address -- so a
// tenant who set a password on their building's branded page confirmed it
// on a page that had never heard of their building. It has to be on the
// project's redirect allow-list (https://*.subsub.work/**) or Supabase
// quietly falls back to the Site URL again.
async function supabaseSignUp(env, email, password, { redirectTo } = {}) {
  let res, body;
  try {
    res = await fetch(`${env.SUPABASE_URL}/auth/v1/signup`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: env.SUPABASE_ANON_KEY },
      body: JSON.stringify({ email, password, ...(redirectTo ? { email_redirect_to: redirectTo } : {}) }),
    });
    body = await res.json();
  } catch (err) {
    return { ok: false, error: "auth_unreachable", detail: String(err?.message || err) };
  }
  if (!res.ok) {
    const msg = String(body?.msg || body?.error_description || body?.error || "");
    if (/already registered|already been registered|User already/i.test(msg)) {
      return { ok: false, error: "email_in_use" };
    }
    if (/password/i.test(msg)) return { ok: false, error: "weak_password", detail: msg };
    // Confirmation is on but the mail could not go out, so Supabase refuses
    // the whole signup. Worth its own code: it is a configuration fault on
    // our side, not anything the person filling in the form can fix, and it
    // is the single most likely way a correctly filled form still fails.
    if (/sending confirmation|error sending|smtp|mail/i.test(msg)) {
      return { ok: false, error: "auth_email_failed", detail: msg };
    }
    return { ok: false, error: "auth_failed", detail: msg };
  }
  // A project with email confirmation on returns a user but no session.
  // Only whether one exists is reported: the tokens themselves are
  // deliberately not passed on. Signup does not sign anyone in -- see the
  // note on needsConfirmation below.
  //
  // `existed` is Supabase's enumeration protection showing through: with
  // confirmation on, signing up an address that is already registered
  // answers 200 with a user object whose id is fabricated and whose
  // identities list is empty, rather than admitting the address is taken.
  // Storing that id would overwrite a real auth_id with one that matches
  // nobody, so it has to be detected rather than trusted.
  const user = body?.user || body;
  const existed = Array.isArray(user?.identities) && user.identities.length === 0;
  return {
    ok: true, existed,
    authId: existed ? null : (user?.id || null),
    session: !!body?.access_token,
  };
}

// A password nobody will ever use or see. It exists because Supabase needs
// one to create an account, and the person it belongs to will set their own
// from the reset link that follows.
function throwawayPassword() {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  return "Aa1!" + [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// Make sure this address exists in Supabase, creating it if it does not.
//
// Staff can create an account or add a colleague from the console, and both
// wrote a users row with auth_id left null and no Supabase account behind it.
// "Send reset link" then called /auth/v1/recover, which answers 200 for an
// address it has never seen -- deliberately, so the endpoint cannot be used
// to discover who has an account. The console reported a reset sent, no mail
// was ever going to arrive, and the person could never sign in.
//
// Creating it here is the anon-key signup the public form already uses, so
// no new secret and no extra privilege. Already-registered is the expected
// answer, not a failure: it means there was nothing to do.
async function ensureAuthUser(env, email) {
  if (!env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) return { ok: false, error: "auth_not_configured" };
  const signed = await supabaseSignUp(env, email, throwawayPassword());
  // `existed` and `email_in_use` are the same answer wearing two faces --
  // whether Supabase admits the address is taken depends on its enumeration
  // setting. Both mean there was nothing to do.
  if (signed.ok) return { ok: true, created: !signed.existed, authId: signed.authId };
  if (signed.error === "email_in_use") return { ok: true, created: false, authId: null };
  return { ok: false, error: signed.error, detail: signed.detail };
}

// ---------------------------------------------------------------------------
// "I cannot get in" -- one door, three different problems behind it.
// ---------------------------------------------------------------------------
//
// The sign-in page used to call Supabase's /auth/v1/recover straight from the
// browser. That endpoint answers 200 for an address it has never seen --
// deliberately, so it cannot be walked to find out who has an account -- which
// means the page said "a reset link is on its way" in three quite different
// situations and only one of them was true:
//
//   1. A real login. The link sends and arrives. Fine.
//   2. A users row with auth_id null -- somebody added from the console, or an
//      applicant who never finished. There is nothing in Supabase to recover,
//      so nothing was ever going to arrive.
//   3. AN INVITED SUBCONTRACTOR WHO NEVER OPENED THEIR LINK. A sub invite is a
//      token; the users row is written by createApplication when they redeem
//      it. So before that there is no user, no password, and no amount of
//      resetting will make one -- what they actually need is the invite again.
//
// Case 3 is the one that cost an afternoon: a subcontractor invited by a
// property manager, told a link was coming, with no way out except somebody at
// the hiring account noticing. So this route does the right thing per case and
// says the same sentence for all of them.
//
// WHY THIS IS NOT A WAY TO MAIL STRANGERS. Every branch sends only to an
// address that is ALREADY on a row here -- a user, or an open invite somebody
// at an account addressed to them. An address we hold nothing for gets nothing
// sent, and the same reply. So it cannot be pointed at an arbitrary inbox, and
// it cannot be used to discover which addresses are on SubSub: one reply, one
// status code, whichever branch ran.
async function openSubInviteFor(env, email) {
  try {
    return await env.DB.prepare(
      `SELECT * FROM sub_invites
        WHERE lower(email) = lower(?)
          AND used_at IS NULL AND revoked_at IS NULL
          AND datetime(expires_at) > datetime('now')
        ORDER BY created_at DESC LIMIT 1`
    ).bind(email).first();
  } catch {
    // 027 not applied: sub_invites has no email column, so there is nothing to
    // match on. Not a failure of this route -- the other two branches stand.
    return null;
  }
}

// Only ever back to a SubSub address. The origin arrives from the browser so a
// branded page returns you to itself rather than the shared one, but an
// unchecked redirect_to is an open redirect with an emailed link attached.
const safeReturnTo = (env, origin) => {
  const domain = env.APP_DOMAIN || "subsub.work";
  const ok = new RegExp(`^https://[a-z0-9-]+\\.${domain.replace(/\./g, "\\.")}$`);
  return ok.test(String(origin || "")) ? String(origin) : `https://app.${domain}`;
};

app.post("/api/password-help", async (c) => {
  // Two ceilings. The per-address one stops somebody mailbombing a person they
  // know is here; the per-IP one stops a list being worked through.
  const byIp = await rateLimit(c.env, "pwhelp-ip", clientIp(c), { limit: 20, windowMinutes: 60 });
  if (!byIp.ok) return c.json({ ok: true });

  const body = await c.req.json().catch(() => ({}));
  const email = String(body?.email || "").trim().toLowerCase();
  // Same answer for a malformed address as for a real one nobody here holds.
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return c.json({ ok: true });

  const byEmail = await rateLimit(c.env, "pwhelp-addr", email, { limit: 5, windowMinutes: 60 });
  if (!byEmail.ok) return c.json({ ok: true });

  const returnTo = safeReturnTo(c.env, body?.origin);

  try {
    const user = await c.env.DB.prepare(
      `SELECT id, email, auth_id FROM users WHERE lower(email) = lower(?)`).bind(email).first();

    if (user) {
      // Case 2 before case 1: recover against an address Supabase has never
      // seen sends nothing, so the login has to exist first. Only when there
      // is no evidence of one -- an auth_id means they have signed in before,
      // and signing them up again spends a send against the hourly limit that
      // the recover itself needs.
      if (!user.auth_id) {
        const made = await ensureAuthUser(c.env, email);
        if (made.ok && made.authId) {
          await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ?`)
            .bind(made.authId, user.id).run().catch(() => {});
        }
      }
      if (c.env.SUPABASE_URL && c.env.SUPABASE_ANON_KEY) {
        const res = await fetch(`${c.env.SUPABASE_URL}/auth/v1/recover`, {
          method: "POST",
          headers: { "Content-Type": "application/json", apikey: c.env.SUPABASE_ANON_KEY },
          body: JSON.stringify({ email, redirect_to: returnTo }),
        }).catch(() => null);
        // Logged, never returned. Whether Supabase was rate-limited is our
        // problem to see and not something the form should differentiate on.
        if (!res || !res.ok) console.warn("[pwhelp] recover failed for a known user:", res?.status);
      }
      return c.json({ ok: true });
    }

    // Case 3. No user row, so a reset is meaningless -- but if an account has
    // an open invite out to this address, that link IS the way in, and sending
    // it again is the same act as the account pressing resend. Same token, so
    // the one already in their inbox keeps working.
    const invite = await openSubInviteFor(c.env, email);
    if (invite) {
      const account = await c.env.DB.prepare(
        `SELECT id, name, subdomain, theme, logo_key, use_default_mark, hostname_status
           FROM accounts WHERE id = ?`).bind(invite.account_id).first();
      if (account) {
        await deliverSubInvite(c.env, { row: { ...invite, phone: null }, account,
          accountId: account.id, userId: null });
        await c.env.DB.prepare(`UPDATE sub_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`)
          .bind(invite.id).run().catch(() => {});
      }
    }
    // Nothing held for this address: nothing sent, same reply.
    return c.json({ ok: true });
  } catch (err) {
    // Even a failure answers the same way. A 500 on a known address and a 200
    // on an unknown one is the oracle this route exists to avoid.
    console.error("[pwhelp]", err?.message || err);
    return c.json({ ok: true });
  }
});

// ---------------------------------------------------------------------------
// Branded hostnames
// ---------------------------------------------------------------------------

// Bring an account's hostname into line with its plan, and write down what
// happened. Never throws: every caller is a request somebody is waiting on --
// a signup, a payment, a plan change -- and none of them should fail because
// Cloudflare's API was slow. What it cannot finish now, the nightly sweep
// finishes later.
async function syncHostname(env, account, { reason } = {}) {
  const sub = account?.subdomain;
  if (!sub) return null;
  if (!hostnameConfig(env)) return null;      // not wired up; nothing to record

  const wanted = account.plan === "scale";
  try {
    const res = wanted
      ? await provisionHostname(env, sub)
      : await deprovisionHostname(env, sub);
    await env.DB.prepare(
      `UPDATE accounts SET hostname_status = ?, hostname_error = ?, hostname_checked_at = ? WHERE id = ?`
    ).bind(res.status, res.error || null, new Date().toISOString(), account.id).run();
    if (res.status === "failed") {
      console.error("[hostname]", reason || "sync", sub, res.error);
    }
    return res;
  } catch (err) {
    // A thrown error here is a bug in this code, not a Cloudflare refusal,
    // but the account still should not be left claiming an address it has
    // not got.
    console.error("[hostname] threw:", sub, err?.stack || err?.message || err);
    try {
      await env.DB.prepare(
        `UPDATE accounts SET hostname_status = 'failed', hostname_error = ?, hostname_checked_at = ? WHERE id = ?`
      ).bind(String(err?.message || err).slice(0, 300), new Date().toISOString(), account.id).run();
    } catch { /* the log above is the record */ }
    return { ok: false, status: "failed", error: String(err?.message || err) };
  }
}

// Fire and forget, without losing the work when the response returns. A
// Worker stops executing the moment it replies unless the platform is told
// to wait, so this is not decoration.
function syncHostnameAfter(c, account, opts) {
  const run = syncHostname(c.env, account, opts);
  try { c.executionCtx.waitUntil(run); } catch { /* no ctx in tests; it still runs */ }
  return run;
}

// Changing an address is two operations, and the order matters. The old
// hostname comes down first: leaving it up means a name the account has given
// up still answers for them, and whoever claims it next cannot have it. Taking
// it down is best-effort -- a Cloudflare refusal there must not stop the new
// address being set up, because the account is already on the new name in the
// database and an account with no address at all is the worse outcome.
async function moveHostnameAfter(c, account, from) {
  const run = (async () => {
    if (!hostnameConfig(c.env)) return null;
    if (from && from !== account.subdomain) {
      try {
        const gone = await deprovisionHostname(c.env, from);
        if (!gone.ok) console.error("[hostname] could not take down", from, gone.error);
      } catch (err) {
        console.error("[hostname] take-down threw:", from, err?.message || err);
      }
    }
    return syncHostname(c.env, account, { reason: "subdomain_changed" });
  })();
  try { c.executionCtx.waitUntil(run); } catch { /* no ctx in tests; it still runs */ }
  return run;
}

// `subcontractor` is the newest and it is the one the growth loop needs. Every
// other kind here HIRES; the send-your-compliance-pack flow is aimed at the
// company being hired, and a roofer arriving from it had to call itself a
// general contractor to get an account at all. Structurally it is a general
// contractor without the buildings -- hireable, no properties, nobody to invite
// -- and the reason it is its own value rather than a label on top of
// `general_contractor` is that the console, the switcher and the branded
// sign-in page all read `kind` to say what an account IS. A roofer told it is a
// general contractor everywhere it looks has been misfiled, and nothing
// downstream can tell the two apart.
const ACCOUNT_KINDS = ["general_contractor", "subcontractor",
  "property_manager", "building_owner", "portfolio_manager"];
// The kinds that keep a building list, and so are the only ones with anything
// for a tenant or a building owner to be attached to.
const ACCOUNT_KINDS_WITH_PROPERTIES = ["property_manager", "building_owner", "portfolio_manager"];
// And the kinds that can themselves be hired. A general contractor sells
// siding on Tuesday and subs its gutters out on Wednesday, and a subcontractor
// is hired by definition; a property manager, a portfolio manager and a
// building owner only ever hire. 031 gives a company row to nobody else, and
// this is the check that keeps it that way as accounts change kind -- so
// adding a kind here is what mints its company row, and leaving it out is what
// would give a subcontractor nothing to be hired AS.
const HIREABLE_KINDS = ["general_contractor", "subcontractor"];

// And the kinds that HIRE, which is the other direction and not the same list.
//
// Sending your compliance pack to somebody means you are working FOR them.
// Creating a job means somebody is going to work for YOU -- it is the act that
// makes an account the hiring side, and it is where a subcontractor account
// stops being one. They are not blocked from anything they came for: their
// documents, their pack, their work orders and their own crews are all
// untouched. They are blocked from the one thing that means they have changed
// what they are, and told how to change it -- which costs nothing and keeps
// everything, because both kinds are hireable so the company row, the licence
// and every pack already sent survive the switch.
const HIRING_KINDS = ["general_contractor", "property_manager", "building_owner", "portfolio_manager"];

// The trade categories an account can hire out -- the same thirty ids the app
// renders from. Kept here too because the browser's copy is a convenience and
// this is the one that decides what is storable: an id the app cannot render
// is worse stored than rejected.
// Where a company will work: named cities, or travel radii from ZIPs. One or
// the other, never both -- that has been the shape since the roster's own
// picker and it is what `coversJob` reads.
//
// Validated rather than trusted because this lands on a shared row: a string
// where an array belongs breaks every screen that maps it, and a thousand
// cities is somebody using a text box as storage.
function validCoverage(v) {
  if (!v || typeof v !== "object") return null;
  const mode = v.mode === "radius" ? "radius" : "cities";
  const cities = Array.isArray(v.cities)
    ? v.cities.map((c) => String(c || "").trim().slice(0, 80)).filter(Boolean).slice(0, 60)
    : [];
  const radii = Array.isArray(v.radii)
    ? v.radii.map((r) => ({
        zip: String(r?.zip || "").trim().slice(0, 12),
        miles: Math.max(1, Math.min(500, Number(r?.miles) || 0)),
      })).filter((r) => r.zip && r.miles).slice(0, 20)
    : [];
  // Empty is a real answer -- "I have not said yet" -- and must not be a 400.
  return mode === "radius" ? { mode, cities: [], radii } : { mode, cities, radii: [] };
}


// Imported, not restated. See shared/trades.js for why this was two lists.

// Returns the cleaned list, or null if anything in it is not a trade we know.
// Order is not meaningful, but duplicates are dropped so the stored value is
// the set it is meant to be.
function validTrades(v) {
  if (!Array.isArray(v)) return null;
  const out = [];
  for (const raw of v) {
    const id = String(raw ?? "").trim();
    if (!TRADE_IDS.has(id)) return null;
    if (!out.includes(id)) out.push(id);
  }
  return out;
}

// The look AND the browser-tab titles of the two pages a subcontractor sees
// before they are inside the app. The titles live here rather than in
// columns of their own because they belong to exactly the same two pages as
// the colours, and one JSON blob is one thing to keep in step.
function validTheme(theme) {
  if (!theme || typeof theme !== "object") return null;
  const out = {};
  for (const k of ["bg", "surface", "text", "accent", "btnText"]) {
    if (typeof theme[k] !== "string" || !HEX_COLOR.test(theme[k])) return null;
    out[k] = theme[k];
  }
  // SubSub is not the customer's to remove. The browser adds nothing, so
  // the name only survives because the page puts it there -- which means a
  // title saved without it would be a page passing the product off as the
  // customer's own. It is stripped on the way in and added on the way out,
  // so a customer who types it gets one and a customer who deletes it gets
  // one anyway.
  for (const k of ["signInTitle", "applyTitle"]) {
    if (theme[k] === undefined || theme[k] === null) continue;
    if (typeof theme[k] !== "string") return null;
    const own = String(theme[k])
      .replace(/\s*[\u00b7|\-\u2013\u2014]\s*SubSub\s*$/i, "")
      .replace(/\s*\bSubSub\b\s*$/i, "")
      .replace(/[\r\n\t]+/g, " ")
      .trim()
      .slice(0, 60);
    if (own) out[k] = own;
  }
  return out;
}

// One's own notification choices. Any signed-in person, their own row only:
// there is nothing here about anybody else.
app.patch("/api/me", async (c) => {
  const { userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const n = b.notify || {};
  const notify = {
    email: !!n.email, sms: !!n.sms,
    statusChanges: n.statusChanges === undefined ? true : !!n.statusChanges,
  };
  try {
    await c.env.DB.prepare(`UPDATE users SET notify = ? WHERE id = ?`)
      .bind(JSON.stringify(notify), userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
  return c.json({ ok: true, notify });
});

// 072. HOW A TENANT WOULD LIKE THIS ACCOUNT TO REACH THEM, AND WHO TO CALL IF
// IT CANNOT. Keyed by (account, person): a person is global and may rent from
// two landlords, and the emergency contact they gave one of them is not the
// other's to read. The number itself is users.phone, which is what every text
// already goes to -- a second copy here would be two records of one fact and
// the texts would follow one of them.
//
// The caller's own row and nobody else's: there is no id in the path, so
// there is nothing here a tenant could point at another tenant.
const contactRowToJs = (r, u) => ({
  prefer: r?.prefer || null,
  bestTime: r?.best_time || null,
  emergencyName: r?.emergency_name || null,
  emergencyRelation: r?.emergency_relation || null,
  emergencyPhone: r?.emergency_phone || null,
  phone: u?.phone || null,
  email: realEmail(u?.email) || null,
  updatedAt: r?.updated_at || null,
});

// WHO LOOKS AFTER THESE BUILDINGS, in the order a tenant would want to ring
// them: a project manager narrowed to one of them, then a manager narrowed to
// nothing, then the admins. The first tier with anybody in it is the answer,
// at most two people. One function, read by Tenant HQ's card and by the
// Access panel, so the two cannot name different people for one building.
async function buildingManagers(env, accountId, propertyIds = []) {
  const { results: team } = await env.DB.prepare(
    `SELECT m.id AS mid, m.user_id, m.role, u.name, u.email, u.phone
       FROM memberships m JOIN users u ON u.id = m.user_id
      WHERE m.account_id = ? AND m.role IN ('admin','pm')
      ORDER BY u.name`).bind(accountId).all();
  const scopes = new Map();
  for (const t of team || []) {
    const { results } = await env.DB.prepare(
      `SELECT property_id FROM membership_properties WHERE membership_id = ?`).bind(t.mid).all()
      .catch(() => ({ results: [] }));
    scopes.set(t.mid, (results || []).map((x) => x.property_id));
  }
  const pms = (team || []).filter((t) => t.role === "pm");
  const tiers = [
    pms.filter((t) => scopes.get(t.mid).some((p) => propertyIds.includes(p))),
    pms.filter((t) => scopes.get(t.mid).length === 0),
    (team || []).filter((t) => t.role === "admin"),
  ];
  return (tiers.find((t) => t.length) || []).slice(0, 2);
}

// WHO RUNS MY BUILDING, for the card on Tenant HQ. Asked for as *"the property
// manager profile and contact info, in a quick digestible format so a tenant
// can quickly look"*. The account itself carries no office phone or address,
// so the answer is the people: a project manager narrowed to this tenant's
// building first, because that is the person who actually looks after it;
// then a manager narrowed to nothing, who runs every building; then the
// account's admins. The first tier that has anybody in it is the answer, at
// most two names -- a list of the whole office is not "your manager".
//
// This account's own team, read by somebody this account houses. A name, a
// title, a work email and the phone on their seat: what a tenant needs to
// reach the people who run their home, and nothing about anybody else on the
// account -- no other tenants, no contractors, no owners.
app.get("/api/my-manager", requireRole("tenant"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const acct = await c.env.DB.prepare(`SELECT name, kind FROM accounts WHERE id = ?`).bind(accountId).first();
  const mine = await c.env.DB.prepare(
    `SELECT mp.property_id FROM memberships m
       JOIN membership_properties mp ON mp.membership_id = m.id
      WHERE m.user_id = ? AND m.account_id = ?`).bind(userId, accountId).all()
    .then((r) => (r.results || []).map((x) => x.property_id)).catch(() => []);
  const pick = await buildingManagers(c.env, accountId, mine);
  return c.json({
    company: acct?.name || null,
    kind: acct?.kind || null,
    managers: pick.map((t) => ({ name: t.name || null, role: t.role,
      email: realEmail(t.email) || null, phone: t.phone || null })),
  });
});

// 073. HOW THE CREW GETS IN, for the two people who have to meet at the door.
// The rule about whose number each viewer is given is `visiblePeople` in
// shared/accessplan.js; this only gathers the facts it decides between.
//
// `viewer` is "team", "crew" (the caller's company, which must hold accepted
// work here -- the route checks that before it gets this far) or "tenant" (the
// person who has to be let in). A job that is finished with hands nobody's
// number to anybody: a phone number outliving the visit it was for is a number
// somebody holds for no reason.
async function accessPlanFor(env, job, { viewer = "team", companyId = null } = {}) {
  const who = accessTenant(job);
  const seat = who ? await env.DB.prepare(
    `SELECT role FROM memberships WHERE user_id = ? AND account_id = ?`)
    .bind(who, job.account_id).first().catch(() => null) : null;
  const kind = accessFor(job, { tenantReported: seat?.role === "tenant" });
  let how = null, howFrom = null, migration = null;
  try {
    const r = await env.DB.prepare(`SELECT how, updated_by FROM job_access WHERE job_id = ?`)
      .bind(job.id).first();
    how = r?.how || null;
    howFrom = r?.how ? (r.updated_by && r.updated_by === who ? "tenant" : "office") : null;
  } catch (err) {
    migration = missingSchema(err);
    if (!migration) throw err;
  }
  const v = await env.DB.prepare(
    `SELECT date, start_time, end_time, status FROM visits
      WHERE job_id = ? AND status IN ('proposed','confirmed')
      ORDER BY created_at DESC, rowid DESC LIMIT 1`).bind(job.id).first().catch(() => null);
  const live = !jobIsClosed(job);
  let tenant = null, manager = null, crews = [];
  if (live) {
    if (kind === "tenant" && who) {
      const u = await env.DB.prepare(`SELECT name, phone FROM users WHERE id = ?`).bind(who).first();
      let bestTime = null;
      try {
        bestTime = (await env.DB.prepare(
          `SELECT best_time FROM tenant_contacts WHERE account_id = ? AND user_id = ?`)
          .bind(job.account_id, who).first())?.best_time || null;
      } catch (err) { if (!missingSchema(err)) throw err; }
      tenant = { firstName: firstName(u?.name), phone: u?.phone || null, bestTime };
    }
    if (kind === "manager") {
      const [m] = await buildingManagers(env, job.account_id, job.property_id ? [job.property_id] : []);
      manager = m ? { firstName: firstName(m.name), phone: m.phone || null } : null;
    }
    // ACCEPTED, never merely offered: somebody who has not said yes to the job
    // is not coming, and is not owed the tenant's number.
    const { results: wos } = await env.DB.prepare(
      `SELECT w.company_id, w.crew_name, c.company, c.contact, c.phone
         FROM work_orders w JOIN companies c ON c.id = w.company_id
        WHERE w.job_id = ? AND w.voided_at IS NULL AND w.status = 'accepted'
        ORDER BY w.trade`).bind(job.id).all();
    const seen = new Set();
    for (const w of wos || []) {
      if (seen.has(w.company_id)) continue;
      if (viewer === "crew" && w.company_id !== companyId) continue;
      seen.add(w.company_id);
      let name = firstName(w.contact), phone = w.phone || null;
      if (!name || !phone) {
        const u = await env.DB.prepare(
          `SELECT u.name, u.phone FROM memberships m JOIN users u ON u.id = m.user_id
            WHERE m.company_id = ? AND m.role = 'contractor'
            ORDER BY (u.phone IS NULL), u.name LIMIT 1`).bind(w.company_id).first().catch(() => null);
        name = name || firstName(u?.name);
        phone = phone || u?.phone || null;
      }
      crews.push({ company: w.company, firstName: name, phone });
    }
  }
  return {
    kind, how, howFrom, live, migration,
    when: v ? { date: v.date, startTime: v.start_time || null, endTime: v.end_time || null,
      status: v.status } : null,
    people: visiblePeople({ kind, viewer, tenant, manager, crews }),
  };
}

// Who may read it, checked on the row rather than taken from a header: the
// tenant who has to be let in, a company holding accepted work on the job, or
// the team. Anybody else -- another tenant, a crew that was never given the
// job -- gets the same not-found as a job that does not exist.
async function accessViewer(c, job) {
  const auth = c.get("auth");
  if (auth.role === "tenant") return accessTenant(job) === auth.userId ? { viewer: "tenant" } : null;
  if (auth.role === "contractor") {
    const wo = await c.env.DB.prepare(
      `SELECT 1 AS yes FROM work_orders WHERE job_id = ? AND company_id = ?
          AND voided_at IS NULL AND status = 'accepted' LIMIT 1`).bind(job.id, auth.companyId).first();
    return wo?.yes ? { viewer: "crew", companyId: auth.companyId } : null;
  }
  return { viewer: "team" };
}

app.get("/api/jobs/:id/access", requireRole("admin", "pm", "tenant", "contractor"), async (c) => {
  const auth = c.get("auth");
  const job = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), auth.accountId).first();
  const v = job ? await accessViewer(c, job) : null;
  if (!v) return c.json({ error: "job_not_found" }, 404);
  const plan = await accessPlanFor(c.env, job, v);
  return c.json({ ...plan, canEditHow: mayEditHow(auth.role,
    { kind: plan.kind, isAccessTenant: accessTenant(job) === auth.userId }) });
});

app.put("/api/jobs/:id/access-how", requireRole("admin", "pm", "tenant"), async (c) => {
  const auth = c.get("auth");
  const job = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), auth.accountId).first();
  const v = job ? await accessViewer(c, job) : null;
  if (!v) return c.json({ error: "job_not_found" }, 404);
  const before = await accessPlanFor(c.env, job, v);
  if (!mayEditHow(auth.role, { kind: before.kind, isAccessTenant: accessTenant(job) === auth.userId })) {
    return c.json({ error: "forbidden" }, 403);
  }
  const b = await c.req.json().catch(() => ({}));
  const how = normalizeHow(b.how);
  try {
    await c.env.DB.prepare(
      `INSERT INTO job_access (job_id, how, updated_by, updated_at)
       VALUES (?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT (job_id) DO UPDATE SET how = excluded.how,
         updated_by = excluded.updated_by, updated_at = CURRENT_TIMESTAMP`
    ).bind(job.id, how, auth.userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
  await touchJob(c.env, job.id);
  const plan = await accessPlanFor(c.env, job, v);
  return c.json({ ...plan, canEditHow: true });
});

app.get("/api/me/contact", requireRole("tenant"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const user = await c.env.DB.prepare(`SELECT phone, email FROM users WHERE id = ?`).bind(userId).first();
  try {
    const row = await c.env.DB.prepare(
      `SELECT * FROM tenant_contacts WHERE account_id = ? AND user_id = ?`
    ).bind(accountId, userId).first();
    return c.json(contactRowToJs(row, user));
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    // The dashboard draws without it; the number on file still shows.
    return c.json({ ...contactRowToJs(null, user), migration });
  }
});

app.put("/api/me/contact", requireRole("tenant"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const prefer = b.prefer == null || b.prefer === "" ? null : String(b.prefer);
  if (prefer && !PREF_IDS.includes(prefer)) return c.json({ error: "bad_prefer" }, 400);

  // Their own number. Blank is allowed -- somebody may not want to give one --
  // but a number that will not text is refused rather than stored, the rule
  // createTenant follows, because a bad number is otherwise found out by the
  // text that never arrives.
  const phoneRaw = String(b.phone ?? "").trim();
  const phone = phoneRaw ? normalizePhone(phoneRaw) : null;
  if (phoneRaw && (!phone || !toE164(phoneRaw))) return c.json({ error: "bad_phone" }, 400);
  if (prefer && NEEDS_PHONE.includes(prefer) && !phone) return c.json({ error: "phone_required" }, 400);

  const user = await c.env.DB.prepare(`SELECT phone, email FROM users WHERE id = ?`).bind(userId).first();
  if (prefer === "email" && !realEmail(user?.email)) return c.json({ error: "email_required" }, 400);

  const ename = String(b.emergencyName ?? "").trim().slice(0, 80) || null;
  const erel = String(b.emergencyRelation ?? "").trim().slice(0, 40) || null;
  const ephoneRaw = String(b.emergencyPhone ?? "").trim();
  const ephone = ephoneRaw ? normalizePhone(ephoneRaw) : null;
  if (ephoneRaw && !ephone) return c.json({ error: "bad_emergency_phone" }, 400);
  // A name with no number, or a number with nobody's name on it, is a contact
  // nobody can use at the moment it is needed.
  if (!!ename !== !!ephone) return c.json({ error: "emergency_incomplete" }, 400);
  const best = String(b.bestTime ?? "").trim().slice(0, 80) || null;

  try {
    await c.env.DB.prepare(
      `INSERT INTO tenant_contacts (account_id, user_id, prefer, best_time,
              emergency_name, emergency_relation, emergency_phone, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT (account_id, user_id) DO UPDATE SET
         prefer = excluded.prefer, best_time = excluded.best_time,
         emergency_name = excluded.emergency_name,
         emergency_relation = excluded.emergency_relation,
         emergency_phone = excluded.emergency_phone,
         updated_at = CURRENT_TIMESTAMP`
    ).bind(accountId, userId, prefer, best, ename, erel, ephone).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
  // Written after the row, so a refused save does not move the number.
  if ((user?.phone || null) !== phone) {
    await c.env.DB.prepare(`UPDATE users SET phone = ? WHERE id = ?`).bind(phone, userId).run();
  }
  const row = await c.env.DB.prepare(
    `SELECT * FROM tenant_contacts WHERE account_id = ? AND user_id = ?`).bind(accountId, userId).first();
  return c.json(contactRowToJs(row, { ...user, phone }));
});

// 072. NOTICES TO A BUILDING. Per building and never per account: a notice
// about one address shown at another is the wrong answer to "is my water off".
//
// Who reads them: the team, and the guests scoped to that building -- a
// tenant and an owner. Not a contractor seat, which is on this account to do
// work and has no reason to read what the manager tells the residents.
const NOTICE_READ_ROLES = ["admin", "pm", "tenant", "owner"];
const noticeRowToJs = (r) => ({
  id: r.id, propertyId: r.property_id, propertyName: r.property_name || null,
  title: r.title, body: r.body || null, important: !!r.important,
  endsOn: r.ends_on || null, createdAt: r.created_at, createdBy: r.created_by || null,
  createdByName: r.created_by_name || null, emailed: Number(r.emailed || 0),
});
// A day either side of UTC, because the reader's own clock decides "today"
// and the browser filters again with it: a notice up "until Friday" must not
// vanish at 5pm on Friday in Seattle because it is already Saturday in UTC.
const utcYesterday = () => new Date(Date.now() - 86400000).toISOString().slice(0, 10);

app.get("/api/notices", requireRole(...NOTICE_READ_ROLES), async (c) => {
  const auth = c.get("auth");
  const scope = scopeClause(auth, "n.property_id");
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT n.*, p.name AS property_name, u.name AS created_by_name
         FROM building_notices n
         JOIN properties p ON p.id = n.property_id
         LEFT JOIN users u ON u.id = n.created_by
        WHERE n.account_id = ? AND n.removed_at IS NULL ${scope.sql}
        ORDER BY n.created_at DESC
        LIMIT 200`
    ).bind(auth.accountId, ...scope.vals).all();
    const since = utcYesterday();
    const live = (results || []).filter((r) => noticeLive(r, since)).map(noticeRowToJs);
    return c.json({ notices: sortNotices(live) });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    // Nothing to show is the honest answer on a database without 072, and a
    // dashboard must not lose its reports over a table it does not need.
    return c.json({ notices: [], migration });
  }
});

app.post("/api/notices", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const propertyId = String(b.propertyId || "");
  if (!propertyId) return c.json({ error: "property_required" }, 400);
  if (!maySeeProperty(auth, propertyId)) return c.json({ error: "not_found" }, 404);
  const property = await c.env.DB.prepare(
    `SELECT id, name FROM properties WHERE id = ? AND account_id = ?`
  ).bind(propertyId, auth.accountId).first();
  // Operated here, not merely owned: the people who live there are this
  // account's tenants only where this account runs the building.
  if (!property) return c.json({ error: "not_found" }, 404);
  const v = validNotice(b, utcYesterday());
  if (v.error) return c.json({ error: v.error }, 400);

  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO building_notices (id, account_id, property_id, title, body, important, ends_on, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, auth.accountId, propertyId, v.title, v.body, v.important ? 1 : 0, v.endsOn, auth.userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }

  // Emailed only when asked. Text messages are deliberately not offered: a
  // notice to a two-hundred-flat building is two hundred texts against the
  // account's allowance, and that is a decision for its own control.
  let emailed = 0, notEmailed = 0;
  if (b.email) {
    const [{ results: tenants }, account] = await Promise.all([
      c.env.DB.prepare(
        `SELECT u.id, u.name, u.email, u.notify
           FROM memberships m
           JOIN membership_properties mp ON mp.membership_id = m.id
           JOIN users u ON u.id = m.user_id
          WHERE m.account_id = ? AND m.role = 'tenant' AND mp.property_id = ?`
      ).bind(auth.accountId, propertyId).all(),
      c.env.DB.prepare(`SELECT id, name, subdomain, hostname_status FROM accounts WHERE id = ?`)
        .bind(auth.accountId).first(),
    ]);
    const link = `${accountOrigin(account)}/`;
    for (const t of tenants || []) {
      const to = realEmail(t.email);
      // Their own choice: somebody who switched email off is not emailed by
      // the back door of a notice.
      if (!to || !notifyOf(t).email) { notEmailed++; continue; }
      const m = buildingNoticeEmail({ firstName: String(t.name || "").split(" ")[0], account,
        propertyName: property.name, title: v.title, body: v.body, endsOn: v.endsOn,
        important: v.important, link });
      const result = await sendEmail(c.env, { to, subject: m.subject, text: m.text, html: m.html });
      await logMail(c.env, { accountId: auth.accountId, to, kind: "building_notice",
        subject: m.subject, result, sentBy: auth.userId });
      if (result?.ok) emailed++; else notEmailed++;
    }
    await c.env.DB.prepare(`UPDATE building_notices SET emailed = ? WHERE id = ?`).bind(emailed, id).run();
  }
  await logActivity(c.env, auth.accountId, auth.userId, "notice_posted",
    `Posted a${v.important ? "n important" : ""} notice at ${property.name}: ${v.title}`);

  const row = await c.env.DB.prepare(
    `SELECT n.*, p.name AS property_name FROM building_notices n
       JOIN properties p ON p.id = n.property_id WHERE n.id = ?`).bind(id).first();
  return c.json({ notice: noticeRowToJs(row), emailed, notEmailed }, 201);
});

app.delete("/api/notices/:id", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  let row;
  try {
    row = await c.env.DB.prepare(
      `SELECT n.*, p.name AS property_name FROM building_notices n
         JOIN properties p ON p.id = n.property_id
        WHERE n.id = ? AND n.account_id = ?`
    ).bind(c.req.param("id"), auth.accountId).first();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
  // Another building's notice answers like one that does not exist.
  if (!row || !maySeeProperty(auth, row.property_id)) return c.json({ error: "not_found" }, 404);
  if (row.removed_at) return c.json({ ok: true });
  await c.env.DB.prepare(
    `UPDATE building_notices SET removed_at = CURRENT_TIMESTAMP WHERE id = ? AND removed_at IS NULL`
  ).bind(row.id).run();
  await logActivity(c.env, auth.accountId, auth.userId, "notice_removed",
    `Took down the notice at ${row.property_name}: ${row.title}`);
  return c.json({ ok: true });
});

// Branding/plan/billing for the current account.
app.patch("/api/account", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  const b = await c.req.json(); // { name, subdomain, kind, plan, billing, logoKey, useDefaultMark, theme, trades }
  const sets = [], vals = [];
  if (b.name != null) { sets.push("name = ?"); vals.push(b.name); }

  // Moving to a different address. Held separately from the other fields
  // because it is the only one that changes something outside this database:
  // a hostname at Cloudflare, which has to be taken down at the old name and
  // put up at the new one once the row is written.
  let movedFrom = null, current = null;
  if (b.subdomain != null) {
    current = await c.env.DB.prepare(
      `SELECT subdomain, plan FROM accounts WHERE id = ?`).bind(accountId).first();
    const next = validSubdomain(b.subdomain);
    if (!next) return c.json({ error: "invalid_subdomain" }, 400);
    if (current && next !== current.subdomain) {
      const taken = await c.env.DB.prepare(
        `SELECT id FROM accounts WHERE subdomain = ? AND id <> ?`).bind(next, accountId).first();
      if (taken) return c.json({ error: "subdomain_taken" }, 409);
      sets.push("subdomain = ?"); vals.push(next);
      // The old address is no longer theirs and the new one is not live yet.
      // Carrying "active" across the gap would have the account page telling
      // somebody their address works while it points at nothing.
      sets.push("hostname_status = ?"); vals.push(null);
      sets.push("hostname_error = ?"); vals.push(null);
      movedFrom = current.subdomain;
    }
  }
  if (b.kind != null) {
    if (!ACCOUNT_KINDS.includes(b.kind)) return c.json({ error: "invalid_kind" }, 400);
    sets.push("kind = ?"); vals.push(b.kind);
    // Becoming a kind that cannot be hired has to take the company row with
    // it. Since 031 a general contractor IS a company, and the kind change
    // left that row attached -- so an account could turn itself into a
    // property manager or a building owner and stay on the hireable side of
    // every query, which is one careless join from a landlord appearing on
    // somebody's subcontractor roster. CHECK.sql's m031_others_with counts
    // exactly this.
    //
    // Unless somebody already hires them. Clearing the link then would leave
    // live engagements pointing at a company no account answers for, and the
    // contractor on the other end would never be told. That is a conversation
    // to have with their clients, not a setting to flip.
    if (!HIREABLE_KINDS.includes(b.kind)) {
      try {
        const mine = await c.env.DB.prepare(`SELECT company_id FROM accounts WHERE id = ?`)
          .bind(accountId).first();
        if (mine?.company_id) {
          const hired = await c.env.DB.prepare(
            `SELECT COUNT(*) AS n FROM engagements WHERE company_id = ? AND status != 'ended'`
          ).bind(mine.company_id).first();
          if (hired?.n) return c.json({ error: "hired_by_others", count: hired.n }, 409);
          sets.push("company_id = ?"); vals.push(null);
        }
      } catch (err) { if (!missingSchema(err)) throw err; }
    }
  }
  if (b.plan != null) { sets.push("plan = ?"); vals.push(b.plan); }
  if (b.billing != null) { sets.push("billing = ?"); vals.push(b.billing); }
  if (b.logoKey !== undefined) { sets.push("logo_key = ?"); vals.push(b.logoKey); }
  if (b.useDefaultMark != null) { sets.push("use_default_mark = ?"); vals.push(b.useDefaultMark ? 1 : 0); }
  if (b.theme !== undefined) {
    const theme = validTheme(b.theme);
    if (b.theme != null && !theme) return c.json({ error: "invalid_theme" }, 400);
    sets.push("theme = ?"); vals.push(theme ? JSON.stringify(theme) : null);
  }
  if (b.trades !== undefined) {
    const trades = validTrades(b.trades);
    if (!trades) return c.json({ error: "invalid_trades" }, 400);
    sets.push("trades = ?"); vals.push(JSON.stringify(trades));
  }
  // Who takes an emergency call-out. Checked rather than stored as given:
  // this is the one setting that lets a tenant's tap commit the account to
  // a contractor, so it has to name somebody the account actually works
  // with. Clearing it turns automatic dispatch off, which is the default.
  // 065. Auto-scheduling a turnaround. A plain yes or no with nothing to
  // validate against -- unlike the emergency contractor below, which names
  // somebody and so has to be checked. The choosing is done at the moment a
  // job is raised, against the roster as it stands then.
  if (b.autoTurnaround !== undefined) {
    sets.push("auto_turnaround = ?"); vals.push(b.autoTurnaround ? 1 : 0);
  }
  if (b.emergencyCompanyId !== undefined) {
    const want = b.emergencyCompanyId || null;
    if (want) {
      const eng = await c.env.DB.prepare(
        `SELECT id, status FROM engagements WHERE account_id = ? AND company_id = ?`)
        .bind(accountId, want).first();
      // `onRoster`, not `!== 'ended'`: this is the one setting that lets a
      // tenant's tap commit the account to a contractor, so it has to name
      // somebody who could actually be given the work -- which a paused
      // contractor cannot be, by the same gate the assign route uses.
      if (!eng || !onRoster(eng.status)) return c.json({ error: "not_engaged" }, 400);
    }
    sets.push("emergency_company_id = ?"); vals.push(want);
  }
  if (sets.length) {
    vals.push(accountId);
    try {
      await c.env.DB.prepare(`UPDATE accounts SET ${sets.join(", ")} WHERE id = ?`).bind(...vals).run();
    } catch (err) {
      // Two accounts claiming one address race past the check above and are
      // caught here by the unique index instead. Same answer either way.
      if (movedFrom && /UNIQUE|constraint/i.test(String(err?.message || err))) {
        return c.json({ error: "subdomain_taken" }, 409);
      }
      // A COLUMN A MIGRATION HAS NOT ADDED YET IS ALREADY NAMED, by
      // `app.onError`, which turns one into a 503 `migration_needed` with the
      // file to run on it -- for every route rather than this one. A local
      // copy here would be a second record of one fact, so this rethrows and
      // lets it answer. What was actually wrong was one layer up: the screen
      // read every failure as *"That didn't save. Try again"*, which is false
      // on a database behind the code and told the one person who could fix
      // it nothing.
      throw err;
    }
  }

  const after = await c.env.DB.prepare(
    `SELECT subdomain, hostname_status FROM accounts WHERE id = ?`).bind(accountId).first();
  if (movedFrom) {
    await logActivity(c.env, accountId, c.get("auth").userId, "subdomain_changed",
      `Sign-in address changed from ${movedFrom}.subsub.work to ${after?.subdomain}.subsub.work`,
      { from: movedFrom, to: after?.subdomain });
    moveHostnameAfter(c, { id: accountId, subdomain: after?.subdomain, plan: current?.plan }, movedFrom);
  }
  // The saved address goes back, not the one that was asked for: the browser
  // should show what the database holds, so a rejected or tidied-up value
  // cannot sit on screen looking saved.
  return c.json({ ok: true, subdomain: after?.subdomain || null,
                  hostnameStatus: after?.hostname_status || null });
});

// ---------------------------------------------------------------------------
// Companies + engagements (the "subs" the UI works with)
// ---------------------------------------------------------------------------

// List every company engaged with the current account, composed flat.
app.get("/api/subs", async (c) => {
  const auth = c.get("auth");
  const { accountId } = auth;
  // An owner has no contractor directory -- they see who is coming to their
  // own buildings and nobody else. A scoped property manager is the opposite
  // case: they have to pick somebody, so they get the whole roster even though
  // their buildings are limited.
  const onlyMine = auth.role === "owner" ? `
       AND en.company_id IN (
         SELECT wo.company_id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id
          WHERE j.account_id = ? AND wo.voided_at IS NULL
            AND j.property_id IN (${auth.propertyIds.map(() => "?").join(",") || "NULL"}))` : "";
  const scopeVals = auth.role === "owner" ? [accountId, ...auth.propertyIds] : [];
  const { results } = await c.env.DB.prepare(
    `SELECT co.*, en.id as en_id, en.account_id as en_account_id, en.company_id as en_company_id,
            en.status as en_status, en.doc_review as en_doc_review, en.categories as en_categories,
            en.caps as en_caps, en.rating as en_rating, en.rated_jobs as en_rated_jobs,
            en.accepted as en_accepted, en.declined as en_declined,
            en.auto_schedule as en_auto_schedule, en.notes as en_notes,
            en.engaged_as as en_engaged_as,
            (SELECT group_concat(ep.property_id) FROM engagement_properties ep
              WHERE ep.engagement_id = en.id) as en_property_ids,
            -- Whether anybody is there to answer for this company: a seat on
            -- THIS account, or an account of their own (031 made general
            -- contractors hireable, and theirs is the second kind). It
            -- decides who owns the auto-schedule switch, so the browser is
            -- told the same fact the PATCH route enforces on. A count, never
            -- a name -- who the seat belongs to is already on the roster for
            -- this account's own people and is nobody else's to collect.
            (SELECT COUNT(*) FROM memberships ms
              WHERE ms.company_id = co.id AND ms.account_id = en.account_id
                AND ms.role = 'contractor') as en_seats,
            (SELECT COUNT(*) FROM accounts ac WHERE ac.company_id = co.id) as en_own_account,
            -- DOES ANYBODY ANSWER FOR THIS COMPANY AT ALL -- which is a
            -- different question from the one directly above, and the browser
            -- needs both. en_seats is scoped to this account and asks "is
            -- there somebody *I* can ask?", which is what the auto-schedule
            -- switch turns on. This one is unscoped and asks whether the
            -- company row is theirs rather than ours, which is what decides
            -- whether this account may edit it -- and it is the predicate
            -- companyAnswersForItself enforces on the PATCH route, so the
            -- screen drawing the other one offered a form whose save the
            -- server threw away.
            --
            -- (No backticks in here: this SQL is a template literal, and one
            -- in a comment closes it. Fifth time.)
            --
            -- EXISTS, never COUNT. A count of seats across every account is a
            -- count of how many other people hire them, which is their book
            -- and nobody else's to collect. A bare yes/no is the whole of what
            -- drawing the right form needs.
            (SELECT EXISTS(SELECT 1 FROM memberships ms2
               WHERE ms2.company_id = co.id AND ms2.role = 'contractor')) as en_any_seat
     FROM engagements en JOIN companies co ON co.id = en.company_id
     WHERE en.account_id = ? ${onlyMine}`
  ).bind(accountId, ...scopeVals).all();

  const subs = results.map((r) => composeSub(r, {
    id: r.en_id, account_id: r.en_account_id, company_id: r.en_company_id, status: r.en_status,
    doc_review: r.en_doc_review, categories: r.en_categories, caps: r.en_caps,
    rating: r.en_rating, rated_jobs: r.en_rated_jobs, accepted: r.en_accepted, declined: r.en_declined,
    auto_schedule: r.en_auto_schedule, notes: r.en_notes,
    // NAMED IN THREE PLACES OR IT IS SILENTLY DROPPED: the SELECT, this
    // re-map and the row shape. The first version missed the SELECT, so
    // `engagedAs` read undefined and every handyman came back as a
    // subcontractor -- which is not a visible failure, it is a roster that
    // quietly asks a maintenance worker for a certificate again.
    engaged_as: r.en_engaged_as,
    property_ids: r.en_property_ids,
  }));
  // Reachability is not an engagement column, so it is attached after
  // composeSub rather than threaded through it.
  subs.forEach((sub, i) => {
    sub.hasPortal = hasPortal({
      hasSeat: (results[i].en_seats || 0) > 0,
      ownsAccount: (results[i].en_own_account || 0) > 0,
    });
    // Whose record this is. Same shape, unscoped seat -- see the query.
    sub.answersForItself = hasPortal({
      hasSeat: !!results[i].en_any_seat,
      ownsAccount: (results[i].en_own_account || 0) > 0,
    });
  });

  // What each company's paperwork says, so the roster can colour itself and
  // assignment can ask about the JOB'S date rather than today's. One query for
  // the whole roster: per-company would be a round trip each and this is the
  // list screen.
  try {
    const ids = subs.map((x) => x.id);
    if (ids.length) {
      const { results: docRows } = await c.env.DB.prepare(
        `SELECT * FROM company_docs
          WHERE superseded_at IS NULL AND company_id IN (${ids.map(() => "?").join(",")})
          ORDER BY company_id, kind, uploaded_at DESC`
      ).bind(...ids).all();
      const byCompany = {};
      for (const r of docRows || []) {
        const per = (byCompany[r.company_id] ||= {});
        if (!per[r.kind]) per[r.kind] = r;
      }
      const today = new Date().toISOString().slice(0, 10);
      // AN AGREEMENT COUNTS ONLY ONCE THIS ACCOUNT HAS ASKED FOR ONE.
      //
      // `DOC_KINDS` counted it against every subcontractor on every roster,
      // so a sub whose client never sent an agreement -- which is most of
      // them -- sat permanently short of complete over a document only the
      // hiring account could produce. `docs.js` already excused that on the
      // sub's own screens and could not excuse it here, because whether an
      // agreement is wanted is this account's call. Issuing one IS that call.
      //
      // One read for the whole roster: asking per row would be a query per
      // contractor on every page load.
      let agreements = {};
      try { agreements = await liveAgreementsFor(c.env, auth.accountId); }
      catch (err) {
        // A database without 052 keeps the roster it always had, which is
        // every kind counting -- the behaviour before this shipped.
        if (!missingSchema(err)) throw err;
      }
      subs.forEach((sub, i) => {
        sub.docs = docShapeWithLegacy(byCompany[sub.id] || {}, results[i]);
        const ag = agreements[sub.id] || null;
        sub.agreement = ag ? {
          id: ag.id, status: ag.status, source: ag.source,
          waitingOn: waitingOn(ag), inForce: inForce(ag),
          signedAt: ag.signed_at || null, countersignedAt: ag.countersigned_at || null,
        } : null;
        // Drawn as the document `docs.js` understands, so the roster does not
        // need a second code path for one of the four rows. A SubSub
        // agreement is not a file in `company_docs` and never will be.
        const shape = agreementDocShape(ag);
        if (shape) sub.docs = { ...sub.docs, contract: shape };
        // Today's verdict, for the roster. Assignment recomputes against the
        // job's date, which is the only number that decides whether a
        // certificate actually covers the work.
        // NARROWED BY WHAT THEY ARE TO THIS ACCOUNT. `kindsFor` decides
        // whether a signed agreement counts; `requiredDocsFor` then takes
        // insurance and a bond off a handyman. Composed rather than replaced,
        // so there is still one place deciding what a document kind IS.
        const st = companyDocStatus(sub.docs, today,
          requiredDocsFor(sub.engagedAs, kindsFor(ag)));
        sub.docState = st.state;
        sub.docAssignable = st.assignable;
        sub.docSoonest = st.soonest;
      });
    }
  } catch (err) {
    // A database without 037 keeps the roster it always had.
    if (!missingSchema(err)) throw err;
    console.warn("[company_docs] roster detail unavailable:", err?.message || err);
  }
  // PREFERRED SUB, read off the referral ledger rather than stored beside it:
  // a sub holding a cash reward nobody voided brought a paying account onto
  // SubSub. One query for the roster, and a database without 075 simply has
  // no badges. Attached here and carried by name in hydrateAccount, which
  // drops anything its whitelists do not name.
  try {
    const ids = subs.map((x) => x.id);
    if (ids.length) {
      const { results: pref } = await c.env.DB.prepare(
        `SELECT DISTINCT r.beneficiary_company_id AS company_id FROM referral_rewards r
          WHERE r.kind = 'sub_cash' AND r.status <> 'void'
            AND r.beneficiary_company_id IN (${ids.map(() => "?").join(",")})`
      ).bind(...ids).all();
      const set = new Set((pref || []).map((r) => r.company_id));
      subs.forEach((sub) => { sub.preferredSub = set.has(sub.id); });
    }
  } catch (err) {
    if (!missingSchema(err)) throw err;
  }
  return c.json(subs);
});

// Invite/add a company. Dedupes on license number first, then email —
// an existing company only gets a new engagement, never a duplicate row.
app.post("/api/subs", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const body = await c.req.json();
  const licenseKey = (body.license || "").trim().toUpperCase();

  let company = null;
  if (licenseKey) {
    company = await c.env.DB.prepare(`SELECT * FROM companies WHERE UPPER(TRIM(license)) = ?`).bind(licenseKey).first();
  }
  if (!company && body.email) {
    company = await c.env.DB.prepare(`SELECT * FROM companies WHERE lower(email) = lower(?)`).bind(body.email).first();
  }

  let companyId;
  if (company) {
    companyId = company.id;
  } else {
    companyId = uid();
    await c.env.DB.prepare(
      `INSERT INTO companies (id, company, contact, phone, email, license, ubi, city, state, zip)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(companyId, body.company || "", body.contact || null, body.phone || null, body.email || null,
      body.license || null, body.ubi || null, body.city || null, body.state || null, body.zip || null).run();
  }

  const existingEngagement = await c.env.DB.prepare(
    `SELECT id FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (existingEngagement) return c.json({ error: "already_engaged", companyId }, 409);

  const engagementId = uid();
  await c.env.DB.prepare(
    `INSERT INTO engagements (id, account_id, company_id, status, categories, caps)
     VALUES (?, ?, ?, 'invited', ?, ?)`
  ).bind(engagementId, accountId, companyId, JSON.stringify(body.categories || []), JSON.stringify(body.caps || [])).run();

  // Only for a genuinely NEW company: crews, coverage, doc flags, etc. from
  // the invite form. An EXISTING (deduped) company keeps its established
  // profile — categories/caps above are the only things that are ever
  // this account's own to set on someone else's shared company record.
  if (!company) {
    await applySubPatch(c.env.DB, companyId, engagementId, body);
  }

  await logEvent(c.env, accountId, userId, "engagement.invited", engagementId, { companyId, reused: !!company });
  await logActivity(c.env, accountId, userId, "sub_added",
    `Added ${await companyName(c.env.DB, companyId)}`);

  // And tell them. Adding a subcontractor by hand used to send nothing at
  // all: a company row, an engagement, silence. They had no login, no
  // notification and no way to take over their own profile -- the account
  // that typed them in owned their details forever, and the contractor
  // found out they had been added by being told over the phone, if at all.
  //
  // This is the fourth of the four ways somebody joins an account, and the
  // last one that was still silent. It goes through the same user-invite
  // machinery as adding a manager: a seat, then a link that sets a
  // password.
  let invite = { invited: false, reason: "no_email" };
  const inviteEmail = realEmail(body.email);
  if (inviteEmail) {
    let user = await c.env.DB.prepare(`SELECT * FROM users WHERE lower(email) = lower(?)`).bind(inviteEmail).first();
    if (!user) {
      const newUserId = uid();
      await c.env.DB.prepare(`INSERT INTO users (id, name, email, phone) VALUES (?, ?, ?, ?)`)
        .bind(newUserId, body.contact || body.company || inviteEmail, inviteEmail, normalizePhone(body.phone)).run();
      user = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(newUserId).first();
    } else if (!user.phone && normalizePhone(body.phone)) {
      // A number typed on this form is worth keeping, and it is what the
      // text below is sent to.
      await c.env.DB.prepare(`UPDATE users SET phone = ? WHERE id = ?`)
        .bind(normalizePhone(body.phone), user.id).run();
      user = { ...user, phone: normalizePhone(body.phone) };
    }
    // The seat, so the link they follow lands on their own portal rather
    // than on a sign-in page that does not recognise them.
    try {
      await c.env.DB.prepare(
        `INSERT INTO memberships (id, user_id, account_id, role, company_id) VALUES (?, ?, ?, 'contractor', ?)`
      ).bind(uid(), user.id, accountId, companyId).run();
    } catch (err) {
      if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
    }
    const by = await c.env.DB.prepare(`SELECT id, name FROM users WHERE id = ?`).bind(userId).first();
    invite = await inviteAccountUser(c, { accountId, user, role: "contractor", invitedBy: by });
  }

  return c.json({ companyId, engagementId, reused: !!company, invite }, 201);
});

// Routes a flat patch to companies/engagements exactly like splitPatch() on
// the client, and writes both halves. Shared by PATCH /api/subs/:companyId
// (editing an existing sub) and POST /api/subs (a new sub's initial fields —
// crews, coverage, doc flags, categories — beyond just its identity).
const SUB_COMPANY_COL = {
  company: "company", contact: "contact", phone: "phone", email: "email",
  license: "license", ubi: "ubi", city: "city", state: "state", zip: "zip",
  mailStreet: "mail_street", mailCity: "mail_city", mailState: "mail_state", mailZip: "mail_zip",
  crews: "crews", coverage: "coverage", available: "available",
  unavailableDays: "unavailable_days", warranty: "warranty",
  insurance: "insurance", bond: "bond", contract: "contract", w9: "w9",
  docFiles: "doc_files", notify: "notify",
};
const SUB_COMPANY_JSON_FIELDS = new Set(["crews", "coverage", "unavailableDays", "warranty", "docFiles", "notify"]);
// `status` is deliberately NOT here. Removing somebody takes a seat away and
// clears their auto-schedule flag as well as writing the column, and a PATCH
// that wrote the word and nothing else would leave a standing permission
// against a contractor nobody is watching. POST /api/subs/:companyId/end is
// the one door, and it does the whole job.
const SUB_ENGAGEMENT_COL = {
  docReview: "doc_review", categories: "categories", caps: "caps",
  rating: "rating", ratedJobs: "rated_jobs", accepted: "accepted", declined: "declined",
  autoSchedule: "auto_schedule", notes: "notes",
  // 058. What they are to THIS account. Validated by the route before it
  // reaches here -- this map only says which column a key writes to.
  engagedAs: "engaged_as",
};
const SUB_ENGAGEMENT_JSON_FIELDS = new Set(["docReview", "categories", "caps"]);

// Does anybody answer for this company?
//
// `companies` is a shared row: one name, one contact, one licence, one set of
// document booleans, read by EVERY account that engages them. So "I have them
// on my roster" is enough to edit a record I typed in myself, and is not
// enough to rewrite a company that has its own people.
//
// Deliberately NOT the scoped seat count the roster and the auto-schedule
// branch use. Those ask "is there somebody *I* can ask?", which is per-account
// on purpose. This asks "does anybody answer for this company at all?", so a
// roofer whose only seat is on another general contractor's account is still
// protected from this one. Scoping it would have left exactly that hole.
async function companyAnswersForItself(env, companyId) {
  const r = await env.DB.prepare(
    `SELECT (SELECT COUNT(*) FROM memberships WHERE company_id = ? AND role = 'contractor') AS seats,
            (SELECT COUNT(*) FROM accounts WHERE company_id = ?) AS own_account`
  ).bind(companyId, companyId).first();
  return hasPortal({
    hasSeat: (r?.seats || 0) > 0,
    ownsAccount: (r?.own_account || 0) > 0,
  });
}

async function applySubPatch(db, companyId, engagementId, patch) {
  const coPatch = {}, enPatch = {};
  for (const [k, v] of Object.entries(patch)) {
    (ENGAGEMENT_FIELDS.has(k) ? enPatch : coPatch)[k] = v;
  }

  const coSets = [], coVals = [];
  for (const [k, v] of Object.entries(coPatch)) {
    if (!SUB_COMPANY_COL[k]) continue;
    coSets.push(`${SUB_COMPANY_COL[k]} = ?`);
    coVals.push(SUB_COMPANY_JSON_FIELDS.has(k) ? JSON.stringify(v) : (typeof v === "boolean" ? (v ? 1 : 0) : v));
  }
  if (coSets.length) {
    coVals.push(companyId);
    await db.prepare(`UPDATE companies SET ${coSets.join(", ")} WHERE id = ?`).bind(...coVals).run();
  }

  const enSets = [], enVals = [];
  for (const [k, v] of Object.entries(enPatch)) {
    if (!SUB_ENGAGEMENT_COL[k]) continue;
    enSets.push(`${SUB_ENGAGEMENT_COL[k]} = ?`);
    enVals.push(SUB_ENGAGEMENT_JSON_FIELDS.has(k) ? JSON.stringify(v) : (typeof v === "boolean" ? (v ? 1 : 0) : v));
  }
  if (enSets.length) {
    enVals.push(engagementId);
    await db.prepare(`UPDATE engagements SET ${enSets.join(", ")} WHERE id = ?`).bind(...enVals).run();
  }
}

app.patch("/api/subs/:companyId", async (c) => {
  const auth = c.get("auth");
  const { accountId, userId } = auth;
  const companyId = c.req.param("companyId");
  if (auth.role === "contractor" && auth.companyId !== companyId) return c.json({ error: "forbidden" }, 403);
  const patch = await c.req.json();

  const engagement = await c.env.DB.prepare(
    `SELECT id FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (!engagement) return c.json({ error: "not_found" }, 404);

  // WHAT THEY ARE TO THIS ACCOUNT, and both halves are checked here because
  // the column is what excuses a document.
  //
  // A handyman is not asked for insurance, a bond or a licence -- so a route
  // that took the word on trust would let any account relabel somebody and
  // walk the whole compliance gate. `mayEngageHandyman` is the second half:
  // a handyman is a maintenance worker for a BUILDING, so an account with no
  // building list has nothing for one to do, and CHECK.sql counts a row that
  // got past this.
  if ("engagedAs" in patch) {
    if (!isEngagedAs(patch.engagedAs)) return c.json({ error: "bad_engaged_as" }, 400);
    if (isHandyman(patch.engagedAs)) {
      const acct = await c.env.DB.prepare(`SELECT kind FROM accounts WHERE id = ?`)
        .bind(accountId).first();
      if (!mayEngageHandyman(acct?.kind)) return c.json({ error: "not_a_handyman_account" }, 409);
    }
  }

  // Auto-schedule books work to somebody's calendar as accepted, with no
  // buttons on their side. Hiding the toggle from the roster is not a
  // control -- this is. See shared/autoschedule.js for why the ON direction
  // needs a consenting party and OFF never does.
  if ("autoSchedule" in patch) {
    const seats = await c.env.DB.prepare(
      `SELECT (SELECT COUNT(*) FROM memberships ms
                WHERE ms.company_id = ? AND ms.account_id = ? AND ms.role = 'contractor') AS seats,
              (SELECT COUNT(*) FROM accounts ac WHERE ac.company_id = ?) AS own_account`
    ).bind(companyId, accountId, companyId).first();
    const verdict = canSetAuto({
      side: auth.role === "contractor" ? "contractor" : "hiring",
      on: !!patch.autoSchedule,
      portal: hasPortal({
        hasSeat: (seats?.seats || 0) > 0,
        ownsAccount: (seats?.own_account || 0) > 0,
      }),
    });
    if (!verdict.ok) {
      return c.json({ error: verdict.reason, detail: AUTO_DENY_TEXT[verdict.reason] }, 409);
    }
  }

  // Their record, or yours?
  //
  // The engagement half -- the trades you use them for, your capabilities,
  // your rating, your notes, which buildings you scope them to -- is yours and
  // stays writable. The company half is theirs the moment anybody answers for
  // it, and until now an engagement alone was enough to overwrite it: their
  // name, their contact, their phone, their licence, their crews, their
  // coverage, for every other account that hires them.
  //
  // It also closed a back door. `mayWriteCompanyDocs` guards
  // POST/DELETE /api/subs/:id/documents/:kind because those booleans decide
  // whether somebody can be assigned work -- and this route writes the same
  // columns (`insurance`, `bond`, `contract`, `w9`, `docFiles`) from a plain
  // PATCH, with no such check and no test for an ended engagement.
  //
  // Refused rather than quietly dropped: a save that reports success and
  // writes nothing is how somebody re-types the same correction three times.
  //
  // AND SUPPORT IS THE ONE CALLER IT WAS NEVER MEANT TO REFUSE. The rule stops
  // one hiring account rewriting another business's record; a staff member
  // standing in the account is not that. `staffMayWriteShared` says why at
  // length -- it reads the impersonation session row rather than anything the
  // caller sends, and only for a team seat. Recorded rather than silent,
  // because the banner across the top of that screen promises actions are.
  const editingSelf = auth.role === "contractor" && auth.companyId === companyId;
  let staffOverrode = null;
  if (!editingSelf) {
    const coKeys = Object.keys(patch).filter((k) => !ENGAGEMENT_FIELDS.has(k) && SUB_COMPANY_COL[k]);
    if (coKeys.length && await companyAnswersForItself(c.env, companyId)) {
      if (!staffMayWriteShared(auth)) {
        return c.json({ error: "company_not_yours", fields: coKeys }, 409);
      }
      staffOverrode = coKeys;
    }
  }

  await applySubPatch(c.env.DB, companyId, engagement.id, patch);

  await logEvent(c.env, accountId, userId, "sub.updated", companyId, { fields: Object.keys(patch) });
  // A SEPARATE RECORD, not a flag on the one above, because it is a different
  // event: somebody else's shared company row was written by SubSub rather
  // than by the account, and *which fields* is the whole of what anybody would
  // ask afterwards. `account_id` is the account it was done from and
  // `actor_id` is the seat; the staff user is named in the payload, which is
  // the only place the real actor exists.
  if (staffOverrode) {
    await logEvent(c.env, accountId, userId, "sub.company_written_by_staff", companyId,
      { fields: staffOverrode, staffUserId: auth.impersonatedBy, seatRole: auth.role });
  }
  return c.json({ ok: true, staffOverrode });
});

// ---------------------------------------------------------------------------
// License verification. WA (L&I, data.wa.gov) was the original, hand-built
// integration and its field names come from confirmed dataset knowledge.
// The other six states below (STATE_LICENSING_APIS.md's "Tier 1") are new:
// their dataset IDs and field names are best-effort, from search results,
// NOT a live schema check — this sandbox's network policy blocks
// *.state-domains the same way it blocks data.wa.gov, so none of this has
// been exercised against a live response. Every result carries
// `fieldMappingVerified` so callers (and the UI) can tell confirmed WA
// parsing apart from best-effort parsing elsewhere, and the full raw
// response is always stored — if a field name below is wrong, the raw
// data is still there to fix it from, not lost.
//
// Coverage caveats worth knowing before trusting a result, from the
// survey doc: CT/IA have no insurance or bond fields at all (registration-
// only); IL's dataset only covers roofing (Illinois has no general
// contractor license); TX's TDLR dataset has NO general-contractor
// license at all (only trades like electrical/HVAC); DC's is a general
// business-license registry, not a dedicated contractor board.
// ---------------------------------------------------------------------------

const SOCRATA_STATES = {
  WA: {
    base: "https://data.wa.gov/resource", licenseField: "contractorlicensenumber",
    datasets: { general: "m8qx-ubtq", insurance: "ciwg-agsx", bond: "bzff-4fmt" },
    fieldMappingVerified: true,
    map: (lic, insuranceRows, bondRows) => {
      const today = new Date().toISOString().slice(0, 10);
      const current = (rows, endField) =>
        rows.filter((r) => !r.cancel_date && (!r[endField] || r[endField].slice(0, 10) >= today))
          .sort((a, b) => (b.effective_date || "").localeCompare(a.effective_date || ""))[0] || null;
      return {
        businessName: lic.businessname, status: lic.contractorlicensestatus,
        licenseType: lic.contractorlicensetypecodedesc, ubi: lic.ubi,
        effectiveDate: lic.licenseeffectivedate?.slice(0, 10),
        expirationDate: lic.licenseexpirationdate?.slice(0, 10),
        suspendDate: lic.contractorlicensesuspenddate?.slice(0, 10) || null,
        principal: lic.primaryprincipalname,
        insurance: current(insuranceRows, "insurance_expiration_date"),
        bond: current(bondRows, "bond_expiration_date"),
      };
    },
  },
  OR: {
    base: "https://data.oregon.gov/resource", licenseField: "ccb_number",
    datasets: { general: "g77e-6bhs" }, fieldMappingVerified: false,
    // Single dataset reportedly carries bond + insurance inline — no
    // second/third fetch needed if this field mapping holds up.
    map: (lic) => ({
      businessName: lic.business_name || lic.dba_name, status: lic.status,
      licenseType: lic.endorsement || lic.license_type,
      effectiveDate: lic.issue_date?.slice(0, 10), expirationDate: lic.expiration_date?.slice(0, 10),
      suspendDate: null, principal: lic.principal_name,
      insurance: lic.insurance_company ? { insurance_company: lic.insurance_company, coverage_amount: lic.insurance_amount } : null,
      bond: lic.bond_company ? { surety_company: lic.bond_company, bond_amount: lic.bond_amount } : null,
    }),
  },
  CT: {
    base: "https://data.ct.gov/resource", licenseField: "license_number",
    datasets: { general: "5r9m-qgni" }, fieldMappingVerified: false,
    map: (lic) => ({
      businessName: lic.business_name, status: lic.license_status, licenseType: "Home Improvement Contractor",
      effectiveDate: lic.issue_date?.slice(0, 10), expirationDate: lic.expiration_date?.slice(0, 10),
      suspendDate: null, principal: null, insurance: null, bond: null, // CT dataset has no bond/insurance fields
    }),
  },
  IA: {
    base: "https://data.iowa.gov/resource", licenseField: "registration_number",
    datasets: { general: "dpf3-iz94" }, fieldMappingVerified: false,
    map: (lic) => ({
      businessName: lic.business_name, status: "ACTIVE", // dataset is pre-filtered to active-only
      licenseType: lic.primary_activity,
      effectiveDate: lic.issue_date?.slice(0, 10), expirationDate: lic.expire_date?.slice(0, 10),
      suspendDate: null, principal: [lic.first_name, lic.last_name].filter(Boolean).join(" ") || null,
      insurance: null, bond: null, // registration roster only — no bond/insurance in this dataset
    }),
  },
  IL: {
    base: "https://data.illinois.gov/resource", licenseField: "license_number",
    datasets: { general: "pzzh-kp68" }, fieldMappingVerified: false,
    // No statewide GC license in Illinois — this only covers roofing
    // contractors within IDFPR's combined 100+-profession dataset.
    map: (lic) => ({
      businessName: lic.name || lic.business_name, status: lic.license_status,
      licenseType: lic.profession || "Roofing Contractor",
      effectiveDate: lic.original_issue_date?.slice(0, 10), expirationDate: lic.expiration_date?.slice(0, 10),
      suspendDate: null, principal: null, insurance: null, bond: null,
    }),
  },
  TX: {
    base: "https://data.texas.gov/resource", licenseField: "license_number",
    datasets: { general: "7358-krk7" }, fieldMappingVerified: false,
    // Texas has NO general-contractor license — only useful for
    // TDLR-regulated trades (electrical, HVAC, etc).
    map: (lic) => ({
      businessName: lic.business_name || lic.licensee_name, status: lic.license_status,
      licenseType: lic.license_type || lic.endorsement,
      effectiveDate: lic.original_issue_date?.slice(0, 10), expirationDate: lic.expiration_date?.slice(0, 10),
      suspendDate: null, principal: null, insurance: null, bond: null,
    }),
  },
};

// Datasets are public open-data endpoints outside our control — a block
// page, rate-limit response, or outage can come back as non-JSON even on a
// 200. Never let that throw past this function; surface it as a check
// failure instead of a 500.
async function fetchJsonSafe(url) {
  let resp;
  try {
    resp = await fetch(url);
  } catch (err) {
    return { ok: false, error: String(err?.message || err) };
  }
  const text = await resp.text();
  if (!resp.ok) return { ok: false, error: `HTTP ${resp.status}: ${text.slice(0, 200)}` };
  try {
    return { ok: true, data: JSON.parse(text) };
  } catch {
    return { ok: false, error: `non-JSON response: ${text.slice(0, 200)}` };
  }
}

async function verifySocrataState(cfg, licenseNumber) {
  const q = `?${cfg.licenseField}=${encodeURIComponent(licenseNumber)}`;
  const rows = {};
  for (const [key, id] of Object.entries(cfg.datasets)) {
    const res = await fetchJsonSafe(`${cfg.base}/${id}.json${q}`);
    if (!res.ok) return { found: false, status: "CHECK_FAILED", error: res.error, fieldMappingVerified: cfg.fieldMappingVerified };
    rows[key] = res.data;
  }
  const lic = rows.general?.[0];
  // Say so explicitly. A bare { found: false } has no status at all, and the
  // screens that describe a check used to read .status straight off it.
  if (!lic) return { found: false, status: "NOT_FOUND", fieldMappingVerified: cfg.fieldMappingVerified };
  return { found: true, fieldMappingVerified: cfg.fieldMappingVerified, raw: lic, ...cfg.map(lic, rows.insurance || [], rows.bond || []) };
}

// DC: ArcGIS Feature Service, not Socrata — different query shape entirely.
async function verifyDC(licenseNumber) {
  const url = "https://maps2.dcgis.dc.gov/dcgis/rest/services/FEEDS/DCRA/FeatureServer/0/query"
    + `?where=${encodeURIComponent(`LICENSENUMBER='${licenseNumber.replace(/'/g, "''")}'`)}`
    + "&outFields=*&f=json";
  const res = await fetchJsonSafe(url);
  if (!res.ok) return { found: false, status: "CHECK_FAILED", error: res.error, fieldMappingVerified: false };
  const attrs = res.data?.features?.[0]?.attributes;
  if (!attrs) return { found: false, status: "NOT_FOUND", fieldMappingVerified: false };
  const esriDate = (ms) => (ms ? new Date(ms).toISOString().slice(0, 10) : null);
  return {
    found: true, fieldMappingVerified: false, raw: attrs,
    businessName: attrs.BUSINESSNAME || attrs.LICENSEE, status: attrs.LICENSESTATUS,
    licenseType: attrs.LICENSECATEGORY || attrs.LICENSETYPE,
    effectiveDate: esriDate(attrs.ISSUEDATE), expirationDate: esriDate(attrs.EXPIRATIONDATE),
    suspendDate: null, principal: null, insurance: null, bond: null,
  };
}

// The state's own registry, and nothing else. Kept separate so the chain in
// licenses.js can ask it first and only fall through when it could not
// answer -- a paid verifier saying "active" over a state registry saying
// "no such licence" is worse than having no verifier.
async function askStateRegistry(state, licenseNumber) {
  const code = (state || "").trim().toUpperCase();
  if (code === "DC") return verifyDC(licenseNumber);
  const cfg = SOCRATA_STATES[code];
  if (!cfg) return { found: false, status: "UNSUPPORTED_STATE", supportedStates: [...Object.keys(SOCRATA_STATES), "DC"] };
  return verifySocrataState(cfg, licenseNumber);
}

// ===========================================================================
// THE MARKETING SITE'S FREE TOOLS. Public, rate-limited per IP, and never a
// door into SubSub's own data: the licence checker reads the STATE's public
// registry, never the companies table, and the handyman calculator is
// arithmetic the browser already did. The rules are shared/licenselookup.js.
// ===========================================================================

// A provider answers two questions about one state. Washington is the state's
// own open data; a 50-state verification partner slots in here as one more
// provider when LICENSE_LOOKUP_PARTNER names one of worker/licenses.js's
// PROVIDERS and its key is set. byName may be null -- most partners verify by
// number only -- and the route says so rather than pretending to search.
const LOOKUP_PROVIDERS = {
  WA: {
    id: "wa-lni", label: "Washington State L&I",
    byLicense: (env, license) => askStateRegistry("WA", license),
    byName: (env, name) => socrataNameSearch(SOCRATA_STATES.WA, name),
  },
};
function lookupProviderFor(env, state) {
  if (!isLiveState(state)) return null;
  if (LOOKUP_PROVIDERS[state]) return LOOKUP_PROVIDERS[state];
  const want = String(env.LICENSE_LOOKUP_PARTNER || "").trim();
  const partner = want && configuredProviders(env).find((p) => p.id === want);
  if (!partner) return null;
  return { id: partner.id, label: partner.label, byName: null,
    byLicense: (env2, license) => askProvider(partner, { state, license }) };
}

// The registry's own search, by business name. A CONTAINS match on the state's
// public data -- which is what the state's own lookup page offers -- and never
// anything of SubSub's: this reads data.wa.gov, not the companies table, so it
// is not the directory this product refuses. Ten rows, no status in them.
async function socrataNameSearch(cfg, name) {
  const q = String(name).toUpperCase().replace(/'/g, "''").replace(/[%_]/g, "");
  const where = `upper(businessname) like '%${q}%'`;
  const url = `${cfg.base}/${cfg.datasets.general}.json?$where=${encodeURIComponent(where)}`
    + `&$order=${encodeURIComponent("businessname")}&$limit=${MAX_MATCHES}`;
  const res = await fetchJsonSafe(url);
  if (!res.ok) return { ok: false, error: res.error };
  return { ok: true, rows: (res.data || []).map((r) => ({
    businessName: r.businessname || null,
    licenseNumber: r[cfg.licenseField] || null,
    city: r.city || r.businessaddresscity || null,
  })) };
}

async function storeLead(env, { email, tool, state, detail, refCode }) {
  const id = uid();
  await env.DB.prepare(
    `INSERT INTO leads (id, email, tool, state, detail, ref_code) VALUES (?, ?, ?, ?, ?, ?)`
  ).bind(id, email, tool, state || null, JSON.stringify(detail || {}), refCode || null).run();
  // Told to a person, because a lead nobody hears about is a row in a table.
  const to = String(env.LEADS_EMAIL || "").trim();
  if (to) {
    const subject = `[Lead] ${tool === "check" ? "Licence check" : "Handyman limits"} · ${state || "no state"} · ${email}`;
    const text = [`${email} used ${tool === "check" ? "subsub.work/check" : "subsub.work/handyman-limits"}.`,
      `State: ${state || "—"}`, `Asked: ${JSON.stringify(detail || {})}`,
      refCode ? `Arrived on referral code ${refCode}.` : ""].filter(Boolean).join("\n");
    const res = await sendEmail(env, { to, subject, text, replyTo: email });
    if (res?.ok) await env.DB.prepare(`UPDATE leads SET notified = 1 WHERE id = ?`).bind(id).run();
  }
  return id;
}

// THE CHECKER. Without an email: whether there is a record, and whose. With
// one: the status, the expiry, the bond and the insurance, and the address is
// kept as a lead tagged with the tool and the state.
app.post("/api/public/license-lookup", async (c) => {
  const limit = await rateLimit(c.env, "public-lookup", clientIp(c), { limit: 30, windowMinutes: 10 });
  if (!limit.ok) return c.json({ error: "slow_down" }, 429);
  const b = await c.req.json().catch(() => ({}));
  const q = readLookup(b);
  if (q.error) return c.json({ error: q.error }, 400);
  const provider = lookupProviderFor(c.env, q.state);
  if (!provider) {
    return c.json({ error: "state_not_live", state: q.state, live: LIVE_STATES }, 404);
  }
  const email = String(b.email || "").trim().toLowerCase();
  const wantFull = !!email;
  if (wantFull && !validLeadEmail(email)) return c.json({ error: "bad_email" }, 400);

  // By name: a list of matches to choose from. Never the full answer, even
  // with an email -- that is asked for by number, once a match is chosen.
  if (q.name) {
    if (!provider.byName) return c.json({ error: "name_search_unavailable", source: provider.label }, 400);
    const r = await provider.byName(c.env, q.name);
    if (!r.ok) return c.json({ error: "registry_unavailable", source: provider.label }, 502);
    return c.json({ state: q.state, source: provider.label, matches: r.rows.map(previewOf) });
  }

  const rec = await provider.byLicense(c.env, q.license);
  if (rec?.status === "CHECK_FAILED") return c.json({ error: "registry_unavailable", source: provider.label }, 502);
  const full = fullOf({ ...rec, licenseNumber: rec?.licenseNumber || q.license });
  if (!wantFull) {
    return c.json({ state: q.state, source: provider.label, found: full.found,
      preview: full.found ? previewOf({ businessName: full.name, licenseNumber: full.license }) : null });
  }
  let leadSaved = true;
  try {
    await storeLead(c.env, { email, tool: "check", state: q.state,
      detail: { license: q.license }, refCode: normalizeCode(b.ref) || null });
  } catch (err) {
    if (!missingSchema(err)) throw err;
    leadSaved = false;   // a database without 076 still answers
  }
  return c.json({ state: q.state, source: provider.label, full, verdict: verdictText(full, q.state), leadSaved });
});

// THE CALCULATOR'S EMAIL, and "tell me when my state is live" on a check page.
// The arithmetic happens in the browser off the same handycap.js the app uses;
// this keeps the address and emails the visitor what they asked for.
app.post("/api/public/leads", async (c) => {
  const limit = await rateLimit(c.env, "public-lead", clientIp(c), { limit: 10, windowMinutes: 10 });
  if (!limit.ok) return c.json({ error: "slow_down" }, 429);
  const b = await c.req.json().catch(() => ({}));
  const email = String(b.email || "").trim().toLowerCase();
  if (!validLeadEmail(email)) return c.json({ error: "bad_email" }, 400);
  if (!isLeadTool(b.tool)) return c.json({ error: "bad_tool" }, 400);
  const state = normalizeState(b.state) || null;
  const raw = b.detail && typeof b.detail === "object" ? b.detail : {};
  const detail = {};
  for (const k of ["jobValue", "jobType", "notifyWhenLive", "license"]) {
    if (raw[k] !== undefined) detail[k] = typeof raw[k] === "string" ? raw[k].slice(0, 80) : raw[k];
  }
  try {
    await storeLead(c.env, { email, tool: b.tool, state, detail, refCode: normalizeCode(b.ref) || null });
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }
  // The visitor gets the copy they asked for. The words are the shared
  // module's, so the email cannot say something the page did not.
  if (b.tool === "handyman_limits" && state) {
    const t = handyVerdict({ state, jobValue: detail.jobValue, jobType: detail.jobType });
    if (t) {
      const text = [`Your handyman limit check for ${stateName(state) || state}:`, "",
        t.answer, t.head, t.why, t.note || "", "",
        "Not legal advice. Verify with your state licensing board before relying on it.", "",
        "SubSub keeps your subs, their licenses and their insurance in one place: https://subsub.work/"].filter((x) => x !== null).join("\n");
      await sendEmail(c.env, { to: email, subject: `Handyman limits in ${stateName(state) || state}`, text });
    }
  }
  return c.json({ ok: true });
});

async function verifyLicenseForState(env, state, licenseNumber) {
  return verifyWithFallback(env, {
    state: (state || "").trim().toUpperCase(),
    license: licenseNumber,
    askState: askStateRegistry,
  });
}

async function storeLicenseCheck(db, companyId, state, result) {
  // Every attempt is a row in the history, failures included -- "we tried
  // on the 9th and L&I did not answer" is part of the record. What the
  // company row says is a different question, and a failed attempt does not
  // get to answer it over a real one (nextStoredCheck says why).
  const bond = bondView(result.bond), insurance = insuranceView(result.insurance);
  await db.prepare(
    `INSERT INTO license_checks
      (company_id, state, status, license_type, effective_date, expiration_date, suspend_date,
       bond_amount_cents, bond_surety, insurance_coverage_cents, insurance_carrier, field_mapping_verified, raw)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    companyId, state, result.status ?? (result.found ? null : "NOT_FOUND"), result.licenseType ?? null,
    result.effectiveDate ?? null, result.expirationDate ?? null, result.suspendDate ?? null,
    bond?.amount != null ? Math.round(bond.amount * 100) : null,
    bond?.surety ?? null,
    insurance?.coverage != null ? Math.round(insurance.coverage * 100) : null,
    insurance?.carrier ?? null,
    result.fieldMappingVerified ? 1 : 0,
    JSON.stringify(result)
  ).run();
  const row = await db.prepare(`SELECT license, license_check FROM companies WHERE id = ?`).bind(companyId).first();
  const { stored, kept } = nextStoredCheck(parseJson(row?.license_check, null), result);
  const view = checkView(stored, row?.license || null);
  await db.prepare(`UPDATE companies SET license_check = ? WHERE id = ?`)
    .bind(JSON.stringify(view), companyId).run();
  return { stored: view, kept };
}

// ===========================================================================
// Taking a contractor off your roster.
//
// THE ENGAGEMENT ENDS; NOTHING IS DELETED. `engagements.status` has had
// `ended` since the start and every read in this Worker already guards on it
// -- and nothing ever wrote it, so the state the schema was built for was
// unreachable. This is the door.
//
// Three things must survive, and each one is a rule already written down here:
//
//   `companies` IS SHARED. One name, one licence, one set of documents, read
//   by every account that engages them -- and they may have their own login.
//   Deleting that row to tidy one roster takes a contractor off every other
//   roster they are on.
//
//   THE JOB HISTORY STAYS. "Were they insured on the day of that job" is the
//   question a dispute asks, and the work orders, the releases, the completion
//   events and the documents-on-the-day are what answer it. Same rule the
//   handover follows: a job an account ran is a job it may later be asked to
//   account for.
//
//   AND THEIR DOCUMENTS ARE THEIRS. A certificate is the contractor's own
//   record, not this account's copy of it.
//
// So "remove" is a status, which also makes it REVERSIBLE -- a delete is not,
// and "remove" that can be undone is a very different thing to confirm.
// ===========================================================================

// What ending it would cost, so the screen can say so before anybody presses.
// Live work is the part worth naming: a work order still open on an unfinished
// job means somebody is due on site.
async function engagementLiveWork(env, accountId, companyId) {
  try {
    const { results } = await env.DB.prepare(
      `SELECT w.id, w.wo_number, j.title, j.date
         FROM work_orders w JOIN jobs j ON j.id = w.job_id
        WHERE w.company_id = ? AND j.account_id = ?
          AND w.voided_at IS NULL
          AND w.status IN ('pending','accepted')
          AND COALESCE(j.status, '') <> 'completed'
        ORDER BY j.date LIMIT 20`
    ).bind(companyId, accountId).all();
    return (results || []).map((r) => ({
      id: r.id, number: r.wo_number || null, job: r.title || null, date: r.date || null,
    }));
  } catch (err) {
    // A database behind the code must not make removing somebody impossible;
    // the count is a warning, not the act.
    if (missingSchema(err)) return [];
    throw err;
  }
}

app.get("/api/subs/:companyId/end-check", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const { companyId } = c.req.param();
  const eng = await c.env.DB.prepare(
    `SELECT id, status FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  // Somebody else's contractor and one that does not exist give the same
  // answer, so this cannot be walked to find out which ids are real.
  if (!eng) return c.json({ error: "not_found" }, 404);
  const seats = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM memberships
      WHERE account_id = ? AND company_id = ? AND role = 'contractor'`
  ).bind(accountId, companyId).first();
  // What else points at them, so the consequence can say so rather than
  // somebody discovering it when a tenant reports a flood.
  const acct = await c.env.DB.prepare(
    `SELECT emergency_company_id FROM accounts WHERE id = ?`).bind(accountId).first();
  let invites = 0;
  try {
    const r = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM sub_invites
        WHERE account_id = ? AND company_id = ? AND used_at IS NULL AND revoked_at IS NULL`
    ).bind(accountId, companyId).first();
    invites = r?.n || 0;
  } catch (err) { if (!missingSchema(err)) throw err; }

  return c.json({
    status: eng.status,
    liveWork: await engagementLiveWork(c.env, accountId, companyId),
    seats: seats?.n || 0,
    isEmergency: acct?.emergency_company_id === companyId,
    invites,
  });
});

// `ended` or `paused`, because they are different things and offering only one
// makes people choose the wrong one. Paused is "not right now" -- a season, a
// lapsed certificate, a falling-out that may mend. Ended is "we do not work
// with them". Both come off the pickable roster; only one reads as final.
app.post("/api/subs/:companyId/end", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { companyId } = c.req.param();
  const body = await c.req.json().catch(() => ({}));
  // Three targets and nothing else. `ended` is the default because that is
  // what the button says; `active` is how somebody is added back, which is
  // what makes this reversible.
  const to = ["ended", "paused", "active"].includes(body.status) ? body.status : "ended";

  const eng = await c.env.DB.prepare(
    `SELECT id, status FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (!eng) return c.json({ error: "not_found" }, 404);
  if (eng.status === to) return c.json({ ok: true, status: to, unchanged: true });

  // LIVE WORK DOES NOT BLOCK, and that is deliberate. The handover made the
  // same call for the same reason: a repair going nowhere is very often WHY
  // somebody is being removed, and refusing until the work is finished hands
  // the party you are trying to leave a hostage. It is named on the way out
  // instead, and the work orders stay with their jobs so the record holds.
  const live = OFF_ROSTER.includes(to)
    ? await engagementLiveWork(c.env, accountId, companyId) : [];

  await c.env.DB.prepare(`UPDATE engagements SET status = ? WHERE id = ?`).bind(to, eng.id).run();

  let seatsRemoved = 0;
  let wasEmergency = false;
  let invitesRevoked = 0;
  if (OFF_ROSTER.includes(to)) {
    // AUTO-SCHEDULE OFF for both, because it writes to their calendar as
    // accepted. A flag left on against somebody who is not being offered work
    // is a standing permission nobody is watching.
    await c.env.DB.prepare(`UPDATE engagements SET auto_schedule = 0 WHERE id = ?`)
      .bind(eng.id).run();
    // AND THE EMERGENCY NOMINATION GOES WITH THEM, which is the same rule and
    // the more expensive one. `dispatchEmergency` refuses somebody off the
    // roster -- but it refuses at the moment a tenant reports a flood, and the
    // account finds out then or not at all. Worse, the panel draws nothing
    // selected once they are off the roster, so the column would point at a
    // contractor the screen could not name. Cleared here turns automatic
    // dispatch off, which is the honest default, and the feed says so.
    try {
      const cleared = await c.env.DB.prepare(
        `UPDATE accounts SET emergency_company_id = NULL
          WHERE id = ? AND emergency_company_id = ?`).bind(accountId, companyId).run();
      wasEmergency = (cleared?.meta?.changes || 0) > 0;
    } catch (err) { if (!missingSchema(err)) throw err; }
  }
  if (to === "ended") {
    // THE SEAT GOES ONLY WHEN IT ENDS, and that is what separates the two.
    // Pausing is "not right now" -- a season, a lapsed certificate, a
    // falling-out that may mend -- and taking somebody's login away over it
    // costs them their history with this account for something reversible,
    // which un-pausing could not give back: re-issuing a login silently would
    // hand somebody a key without anybody deciding to. Ending is "we do not
    // work with them", and there access is the thing that has to stop.
    //
    // Their `users` row stays either way -- a person is global and holds seats
    // in other accounts -- and so does everything they did here, with their
    // name on it.
    const gone = await c.env.DB.prepare(
      `DELETE FROM memberships
        WHERE account_id = ? AND company_id = ? AND role = 'contractor'`
    ).bind(accountId, companyId).run();
    seatsRemoved = gone?.meta?.changes || 0;

    // AND AN INVITE STILL OUT IS REVOKED, for the same reason and with the
    // sharper consequence: a live token is a way IN. Redeeming one writes a
    // `users` row and a contractor seat on this account -- the seat that was
    // just deleted two lines up -- so leaving it live means somebody can let
    // themselves back on to a roster they were taken off, by opening an email.
    // Revoked rather than deleted, which is what the invite list already does:
    // "we invited them and then removed them" is a thing that happened.
    //
    // Only on `ended`. A paused contractor keeps their login, so the invite
    // that would give them one is still the right link to be holding.
    try {
      const killed = await c.env.DB.prepare(
        `UPDATE sub_invites SET revoked_at = CURRENT_TIMESTAMP
          WHERE account_id = ? AND company_id = ?
            AND used_at IS NULL AND revoked_at IS NULL`
      ).bind(accountId, companyId).run();
      invitesRevoked = killed?.meta?.changes || 0;
    } catch (err) { if (!missingSchema(err)) throw err; }
  }

  const who = await c.env.DB.prepare(`SELECT company FROM companies WHERE id = ?`)
    .bind(companyId).first();
  const verb = to === "ended" ? "Removed" : to === "paused" ? "Paused" : "Re-added";
  await logActivity(c.env, accountId, userId, `engagement_${to}`,
    `${verb} ${who?.company || "a contractor"}`);
  await logEvent(c.env, accountId, userId, `engagement.${to}`, companyId,
    { from: eng.status, liveWork: live.length, seatsRemoved, wasEmergency, invitesRevoked });
  if (wasEmergency) {
    await logActivity(c.env, accountId, userId, "emergency_cleared",
      `${who?.company || "They"} were your emergency contractor \u2014 automatic dispatch is now off`);
  }

  return c.json({ ok: true, status: to, liveWork: live, seatsRemoved, wasEmergency, invitesRevoked });
});

app.post("/api/subs/:companyId/verify-license", requireRole("admin", "pm"), async (c) => {
  const companyId = c.req.param("companyId");
  const company = await c.env.DB.prepare(`SELECT license, state FROM companies WHERE id = ?`).bind(companyId).first();
  if (!company?.license) return c.json({ error: "no_license_on_file" }, 400);
  // Best available proxy for "which state issued this license" — the
  // company's own business-address state. Add a dedicated license_state
  // column later if a company's licensing state can differ from its
  // mailing address in practice.
  const state = (company.state || "WA").trim().toUpperCase();

  const result = await verifyLicenseForState(c.env, state, company.license);
  const { stored, kept } = await storeLicenseCheck(c.env.DB, companyId, state, result);
  // What the screen draws is what the row now says. When the registry could
  // not be reached and an earlier answer was kept, say so beside it, so a
  // press that changed nothing does not read as a fresh confirmation.
  return c.json(kept ? { ...stored, checkFailed: true, failure: result.status || "CHECK_FAILED" } : stored);
});

// ---------------------------------------------------------------------------
// Tenants
// ---------------------------------------------------------------------------
// The same shape as a subcontractor invite -- a one-use link with a life --
// but accepted by naming a building rather than a company.

// Tenants arrive at the account's own address, not app.subsub.work: the whole
// point is that the letter or noticeboard says their building's name. Falls
// back to the generic address for an account with no branded hostname yet.
const accountOrigin = (account) =>
  account?.hostname_status === "active" && account?.subdomain
    ? `https://${account.subdomain}.subsub.work`
    : "https://app.subsub.work";
const tenantInviteUrl = (account, token) => `${accountOrigin(account)}/?tenant=${token}`;

const tenantInviteRowToJs = (r, account, propertyName) => ({
  id: r.id, label: r.label, propertyId: r.property_id, propertyName: propertyName || null,
  createdAt: r.created_at, expiresAt: r.expires_at, usedAt: r.used_at,
  revokedAt: r.revoked_at, userId: r.user_id,
  url: tenantInviteUrl(account, r.token),
  status: r.revoked_at ? "revoked"
    : r.used_at ? "accepted"
    : new Date(r.expires_at) < new Date() ? "expired"
    : "open",
});

async function lookupTenantInvite(env, token) {
  if (!token || !/^[0-9a-f]{64}$/.test(token)) return { error: "invalid" };
  const row = await env.DB.prepare(`SELECT * FROM tenant_invites WHERE token = ?`).bind(token).first();
  if (!row) return { error: "invalid" };
  if (row.revoked_at) return { error: "revoked" };
  if (row.used_at) return { error: "used" };
  if (new Date(row.expires_at) < new Date()) return { error: "expired" };
  const account = await env.DB.prepare(
    `SELECT id, name, subdomain, theme, logo_key, use_default_mark, kind, hostname_status
       FROM accounts WHERE id = ?`).bind(row.account_id).first();
  if (!account) return { error: "invalid" };
  return { invite: row, account };
}

// Adding a tenant is not handing somebody a link. A managing agent with three
// hundred apartments is never going to paste three hundred links, and the
// person who has to be chased for it is the busiest one in the building. They
// type in who lives where -- or upload the list they already have -- and
// SubSub does the sending.
//
// Everything about one tenant that the account has to know, plus whether the
// invite got out and how.
const tenantRowToJs = (r) => ({
  userId: r.user_id, name: r.name, email: r.email, phone: r.phone,
  unit: r.unit, propertyId: r.property_id, propertyName: r.property_name || null,
  addedAt: r.created_at,
  // "invited" until they set a password; after that the seat is theirs.
  status: r.used_at ? "active" : "invited",
  invitedAt: r.invite_created_at || null,
  lastSentAt: r.last_sent_at || null,
});

// The roster. Scoped like everything else -- a manager assigned to two
// buildings sees the tenants of those two.
app.get("/api/tenants", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const scope = scopeClause(auth, "mp.property_id");
  try {
  const { results } = await c.env.DB.prepare(
    `SELECT u.id AS user_id, u.name, u.email, u.phone,
            m.unit, m.created_at,
            mp.property_id, p.name AS property_name,
            ti.first_created AS invite_created_at, ti.used_at, ti.last_sent_at
       FROM memberships m
       JOIN users u ON u.id = m.user_id
       LEFT JOIN membership_properties mp ON mp.membership_id = m.id
       LEFT JOIN properties p ON p.id = mp.property_id
       -- Rolled up, not joined row for row: resending mints a fresh invite
       -- and revokes the old one, so a tenant who has been chased twice has
       -- three rows here and would otherwise appear three times, each with a
       -- different idea of whether they had signed in.
       LEFT JOIN (
         SELECT user_id, account_id,
                MAX(used_at)    AS used_at,
                MAX(sent_at)    AS last_sent_at,
                MIN(created_at) AS first_created
           FROM tenant_invites GROUP BY user_id, account_id
       ) ti ON ti.user_id = u.id AND ti.account_id = m.account_id
      WHERE m.account_id = ? AND m.role = 'tenant' ${scope.sql}
      ORDER BY p.name, m.unit, u.name`
  ).bind(auth.accountId, ...scope.vals).all();
  // 072. How each would like to be reached and who to call if they cannot.
  // A second query rather than a join, so a database without 072 still lists
  // its tenants -- losing the contact line must never cost the list.
  let contacts = new Map();
  try {
    const { results: cs } = await c.env.DB.prepare(
      `SELECT * FROM tenant_contacts WHERE account_id = ?`).bind(auth.accountId).all();
    contacts = new Map((cs || []).map((r) => [r.user_id, r]));
  } catch (err) {
    if (!missingSchema(err)) throw err;
  }
  return c.json((results || []).map((r) => {
    const t = tenantRowToJs(r);
    const k = contacts.get(r.user_id);
    t.contact = k ? {
      prefer: k.prefer || null, bestTime: k.best_time || null,
      emergencyName: k.emergency_name || null, emergencyRelation: k.emergency_relation || null,
      emergencyPhone: k.emergency_phone || null,
    } : null;
    return t;
  }));
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    console.error("[tenants] schema not migrated:", err?.message || err);
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// One tenant, created and invited in a single step. Returns what happened to
// the sending as well as the creating, because "added but not told" is a
// state somebody has to be able to see and fix.
async function createTenant(c, auth, row, account) {
  const first = String(row.firstName || "").trim().slice(0, 60);
  const last = String(row.lastName || "").trim().slice(0, 60);
  const name = [first, last].filter(Boolean).join(" ");
  const email = String(row.email || "").trim().toLowerCase();
  const phoneRaw = String(row.phone || "").trim();
  // Stored the way every other number here is stored; toE164 turns it into
  // what Twilio wants at the moment of sending, and refusing early means a
  // spreadsheet row with a bad number is reported as bad rather than
  // silently never texted.
  const phone = phoneRaw ? normalizePhone(phoneRaw) : null;
  const textable = phoneRaw ? toE164(phoneRaw) : null;
  const unit = String(row.unit || "").trim().slice(0, 60) || null;
  const propertyId = row.propertyId || null;

  if (!name) return { ok: false, error: "name_required" };
  // One of the two, not both: a tenant with a phone and no email is ordinary,
  // and so is the reverse. With neither there is no way to tell them.
  if (!email && !phone) return { ok: false, error: "contact_required" };
  if (email && !EMAIL_RE.test(email)) return { ok: false, error: "bad_email" };
  if (phoneRaw && (!phone || !textable)) return { ok: false, error: "bad_phone" };
  if (!propertyId) return { ok: false, error: "property_required" };
  if (!maySeeProperty(auth, propertyId)) return { ok: false, error: "forbidden" };

  const property = await c.env.DB.prepare(
    `SELECT id, name FROM properties WHERE id = ? AND account_id = ?`
  ).bind(propertyId, auth.accountId).first();
  if (!property) return { ok: false, error: "property_not_found" };

  // Two people in one apartment is normal -- a couple, roommates, a business
  // and its owner -- so the unit is a label, never a key. The email is the
  // key, because that is what a login is.
  let user = email
    ? await c.env.DB.prepare(`SELECT * FROM users WHERE lower(email) = lower(?)`).bind(email).first()
    : null;
  const userId = user?.id ?? uid();
  if (!user) {
    await c.env.DB.prepare(`INSERT INTO users (id, name, email, phone) VALUES (?, ?, ?, ?)`)
      .bind(userId, name, email || `${userId}@no-email.invalid`, phone).run();
  } else {
    await c.env.DB.prepare(`UPDATE users SET phone = COALESCE(?, phone) WHERE id = ?`)
      .bind(phone, userId).run();
  }

  const seat = await c.env.DB.prepare(
    `SELECT id, role FROM memberships WHERE user_id = ? AND account_id = ?`
  ).bind(userId, auth.accountId).first();
  if (seat && seat.role !== "tenant") return { ok: false, error: "already_a_member" };

  const membershipId = seat?.id ?? uid();
  if (seat) {
    await c.env.DB.prepare(`UPDATE memberships SET unit = COALESCE(?, unit) WHERE id = ?`)
      .bind(unit, membershipId).run();
  } else {
    await c.env.DB.prepare(
      `INSERT INTO memberships (id, user_id, account_id, role, unit) VALUES (?, ?, ?, 'tenant', ?)`
    ).bind(membershipId, userId, auth.accountId, unit).run();
  }
  await c.env.DB.prepare(
    `INSERT OR IGNORE INTO membership_properties (membership_id, property_id) VALUES (?, ?)`
  ).bind(membershipId, propertyId).run();

  const sent = await issueTenantInvite(c, auth, {
    userId, name, first, email, phone, unit, account, property,
    channels: row.channels,
  });
  return { ok: true, userId, name, email, phone, unit,
    propertyId, propertyName: property.name, sent };
}

// Mint a fresh token for this tenant and send it. Used both when they are
// first added and when somebody presses resend, which is the same act: the
// old link stops working, which is what "resend" should mean.
async function issueTenantInvite(c, auth, t) {
  const token = newInviteToken();
  const expires = new Date(Date.now() + INVITE_TTL_DAYS * 86400_000).toISOString();
  await c.env.DB.prepare(
    `UPDATE tenant_invites SET revoked_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND account_id = ? AND used_at IS NULL AND revoked_at IS NULL`
  ).bind(t.userId, auth.accountId).run();
  const inviteId = uid();
  await c.env.DB.prepare(
    `INSERT INTO tenant_invites (id, account_id, property_id, token, label, created_by, expires_at, user_id)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(inviteId, auth.accountId, t.property.id, token, t.unit, auth.userId, expires, t.userId).run();

  const link = tenantInviteUrl(t.account, token);
  const want = Array.isArray(t.channels) && t.channels.length
    ? t.channels
    : [t.email ? "email" : null, t.phone ? "sms" : null].filter(Boolean);
  const out = { email: null, sms: null };

  if (want.includes("email") && t.email && !t.email.endsWith("@no-email.invalid")) {
    // Whatever the manager edited, if they edited anything. The link is put
    // in here rather than in the draft, because the draft was written before
    // this token existed.
    const mail = t.draft?.message
      ? customInviteEmail({
          subject: t.draft.subject
            || tenantInviteEmail({ firstName: t.first || t.name, account: t.account,
                 propertyName: t.property.name, unit: t.unit, link }).subject,
          text: t.draft.message, link })
      : tenantInviteEmail({
          firstName: t.first || t.name, account: t.account,
          propertyName: t.property.name, unit: t.unit, link,
        });
    const res = await sendEmail(c.env, { to: t.email, subject: mail.subject, text: mail.text, html: mail.html });
    out.email = res.ok ? "sent" : (res.error || "failed");
    await logMail(c.env, { accountId: auth.accountId, to: t.email, kind: "tenant_invite",
      subject: mail.subject, result: res, sentBy: auth.userId });
  }
  if (want.includes("sms") && t.phone) {
    const body = t.draft?.sms
      ? withInviteLink(t.draft.sms, link)
      : tenantInviteSms({ account: t.account, propertyName: t.property.name, unit: t.unit, link });
    const res = await sendAccountSms(c.env, { accountId: auth.accountId, to: t.phone,
      kind: "tenant_invite", body });
    out.sms = res.ok ? "sent" : (res.error || "failed");
  }

  // Only counted as sent if something actually went out. An invite recorded
  // as sent that never left is the worst of both worlds: nobody chases it.
  if (out.email === "sent" || out.sms === "sent") {
    await c.env.DB.prepare(`UPDATE tenant_invites SET sent_at = CURRENT_TIMESTAMP WHERE id = ?`)
      .bind(inviteId).run();
  }
  return out;
}

// Which migration a D1 complaint is really about. The message names the
// column or table, so the answer is in the error and only needs reading.
export function missingSchema(err) {
  // D1 sometimes carries the real message on the cause rather than the error
  // itself, so both are read.
  const m = [err?.message, err?.cause?.message, err].map((x) => String(x || "")).join(" | ");
  // SQLite has two ways of saying the same thing and they do not share a
  // word: a SELECT or UPDATE against a column that is not there says "no such
  // column: unit", while an INSERT says "table memberships has no column
  // named unit". Matching only the first meant adding a tenant before
  // migration 015 -- an INSERT -- threw a plain 500, and the form said
  // "Could not add them. Try again." instead of naming the migration.
  if (!/no such (table|column)|has no column named/i.test(m)) return null;
  // The recent ones first, because several of them mention words an older
  // rule would claim. "overflow_posts has no column named severity" is 038,
  // not 023, and the severity rule below would have taken it.
  //
  // `countersigned_at` rather than anything shorter: `agreements` and
  // `agreement_terms` both start with a word the older `\bcontract\b` rules
  // would not claim, but a column named `terms` is exactly the sort of thing
  // a later rule could, so the distinctive ones are named.
  // 060's column is called `access`, which is far too ordinary a word to match
  // loosely -- so it is matched only in the two shapes SQLite actually
  // produces for a missing column, and it is first because a later rule with a
  // broader pattern would otherwise claim it.
  // 068's three tables all start `inspection_`, which `inspection_summaries`
  // (063) and `inspection_sends` (056) also do -- so each is named in full
  // rather than by a prefix, and they sit above the older rules for the reason
  // the comment above gives.
  if (/\bpassport(s|_photos|_access)\b|\blicense_reminders\b|ux_passport_|ux_license_reminder/i.test(m)) return "077_passport";
  if (/\bleads\b/i.test(m)) return "076_leads";
  if (/\breferral_(codes|touches|attributions|rewards|invites)\b|ux_referral_/i.test(m)) return "075_referrals";
  if (/\bwo_claim_links\b|\bsub_attributions\b/i.test(m)) return "074_wo_claims";
  if (/\bjob_access\b/i.test(m)) return "073_job_access";
  if (/\btenant_contacts\b|\bbuilding_notices\b/i.test(m)) return "072_tenant_home";
  if (/\bwaiver_forms\b|ux_waiver_open/i.test(m)) return "069_waiver_forms";
  if (/\binspection_(sources|status_rules|unmapped)\b/i.test(m)) return "068_inspection_ingest";
  if (/\bjob_endings\b/i.test(m)) return "066_job_endings";
  if (/\binspection_summaries\b/i.test(m)) return "063_inspection_summary";
  if (/\bauto_turnaround\b/i.test(m)) return "065_auto_turnaround";
  if (/\bsms_overage\b/i.test(m)) return "070_sms_overage";
  if (/\baccount_sms_settings\b/i.test(m)) return "070_sms_overage";
  if (/\baccount_fee_terms\b/i.test(m)) return "071_fee_terms";
  if (/\bmanager_at\b/i.test(m)) return "064_visit_manager";
  if (/contractor_(at|note)/i.test(m)) return "061_visit_contractor";
  if (/access_user_id/i.test(m)) return "062_job_access_user";
  if (/no such column: (jobs\.)?access\b|jobs has no column named access\b/i.test(m)) return "060_job_access";
  if (/\bagreements?\b|\bagreement_terms\b|countersigned_(at|by)/i.test(m)) return "052_agreements";
  if (/\bwo_(funding|transfers)\b/i.test(m)) return "051_escrow";
  if (/\bpayout_accounts\b/i.test(m)) return "050_payout_accounts";
  if (/\bdoc_shares\b/i.test(m)) return "041_doc_shares";
  if (/owner_declared_(at|by)/i.test(m)) return "040_owner_declared";
  if (/\bproperty_transfers\b|owner_account_id|requested_by_account_id/i.test(m)) return "039_building_handover";
  if (/\boverflow_(posts|invites|responses)\b|overflow_(opt_in|trades|since)/i.test(m)) return "038_overflow";
  if (/\bcompany_docs\b|\bdoc_reminders\b|superseded_at|policy_no|coverage_cents/i.test(m)) return "037_document_detail";
  if (/scope_kind/i.test(m)) return "036_wo_scope";
  if (/\blien_waivers\b|\blower_tier_parties\b|through_date|doc_sha256/i.test(m)) return "035_waiver_chain";
  if (/retainage_bps/i.test(m)) return "034_retainage";
  if (/\bwo_(milestones|events|releases)\b|fee_bps|idem_key/i.test(m)) return "033_job_ledger";
  if (/avatar_key/i.test(m)) return "032_user_avatar";
  if (/\bnotify\b/i.test(m)) return "018_user_notify";
  if (/\bvisits\b/i.test(m)) return "019_visits";
  if (/withdrawn_(at|note)/i.test(m)) return "020_withdrawn_reports";
  if (/declined_(at|note)/i.test(m)) return "021_declined_requests";
  if (/\bphotos\b|report_detail/i.test(m)) return "022_report_photos";
  if (/\bseverity\b|emergency_company_id/i.test(m)) return "023_emergencies";
  if (/pay_kind|rate_cents|cap_hours/i.test(m)) return "024_hourly_work_orders";
  if (/updated_at/i.test(m)) return "025_job_activity";
  if (/material_supplier|material_branch/i.test(m)) return "026_material_supplier";
  if (/user_invites/i.test(m)) return "028_user_invites";
  // Both halves of 030: the table the requests live in, and the column
  // holding the code a contractor's QR encodes. Named rather than left to
  // "unknown" because this is the one an account with 031 already applied
  // hits -- the company profile panel needs both, and being told to run the
  // migration it had was worse than being told nothing.
  if (/connect_requests|connect_code/i.test(m)) return "030_connect_requests";
  if (/tenant_invites|memberships\.unit|\bunit\b/i.test(m)) {
    return /sent_at/i.test(m) ? "017_tenant_invite_sent" : "015_tenants";
  }
  if (/membership_properties/i.test(m)) return "014_building_owners";
  if (/cancel_at_period_end/i.test(m)) return "013_cancel_at_period_end";
  return "unknown";
}

app.post("/api/tenants", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(auth.accountId).first();
  if (!ACCOUNT_KINDS_WITH_PROPERTIES.includes(account?.kind || "")) {
    return c.json({ error: "not_a_property_account" }, 400);
  }
  const b = await c.req.json().catch(() => ({}));
  let res;
  try {
    res = await createTenant(c, auth, b, account);
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) {
      console.error("[tenants] schema not migrated:", err?.message || err);
      return c.json({ error: "migration_needed", migration }, 503);
    }
    throw err;
  }
  if (!res.ok) return c.json({ error: res.error }, res.error === "forbidden" ? 403 : 400);
  await logActivity(c.env, auth.accountId, auth.userId, "tenant_added",
    `Added tenant ${res.name}${res.unit ? ` (${res.unit})` : ""} at ${res.propertyName}`);
  return c.json(res, 201);
});

// The same thing, many at a time, for the list a managing agent already has
// in a spreadsheet. The browser parses the file and sends rows in batches, so
// this stays a plain array and nothing here has to understand a file format.
//
// Every row is reported on individually. A bulk import that fails as a unit
// because row 184 has a typo is one somebody gives up on.
app.post("/api/tenants/bulk", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(auth.accountId).first();
  if (!ACCOUNT_KINDS_WITH_PROPERTIES.includes(account?.kind || "")) {
    return c.json({ error: "not_a_property_account" }, 400);
  }
  const b = await c.req.json().catch(() => ({}));
  const rows = Array.isArray(b.rows) ? b.rows : [];
  // A cap, because this runs inside one request and a spreadsheet can hold
  // anything. The browser sends in batches of this size or smaller.
  if (rows.length > 25) return c.json({ error: "too_many", max: 25 }, 400);

  const results = [];
  for (const row of rows) {
    try {
      const res = await createTenant(c, auth, row, account);
      results.push(res.ok
        ? { ok: true, userId: res.userId, name: res.name, unit: res.unit, sent: res.sent }
        : { ok: false, error: res.error });
    } catch (err) {
      console.error("[tenants] bulk row failed:", err);
      results.push({ ok: false, error: "failed" });
    }
  }
  const added = results.filter((r) => r.ok).length;
  if (added) {
    await logActivity(c.env, auth.accountId, auth.userId, "tenants_imported",
      `Imported ${added} tenant${added === 1 ? "" : "s"}`);
  }
  return c.json({ results });
});

// One tenant's seat, by user id, with the property they are attached to and
// whether their invite is still outstanding. Shared by the three routes
// below, all of which have the same two things to check first.
async function tenantSeat(c, auth, userId) {
  const row = await c.env.DB.prepare(
    `SELECT m.id AS membership_id, m.unit, u.id AS user_id, u.name, u.email, u.phone, u.auth_id,
            mp.property_id, p.name AS property_name,
            ti.used_at, ti.open_invites, ti.last_sent_at
       FROM memberships m
       JOIN users u ON u.id = m.user_id
       LEFT JOIN membership_properties mp ON mp.membership_id = m.id
       LEFT JOIN properties p ON p.id = mp.property_id
       LEFT JOIN (
         SELECT user_id, account_id, MAX(used_at) AS used_at, MAX(sent_at) AS last_sent_at,
                SUM(CASE WHEN used_at IS NULL AND revoked_at IS NULL THEN 1 ELSE 0 END) AS open_invites
           FROM tenant_invites GROUP BY user_id, account_id
       ) ti ON ti.user_id = u.id AND ti.account_id = m.account_id
      WHERE m.user_id = ? AND m.account_id = ? AND m.role = 'tenant'`
  ).bind(userId, auth.accountId).first();
  if (!row) return { error: "not_found", status: 404 };
  if (!maySeeProperty(auth, row.property_id)) return { error: "forbidden", status: 403 };
  return { row };
}

const realEmail = (e) => e && !String(e).endsWith("@no-email.invalid") ? e : null;

// What is about to be sent, before it is sent -- so somebody can read it,
// change it, or decide not to. The link is a placeholder here: the real one
// does not exist until the moment of sending, because sending mints a fresh
// token and revokes whatever came before.
app.get("/api/tenants/:userId/invite", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const { row, error, status } = await tenantSeat(c, auth, c.req.param("userId"));
  if (error) return c.json({ error }, status);
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(auth.accountId).first();
  const first = String(row.name || "").split(" ")[0];
  const property = { id: row.property_id, name: row.property_name };
  const mail = tenantInviteEmail({ firstName: first, account,
    propertyName: property.name, unit: row.unit, link: INVITE_LINK_TOKEN });
  return c.json({
    userId: row.user_id, name: row.name, email: realEmail(row.email), phone: row.phone,
    unit: row.unit, propertyId: row.property_id, propertyName: property.name,
    status: row.used_at ? "active" : "invited",
    // Somebody who has already signed in has a login keyed to their address,
    // so it is not ours to change underneath them.
    emailLocked: !!(row.used_at || row.auth_id),
    openInvite: (row.open_invites || 0) > 0,
    lastSentAt: row.last_sent_at || null,
    linkToken: INVITE_LINK_TOKEN,
    draft: {
      subject: mail.subject,
      message: mail.text,
      sms: tenantInviteSms({ account, propertyName: property.name, unit: row.unit, link: INVITE_LINK_TOKEN }),
    },
  });
});

// Correcting the record before chasing it again -- a mistyped address, the
// wrong unit, the wrong building. The commonest reason an invite goes
// nowhere is that it was addressed wrongly, and re-sending it unchanged
// sends it to the same wrong place.
app.patch("/api/tenants/:userId", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const userId = c.req.param("userId");
  const { row, error, status } = await tenantSeat(c, auth, userId);
  if (error) return c.json({ error }, status);
  const b = await c.req.json().catch(() => ({}));

  const first = String(b.firstName ?? "").trim().slice(0, 60);
  const last = String(b.lastName ?? "").trim().slice(0, 60);
  const name = [first, last].filter(Boolean).join(" ") || row.name;
  if (!name) return c.json({ error: "name_required" }, 400);

  const userSets = ["name = ?"], userVals = [name];

  if (b.email !== undefined) {
    const email = String(b.email || "").trim().toLowerCase();
    const current = realEmail(row.email);
    if (email !== (current || "")) {
      // Their sign-in is that address. Moving it would leave them holding a
      // password for an account this one no longer points at.
      if (row.used_at || row.auth_id) return c.json({ error: "email_locked" }, 409);
      if (email) {
        if (!EMAIL_RE.test(email)) return c.json({ error: "bad_email" }, 400);
        const clash = await c.env.DB.prepare(
          `SELECT id FROM users WHERE lower(email) = lower(?) AND id != ?`).bind(email, userId).first();
        if (clash) return c.json({ error: "email_taken" }, 409);
        userSets.push("email = ?"); userVals.push(email);
      } else {
        // Back to no address at all: the placeholder is what the rest of the
        // code reads as "reachable by phone only".
        userSets.push("email = ?"); userVals.push(`${userId}@no-email.invalid`);
      }
    }
  }

  if (b.phone !== undefined) {
    const raw = String(b.phone || "").trim();
    const phone = raw ? normalizePhone(raw) : null;
    if (raw && !phone) return c.json({ error: "bad_phone" }, 400);
    userSets.push("phone = ?"); userVals.push(phone);
  }

  // Neither an address nor a number leaves nobody to tell.
  const nextEmail = b.email !== undefined
    ? realEmail(String(b.email || "").trim().toLowerCase() || null) : realEmail(row.email);
  const nextPhone = b.phone !== undefined
    ? (String(b.phone || "").trim() ? normalizePhone(String(b.phone)) : null) : row.phone;
  if (!nextEmail && !nextPhone) return c.json({ error: "contact_required" }, 400);

  if (b.propertyId !== undefined && b.propertyId !== row.property_id) {
    if (!b.propertyId) return c.json({ error: "property_required" }, 400);
    if (!maySeeProperty(auth, b.propertyId)) return c.json({ error: "forbidden" }, 403);
    const prop = await c.env.DB.prepare(
      `SELECT id FROM properties WHERE id = ? AND account_id = ?`).bind(b.propertyId, auth.accountId).first();
    if (!prop) return c.json({ error: "property_not_found" }, 400);
    await c.env.DB.prepare(`DELETE FROM membership_properties WHERE membership_id = ?`)
      .bind(row.membership_id).run();
    await c.env.DB.prepare(
      `INSERT OR IGNORE INTO membership_properties (membership_id, property_id) VALUES (?, ?)`
    ).bind(row.membership_id, b.propertyId).run();
  }

  if (b.unit !== undefined) {
    await c.env.DB.prepare(`UPDATE memberships SET unit = ? WHERE id = ?`)
      .bind(String(b.unit || "").trim().slice(0, 60) || null, row.membership_id).run();
  }

  userVals.push(userId);
  try {
    await c.env.DB.prepare(`UPDATE users SET ${userSets.join(", ")} WHERE id = ?`).bind(...userVals).run();
  } catch (err) {
    if (/UNIQUE|constraint/i.test(String(err?.message || err))) return c.json({ error: "email_taken" }, 409);
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration }, 503);
    throw err;
  }

  const after = await tenantSeat(c, auth, userId);
  return c.json({ ok: true, name, unit: after.row?.unit ?? null,
    email: realEmail(after.row?.email), phone: after.row?.phone ?? null,
    propertyId: after.row?.property_id ?? null, propertyName: after.row?.property_name ?? null });
});

// Calling it off without removing the person. Their outstanding link stops
// working; they stay on the roster, so somebody can fix the record and send
// again rather than adding them from scratch.
app.post("/api/tenants/:userId/revoke", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const userId = c.req.param("userId");
  const { row, error, status } = await tenantSeat(c, auth, userId);
  if (error) return c.json({ error }, status);
  if (row.used_at) return c.json({ error: "already_accepted" }, 409);
  const res = await c.env.DB.prepare(
    `UPDATE tenant_invites SET revoked_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND account_id = ? AND used_at IS NULL AND revoked_at IS NULL`
  ).bind(userId, auth.accountId).run();
  const revoked = res?.meta?.changes ?? 0;
  if (revoked) {
    await logActivity(c.env, auth.accountId, auth.userId, "tenant_invite_revoked",
      `Revoked the invite for ${row.name}`);
  }
  return c.json({ ok: true, revoked });
});

app.post("/api/tenants/:userId/resend", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const userId = c.req.param("userId");
  const b = await c.req.json().catch(() => ({}));
  const { row, error, status } = await tenantSeat(c, auth, userId);
  if (error) return c.json({ error }, status);
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(auth.accountId).first();

  // Wording the manager changed, if they changed any. Bounded because it is
  // going out over somebody else's mail server and somebody else's phone
  // bill; an SMS beyond this is several messages and several charges.
  const draft = {
    subject: b.subject == null ? null : String(b.subject).trim().slice(0, 200),
    message: b.message == null ? null : String(b.message).slice(0, 4000),
    sms: b.sms == null ? null : String(b.sms).slice(0, 480),
  };
  if (draft.message !== null && !draft.message.trim()) return c.json({ error: "empty_message" }, 400);
  if (draft.message !== null && !draft.subject) return c.json({ error: "empty_subject" }, 400);

  const sent = await issueTenantInvite(c, auth, {
    userId, name: row.name, first: String(row.name || "").split(" ")[0],
    email: row.email, phone: row.phone, unit: row.unit, account,
    property: { id: row.property_id, name: row.property_name },
    channels: b.channels, draft,
  });
  return c.json({ ok: true, sent, edited: !!draft.message });
});

// Removing a tenant drops their seat here, not the person: the same address
// may be a tenant of somebody else's building.
app.delete("/api/tenants/:userId", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  const userId = c.req.param("userId");
  const row = await c.env.DB.prepare(
    `SELECT m.id, mp.property_id FROM memberships m
       LEFT JOIN membership_properties mp ON mp.membership_id = m.id
      WHERE m.user_id = ? AND m.account_id = ? AND m.role = 'tenant'`
  ).bind(userId, auth.accountId).first();
  if (!row) return c.json({ error: "not_found" }, 404);
  if (!maySeeProperty(auth, row.property_id)) return c.json({ error: "forbidden" }, 403);
  await c.env.DB.prepare(`DELETE FROM memberships WHERE id = ?`).bind(row.id).run();
  await c.env.DB.prepare(
    `UPDATE tenant_invites SET revoked_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND account_id = ? AND used_at IS NULL AND revoked_at IS NULL`
  ).bind(userId, auth.accountId).run();
  return c.json({ ok: true });
});

// What the branded page shows somebody holding a tenant link, before they
// have any account at all. Public, so it says as little as it can get away
// with: the building's name and the account's branding.
// What the branded page shows somebody holding a tenant link, before they
// have any account at all. Public, so it says as little as it can: their own
// first name, their building, and the branding of whoever set them up.
app.get("/api/tenant-invite/:token", async (c) => {
  const { error, invite, account } = await lookupTenantInvite(c.env, c.req.param("token"));
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);

  const who = invite.user_id
    ? await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(invite.user_id).first()
    : null;
  const property = invite.property_id
    ? await c.env.DB.prepare(`SELECT name FROM properties WHERE id = ?`).bind(invite.property_id).first()
    : null;

  // A tenant added by phone alone has a placeholder address on file, which is
  // fine for texting them and no use as a login. Rather than send them a link
  // that turns them away, the page asks for an address at this point -- the
  // one moment they are already here and paying attention.
  const placeholder = !who?.email || String(who.email).endsWith("@no-email.invalid");

  return c.json({
    // A first name only. The link arrived in their inbox or on their phone,
    // so this is recognition rather than disclosure -- and the surname and
    // the full address are not needed to say "this is yours".
    firstName: String(who?.name || "").split(" ")[0] || null,
    needsEmail: placeholder,
    propertyName: property?.name || null,
    unit: invite.label || null,
    account: {
      id: account.id, name: account.name, subdomain: account.subdomain,
      theme: parseJson(account.theme),
      logoKey: account.logo_key, useDefaultMark: !!account.use_default_mark,
      kind: account.kind,
    },
  });
});

// Accepting one. Everything about them is already known -- their building
// manager typed it in, or uploaded it -- so the only thing left is a
// password, which they choose and Supabase stores. No service_role key is
// involved here or anywhere else in this codebase.
app.post("/api/tenant-invite/:token", async (c) => {
  const rl = await rateLimit(c.env, "tenant-invite", clientIp(c), { limit: 20, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const { error, invite, account } = await lookupTenantInvite(c.env, c.req.param("token"));
  if (error) return c.json({ error }, error === "invalid" ? 404 : 410);
  if (!invite.user_id) return c.json({ error: "invalid" }, 404);

  const b = await c.req.json().catch(() => ({}));
  const password = String(b.password || "");
  if (password.length < 8) return c.json({ error: "weak_password" }, 400);

  const user = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(invite.user_id).first();
  if (!user) return c.json({ error: "invalid" }, 404);

  // Added by phone alone: there is no address to sign in with, so they give
  // one now. Taking it here rather than refusing them is the difference
  // between a text that works and a text that wastes somebody's afternoon.
  let email = user.email;
  if (!email || String(email).endsWith("@no-email.invalid")) {
    email = String(b.email || "").trim().toLowerCase();
    if (!EMAIL_RE.test(email)) return c.json({ error: "email_required" }, 400);
    const clash = await c.env.DB.prepare(
      `SELECT id FROM users WHERE lower(email) = lower(?) AND id != ?`).bind(email, user.id).first();
    if (clash) return c.json({ error: "email_in_use_here" }, 409);
    await c.env.DB.prepare(`UPDATE users SET email = ? WHERE id = ?`).bind(email, user.id).run();
  }

  const signed = await supabaseSignUp(c.env, email, password, { redirectTo: `${accountOrigin(account)}/` });
  if (!signed.ok && signed.error !== "email_in_use") {
    return c.json({ error: signed.error, detail: signed.detail }, 400);
  }
  // `existed` is Supabase's enumeration protection showing through: an
  // address that is already registered answers 200 with a fabricated id and
  // an empty identities list. Writing that id would point auth_id at nobody.
  const already = signed.error === "email_in_use" || signed.existed;
  if (signed.ok && !signed.existed && signed.authId && !user.auth_id) {
    await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ? AND auth_id IS NULL`)
      .bind(signed.authId, user.id).run();
  }

  await c.env.DB.prepare(
    `UPDATE tenant_invites SET used_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(invite.id).run();
  await logActivity(c.env, account.id, null, "tenant_joined",
    `${user.name} set up their login${invite.label ? ` (${invite.label})` : ""}`);

  return c.json({
    ok: true, email,
    // Supabase projects with email confirmation on will not sign them in
    // yet. Saying so is the difference between "check your email" and a
    // person typing a correct password into a screen that keeps refusing it.
    needsConfirmation: signed.ok && !signed.session && !already,
    // Already registered: they have a password from somewhere and the one
    // just typed was not used. Telling them to sign in beats telling them
    // nothing and letting them wonder why it does not work.
    existed: already,
  });
});

// ---------------------------------------------------------------------------
// Jobs
// ---------------------------------------------------------------------------
app.get("/api/jobs", async (c) => {
  const auth = c.get("auth");
  const { accountId } = auth;
  // An owner sees the jobs at their own buildings and nothing else. A job with
  // no property is account-wide work and is not theirs to see either, which
  // `property_id IN (...)` gives for free -- NULL matches nothing.
  //
  // A tenant is narrower still: their own reports, not the building's work.
  // Sharing a building with somebody is not a reason to see their repairs.
  const scope = scopeClause(auth, "property_id");
  // And a PROJECT manager narrowed to named jobs, which is what a general
  // contractor has instead of buildings -- see shared/jobscope.js. It stacks
  // with the property scope rather than replacing it: both are empty for an
  // unnarrowed seat, so nothing that worked before changes.
  const jscope = jobScopeClause(auth, "id");
  const mine = auth.role === "tenant" ? ` AND requested_by = ? ` : "";
  // A CONTRACTOR seat sees the jobs their company was actually issued, and no
  // others. scopeClause narrows owners and tenants by property and contributes
  // nothing for a contractor, so this list was every job on the account --
  // including the ones they are not on, each carrying every trade's assignment.
  // That is which company the account uses for each trade and what each of them
  // is being paid, handed to a competitor on the same roster. stripMoney does
  // not help: it redacts owners and tenants only, so the values went too.
  //
  // Accepting one connect request was enough, which is the accumulation this
  // product refuses everywhere else -- and the send-my-documents loop exists to
  // put more subcontractors on more rosters, so it was getting worse by design.
  //
  // Scoped by the work order, the same way /api/my-work is, because the work
  // order is the thing that says this job was given to them.
  const asContractor = auth.role === "contractor" && auth.companyId;
  const woScope = asContractor
    ? ` AND EXISTS (SELECT 1 FROM work_orders w
                     WHERE w.job_id = j.id AND w.company_id = ? AND w.voided_at IS NULL) `
    : "";
  const binds = [accountId, ...scope.vals, ...jscope.vals,
    ...(auth.role === "tenant" ? [auth.userId] : []),
    ...(asContractor ? [auth.companyId] : [])];
  // `order` is interpolated rather than bound because ORDER BY cannot be a
  // bound parameter. Both callers below pass a literal written here; nothing
  // from a request reaches it, and nothing may be added that does.
  const listJobs = (order) => c.env.DB.prepare(
    // The requester's name, on the row. Somebody who asked for work from
    // another account is not a member of this one, so the account's own users
    // list will never contain them -- and a request reading "somebody asked for
    // work" is not something a manager can act on.
    `SELECT j.*, ru.name AS requested_by_name,
            -- 060. Whether the person who raised it is somebody who has to
            -- be IN. The requested_by column alone cannot answer that: an
            -- OWNER can raise a request too, and an owner is not a tenant. The
            -- effective access answer is computed from this on the way out, so
            -- no screen has to derive a second one.
            -- (No backticks: this is a template literal. Eleventh time.)
            rm.role AS requested_by_role
       FROM jobs j
       LEFT JOIN users ru ON ru.id = j.requested_by
       LEFT JOIN memberships rm ON rm.user_id = j.requested_by AND rm.account_id = j.account_id
      WHERE j.account_id = ? ${scope.sql.replace(/\bproperty_id\b/g, "j.property_id")}
        ${jscope.sql.replace(/ id IN/g, " j.id IN")}
        ${mine.replace(/\brequested_by\b/g, "j.requested_by")}
        ${woScope} ORDER BY ${order.replace(/\b(updated_at|created_at)\b/g, "j.$1")}`
  ).bind(...binds).all();

  // The order we want needs the column migration 025 adds. The order is a
  // nicety; this list is the entire page. A database still waiting on 025
  // failed the whole query, and the browser -- which treats a failed call
  // here as an empty result, because a refused one really is empty -- drew
  // the account as having no jobs at all. Signing in to an empty company is
  // the worst possible way to be told a migration is pending. So: ask for
  // the good order, and if the column is not there yet, ask again for the
  // plain one.
  let jobs;
  try {
    ({ results: jobs } = await listJobs("COALESCE(updated_at, created_at) DESC, created_at DESC"));
  } catch (err) {
    if (missingSchema(err) !== "025_job_activity") throw err;
    console.warn("[jobs] 025_job_activity not applied - falling back to created_at order");
    ({ results: jobs } = await listJobs("created_at DESC"));
  }

  // Work at buildings this account OWNS but has appointed somebody else to run.
  //
  // Without this an owner who appoints a manager keeps the building on their
  // list and sees nothing happening at it: a name, an address, and no work,
  // ever. That is not seeing your building -- it is being shown a card about
  // it. The whole reason an owner is on SubSub is to watch what happens at the
  // property they own, and appointing a manager is precisely when they stop
  // being able to watch it themselves.
  //
  // Read-only, and marked so. The work belongs to the manager: the owner does
  // not assign it, price it, complete it or cancel it, and every screen needs
  // to know that before it offers a button.
  //
  // A guest seat never reaches this. An owner scoped to named buildings on
  // somebody else's account sees what that scope allows and nothing through a
  // second door.
  // A tenant's OWN reports, wherever they ended up.
  //
  // When a building changes hands the tenants follow it -- their next report has
  // to reach whoever manages the place now -- but the reports they already made
  // stay with the account that handled them, because jobs never move. So a
  // tenant who followed their building lost every report they had ever made
  // about their own home: nothing on the new account, and a 403 from the old one
  // because their seat there is gone.
  //
  // Their own reports about their own home are the most personal record here and
  // the least defensible thing to lose. Scoped hard: reported BY them, at a
  // property they are STILL a tenant of. Not the building's other repairs --
  // sharing an address with somebody is not a reason to read their business.
  let pastReports = [];
  if (auth.role === "tenant" && (auth.propertyIds || []).length) {
    try {
      const marks = auth.propertyIds.map(() => "?").join(",");
      const { results } = await c.env.DB.prepare(
        `SELECT j.*, a.name AS managed_by_name FROM jobs j
           LEFT JOIN accounts a ON a.id = j.account_id
          WHERE j.requested_by = ? AND j.account_id != ?
            AND j.property_id IN (${marks})
          ORDER BY COALESCE(j.date, j.created_at) DESC LIMIT 200`
      ).bind(auth.userId, accountId, ...auth.propertyIds).all();
      pastReports = results || [];
    } catch (err) { if (!missingSchema(err)) throw err; }
  }

  let ownedJobs = [];
  if (auth.role !== "owner" && auth.role !== "tenant") {
    try {
      const { results } = await c.env.DB.prepare(
        `SELECT j.*, a.name AS managed_by_name FROM jobs j
           JOIN properties p ON p.id = j.property_id
           LEFT JOIN accounts a ON a.id = j.account_id
          WHERE p.owner_account_id = ? AND p.account_id != ?
          ORDER BY COALESCE(j.date, j.created_at) DESC LIMIT 400`
      ).bind(accountId, accountId).all();
      ownedJobs = results || [];
    } catch (err) {
      // No 039 means no owner_account_id, and the list is what it always was.
      if (!missingSchema(err)) throw err;
    }
  }

  // Work the PREVIOUS operator is still running at a building this account has
  // just taken on.
  //
  // Jobs do not move, so before this the incoming manager saw nothing: no sign
  // a contractor was due Tuesday, nobody to let them in, nobody to verify it,
  // and a tenant waiting on a leak they had never heard of. The contractor
  // turns up at a building whose manager has no record of them.
  //
  // Found without a new column: this account operates the property, the job
  // sits on somebody else's account, and it is not finished. Once the previous
  // manager closes it out it drops off this list by itself and lives in the
  // building's history, where it belongs.
  let inheritedJobs = [];
  if (auth.role !== "owner" && auth.role !== "tenant" && !auth.propertyIds) {
    try {
      const { results } = await c.env.DB.prepare(
        `SELECT j.*, a.name AS prev_name, ru.name AS requested_by_name FROM jobs j
           JOIN properties p ON p.id = j.property_id
           LEFT JOIN accounts a ON a.id = j.account_id
           LEFT JOIN users ru ON ru.id = j.requested_by
          WHERE p.account_id = ? AND j.account_id != ?
            AND j.status != 'completed'
            AND j.withdrawn_at IS NULL AND j.declined_at IS NULL
          ORDER BY COALESCE(j.date, j.created_at) ASC LIMIT 200`
      ).bind(accountId, accountId).all();
      inheritedJobs = results || [];
    } catch (err) {
      // Older databases have neither the withdrawn/declined columns nor 039.
      // A missing column here must not empty the whole jobs screen.
      if (!missingSchema(err)) throw err;
    }
  }

  // Work orders for both sets. The second query is scoped by JOB rather than by
  // account, because these jobs are on an account the caller is not part of.
  const jobIds = [...jobs, ...ownedJobs, ...pastReports, ...inheritedJobs].map((j) => j.id);
  const woByJob = {};
  if (jobIds.length) {
    const { results: wos } = await c.env.DB.prepare(
      `SELECT wo.* FROM work_orders wo
        WHERE wo.voided_at IS NULL AND wo.job_id IN (${jobIds.map(() => "?").join(",")})`
    ).bind(...jobIds).all();
    for (const w of wos) (woByJob[w.job_id] ||= []).push(w);
  }

  // 066. HOW EACH JOB ENDED, WHERE IT HAS, in ONE query for all four lists.
  //
  // Stitched onto the rows rather than subqueried into each SELECT, because
  // there are four of them -- this account's, the owned-not-operated ones, a
  // tenant's past reports and the inherited ones -- and a column added to
  // three of four is the shape this file keeps recording: the list that
  // forgets is the one that draws a cancelled job as live.
  //
  // The newest row per job wins, which is what makes the table append-only
  // usable: a deferral is ended by a `resumed` row rather than by deleting
  // the one that put it on hold. `at DESC, rowid DESC` for the reason the
  // visit lookup uses it -- two rows written in the same second need a
  // tiebreak that is not the one SQLite feels like.
  //
  // A database without 066 has no endings, which is exactly the behaviour
  // this route had before it. Narrow catch: only the missing table.
  const endingByJob = await (async () => {
    const ids = [...new Set([...jobs, ...ownedJobs, ...pastReports, ...inheritedJobs]
      .map((j) => j.id))];
    if (!ids.length) return {};
    const out = {};
    try {
      const marks = ids.map(() => "?").join(",");
      const { results } = await c.env.DB.prepare(
        `SELECT e.job_id, e.kind, e.note, e.until, e.at FROM job_endings e
          WHERE e.job_id IN (${marks})
          ORDER BY e.at ASC, e.rowid ASC`).bind(...ids).all();
      // Ascending, then last-write-wins into the map: the same answer as
      // DESC + LIMIT 1 per job, in one pass and one statement.
      for (const r of results || []) out[r.job_id] = r;
    } catch (err) { if (!missingSchema(err)) throw err; }
    return out;
  })();
  const withEnding = (j) => {
    const e = endingByJob[j.id];
    return e ? { ...j, ending_kind: e.kind, ending_note: e.note,
      ending_until: e.until, ending_at: e.at } : j;
  };

  // WHICH OF THESE WAS RAISED FROM AN INSPECTION, so the list can mark them.
  // A walk-raised job is a different kind of work -- a list of rooms, an empty
  // unit, a tenancy turning round -- and in a list of forty it read exactly like
  // a leak somebody phoned in. One query, this account's OWN inspections only:
  // an inspection is the team's record, so a job on somebody else's account
  // (owned-not-operated, inherited) is not marked from here, and a TENANT is
  // never told, because an inspection is deliberately not shown to the tenant
  // it is about. A database without 055 marks nothing.
  const inspByJob = await (async () => {
    if (auth.role === "tenant" || !jobs.length) return {};
    const out = {};
    try {
      const ids = jobs.map((j) => j.id);
      const { results } = await c.env.DB.prepare(
        `SELECT i.id, i.job_id, i.kind, i.unit FROM inspections i
          WHERE i.account_id = ? AND i.job_id IN (${ids.map(() => "?").join(",")})`
      ).bind(accountId, ...ids).all();
      for (const r of results || []) out[r.job_id] = { id: r.id, kind: r.kind, unit: r.unit || null };
    } catch (err) { if (!missingSchema(err)) throw err; }
    return out;
  })();

  // Every job leaving this route goes through the same two redactions, rather
  // than each list remembering to apply them.
  const forCaller = (j) => stripOtherTrades(auth,
    stripMoney(auth, jobRowToJs(withEnding(j), woByJob[j.id] || [])));
  return c.json([
    ...jobs.map((j) => ({
      ...forCaller(j),
      ...(j.requested_by_name ? { requestedByName: j.requested_by_name } : {}),
      ...(inspByJob[j.id] ? { fromInspection: inspByJob[j.id] } : {}),
    })),
    ...ownedJobs.map((j) => ({
      ...forCaller(j),
      // Theirs to watch, not to touch.
      atOwnedProperty: true, readOnly: true,
      managedBy: j.managed_by_name || null,
    })),
    // Handled by whoever managed the building at the time, so read-only now.
    // Named, because "who did I report this to" is the question a tenant
    // chasing an old repair is actually asking.
    ...pastReports.map((j) => ({
      ...forCaller(j),
      underPreviousManager: true, readOnly: true,
      managedBy: j.managed_by_name || null,
    })),
    // Open work the previous operator is still finishing. NOT stripMoney'd and
    // then handed over -- stripMoney only redacts for owners and tenants, and
    // the caller here is an admin of their own account, so it would have passed
    // the outgoing manager's prices and contractor straight through.
    // inheritedShape decides what crosses instead: what is wrong with the
    // building and when somebody is due, never who or for how much.
    ...inheritedJobs.map((j) => inheritedShape(
      { ...jobRowToJs(withEnding(j), woByJob[j.id] || []),
        ...(j.requested_by_name ? { requestedByName: j.requested_by_name } : {}) },
      j.prev_name || null)),
  ]);
});

// Every job the API has ever seen, across ALL accounts, but only the fact of
// a booking (no client/address/value) — this is what makes crew availability
// correct across GCs without leaking one account's job details to another.
app.get("/api/jobs/all-bookings", async (c) => {
  const { results } = await c.env.DB.prepare(
    `SELECT wo.company_id, wo.trade, wo.crew_name, j.id as job_id, j.date, j.account_id
     FROM work_orders wo JOIN jobs j ON j.id = wo.job_id
     WHERE wo.voided_at IS NULL AND wo.status != 'declined' AND j.status = 'active'`
  ).all();
  return c.json(results);
});

// 066. THE NEWEST ENDING FOR ONE JOB, stitched onto a row a route has already
// loaded.
//
// Three doors commit a contractor to work -- assign, ask for quotes, post to
// overflow -- and each loads the job with its own named SELECT. Adding a
// correlated subquery to three places is the shape this file keeps recording:
// the one that forgets is the one that issues a work order against a job
// somebody cancelled on Tuesday. One helper, read by all of them.
//
// A database without 066 answers the row unchanged, which is exactly the
// behaviour these routes had before it. Narrow catch, because a catch wide
// enough to hide a real error would hide it in front of a work order.
async function jobWithEnding(env, job) {
  if (!job?.id) return job;
  try {
    const e = await env.DB.prepare(
      `SELECT kind, note, until, at FROM job_endings WHERE job_id = ?
        ORDER BY at DESC, rowid DESC LIMIT 1`).bind(job.id).first();
    if (!e) return job;
    return { ...job, ending_kind: e.kind, ending_note: e.note,
      ending_until: e.until, ending_at: e.at };
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return job;
  }
}

// AND WHY A DOOR THAT COMMITS SOMEBODY ELSE'S TIME IS SHUT, in one place.
//
// Closed and on hold are two different answers and both have to refuse: a
// held job is deliberately NOT closed, so `jobClosure` says no to it and a
// route reading only that would issue the work order. The reason is named
// either way, because "on hold until the 14th" and "cancelled" need different
// sentences and a reversible thing must not be reported as a finished one.
function jobCommitRefusal(job) {
  const shut = jobClosure(job);
  if (shut.closed) return { error: "job_closed", reason: shut.reason };
  const hold = jobHold(job, dayKeyUtc());
  if (hold.held) return { error: "job_deferred", until: hold.until || null };
  return null;
}

// Mark a job as having just moved.
//
// Called from everywhere that changes a job or anything hanging off it --
// its work orders, its visits -- so that "moved" means what a person means
// by it rather than "the jobs row happened to be written to". Deliberately
// swallows its own failure: a job that could not be timestamped is still a
// job, and losing an assignment because the clock write failed would be a
// far worse trade than a row that sorts a little low.
async function touchJob(env, jobId) {
  if (!jobId) return;
  try {
    // datetime('now'), not a JS ISO string. The column is sorted as text and
    // falls back to created_at, which SQLite writes as "2026-09-22 19:28:16".
    // An ISO value carries a "T" where that has a space, and "T" sorts above
    // every digit -- so one job updated at one in the morning would outrank
    // another created at eleven at night. Same format, or no ordering.
    await env.DB.prepare(`UPDATE jobs SET updated_at = datetime('now') WHERE id = ?`)
      .bind(jobId).run();
  } catch (err) {
    if (!missingSchema(err)) throw err;      // a real error is still an error
  }
}

function jobRowToJs(j, workOrders) {
  const assignments = {};
  for (const w of workOrders) {
    assignments[w.trade] = {
      id: w.id, subId: w.company_id, wo: w.wo_number, woIssued: w.issued_at?.slice(0, 10),
      crewName: w.crew_name, tradeScope: w.trade_scope, value: w.value_cents != null ? String(w.value_cents / 100) : "",
      // How it is priced. value stays the ceiling either way, so anything
      // that only cares what this might cost need not know the difference.
      payKind: w.pay_kind || "fixed",
      rate: w.rate_cents != null ? String(w.rate_cents / 100) : "",
      capHours: w.cap_hours != null ? w.cap_hours : null,
      status: w.status, auto: !!w.auto_scheduled, responseWindow: w.response_window, respondBy: w.respond_by,
      respondedAt: w.responded_at, rating: w.rating, distance: w.distance, inRange: !!w.in_range,
      signedWO: w.signed_file_key,
    };
  }
  return {
    id: j.id, accountId: j.account_id, title: j.title, client: j.client, address: j.address, area: j.area, zip: j.zip,
    sqft: j.sqft, stories: j.stories, date: j.date, time: j.time,
    trades: parseJson(j.trades, []), scope: j.scope, materialSource: j.material_source,
    materialSupplier: j.material_supplier || null, materialBranch: j.material_branch || null,
    materialsPaidBy: j.materials_paid_by, measurementDocs: parseJson(j.measurement_docs, []),
    // Only what is needed to list and fetch them -- the R2 key stays on the
    // server, so a photo is only ever reachable through the route below,
    // which re-checks who is asking.
    photos: parseJson(j.photos, []).map((p) => ({ id: p.id, name: p.name, type: p.type, size: p.size, at: p.at })),
    // What the tenant actually answered, for showing back and for editing.
    // Null on anything not raised through the tenant's form, and on reports
    // made before this was kept -- the composed scope is all those have.
    reportDetail: parseJson(j.report_detail, null),
    // "911" or "urgent", or null for the great majority. Decided from what
    // they picked -- see shared/emergency.js.
    severity: j.severity || null,
    // 060. Who has to be there to let somebody in. BOTH halves: the raw
    // column so a screen can tell "not answered" from an answer, and the
    // effective one so nothing has to derive it. The effective value needs the
    // reporter's seat role, which only the server has.
    access: j.access || null,
    // 062. Who has to be let in, when it is not the person who asked. The
    // screen needs it to answer "is there anybody to ask" -- a job marked
    // "the tenant needs to be in" with nobody behind it books outright, and
    // the panel has to say so rather than drawing a confirmation step that
    // will never happen.
    accessUserId: j.access_user_id || null,
    accessEffective: accessFor(j, { tenantReported: j.requested_by_role === "tenant" }),
    status: j.status, completedAt: j.completed_at, notes: j.notes, createdAt: j.created_at?.slice(0, 10), assignments,
    // The column has been on jobs since the beginning and was cleared when a
    // property was deleted, but nothing ever wrote it and nothing ever read
    // it back, so a job's building survived only until the page reloaded.
    propertyId: j.property_id || null,
    // Set when a building owner asked for the work. Until approved_at is
    // filled in it is a request, and nothing may be assigned against it.
    requestedBy: j.requested_by || null, approvedAt: j.approved_at || null,
    // Taken back by whoever reported it. Not a status, because the status
    // column has a CHECK on it; a withdrawn job is out of everything live.
    withdrawnAt: j.withdrawn_at || null, withdrawnNote: j.withdrawn_note || null,
    // Turned down by the manager, with the reason they gave. A request that
    // is neither approved nor declined is still waiting on them.
    declinedAt: j.declined_at || null, declinedNote: j.declined_note || null,
    // 066. HOW IT ENDED, flat, and the same four names `shared/jobstate.js`
    // reads on a raw row. Flat on both sides on purpose: a nested object in
    // the browser and columns on the server is a conversion to forget, and a
    // missed one here reads as "not ended", which is the direction that draws
    // a cancelled job as live work.
    //
    // Absent -- not null -- on a database without 066, which is the signal
    // `jobEnding` needs and the shape this route had before it.
    ...(j.ending_kind ? {
      endingKind: j.ending_kind, endingNote: j.ending_note || null,
      endingUntil: j.ending_until || null, endingAt: j.ending_at || null,
    } : {}),
    // The full timestamp, for the ten minutes in which a report can still be
    // corrected. createdAt above is the date alone and always was.
    createdAtIso: j.created_at || null,
    // When it last moved, by any route: assigned, replied to, scheduled,
    // corrected, approved. What the list sorts on, and what "just updated"
    // is measured from.
    updatedAtIso: j.updated_at || j.created_at || null,
  };
}

// What a building owner is not shown. They see the work, the schedule and who
// is coming; what the account pays a subcontractor is not theirs. Applied on
// the way out of the API rather than hidden in the page, because a value the
// browser is sent is a value the browser can be made to show.
function stripMoney(auth, job) {
  if (auth.role !== "owner" && auth.role !== "tenant") return job;
  const assignments = {};
  for (const [trade, a] of Object.entries(job.assignments || {})) {
    const { value, ...rest } = a;
    assignments[trade] = rest;
  }
  return { ...job, assignments };
}

// What a subcontractor is not shown about a job they ARE on.
//
// Scoping the list to jobs they hold a work order on is only half of it: a job
// carries a work order per trade, and the other two name other companies on
// that account's roster, with what each of them is being paid. Telling a roofer
// which electrician the general contractor uses, and for how much, is the
// accumulation this product refuses everywhere else -- and it needs no special
// access at all, just being on the same job.
//
// So a contractor seat gets its OWN trades and nothing else. Empty rather than
// absent when they hold none, because every screen does
// `j.trades.filter((t) => j.assignments[t])` and a job without the map white-
// screens the jobs list -- the same rule inheritedShape follows, for the same
// reason.
//
// Applied on the way out of the API rather than hidden in the page, because a
// value the browser is sent is a value the browser can be made to show.
function stripOtherTrades(auth, job) {
  if (auth.role !== "contractor" || !auth.companyId) return job;
  const assignments = {};
  for (const [trade, a] of Object.entries(job.assignments || {})) {
    if (a && a.subId === auth.companyId) assignments[trade] = a;
  }
  return { ...job, assignments };
}

// An owner may raise work, which is why this is not requireRole("admin","pm"):
// what they create is a request rather than a job, and the difference is
// enforced below rather than left to the caller to declare.
app.post("/api/jobs", requireRole("admin", "pm", "owner", "tenant"), async (c) => {
  const auth = c.get("auth");
  const { accountId, userId } = auth;

  // Creating a job is the hiring side's act, so a subcontractor account cannot.
  // Enforced here and not only by hiding the button: a gate that lives in the
  // browser is a suggestion.
  //
  // Read off the account rather than the seat. A tenant or an owner raising
  // work at a building is a different path entirely and is never on a
  // subcontractor account, which has no properties.
  const acct = await c.env.DB.prepare(`SELECT kind FROM accounts WHERE id = ?`)
    .bind(accountId).first();
  if (acct && !HIRING_KINDS.includes(acct.kind)) {
    return c.json({ error: "not_a_hiring_account", kind: acct.kind }, 403);
  }

  const b = await c.req.json();
  const id = uid();

  const propertyId = b.propertyId || null;
  // A scoped seat's work has to be at one of their own buildings. Refusing
  // here rather than filtering means work aimed somewhere else is an error
  // they see, not a row that quietly goes missing.
  if (auth.propertyIds) {
    if (!propertyId) return c.json({ error: "property_required" }, 400);
    if (!maySeeProperty(auth, propertyId)) return c.json({ error: "forbidden" }, 403);
  }

  // Which account the job belongs to. Normally the caller's -- but an owner
  // holding a building somebody else RUNS can raise work at it, and that work
  // belongs to the manager, because they are the ones who will do it.
  //
  // This is the other half of appointing a manager. Without it an owner watches
  // their own building, sees the boiler is making a noise, and has no way to say
  // so: they are not a seat on the managing account, so the ordinary owner
  // request is not open to them. The only remaining option is to ring somebody,
  // which is the thing this product exists to stop.
  let jobAccountId = accountId;
  let crossAccount = false;
  // A scoped seat was already checked above, and cannot reach past its own
  // buildings; this only concerns an unscoped caller naming a property.
  if (!auth.propertyIds && propertyId) {
    const prop = await c.env.DB.prepare(
      `SELECT id, account_id, owner_account_id FROM properties WHERE id = ?`
    ).bind(propertyId).first().catch(async (err) => {
      if (!missingSchema(err)) throw err;
      return c.env.DB.prepare(`SELECT id, account_id FROM properties WHERE id = ?`)
        .bind(propertyId).first();
    });
    if (!prop) return c.json({ error: "property_not_found" }, 404);
    if (prop.account_id === accountId) {
      // Their own building, run by them. Nothing changes.
    } else if (prop.owner_account_id === accountId) {
      // Theirs, run by somebody else. The work goes to the manager, as a
      // request they have to approve -- exactly like an owner seat's.
      jobAccountId = prop.account_id;
      crossAccount = true;
    } else {
      return c.json({ error: "property_not_found" }, 404);
    }
  }

  // Owners and tenants raise requests; a scoped property manager is there to
  // run the work, so what they create is a job like any other manager's. An
  // owner reaching into the account that manages their building is a request
  // too, and for the same reason: nobody may commit somebody else's account to
  // a price.
  const requestedBy = (auth.role === "owner" || auth.role === "tenant" || crossAccount)
    ? userId : null;
  // Validated against the account that UPLOADED them, which is the caller's --
  // a cross-account request carries photos that live in the owner's own R2
  // space, and checking them against the manager's would throw away every one.
  const photos = cleanPhotos(b.photos, accountId);
  // A tenant's report sends its answers; everything else sends a scope it
  // wrote itself. Composing here rather than in the browser means the
  // sentence and the parts cannot disagree, whichever of the two edits it.
  const detail = b.reportDetail ? cleanDetail({ ...b.reportDetail, title: b.title }) : null;
  const scope = detail ? composeScope({ ...detail, title: b.title }) : (b.scope || null);
  // Worked out here from what they picked, never taken from the request.
  // Only a tenant's or owner's report can be an emergency: a manager
  // creating their own job already knows how to prioritise it.
  const severity = requestedBy ? severityOf(detail?.problem) : null;
  // Materials. The supplier id is checked against the shared list and the
  // line is composed here, never taken from the request: what a contractor
  // reads on a work order should be something this list produced, not
  // whatever a client sent. An older build sends only materialSource, and
  // that still works.
  const supplier = isSupplier(b.materialSupplier) ? b.materialSupplier : null;
  const branch = supplier && supplier !== OTHER
    ? (String(b.materialBranch || "").trim() || null) : null;
  const materialSource = (supplier
    ? materialLine({ supplier, branch, other: b.materialOther })
    : String(b.materialSource || "").trim()) || null;

  // 060. Who has to be there, when the person creating it already knows.
  // Refused rather than defaulted on an unrecognised word; NULL when nothing
  // was said, which `accessFor` reads as the rule 019 has always run.
  if (b.access !== undefined && b.access !== null && !isAccess(b.access)) {
    return c.json({ error: "bad_access" }, 400);
  }
  // A TENANT OR AN OWNER DOES NOT GET TO ANSWER IT. They are the side being
  // let in or the side asking for the work -- whether somebody has to be home
  // is the managing side's call, and taking it from the request would let a
  // tenant book themselves out of their own confirmation step.
  const access = requestedBy ? null : (b.access || null);

  const cols = ["id", "account_id", "title", "client", "address", "area", "zip", "sqft", "stories",
    "date", "time", "trades", "scope", "material_source", "materials_paid_by", "measurement_docs",
    "created_by", "property_id", "requested_by", "photos", "report_detail", "severity"];
  const vals = [id, jobAccountId, b.title, b.client || null, b.address || null, b.area || null,
    b.zip || null, b.sqft || null, b.stories || null, b.date || null, b.time || "07:00",
    JSON.stringify(b.trades || []), scope, materialSource, b.materialsPaidBy || null,
    JSON.stringify(b.measurementDocs || []), userId, propertyId, requestedBy,
    photos.length ? JSON.stringify(photos) : null, detail ? JSON.stringify(detail) : null, severity];

  // AN EXTRA COLUMN, and only when there is something to say. NULL is the
  // default and reads as the rule 019 has always run, so a job nobody answered
  // the question for never touches a column 060 added -- which is what keeps a
  // database behind the code able to create one at all. The same reason
  // `material_supplier` is an extra rather than a base column.
  const accessCols = access ? ["access"] : [];
  const accessVals = access ? [access] : [];

  const insertJob = (extraCols, extraVals) => {
    const all = [...cols, ...extraCols];
    return c.env.DB.prepare(
      `INSERT INTO jobs (${all.join(", ")}) VALUES (${all.map(() => "?").join(", ")})`
    ).bind(...vals, ...extraVals).run();
  };

  try {
    try {
      await insertJob(["material_supplier", "material_branch", ...accessCols],
        [supplier, branch, ...accessVals]);
    } catch (err) {
      // 026 only adds the counting. The line a person reads is already in
      // material_source, so a database that has not had it yet must still
      // be able to take a job -- refusing to create one over a column that
      // exists for reporting would be a far worse failure than the one it
      // is guarding.
      //
      // 060 is the same trade one column along: losing the access answer
      // costs a round trip with the tenant that was not needed, and refusing
      // the job entirely costs the repair.
      const which = missingSchema(err);
      if (which === "060_job_access") {
        console.warn("[jobs] 060_job_access not applied - saving without who lets them in");
        await insertJob(["material_supplier", "material_branch"], [supplier, branch]);
      } else if (which === "026_material_supplier") {
        console.warn("[jobs] 026_material_supplier not applied - saving without the supplier columns");
        await insertJob(accessCols, accessVals);
      } else throw err;
    }
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }

  // A NARROWED SEAT KEEPS WHAT IT JUST MADE. Without this, a project manager
  // scoped to four jobs creates a fifth and it vanishes on the next render --
  // the screen worked, the job exists, and the person who made it cannot find
  // it or act on it. Creating something is the clearest possible statement
  // that it is yours to run, and this is the only place that statement is
  // made, so it is the only place that can record it.
  if (auth.jobIds && !crossAccount) {
    try {
      await c.env.DB.prepare(
        `INSERT OR IGNORE INTO membership_jobs (membership_id, job_id) VALUES (?, ?)`
      ).bind(auth.membershipId, id).run();
    } catch (err) { if (!missingSchema(err)) throw err; }
  }

  if (crossAccount) {
    // Both feeds. The manager has a request to answer; the owner has a record
    // of having asked, on the account they actually run.
    const who = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`).bind(userId).first();
    const where = await c.env.DB.prepare(`SELECT name FROM properties WHERE id = ?`)
      .bind(propertyId).first();
    await logEvent(c.env, jobAccountId, userId, "job.requested", id,
      { title: b.title, byAccount: accountId });
    await logActivity(c.env, jobAccountId, null, "job_requested",
      `${who?.name || "The owner"} asked for work at ${where?.name || "their building"}: ${b.title}`);
    await logActivity(c.env, accountId, userId, "job_requested",
      `Asked your manager for work at ${where?.name || "your building"}: ${b.title}`);
  } else if (requestedBy) {
    await logEvent(c.env, accountId, userId, "job.requested", id, { title: b.title });
    await logActivity(c.env, accountId, userId, "job_requested", `Requested work: ${b.title}`);
  } else {
    await logEvent(c.env, accountId, userId, "job.created", id, { title: b.title });
    await logActivity(c.env, accountId, userId, "job_created", `Created job ${b.title}`);
  }
  // The row as stored, not just its id. What the browser can guess about a
  // job it has just created is not the same as what was written: it has no
  // created_at to the second, so the ten-minute edit window read as already
  // over, and no ids for the photos it just sent, so they could not be
  // fetched back. Both looked like features that did not work.
  // Urgent, and somebody named to take it: send them, now, and say so in
  // the answer so the tenant is told a contractor is already coming rather
  // than being left to wonder. A fire never reaches this -- emergency
  // services are not a subcontractor.
  let emergency = null;
  if (severity === "urgent" && crossAccount) {
    // Not ours to dispatch. dispatchEmergency approves the job and issues a
    // work order against the ACCOUNT'S emergency contractor -- run here it
    // would approve the manager's job from the owner's side and engage the
    // owner's contractor on it. Urgency travels as information; the manager
    // holds the contractor, the money and the decision.
    emergency = { dispatched: false, reason: "manager_decides" };
  } else if (severity === "urgent") {
    emergency = await dispatchEmergency(c, id, accountId);
  }

  const saved = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ?`).bind(id).first();
  const wos = saved ? (await c.env.DB.prepare(
    `SELECT * FROM work_orders WHERE job_id = ? AND voided_at IS NULL`).bind(id).all()).results : [];
  return c.json({ id, requested: !!requestedBy, severity,
    emergency, job: saved ? jobRowToJs(saved, wos) : null }, 201);
});

// Turning an owner's request into a job somebody can be assigned to. Only the
// account can do this -- that is the entire point of a request.
// Tell the tenant who reported a job that it has moved, if they asked to be
// told. Never throws: a message that could not go out must not undo the
// approval or the assignment that caused it. Owners raise requests too, but
// they have a dashboard for this; a tenant has an inbox.
async function notifyTenant(c, jobId, stage, detail = null) {
  try {
    // 062. `access_user_id` as well, because the tenant who has to be let in
    // is not always the one who asked -- a job raised from a move-in
    // inspection has nobody who asked for it. Optional: a database without
    // 062 keeps the requester, which is what this has always read.
    const job = await (async () => {
      for (const cols of [", access_user_id", ""]) {
        try {
          return await c.env.DB.prepare(
            `SELECT id, title, account_id, requested_by, withdrawn_at${cols} FROM jobs WHERE id = ?`
          ).bind(jobId).first();
        } catch (err) { if (!missingSchema(err)) throw err; }
      }
      return null;
    })();
    const who = accessTenant(job);
    if (!who || job.withdrawn_at) return;
    const [user, seat, account] = await Promise.all([
      c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(who).first(),
      c.env.DB.prepare(`SELECT role FROM memberships WHERE user_id = ? AND account_id = ?`)
        .bind(who, job.account_id).first(),
      c.env.DB.prepare(`SELECT id, name, subdomain, hostname_status FROM accounts WHERE id = ?`)
        .bind(job.account_id).first(),
    ]);
    if (!user || seat?.role !== "tenant") return;
    const prefs = notifyOf(user);
    if (!prefs.statusChanges) return;
    const link = `${accountOrigin(account)}/`;
    const firstName = String(user.name || "").split(" ")[0];
    const email = realEmail(user.email);
    const sentBy = c.get("auth")?.userId ?? null;
    if (prefs.email && email) {
      const m = tenantStatusEmail({ firstName, account, title: job.title, stage, link, detail });
      const result = await sendEmail(c.env, { to: email, subject: m.subject, text: m.text, html: m.html });
      await logMail(c.env, { accountId: job.account_id, to: email, kind: "tenant_status",
        subject: m.subject, result, sentBy });
    }
    if (prefs.sms && user.phone) {
      const body = tenantStatusSms({ account, title: job.title, stage, link, detail });
      await sendAccountSms(c.env, { accountId: job.account_id, to: user.phone,
        kind: "tenant_status", body });
    }
  } catch (err) {
    console.error("[tenant-notify] failed:", err?.message || err);
  }
}

app.post("/api/jobs/:id/approve", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const job = await c.env.DB.prepare(
    `SELECT id, title, requested_by, approved_at, withdrawn_at FROM jobs WHERE id = ? AND account_id = ?`
  ).bind(id, accountId).first();
  if (!job || !maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  if (!job.requested_by) return c.json({ error: "not_a_request" }, 400);
  if (job.withdrawn_at) return c.json({ error: "withdrawn" }, 409);
  if (job.approved_at) return c.json({ ok: true, alreadyApproved: true });

  // Clearing the decline as well: approving one that was turned down is
  // changing your mind about it, and it must not read as both.
  await c.env.DB.prepare(
    `UPDATE jobs SET approved_at = datetime('now'), declined_at = NULL, declined_note = NULL
      WHERE id = ? AND account_id = ?`
  ).bind(id, accountId).run();
  await touchJob(c.env, id);
  await logEvent(c.env, accountId, userId, "job.approved", id, { title: job.title });
  await logActivity(c.env, accountId, userId, "job_approved", `Approved requested work: ${job.title}`);
  await notifyTenant(c, id, "approved");
  return c.json({ ok: true });
});

// Saying no. A request that cannot be said no to sits on the dashboard
// forever and the person who asked is never told, which is worse than a
// refusal. The reason is required: "declined" on its own is what makes
// somebody pick up the phone, and not having to pick up the phone is the
// point of all this.
app.post("/api/jobs/:id/decline", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const note = String(b.note || "").trim().slice(0, 500);
  if (!note) return c.json({ error: "reason_required" }, 400);
  const job = await c.env.DB.prepare(
    `SELECT id, title, requested_by, approved_at, withdrawn_at, declined_at, status
       FROM jobs WHERE id = ? AND account_id = ?`).bind(id, accountId).first();
  if (!job || !maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  if (!job.requested_by) return c.json({ error: "not_a_request" }, 400);
  if (job.withdrawn_at) return c.json({ error: "withdrawn" }, 409);
  if (job.status === "completed") return c.json({ error: "already_completed" }, 409);
  if (job.approved_at) return c.json({ error: "already_approved" }, 409);
  if (job.declined_at) return c.json({ ok: true, alreadyDeclined: true });
  try {
    await c.env.DB.prepare(`UPDATE jobs SET declined_at = ?, declined_note = ? WHERE id = ?`)
      .bind(new Date().toISOString(), note, id).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  await logEvent(c.env, accountId, userId, "job.declined", id, { title: job.title, note });
  await logActivity(c.env, accountId, userId, "job_declined", `Didn't approve "${job.title}": ${note}`);
  await touchJob(c.env, id);
  await notifyTenant(c, id, "declined", note);
  return c.json({ ok: true });
});

app.post("/api/jobs/:id/complete", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  await c.env.DB.prepare(
    `UPDATE jobs SET status = 'completed', completed_at = ? WHERE id = ? AND account_id = ?`
  ).bind(new Date().toISOString().slice(0, 10), id, accountId).run();
  await logEvent(c.env, accountId, userId, "job.completed", id, {});
  { const j = await c.env.DB.prepare(`SELECT title FROM jobs WHERE id = ?`).bind(id).first();
    await logActivity(c.env, accountId, userId, "job_completed", `Completed ${j?.title || "a job"}`); }
  await touchJob(c.env, id);
  await notifyTenant(c, id, "done");
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Visits: the proposed time for a repair, confirmed by the tenant
// ---------------------------------------------------------------------------
//
// A report went from "contractor assigned" to "done" with the person who
// lives there told nothing about when anybody would turn up. The manager or
// the contractor proposes a date and a window; the tenant confirms it or
// says it doesn't work, in the app; only a confirmed visit puts a date on
// the job and reads as "Scheduled" to them. One live visit per job.

const visitRowToJs = (v) => ({
  id: v.id, jobId: v.job_id, date: v.date, startTime: v.start_time || null, endTime: v.end_time || null,
  note: v.note || null, status: v.status, tenantNote: v.tenant_note || null,
  proposedBy: v.proposed_by || null, createdAt: v.created_at, respondedAt: v.responded_at || null,
  // 061. The contractor's half, kept apart from the tenant's. One column
  // carrying both answers would make every row written before 061 ambiguous
  // about which side it was that replied.
  contractorAt: v.contractor_at || null, contractorNote: v.contractor_note || null,
  // 064. The hiring side's own leg, which is what makes the three parties a
  // chain. They agree to their own proposal by making it.
  managerAt: v.manager_at || null,
});

// WHO IS STILL OWED AN ANSWER ON THIS JOB. Both facts come off the database --
// the reporter's seat role and whether anybody holds the work -- because a
// screen deriving either would be a second opinion about whose answer is
// outstanding, and the two sides disagreeing is how both draw "waiting on
// them" and nothing moves.
async function partiesFor(env, job) {
  // 062. WHICH tenant, which is not always the requester. A job raised from a
  // move-in inspection has nobody who asked for it and a named tenant who will
  // be standing in the unit, so the seat looked up here is theirs.
  const who = accessTenant(job);
  const seat = who ? await env.DB.prepare(
    `SELECT role FROM memberships WHERE user_id = ? AND account_id = ?`)
    .bind(who, job.account_id).first().catch(() => null) : null;
  // A window proposed before anybody is assigned has nobody to ask. ACCEPTED
  // rather than any live work order: somebody who has not said yes to the JOB
  // cannot be waited on for the time, and treating a pending offer as a party
  // would leave every visit stuck behind a work order nobody has opened.
  const wo = await env.DB.prepare(
    `SELECT 1 AS yes FROM work_orders
      WHERE job_id = ? AND voided_at IS NULL AND status = 'accepted' LIMIT 1`
  ).bind(job.id).first().catch(() => null);
  return visitParties(job, { tenantReported: seat?.role === "tenant", hasContractor: !!wo?.yes,
    hasManagerLeg: await hasManagerLeg(env) });
}

// WHETHER 064 IS APPLIED, asked of the schema rather than assumed.
//
// Not cached: a stale `false` would keep every appointment on the 061 shape
// for however long an isolate lives after the migration is pasted, and these
// routes are not hot enough for the pragma to matter. Read by COLUMN rather
// than by table name, which is the lesson 052 paid for against a live
// database -- `sqlite_master` says a table is there and `pragma_table_info`
// says it is the right one.
async function hasAccessUser(env) {
  try {
    const r = await env.DB.prepare(
      `SELECT COUNT(*) AS n FROM pragma_table_info('jobs') WHERE name = 'access_user_id'`).first();
    return !!r?.n;
  } catch { return false; }
}
async function hasManagerLeg(env) {
  try {
    const r = await env.DB.prepare(
      `SELECT COUNT(*) AS n FROM pragma_table_info('visits') WHERE name = 'manager_at'`).first();
    return !!r?.n;
  } catch { return false; }
}
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/, TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

app.get("/api/visits", async (c) => {
  const auth = c.get("auth");
  const scope = scopeClause(auth, "j.property_id");
  // 062 LEFT THIS BEHIND, and the chain is what made it matter. A tenant named
  // on `access_user_id` -- which is every job raised from a move-in inspection
  // -- was filtered out of their own appointments, so the window they are now
  // asked to confirm last was one they could never see. The route that decides
  // who may ANSWER has read both since 062; this one still read the requester.
  // Guarded on the column, because a database without 062 has none and this
  // SELECT is the tenant's whole appointment list: naming a column that is not
  // there would answer `migration_needed` to every tenant rather than losing
  // the one row shape they do not have yet.
  const au = auth.role === "tenant" && await hasAccessUser(c.env);
  const mine = auth.role === "tenant"
    ? (au ? " AND (j.requested_by = ? OR j.access_user_id = ?) " : " AND j.requested_by = ? ")
    : "";
  // A CONTRACTOR SEAT IS NARROWED BY ITS WORK ORDERS, the same way
  // /api/jobs is, and was not. `scopeClause` answers nothing for a contractor
  // -- it narrows by buildings and a contractor has none -- so this list was
  // every appointment on the account: when a manager is due at every other
  // building, for every job this company holds no work order on. The same
  // leak /api/jobs already closed, one table along, and it got wider the
  // moment anything started reading this list from the portal.
  //
  // By the WORK ORDER, never the job: holding one is the thing that says this
  // job was given to them.
  const asContractor = auth.role === "contractor" && auth.companyId;
  const woScope = asContractor
    ? ` AND EXISTS (SELECT 1 FROM work_orders w
                      WHERE w.job_id = j.id AND w.company_id = ? AND w.voided_at IS NULL) `
    : "";
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT v.* FROM visits v JOIN jobs j ON j.id = v.job_id
        WHERE v.account_id = ? ${scope.sql} ${mine} ${woScope} AND v.status != 'superseded'
        -- created_at is second-granular, so two visits written in the same
        -- second tie and the order becomes whatever the table felt like.
        -- The client takes the first row per job, so this decides which
        -- visit a tenant is shown: newest wins, and rowid breaks the tie.
        ORDER BY v.created_at DESC, v.rowid DESC`
    ).bind(auth.accountId, ...scope.vals,
      ...(auth.role === "tenant" ? (au ? [auth.userId, auth.userId] : [auth.userId]) : []),
      ...(asContractor ? [auth.companyId] : [])).all();
    // 064. WHOSE TURN EACH ONE IS, worked out here rather than on the screen.
    // The tenant is last in the chain and their screen holds no work orders,
    // so it cannot know whether the crew has agreed -- and a screen guessing
    // would be a second opinion about whose answer is outstanding, which is
    // the thing `visitparty.js` exists to stop.
    //
    // Memoised per JOB rather than per visit: parties are a fact about the
    // job, and a list of forty appointments across eight jobs is eight
    // lookups.
    const byJob = new Map();
    const rows = [];
    for (const r of results || []) {
      if (!byJob.has(r.job_id)) {
        const j = await c.env.DB.prepare(
          `SELECT id, account_id, requested_by${await hasAccessUser(c.env) ? ", access, access_user_id" : ""}
             FROM jobs WHERE id = ?`).bind(r.job_id).first().catch(() => null);
        byJob.set(r.job_id, { job: j, parties: j ? await partiesFor(c.env, j) : [] });
      }
      // Narrowed per WINDOW, because who proposed it is a fact about the
      // window: one the tenant put forward is settled by the crew alone.
      const { job: pj, parties: jp } = byJob.get(r.job_id);
      const parties = windowParties(jp, { byTenant: !!pj && tenantProposed(r, pj) });
      rows.push({ ...visitRowToJs(r), parties, turn: nextToAnswer(visitRowToJs(r), parties) });
    }
    return c.json(rows);
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// Propose one. The manager, or a contractor who holds a live work order on
// the job -- they are the one who knows when they can come.
// AND THE TENANT, who until now could only say yes or no to a time somebody
// else picked. The person who has to be in is the one most likely to know a
// better morning, and "that doesn't work" with no way to say what would is a
// round trip through a note field the manager then has to turn into a date.
app.post("/api/jobs/:id/visits", requireRole("admin", "pm", "contractor", "tenant"), async (c) => {
  const auth = c.get("auth");
  const jobId = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  // THE TWO SCHEDULING COLUMNS ARE OPTIONAL, newest first. A database behind
  // the code keeps the rule 019 has been running -- which is what `accessFor`
  // falls back to anyway -- because one missing column must not stop anybody
  // scheduling a repair. Written as a cascade rather than nested catches: 060
  // and 062 can be missing together or one at a time, and three hand-written
  // catches is the shape that goes wrong on the fourth column.
  const job = await (async () => {
    for (const cols of ["access, access_user_id", "access", ""]) {
      try {
        return await c.env.DB.prepare(
          `SELECT id, title, requested_by, approved_at${cols ? ", " + cols : ""}
             FROM jobs WHERE id = ? AND account_id = ?`
        ).bind(jobId, auth.accountId).first();
      } catch (err) { if (!missingSchema(err)) throw err; }
    }
    return null;
  })();
  if (!job || !maySeeJob(c.get("auth"), jobId)) return c.json({ error: "job_not_found" }, 404);
  if (job.requested_by && !job.approved_at) return c.json({ error: "not_approved" }, 409);
  if (auth.role === "contractor") {
    const wo = await c.env.DB.prepare(
      `SELECT id FROM work_orders WHERE job_id = ? AND company_id = ? AND voided_at IS NULL`
    ).bind(jobId, auth.companyId).first();
    if (!wo) return c.json({ error: "forbidden" }, 403);
  }
  // A tenant proposes only for the job they have to be in for. Somebody else's
  // report answers as missing, the same reply as a job that does not exist, so
  // a tenant cannot learn which ids are real.
  if (auth.role === "tenant" && accessTenant(job) !== auth.userId) {
    return c.json({ error: "job_not_found" }, 404);
  }
  const date = String(b.date || "").trim();
  const start = b.startTime ? String(b.startTime).trim() : null;
  const end = b.endTime ? String(b.endTime).trim() : null;
  if (!DATE_RE.test(date)) return c.json({ error: "bad_date" }, 400);
  if ((start && !TIME_RE.test(start)) || (end && !TIME_RE.test(end))) return c.json({ error: "bad_time" }, 400);
  if (start && end && end <= start) return c.json({ error: "bad_window" }, 400);
  const note = String(b.note || "").trim().slice(0, 500) || null;

  // WHO HAS TO AGREE, and until 060 this was derived and nothing could
  // override it: a tenant's repair waited on that tenant, anything else was
  // booked straight away. Good default, no way out -- so a tenant reporting a
  // leaking roof, which is fixed from outside, sat waiting on them to agree a
  // morning they did not need to be home for.
  //
  // `accessFor` takes the stored answer when there is one and falls back to
  // exactly that rule when there is not, so a job raised before this existed
  // behaves as it always did.
  const seat = job.requested_by ? await c.env.DB.prepare(
    `SELECT role FROM memberships WHERE user_id = ? AND account_id = ?`).bind(job.requested_by, auth.accountId).first() : null;
  const access = accessFor(job, { tenantReported: seat?.role === "tenant" });
  // AND A JOB NOBODY REPORTED HAS NOBODY TO ASK, whatever the column says. A
  // manager can mark a job "the tenant needs to be in" on a building with no
  // tenant seat on it at all, and then the visit would sit proposed for ever
  // with nobody able to answer it -- the waiting-on-somebody-who-cannot-reply
  // failure this file records about a handshake behind a capability nobody
  // has. The override decides whether to ask; whether there is anybody to ask
  // is still a fact.
  const needsTenant = needsTenantConfirm(access) && canAskTenant(job);
  // And a tenant who does not have to be in has no window to propose: the
  // repair is fixed from outside, or the agent lets them in, and a time from
  // them would be a time nobody asked for. Said rather than written.
  if (auth.role === "tenant" && !needsTenant) return c.json({ error: "no_tenant_needed" }, 409);
  // 061. And whether anybody holds the work, which is the other side that has
  // to agree. A time the crew cannot make is not a time.
  // A tenant's own window is settled by the crew, not by the hiring side as
  // well -- see `windowParties`.
  const parties = windowParties(await partiesFor(c.env, { ...job, account_id: auth.accountId }),
    { byTenant: auth.role === "tenant" });
  // PROPOSING IS AGREEING, for whoever proposed it. A contractor who offers
  // Tuesday has said they can come on Tuesday, and asking them to confirm
  // their own suggestion is a round trip that answers nothing -- the same
  // reason the side that asks for a handover has already agreed by asking.
  // 064. AND WHICH LEG IS THEIRS. Every side agrees by proposing, so the only
  // question is which column the stamp lands in. The hiring side gets one of
  // its own now, which is what turns three parties asked at once into a chain
  // that asks the crew first and the tenant last.
  const nowIso = new Date().toISOString();
  const myLeg = auth.role === "contractor" ? "contractor"
    : auth.role === "tenant" ? "tenant" : "manager";
  const crewGranted = myLeg === "manager" && parties.includes("contractor")
    && await crewGrantedBooking(c.env, { jobId, accountId: auth.accountId, date });
  const mineNow = myLeg === "contractor" || crewGranted ? nowIso : null;
  const id = uid();
  try {
    // The combined verdict from one rule, rather than a second expression of
    // it written here: `visitSettled` is what every screen reads, so the row
    // and the screens cannot disagree about whether this is booked.
    // 019 stamped `responded_at` on a visit nobody had to confirm, so the row
    // read as answered. With 061 the verdict comes from `visitSettled` and
    // that stamp is both redundant and untrue: the column is the TENANT's
    // answer, and on a job they are not a party to there was no answer to
    // record. Left NULL, so the row cannot claim one.
    // A TENANT'S OWN COUNTER IS THEIR AGREEMENT TOO, which is what keeps the
    // chain bounded: it re-enters at the contractor rather than asking the
    // person who just proposed it to confirm their own suggestion.
    const seeded = {
      respondedAt: myLeg === "tenant" ? nowIso : null,
      contractorAt: mineNow,
      managerAt: myLeg === "manager" ? nowIso : null,
    };
    const status = visitSettled({ ...seeded, status: "proposed" }, parties);
    // NEWEST COLUMN FIRST, AND A DATABASE BEHIND THE CODE KEEPS THE SHAPE IT
    // HAS. Losing a leg costs a confirmation; refusing the insert costs
    // anybody the ability to schedule a repair at all -- which is the trade
    // 061 already made one column along, and the reason the fallbacks compute
    // their own status rather than carrying this one down.
    const shapes = [
      { cols: ", responded_at, contractor_at, manager_at",
        vals: [seeded.respondedAt, seeded.contractorAt, seeded.managerAt], status },
      { cols: ", responded_at, contractor_at",
        vals: [seeded.respondedAt, seeded.contractorAt],
        status: visitSettled({ ...seeded, managerAt: null, status: "proposed" },
          parties.filter((pp) => pp !== "manager")) },
      { cols: ", responded_at", vals: [seeded.respondedAt],
        status: needsTenant ? "proposed" : "confirmed" },
    ];
    let wrote = false;
    for (const sh of shapes) {
      try {
        await c.env.DB.prepare(
          `INSERT INTO visits (id, account_id, job_id, proposed_by, date, start_time, end_time, note,
             status${sh.cols})
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?${sh.vals.map(() => ", ?").join("")})`
        ).bind(id, auth.accountId, jobId, auth.userId, date, start, end, note,
          sh.status, ...sh.vals).run();
        wrote = true;
        break;
      } catch (err) {
        const m = missingSchema(err);
        if (m !== "064_visit_manager" && m !== "061_visit_contractor") throw err;
        console.warn(`[visits] ${m} not applied - that side is not asked`);
      }
    }
    if (!wrote) throw new Error("no such column: visits");
    // AND THE OLD ONE COMES DOWN ONLY NOW THAT THE NEW ONE IS THERE.
    //
    // This ran FIRST, and the two statements are not a transaction -- so an
    // insert that failed for any reason left the job with NO live visit at
    // all: the appointment gone, and a refusal on screen that reads as
    // nothing having happened. Which is exactly what a contractor's card
    // showing "Target date. No visit time has been agreed" looks like over a
    // job that had a window on it an hour earlier.
    //
    // Reversed, the worst case is a stale row nothing reads: every reader
    // takes the newest live visit by `created_at DESC, rowid DESC`, and the
    // new one is the newest by construction. A vanished appointment is a
    // crew nobody told; a superseded row that did not get the word is
    // invisible. Including 'confirmed', because "propose a different time" is
    // exactly that -- the time that was agreed is no longer the time.
    await c.env.DB.prepare(
      `UPDATE visits SET status = 'superseded'
        WHERE job_id = ? AND id <> ?
          AND status IN ('proposed', 'confirmed', 'declined', 'missed', 'happened')`
    ).bind(jobId, id).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  const when = visitWhen({ date, start_time: start, end_time: end });
  // THE DATE LANDS ON THE JOB WHEN IT IS SETTLED, not when the tenant alone
  // has been dealt with. `needsTenant` answers one side; a window the crew has
  // not agreed to is not a booking either, and writing the date for it would
  // put a job on a calendar nobody has committed to -- which is the state this
  // whole change exists to stop reading as settled.
  const made = await c.env.DB.prepare(`SELECT * FROM visits WHERE id = ?`).bind(id).first();
  if (made?.status === "confirmed") {
    await c.env.DB.prepare(`UPDATE jobs SET date = ?, time = ? WHERE id = ?`).bind(date, start || "07:00", jobId).run();
    await logActivity(c.env, auth.accountId, auth.userId, "visit_set", `Set a visit for "${job.title}": ${when}`);
  } else {
    await logActivity(c.env, auth.accountId, auth.userId, "visit_proposed",
      `Proposed a visit for "${job.title}": ${when}`);
  }
  // Not the tenant about a time they put forward themselves.
  if (needsTenant && myLeg !== "tenant") await notifyTenant(c, jobId, "visit", when);
  await touchJob(c.env, jobId);
  const row = await c.env.DB.prepare(`SELECT * FROM visits WHERE id = ?`).bind(id).first();
  return c.json({ ...visitRowToJs(row), parties, waitingOn: visitWaitingOn(visitRowToJs(row), parties),
    turn: nextToAnswer(visitRowToJs(row), parties) }, 201);
});

// The tenant's answer. Only the person who reported it; only while it is
// still open. Confirming puts the date on the job -- that is the moment it
// becomes scheduled, not the moment somebody proposed it.
app.post("/api/visits/:id/respond", async (c) => {
  const auth = c.get("auth");
  // 061. TWO SIDES MAY ANSWER NOW, and which one you are decides which column
  // your answer lands in. The tenant has answered here since 019; the
  // contractor could neither accept a window nor say it does not work, so a
  // time agreed between a manager and a tenant could be a morning the crew was
  // already on another roof -- discovered by nobody turning up.
  // 064. THREE SIDES MAY ANSWER NOW. The hiring side joined because the order
  // matters: they agree to their own proposal by making it, and have agreed to
  // nothing when the contractor comes back with a different time.
  const MAY_ANSWER = ["tenant", "contractor", "admin", "pm"];
  if (!MAY_ANSWER.includes(auth.role)) return c.json({ error: "forbidden" }, 403);
  const b = await c.req.json().catch(() => ({}));
  const status = b.status === "confirmed" ? "confirmed" : b.status === "declined" ? "declined" : null;
  if (!status) return c.json({ error: "bad_status" }, 400);
  const v = await (async () => {
    for (const cols of [", j.access, j.access_user_id", ", j.access", ""]) {
      try {
        return await c.env.DB.prepare(
          `SELECT v.*, j.id AS jid, j.account_id AS jacct, j.requested_by, j.title${cols}
             FROM visits v JOIN jobs j ON j.id = v.job_id
            WHERE v.id = ? AND v.account_id = ?`).bind(c.req.param("id"), auth.accountId).first();
      } catch (err) { if (!missingSchema(err)) throw err; }
    }
    return null;
  })();
  if (!v) return c.json({ error: "not_found" }, 404);
  // WHOSE ANSWER THIS IS, checked on the row rather than taken from the body.
  // A tenant answers their own report; a contractor answers only where they
  // hold the work -- the same rule the propose route beside it applies, and
  // the reason it is the work order rather than the engagement is that holding
  // one is what says this job was given to them.
  const isTenant = auth.role === "tenant";
  // Which leg this seat answers with. One word, read by the turn check, the
  // column choice and the sentence in the trail, so the three cannot disagree
  // about who it was that replied.
  const myLeg = isTenant ? "tenant" : auth.role === "contractor" ? "contractor" : "manager";
  // 062. THE TENANT WHO HAS TO BE LET IN, which on a job raised from a move-in
  // inspection is not the requester -- there is no requester. One predicate,
  // so this cannot disagree with the propose route about who may answer.
  if (isTenant && accessTenant(v) !== auth.userId) return c.json({ error: "forbidden" }, 403);
  if (myLeg === "contractor") {
    const wo = await c.env.DB.prepare(
      `SELECT 1 AS yes FROM work_orders
        WHERE job_id = ? AND company_id = ? AND voided_at IS NULL AND status = 'accepted' LIMIT 1`
    ).bind(v.job_id, auth.companyId).first();
    if (!wo?.yes) return c.json({ error: "forbidden" }, 403);
  }
  // The hiring side answers for its own account, which the row lookup above
  // already scoped -- so there is nothing further to check for them.
  if (v.status !== "proposed") return c.json({ error: "not_open", status: v.status }, 409);
  const note = String(b.note || "").trim().slice(0, 500) || null;

  const vJob = { id: v.job_id, account_id: auth.accountId,
    requested_by: v.requested_by, access: v.access, access_user_id: v.access_user_id };
  let parties = windowParties(await partiesFor(c.env, vJob), { byTenant: tenantProposed(v, vJob) });
  // A DATABASE WITHOUT 061 HAS NO CONTRACTOR LEG, and `SELECT v.*` is what
  // says so: the key is absent rather than null. Without this the tenant
  // confirms, the contractor is counted as a party who can never answer, and
  // the window sits proposed for ever -- a repair that stops moving because of
  // a migration nobody has run. The two-party shape 019 shipped is what a
  // database behind the code keeps.
  if (!Object.prototype.hasOwnProperty.call(v, "contractor_at")) {
    parties = parties.filter((pp) => pp !== "contractor");
  }
  // And the same signal for 064's own column, for the same reason: a party
  // that cannot answer is an appointment that never settles.
  if (!Object.prototype.hasOwnProperty.call(v, "manager_at")) {
    parties = parties.filter((pp) => pp !== "manager");
  }
  // ONLY IN TURN, WHICH IS THE WHOLE OF 064 ON THIS ROUTE. The tenant is
  // outstanding from the moment a window is proposed and must not be ASKED
  // until the crew has said they can come -- otherwise they book a morning off
  // work for a time that then evaporates, and the second ask is the one that
  // costs their trust. Refused rather than merely not offered, because a
  // screen is a convenience and this is the rule.
  //
  // A DECLINE IS EXEMPT. "I cannot make this" is true whenever it is said, and
  // holding it until somebody's turn would collect agreement to a window that
  // is already dead.
  // AND A SIDE WHOSE COLUMN IS NOT THERE IS TOLD WHICH MIGRATION, rather than
  // that it is not their turn. Both are refusals and only one is actionable:
  // "not your turn" sends somebody to wait for a hand-off that can never come,
  // when what is actually wrong is a paste nobody has run.
  const LEG_COL = { tenant: "responded_at", contractor: "contractor_at", manager: "manager_at" };
  if (!Object.prototype.hasOwnProperty.call(v, LEG_COL[myLeg])) {
    return c.json({ error: "migration_needed",
      migration: myLeg === "manager" ? "064_visit_manager" : "061_visit_contractor" }, 503);
  }
  // AND THE TENANT MAY SAY YES EARLY. `mayConfirm` holds the rule and the
  // reason: the chain decides whom we ask, not who may speak, and a tenant
  // looking at a window put forward for their own home was being shown
  // "Confirm a time" with nothing to press.
  if (status !== "declined" && !mayConfirm(v, parties, myLeg)) {
    return c.json({ error: "not_your_turn", turn: nextToAnswer(v, parties) }, 409);
  }
  const now = new Date().toISOString();
  // A DECLINE FROM EITHER SIDE ENDS IT. A time one party cannot make is not a
  // time, and carrying on collecting the other side's answer would leave a
  // window with a tick against it that nobody is attending -- the worst of the
  // three states, because it reads as settled.
  const after = status === "declined" ? { status: "declined" } : {
    respondedAt: myLeg === "tenant" ? now : (v.responded_at || null),
    contractorAt: myLeg === "contractor" ? now : (v.contractor_at || null),
    managerAt: myLeg === "manager" ? now : (v.manager_at || null),
  };
  const nextStatus = status === "declined" ? "declined" : visitSettled(after, parties);

  const cols = myLeg === "tenant"
    ? `status = ?, tenant_note = ?, responded_at = ?`
    : myLeg === "contractor"
      ? `status = ?, contractor_note = ?, contractor_at = ?`
      // The hiring side's note rides in the contractor's column deliberately:
      // it is a note about the WINDOW, and a fourth column for one more
      // sentence is a column to keep in step for nothing. `manager_at` is
      // what says who agreed.
      : `status = ?, contractor_note = COALESCE(?, contractor_note), manager_at = ?`;
  try {
    await c.env.DB.prepare(`UPDATE visits SET ${cols} WHERE id = ?`)
      .bind(nextStatus, note, now, v.id).run();
  } catch (err) {
    if (!missingSchema(err) || isTenant) throw err;
    return c.json({ error: "migration_needed", migration: missingSchema(err) }, 503);
  }

  const when = visitWhen(v);
  const who = isTenant ? "visit" : "visit by the contractor";
  if (nextStatus === "confirmed") {
    await c.env.DB.prepare(`UPDATE jobs SET date = ?, time = ? WHERE id = ?`)
      .bind(v.date, v.start_time || "07:00", v.job_id).run();
    await logActivity(c.env, auth.accountId, auth.userId, "visit_confirmed",
      `Confirmed the visit for "${v.title}": ${when}`);
  } else if (nextStatus === "declined") {
    await logActivity(c.env, auth.accountId, auth.userId, "visit_declined",
      `Can't make the ${who} for "${v.title}" (${when})${note ? `: ${note}` : ""}`);
    // 065. AND THE NEXT DAY GOES FORWARD BY ITSELF, which is the half that
    // makes this "automate the back and forth until it's booked". Bounded, and
    // never allowed to fail the decline: somebody said they cannot make it and
    // that answer has to land whatever happens next.
    await autoRepropose(c, v).catch((err) =>
      console.warn("[auto-turnaround] re-propose failed:", err?.message || err));
  } else {
    // Agreed by one side and still waiting on the other. Said out loud,
    // because "confirmed" on a half-answered window is exactly the lie this
    // change exists to stop.
    await logActivity(c.env, auth.accountId, auth.userId, "visit_part_confirmed",
      `${myLeg === "tenant" ? "The tenant" : myLeg === "contractor" ? "The contractor" : "The hiring side"} agreed ${when} for "${v.title}" `
      + `— still waiting on ${visitWaitingOn(after, parties).join(" and ")}`);
  }
  const row = await c.env.DB.prepare(`SELECT * FROM visits WHERE id = ?`).bind(v.id).first();
  await touchJob(c.env, v.job_id);
  // `turn` as well, because the screen replaces its row with this one and a
  // row with no turn reads as "the tenant's to answer" -- which would put the
  // question straight back in front of a tenant who has just answered it.
  return c.json({ ...visitRowToJs(row), parties,
    waitingOn: visitWaitingOn(visitRowToJs(row), parties),
    turn: nextToAnswer(visitRowToJs(row), parties) });
});

// What happened on the day. A confirmed visit is a promise, and until now
// nothing ever collected on it: the window passed, nobody wrote anything
// down, and the tenant's dashboard went on saying "Somebody is coming" about
// an afternoon two days gone. So once the window has been and gone the person
// who was waiting in gets asked the only question that settles it.
//
// "Nobody came" deliberately does not touch the job. The repair is still
// needed and still open; what is finished is this particular appointment, and
// the manager is the one who arranges the next one. Proposing it supersedes
// this row.
app.post("/api/visits/:id/outcome", async (c) => {
  const auth = c.get("auth");
  if (auth.role !== "tenant") return c.json({ error: "forbidden" }, 403);
  const b = await c.req.json().catch(() => ({}));
  if (typeof b.happened !== "boolean") return c.json({ error: "bad_outcome" }, 400);
  const v = await c.env.DB.prepare(
    `SELECT v.*, j.requested_by, j.title FROM visits v JOIN jobs j ON j.id = v.job_id
      WHERE v.id = ? AND v.account_id = ?`).bind(c.req.param("id"), auth.accountId).first();
  if (!v) return c.json({ error: "not_found" }, 404);
  if (v.requested_by !== auth.userId) return c.json({ error: "forbidden" }, 403);
  // Only a visit that was actually agreed, and only after its day. The client
  // works the window out to the minute in the reader's own timezone; the
  // check here is the coarser one on purpose, because the server has no idea
  // which timezone that is and refusing a real answer is the worse failure.
  if (v.status !== "confirmed") return c.json({ error: "not_open", status: v.status }, 409);
  if (String(v.date) > new Date().toISOString().slice(0, 10)) {
    return c.json({ error: "not_yet", date: v.date }, 409);
  }
  // Somebody has to have been SENT before it makes sense to ask whether
  // they came. A visit and a work order were unconnected facts: a time
  // could be agreed before anybody was hired, and withdrawing the only
  // contractor voided the work order and left the visit standing. The
  // tenant was then asked whether somebody came for a job nobody had been
  // booked for, and a yes to that reads on the manager's side as though
  // the work had been done.
  //
  // The client stops asking the question in that state; this is here
  // because a tab that was open before the contractor was withdrawn would
  // still have the buttons on it, and a safeguard only in the browser is
  // not one.
  const sent = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM work_orders
      WHERE job_id = ? AND voided_at IS NULL AND status != 'declined' LIMIT 1`
  ).bind(v.job_id).first();
  if (!sent) return c.json({ error: "no_contractor" }, 409);
  const note = String(b.note || "").trim().slice(0, 500) || null;
  const status = b.happened ? "happened" : "missed";
  await c.env.DB.prepare(
    `UPDATE visits SET status = ?, tenant_note = ?, responded_at = ? WHERE id = ?`
  ).bind(status, note, new Date().toISOString(), v.id).run();
  const when = visitWhen(v);
  await logActivity(c.env, auth.accountId, auth.userId,
    b.happened ? "visit_happened" : "visit_missed",
    b.happened
      ? `Somebody came for "${v.title}" (${when})${note ? `: ${note}` : ""}`
      : `Nobody came for "${v.title}" (${when})${note ? `: ${note}` : ""}`);
  const row = await c.env.DB.prepare(`SELECT * FROM visits WHERE id = ?`).bind(v.id).first();
  await touchJob(c.env, v.job_id);
  return c.json(visitRowToJs(row));
});

// ---------------------------------------------------------------------------
// A tenant's own report: taken back, or corrected while it is still fresh
// ---------------------------------------------------------------------------

// Whose report, and is it still theirs to change. Owners raise requests the
// same way, so they get the same two things.
// Photos on a report. The numbers are deliberate rather than generous: six
// is more than enough to show one problem from every useful angle, and a
// phone photo is two to four megabytes, so ten leaves room for an
// unprocessed one without leaving room for a video renamed .jpg.
// The sentence a contractor reads, built from what the tenant answered.
// Kept in one function because it is written on create and rewritten on
// every edit, and two copies of this would drift the first time one changed.
// Order matters: it is the order somebody reads it in.
function composeScope(d = {}) {
  return [
    d.unit ? `Unit ${d.unit}.` : null,
    d.problem && d.problem !== d.title ? `Reported as: ${d.problem}.` : null,
    d.started ? `Started: ${String(d.started).toLowerCase()}.` : null,
    String(d.words || "").trim(),
  ].filter(Boolean).join(" ");
}
// What is kept of the tenant's answers, apart from the prose above.
const cleanDetail = (d = {}) => ({
  problem: String(d.problem || "").slice(0, 140) || null,
  started: String(d.started || "").slice(0, 60) || null,
  words: String(d.words || "").slice(0, 4000),
  unit: String(d.unit || "").slice(0, 40) || null,
});

const MAX_REPORT_PHOTOS = 6;
const MAX_PHOTO_BYTES = 10 * 1024 * 1024;
const PHOTO_TYPES = new Set(["image/jpeg", "image/png", "image/webp", "image/heic", "image/heif", "image/gif"]);
// A filename becomes part of an R2 key and comes straight off a phone, so
// it is rewritten rather than trusted: no slashes to climb out of the
// account's prefix, no dot-dot, nothing that is not plainly a name.
const safeFileName = (raw) => {
  let n = raw;
  try { n = decodeURIComponent(raw); } catch { /* already literal */ }
  return (n.replace(/[^\w.\-]+/g, "_").replace(/\.{2,}/g, ".").replace(/^[.\-]+/, "").slice(-80) || "photo.jpg");
};

// What the client sends back after uploading is a claim, not a fact: it says
// which key it wrote and what was in it. The key is checked to be inside
// this account's own prefix -- without that, one account could attach
// another's file by guessing a key and then read it through the route below,
// which serves whatever the row points at.
function cleanPhotos(raw, accountId, existing = []) {
  const out = [];
  for (const p of Array.isArray(raw) ? raw : []) {
    const key = String(p?.key || "");
    if (!key.startsWith(`${accountId}/report-photo/`)) continue;
    if (key.includes("..")) continue;
    if (existing.some((e) => e.key === key) || out.some((e) => e.key === key)) continue;
    const type = String(p?.type || "").toLowerCase();
    out.push({
      id: uid(),
      key,
      name: String(p?.name || "photo").slice(0, 120),
      type: PHOTO_TYPES.has(type) ? type : "image/jpeg",
      size: Number.isFinite(+p?.size) ? Math.max(0, Math.min(MAX_PHOTO_BYTES, +p.size)) : null,
      at: new Date().toISOString(),
    });
    if (existing.length + out.length >= MAX_REPORT_PHOTOS) break;
  }
  return out;
}

// Every route that touches a job's photos needs the same three answers: does
// the job exist on this account, may this caller see it, and what is on it
// now. A tenant or owner only ever reaches their own report; everybody else
// on the account is staff and sees the account's work.
async function jobForPhotos(c, auth, jobId) {
  if (auth.role === "tenant" || auth.role === "owner") return ownReport(c, auth, jobId);
  const job = await c.env.DB.prepare(
    `SELECT * FROM jobs WHERE id = ? AND account_id = ?`).bind(jobId, auth.accountId).first();
  if (!job) return { error: "not_found", status: 404 };
  if (auth.propertyIds && !maySeeProperty(auth, job.property_id)) return { error: "forbidden", status: 403 };
  return { job };
}

async function ownReport(c, auth, jobId) {
  if (auth.role !== "tenant" && auth.role !== "owner") return { error: "forbidden", status: 403 };
  const job = await c.env.DB.prepare(
    `SELECT * FROM jobs WHERE id = ? AND account_id = ?`).bind(jobId, auth.accountId).first();
  if (!job) return { error: "not_found", status: 404 };
  if (job.requested_by !== auth.userId) return { error: "forbidden", status: 403 };
  return { job };
}

// It fixed itself, or it was never really a problem. Anything live on it
// comes down: the work orders are voided so nobody turns up, the open visit
// is superseded so nobody is asked to confirm it.
app.post("/api/jobs/:id/withdraw", async (c) => {
  const auth = c.get("auth");
  const id = c.req.param("id");
  const { job, error, status } = await ownReport(c, auth, id);
  if (error) return c.json({ error }, status);
  if (job.status === "completed") return c.json({ error: "already_completed" }, 409);
  if (job.withdrawn_at) return c.json({ ok: true, alreadyWithdrawn: true });
  // Once a contractor is on it, taking it back is not the tenant's call any
  // more. Somebody has been booked, may have turned work away for the slot,
  // and may already be on the way. The tenant asks the manager, who can
  // still void the work order -- this refuses the silent version of that,
  // where the contractor finds out by arriving.
  //
  // Checked here and not only in the browser: the route is reachable with a
  // job id and nothing else.
  const live = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM work_orders
      WHERE job_id = ? AND voided_at IS NULL AND status != 'declined'`).bind(id).first();
  if ((live?.n || 0) > 0 && auth.role === "tenant") {
    return c.json({ error: "contractor_assigned" }, 409);
  }
  const b = await c.req.json().catch(() => ({}));
  const note = String(b.note || "").trim().slice(0, 500) || null;
  try {
    await c.env.DB.prepare(`UPDATE jobs SET withdrawn_at = ?, withdrawn_note = ? WHERE id = ?`)
      .bind(new Date().toISOString(), note, id).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  const voided = await c.env.DB.prepare(
    `UPDATE work_orders SET voided_at = CURRENT_TIMESTAMP WHERE job_id = ? AND voided_at IS NULL`).bind(id).run();
  try {
    await c.env.DB.prepare(`UPDATE visits SET status = 'superseded' WHERE job_id = ? AND status IN ('proposed', 'declined')`).bind(id).run();
  } catch { /* no visits table yet is not a reason to refuse the withdrawal */ }
  await touchJob(c.env, id);
  await logEvent(c.env, auth.accountId, auth.userId, "job.withdrawn", id, { title: job.title, note });
  await logActivity(c.env, auth.accountId, auth.userId, "job_withdrawn",
    `Withdrew the report "${job.title}"${note ? `: ${note}` : ""}${voided?.meta?.changes ? ` (${voided.meta.changes} work order${voided.meta.changes === 1 ? "" : "s"} voided)` : ""}`);
  return c.json({ ok: true, voided: voided?.meta?.changes ?? 0 });
});

// ---- Photos on a report --------------------------------------------------
//
// The file itself goes to R2 through /api/uploads/report-photo/... first;
// this attaches what came back to the report. Two steps rather than one
// multipart POST because the Worker is already the data path for the upload
// and streaming a file straight into R2 costs it nothing to hold.
app.post("/api/jobs/:id/photos", async (c) => {
  const auth = c.get("auth");
  const id = c.req.param("id");
  const { job, error, status } = await jobForPhotos(c, auth, id);
  if (error) return c.json({ error }, status);
  if (job.withdrawn_at || job.declined_at || job.status === "completed") {
    return c.json({ error: "closed" }, 409);
  }
  let existing;
  try { existing = parseJson(job.photos, []); }
  catch { existing = []; }
  if (existing.length >= MAX_REPORT_PHOTOS) return c.json({ error: "too_many", max: MAX_REPORT_PHOTOS }, 409);
  const b = await c.req.json().catch(() => ({}));
  const added = cleanPhotos(b.photos, auth.accountId, existing);
  if (!added.length) return c.json({ error: "nothing_to_add" }, 400);
  const next = [...existing, ...added];
  try {
    await c.env.DB.prepare(`UPDATE jobs SET photos = ? WHERE id = ?`).bind(JSON.stringify(next), id).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  await touchJob(c.env, id);
  await logActivity(c.env, auth.accountId, auth.userId, "job_photos",
    `Added ${added.length} photo${added.length === 1 ? "" : "s"} to "${job.title}"`);
  return c.json({ ok: true, photos: next.map((x) => ({ id: x.id, name: x.name, type: x.type, size: x.size, at: x.at })) });
});

// Taking one off does not delete the object in R2. A withdrawn photo is
// still evidence of what was reported, and an accidental removal a minute
// after uploading is the likelier event by far. Nothing points at it any
// more, which is what the tenant asked for.
app.delete("/api/jobs/:id/photos/:photoId", async (c) => {
  const auth = c.get("auth");
  const id = c.req.param("id");
  const { job, error, status } = await jobForPhotos(c, auth, id);
  if (error) return c.json({ error }, status);
  const existing = parseJson(job.photos, []);
  const next = existing.filter((p) => p.id !== c.req.param("photoId"));
  if (next.length === existing.length) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`UPDATE jobs SET photos = ? WHERE id = ?`)
    .bind(next.length ? JSON.stringify(next) : null, id).run();
  return c.json({ ok: true, photos: next.map((x) => ({ id: x.id, name: x.name, type: x.type, size: x.size, at: x.at })) });
});

// Serving one back. The caller names a job and a photo on it, never a key:
// the key is read from the row after the same permission check every other
// route on that job makes. An <img src> cannot carry an Authorization
// header, so the browser fetches this like any other call and renders the
// blob -- which keeps one way in rather than inventing a second, weaker one
// on a query string.
app.get("/api/jobs/:id/photos/:photoId", async (c) => {
  const auth = c.get("auth");
  const id = c.req.param("id");
  const { job, error, status } = await jobForPhotos(c, auth, id);
  if (error) return c.json({ error }, status);
  const photo = parseJson(job.photos, []).find((p) => p.id === c.req.param("photoId"));
  if (!photo) return c.notFound();
  const obj = await c.env.FILES.get(photo.key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": photo.type || "image/jpeg",
      // The key carries a uid, so a given photo id never changes content.
      "Cache-Control": "private, max-age=3600",
      "Content-Disposition": `inline; filename="${photo.name.replace(/[^\w.\- ]/g, "_")}"`,
    },
  });
});

// Ten minutes to fix a typo or add the thing you forgot, and only until the
// manager has acted on it -- once approved, it is being worked from, and a
// change underneath that is a new report.
const REPORT_EDIT_WINDOW_MS = 10 * 60 * 1000;
app.patch("/api/jobs/:id/report", async (c) => {
  const auth = c.get("auth");
  const id = c.req.param("id");
  const { job, error, status } = await ownReport(c, auth, id);
  if (error) return c.json({ error }, status);
  if (job.withdrawn_at) return c.json({ error: "withdrawn" }, 409);
  if (job.approved_at || job.status === "completed") return c.json({ error: "already_actioned" }, 409);
  // SQLite's CURRENT_TIMESTAMP is UTC without a zone marker.
  const created = new Date(String(job.created_at).replace(" ", "T") + (String(job.created_at).endsWith("Z") ? "" : "Z"));
  if (Date.now() - created.getTime() > REPORT_EDIT_WINDOW_MS) return c.json({ error: "edit_window_closed" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const sets = [], vals = [];
  if (b.title !== undefined) {
    const title = String(b.title || "").trim().slice(0, 140);
    if (!title) return c.json({ error: "title_required" }, 400);
    sets.push("title = ?"); vals.push(title);
  }
  // The tenant's own answers. Sending these rewrites the scope sentence from
  // them, so the prose a contractor reads and the parts the tenant sees can
  // never drift apart -- which they would if the browser sent both.
  if (b.reportDetail !== undefined) {
    const was = parseJson(job.report_detail, {}) || {};
    const detail = cleanDetail({ ...was, ...b.reportDetail });
    const title = b.title !== undefined ? String(b.title || "").trim() : job.title;
    sets.push("report_detail = ?"); vals.push(JSON.stringify(detail));
    sets.push("scope = ?"); vals.push(composeScope({ ...detail, title }) || null);
  } else if (b.scope !== undefined) {
    sets.push("scope = ?"); vals.push(String(b.scope || "").trim().slice(0, 4000) || null);
  }
  if (Array.isArray(b.trades)) {
    const trades = b.trades.filter((t) => TRADE_IDS.has(t));
    sets.push("trades = ?"); vals.push(JSON.stringify(trades));
  }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);
  vals.push(id);
  try {
    await c.env.DB.prepare(`UPDATE jobs SET ${sets.join(", ")} WHERE id = ?`).bind(...vals).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  await touchJob(c.env, id);
  await logActivity(c.env, auth.accountId, auth.userId, "job_edited", `Corrected the report "${b.title || job.title}"`);
  const row = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ?`).bind(id).first();
  return c.json(jobRowToJs(row, []));
});

// 066. WHAT ENDING THIS JOB WOULD COST, asked BEFORE the modal opens.
//
// The same shape and the same reason as `/api/subs/:companyId/end-check`,
// which this file already records: *the consequence can name what is booked
// and how many people lose access; opening the modal first and filling it in
// afterwards puts the question in front of somebody above an empty space, and
// they answer it before it is finished.*
//
// The browser cannot derive the money. What is funded sits on `wo_funding`
// per work order and the jobs list deliberately does not carry it -- a figure
// on every job row would have to be redacted for owners and tenants, and the
// server is the side that knows it authoritatively anyway.
//
// A COURTESY, not a gate. Every answer here is advisory: the route refuses
// what it refuses whatever this said, and the screen is written to ask anyway
// if this call fails. A pre-flight that could stop somebody tidying up their
// own job list would be worse than no pre-flight.
app.get("/api/jobs/:id/end-check", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const id = c.req.param("id");
  if (!maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT id, trades, status, withdrawn_at, declined_at, requested_by, approved_at
       FROM jobs WHERE id = ? AND account_id = ?`).bind(id, accountId).first());
  if (!job) return c.json({ error: "job_not_found" }, 404);

  // WHO WOULD BE STOOD DOWN. Pending as well as accepted: an offer somebody
  // is about to take, voided silently, is an afternoon they spent pricing
  // work that was already off.
  const { results: wos } = await c.env.DB.prepare(
    `SELECT trade, status, auto_scheduled FROM work_orders
      WHERE job_id = ? AND voided_at IS NULL AND status != 'declined'`).bind(id).all();
  const booked = [...new Set((wos || []).map((w) => w.trade))];
  const accepted = [...new Set((wos || [])
    .filter((w) => w.status === "accepted" || w.auto_scheduled).map((w) => w.trade))];

  const count = async (sql, ...binds) => {
    try { return Number((await c.env.DB.prepare(sql).bind(...binds).first())?.n || 0); }
    catch (err) { if (!missingSchema(err)) throw err; return 0; }
  };
  const openQuotes = await count(
    `SELECT COUNT(*) AS n FROM quote_requests WHERE job_id = ? AND status = 'open'`, id);
  const openOverflow = await count(
    `SELECT COUNT(*) AS n FROM overflow_posts WHERE job_id = ? AND status = 'open'`, id);
  const hasVisit = (await count(
    `SELECT COUNT(*) AS n FROM visits WHERE job_id = ?
      AND status IN ('proposed','confirmed')`, id)) > 0;
  const fundedCents = await count(
    `SELECT COALESCE(SUM(f.amount_cents), 0) AS n FROM wo_funding f
       JOIN work_orders w ON w.id = f.work_order_id
      WHERE w.job_id = ? AND f.status = 'funded'`, id);
  const refundedCents = await count(
    `SELECT COALESCE(SUM(f.refunded_cents), 0) AS n FROM wo_funding f
       JOIN work_orders w ON w.id = f.work_order_id
      WHERE w.job_id = ?`, id);
  const net = Math.max(0, fundedCents - refundedCents);

  return c.json({
    booked, accepted, openQuotes, openOverflow, hasVisit, fundedCents: net,
    // What each kind would be refused for, worked out by the one rule the
    // route reads -- so the modal can grey an option with the reason beside
    // it rather than offering a press that answers 409.
    blocked: Object.fromEntries(CHOOSABLE_ENDINGS.map((k) =>
      [k, whyNotEnd(job, k, { fundedCents: net, today: dayKeyUtc() })])),
    onHold: jobHold(job, dayKeyUtc()).held,
  });
});

// 066. CANCEL, DEFER, OR CLOSE IT OUT WITH NOTHING DONE.
//
// Asked for as *"a job should be able to be cancelled or deferred if needed
// for some reason... maybe we have something 'complete, no work done'"*.
//
// ONE ROUTE FOR THE THREE, because they share everything that matters: the
// same approval check, the same money boundary, the same standing-down of
// whoever was booked, the same append-only row. Three routes would be three
// places for the void to be forgotten, and the one that forgot it would be a
// contractor turning up to work nobody is expecting.
//
// `whyNotEnd` is the rule, shared with the screen so neither can offer what
// the other refuses -- and the screen is NOT allowed to be the only gate: a
// job id and a word is all this takes, which is the gate-lives-in-the-browser
// lie this file refuses everywhere.
app.post("/api/jobs/:id/end", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  // Before anything is read, let alone written: 053's job scope, which the
  // middleware also applies -- this is the belt to its braces and costs a
  // function call.
  if (!maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  const b = await c.req.json().catch(() => ({}));
  const kind = String(b.kind || "").trim();
  if (!isEndingKind(kind) || kind === "resumed") return c.json({ error: "bad_kind" }, 400);

  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT id, title, requested_by, approved_at, status, withdrawn_at, declined_at
       FROM jobs WHERE id = ? AND account_id = ?`).bind(id, accountId).first());
  if (!job) return c.json({ error: "job_not_found" }, 404);

  // MONEY IS THE HARD BOUNDARY AND IT IS NOT OVERRIDABLE. Once a funding has
  // landed there is real money in a balance with this job's name on it, and a
  // route that cancelled around it would leave the only record of that money
  // saying the work was called off.
  //
  // READ FOR EVERY KIND, and `whyNotEnd` is the only thing that decides what
  // to do with it -- a hold is exempt because putting work off spends nothing
  // and the funding is still there when it comes back. The first version
  // skipped the query for a deferral, which is the same answer by a second
  // route: two guards covering for each other, so a mutation to the rule
  // changed no outcome here and the suite's own money assertion could not see
  // it. One query is cheaper than that.
  let fundedCents = 0;
  try {
    const f = await c.env.DB.prepare(
      `SELECT COALESCE(SUM(f.amount_cents), 0) AS n FROM wo_funding f
         JOIN work_orders w ON w.id = f.work_order_id
        WHERE w.job_id = ? AND f.status = 'funded'`).bind(id).first();
    fundedCents = Number(f?.n || 0);
  } catch (err) { if (!missingSchema(err)) throw err; }

  const why = whyNotEnd(job, kind, { fundedCents, today: dayKeyUtc() });
  if (why) return c.json({ error: why, fundedCents }, why === "bad_kind" ? 400 : 409);

  // THE REASON IS REQUIRED ON THE TWO TERMINAL ONES. *"An inaccurate
  // assessment of what the issue was"* is exactly the thing somebody reads
  // back in six months, and a cancellation with no words on it is
  // indistinguishable from a mis-press. A hold usually has the date as its
  // whole story, so there it is optional.
  const note = String(b.note || "").trim().slice(0, 500) || null;
  if (ENDING_KINDS[kind].needsNote && !note) return c.json({ error: "reason_required" }, 400);
  // The day it comes back, deferrals only. NULL is an indefinite hold, which
  // only a resume ends.
  const until = kind === "deferred" && b.until
    ? String(b.until).trim() : null;
  if (until && !DATE_RE.test(until)) return c.json({ error: "bad_date" }, 400);
  // A date already gone is a hold that is over before it starts, which reads
  // on screen as nothing having happened.
  if (until && until < dayKeyUtc()) return c.json({ error: "until_in_the_past" }, 400);

  const now = new Date().toISOString();
  try {
    await c.env.DB.prepare(
      `INSERT INTO job_endings (id, job_id, account_id, kind, note, until, at, by_user_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(uid(), id, accountId, kind, note, until, now, userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }

  // NOBODY IS LEFT BOOKED FOR WORK THAT IS NOT HAPPENING, and that is true of
  // a hold as much as a cancellation: a crew expecting Tuesday is a crew that
  // turns up. The work orders are VOIDED rather than deleted -- the question
  // afterwards is what was issued and what happened to it -- and the open
  // window is superseded, the same pair `withdraw` has done since 020.
  //
  // `no_work` voids too. The job is finished with; an un-voided order against
  // it is a contractor who has not been told.
  const voided = await c.env.DB.prepare(
    `UPDATE work_orders SET voided_at = CURRENT_TIMESTAMP
      WHERE job_id = ? AND voided_at IS NULL`).bind(id).run();
  try {
    await c.env.DB.prepare(
      `UPDATE visits SET status = 'superseded'
        WHERE job_id = ? AND status IN ('proposed', 'confirmed')`).bind(id).run();
  } catch { /* no visits table yet is not a reason to refuse the ending */ }
  // Quote requests go too: three companies pricing work that is cancelled is
  // an afternoon each, and the whole reason the commit gate refuses a closed
  // job is that it costs somebody else their time.
  try {
    await c.env.DB.prepare(
      `UPDATE quote_requests SET status = 'cancelled', closed_at = CURRENT_TIMESTAMP
        WHERE job_id = ? AND status = 'open'`).bind(id).run();
  } catch { /* 043 not applied */ }

  // `no_work` IS A COMPLETION. The row says why; `status` is what every
  // existing reader -- the phase filter, the roster, the ledger -- already
  // answers correctly for, and a fourth status word would mean a full rebuild
  // of a table with a CHECK on it for nothing.
  if (kind === "no_work") {
    await c.env.DB.prepare(
      `UPDATE jobs SET status = 'completed', completed_at = ? WHERE id = ? AND account_id = ?`
    ).bind(new Date().toISOString().slice(0, 10), id, accountId).run();
  }

  await touchJob(c.env, id);
  await logEvent(c.env, accountId, userId, `job.${kind}`, id,
    { title: job.title, note, until, voided: voided?.meta?.changes ?? 0 });
  await logActivity(c.env, accountId, userId, `job_${kind}`,
    `${ENDING_KINDS[kind].short} "${job.title}"${until ? ` until ${until}` : ""}${note ? `: ${note}` : ""}`
      + `${voided?.meta?.changes ? ` (${voided.meta.changes} work order${voided.meta.changes === 1 ? "" : "s"} voided)` : ""}`);
  // Whoever asked for it is told, because a tenant watching a repair they
  // reported is the one person who finds out otherwise by it never happening.
  //
  // THE KIND AS IT IS, not flattened to "cancelled": somebody who read the
  // problem and decided nothing needed doing is saying a different thing from
  // somebody calling the work off, and a tenant told the wrong one of those
  // rings up. The date rides along on a hold, so the message can name it.
  await notifyTenant(c, id, kind, kind === "deferred" ? (until ? `back on ${until}` : "") : note);
  return c.json({ ok: true, kind, until, voided: voided?.meta?.changes ?? 0 });
});

// AND TAKING A HOLD OFF, which is what makes a deferral a hold rather than a
// delete wearing a softer word.
//
// A `resumed` ROW rather than deleting the one that put it on hold: *we put
// this off in January and picked it up in March* is two facts, and the first
// is the one anybody asks about later. Same reason the invite list revokes
// rather than deletes.
//
// It does NOT re-issue the work orders it voided. Those were a price and a
// date somebody agreed to for a day that has gone; re-issuing silently would
// commit a contractor to work they have not been asked about again, which is
// the rule `autoschedule.js` states at length about whose calendar may be
// written to.
app.post("/api/jobs/:id/resume", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  if (!maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT id, title, status, withdrawn_at, declined_at
       FROM jobs WHERE id = ? AND account_id = ?`).bind(id, accountId).first());
  if (!job) return c.json({ error: "job_not_found" }, 404);
  const why = whyNotResume(job, { today: dayKeyUtc() });
  if (why) return c.json({ error: why }, 409);
  const note = String((await c.req.json().catch(() => ({})))?.note || "").trim().slice(0, 500) || null;
  try {
    await c.env.DB.prepare(
      `INSERT INTO job_endings (id, job_id, account_id, kind, note, until, at, by_user_id)
       VALUES (?, ?, ?, 'resumed', ?, NULL, ?, ?)`
    ).bind(uid(), id, accountId, note, new Date().toISOString(), userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
  await touchJob(c.env, id);
  await logEvent(c.env, accountId, userId, "job.resumed", id, { title: job.title, note });
  await logActivity(c.env, accountId, userId, "job_resumed",
    `Took "${job.title}" off hold${note ? `: ${note}` : ""}`);
  return c.json({ ok: true });
});

app.post("/api/jobs/:id/reopen", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  await c.env.DB.prepare(
    `UPDATE jobs SET status = 'active', completed_at = NULL WHERE id = ? AND account_id = ?`
  ).bind(c.req.param("id"), accountId).run();
  await touchJob(c.env, c.req.param("id"));
  return c.json({ ok: true });
});

// Everything about a job that ISN'T a work order — notes, measurement docs.
// EDITING A JOB THAT ALREADY EXISTS.
//
// Asked for as *"when you click on a job card it should open to edit, so the
// entire job can be edited and saved"*. This route took four fields -- notes,
// measurement docs, the property and 060's access answer -- so everything
// somebody typed on the create form was typed once and frozen: a job name with
// a street spelt wrong, a square footage, a trade nobody needed, the materials
// line. The only way to correct any of it was to close the job out and raise
// another one, which loses the work orders, the visit and the history. The
// fourteenth no-way-in in this file, and the one on the object this product is
// about.
//
// Only the keys sent are written, which is the shape that once deleted a W-9
// through `SubForm`: a form that edits part of a record must not replace the
// whole of it.
app.patch("/api/jobs/:id", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  // 053's job scope, BEFORE anything is written. A scoped project manager must
  // not be able to edit a job outside their list, and checking afterwards
  // would answer 404 to a write that had already happened.
  if (!maySeeJob(c.get("auth"), id)) return c.json({ error: "job_not_found" }, 404);
  const b = await c.req.json();
  // WHAT IT SAYS NOW, because a reschedule is a CHANGE and this route cannot
  // tell one from a save that happened to resend the same date. Read through
  // the same cascade the propose route uses, newest column first: a database
  // behind the code loses the ability to work out who has to agree, which
  // costs the ask -- it must not cost the edit.
  const before = await (async () => {
    for (const cols of ["access, access_user_id", "access", ""]) {
      try {
        return await c.env.DB.prepare(
          `SELECT id, account_id, date, time, requested_by${cols ? ", " + cols : ""}
             FROM jobs WHERE id = ? AND account_id = ?`
        ).bind(id, accountId).first();
      } catch (err) { if (!missingSchema(err)) throw err; }
    }
    return null;
  })();
  const sets = [], vals = [];
  if (b.notes !== undefined) { sets.push("notes = ?"); vals.push(b.notes); }
  if (b.measurementDocs !== undefined) { sets.push("measurement_docs = ?"); vals.push(JSON.stringify(b.measurementDocs)); }
  // THE PLAIN TEXT OF THE JOB. Trimmed, and an emptied optional field is
  // stored NULL rather than "": a column holding an empty string where it
  // means "not given" is a lie a screen reads back, which is the same reason
  // the Zapier app leaves `cleanInputData` at its default.
  const TEXT = { title: "title", client: "client", address: "address", area: "area",
    zip: "zip", scope: "scope", materialsPaidBy: "materials_paid_by" };
  for (const [k, col] of Object.entries(TEXT)) {
    if (b[k] === undefined) continue;
    const v = String(b[k] ?? "").trim();
    // A job with no name is a row nobody can find again, and `title` is NOT
    // NULL. Refused rather than silently kept, because a save that reports
    // success and writes nothing is how somebody re-types the same
    // correction three times.
    if (k === "title" && !v) return c.json({ error: "title_required" }, 400);
    sets.push(`${col} = ?`); vals.push(v || null);
  }
  for (const k of ["sqft", "stories"]) {
    if (b[k] === undefined) continue;
    const n = Number(String(b[k] ?? "").replace(/[^0-9]/g, ""));
    sets.push(`${k} = ?`); vals.push(Number.isFinite(n) && n > 0 ? n : null);
  }
  // THE DATE AND TIME SOMEBODY ASKED FOR. Validated in the shapes the visit
  // routes validate, so one screen cannot store a date the other refuses.
  //
  // AND MOVING IT IS A RESCHEDULE, which is the correction this route needed.
  // It wrote these two columns and stopped -- so a manager who opened a job
  // and changed its date moved the target and told NOBODY, and the crew's own
  // card went on reading "Target date. No visit time has been agreed" over a
  // date that had already moved. Reported with a screenshot of exactly that,
  // and the form used to carry a sentence explaining the behaviour, which
  // described the bug accurately rather than excusing it.
  //
  // Nobody edits the date on a job a crew has accepted "just as a target".
  // See after the UPDATE for what is actually done about it.
  if (b.date !== undefined) {
    const d = String(b.date || "").trim();
    if (d && !DATE_RE.test(d)) return c.json({ error: "bad_date" }, 400);
    sets.push("date = ?"); vals.push(d || null);
  }
  if (b.time !== undefined) {
    const t = String(b.time || "").trim();
    if (t && !TIME_RE.test(t)) return c.json({ error: "bad_time" }, 400);
    sets.push("time = ?"); vals.push(t || null);
  }
  // THE MATERIALS LINE IS COMPOSED HERE AND NEVER TAKEN FROM THE REQUEST, the
  // same rule the create route states: what a contractor reads on a work order
  // should be something the shared supplier list produced.
  if (b.materialSupplier !== undefined || b.materialSource !== undefined) {
    const supplier = isSupplier(b.materialSupplier) ? b.materialSupplier : null;
    const branch = supplier && supplier !== OTHER
      ? (String(b.materialBranch || "").trim() || null) : null;
    const line = (supplier
      ? materialLine({ supplier, branch, other: b.materialOther })
      : String(b.materialSource || "").trim()) || null;
    sets.push("material_source = ?", "material_supplier = ?", "material_branch = ?");
    vals.push(line, supplier, branch);
  }
  // WHICH TRADES, AND A TRADE SOMEBODY IS ALREADY BOOKED FOR CANNOT BE TAKEN
  // OFF. Each trade is a slot and a slot can hold a live work order -- a
  // price, a date and a company that has accepted it -- so dropping the trade
  // would leave that work order pointing at a slot the job no longer has:
  // invisible on every screen, and a contractor who still turns up. Refused by
  // name so the form can say which, rather than quietly keeping it, which is
  // the save-that-writes-nothing shape.
  let droppedTrades = [];
  if (b.trades !== undefined) {
    const want = (Array.isArray(b.trades) ? b.trades : []).filter((t) => TRADE_IDS.has(t));
    if (!want.length) return c.json({ error: "trades_required" }, 400);
    const { results: live } = await c.env.DB.prepare(
      `SELECT DISTINCT w.trade FROM work_orders w JOIN jobs j ON j.id = w.job_id
        WHERE w.job_id = ? AND j.account_id = ? AND w.voided_at IS NULL`
    ).bind(id, accountId).all();
    const kept = new Set(want);
    const booked = (live || []).map((r) => r.trade).filter((t) => !kept.has(t));
    if (booked.length) return c.json({ error: "trade_has_work_order", trades: booked }, 409);
    sets.push("trades = ?"); vals.push(JSON.stringify([...new Set(want)]));
    // What is being taken OFF, read before the write so the questions still
    // out about it can be closed once the write lands.
    const prior = await c.env.DB.prepare(
      `SELECT trades FROM jobs WHERE id = ? AND account_id = ?`).bind(id, accountId).first();
    droppedTrades = parseJson(prior?.trades, []).filter((t) => !kept.has(t));
  }
  if (b.propertyId !== undefined) {
    const pid = b.propertyId || null;
    if (pid) {
      const owned = await c.env.DB.prepare(
        `SELECT id FROM properties WHERE id = ? AND account_id = ?`).bind(pid, accountId).first();
      if (!owned) return c.json({ error: "property_not_found" }, 404);
    }
    sets.push("property_id = ?"); vals.push(pid);
  }
  // 060. Changing it AFTER the job exists is most of the point: what a repair
  // turns out to need is often only clear once somebody has looked at it, and
  // "sometimes you need to be there" is a judgement made at scheduling time
  // rather than at creation. Refused rather than defaulted on a word nothing
  // recognises -- silence is only safe when nothing was asked.
  if (b.access !== undefined) {
    if (b.access !== null && !isAccess(b.access)) return c.json({ error: "bad_access" }, 400);
    sets.push("access = ?"); vals.push(b.access || null);
  }
  if (!sets.length) return c.json({ ok: true });
  // AND THE JOB FLOATS, because somebody just worked on it. 025 added this
  // column so a job being worked on rises to the top of the list, and a route
  // that changes the job and not the column leaves the edit somewhere nobody
  // scrolls to.
  sets.push("updated_at = ?"); vals.push(new Date().toISOString());
  vals.push(id, accountId);
  const res = await c.env.DB.prepare(
    `UPDATE jobs SET ${sets.join(", ")} WHERE id = ? AND account_id = ?`).bind(...vals).run();
  // A job id that is not this account's wrote nothing, and answering ok to
  // that is a save that reports success. `maySeeJob` as well, so a scoped
  // project manager cannot edit a job outside their list.
  if (!res.meta?.changes) return c.json({ error: "job_not_found" }, 404);
  // A TRADE TAKEN OFF TAKES ITS OPEN QUESTIONS WITH IT. Companies asked to
  // price that trade, or answering an overflow post for it, would otherwise
  // spend an afternoon on work the job no longer has -- the reason ending a
  // job cancels its open quote requests. Only open ones: an awarded request
  // has a work order behind it, and the booked check above already refuses
  // that. Tolerant of a database without 043 or 038, because losing the tidy
  // must not cost the edit.
  if (droppedTrades.length) {
    const marks = droppedTrades.map(() => "?").join(",");
    for (const table of ["quote_requests", "overflow_posts"]) {
      try {
        await c.env.DB.prepare(
          `UPDATE ${table} SET status = 'cancelled', closed_at = CURRENT_TIMESTAMP
            WHERE job_id = ? AND account_id = ? AND status = 'open' AND trade IN (${marks})`
        ).bind(id, accountId, ...droppedTrades).run();
      } catch (e) {
        if (!missingSchema(e)) throw e;
      }
    }
    await logActivity(c.env, accountId, userId, "job_trades_removed",
      `Took ${droppedTrades.map(tradeLabel).join(", ")} off the job`);
  }
  await logActivity(c.env, accountId, userId, "job_edited", "Edited the job details");
  // AND THE PEOPLE WHO HAVE TO BE THERE ARE ASKED AGAIN.
  //
  // THROUGH THE REAL ROUTE, never a second insert beside it, which is the
  // decision 065's auto-scheduler already records: proposing carries the
  // approval check, the parties, the chain's turn order, the supersede and
  // three schema fallbacks, and a copy here would be a second set of rules
  // with the one that drifted being whichever door is used less.
  //
  // ONLY WHEN THERE IS SOMEBODY BUT US TO ASK. `othersMustAgree` is that
  // question: a crew who has accepted, or a tenant who has to be in. With
  // nobody on the job the date is a target and saying so is the honest
  // answer -- proposing one would draw "Confirmed. Agreed by everybody who
  // has to be there" over work nobody is booked for.
  //
  // AND ONLY WHEN IT MOVED. A save that resends the same date is not a
  // reschedule, and asking a crew to re-confirm a day they already agreed to
  // is the round trip this whole chain is ordered to avoid.
  const moved = (b.date !== undefined || b.time !== undefined)
    && String(b.date ?? before?.date ?? "").trim()
    && (String(b.date ?? before?.date ?? "").trim() !== String(before?.date || "")
      || String(b.time ?? before?.time ?? "").trim() !== String(before?.time || ""));
  let rescheduled = null;
  if (moved && before) {
    const parties = await partiesFor(c.env, before);
    if (othersMustAgree(parties)) {
      const date = String(b.date ?? before.date ?? "").trim();
      const start = String(b.time ?? before.time ?? "").trim() || null;
      // The window somebody already agreed to, so its LENGTH survives the
      // move -- a 2h15m slot shifted to the afternoon is still 2h15m. Read
      // off the live visit rather than reinvented, and `windowEnd` is the one
      // rule the propose form uses for the same arithmetic.
      const live = await c.env.DB.prepare(
        `SELECT start_time, end_time FROM visits
          WHERE job_id = ? AND status IN ('proposed','confirmed')
          ORDER BY created_at DESC, rowid DESC LIMIT 1`).bind(id).first().catch(() => null);
      const got = await asSelf(c, `/api/jobs/${id}/visits`, {
        date, startTime: start,
        endTime: start ? windowEnd(start, live?.start_time, live?.end_time) : null,
      });
      // SAID ON THE REPLY RATHER THAN ASSUMED, the rule `engagedAsRecorded`
      // already follows: a screen that cannot tell "nobody needed telling"
      // from "the ask did not go" cannot offer the one of those worth a
      // second press. The edit itself stands either way -- the job really was
      // saved, and refusing it now would be a save that reports failure over
      // a write that happened.
      rescheduled = got.status < 300
        ? { asked: parties.filter((pp) => pp !== "manager"), status: got.body?.visit?.status || null }
        : { error: got.body?.error || "propose_failed" };
    }
  }
  return c.json({ ok: true, rescheduled });
});

// ---------------------------------------------------------------------------
// Work orders — issuing one is atomic and server-side authoritative.
// ---------------------------------------------------------------------------
// A work order number a person can read out on the phone, and one the
// database will accept.
//
// It used to be four random digits. That is 9,000 possibilities against a
// UNIQUE column shared by every account, so it is fine for a demo and a coin
// flip by the time there are a few thousand work orders: around one in nine
// at 1,000 rows, better than even at 4,000. It surfaced here first, on a test
// database that has run up thousands of them, as an unexplained 500 on
// assign -- which is precisely how it would have surfaced for a customer,
// with "couldn't assign" on screen and nothing to act on.
//
// Six digits for headroom, and a retry because headroom is not a guarantee.
async function withWoNumber(run) {
  for (let attempt = 0; ; attempt++) {
    const n = "WO-" + Math.floor(100000 + Math.random() * 900000);
    try {
      await run(n);
      return n;
    } catch (err) {
      const taken = /UNIQUE constraint failed:\s*work_orders\.wo_number/i.test(String(err?.message || err));
      if (!taken || attempt >= 5) throw err;
    }
  }
}

app.post("/api/jobs/:jobId/assign", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const jobId = c.req.param("jobId");
  const { trade, companyId, crewName, tradeScope, value, responseWindow,
    payKind, rate, capHours, autoBook } = await c.req.json();

  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT id, requested_by, approved_at, date, status, withdrawn_at, declined_at
       FROM jobs WHERE id = ? AND account_id = ?`
  ).bind(jobId, accountId).first());
  if (!job || !maySeeJob(c.get("auth"), jobId)) return c.json({ error: "job_not_found" }, 404);
  // A request an owner raised is not work anybody has agreed to yet. Issuing a
  // work order against one would commit the account to a price it never set.
  if (job.requested_by && !job.approved_at) return c.json({ error: "not_approved" }, 409);
  // AND A JOB THAT IS FINISHED WITH IS NOT WORK EITHER. This row did not carry
  // `status` at all until now, so a job closed out last week took a work order
  // exactly as a live one did -- and the card went on offering the button,
  // because the empty slot's action row had no check either. A work order
  // against a closed job is a contractor turning up to work nobody is
  // expecting. The reason is named, so the screen can say which of the three
  // it was rather than "no".
  // 066. AND ON HOLD IS NOT WORK EITHER, which `jobClosure` deliberately does
  // not answer -- a held job keeps its phase and can be resumed. One refusal
  // for both, so a door cannot read one and miss the other.
  {
    const no = jobCommitRefusal(job);
    if (no) return c.json(no, 409);
  }

  // ON THE ROSTER, not merely once engaged. This read had no status check at
  // all, so a contractor who had been removed -- or paused -- was still
  // assignable: the roster hid them and the route issued the work order
  // anyway, which is the gate-lives-in-the-browser lie this file refuses
  // everywhere else. `not_engaged` is the right answer and the existing one:
  // they are not.
  const engagement = await c.env.DB.prepare(
    `SELECT * FROM engagements WHERE account_id = ? AND company_id = ? AND ${onRosterSql()}`
  ).bind(accountId, companyId).first();
  if (!engagement) return c.json({ error: "not_engaged" }, 404);

  // AND ENGAGED FOR THIS KIND OF WORK. A handyman is engaged for small jobs
  // -- a tap washer, a tripped breaker, a bedroom wall -- and `HANDYMAN_TRADES`
  // is the only axis this product has to say so, because every slot on a job
  // is a trade.
  //
  // ON THE SERVER, because the roster could simply not offer them and the
  // route would issue the work order anyway: that is the
  // gate-lives-in-the-browser lie, and here it ends with a maintenance worker
  // sent to a roof. The reason is named so the screen can say which it was.
  if (!mayCover(engagement.engaged_as, trade)) {
    return c.json({ error: "trade_not_handyman", trade }, 409);
  }

  // Documents must be complete before a work order can be issued -- and WHICH
  // documents follows what they are to this account. A handyman is not asked
  // for insurance or a bond, so demanding them here would make the gate
  // unsatisfiable for somebody the account deliberately engaged without them:
  // the permanently-amber failure, wearing its most expensive hat, since it
  // would refuse every work order rather than colouring a row.
  const company = await c.env.DB.prepare(
    `SELECT insurance, bond, contract, w9, doc_files, license FROM companies WHERE id = ?`
  ).bind(companyId).first();
  const docReview = parseJson(engagement.doc_review, {});
  const verified = (k) => docReview[k]?.status === "verified";
  //
  // `ASSIGN_KINDS` rather than a list written out here: the contractor's own
  // banner says what stops them being assigned, and two copies of that answer
  // is how it came to name the W-9, which this route has never checked.
  const mustHave = requiredDocsFor(engagement.engaged_as, ASSIGN_KINDS);
  const short = mustHave.filter((k) => !verified(k));
  if (short.length) {
    // WHICH WAY it is short, because the two need opposite actions and the
    // screen said the wrong one. Nothing uploaded is the contractor's to fix
    // and the hiring account can only ask; uploaded and not yet verified is
    // THIS account's own review sitting undone, which nobody else can clear.
    // Telling somebody to chase a certificate that is already on file is how
    // a work order waits a week on the person who was never the blocker --
    // the expired-versus-never-added distinction, one screen along.
    return c.json({
      error: "documents_incomplete",
      missing: short,
      absent: short.filter((k) => !company?.[k]),
      unreviewed: short.filter((k) => !!company?.[k]),
    }, 409);
  }

  // Verified is not the same as in force. A review is a verdict somebody
  // recorded once; a certificate has a date on it. An approved COI that ran
  // out eight months ago passed every check above, which is precisely the
  // failure this is here to stop -- and the date to ask about is the JOB'S,
  // not today's, because cover that lapses on the Friday does not cover work
  // booked for the Tuesday after.
  //
  // This refuses a NEW assignment. It is not the same as a certificate
  // lapsing under work already booked: stranding scheduled work over
  // paperwork helps nobody, so that case is chased hard by the nightly sweep
  // instead of cancelling anything.
  try {
    const rows = await currentDocRows(c.env.DB, companyId);
    const docs = docShapeWithLegacy(rows, company);
    // Only the kinds that have a shelf life, and only the ones this account
    // requires: a W-9 with no date is not a reason to refuse anything.
    // Narrowed the same way. EXPIRING_KINDS is insurance and a bond, and both
    // come off a handyman -- so without this the lapse check would refuse a
    // work order over a certificate this account never asked them for, which
    // is the same gate one step along.
    const cover = coversJob(docs, job.date || new Date().toISOString().slice(0, 10),
      requiredDocsFor(engagement.engaged_as, EXPIRING_KINDS));
    if (!cover.ok && cover.lapsing.length) {
      return c.json({
        error: "documents_lapse_before_job",
        lapsing: cover.lapsing,
        jobDate: job.date || null,
        detail: cover.lapsing.map((k) => {
          const until = docs[k]?.expiresOn;
          const name = { insurance: "Insurance", bond: "Bond" }[k] || k;
          return `${name} expires ${until}, before this job on ${job.date}.`;
        }).join(" "),
      }, 409);
    }
  } catch (err) {
    // No 037 means no dates to check, which is the position this account was
    // in before any of this shipped. It must not stop them assigning work.
    if (!missingSchema(err)) throw err;
    console.warn("[assign] expiry check unavailable:", err?.message || err);
  }

  const autoScheduled = !!engagement.auto_schedule;
  const id = uid();
  const cents = (v) => (v || v === 0) && String(v).trim() !== ""
    ? Math.round(Number(String(v).replace(/[^0-9.]/g, "")) * 100) : null;

  // Hourly needs both halves or it is not an offer: a rate with no ceiling
  // is an open cheque, and a ceiling with no rate is nothing. Refused here
  // rather than stored half-formed, because the contractor is about to be
  // sent whatever this says.
  const hourly = payKind === "hourly";
  const rateCents = hourly ? cents(rate) : null;
  const cap = hourly ? Number(capHours) : null;
  if (hourly) {
    if (!rateCents || rateCents <= 0) return c.json({ error: "rate_required" }, 400);
    if (!Number.isFinite(cap) || cap <= 0) return c.json({ error: "cap_required" }, 400);
  }
  // value_cents goes on meaning the most this can cost, whichever way it is
  // priced, so every total and spend figure written against it still adds up.
  const valueCents = hourly ? Math.round(rateCents * cap) : cents(value);
  const respondBy = autoScheduled ? null
    : new Date(Date.now() + windowMins(responseWindow) * 60000).toISOString();

  // Three of these columns arrive with migration 024. Without it this INSERT
  // threw an unhandled error, which reached the browser as a plain 500 and
  // read on screen as the assignment simply not working -- with nothing to
  // say why. Name the file instead: it is the one thing that turns this into
  // a two-minute fix.
  let woNumber;
  try {
    woNumber = await withWoNumber((n) => c.env.DB.prepare(
      `INSERT INTO work_orders
        (id, wo_number, job_id, trade, company_id, engagement_id, crew_name, trade_scope, value_cents,
         status, auto_scheduled, response_window, respond_by, pay_kind, rate_cents, cap_hours)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, n, jobId, trade, companyId, engagement.id, crewName || null, tradeScope || "",
      valueCents, autoScheduled ? "accepted" : "pending", autoScheduled ? 1 : 0,
      autoScheduled ? null : (responseWindow || "24h"), respondBy,
      hourly ? "hourly" : "fixed", rateCents, cap).run());
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    console.error("[assign] schema not migrated:", err?.message || err);
    return c.json({ error: "migration_needed", migration }, 503);
  }

  // THE HANDYMAN CEILING, RECORDED RATHER THAN ENFORCED.
  //
  // `engaged_as = 'handyman'` says this company works without a contractor
  // licence, and every state's exemption for that is a dollar figure. The
  // figures are in `shared/handycap.js` with the whole argument for why this
  // WARNS and never refuses: they are secondary-source numbers, thirteen of the
  // fifty-one are explicitly unconfirmed, and a figure nobody has checked must
  // not be the thing that stops a work order.
  //
  // So the screen is where it is said -- before the press, where it can still
  // change the number -- and this is the trail: *they were told and issued it
  // anyway* has to survive, because a warning on a screen is not a record. It
  // runs AFTER the insert so the row just written is in the sums.
  let capWarning = null;
  if (isHandyman(engagement.engaged_as)) {
    try {
      // WHERE THE WORK IS, not where the contractor is registered. Licensing
      // follows the property, the same rule `lien_waivers.governing_state`
      // already keeps -- and the company's own state is the fallback, because
      // a job at no building is the one case nothing else can answer.
      const where = await c.env.DB.prepare(
        `SELECT COALESCE(NULLIF(p.state, ''), NULLIF(co.state, '')) AS state
           FROM jobs j
           LEFT JOIN properties p ON p.id = j.property_id
           LEFT JOIN companies co ON co.id = ?
          WHERE j.id = ?`
      ).bind(companyId, jobId).first();
      // EVERYTHING THIS COMPANY HOLDS ON THIS JOB, not the one work order just
      // issued, because the dataset's own rule is that splitting a project
      // across invoices to stay under a cap is prohibited -- and a
      // per-work-order comparison is a screen that teaches people to do it.
      //
      // A deny list on the status, for the reason `onRoster` is one: a
      // declined or voided work order is money nobody owes, and anything else
      // -- including a spelling this code has not heard of -- counts, because
      // under-counting here is the direction that fails to warn.
      const sums = await c.env.DB.prepare(
        `SELECT
           COALESCE(SUM(CASE WHEN w.job_id = ? THEN w.value_cents ELSE 0 END), 0) AS job_cents,
           COALESCE(SUM(CASE WHEN COALESCE(j.date, substr(w.issued_at, 1, 10)) >= ?
                             THEN w.value_cents ELSE 0 END), 0) AS year_cents,
           GROUP_CONCAT(CASE WHEN w.job_id = ? THEN w.trade END) AS job_trades
           FROM work_orders w JOIN jobs j ON j.id = w.job_id
          WHERE w.company_id = ? AND j.account_id = ?
            AND w.status <> 'declined' AND w.voided_at IS NULL`
      ).bind(jobId, `${new Date().getUTCFullYear()}-01-01`, jobId, companyId, accountId).first();
      const chk = handymanCapCheck({
        engagedAs: engagement.engaged_as,
        state: where?.state || null,
        trades: String(sums?.job_trades || "").split(",").filter(Boolean),
        jobDollars: (sums?.job_cents || 0) / 100,
        accountYearDollars: (sums?.year_cents || 0) / 100,
      });
      if (chk) capWarning = { ...chk, text: handymanCapText(chk) };
    } catch (err) {
      // A figure that could not be worked out must not cost somebody their
      // work order: this whole thing is advisory. Narrow, because a catch wide
      // enough to hide a real error is a catch that will.
      if (!missingSchema(err)) throw err;
      console.warn("[assign] handyman cap check unavailable:", err?.message || err);
    }
  }

  await logEvent(c.env, accountId, userId, "wo.issued", id, {
    jobId, trade, companyId, woNumber,
    // Only the verdict and the figures, never the prose: the words change and
    // the log is read months later.
    handymanCap: capWarning
      ? { state: capWarning.state, basis: capWarning.basis, reason: capWarning.reason,
        level: capWarning.level, capDollars: capWarning.capDollars,
        figureDollars: capWarning.figureDollars, over: capWarning.over }
      : null,
  });

  // Tell them. A work order nobody knows about is why response deadlines get
  // missed. Failure is logged and does not undo the issue.
  //
  // It goes by whichever routes the contractor asked for. A work order is
  // the job itself, not an announcement about it, and a roofer who set
  // "Email + SMS" and got neither has been given a deadline nobody told
  // them about -- which is exactly how a response window expires.
  //
  // And it is REPORTED. This sent an email, wrote the result to email_log
  // and returned nothing, so an address that bounced, a number that could
  // not be texted, or a contractor with no address at all were all
  // indistinguishable on screen from a work order delivered. Whoever
  // pressed Assign is the only person who can fix any of those, and they
  // were the one person not told.
  let notified = { emailed: false, texted: false, emailError: null, textError: null, to: null };
  // 074. Minted here, before anything is sent, so the email, the text and
  // the work order drawn in the app all carry the same link -- and so a row
  // exists for every work order that went out, which is what "sent" counts.
  const claimLink = claimUrl(await ensureClaimLink(c.env, { woId: id, accountId, companyId }));
  {
    const co = await c.env.DB.prepare(
      `SELECT id, company, contact, email, phone, notify FROM companies WHERE id = ?`).bind(companyId).first();
    const prefs = parseJson(co?.notify, null) || {};
    // Neither switched on cannot be a silence: the form that sets these
    // refuses to save with both off, so a row in that state is old data
    // rather than a decision, and email is the safer reading of it.
    const wantEmail = prefs.email !== false || prefs.sms !== true;
    const wantSms = prefs.sms === true;
    const to = co?.email && wantEmail ? co.email : null;
    const sms = co?.phone && wantSms ? co.phone : null;
    notified.to = [to, sms].filter(Boolean).join(" and ") || null;

    if (to || sms) {
      const [account, job] = await Promise.all([
        c.env.DB.prepare(`SELECT id, name, subdomain FROM accounts WHERE id = ?`).bind(accountId).first(),
        c.env.DB.prepare(`SELECT title, address, area, zip, date FROM jobs WHERE id = ?`).bind(jobId).first(),
      ]);
      if (to) {
        const mail = workOrderIssuedEmail({ company: co, contact: co.contact, job, trade,
          woNumber, account, respondBy, claimLink });
        const result = await sendEmail(c.env, { to, subject: mail.subject,
          text: mail.text, html: mail.html });
        await logMail(c.env, { accountId, companyId, to, kind: "wo_issued",
          subject: mail.subject, result, sentBy: userId });
        notified.emailed = !!result?.ok;
        if (!result?.ok) notified.emailError = result?.error || "send_failed";
      }
      if (sms) {
        const result = await sendAccountSms(c.env, { accountId, companyId, to: sms, kind: "wo_issued",
          body: workOrderIssuedSms({ job, trade, woNumber, account, respondBy, claimLink }) });
        notified.texted = !!result?.ok;
        if (!result?.ok) notified.textError = result?.error || "send_failed";
      }
    } else {
      // Nothing to send to at all, which is a fact about the contractor
      // record and fixable in ten seconds by whoever is looking at it.
      notified.emailError = co?.email || co?.phone ? "notify_off" : "no_contact";
    }
  }
  await logActivity(c.env, accountId, userId, "wo_issued",
    `Issued ${woNumber} to ${await companyName(c.env.DB, companyId)} · ${trade}`);
  await touchJob(c.env, jobId);
  await notifyTenant(c, jobId, autoScheduled ? "booked" : "arranging");
  // AUTO-SCHEDULED MEANS A DAY ON THE CALENDAR, not only a yes. `autoBook:
  // false` is the turnaround's own run, which picks the day itself from the
  // ranking and must not be beaten to it by a second, cruder choice.
  const autoBooked = autoScheduled && autoBook !== false
    ? await autoBookOnIssue(c, { jobId, companyId, accountId }) : null;
  const summarised = await summariseForWorkOrder(c, { jobId, accountId, userId });
  return c.json({ id, woNumber, status: autoScheduled ? "accepted" : "pending",
    notified, capWarning, summarised, autoBooked }, 201);
});

// THE SUMMARY THE WORK ORDER CARRIES, WRITTEN WHEN THE WORK ORDER IS ISSUED.
//
// Asked for as *"when an inspection follow up creates a job and the job turns
// into a work order, the summary creation should happen automatically when
// added to the work order with all of the other details"*.
//
// 063 writes it when the JOB is raised, which is the right moment and is not
// the only one: a raise whose call failed, a job raised before 063 shipped, a
// job raised from an unfinished inspection that had nothing to combine yet --
// every one of those reaches a contractor with the rooms and no paragraph, and
// nothing retried. The person who has to read it is the one who cannot ask for
// it, so the gap was permanent from their side.
//
// ISSUING IS A PRESS THE ACCOUNT MAKES, which is what makes this allowed where
// 063 refuses the contractor's first read. That entry's three objections were:
// it spends the account's money on a press they did not make, it fails at the
// moment somebody needs it with nothing to fall back on, and three companies
// on one job pay for three answers. Issuing answers all three -- a person
// pressed Assign, there is a fallback (the rooms, which are the record), and
// it writes only when there is nothing there, so the second and third work
// orders on one job cost nothing.
//
// A STALE ONE IS NEVER REWRITTEN, which is 063's rule kept rather than
// weakened: the notes can move on after a job is raised, and a paragraph
// another company may already be pricing from must not change under them. The
// screen says it is behind and the rooms beneath it are always live. Only an
// ABSENT summary is written here.
//
// IT NEVER BLOCKS THE ISSUE, for the reason the raise does not: by the time
// this runs the work order exists, the contractor has been told, and a 500
// over a paragraph would report failure for a job that is on somebody's
// screen. Said on the reply rather than inferred from a null, so a caller can
// tell "there was nothing to summarise" from "the call failed".
async function summariseForWorkOrder(c, { jobId, accountId, userId }) {
  try {
    const insp = await c.env.DB.prepare(
      `SELECT * FROM inspections WHERE job_id = ? AND account_id = ? LIMIT 1`
    ).bind(jobId, accountId).first();
    if (!insp) return null;
    return await summariseInspection(c, { inspection: insp, accountId, userId });
  } catch (err) {
    // This guards ONE statement -- the lookup above. Everything after it is
    // inside `summariseInspection`, which has its own. Named for the function
    // it is in, because a prefix that belongs to the other one sends whoever
    // is reading the log to the wrong catch, which is how a mutation on this
    // pair quietly changed nothing.
    console.warn("[wo-summary] no inspection read:", err?.message || err);
    return { wrote: false, reason: "failed" };
  }
}

// The write itself, shared by all three doors -- finishing the walk, raising
// the job, issuing the work order -- so there is one rule about when a
// paragraph may be written and when it may not, rather than three that drift.
async function summariseInspection(c, { inspection: insp, accountId, userId }) {
  try {
    if (!insp) return null;
    const had = await inspectionSummaryRow(c.env.DB, insp.id);
    if (had) return { wrote: false, reason: "already" };
    // `drafts: false`, which is not a choice about what the model reads --
    // `summarySource` and `countComments` both go through
    // `contractorInspectionShape`, which drops them either way. It says that
    // this path never reads one: the paragraph it writes is for a contractor,
    // and a sentence nobody kept is the team's working note.
    const rooms = await inspectionRooms(c.env.DB, insp.id, { drafts: false });
    const made = await writeInspectionSummary(c, { accountId, userId }, insp, rooms);
    return made.ok ? { wrote: true } : { wrote: false, reason: made.error || "failed" };
  } catch (err) {
    // Deliberately wide, and for the reason 063 states about the raise: the
    // work order already exists and the contractor has already been told, so
    // a throw here would answer 500 to something that has happened.
    console.warn("[summary] not written:", err?.message || err);
    return { wrote: false, reason: "failed" };
  }
}

// Sending somebody out, without waiting for a manager to wake up.
//
// A burst pipe at two in the morning is the case this exists for: the
// difference between a plumber in an hour and a plumber at nine is a
// ceiling. So an urgent report approves itself and issues a work order to
// the one subcontractor the account has named for this.
//
// Everything about it is deliberately conservative, because it spends
// somebody's money without asking:
//
//   * It only fires when the account has named a contractor. Nothing
//     dispatches itself out of the box.
//   * It only fires for "urgent". A fire is not a subcontractor's problem
//     and never dispatches -- emergency services are not something this
//     system can route to.
//   * The usual document rule still applies. Sending an uninsured
//     contractor into an emergency is how an emergency becomes a lawsuit,
//     so a company whose paperwork is not verified is not dispatched and
//     the manager is told why rather than left to assume somebody is on
//     the way.
//
// Never throws. A report that cannot be dispatched is still a report, and
// losing it because the call-out failed would be the worse outcome by far.
async function dispatchEmergency(c, jobId, accountId) {
  const say = (reason, extra = {}) => ({ dispatched: false, reason, ...extra });
  try {
    const account = await c.env.DB.prepare(
      `SELECT id, name, subdomain, emergency_company_id FROM accounts WHERE id = ?`).bind(accountId).first();
    const companyId = account?.emergency_company_id;
    if (!companyId) return say("no_emergency_contractor");

    const engagement = await c.env.DB.prepare(
      `SELECT * FROM engagements WHERE account_id = ? AND company_id = ?`).bind(accountId, companyId).first();
    if (!engagement || !onRoster(engagement.status)) return say("not_engaged");

    const docReview = parseJson(engagement.doc_review, {});
    const verified = (k) => docReview[k]?.status === "verified";
    if (!verified("insurance") || !verified("bond") || !verified("contract")) {
      return say("documents_incomplete", { companyId });
    }

    const job = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ?`).bind(jobId).first();
    if (!job) return say("job_not_found");

    // Approving is part of dispatching: a work order cannot be issued
    // against a request nobody has agreed to, and for this one the agreeing
    // is what the account did when it named an emergency contractor.
    await c.env.DB.prepare(`UPDATE jobs SET approved_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(jobId).run();

    const trade = parseJson(job.trades, [])[0] || "general";
    const autoScheduled = !!engagement.auto_schedule;
    const id = uid();
    // Two hours, not the usual day. If they cannot take it the manager needs
    // to know while it still matters.
    const respondBy = autoScheduled ? null : new Date(Date.now() + windowMins("2h") * 60000).toISOString();
    const woNumber = await withWoNumber((n) => c.env.DB.prepare(
      `INSERT INTO work_orders
        (id, wo_number, job_id, trade, company_id, engagement_id, crew_name, trade_scope, value_cents,
         status, auto_scheduled, response_window, respond_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, n, jobId, trade, companyId, engagement.id, null, job.scope || "", null,
      autoScheduled ? "accepted" : "pending", autoScheduled ? 1 : 0,
      autoScheduled ? null : "2h", respondBy).run());

    const co = await c.env.DB.prepare(
      `SELECT id, company, contact, email, phone, notify FROM companies WHERE id = ?`).bind(companyId).first();
    const where = [job.address, job.zip].filter(Boolean).join(", ");
    const line = `EMERGENCY call-out from ${account.name}: ${job.title}${where ? ` at ${where}` : ""}. ${woNumber}.`;
    // 074. A call-out is a work order too, and says how it was sent.
    const claimLink = claimUrl(await ensureClaimLink(c.env, { woId: id, accountId, companyId }));
    // Email and text, both, regardless of what they normally chose. Somebody
    // who opted out of texts did so about job offers, not about this.
    if (co?.email) {
      const result = await sendEmail(c.env, { to: co.email,
        subject: `Emergency call-out — ${job.title}`,
        text: `${line}\n\n${job.scope || ""}\n\nThis was sent automatically because ${account.name} named you their emergency contractor. Please respond within two hours.\n\n${footerText(claimLink)}` });
      await logMail(c.env, { accountId, companyId, to: co.email, kind: "emergency_dispatch",
        subject: `Emergency call-out — ${job.title}`, result, sentBy: null });
    }
    if (co?.phone) {
      // Sent whatever the month's count says -- see SMS_UNCAPPED_KINDS -- and
      // now logged, which it never was, so the console's count is true.
      await sendAccountSms(c.env, { accountId, companyId, to: co.phone,
        kind: "emergency_dispatch", body: `${line.slice(0, 220)} ${footerSms(claimLink)}` }).catch(() => {});
    }

    await logEvent(c.env, accountId, null, "wo.emergency_dispatched", id, { jobId, companyId, woNumber });
    await logActivity(c.env, accountId, job.requested_by, "emergency_dispatched",
      `Emergency: ${woNumber} went straight to ${co?.company || "the emergency contractor"} for "${job.title}"`);
    await notifyTenant(c, jobId, autoScheduled ? "booked" : "arranging");
    return { dispatched: true, companyId, woNumber, company: co?.company || null,
      status: autoScheduled ? "accepted" : "pending" };
  } catch (err) {
    // A failed dispatch must never cost the report.
    console.error("[emergency] dispatch failed:", err);
    return say("dispatch_failed");
  }
}

const RESPONSE_WINDOW_MINS = { "2h": 120, "8h": 480, "24h": 1440, "48h": 2880 };
const windowMins = (id) => RESPONSE_WINDOW_MINS[id] ?? 1440;

// Void the live WO for a job+trade and issue a fresh one — this is how
// "editing" a work order actually works; nothing is ever UPDATEd in place.
app.post("/api/work-orders/:id/reissue", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const wo = await c.env.DB.prepare(
    `SELECT wo.*, j.account_id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ?`
  ).bind(id).first();
  if (!wo || wo.account_id !== accountId) return c.json({ error: "not_found" }, 404);

  const b = await c.req.json();
  await c.env.DB.prepare(`UPDATE work_orders SET voided_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(id).run();

  const newId = uid();
  const valueCents = b.value ? Math.round(Number(String(b.value).replace(/[^0-9.]/g, "")) * 100) : wo.value_cents;
  const woNumber = await withWoNumber((n) => c.env.DB.prepare(
    `INSERT INTO work_orders
      (id, wo_number, job_id, trade, company_id, engagement_id, crew_name, trade_scope, value_cents, status, auto_scheduled)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', 0)`
  ).bind(newId, n, wo.job_id, wo.trade, wo.company_id, wo.engagement_id,
    b.crewName ?? wo.crew_name, b.tradeScope ?? wo.trade_scope, valueCents).run());

  // 074. A reissued work order is a new document with a link of its own.
  await ensureClaimLink(c.env, { woId: newId, accountId, companyId: wo.company_id });
  await touchJob(c.env, wo.job_id);
  await logEvent(c.env, accountId, userId, "wo.reissued", newId, { voided: id });
  return c.json({ id: newId, woNumber }, 201);
});

app.post("/api/work-orders/:id/respond", async (c) => {
  const { accountId, userId, role, companyId } = c.get("auth");
  const id = c.req.param("id");
  const { status } = await c.req.json(); // 'accepted' | 'declined'
  if (!["accepted", "declined"].includes(status)) return c.json({ error: "bad_status" }, 400);

  const wo = await c.env.DB.prepare(
    `SELECT wo.*, j.account_id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ?`
  ).bind(id).first();
  if (!wo || wo.account_id !== accountId) return c.json({ error: "not_found" }, 404);
  if (role === "contractor" && wo.company_id !== companyId) return c.json({ error: "forbidden" }, 403);

  await c.env.DB.prepare(
    `UPDATE work_orders SET status = ?, responded_at = CURRENT_TIMESTAMP WHERE id = ?`
  ).bind(status, id).run();
  const counterCol = status === "accepted" ? "accepted" : "declined";
  await c.env.DB.prepare(
    `UPDATE engagements SET ${counterCol} = ${counterCol} + 1 WHERE id = ?`
  ).bind(wo.engagement_id).run();

  await logEvent(c.env, accountId, userId, `wo.${status}`, id, {});
  await touchJob(c.env, wo.job_id);
  if (status === "accepted") await notifyTenant(c, wo.job_id, "booked");
  // 065. AND ON AN AUTO-SCHEDULED TURNAROUND, TAKING THE JOB IS WHAT STARTS
  // THE CLOCK. Until they accept they are not a party to the time, so a window
  // put forward earlier would settle without them -- booked, with the crew
  // never asked. This is where the chain actually begins.
  if (status === "accepted") {
    await autoProposeOnAccept(c, wo).catch((err) =>
      console.warn("[auto-turnaround] propose on accept failed:", err?.message || err));
  }
  return c.json({ ok: true });
});

// Pull a trade off a job entirely — voids the live WO, issues nothing new.
app.post("/api/jobs/:jobId/unassign/:trade", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { jobId, trade } = c.req.param();
  const wo = await c.env.DB.prepare(
    `SELECT wo.id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id
     WHERE wo.job_id = ? AND wo.trade = ? AND wo.voided_at IS NULL AND j.account_id = ?`
  ).bind(jobId, trade, accountId).first();
  if (!wo) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`UPDATE work_orders SET voided_at = CURRENT_TIMESTAMP WHERE id = ?`).bind(wo.id).run();
  await logEvent(c.env, accountId, userId, "wo.voided", wo.id, { jobId, trade });
  return c.json({ ok: true });
});

// Reassigning which crew covers a WO is operational, not a contract term —
// unlike reissue(), this updates the live row in place.
app.post("/api/work-orders/:id/crew", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const id = c.req.param("id");
  const { crewName } = await c.req.json();
  const wo = await c.env.DB.prepare(
    `SELECT wo.id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ? AND j.account_id = ?`
  ).bind(id, accountId).first();
  if (!wo) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`UPDATE work_orders SET crew_name = ? WHERE id = ?`).bind(crewName, id).run();
  return c.json({ ok: true });
});

app.post("/api/work-orders/:id/signed", async (c) => {
  const { accountId } = c.get("auth");
  const id = c.req.param("id");
  const { fileKey } = await c.req.json();
  const wo = await c.env.DB.prepare(
    `SELECT wo.id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ? AND j.account_id = ?`
  ).bind(id, accountId).first();
  if (!wo) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`UPDATE work_orders SET signed_file_key = ? WHERE id = ?`).bind(fileKey, id).run();
  return c.json({ ok: true });
});

// Rating a job's work belongs to the RELATIONSHIP, not the company — the
// engagement's rating is the average across every rated WO under it.
app.post("/api/work-orders/:id/rate", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const { rating } = await c.req.json(); // 1-5
  const wo = await c.env.DB.prepare(
    `SELECT wo.*, j.account_id FROM work_orders wo JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ?`
  ).bind(id).first();
  if (!wo || wo.account_id !== accountId) return c.json({ error: "not_found" }, 404);

  await c.env.DB.prepare(`UPDATE work_orders SET rating = ? WHERE id = ?`).bind(rating, id).run();

  const { results: rated } = await c.env.DB.prepare(
    `SELECT rating FROM work_orders WHERE engagement_id = ? AND rating IS NOT NULL`
  ).bind(wo.engagement_id).all();
  const avg = rated.reduce((n, r) => n + r.rating, 0) / rated.length;
  await c.env.DB.prepare(`UPDATE engagements SET rating = ?, rated_jobs = ? WHERE id = ?`)
    .bind(Math.round(avg * 10) / 10, rated.length, wo.engagement_id).run();

  await logEvent(c.env, accountId, userId, "wo.rated", id, { rating });
  return c.json({ ok: true, rating: Math.round(avg * 10) / 10 });
});

// ---------------------------------------------------------------------------
// Document review (per-engagement verdict on a company's uploaded file)
// ---------------------------------------------------------------------------
app.post("/api/subs/:companyId/documents/:kind/review", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const companyId = c.req.param("companyId");
  const kind = c.req.param("kind"); // insurance | bond | contract
  const body = await c.req.json(); // { status, limits, checks, overrides, note }

  const engagement = await c.env.DB.prepare(
    `SELECT * FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (!engagement) return c.json({ error: "not_found" }, 404);

  const docReview = parseJson(engagement.doc_review, {});

  // PER-ITEM FINDINGS, and `checks` DERIVED from them rather than stored beside.
  //
  // A review was pass or fail with a free-text note, and an unticked box meant
  // two different things -- "not got to this yet" and "checked, and it is not
  // there" -- which nothing could tell apart. So the one correctable problem
  // that matters most in construction compliance, the hiring account missing
  // from the additional insured schedule, could only be reported by rejecting
  // the whole certificate and typing a paragraph.
  //
  // `findings` is the record. `checks` is written from it so that anything
  // still reading the old shape agrees by construction -- two independently
  // stored answers to one question is two answers.
  const findings = {};
  // Whether the CALLER sent findings, not whether any of them carried an answer.
  // Those come apart: a reviewer who opened the form and answered nothing still
  // sends a full map of `unanswered`, and writing it is right -- but a caller
  // that sent no `findings` key at all must not have one invented, because
  // `findingsFor` prefers a stored map over the legacy `checks` object and an
  // invented all-unanswered map would mask the checks that same call sent.
  const gaveFindings = !!body.findings && typeof body.findings === "object";
  if (gaveFindings) {
    const acct = await c.env.DB.prepare(`SELECT name FROM accounts WHERE id = ?`).bind(accountId).first();
    const norm = findingsFor({ findings: body.findings }, kind, acct?.name || "the hiring account");
    for (const [id, f] of Object.entries(norm)) {
      // An unanswered line with nothing typed against it is the absence of an
      // answer, not an answer -- so it is not a row.
      if (f.state === "unanswered" && !f.note) continue;
      findings[id] = { state: f.state, note: String(f.note || "").slice(0, 600) || undefined };
    }
  }

  // The whole entry is REPLACED, which is what drops any saved draft: a
  // half-read certificate that outlived the decision would reopen over a
  // finished review. Stated rather than left to the spread, because a later
  // change that carried the old entry forward would resurrect it silently.
  docReview[kind] = { ...body, verifiedBy: userId, verifiedAt: new Date().toISOString().slice(0, 10),
    ...(gaveFindings ? { findings, checks: checksFrom(findings) } : {}) };
  delete docReview[kind].draft;
  delete docReview[kind].draftAt;
  delete docReview[kind].draftBy;
  await c.env.DB.prepare(`UPDATE engagements SET doc_review = ? WHERE id = ?`)
    .bind(JSON.stringify(docReview), engagement.id).run();

  // What the certificate actually says, onto the COMPANY's row rather than
  // this engagement's verdict -- one certificate, shared by every account that
  // engages them, so it cannot expire on different days for different people.
  // This is the moment to ask for it: somebody is reading the document right
  // now in order to approve it, and was already reading these fields.
  //
  // Only on a verified review. A rejection is not a record of cover.
  if (body.status === "verified") {
    try {
      const rows = await currentDocRows(c.env.DB, companyId);
      const cur = rows[kind];
      const expires = isoDay(body.expiresOn ?? body.expires);
      const coverage = centsOf(body.coverageCents ?? body.coverage);
      if (cur) {
        await c.env.DB.prepare(
          `UPDATE company_docs SET
             issuer = COALESCE(?, issuer), policy_no = COALESCE(?, policy_no),
             coverage_cents = COALESCE(?, coverage_cents),
             effective_on = COALESCE(?, effective_on),
             expires_on = COALESCE(?, expires_on),
             approved_at = CURRENT_TIMESTAMP, approved_by = ?
           WHERE id = ?`
        ).bind((body.issuer || "").trim() || null, (body.policyNo || "").trim() || null,
          coverage, isoDay(body.effectiveOn), expires, userId, cur.id).run();
      } else {
        // Approving a file that predates 037, or one uploaded before this
        // shipped. There is a file -- the boolean says so -- and now there is
        // a row describing it, so the next thirty days of chasing work.
        const company = await c.env.DB.prepare(
          `SELECT doc_files FROM companies WHERE id = ?`).bind(companyId).first();
        await c.env.DB.prepare(
          `INSERT INTO company_docs
             (id, company_id, kind, file_name, issuer, policy_no, coverage_cents,
              effective_on, expires_on, approved_at, approved_by)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?)`
        ).bind(uid(), companyId, kind,
          parseJson(company?.doc_files, {})[kind] || "on file",
          (body.issuer || "").trim() || null, (body.policyNo || "").trim() || null,
          coverage, isoDay(body.effectiveOn), expires, userId).run();
      }
      // A fresh expiry restarts the chase. Without this, a renewed
      // certificate stays silent because the old row's reminders are already
      // on file and nothing would ever be sent again.
      if (expires) {
        const again = await currentDocRows(c.env.DB, companyId);
        if (again[kind]) {
          await c.env.DB.prepare(`DELETE FROM doc_reminders WHERE company_doc_id = ?`)
            .bind(again[kind].id).run();
        }
      }
    } catch (err) {
      if (!missingSchema(err)) throw err;
      console.warn("[company_docs] review detail not stored:", err?.message || err);
    }
  }

  await logEvent(c.env, accountId, userId, "doc.reviewed", companyId, { kind, status: body.status });
  await logActivity(c.env, accountId, userId,
    body.status === "verified" ? "doc_verified" : "doc_rejected",
    `${body.status === "verified" ? "Verified" : "Rejected"} ${kind} for ${await companyName(c.env.DB, companyId)}`);
  return c.json({ ok: true });
});

// The FILE belongs to the company (uploaded once, shared by every GC that
// engages them). Re-uploading reopens the review queue for EVERY account
// that engages this company, not just the one who uploaded it — same
// design as the prototype's uploadSubDoc().
// May this seat write to this company's documents at all?
//
// `companies` is a SHARED row: one certificate, one set of booleans, read by
// every account that engages them. So a write here is not a write to your own
// data, and these two routes checked the contractor and nobody else -- an admin
// or a project manager could upload against, and delete from, ANY company id.
//
// That was reachable rather than theoretical. GET /api/account-by-subdomain/:s
// is on the public exemption list and answers with the account id; ownCompanyId
// derives `cmp_own_<accountId>` from it; and DELETE then runs
// `UPDATE companies SET insurance = 0` on a general contractor nobody involved
// has any relationship with. missingDocs and docsComplete read those booleans,
// so that takes them off every roster they are on and their clients are told
// they cannot be assigned work -- and supersedeDoc on the POST side retires the
// certificate row that answers "were they insured on the day of that job".
//
// The check the review route three functions up already does, applied to the
// two routes that write the shared row. Stricter in one way: an ENDED
// engagement is a finished relationship and does not carry the right to edit
// their paperwork afterwards. Review may keep using any engagement -- it writes
// its own account's verdict, on its own row, and reaches nothing shared.
//
// Answering `not_found` rather than `forbidden`, and BEFORE the company is
// looked up, so a company that exists and one that does not give the same
// reply. A 403 here would confirm which derived ids are real, which is the
// same rule the handover subdomain lookup follows.
async function mayWriteCompanyDocs(c, companyId) {
  const auth = c.get("auth");
  if (auth.role === "contractor") return auth.companyId === companyId;
  // Their OWN account's company row, which is not a shared row needing a
  // relationship -- it is this account's own paperwork.
  //
  // Without this, an account that can be hired but has not been yet could not
  // upload its own certificate: the engagement check below asks "do I hire
  // them", and the answer for yourself is always no. That closed the
  // send-your-compliance-pack loop at its first step for exactly the person it
  // exists for -- a subcontractor who signed up on their own rather than being
  // invited, who by definition has no client yet. The panel rendered and the
  // upload answered 404, which is the screen-that-lies failure this file keeps
  // coming back to.
  //
  // Resolved through seatCompany, the same function the read path and
  // /api/doc-shares use, so the two cannot disagree about which row is "mine".
  // And it reads the account id off the SESSION, never off the URL: the hole
  // this check was added to close was that `cmp_own_<accountId>` is derivable
  // from a public route, and deriving somebody else's still gets nowhere here
  // because it cannot equal your own.
  if (auth.accountId && (await seatCompany(c)) === companyId) return true;
  const engaged = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements
      WHERE account_id = ? AND company_id = ? AND status != 'ended' LIMIT 1`
  ).bind(auth.accountId, companyId).first();
  return !!engaged;
}

// The document itself, to the people who have to read it.
//
// Uploading has worked since the start and nothing could ever read one back.
// The only route that served a compliance document's bytes was the PUBLIC
// pack link, keyed by an emailed token -- so a stranger holding a forwarded
// certificate could see it and the account being asked to APPROVE it could
// not. What the review screen offered instead was a generated .txt listing
// the checks it wanted somebody to perform against a document it would not
// show them, which is the screen-that-lies rule pointed at the one screen
// whose entire job is reading a document.
//
// Pinned the same three ways the pack route is: the caller has a relationship
// with this company, the row belongs to that company, and it is the CURRENT
// row of that kind. No R2 key is ever accepted from the caller -- `fileKey`
// travels out on the read shape and means nothing on the way back in.
//
// The W-9 IS served here, and that is the point rather than an oversight.
// `inLink` keeps a taxpayer number out of an emailed link precisely BECAUSE
// this door exists: the pack page says a W-9 is on file and that reading it
// needs an account. This is the account.
// Find an uploaded object by the name the company row records, when nothing
// recorded its key.
//
// `PUT /api/uploads/:kind/:fileName` builds the key as
// `<accountId>/<kind>/<uid>-<fileName>`, and `companies.doc_files[kind]` holds
// that same fileName -- so the object is findable by suffix even though the
// random id in the middle is not derivable. Newest wins, because a replaced
// document keeps its old object and the current one is what is being asked
// for.
//
// Bounded rather than open-ended: an account that has replaced a certificate
// every month for years should not turn one screen into an unbounded scan, so
// it stops after MAX_PAGES and answers "not found" rather than paging on.
async function findUploadedObject(env, accountId, kind, fileName) {
  const prefix = `${accountId}/${kind}/`;
  const suffix = `-${fileName}`;
  const MAX_PAGES = 5;
  let cursor;
  let best = null, bestAt = 0;
  for (let page = 0; page < MAX_PAGES; page++) {
    let res;
    try {
      res = await env.FILES.list({ prefix, cursor, limit: 1000 });
    } catch (err) {
      console.warn("[doc-file] bucket listing failed:", err?.message || err);
      return null;
    }
    for (const o of res?.objects || []) {
      if (!o.key.endsWith(suffix)) continue;
      const at = o.uploaded ? new Date(o.uploaded).getTime() : 0;
      if (!best || at >= bestAt) { best = o.key; bestAt = at; }
    }
    if (!res?.truncated) break;
    cursor = res.cursor;
  }
  return best;
}

app.get("/api/subs/:companyId/documents/:kind/file", requireRole("admin", "pm", "contractor"), async (c) => {
  const auth = c.get("auth");
  const { companyId, kind } = c.req.param();
  if (!DOC_KINDS.includes(kind)) return c.json({ error: "not_found" }, 404);
  // The same predicate as writing, deliberately. Somebody who may REPLACE
  // their certificate may certainly read it, so a second rule here could only
  // be wrong in one direction or the other. It answers before the company is
  // looked up, so a company that exists and one that does not give the same
  // reply -- the oracle `mayWriteCompanyDocs` already refuses to be.
  if (!(await mayWriteCompanyDocs(c, companyId))) return c.json({ error: "not_found" }, 404);

  // Where the key IS recorded: the current row of that kind. Serving a
  // superseded one would draw last year's certificate under a heading
  // reading "Verified".
  let doc = null;
  try {
    doc = await c.env.DB.prepare(
      `SELECT file_key, file_name FROM company_docs
        WHERE company_id = ? AND kind = ? AND superseded_at IS NULL
        ORDER BY uploaded_at DESC LIMIT 1`
    ).bind(companyId, kind).first();
  } catch (err) {
    // A database that has not run 037 has no such table at all, which is not
    // an error here: it is the commonest reason the key is missing, and the
    // bytes are still in the bucket. Fall through.
    if (!missingSchema(err)) throw err;
  }

  let key = doc?.file_key || null;
  let name = doc?.file_name || null;

  // And where it is NOT recorded. The upload route puts the file in R2 first
  // and writes company_docs second, inside a try/catch that swallows a
  // missing table -- so on a database without 037 every document has a file
  // and no row saying where. `doc_files` still names it, and the key the
  // upload built ends with that exact name, so the object is findable.
  //
  // Scoped to the CALLER'S OWN account prefix, read off the session and never
  // the URL, so this cannot reach into another account's space: at worst it
  // fails to find a file somebody uploaded while seated somewhere else, which
  // fails closed. And the name must be the one recorded on a company row this
  // caller already has a relationship with.
  if (!key) {
    const company = await c.env.DB.prepare(
      `SELECT doc_files FROM companies WHERE id = ?`
    ).bind(companyId).first();
    const wanted = parseJson(company?.doc_files, {})[kind];
    if (wanted && auth.accountId) {
      const found = await findUploadedObject(c.env, auth.accountId, kind, wanted);
      if (found) { key = found; name = name || wanted; }
    }
  }

  // `no_file` is its own answer and is not the same as `not_found`. A caller
  // who got this far has a relationship with the company and already knows it
  // exists, so there is nothing to give away -- and the two need telling
  // apart, because one of them is a document nobody can produce.
  if (!key) return c.json({ error: "no_file" }, 404);

  const obj = await c.env.FILES.get(key);
  if (!obj) return c.json({ error: "no_file" }, 404);
  return new Response(obj.body, {
    headers: {
      "Content-Type": obj.httpMetadata?.contentType || "application/octet-stream",
      "Content-Disposition": `inline; filename="${(name || "document").replace(/[^\w.\-]/g, "_")}"`,
      // Never a shared cache: this is one company's certificate, and an
      // intermediary holding a copy outlives the engagement that allowed it.
      "Cache-Control": "private, no-store",
    },
  });
});

// A half-read certificate, kept so nobody reads it twice.
//
// Verifying is one press, but READING an ACORD 25 is not: six coverage lines,
// a carrier, a policy number, two dates and five things to confirm on the
// document. A reviewer who gets four lines in and finds the sixth missing has
// to stop and ask the contractor -- and until now closing the modal threw
// away everything they had typed, so the next attempt started from an empty
// form over a document they had already read once.
//
// THREE PROPERTIES, and the first is the one that matters.
//
// A DRAFT IS NOT A VERDICT. It is stored BESIDE `status`, never as one, so
// `docStatus` keeps answering "pending" and `missingDocs`, `docsComplete`,
// the assignment gate and every badge are untouched. A half-finished review
// that made somebody assignable would be the expired-certificate failure this
// product exists to prevent, arrived at from a new direction -- and it would
// be worse, because it would read as a decision somebody made.
//
// IT IS THE ACCOUNT'S, NOT THE PERSON'S. It lives on `engagements`, which is
// already per-account and already where the verdict lives, so a reviewer who
// runs out of day can be picked up by a colleague. `draftBy` names who left
// it, because a shared form somebody else half-filled needs to say so.
//
// AND IT IS CLEARED BY A DECISION. The review route replaces the whole entry,
// so a verdict drops the draft by construction -- a draft that outlived the
// answer would reopen over a finished review, which is the same shape as a
// queue row that survives being answered.
app.put("/api/subs/:companyId/documents/:kind/draft", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { companyId, kind } = c.req.param();
  if (!DOC_KINDS.includes(kind)) return c.json({ error: "not_found" }, 404);

  const engagement = await c.env.DB.prepare(
    `SELECT * FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (!engagement) return c.json({ error: "not_found" }, 404);

  const body = await c.req.json().catch(() => ({}));
  const docReview = parseJson(engagement.doc_review, {});
  const prev = docReview[kind] || {};
  docReview[kind] = {
    ...prev,
    // Never from the body. A draft that could set its own status is a verdict
    // wearing a draft's name, and this route is reachable by every seat the
    // review route is.
    status: prev.status || "pending",
    draft: body.draft ?? null,
    draftAt: body.draft ? new Date().toISOString() : null,
    draftBy: body.draft ? userId : null,
  };
  await c.env.DB.prepare(`UPDATE engagements SET doc_review = ? WHERE id = ?`)
    .bind(JSON.stringify(docReview), engagement.id).run();
  return c.json({ ok: true, draftAt: docReview[kind].draftAt });
});

app.post("/api/subs/:companyId/documents/:kind", requireRole("admin", "pm", "contractor"), async (c) => {
  const auth = c.get("auth");
  const { companyId } = c.req.param();
  const kind = c.req.param("kind"); // insurance | bond | contract | w9
  if (!(await mayWriteCompanyDocs(c, companyId))) return c.json({ error: "not_found" }, 404);
  const body = await c.req.json();
  const { fileKey, fileName } = body;

  const company = await c.env.DB.prepare(`SELECT doc_files FROM companies WHERE id = ?`).bind(companyId).first();
  if (!company) return c.json({ error: "not_found" }, 404);

  // THE ROW FIRST, THE BOOLEANS SECOND, and the order is the whole point.
  //
  // It used to be the other way round, with the row written inside a
  // try/catch that swallowed anything `missingSchema` recognised. So a
  // detail write that failed left the booleans already set: the roster read
  // "certificate of insurance, awaiting review" with no record of what the
  // certificate says, no expiry to chase, and nothing superseded -- which is
  // 037's entire purpose, silently not happening. It is how a live database
  // ended up with every document flagged on file and `company_docs`
  // completely empty, and nothing anywhere could report it.
  //
  // Now a real failure refuses before anything is written, so the upload is
  // retried rather than half-recorded. The ONE tolerated failure is the table
  // not being there at all, which is a database that has not run 037 and is
  // documented behaviour -- and even that is now SAID rather than assumed, in
  // `detail` on the reply, so a caller can tell the two apart.
  let detail = "recorded";
  try {
    await supersedeDoc(c.env.DB, companyId, kind);
    await c.env.DB.prepare(
      `INSERT INTO company_docs
         (id, company_id, kind, file_key, file_name, issuer, policy_no,
          coverage_cents, effective_on, expires_on, uploaded_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(uid(), companyId, kind, fileKey || null, fileName || null,
      (body.issuer || "").trim() || null, (body.policyNo || "").trim() || null,
      centsOf(body.coverageCents ?? body.coverage),
      isoDay(body.effectiveOn), isoDay(body.expiresOn), auth.userId).run();
  } catch (err) {
    if (!missingSchema(err)) {
      // Nothing has been written yet, so this is a clean refusal rather than
      // a half-done upload. The bytes are already in R2 and the same call
      // repeated lands the same row, so a retry is safe.
      console.error("[company_docs] detail write failed:", err?.message || err);
      return c.json({ error: "detail_not_stored", detail: String(err?.message || err).slice(0, 300) }, 500);
    }
    console.warn("[company_docs] not available:", err?.message || err);
    detail = "not_migrated";
  }

  // What every existing screen and query reads. Written second, so it can
  // never claim a document the record above does not describe.
  const docFiles = { ...parseJson(company.doc_files, {}), [kind]: fileName };
  const col = { insurance: "insurance", bond: "bond", contract: "contract", w9: "w9" }[kind];
  await c.env.DB.prepare(
    `UPDATE companies SET doc_files = ?${col ? `, ${col} = 1` : ""} WHERE id = ?`
  ).bind(JSON.stringify(docFiles), companyId).run();

  const { results: engagements } = await c.env.DB.prepare(
    `SELECT id, doc_review FROM engagements WHERE company_id = ?`
  ).bind(companyId).all();
  for (const e of engagements) {
    const docReview = { ...parseJson(e.doc_review, {}), [kind]: { status: "pending" } };
    await c.env.DB.prepare(`UPDATE engagements SET doc_review = ? WHERE id = ?`).bind(JSON.stringify(docReview), e.id).run();
  }

  // UPLOADING A SIGNED AGREEMENT IS SIGNING IT, and without this the
  // "I'll use my own paper" route was a dead end: the hiring account issued
  // an `uploaded` agreement, the screen told the subcontractor to upload
  // their signed copy, and nothing anywhere moved when they did. It sat at
  // `sent` for ever -- the correct-pieces-with-no-way-in failure this file
  // has now recorded half a dozen times, arrived at from a new direction.
  //
  // It advances to `signed`, not to in force: the hiring account still has to
  // say the paper they got back is the one they sent, which is the same
  // second signature SubSub's own form takes.
  if (kind === "contract" && fileName) {
    try {
      await c.env.DB.prepare(
        `UPDATE agreements SET status = 'signed', signed_at = CURRENT_TIMESTAMP,
           signed_by = ?, file_name = ?
         WHERE company_id = ? AND source = 'uploaded' AND status = 'sent'`
      ).bind(auth.userId, fileName, companyId).run();
    } catch (err) {
      // A database without 052 has no agreements to advance, and an upload
      // must not fail for want of a table this route never needed before.
      if (!missingSchema(err)) throw err;
    }
  }
  return c.json({ ok: true, detail });
});

app.delete("/api/subs/:companyId/documents/:kind", requireRole("admin", "pm", "contractor"), async (c) => {
  const { companyId } = c.req.param();
  const kind = c.req.param("kind");
  if (!(await mayWriteCompanyDocs(c, companyId))) return c.json({ error: "not_found" }, 404);

  const company = await c.env.DB.prepare(`SELECT doc_files FROM companies WHERE id = ?`).bind(companyId).first();
  if (!company) return c.json({ error: "not_found" }, 404);
  const docFiles = { ...parseJson(company.doc_files, {}), [kind]: null };

  const col = { insurance: "insurance", bond: "bond", contract: "contract", w9: "w9" }[kind];
  await c.env.DB.prepare(
    `UPDATE companies SET doc_files = ?${col ? `, ${col} = 0` : ""} WHERE id = ?`
  ).bind(JSON.stringify(docFiles), companyId).run();

  const { results: engagements } = await c.env.DB.prepare(
    `SELECT id, doc_review FROM engagements WHERE company_id = ?`
  ).bind(companyId).all();
  for (const e of engagements) {
    const docReview = { ...parseJson(e.doc_review, {}) };
    delete docReview[kind];
    await c.env.DB.prepare(`UPDATE engagements SET doc_review = ? WHERE id = ?`).bind(JSON.stringify(docReview), e.id).run();
  }
  // Superseded, not deleted. Somebody removing this year's certificate does
  // not unmake the fact that last year's covered a job that was worked.
  try {
    await supersedeDoc(c.env.DB, companyId, kind);
  } catch (err) {
    if (!missingSchema(err)) throw err;
  }
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// "Send my documents to a contractor."
//
// The subcontractor's own paperwork, handed to one person who asked for it.
// See shared/docshare.js for the rules and 041 for why this exists at all:
// it is the only path where the free side can bring the paying side in,
// because every other way in needs the hiring account to already be here.
// ---------------------------------------------------------------------------

// A token that is worth being a secret. 32 bytes of CSPRNG, base64url --
// never derived from the company, the recipient or the clock, all of which a
// recipient already knows and could otherwise walk.
// A password nobody is ever told, for an account whose owner will set their
// own through the emailed link. Full entropy rather than something memorable:
// the point is that it is unusable, not that it is typeable.
function randomSecret() {
  const b = new Uint8Array(24);
  crypto.getRandomValues(b);
  return "Ss1!" + btoa(String.fromCharCode(...b)).replace(/[^A-Za-z0-9]/g, "");
}

// ===========================================================================
// Subcontractor agreements
//
// An agreement is between TWO PARTIES, which is why none of this touches
// `companies`. See shared/agreement.js for the whole of the reasoning; the
// short version is that one boolean on a shared company row said a roofer had
// "a signed agreement" with nobody named, so signing with one general
// contractor read as signed with all of them.
// ===========================================================================

const agreementMigration = () => ({ error: "migration_needed", migration: "052_agreements" });

// What was signed, as forty hex characters. The whole difference between
// proving somebody signed something and proving WHAT.
async function sha256Hex(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// The live agreement for a pair, or null. `LIVE_STATES` is the same list the
// partial unique index uses, so the row this finds is the row the index
// guarantees is the only one.
async function liveAgreement(env, accountId, companyId) {
  return await env.DB.prepare(
    `SELECT * FROM agreements
      WHERE account_id = ? AND company_id = ? AND status IN ('sent','signed','countersigned')
      ORDER BY issued_at DESC LIMIT 1`
  ).bind(accountId, companyId).first();
}

// Every live agreement addressed to the companies on this account's roster,
// in one read. The roster draws a row per subcontractor and asking per row
// would be a query per contractor on every page load.
async function liveAgreementsFor(env, accountId) {
  const { results } = await env.DB.prepare(
    `SELECT * FROM agreements
      WHERE account_id = ? AND status IN ('sent','signed','countersigned')`
  ).bind(accountId).all();
  const by = {};
  for (const r of results || []) by[r.company_id] = r;
  return by;
}

// The hiring account's standing terms, and their own details as they should
// read in a contract.
//
// An account with no row has never answered, and the effective answer to that
// is the defaults with nothing required -- which is the recorded decision:
// an agreement counts against a subcontractor only once somebody has actually
// asked for one.
async function accountAgreementTerms(env, accountId) {
  const row = await env.DB.prepare(`SELECT * FROM agreement_terms WHERE account_id = ?`)
    .bind(accountId).first();
  return {
    terms: validTerms(parseJson(row?.terms, {})),
    hiringParty: parseJson(row?.hiring_party, {}) || {},
    requireByDefault: !!row?.require_by_default,
    updatedAt: row?.updated_at || null,
  };
}

// Both parties, as they read at the moment of issue.
//
// STAMPED, NEVER READ LIVE. A company can be renamed and an account can
// change its standard terms; a re-render that picked either up afterwards
// would produce a document that no longer matches its own hash, which is the
// one thing the hash exists to prevent.
async function agreementParties(env, accountId, companyId) {
  const acct = await env.DB.prepare(`SELECT name, kind, company_id FROM accounts WHERE id = ?`)
    .bind(accountId).first();
  const stored = await accountAgreementTerms(env, accountId);
  // Their own company row when they have one -- every hireable kind does
  // since 031 -- and what they typed in Account otherwise, because a property
  // manager has no company row by design and `accounts` carries no address.
  // The MAILING address, falling back to the physical one. `companies` has no
  // street for the latter -- it is city/state/zip -- and a contract wants the
  // address notices go to.
  const ADDR = `SELECT company, mail_street, mail_city, mail_state, mail_zip,
                       city, state, zip, license FROM companies WHERE id = ?`;
  let own = null;
  if (acct?.company_id) own = await env.DB.prepare(ADDR).bind(acct.company_id).first();
  const hp = stored.hiringParty || {};
  const sub = await env.DB.prepare(ADDR).bind(companyId).first();
  const addr = (r) => !r ? {} : ({
    street: r.mail_street || null,
    city: r.mail_city || r.city || null,
    state: r.mail_state || r.state || null,
    zip: r.mail_zip || r.zip || null,
  });
  const ownAddr = addr(own), subAddr = addr(sub);
  return {
    // WHAT THE TWO PARTIES ARE CALLED FOLLOWS THE KIND, and the kind is
    // stamped here rather than read at render. A general contractor engages a
    // SUBcontractor under a prime contract; a property manager engages a
    // plumber directly and nobody is sub to anything. The same distinction
    // `hiresLabel` already draws on the roster, in the one place it matters
    // most -- a contract's defined terms. Stamped, because an account may
    // change kind afterwards and a signed document must not change with it.
    kind: acct?.kind || null,
    hiring: {
      name: hp.name || own?.company || acct?.name || "",
      street: hp.street || ownAddr.street || null,
      city: hp.city || ownAddr.city || null,
      state: hp.state || ownAddr.state || null,
      zip: hp.zip || ownAddr.zip || null,
      license: hp.license || own?.license || null,
    },
    sub: {
      name: sub?.company || "",
      street: subAddr.street || null,
      city: subAddr.city || null,
      state: subAddr.state || null,
      zip: subAddr.zip || null,
      license: sub?.license || null,
    },
  };
}

// The row, as the browser reads it. Never the raw row: `signed_ip` is kept
// for the record and is nobody's to display.
const agreementToJs = (r, extra = {}) => !r ? null : ({
  id: r.id,
  accountId: r.account_id,
  companyId: r.company_id,
  source: r.source,
  status: r.status,
  templateId: r.template_id || null,
  templateVersion: r.template_version || null,
  terms: parseJson(r.terms, {}),
  parties: parseJson(r.parties, {}),
  governingState: r.governing_state || null,
  fileName: r.file_name || null,
  docSha256: r.doc_sha256 || null,
  issuedAt: r.issued_at || null,
  signedAt: r.signed_at || null,
  signedByName: r.signed_by_name || null,
  countersignedAt: r.countersigned_at || null,
  countersignedByName: r.countersigned_by_name || null,
  declinedAt: r.declined_at || null,
  declinedNote: r.declined_note || null,
  waitingOn: waitingOn(r),
  inForce: inForce(r),
  ...extra,
});

// Rendering a stored agreement, refused loudly when the template version it
// names is not in this build.
//
// `renderAgreement` throws rather than falling back, because a fallback would
// draw a DIFFERENT contract under a heading saying it was signed -- and the
// wrong contract still reads like a contract, so nobody would catch it by
// looking. Every version ever signed stays in agreement-standard.js; this is
// what says so out loud if one ever does not.
function renderStored(r) {
  if (!r || r.source !== "subsub_standard") return null;
  try {
    return renderAgreement({
      templateId: r.template_id,
      templateVersion: r.template_version,
      parties: parseJson(r.parties, {}),
      terms: parseJson(r.terms, {}),
      issuedOn: String(r.issued_at || "").slice(0, 10),
    });
  } catch (err) {
    if (err?.code === "unknown_template") return { unavailable: String(err.message) };
    throw err;
  }
}

// ---- the hiring account's standing terms ----------------------------------

app.get("/api/agreement-terms", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  try {
    const stored = await accountAgreementTerms(c.env, accountId);
    return c.json({
      ...stored,
      fields: TERM_FIELDS,
      template: {
        id: STANDARD_AGREEMENT.id,
        version: STANDARD_AGREEMENT.version,
        title: STANDARD_AGREEMENT.title,
        // Null until somebody qualified has actually read it, and the screen
        // says which it is. An unreviewed template naming a real firm and a
        // real date would read exactly like a reviewed one.
        reviewed: STANDARD_AGREEMENT.reviewed || null,
      },
    });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

app.patch("/api/agreement-terms", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const body = await c.req.json().catch(() => ({}));
  try {
    const cur = await accountAgreementTerms(c.env, accountId);
    // Normalised on the way IN, never only on the way out. This lands in a
    // column the renderer reads directly, and a string where a number belongs
    // prints "$NaN" into a document somebody is about to sign.
    const terms = body.terms === undefined ? cur.terms : validTerms(body.terms);
    const hiringParty = body.hiringParty === undefined ? cur.hiringParty : {
      name: String(body.hiringParty?.name || "").trim().slice(0, 200) || null,
      street: String(body.hiringParty?.street || "").trim().slice(0, 200) || null,
      city: String(body.hiringParty?.city || "").trim().slice(0, 100) || null,
      state: /^[A-Za-z]{2}$/.test(String(body.hiringParty?.state || "").trim())
        ? String(body.hiringParty.state).trim().toUpperCase() : null,
      zip: String(body.hiringParty?.zip || "").trim().slice(0, 12) || null,
      license: String(body.hiringParty?.license || "").trim().slice(0, 60) || null,
    };
    const requireByDefault = body.requireByDefault === undefined
      ? cur.requireByDefault : !!body.requireByDefault;
    await c.env.DB.prepare(
      `INSERT INTO agreement_terms (account_id, terms, hiring_party, require_by_default, updated_by)
       VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(account_id) DO UPDATE SET
         terms = excluded.terms, hiring_party = excluded.hiring_party,
         require_by_default = excluded.require_by_default,
         updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by`
    ).bind(accountId, JSON.stringify(terms), JSON.stringify(hiringParty),
      requireByDefault ? 1 : 0, userId).run();
    return c.json({ ok: true, terms, hiringParty, requireByDefault });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

// ---- the hiring side ------------------------------------------------------

// What this account's agreement with this subcontractor is, and the document
// itself so the screen can show what it is about to send or has sent.
app.get("/api/subs/:companyId/agreement", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const { companyId } = c.req.param();
  // A company this account does not engage answers not_found, before the
  // company is looked up, so a real id and an invented one give the same
  // reply -- the oracle every id-keyed route here refuses to be.
  const engaged = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements WHERE account_id = ? AND company_id = ? LIMIT 1`
  ).bind(accountId, companyId).first();
  if (!engaged) return c.json({ error: "not_found" }, 404);

  try {
    const row = await liveAgreement(c.env, accountId, companyId);
    const stored = await accountAgreementTerms(c.env, accountId);
    // A preview of what WOULD be sent, so the screen is never asking somebody
    // to issue a document they have not been shown.
    const parties = await agreementParties(c.env, accountId, companyId);
    const previewTerms = validTerms({
      ...stored.terms,
      governingState: stored.terms.governingState || parties.hiring.state || null,
    });
    return c.json({
      agreement: agreementToJs(row, { document: renderStored(row) }),
      preview: renderAgreement({
        templateId: STANDARD_AGREEMENT.id,
        templateVersion: STANDARD_AGREEMENT.version,
        parties, terms: previewTerms,
        issuedOn: new Date().toISOString().slice(0, 10),
      }),
      previewTerms,
      parties,
      requireByDefault: stored.requireByDefault,
      fields: TERM_FIELDS,
    });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

// Issue one. This IS the requirement: there is no separate "required" flag,
// because a flag beside an agreement row would be two records of one fact and
// they would eventually disagree.
app.post("/api/subs/:companyId/agreement", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { companyId } = c.req.param();
  const body = await c.req.json().catch(() => ({}));

  const engaged = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM engagements WHERE account_id = ? AND company_id = ? AND status != 'ended' LIMIT 1`
  ).bind(accountId, companyId).first();
  if (!engaged) return c.json({ error: "not_found" }, 404);

  const source = AGREEMENT_SOURCES.includes(body.source) ? body.source : "subsub_standard";

  try {
    const existing = await liveAgreement(c.env, accountId, companyId);
    // Refused rather than quietly replaced. A live agreement is a document the
    // other party may have signed, or may be reading right now; superseding it
    // from under them is a change to terms nobody was told about.
    if (existing) return c.json({ error: "already_issued", status: existing.status }, 409);

    const stored = await accountAgreementTerms(c.env, accountId);
    const parties = await agreementParties(c.env, accountId, companyId);
    const terms = mergeTerms(stored.terms, body.terms);
    // The hiring account's state unless somebody said otherwise. Stamped, so
    // editing an address later cannot change what a signed document meant --
    // the rule lien_waivers.governing_state already follows.
    const governingState = terms.governingState || parties.hiring.state || null;
    const full = validTerms({ ...terms, governingState });

    const id = uid();
    const issuedOn = new Date().toISOString().slice(0, 10);
    let templateId = null, templateVersion = null, docSha256 = null;
    if (source === "subsub_standard") {
      templateId = STANDARD_AGREEMENT.id;
      templateVersion = STANDARD_AGREEMENT.version;
      // Hashed at ISSUE as well as at signature, so "the terms changed between
      // being sent and being signed" is answerable rather than a matter of
      // trust. The signature stores its own hash of what was on screen then.
      docSha256 = await sha256Hex(canonicalText(renderAgreement({
        templateId, templateVersion, parties, terms: full, issuedOn,
      })));
    }

    await c.env.DB.prepare(
      `INSERT INTO agreements
         (id, account_id, company_id, source, template_id, template_version,
          terms, parties, governing_state, status, doc_sha256, issued_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'sent', ?, ?)`
    ).bind(id, accountId, companyId, source, templateId, templateVersion,
      JSON.stringify(full), JSON.stringify(parties), governingState, docSha256, userId).run();

    await logEvent(c.env, accountId, userId, "agreement_issued", id,
      { companyId, source, templateVersion });

    const row = await c.env.DB.prepare(`SELECT * FROM agreements WHERE id = ?`).bind(id).first();
    return c.json({ ok: true, agreement: agreementToJs(row, { document: renderStored(row) }) });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

// The hiring account's own signature. A form signed by one side is not a
// contract, and the side that wrote the terms is the side with the most
// reason to be bound by them.
app.post("/api/agreements/:id/countersign", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { id } = c.req.param();
  const body = await c.req.json().catch(() => ({}));
  try {
    const row = await c.env.DB.prepare(
      `SELECT * FROM agreements WHERE id = ? AND account_id = ?`
    ).bind(id, accountId).first();
    if (!row) return c.json({ error: "not_found" }, 404);

    const gate = canSign(row, { asSub: false });
    if (!gate.ok) return c.json({ error: gate.reason }, 409);

    const me = await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`)
      .bind(userId).first();
    // A typed name is a signature when it is the signer's own act and the
    // record says who, when and from where. What makes it weak is a name typed
    // into a box with nothing tying it to a person, so it has to match theirs.
    if (!typedNameMatches(body.typedName, me?.name)) {
      return c.json({ error: "name_mismatch", expected: me?.name || null }, 400);
    }

    await c.env.DB.prepare(
      `UPDATE agreements SET status = 'countersigned', countersigned_at = CURRENT_TIMESTAMP,
         countersigned_by = ?, countersigned_by_name = ?, countersigned_by_email = ?,
         countersigned_ip = ?
       WHERE id = ? AND status = 'signed'`
    ).bind(userId, me?.name || null, me?.email || null,
      c.req.header("CF-Connecting-IP") || null, id).run();

    await logEvent(c.env, accountId, userId, "agreement_countersigned", id,
      { companyId: row.company_id });
    const after = await c.env.DB.prepare(`SELECT * FROM agreements WHERE id = ?`).bind(id).first();
    return c.json({ ok: true, agreement: agreementToJs(after, { document: renderStored(after) }) });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

// Withdraw it. Not a delete: an agreement somebody signed is a record of what
// they agreed to, and it stays readable after it stops being in force.
app.post("/api/agreements/:id/void", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const { id } = c.req.param();
  try {
    const row = await c.env.DB.prepare(
      `SELECT * FROM agreements WHERE id = ? AND account_id = ?`
    ).bind(id, accountId).first();
    if (!row) return c.json({ error: "not_found" }, 404);
    if (!isLive(row)) return c.json({ error: "already_answered" }, 409);
    await c.env.DB.prepare(
      `UPDATE agreements SET status = 'void', voided_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(id).run();
    await logEvent(c.env, accountId, userId, "agreement_voided", id, { companyId: row.company_id });
    return c.json({ ok: true });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

// ---- the subcontractor's side ---------------------------------------------

// EVERY CLIENT'S AGREEMENT, IN ONE LIST, for the reason /api/my-work exists:
// a subcontractor is on many rosters, and an agreement waiting to be signed on
// one of twenty-five of them is not something anybody finds by switching
// account twenty-five times.
//
// Scoped by `company_id = mine`, read off the seat and never the URL, so it
// cannot be widened into anybody else's.
app.get("/api/my-agreements", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT a.*, acc.name AS account_name
         FROM agreements a
         JOIN accounts acc ON acc.id = a.account_id
        WHERE a.company_id = ? AND a.status IN ('sent','signed','countersigned')
        ORDER BY a.issued_at DESC`
    ).bind(companyId).all();
    return c.json((results || []).map((r) => agreementToJs(r, {
      // WHO IS THIS FOR is the whole question when the answer is a different
      // company every row.
      accountName: r.account_name,
      document: renderStored(r),
    })));
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

app.post("/api/my-agreements/:id/sign", async (c) => {
  const { userId } = c.get("auth");
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  const { id } = c.req.param();
  const body = await c.req.json().catch(() => ({}));
  try {
    const row = await c.env.DB.prepare(
      `SELECT * FROM agreements WHERE id = ? AND company_id = ?`
    ).bind(id, companyId).first();
    if (!row) return c.json({ error: "not_found" }, 404);

    const gate = canSign(row, { asSub: true });
    if (!gate.ok) return c.json({ error: gate.reason }, 409);

    const me = await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`)
      .bind(userId).first();
    if (!typedNameMatches(body.typedName, me?.name)) {
      return c.json({ error: "name_mismatch", expected: me?.name || null }, 400);
    }

    // THE HASH IS TAKEN HERE, OF WHAT IS ON SCREEN NOW.
    //
    // Not carried over from issue, and never taken from the request: a caller
    // who could name the hash could sign one document and record another. It
    // is recomputed from the STORED parties and terms, which are the same
    // inputs the screen was rendered from, so what is hashed is what they
    // were shown.
    const rendered = renderAgreement({
      templateId: row.template_id,
      templateVersion: row.template_version,
      parties: parseJson(row.parties, {}),
      terms: parseJson(row.terms, {}),
      issuedOn: String(row.issued_at || "").slice(0, 10),
    });
    const hash = await sha256Hex(canonicalText(rendered));

    await c.env.DB.prepare(
      `UPDATE agreements SET status = 'signed', signed_at = CURRENT_TIMESTAMP,
         signed_by = ?, signed_by_name = ?, signed_by_email = ?, signed_ip = ?,
         doc_sha256 = ?
       WHERE id = ? AND status = 'sent'`
    ).bind(userId, me?.name || null, me?.email || null,
      c.req.header("CF-Connecting-IP") || null, hash, id).run();

    await logEvent(c.env, row.account_id, userId, "agreement_signed", id, { companyId });
    const after = await c.env.DB.prepare(`SELECT * FROM agreements WHERE id = ?`).bind(id).first();
    return c.json({ ok: true, agreement: agreementToJs(after, { document: renderStored(after) }) });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

app.post("/api/my-agreements/:id/decline", async (c) => {
  const { userId } = c.get("auth");
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  const { id } = c.req.param();
  const body = await c.req.json().catch(() => ({}));
  try {
    const row = await c.env.DB.prepare(
      `SELECT * FROM agreements WHERE id = ? AND company_id = ?`
    ).bind(id, companyId).first();
    if (!row) return c.json({ error: "not_found" }, 404);
    if (row.status !== "sent") return c.json({ error: "already_answered" }, 409);
    await c.env.DB.prepare(
      `UPDATE agreements SET status = 'declined', declined_at = CURRENT_TIMESTAMP,
         declined_note = ? WHERE id = ? AND status = 'sent'`
    ).bind(String(body.note || "").trim().slice(0, 1000) || null, id).run();
    await logEvent(c.env, row.account_id, userId, "agreement_declined", id, { companyId });
    return c.json({ ok: true });
  } catch (err) {
    if (missingSchema(err)) return c.json(agreementMigration(), 503);
    throw err;
  }
});

function shareToken() {
  const b = new Uint8Array(32);
  crypto.getRandomValues(b);
  return btoa(String.fromCharCode(...b)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

const shareToJs = (r) => ({
  id: r.id, toEmail: r.to_email, toName: r.to_name || null, note: r.note || null,
  createdAt: r.created_at, expiresAt: r.expires_at, revokedAt: r.revoked_at || null,
  viewCount: r.view_count || 0, lastViewedAt: r.last_viewed_at || null,
  state: shareState({ expiresAt: r.expires_at, revokedAt: r.revoked_at }),
});

// Send one.
app.post("/api/doc-shares", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  const { userId, accountId } = c.get("auth");

  // Per company, not per IP: this sends mail to an address somebody typed, and
  // the thing to stop is one account emailing a list.
  const rl = await rateLimit(c.env, "doc-share", companyId, { limit: 20, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const b = await c.req.json().catch(() => ({}));
  const toEmail = String(b.toEmail || "").trim().toLowerCase();
  if (!validRecipient(toEmail)) return c.json({ error: "invalid_email" }, 400);
  const toName = String(b.toName || "").trim().slice(0, 120) || null;
  const note = String(b.note || "").trim().slice(0, 500) || null;

  // Something has to be in it. A pack with nothing on file is a link to an
  // empty page, and sending one teaches the recipient this is not worth
  // opening next time.
  const rows = await currentDocRows(c.env.DB, companyId);
  const company = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(companyId).first();
  const docs = docShapeWithLegacy(rows, company);
  if (!PACK_KINDS.some((k) => docs[k])) return c.json({ error: "nothing_on_file" }, 409);

  // One live link per address. Sending again replaces the last one rather
  // than leaving two ways in, which is what somebody expects when they
  // re-send to a person who says they cannot find it.
  try {
    await c.env.DB.prepare(
      `UPDATE doc_shares SET revoked_at = CURRENT_TIMESTAMP
        WHERE company_id = ? AND to_email = ? AND revoked_at IS NULL`
    ).bind(companyId, toEmail).run();
  } catch (err) {
    const m = missingSchema(err);
    if (!m) throw err;
    return c.json({ error: "migration_needed", migration: m }, 503);
  }

  const id = uid();
  const token = shareToken();
  const expires = new Date(Date.now() + SHARE_DAYS * 86400000).toISOString().slice(0, 19).replace("T", " ");
  await c.env.DB.prepare(
    `INSERT INTO doc_shares (id, token, company_id, sent_by, to_email, to_name, note, expires_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(id, token, companyId, userId || null, toEmail, toName, note, expires).run();

  const link = `${APP_ORIGIN}/?pack=${encodeURIComponent(token)}`;
  const mail = docPackEmail({
    company: company?.company || "A subcontractor",
    contact: company?.contact || null,
    toName, note, link, days: SHARE_DAYS,
    kinds: PACK_KINDS.filter((k) => docs[k] && inLink(k)),
  });
  const sent = await sendEmail(c.env, { to: toEmail, ...mail });

  await logEvent(c.env, accountId, userId, "docs.shared", id, { toEmail });
  return c.json({ ...shareToJs({ id, to_email: toEmail, to_name: toName, note,
    created_at: new Date().toISOString(), expires_at: expires, view_count: 0 }),
    sent: !!sent?.ok }, 201);
});

// ---------------------------------------------------------------------------
// Who hires you.
//
// A connection has two ends and only one of them was ever drawn. Accepting a
// request writes an engagement on the OTHER account and seats this team over
// there -- so the hiring side gains a contractor on its roster, and this side
// gains nothing it can see. Every engagement read in this file is
// `account_id = mine`, which is "the contractors I hire"; nothing anywhere
// read `company_id = mine`, which is "the accounts that hire me".
//
// So a general contractor who said yes to a property manager on Tuesday could
// find them in the account switcher and nowhere else, and had no answer at all
// to "who do we work for".
//
// Nothing new crosses here. These are accounts that chose to engage this
// company, and this company's people already hold a seat in each of them --
// the relationship is mutual and already readable from the other side. What
// this adds is the sentence, not the access.
// ---------------------------------------------------------------------------
app.get("/api/clients", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json([]);
  let rows;
  try {
    ({ results: rows } = await c.env.DB.prepare(
      `SELECT en.id AS engagement_id, en.status, en.categories, en.invited_at,
              a.id, a.name, a.subdomain, a.kind,
              (SELECT COUNT(*) FROM work_orders wo
                 JOIN jobs j ON j.id = wo.job_id
                WHERE wo.company_id = en.company_id AND j.account_id = a.id
                  AND wo.voided_at IS NULL) AS work_orders
         FROM engagements en
         JOIN accounts a ON a.id = en.account_id
        WHERE en.company_id = ? AND en.status != 'ended'
        ORDER BY a.name`
    ).bind(companyId).all());
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json([]);
  }
  return c.json((rows || []).map((r) => ({
    id: r.id, name: r.name, subdomain: r.subdomain, kind: r.kind,
    engagementId: r.engagement_id, status: r.status,
    since: r.invited_at || null,
    // What they hired us FOR. Their categories on the engagement, which is
    // their decision about us rather than anything about their business.
    trades: parseJson(r.categories, []) || [],
    workOrders: r.work_orders || 0,
  })));
});

// Every job slot assigned to this company, across every account that engaged
// it. The other end of /api/clients: that says who hires us, this says what
// they want doing.
//
// Why it has to exist. /api/jobs is `WHERE j.account_id = ?`, and the portal's
// My Jobs and its amber badge are both derived from it -- so a subcontractor on
// twenty-five rosters answered "does anybody need me tomorrow" by switching
// account twenty-five times, and the badge only ever counted the account they
// happened to be standing in. Four jobs could sit waiting on a yes behind a
// clean nav. That is not a long menu, it is missed work, and the doc-share flow
// exists precisely to put a subcontractor on more rosters -- so the better the
// growth loop works the worse it gets.
//
// The shape is the one the tenant's own reports use, for the same reason: their
// own work, read-only, with the account that wants it NAMED, because "who is
// this for" is the whole question when the answer is a different company every
// row.
//
// Scoped by the work order, not by the job. `w.company_id = mine` is the only
// thing that selects a row, so this returns THEIR work and cannot be widened
// into the client's job list. Three things are deliberately absent:
//
//   - The other trades on the same job. A job can carry three work orders and
//     the other two name other companies on that account's roster. Telling a
//     roofer which electrician the GC uses is the accumulation this product
//     refuses everywhere else, and it is worth saying that /api/jobs does not
//     redact this today for a contractor seat -- that is a separate hole, not
//     one this route may copy.
//   - Anything about the account beyond its name and subdomain. The subdomain
//     is here because it is how you get there, not as a fact about them.
//   - The client, the sqft, the measurement docs, the tenant's report -- none
//     of which a list answering "where am I due" needs.
//
// Voided orders are gone and withdrawn jobs are out of everything live, so
// neither is here. Capped, because this is a list somebody scans.
// ---- Quotes: asking your own roster to price a job ----------------------
//
// A work order with status 'pending' is already a pre-award view: they see the
// job, the scope and the price, and accept or decline before anything is
// committed. What these routes add is the case where the account does NOT know
// the price yet and wants two or three of its own roofers to quote the same
// trade first. Work orders cannot say that: issuing one commits to a number,
// and issuing three for one trade collides on the live-WO index.
//
// Overflow's shape, pointed at the account's own roster. `shared/quotes.js`
// holds the rules; migration 043 holds the tables.
//
// The line that must not move: an invited company may never learn who else was
// asked, or what they quoted. Those are competing bids and one of them is the
// price this account is about to pay. It is the same rule overflow_invites
// follows, for a sharper reason.

const quoteToJs = (r) => ({
  id: r.id, requestId: r.request_id, companyId: r.company_id, status: r.status,
  priceCents: r.price_cents, canStart: r.can_start, note: r.note,
  invitedAt: r.invited_at, answeredAt: r.answered_at,
  company: r.company || null,
});
const requestToJs = (r) => ({
  id: r.id, jobId: r.job_id, accountId: r.account_id, trade: r.trade,
  scope: r.scope, dueAt: r.due_at, status: r.status,
  awardedCompanyId: r.awarded_company_id || null, awardedWoId: r.awarded_wo_id || null,
  createdAt: r.created_at, closedAt: r.closed_at,
});

// Ask. The invitees are checked against the caller's OWN engagements here, not
// trusted from the request -- a company id in the body is a claim, and the
// roster is the only thing that makes it true.
// SEVERAL TRADES IN ONE PRESS, and that is the shape somebody asking actually
// has. Reported as *"I requested a quote for 2 issues ... it sent one separate
// quote request for each one ... it should be together sent, but quoted
// individually for each item"*. A move-out with a scratched floor and a
// scuffed wall is one conversation with the same two or three contractors,
// and making the account open it twice made the contractor read it twice.
//
// IT STAYS ONE REQUEST PER TRADE UNDERNEATH, which is the half "quoted
// individually" is about. A request is what gets awarded, and the floor and
// the wall may go to different people at different prices -- so `items` makes
// several rows in one press, and the contractor's screen groups them back
// into one card. No new column: the job and the account already say which
// requests belong together.
//
// EACH COMPANY IS ASKED ONLY ABOUT WHAT IT COVERS. A painter ticked beside a
// flooring item is invited to the paint and not the floor -- the same
// `validInvitees` rule the single-trade path always ran, applied per item --
// and an item nobody picked can price is refused BY NAME before anything is
// written, so a press never sends half a question.
app.post("/api/jobs/:id/quote-requests", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId, role } = c.get("auth");
  const jobId = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const batch = Array.isArray(b.items);
  const raw = batch ? b.items : [{ trade: b.trade, scope: b.scope }];
  const items = [];
  for (const it of raw) {
    const trade = String(it?.trade || "").trim();
    if (!trade) return c.json({ error: "trade_required" }, 400);
    if (items.some((x) => x.trade === trade)) continue;
    items.push({ trade, scope: String(it?.scope || "").trim() || null });
  }
  if (!items.length) return c.json({ error: "trade_required" }, 400);

  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT * FROM jobs WHERE id = ? AND account_id = ?`).bind(jobId, accountId).first());
  if (!job) return c.json({ error: "not_found" }, 404);
  const onJob = parseJson(job.trades, []);
  const notOn = items.find((it) => !onJob.includes(it.trade));
  if (notOn) return c.json({ error: "not_a_trade_on_this_job", trade: notOn.trade }, 400);

  try {
    // The roster. Their engagement is what makes them askable; nothing here
    // searches or looks anybody up.
    const { results: roster } = await c.env.DB.prepare(
      `SELECT en.company_id AS id, en.status, en.categories
         FROM engagements en WHERE en.account_id = ? AND en.status != 'ended'`
    ).bind(accountId).all();
    const subs = (roster || []).map((r) => ({ id: r.id, status: r.status,
      categories: parseJson(r.categories, []) }));

    // EVERY ITEM IS CHECKED BEFORE ANY IS WRITTEN.
    for (const it of items) {
      const live = await c.env.DB.prepare(
        `SELECT 1 AS yes FROM work_orders
          WHERE job_id = ? AND trade = ? AND voided_at IS NULL LIMIT 1`).bind(jobId, it.trade).first();
      const open = await c.env.DB.prepare(
        `SELECT 1 AS yes FROM quote_requests
          WHERE job_id = ? AND trade = ? AND status = 'open' LIMIT 1`).bind(jobId, it.trade).first();
      const may = canRequestQuotes(
        { ...jobRowToJs(job, []), requestedBy: job.requested_by, approvedAt: job.approved_at,
          withdrawnAt: job.withdrawn_at },
        // 066. `today` so a hold whose date has passed does not refuse. The job
        // comes off hold by itself when that day arrives -- which is what
        // "defer until March" says -- and a route that ignored the date would
        // keep refusing work that is live again.
        { role, hasOpenRequest: !!open, liveWorkOrder: !!live, today: dayKeyUtc() });
      if (!may.ok) return c.json({ error: may.reason, trade: it.trade }, 409);
      const picked = validInvitees(b.companyIds || [], subs, it.trade);
      if (!picked.ok) return c.json({ error: picked.reason, trade: it.trade, max: MAX_INVITES }, 400);
      it.companyIds = picked.companyIds;
    }

    const made = [];
    for (const it of items) {
      const id = uid();
      await c.env.DB.prepare(
        `INSERT INTO quote_requests (id, account_id, job_id, trade, scope, due_at, created_by)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      ).bind(id, accountId, jobId, it.trade, it.scope, isoDay(b.dueAt), userId).run();
      for (const companyId of it.companyIds) {
        await c.env.DB.prepare(
          `INSERT INTO quote_invites (id, request_id, company_id) VALUES (?, ?, ?)`
        ).bind(uid(), id, companyId).run();
      }
      await logEvent(c.env, accountId, userId, "quotes.requested", id,
        { jobId, trade: it.trade, asked: it.companyIds.length });
      made.push({ id, trade: it.trade, asked: it.companyIds.length });
    }
    const people = new Set(items.flatMap((it) => it.companyIds)).size;
    await logActivity(c.env, accountId, userId, "quotes_requested",
      `Asked ${people} contractor${people === 1 ? "" : "s"} to price ${
        items.map((it) => tradeLabel(it.trade)).join(", ")} on "${job.title}"`);
    await touchJob(c.env, jobId);
    return batch
      ? c.json({ requests: made, asked: people }, 201)
      : c.json({ id: made[0].id, asked: made[0].asked }, 201);
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// What came back. The account picked these companies, so it sees who they are
// and what they said -- that is the comparison this exists for.
app.get("/api/jobs/:id/quote-requests", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const jobId = c.req.param("id");
  try {
    const { results: reqs } = await c.env.DB.prepare(
      `SELECT * FROM quote_requests WHERE job_id = ? AND account_id = ? ORDER BY created_at DESC`
    ).bind(jobId, accountId).all();
    if (!reqs?.length) return c.json([]);
    const marks = reqs.map(() => "?").join(",");
    const { results: invites } = await c.env.DB.prepare(
      `SELECT qi.*, co.company FROM quote_invites qi
         JOIN companies co ON co.id = qi.company_id
        WHERE qi.request_id IN (${marks})`
    ).bind(...reqs.map((r) => r.id)).all();
    const byReq = {};
    for (const i of invites || []) (byReq[i.request_id] ||= []).push(quoteToJs(i));
    return c.json(reqs.map((r) => {
      const list = rankQuotes(byReq[r.id] || []);
      return { ...requestToJs(r), invites: list, state: requestState(requestToJs(r), list) };
    }));
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json([]);
  }
});

// Ours to price. The redaction is the whole route: one job, at the shape
// quoteJobShape allows, and nothing about anybody else who was asked.
app.get("/api/my-quotes", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json([]);
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT qi.id AS invite_id, qi.status, qi.price_cents, qi.can_start, qi.note,
              qi.invited_at, qi.answered_at,
              qr.id AS request_id, qr.trade, qr.scope, qr.due_at, qr.status AS request_status,
              qr.awarded_company_id,
              j.id AS job_id, j.title, j.address, j.area, j.zip, j.date, j.time,
              j.severity, j.scope AS job_scope,
              a.id AS account_id, a.name AS account_name, a.subdomain AS account_subdomain
         FROM quote_invites qi
         JOIN quote_requests qr ON qr.id = qi.request_id
         JOIN jobs j ON j.id = qr.job_id
         JOIN accounts a ON a.id = qr.account_id
        WHERE qi.company_id = ? AND qi.status != 'withdrawn'
          AND j.withdrawn_at IS NULL
        ORDER BY qr.created_at DESC LIMIT 100`
    ).bind(companyId).all();
    return c.json((results || []).map((r) => ({
      inviteId: r.invite_id, requestId: r.request_id,
      status: r.status, requestStatus: r.request_status,
      // Did we get it? Yes or no about OURSELVES -- never who did instead.
      // "You were not picked" is theirs to know; who was picked, and for how
      // much, is the account's business and the winner's.
      wonIt: r.request_status === "awarded" && r.awarded_company_id === companyId,
      priceCents: r.price_cents, canStart: r.can_start, note: r.note,
      invitedAt: r.invited_at, answeredAt: r.answered_at, dueAt: r.due_at,
      trade: r.trade,
      accountId: r.account_id, accountName: r.account_name,
      accountSubdomain: r.account_subdomain,
      job: quoteJobShape({
        id: r.job_id, title: r.title, address: r.address, area: r.area, zip: r.zip,
        date: r.date, time: r.time, severity: r.severity, scope: r.job_scope,
      }, { trade: r.trade, scope: r.scope }),
    })));
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json([]);
  }
});

// Answering. Their own invite, found by its id and pinned to their company --
// an id from somewhere else answers 404, the same as one that is not a row.
app.post("/api/quotes/:inviteId", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: "no_company" }, 403);
  const b = await c.req.json().catch(() => ({}));
  try {
    const row = await c.env.DB.prepare(
      `SELECT qi.*, qr.status AS request_status, qr.id AS req_id, qr.account_id, qr.trade,
              j.title
         FROM quote_invites qi
         JOIN quote_requests qr ON qr.id = qi.request_id
         JOIN jobs j ON j.id = qr.job_id
        WHERE qi.id = ? AND qi.company_id = ?`
    ).bind(c.req.param("inviteId"), companyId).first();
    if (!row) return c.json({ error: "not_found" }, 404);

    const may = canQuote({ status: row.status }, { status: row.request_status });
    if (!may.ok) return c.json({ error: may.reason }, 409);

    // Passing carries no price, and saying so is worth as much to the account
    // as a number: three asked and two passed is an answer.
    if (b.pass) {
      await c.env.DB.prepare(
        `UPDATE quote_invites SET status = 'passed', price_cents = NULL,
           note = ?, answered_at = CURRENT_TIMESTAMP WHERE id = ?`
      ).bind((b.note || "").trim() || null, row.id).run();
      await logEvent(c.env, row.account_id, null, "quotes.passed", row.id,
        { requestId: row.req_id, companyId });
      return c.json({ ok: true, status: "passed" });
    }

    const q = validQuote(b);
    if (!q.ok) return c.json({ error: q.reason }, 400);
    await c.env.DB.prepare(
      `UPDATE quote_invites SET status = 'quoted', price_cents = ?, can_start = ?,
         note = ?, answered_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(q.priceCents, q.canStart, q.note, row.id).run();

    await logEvent(c.env, row.account_id, null, "quotes.quoted", row.id,
      { requestId: row.req_id, companyId });
    await logActivity(c.env, row.account_id, null, "quote_received",
      `A quote came in for ${row.trade} on "${row.title}"`);
    return c.json({ ok: true, status: "quoted", priceCents: q.priceCents });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// Awarding. This is the moment the pre-award view becomes a commitment, and
// the number on the work order is the one THEY gave -- which is the whole
// point of having asked.
app.post("/api/quote-requests/:id/award", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  try {
    const req = await c.env.DB.prepare(
      `SELECT * FROM quote_requests WHERE id = ? AND account_id = ?`
    ).bind(c.req.param("id"), accountId).first();
    if (!req) return c.json({ error: "not_found" }, 404);

    const invite = await c.env.DB.prepare(
      `SELECT * FROM quote_invites WHERE request_id = ? AND company_id = ?`
    ).bind(req.id, b.companyId || "").first();
    if (!invite) return c.json({ error: "not_found" }, 404);

    const may = canAward(requestToJs(req), quoteToJs(invite));
    if (!may.ok) return c.json({ error: may.reason }, 409);

    const engagement = await c.env.DB.prepare(
      `SELECT * FROM engagements WHERE account_id = ? AND company_id = ?`
    ).bind(accountId, invite.company_id).first();
    if (!engagement || engagement.status === "ended") return c.json({ error: "not_engaged" }, 409);

    // Nothing may be issued twice for one trade. Between asking and awarding
    // somebody may have assigned it by hand, and the index would refuse the
    // INSERT below with nothing on screen to explain it.
    const live = await c.env.DB.prepare(
      `SELECT 1 AS yes FROM work_orders
        WHERE job_id = ? AND trade = ? AND voided_at IS NULL LIMIT 1`
    ).bind(req.job_id, req.trade).first();
    if (live) return c.json({ error: "already_issued" }, 409);

    const job = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ?`).bind(req.job_id).first();
    const autoScheduled = !!engagement.auto_schedule;
    const woId = uid();
    const respondBy = autoScheduled ? null
      : new Date(Date.now() + windowMins("24h") * 60000).toISOString();
    const woNumber = await withWoNumber((n) => c.env.DB.prepare(
      `INSERT INTO work_orders
        (id, wo_number, job_id, trade, company_id, engagement_id, crew_name, trade_scope,
         value_cents, status, auto_scheduled, response_window, respond_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(woId, n, req.job_id, req.trade, invite.company_id, engagement.id, null,
      req.scope || job?.scope || "", invite.price_cents,
      autoScheduled ? "accepted" : "pending", autoScheduled ? 1 : 0,
      autoScheduled ? null : "24h", respondBy).run());

    await c.env.DB.prepare(
      `UPDATE quote_requests SET status = 'awarded', awarded_company_id = ?,
         awarded_wo_id = ?, closed_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(invite.company_id, woId, req.id).run();

    // 074. Awarding issues the work order, so it carries its link like any other.
    await ensureClaimLink(c.env, { woId, accountId, companyId: invite.company_id });
    await logEvent(c.env, accountId, userId, "quotes.awarded", req.id,
      { jobId: req.job_id, trade: req.trade, companyId: invite.company_id, woNumber });
    await logActivity(c.env, accountId, userId, "quote_awarded",
      `${woNumber} awarded for ${req.trade} on "${job?.title || "a job"}"`);
    await touchJob(c.env, req.job_id);
    const autoBooked = autoScheduled
      ? await autoBookOnIssue(c, { jobId: req.job_id, companyId: invite.company_id, accountId }) : null;
    return c.json({ ok: true, woId, woNumber, companyId: invite.company_id, autoBooked });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// Asked and thought better of it. The invites stay -- who was asked is a thing
// that happened -- and everyone still sees it as closed rather than it simply
// vanishing from their list with no explanation.
app.post("/api/quote-requests/:id/cancel", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  try {
    const res = await c.env.DB.prepare(
      `UPDATE quote_requests SET status = 'cancelled', closed_at = CURRENT_TIMESTAMP
        WHERE id = ? AND account_id = ? AND status = 'open'`
    ).bind(c.req.param("id"), accountId).run();
    if (!res.meta?.changes) return c.json({ error: "not_found" }, 404);
    await logEvent(c.env, accountId, userId, "quotes.cancelled", c.req.param("id"), {});
    return c.json({ ok: true });
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json({ error: "migration_needed", migration: "043_quotes" }, 503);
  }
});

app.get("/api/my-work", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ work: [] });
  const { accountId } = c.get("auth");
  let rows;
  // THE TWO NEWEST COLUMNS ARE OPTIONAL, and the reason is the catch below:
  // it answers an empty list for any missing column, and an empty contractor
  // portal over a roster of nine jobs is EXACTLY the report this route was
  // last changed to fix. So a database behind the code loses the access
  // answer and the contractor's own tick -- never the work itself. Same trade
  // the insert beside it makes, and `nu` is which half of the SELECT to draw.
  // `lv` is how much of the newest schema this attempt names:
  //   2  everything -- 060's access, 062's access_user_id, 061's contractor
  //      leg and 064's manager leg, which is what `turn` needs to be right.
  //   1  060 and 061 only, which is what this route carried before.
  //   0  neither, which is the shape /api/my-work has always answered on an
  //      older database rather than blanking the portal.
  const sql = (lv) => `SELECT w.id AS wo_id, w.wo_number, w.trade, w.status, w.auto_scheduled,
              w.response_window, w.respond_by, w.responded_at, w.crew_name,
              w.trade_scope, w.value_cents, w.pay_kind, w.rate_cents, w.cap_hours,
              w.issued_at, w.signed_file_key,
              j.id AS job_id, j.account_id, j.title, j.address, j.area, j.zip,
              j.date, j.time, j.severity, j.status AS job_status, j.completed_at,
              j.scope, j.updated_at, j.created_at, j.requested_by,
              ${lv >= 1 ? "j.access" : "NULL AS access"},
              ${lv >= 2 ? "j.access_user_id" : "NULL AS access_user_id"},
              a.name AS account_name, a.subdomain AS account_subdomain,
              -- The HIRER's kind, because what this company is to them follows
              -- it: a subcontract implies a prime contract, and a plumber
              -- engaged directly by a building's manager is under no such
              -- thing. See shared/hires.js.
              a.kind AS account_kind,
              p.name AS property_name,
              -- Who opens the door. The contractor is the one person who
              -- turns up, and nothing told them whether anybody would be
              -- there -- which is the same silence the appointment itself was
              -- in until this route started carrying it.
              rm.role AS requested_by_role,
              -- THE APPOINTMENT, which this route has never carried.
              --
              -- 019 built visits as a manager-to-tenant conversation: the
              -- manager proposes a window, the tenant confirms it because
              -- somebody has to be in. The one party who physically turns up
              -- was told nothing -- their card read "No date" over a job
              -- somebody had already proposed a Saturday morning for, and
              -- they were being asked to accept it.
              --
              -- Correlated rather than joined: the visits table has no
              -- unique index per job, and the list route beside it already
              -- relies on created_at DESC, rowid DESC to pick which row is
              -- current. A plain JOIN would multiply a work order by its
              -- job's whole visit history.
              --
              -- (No backticks in here. This is a template literal, and a
              -- backtick in a SQL comment closes it -- the tenth time this
              -- repository has paid for that one.)
              (SELECT v.id FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_id,
              (SELECT v.date FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_date,
              (SELECT v.start_time FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_start,
              (SELECT v.end_time FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_end,
              (SELECT v.status FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_status,
              (SELECT v.note FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_note,
              -- 061. Whether THIS side has answered it yet, which is what
              -- decides whether their card offers a Confirm button or says
              -- who else it is waiting on.
              ${lv >= 1 ? "(SELECT v.contractor_at FROM visits v WHERE v.job_id = j.id AND v.status IN ('proposed','confirmed') ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)" : "NULL"} AS visit_cat,
              -- 019's own column and 064's, because WHOSE TURN IT IS cannot be
              -- worked out from the contractor's leg alone. Without them this
              -- card could say "Confirm this time" on a window it is not this
              -- side's turn to answer -- which the route refuses -- and could
              -- not name who it is waiting on once they had.
              (SELECT v.responded_at FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_tat,
              ${lv >= 2 ? "(SELECT v.manager_at FROM visits v WHERE v.job_id = j.id AND v.status IN ('proposed','confirmed') ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)" : "NULL"} AS visit_mat,
              (SELECT v.proposed_by FROM visits v WHERE v.job_id = j.id
                 AND v.status IN ('proposed','confirmed')
                ORDER BY v.created_at DESC, v.rowid DESC LIMIT 1)      AS visit_by
         FROM work_orders w
         JOIN jobs j ON j.id = w.job_id
         JOIN accounts a ON a.id = j.account_id
         LEFT JOIN properties p ON p.id = j.property_id
         LEFT JOIN memberships rm ON rm.user_id = j.requested_by AND rm.account_id = j.account_id
        WHERE w.company_id = ? AND w.voided_at IS NULL AND j.withdrawn_at IS NULL
        ORDER BY COALESCE(j.updated_at, j.created_at) DESC
        LIMIT 200`;
  // Newest first, falling back a level at a time. Only the four scheduling
  // columns are optional: anything else missing is the older behaviour this
  // route has always had, because an empty portal over a roster of nine jobs
  // is exactly the report it was last changed to fix.
  const OPTIONAL = ["060_job_access", "061_visit_contractor",
    "062_job_access_user", "064_visit_manager"];
  let level = 2;
  for (;;) {
    try {
      ({ results: rows } = await c.env.DB.prepare(sql(level)).bind(companyId).all());
      break;
    } catch (err) {
      const m = missingSchema(err);
      if (!m) throw err;
      if (level === 0 || !OPTIONAL.includes(m)) return c.json({ work: [] });
      level -= 1;
    }
  }
  // 073. HOW THEY GET IN, on every job this company has said yes to. Only
  // accepted work: an offer nobody has taken is not owed a tenant's number.
  // Read straight off the job row, because half of this list is on other
  // accounts and the plan has to be the same whichever one it is.
  const plans = {};
  for (const r of rows || []) {
    if (r.status !== "accepted" || plans[r.job_id] !== undefined) continue;
    const job = await c.env.DB.prepare(`SELECT * FROM jobs WHERE id = ?`).bind(r.job_id).first()
      .catch(() => null);
    plans[r.job_id] = job ? await accessPlanFor(c.env, job, { viewer: "crew", companyId })
      .catch((err) => { console.warn("[my-work] access plan:", err?.message || err); return null; })
      : null;
  }
  return c.json({
    work: (rows || []).map((r) => ({
      woId: r.wo_id, wo: r.wo_number, jobId: r.job_id, trade: r.trade,
      accessPlan: plans[r.job_id] || null,
      // The account this is for. `here` is what lets the screen offer the
      // accept and decline buttons on the rows it can actually act on: this
      // list spans accounts and responding is an account-scoped write, so a
      // row belonging elsewhere is read-only and says where to go instead.
      accountId: r.account_id, accountName: r.account_name,
      accountSubdomain: r.account_subdomain, accountKind: r.account_kind || null,
      here: r.account_id === accountId,
      status: r.status, auto: !!r.auto_scheduled,
      responseWindow: r.response_window || null, respondBy: r.respond_by || null,
      respondedAt: r.responded_at || null,
      title: r.title, address: r.address || null, area: r.area || null, zip: r.zip || null,
      propertyName: r.property_name || null,
      date: r.date || null, time: r.time || null,
      // The live appointment, or null. `shared/schedule.js` decides which of
      // the two this row actually means -- a confirmed visit outranks the
      // job's own date, because the visit is what the tenant agreed to.
      // THE TENANT'S NOTE IS DELIBERATELY NOT HERE: why Tuesday does not work
      // for somebody's flat is theirs, and the contractor needs the window
      // rather than the reason. `note` is whoever PROPOSED it, which is the
      // manager telling the contractor something about the visit.
      // 060. Who lets them in, effective -- the raw column plus the rule, in
      // the one place that knows the reporter's seat role.
      access: accessFor(r, { tenantReported: r.requested_by_role === "tenant" }),
      visit: r.visit_id ? {
        id: r.visit_id, date: r.visit_date || null,
        startTime: r.visit_start || null, endTime: r.visit_end || null,
        status: r.visit_status, note: r.visit_note || null,
        contractorAt: r.visit_cat || null,
        // 064. WHOSE TURN IT IS, worked out here and not on the card.
        //
        // The card cannot do it: whether the tenant is a party at all depends
        // on the access answer AND on there being a seat to ask, and whether
        // the hiring side is one depends on a column existing. A screen
        // guessing would be a second opinion about whose answer is
        // outstanding, which is what `visitparty.js` exists to stop -- and
        // the cost of guessing wrong is a Confirm button the route refuses
        // with `not_your_turn`, pressed by somebody who was told to press it.
        //
        // `hasContractor` is an ACCEPTED work order, which is this row's own
        // status: somebody who has not said yes to the JOB cannot be waited
        // on for the TIME.
        ...(() => {
          const v = { date: r.visit_date, status: r.visit_status,
            respondedAt: r.visit_tat || null, contractorAt: r.visit_cat || null,
            managerAt: r.visit_mat || null };
          const vj = { requested_by: r.requested_by, access: r.access, access_user_id: r.access_user_id };
          const parties = windowParties(visitParties(vj,
            { tenantReported: r.requested_by_role === "tenant",
              hasContractor: r.status === "accepted" || !!r.auto_scheduled,
              hasManagerLeg: level >= 2 }), { byTenant: tenantProposed({ proposedBy: r.visit_by }, vj) });
          return { parties, turn: nextToAnswer(v, parties),
            waitingOn: visitWaitingOn(v, parties) };
        })(),
      } : null,
      severity: r.severity || null, jobStatus: r.job_status,
      completedAt: r.completed_at || null, tradeScope: r.trade_scope || null,
      crewName: r.crew_name || null,
      // What they are being paid, because it is their own work order.
      payKind: r.pay_kind || "fixed",
      value: r.value_cents != null ? String(r.value_cents / 100) : "",
      rate: r.rate_cents != null ? String(r.rate_cents / 100) : "",
      capHours: r.cap_hours != null ? r.cap_hours : null,
      signedWO: r.signed_file_key || null,
      issuedAt: r.issued_at || null,
      updatedAtIso: r.updated_at || r.created_at || null,
    })),
  });
});

// What they have sent, and whether anybody opened it. The view count is the
// reason to send it through here rather than as an attachment.
app.get("/api/doc-shares", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json([]);
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT * FROM doc_shares WHERE company_id = ? ORDER BY created_at DESC LIMIT 50`
    ).bind(companyId).all();
    return c.json((results || []).map(shareToJs));
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json([]);
  }
});

// Taking it back. Theirs to withdraw at any point, which is most of what
// makes sending it safe in the first place.
app.post("/api/doc-shares/:id/revoke", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: "forbidden" }, 403);
  const r = await c.env.DB.prepare(
    `UPDATE doc_shares SET revoked_at = CURRENT_TIMESTAMP
      WHERE id = ? AND company_id = ? AND revoked_at IS NULL`
  ).bind(c.req.param("id"), companyId).run();
  if (!r?.meta?.changes) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true });
});

// ---- the public page ------------------------------------------------------
// No account, no session. Everything it can reach is pinned to the one share
// row the token names, exactly as /api/logo/:accountId is pinned to one key.

async function shareByToken(env, token) {
  const row = await env.DB.prepare(
    `SELECT s.*, co.company, co.contact, co.city, co.state, co.license, co.license_check
       FROM doc_shares s JOIN companies co ON co.id = s.company_id
      WHERE s.token = ?`
  ).bind(String(token || "")).first();
  if (!row) return null;
  return row;
}

app.get("/api/pack/:token", async (c) => {
  // A token is a guess-resistant secret, but the endpoint is still open, so
  // it gets the same floor every other public route has.
  const rl = await rateLimit(c.env, "pack-view", clientIp(c), { limit: 120, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  let row;
  try {
    row = await shareByToken(c.env, c.req.param("token"));
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.json({ error: "not_found" }, 404);
  }
  // One answer for every way a link can be no good EXCEPT the two the holder
  // needs to tell apart. Not found stays vague on purpose: it is the only
  // reply a guessed token can get.
  if (!row) return c.json({ error: "not_found" }, 404);
  const state = shareState({ expiresAt: row.expires_at, revokedAt: row.revoked_at });
  if (state !== "active") return c.json({ error: state, company: row.company }, 410);

  const rows = await currentDocRows(c.env.DB, row.company_id);
  const company = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`)
    .bind(row.company_id).first();
  const docs = docShapeWithLegacy(rows, company);

  // Counted here rather than on the file fetch: opening the page is the event
  // the sender cares about, and a page with three documents on it must not
  // read as three opens.
  await c.env.DB.prepare(
    `UPDATE doc_shares SET view_count = view_count + 1, last_viewed_at = CURRENT_TIMESTAMP
      WHERE id = ?`).bind(row.id).run().catch(() => {});

  const lic = parseJson(row.license_check, null);
  return c.json({
    company: row.company,
    contact: row.contact || null,
    where: [row.city, row.state].filter(Boolean).join(", ") || null,
    license: row.license || null,
    // Verified against the state registry, with the date -- the one thing on
    // here that an emailed PDF genuinely cannot carry.
    licenseVerified: licenseActive(lic),
    licenseCheckedAt: lic?.checkedAt || null,
    sentTo: row.to_name || null,
    note: row.note || null,
    expiresAt: row.expires_at,
    docs: PACK_KINDS.map((k) => ({ ...packRow({ ...(docs[k] || {}), kind: k }),
      id: rows[k]?.id || null })),
  });
});

// One file out of one pack. Pinned three ways: the token names the share, the
// share names the company, and the document id must be a current row of THAT
// company of a kind the link is allowed to carry. An id from another company
// -- or the W-9 from this one -- gets the same nothing.
// ---------------------------------------------------------------------------
// The inbox: every pack one person has been sent, on one page.
//
// This is the demand side of the growth loop and the only half that pulls. The
// subcontractors do the data entry; the recipient accumulates a roster they did
// not build; claiming it lands them in an account already populated. That is
// the cold-start problem solved by the people who wanted to be on it.
//
// `shared/inbox.js` holds the rules; migration 045 holds the table.

// "Show me everything sent to me." Asked from a pack page, answered by email.
//
// A share token proves somebody holds one link that was emailed to an address.
// It does NOT prove they control that address now -- certificates get
// forwarded, which is most of what they are for. Without a second email a
// forwarded link would open every pack ever sent to the forwarder.
//
// So: the request names no address. It is read off the share, and the link
// goes there. An endpoint that took an address would mail anybody's inbox to
// anybody.
app.post("/api/pack/:token/inbox", async (c) => {
  try {
    const share = await c.env.DB.prepare(
      `SELECT to_email, to_name FROM doc_shares
        WHERE token = ? AND revoked_at IS NULL`
    ).bind(c.req.param("token")).first();
    // Same answer either way, so this cannot be used to test a token.
    if (!share) return c.json({ ok: true, sent: false });

    const rl = await rateLimit(c.env, "inbox-ask", share.to_email,
      { limit: INBOX_ASKS_PER_HOUR, windowMinutes: 60 });
    if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

    // One live link per address: asking again replaces rather than leaving two
    // keys to the same inbox loose.
    await c.env.DB.prepare(
      `UPDATE doc_inboxes SET revoked_at = CURRENT_TIMESTAMP
        WHERE to_email = ? AND revoked_at IS NULL AND claimed_at IS NULL`
    ).bind(share.to_email).run();

    const token = shareToken();
    const expires = new Date(Date.now() + INBOX_DAYS * 86400000)
      .toISOString().slice(0, 19).replace("T", " ");
    await c.env.DB.prepare(
      `INSERT INTO doc_inboxes (id, token, to_email, expires_at) VALUES (?, ?, ?, ?)`
    ).bind(uid(), token, share.to_email, expires).run();

    const { results: mine } = await c.env.DB.prepare(
      `SELECT COUNT(DISTINCT company_id) AS n FROM doc_shares
        WHERE to_email = ? AND revoked_at IS NULL`
    ).bind(share.to_email).all();
    const mail = docInboxEmail({
      toName: share.to_name, count: mine?.[0]?.n || 0, days: INBOX_DAYS,
      link: `${APP_ORIGIN}/?inbox=${encodeURIComponent(token)}`,
    });
    const res = await sendEmail(c.env, { to: share.to_email, ...mail });
    await logMail(c.env, { accountId: null, companyId: null, to: share.to_email,
      kind: "doc_inbox", subject: mail.subject, result: res, sentBy: null });
    // Never says WHICH address it went to. The person who asked knows; anybody
    // holding a forwarded token learns nothing.
    return c.json({ ok: true, sent: !!res?.ok });
  } catch (err) {
    if (missingSchema(err)) return c.json({ ok: true, sent: false, skipped: "not_migrated" });
    throw err;
  }
});

// The inbox itself. Public, because a page that needs an account is not a page
// somebody with no account will read -- and the token is the whole of the auth.
app.get("/api/inbox/:token", async (c) => {
  try {
    const box = await c.env.DB.prepare(
      `SELECT * FROM doc_inboxes WHERE token = ?`).bind(c.req.param("token")).first();
    const state = inboxState({ token: box?.token, revokedAt: box?.revoked_at,
      claimedAt: box?.claimed_at, expiresAt: box?.expires_at });
    if (state !== "active") return c.json({ error: state === "unknown" ? "not_found" : state }, 404);

    await c.env.DB.prepare(`UPDATE doc_inboxes SET last_used_at = CURRENT_TIMESTAMP WHERE id = ?`)
      .bind(box.id).run();

    // The most recent live share per company. A second send replaced the
    // first, so this is one row per subcontractor, not one per send.
    const { results: shares } = await c.env.DB.prepare(
      `SELECT ds.token, ds.company_id, ds.created_at, ds.expires_at,
              co.company, co.contact, co.city, co.state
         FROM doc_shares ds
         JOIN companies co ON co.id = ds.company_id
        WHERE ds.to_email = ? AND ds.revoked_at IS NULL
          AND ds.created_at = (SELECT MAX(d2.created_at) FROM doc_shares d2
                                WHERE d2.company_id = ds.company_id AND d2.to_email = ds.to_email
                                  AND d2.revoked_at IS NULL)
        ORDER BY ds.created_at DESC LIMIT 100`
    ).bind(box.to_email).all();

    const rows = [];
    for (const sh of shares || []) {
      const co = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`)
        .bind(sh.company_id).first();
      const docs = docShapeWithLegacy(await currentDocRows(c.env.DB, sh.company_id), co);
      rows.push(inboxRow({
        token: sh.token, company: sh.company, contact: sh.contact,
        where: [sh.city, sh.state].filter(Boolean).join(", ") || null,
        createdAt: sh.created_at, expiresAt: sh.expires_at,
      }, PACK_KINDS.map((k) => ({ ...packRow({ ...(docs[k] || {}), kind: k }) }))));
    }

    const today = new Date().toISOString().slice(0, 10);
    const ranked = rankInbox(rows, today);
    return c.json({ rows: ranked, summary: inboxSummary(ranked, today),
      expiresAt: box.expires_at });
  } catch (err) {
    if (missingSchema(err)) return c.json({ error: "not_found" }, 404);
    throw err;
  }
});

// Turning it into an account's roster.
//
// The subcontractors chose to send this person their paperwork, which is
// consent to a working relationship being recorded -- so these engagements are
// not the accumulation this product refuses. They arrive as 'invited', the same
// status as a company somebody typed in themselves: a document share is
// agreement to be hireable by this person, not agreement to have been hired.
app.post("/api/inbox/:token/claim", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  try {
    const box = await c.env.DB.prepare(
      `SELECT * FROM doc_inboxes WHERE token = ?`).bind(c.req.param("token")).first();
    const state = inboxState({ token: box?.token, revokedAt: box?.revoked_at,
      claimedAt: box?.claimed_at, expiresAt: box?.expires_at });
    if (state !== "active") return c.json({ error: state === "unknown" ? "not_found" : state }, 404);

    const { results: companies } = await c.env.DB.prepare(
      `SELECT DISTINCT company_id FROM doc_shares
        WHERE to_email = ? AND revoked_at IS NULL`
    ).bind(box.to_email).all();

    let added = 0;
    for (const row of companies || []) {
      try {
        await c.env.DB.prepare(
          `INSERT INTO engagements (id, account_id, company_id, status, notes)
           VALUES (?, ?, ?, 'invited', ?)`
        ).bind(uid(), accountId, row.company_id,
          "Sent you their documents before you had an account.").run();
        added += 1;
      } catch (err) {
        // Already on the roster. Claiming twice is the same outcome.
        if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
      }
    }

    await c.env.DB.prepare(
      `UPDATE doc_inboxes SET claimed_at = CURRENT_TIMESTAMP, claimed_account_id = ? WHERE id = ?`
    ).bind(accountId, box.id).run();
    await logEvent(c.env, accountId, userId, "inbox.claimed", box.id, { added });
    await logActivity(c.env, accountId, userId, "inbox_claimed",
      `Added ${added} contractor${added === 1 ? "" : "s"} who had already sent their documents`);
    return c.json({ ok: true, added });
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }
});

// "Stop telling me when this renews."
//
// Keyed by the SHARE TOKEN, which the recipient already holds and which
// already proves they are the person that link was made for. A dedicated
// unsubscribe token would be a second secret to mint, store and leak; an
// endpoint taking an email address would let anybody unsubscribe anybody.
//
// Public, because the whole point of the pack page is that reading it needs no
// account -- and an opt-out somebody has to sign up for is not an opt-out.
app.post("/api/pack/:token/stop", async (c) => {
  try {
    const share = await c.env.DB.prepare(
      `SELECT company_id, to_email FROM doc_shares WHERE token = ?`
    ).bind(c.req.param("token")).first();
    // Deliberately not distinguishing a bad token from a good one: this
    // answers ok either way, so it cannot be used to test whether a token is
    // real. There is nothing to gain by being precise here.
    if (share) {
      const b = await c.req.json().catch(() => ({}));
      // Everybody, or just this subcontractor. Saying stop about one is not
      // saying it about the others, so the narrow one is the default.
      const companyId = b.all ? null : share.company_id;
      try {
        await c.env.DB.prepare(
          `INSERT INTO doc_share_optouts (id, to_email, company_id) VALUES (?, ?, ?)`
        ).bind(uid(), share.to_email, companyId).run();
      } catch (err) {
        // Already said. Saying it twice is the same answer.
        if (!/UNIQUE constraint failed/i.test(String(err?.message || err))) throw err;
      }
    }
    return c.json({ ok: true });
  } catch (err) {
    if (missingSchema(err)) return c.json({ ok: true, skipped: "not_migrated" });
    throw err;
  }
});

app.get("/api/pack/:token/file/:docId", async (c) => {
  const rl = await rateLimit(c.env, "pack-file", clientIp(c), { limit: 240, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  let row;
  try {
    row = await shareByToken(c.env, c.req.param("token"));
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return c.notFound();
  }
  if (!row) return c.notFound();
  if (shareState({ expiresAt: row.expires_at, revokedAt: row.revoked_at }) !== "active") {
    return c.notFound();
  }

  const doc = await c.env.DB.prepare(
    `SELECT * FROM company_docs
      WHERE id = ? AND company_id = ? AND superseded_at IS NULL`
  ).bind(c.req.param("docId"), row.company_id).first();
  if (!doc || !doc.file_key) return c.notFound();
  // The rule that keeps a taxpayer number out of an emailed link.
  if (!inLink(doc.kind)) return c.notFound();

  const obj = await c.env.FILES.get(doc.file_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": obj.httpMetadata?.contentType || "application/octet-stream",
      "Content-Disposition": `inline; filename="${(doc.file_name || "document").replace(/[^\w.\-]/g, "_")}"`,
      // Never a shared cache: this is one person's certificate behind one
      // token, and an intermediary holding a copy outlives the revocation.
      "Cache-Control": "private, no-store",
    },
  });
});

// File uploads. R2Bucket has no createPresignedUrl() — that's an S3-style
// presigned URL, which on R2 needs the S3-compatible API signed with an R2
// API token (Account ID + Access Key + Secret), not the Workers binding.
// Simpler and sufficient for compliance-doc-sized files: stream the upload
// straight through the Worker into R2 with the binding's own put(). If
// upload volume ever justifies it, swap this for real presigned URLs via
// aws4fetch + an R2 API token to take the Worker out of the data path.
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Milestones, verification and release.
//
// The two-party rule is the whole point and it is enforced three ways,
// because one way is a way somebody removes by accident: the subcontractor's
// seat is the only one that may REACH, an admin or project manager is the
// only one that may VERIFY, and the person who reached is refused on verify
// even when they hold both seats. That last one is not paranoia -- a general
// contractor who is also somebody's subcontractor has both, and 031 made
// that the ordinary case rather than a curiosity.
//
// Every state change writes an append-only event. Status on the milestone is
// a convenience for reading; wo_events is the record.
// ---------------------------------------------------------------------------

// One work order, with who is allowed to touch it already decided.
async function loadWorkOrder(c, id) {
  const { accountId, role, companyId } = c.get("auth");
  const wo = await c.env.DB.prepare(
    `SELECT wo.*, j.account_id, j.property_id FROM work_orders wo
       JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ?`
  ).bind(id).first();
  if (!wo || wo.account_id !== accountId) return { error: c.json({ error: "not_found" }, 404) };
  // A contractor sees their own and nobody else's. Checked here rather than
  // in each route, because the route that forgets is the one that matters.
  if (role === "contractor" && wo.company_id !== companyId) {
    return { error: c.json({ error: "forbidden" }, 403) };
  }
  return { wo };
}

// 066. NOTHING IS PAYABLE AGAINST A JOB THAT WAS CANCELLED, OR CLOSED OUT
// WITH NOTHING DONE.
//
// This is the half of "complete, no work done" that would otherwise be a
// word on a screen. `no_work` writes `status = 'completed'` so every existing
// reader answers correctly for it -- and *completed* is precisely the state a
// release is normally paid against, so without this it would be the most
// payable a job ever gets. A transfer out against work nobody did is the one
// mistake in this codebase that cannot be undone with a word.
//
// IN ONE PLACE, read by settle AND pay, because those are two routes on
// purpose -- one records money that moved elsewhere, one moves it -- and a
// gate on one of the two is a door round it. Both already call
// `loadWorkOrder`, so this reads what it hands back plus the ending.
//
// A database without 066 has no endings and answers null, which is the
// behaviour both routes had before this. Narrow catch, because a catch wide
// enough to hide a real error would hide it in front of money.
// WIDENING `loadWorkOrder`'S SELECT WAS THE FIRST VERSION AND IT BROKE A
// SUITE IMMEDIATELY. `milestone-test.mjs` builds its own schema by hand --
// *"if a route reaches for a column that is not here, that is worth
// knowing"* -- and three aliases added here for columns nothing reads duly
// reported themselves. Worth more than the convenience: on a database without
// 020 or 021 that SELECT throws, and `loadWorkOrder` is in the path of every
// money route. `work_orders.job_id` is already on the row, so nothing needed
// widening at all.
async function jobEndingBlocksPay(c, wo) {
  const row = await jobWithEnding(c.env, { id: wo?.job_id });
  const kind = row?.ending_kind || null;
  if (kind === "cancelled") return { error: "job_cancelled", note: row.ending_note || null };
  if (kind === "no_work") return { error: "job_no_work", note: row.ending_note || null };
  return null;
}

// The append-only record. Everything that changes a milestone or a release
// goes through here and nothing updates what it wrote.
async function woEvent(c, { workOrderId, milestoneId = null, kind, payload = {}, idemKey = null }) {
  const { accountId, userId, role, companyId } = c.get("auth");
  try {
    await c.env.DB.prepare(
      `INSERT INTO wo_events (id, work_order_id, account_id, milestone_id, kind,
         actor_user_id, actor_role, actor_company_id, payload, idem_key)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(uid(), workOrderId, accountId, milestoneId, kind,
      userId || null, role || null, companyId || null, JSON.stringify(payload), idemKey).run();
    return { written: true };
  } catch (err) {
    // A repeat of a write that already happened is not a failure. Anything
    // else is.
    if (/UNIQUE constraint failed: wo_events\.idem_key/i.test(String(err?.message || err))) {
      return { written: false, duplicate: true };
    }
    throw err;
  }
}

const milestoneToJs = (m) => ({
  id: m.id, seq: m.seq, label: m.label, amountCents: m.amount_cents,
  status: m.status,
  reachedAt: m.reached_at || null, reachedBy: m.reached_by || null,
  verifiedAt: m.verified_at || null, verifiedBy: m.verified_by || null,
  note: m.note || null,
});

// What the work order is broken into, what has happened to it, and what is
// owed. One call, because a screen that needs three is a screen that renders
// three different moments.
app.get("/api/work-orders/:id/plan", async (c) => {
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const [ms, evs, rel] = await Promise.all([
    c.env.DB.prepare(`SELECT * FROM wo_milestones WHERE work_order_id = ? ORDER BY seq`).bind(wo.id).all(),
    c.env.DB.prepare(`SELECT * FROM wo_events WHERE work_order_id = ? ORDER BY at, rowid`).bind(wo.id).all(),
    c.env.DB.prepare(`SELECT * FROM wo_releases WHERE work_order_id = ? ORDER BY created_at, rowid`).bind(wo.id).all(),
  ]).catch((err) => { throw err; });
  return c.json({
    workOrderId: wo.id,
    valueCents: wo.value_cents,
    scopeKind: wo.scope_kind || "labor_materials",
    retainageBps: wo.retainage_bps || 0,
    milestones: (ms.results || []).map(milestoneToJs),
    events: (evs.results || []).map((e) => ({
      id: e.id, kind: e.kind, at: e.at, milestoneId: e.milestone_id || null,
      actorUserId: e.actor_user_id || null, actorRole: e.actor_role || null,
      payload: parseJson(e.payload, {}),
    })),
    releases: (rel.results || []).map((r) => ({
      // The work order it belongs to, so a caller holding one release does not
      // need a second prop to ask about the money behind it.
      id: r.id, workOrderId: r.work_order_id, milestoneId: r.milestone_id || null, grossCents: r.gross_cents,
      retainageCents: r.retainage_cents, feeBps: r.fee_bps, feeCents: r.fee_cents,
      netCents: r.net_cents, status: r.status, method: r.method || null,
      reference: r.reference || null, settledAt: r.settled_at || null,
      createdAt: r.created_at,
    })),
  });
});

// Set the plan. Replaces it wholesale rather than patching: a milestone list
// that half-changed is a list whose amounts no longer sum to anything.
//
// Refused once anything has been verified. Re-cutting the parts of a job
// after money has been released against one of them is a change order, which
// is a different mechanism with a different paper trail.
app.put("/api/work-orders/:id/plan", requireRole("admin", "pm"), async (c) => {
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const b = await c.req.json().catch(() => ({}));

  const settled = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM wo_milestones WHERE work_order_id = ? AND status = 'verified'`
  ).bind(wo.id).first();
  if (settled?.n) return c.json({ error: "already_verified", verified: settled.n }, 409);

  const rows = Array.isArray(b.milestones) ? b.milestones : [];
  if (!rows.length) return c.json({ error: "no_milestones" }, 400);
  if (rows.length > 40) return c.json({ error: "too_many" }, 400);
  const clean = rows.map((m, i) => ({
    seq: i + 1,
    label: String(m.label || "").trim().slice(0, 120) || `Part ${i + 1}`,
    amountCents: Math.round(Number(m.amountCents) || 0),
  }));
  if (clean.some((m) => m.amountCents < 0)) return c.json({ error: "negative_amount" }, 400);

  // The invariant that keeps a work order honest: the parts sum to the
  // whole. Without it a work order can be fully verified having released
  // less than its value, and the gap is invisible rather than wrong.
  const cover = milestonesCover(clean, wo.value_cents);
  if (!cover.ok) return c.json({ error: "does_not_cover", ...cover }, 400);

  await c.env.DB.prepare(`DELETE FROM wo_milestones WHERE work_order_id = ?`).bind(wo.id).run();
  for (const m of clean) {
    await c.env.DB.prepare(
      `INSERT INTO wo_milestones (id, work_order_id, account_id, seq, label, amount_cents)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(uid(), wo.id, wo.account_id, m.seq, m.label, m.amountCents).run();
  }
  await woEvent(c, { workOrderId: wo.id, kind: "plan.set",
    payload: { milestones: clean, valueCents: wo.value_cents } });
  return c.json({ ok: true, milestones: clean.length });
});

// Labour or materials, and how much is held back. Both change what a waiver
// has to say and what a release is worth, so both are refused once anything
// is verified.
app.patch("/api/work-orders/:id/scope", requireRole("admin", "pm"), async (c) => {
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const b = await c.req.json().catch(() => ({}));
  const verified = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM wo_milestones WHERE work_order_id = ? AND status = 'verified'`
  ).bind(wo.id).first();
  if (verified?.n) return c.json({ error: "already_verified" }, 409);

  const sets = [], vals = [];
  if (b.scopeKind !== undefined) {
    if (!SCOPE_KINDS.includes(b.scopeKind)) return c.json({ error: "bad_scope" }, 400);
    sets.push("scope_kind = ?"); vals.push(b.scopeKind);
  }
  if (b.retainageBps !== undefined) {
    const bps = Math.round(Number(b.retainageBps) || 0);
    // A hold larger than half the job is not retainage, it is a typo.
    if (bps < 0 || bps > 5000) return c.json({ error: "bad_retainage" }, 400);
    sets.push("retainage_bps = ?"); vals.push(bps);
  }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);
  await c.env.DB.prepare(`UPDATE work_orders SET ${sets.join(", ")} WHERE id = ?`)
    .bind(...vals, wo.id).run();
  await woEvent(c, { workOrderId: wo.id, kind: "scope.set",
    payload: { scopeKind: b.scopeKind, retainageBps: b.retainageBps } });
  return c.json({ ok: true });
});

// The subcontractor says a part is done.
//
// Only their seat. An admin cannot reach on their behalf, because a record
// where the paying party wrote both halves is worth nothing to anybody
// looking at it later.
app.post("/api/milestones/:id/reach", async (c) => {
  const { role, companyId, userId } = c.get("auth");
  const m = await c.env.DB.prepare(`SELECT * FROM wo_milestones WHERE id = ?`)
    .bind(c.req.param("id")).first();
  if (!m) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, m.work_order_id);
  if (error) return error;
  if (role !== "contractor" || wo.company_id !== companyId) {
    return c.json({ error: "not_yours_to_mark" }, 403);
  }
  if (m.status === "verified") return c.json({ error: "already_verified" }, 409);

  const b = await c.req.json().catch(() => ({}));
  const photos = Array.isArray(b.photos) ? b.photos.slice(0, 12) : [];
  const note = String(b.note || "").trim().slice(0, 2000) || null;

  await c.env.DB.prepare(
    `UPDATE wo_milestones SET status = 'reached', reached_at = CURRENT_TIMESTAMP,
       reached_by = ?, note = COALESCE(?, note) WHERE id = ?`
  ).bind(userId, note, m.id).run();
  // Photos are nudged, never required -- requiring them is how you collect
  // four pictures of a van dashboard.
  await woEvent(c, { workOrderId: wo.id, milestoneId: m.id, kind: "milestone.reached",
    payload: { photos, note, hadPhotos: photos.length > 0 }, idemKey: b.idemKey || null });
  return c.json({ ok: true, photos: photos.length });
});

// The account's fee terms -- its own where staff set them, the defaults where
// not. A database without 071 is on the defaults, which is exactly what every
// account was on before 071 existed, so a missing table costs nothing.
async function accountFeeTerms(env, accountId) {
  try {
    const row = await env.DB.prepare(`SELECT * FROM account_fee_terms WHERE account_id = ?`)
      .bind(accountId).first();
    return { ...feeTerms(row), custom: !!row, row: row || null };
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return { ...DEFAULT_FEE_TERMS, custom: false, row: null, migration: "071_fee_terms" };
  }
}

// What this account has sent through SubSub: releases PAID by `stripe`, which
// is what the free $50,000 is counted against. A check recorded here is not
// in it -- nothing went through us. `includeDue` adds releases still owed, for
// the estimate stamped at verify, so two releases verified back to back do not
// both claim the same free dollars.
async function processedCents(env, accountId, { includeDue = false, excludeReleaseId = null } = {}) {
  const r = await env.DB.prepare(
    `SELECT COALESCE(SUM(gross_cents), 0) AS n FROM wo_releases
      WHERE account_id = ? AND id <> COALESCE(?, '')
        AND ((status = 'paid' AND method = 'stripe')${includeDue ? " OR status = 'due'" : ""})`
  ).bind(accountId, excludeReleaseId).first();
  return Number(r?.n) || 0;
}

// And the hiring account agrees, which is what makes anything owed.
app.post("/api/milestones/:id/verify", requireRole("admin", "pm"), async (c) => {
  const { userId } = c.get("auth");
  const m = await c.env.DB.prepare(`SELECT * FROM wo_milestones WHERE id = ?`)
    .bind(c.req.param("id")).first();
  if (!m) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, m.work_order_id);
  if (error) return error;
  if (m.status === "verified") return c.json({ error: "already_verified" }, 409);
  if (m.status !== "reached") return c.json({ error: "not_reached" }, 409);
  // The third guard. An account that is also somebody's subcontractor holds
  // both seats, and 031 made that ordinary rather than exotic.
  if (m.reached_by && m.reached_by === userId) {
    return c.json({ error: "same_person", detail: "whoever marked this cannot verify it" }, 409);
  }

  const prior = await c.env.DB.prepare(
    `SELECT COALESCE(SUM(gross_cents), 0) AS gross FROM wo_releases
      WHERE work_order_id = ? AND status <> 'void'`
  ).bind(wo.id).first();

  // SubSub's fee, stamped now so the account sees it before it funds or pays:
  // the account's own terms, and only on the part of this payment past the
  // free allowance still left. An ESTIMATE -- `/pay` works it out again from
  // what has actually been processed by then, which is the figure charged.
  const terms = await accountFeeTerms(c.env, wo.account_id);
  const fee = feeFor({ gross: m.amount_cents, terms,
    processedBefore: await processedCents(c.env, wo.account_id, { includeDue: true }) }).fee;
  const amounts = { ...releaseAmounts({
    gross: m.amount_cents,
    priorGross: prior?.gross || 0,
    retainageBps: wo.retainage_bps || 0,
  }), fee };

  await c.env.DB.prepare(
    `UPDATE wo_milestones SET status = 'verified', verified_at = CURRENT_TIMESTAMP,
       verified_by = ? WHERE id = ?`
  ).bind(userId, m.id).run();

  const releaseId = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO wo_releases (id, work_order_id, account_id, milestone_id, company_id,
         gross_cents, retainage_cents, fee_bps, fee_cents, net_cents, idem_key)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(releaseId, wo.id, wo.account_id, m.id, wo.company_id,
      amounts.gross, amounts.retainage, terms.bps, amounts.fee, amounts.net,
      `rel:${m.id}`).run();
  } catch (err) {
    // The unique index on milestone_id doing its job. Verifying twice is a
    // double-click, not a second release.
    if (/UNIQUE constraint failed/i.test(String(err?.message || err))) {
      return c.json({ error: "already_released" }, 409);
    }
    throw err;
  }

  await woEvent(c, { workOrderId: wo.id, milestoneId: m.id, kind: "milestone.verified",
    payload: { releaseId, ...amounts, feeBps: terms.bps } });
  return c.json({ ok: true, releaseId, ...amounts });
});

// Turning one down. The reason travels, because a rejection nobody can read
// is a rejection somebody has to telephone about.
app.post("/api/milestones/:id/reject", requireRole("admin", "pm"), async (c) => {
  const m = await c.env.DB.prepare(`SELECT * FROM wo_milestones WHERE id = ?`)
    .bind(c.req.param("id")).first();
  if (!m) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, m.work_order_id);
  if (error) return error;
  if (m.status === "verified") return c.json({ error: "already_verified" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const why = String(b.reason || "").trim().slice(0, 1000);
  if (!why) return c.json({ error: "reason_required" }, 400);

  await c.env.DB.prepare(`UPDATE wo_milestones SET status = 'rejected' WHERE id = ?`).bind(m.id).run();
  await woEvent(c, { workOrderId: wo.id, milestoneId: m.id, kind: "milestone.rejected",
    payload: { reason: why } });
  return c.json({ ok: true });
});

// Is this release's chain clear, and through when?
//
// Counts and dates, never a roster. The account is entitled to know their
// subcontractor's chain is clear; the subcontractor's supplier list is that
// subcontractor's book.
async function waiverStateFor(c, { wo, release, asOf }) {
  // WHICH WAIVER IS THE ONE THAT COUNTS. A release collects several over its
  // life -- a conditional one before the money, an unconditional one after,
  // one withdrawn and asked for again -- so "the newest" would let a fresh
  // request for the unconditional waiver, unsigned, hide the conditional one
  // that was signed and is what the payment went out against. A signed one
  // outranks an unsigned one; a withdrawn one is not a waiver at all.
  const root = await c.env.DB.prepare(
    `SELECT * FROM lien_waivers WHERE release_id = ? AND tier = 0 AND status <> 'void'
      ORDER BY (status = 'signed') DESC, created_at DESC, rowid DESC LIMIT 1`
  ).bind(release.id).first();
  const kids = root
    ? (await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE parent_id = ? AND status <> 'void'`)
        .bind(root.id).all()).results
    : [];
  const declared = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM lower_tier_parties WHERE work_order_id = ? AND company_id = ?`
  ).bind(wo.id, wo.company_id).first();

  // THE DAY THE WORK THIS RELEASE PAYS FOR WAS VERIFIED, not the day somebody
  // presses Pay. It used to be today, so a waiver signed through the 20th went
  // stale on the 21st over a payment for work finished on the 20th -- every
  // waiver expired the night after it was signed, and the gate could only be
  // passed on the same day it was answered. Work after the release's own day
  // is paid by a later release, with a waiver of its own.
  const day = asOf || String(release.created_at || "").slice(0, 10) || dayKeyUtc();
  // The signer's declaration outranks the work order's setting once they have
  // signed it: "I furnished labour only" is a thing somebody swore to.
  const scopeKind = root?.status === "signed" && root.scope_kind
    ? root.scope_kind : (wo.scope_kind || "labor_materials");

  const shape = (w) => (w ? { status: w.status, throughDate: w.through_date, scopeKind: w.scope_kind } : null);
  return chainStatus({
    root: shape(root),
    children: (kids || []).map(shape),
    asOf: day,
    scopeKind,
    declaredCount: declared?.n || 0,
  });
}

// Was this company's paperwork good for the work this release pays for?
//
// Reads the same three sources the roster reads and hands them to
// shared/paygate.js, which holds the rule. The job's date is fetched rather
// than taken from the release, because a release records money and a job
// records when the work was: see the module for why that difference is the
// whole point.
//
// A job with no date falls back to today, which is the only honest answer
// available -- it is also very rare, since /api/jobs requires one.
async function coverStateFor(c, { wo, release }) {
  const company = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`)
    .bind(release.company_id).first();
  // A DATABASE WITHOUT 037 MUST NOT STOP PAYMENT. `company_docs` is where the
  // expiry lives, and on a database that never ran that migration there is no
  // table -- which threw, which this route turned into `migration_needed`, which
  // means nobody could be paid at all. That is worse than the gap it reports.
  //
  // So it falls back to the booleans on `companies`, exactly as the document
  // read path does: `docShapeWithLegacy` reads them and leaves `expiresOn` null,
  // which `docs.js` treats as "does not expire". On such a database that is the
  // honest limit of what is known -- the boolean says a certificate was handed
  // over and nothing anywhere records when it runs out -- so the gate checks
  // presence and this account's own verdict, which is still strictly more than
  // the nothing it checked before.
  //
  // Narrow on purpose: only `missingSchema`, which is the documented pre-037
  // shape. Any other failure still throws, because a catch wide enough to hide
  // a real error here would hide it in front of money.
  let rows = {};
  try { rows = await currentDocRows(c.env.DB, release.company_id); }
  catch (err) { if (!missingSchema(err)) throw err; }
  const engagement = await c.env.DB.prepare(
    `SELECT doc_review FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(release.account_id, release.company_id).first();
  const job = await c.env.DB.prepare(`SELECT date FROM jobs WHERE id = ?`)
    .bind(wo.job_id).first();
  return coverState({
    docs: docShapeWithLegacy(rows, company),
    docReview: parseJson(engagement?.doc_review, {}),
    jobDate: job?.date || null,
    asOf: dayKeyUtc(),
  });
}

app.get("/api/releases/:id/cover-state", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  return c.json(await coverStateFor(c, { wo, release: r }));
});

app.get("/api/releases/:id/waiver-state", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  // A Basic account cannot ask for a waiver, so nothing is outstanding on one.
  if (!(await payingAccountOnScale(c.env, accountId))) return c.json({ clear: true, reasons: [], onScale: false });
  return c.json(await waiverStateFor(c, { wo, release: r }));
});

// ---------------------------------------------------------------------------
// Lien waivers: asking for one, signing one, and the chain below it.
//
// 035 built the chain and the gate and wrote nothing, so every release has
// answered "no waiver has been requested yet" since the gate shipped and the
// override was the only way past it. This is the half that writes. The forms
// themselves -- which state takes which paper, and SubSub's own for the ones
// that prescribe none -- are in shared/waiverform.js, with the reasoning.
//
// THREE WAYS TO SIGN, ONE RECORD. A subcontractor on the roster signs in the
// app; anybody holding the emailed link signs on a page that needs no
// account, which is how the supply house at the bottom of a chain answers;
// and a signed paper copy can be uploaded by the side that signed it or by
// the side that received it. Each lands the same row, through `markSigned`,
// so the gate cannot tell them apart -- and the record can, because it says
// which.

const waiverMigration = () => ({ error: "migration_needed", migration: "069_waiver_forms" });

// LIEN WAIVERS ARE SCALE, BECAUSE THEY BELONG TO PAYMENTS AND PAYING IS SCALE.
// A waiver is only ever for a payment, and moving money through SubSub is the
// Scale plan. Read off the PAYING account -- the one that asks -- and never off
// the subcontractor's, whose own plan has nothing to do with it.
//
// Three consequences, each deliberate. Asking, re-sending and recording a copy
// are refused with `scale_required`. The payment gate does NOT demand a waiver
// of an account that cannot ask for one: holding a Basic account's cheque over
// a feature it does not have would make every payment an override. And a
// waiver already asked for stays signable and withdrawable after a downgrade,
// because the subcontractor's signature is their act and taking a request back
// costs nobody anything.
async function payingAccountOnScale(env, accountId) {
  const a = await env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(accountId).first();
  return accountOnScale(a);
}
const scaleRequired = (c) => c.json({ error: "scale_required",
  detail: "Lien waivers and paying subcontractors through SubSub are part of the Scale plan." }, 403);

async function sha256Bytes(buf) {
  const d = await crypto.subtle.digest("SHA-256", buf);
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// What a waiver's document says, from what is STORED and nothing live. The
// declaration is the one input the signer supplies, so it is passed in at
// signature and read back off the row afterwards.
function renderStoredWaiver(w, f, scopeKind) {
  if (!f || f.source !== "subsub_standard") return null;
  return renderWaiver({
    templateId: f.template_id, templateVersion: f.template_version, kind: w.kind,
    parties: parseJson(f.parties, {}), amountCents: w.amount_cents,
    throughDate: w.through_date, state: w.governing_state,
    scopeKind: scopeKind === undefined ? (w.status === "signed" ? w.scope_kind : null) : scopeKind,
  });
}

// The row as a screen reads it. `side` decides what crosses: the paying side
// learns who signed and when; neither side is handed the token.
function waiverToJs(w, f, extra = {}) {
  let document = null;
  try { document = renderStoredWaiver(w, f); }
  catch (err) { console.warn("[waiver] render failed:", err?.message || err); }
  const parties = parseJson(f?.parties, {});
  return {
    id: w.id, kind: w.kind, tier: w.tier, status: w.status,
    title: KIND_WORDS[w.kind]?.title || "Lien waiver",
    amountCents: w.amount_cents || 0, throughDate: w.through_date,
    governingState: w.governing_state || null,
    scopeKind: w.status === "signed" ? w.scope_kind : null,
    source: f?.source || "uploaded",
    claimant: parties.claimant || w.from_name || null,
    customer: parties.customer || null,
    job: parties.job || null, property: parties.property || null,
    requestedAt: w.requested_at || w.created_at || null,
    signedAt: w.signed_at || null, signedByName: w.signed_by_name || null,
    declinedNote: w.declined_note || null,
    hasFile: !!w.doc_key, fileName: f?.file_name || null,
    uploadedSide: f?.uploaded_side || null,
    emailed: !!f?.emailed, docSha256: w.doc_sha256 || null,
    forms: formsFor(w.governing_state),
    document,
    ...extra,
  };
}

async function loadWaiverForm(env, id) {
  return env.DB.prepare(`SELECT * FROM waiver_forms WHERE waiver_id = ?`).bind(id).first();
}

// Where this release stands, for the screen that asks for one: which forms
// the building's state allows, which of the four fits, and every waiver asked
// for against it so far.
async function releaseWaiverContext(c, release) {
  const wo = await c.env.DB.prepare(
    `SELECT wo.*, j.title AS job_title, j.property_id FROM work_orders wo
       JOIN jobs j ON j.id = wo.job_id WHERE wo.id = ?`
  ).bind(release.work_order_id).first();
  // LIEN LAW FOLLOWS THE PROPERTY, and only the property. The company's own
  // state is NOT a fallback here, unlike the handyman cap: a roofer registered
  // in Oregon on a Washington building signs under Washington law, and a job
  // at no building with a state on it has no governing state anybody here can
  // name. That answers `no_state`, which offers an upload rather than a guess.
  const prop = wo?.property_id
    ? await c.env.DB.prepare(`SELECT * FROM properties WHERE id = ?`).bind(wo.property_id).first()
    : null;
  const state = normalizeState(prop?.state) || null;
  // Final once this is the last milestone on the work order and everything
  // before it is verified -- a suggestion the hiring side can change.
  const ms = (await c.env.DB.prepare(
    `SELECT id, seq, status FROM wo_milestones WHERE work_order_id = ? ORDER BY seq`
  ).bind(release.work_order_id).all()).results || [];
  const last = ms[ms.length - 1];
  const isFinal = !!last && last.id === release.milestone_id && ms.every((m) => m.status === "verified");
  const paid = release.status === "paid";
  return { wo, prop, state, isFinal, paid, suggestedKind: waiverKindFor({ settled: paid, isFinal }) };
}

const propertyLine = (p) => !p ? null
  : [p.name, p.address, [p.city, [p.state, p.zip].filter(Boolean).join(" ")].filter(Boolean).join(", ")]
      .filter(Boolean).join(", ");

app.get("/api/releases/:id/waivers", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  const ctx = await releaseWaiverContext(c, r);
  const company = await c.env.DB.prepare(`SELECT company, email FROM companies WHERE id = ?`)
    .bind(r.company_id).first();
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT * FROM lien_waivers WHERE release_id = ? AND tier = 0
        ORDER BY created_at DESC, rowid DESC`
    ).bind(r.id).all();
    const waivers = [];
    for (const w of results || []) {
      const f = await loadWaiverForm(c.env, w.id);
      // The lower tier as COUNTS, never names -- the subcontractor's supplier
      // list is their book. See shared/waivers.js.
      const kids = (await c.env.DB.prepare(
        `SELECT status FROM lien_waivers WHERE parent_id = ? AND status <> 'void'`
      ).bind(w.id).all()).results || [];
      waivers.push(waiverToJs(w, f, {
        lowerTierSigned: kids.filter((k) => k.status === "signed").length,
        lowerTierTotal: kids.length,
      }));
    }
    const onScale = await payingAccountOnScale(c.env, accountId);
    return c.json({
      onScale,
      forms: formsFor(ctx.state), state: ctx.state, paid: ctx.paid, isFinal: ctx.isFinal,
      suggestedKind: ctx.suggestedKind, claimant: company?.company || null,
      claimantEmail: company?.email || null, amountCents: r.net_cents,
      throughDate: String(r.created_at || "").slice(0, 10) || dayKeyUtc(),
      waivers,
      chain: onScale ? await waiverStateFor(c, { wo, release: r }) : { clear: true, reasons: [], onScale: false },
    });
  } catch (err) {
    const m = missingSchema(err);
    if (m) return c.json({ error: "migration_needed", migration: m }, 503);
    throw err;
  }
});

// Ask for one.
app.post("/api/releases/:id/waiver", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  if (r.status === "void") return c.json({ error: "release_void" }, 409);
  const { error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  if (!(await payingAccountOnScale(c.env, accountId))) return scaleRequired(c);
  const b = await c.req.json().catch(() => ({}));
  const ctx = await releaseWaiverContext(c, r);

  const kind = b.kind || ctx.suggestedKind;
  const refusal = kindRefusal({ kind, paid: ctx.paid });
  if (refusal) return c.json({ error: refusal }, 400);

  const forms = formsFor(ctx.state);
  const source = b.source || forms.sources[0];
  // A STATUTORY STATE IS REFUSED SUBSUB'S FORM ON THE SERVER, not merely not
  // offered on the screen. A waiver on the wrong form can release nothing and
  // still look exactly like one that does.
  if (!WAIVER_SOURCES.includes(source) || !forms.sources.includes(source)) {
    return c.json({ error: "form_not_allowed", reason: forms.reason || null, state: ctx.state }, 400);
  }
  const through = /^\d{4}-\d{2}-\d{2}$/.test(String(b.throughDate || ""))
    ? b.throughDate : (String(r.created_at || "").slice(0, 10) || dayKeyUtc());

  const company = await c.env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(r.company_id).first();
  const account = await c.env.DB.prepare(`SELECT name, company_id FROM accounts WHERE id = ?`).bind(accountId).first();
  const toEmail = String(b.toEmail || company?.email || "").trim().toLowerCase() || null;
  if (toEmail && !validRecipient(toEmail)) return c.json({ error: "invalid_email" }, 400);

  try {
    // Already asked, or already signed: a second identical request is two
    // links in one inbox. The partial index is what holds under a race.
    const prior = await c.env.DB.prepare(
      `SELECT id, status FROM lien_waivers
        WHERE release_id = ? AND tier = 0 AND kind = ? AND status IN ('requested', 'signed')`
    ).bind(r.id, kind).first();
    if (prior) return c.json({ error: prior.status === "signed" ? "already_signed" : "already_requested", id: prior.id }, 409);

    const id = uid();
    const token = shareToken();
    const tpl = source === "subsub_standard" ? generatedTemplateFor(ctx.state) : null;
    const parties = {
      claimant: company?.company || null,
      customer: account?.name || null,
      job: ctx.wo?.job_title || null,
      property: propertyLine(ctx.prop),
    };
    await c.env.DB.prepare(
      `INSERT INTO lien_waivers (id, job_id, account_id, from_company_id, from_email, to_company_id,
         tier, work_order_id, release_id, kind, through_date, amount_cents, governing_state,
         status, token, requested_by)
       VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?, 'requested', ?, ?)`
    ).bind(id, ctx.wo.job_id, accountId, r.company_id, toEmail, account?.company_id || null,
      r.work_order_id, r.id, kind, through, r.net_cents || 0, ctx.state, token, userId).run();
    await c.env.DB.prepare(
      `INSERT INTO waiver_forms (waiver_id, source, template_id, template_version, parties)
       VALUES (?, ?, ?, ?, ?)`
    ).bind(id, source, tpl?.templateId || null, tpl?.templateVersion || null, JSON.stringify(parties)).run();

    const sent = await mailWaiverRequest(c.env, { id, token, toEmail, toName: company?.contact,
      fromName: account?.name, kind, amountCents: r.net_cents, through, job: parties.job,
      source, state: ctx.state });
    await logEvent(c.env, accountId, userId, "waiver_requested", id,
      { releaseId: r.id, kind, source, state: ctx.state, emailed: sent.ok });
    const w = await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE id = ?`).bind(id).first();
    return c.json({ ok: true, waiver: waiverToJs(w, await loadWaiverForm(c.env, id)),
      emailed: sent.ok, emailError: sent.ok ? null : sent.error || null }, 201);
  } catch (err) {
    if (/UNIQUE constraint failed/i.test(String(err?.message || err))) {
      return c.json({ error: "already_requested" }, 409);
    }
    const m = missingSchema(err);
    if (m) return c.json({ error: "migration_needed", migration: m }, 503);
    throw err;
  }
});

// The email, and whether it went -- recorded on the row, because a row
// reading "sent" over a supplier who was never told is how somebody says they
// never got it while the screen says they did.
async function mailWaiverRequest(env, { id, token, toEmail, toName, fromName, kind,
  amountCents, through, job, source, state }) {
  if (!toEmail) return { ok: false, error: "no_recipient" };
  const mail = waiverRequestEmail({
    toName, fromName, kindTitle: KIND_WORDS[kind]?.title || "Lien waiver",
    conditional: kind.startsWith("conditional_"),
    amount: Number(amountCents) > 0 ? `$${(amountCents / 100).toLocaleString("en-US", { minimumFractionDigits: 2 })}` : "everything you are owed",
    through, job, link: `${APP_ORIGIN}/?waiver=${encodeURIComponent(token)}`,
    uploadOnly: source === "uploaded", stateName: stateName(state),
  });
  const sent = await sendEmail(env, { to: toEmail, ...mail });
  if (sent.ok) {
    await env.DB.prepare(`UPDATE waiver_forms SET emailed = 1 WHERE waiver_id = ?`).bind(id).run();
  }
  return sent;
}

app.post("/api/waivers/:id/resend", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  try {
    const w = await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE id = ? AND account_id = ?`)
      .bind(c.req.param("id"), accountId).first();
    if (!w) return c.json({ error: "not_found" }, 404);
    if (w.status !== "requested") return c.json({ error: "already_answered" }, 409);
    if (!(await payingAccountOnScale(c.env, accountId))) return scaleRequired(c);
    const f = await loadWaiverForm(c.env, w.id);
    const account = await c.env.DB.prepare(`SELECT name FROM accounts WHERE id = ?`).bind(accountId).first();
    const parties = parseJson(f?.parties, {});
    const sent = await mailWaiverRequest(c.env, { id: w.id, token: w.token, toEmail: w.from_email,
      fromName: w.tier === 0 ? account?.name : parties.customer, kind: w.kind,
      amountCents: w.amount_cents, through: w.through_date, job: parties.job,
      source: f?.source, state: w.governing_state });
    await logEvent(c.env, accountId, userId, "waiver_resent", w.id, { emailed: sent.ok });
    return c.json({ ok: sent.ok, error: sent.ok ? null : sent.error || null });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

// Withdraw one. Not a delete: a waiver somebody was asked for is a thing that
// happened, and the chain is the record of who was asked what.
app.post("/api/waivers/:id/void", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const w = await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE id = ? AND account_id = ? AND tier = 0`)
    .bind(c.req.param("id"), accountId).first();
  if (!w) return c.json({ error: "not_found" }, 404);
  // A SIGNED waiver is not withdrawn. It is somebody's signature releasing a
  // right, and it stays on the record whatever happens to the payment.
  if (w.status !== "requested") return c.json({ error: "already_answered" }, 409);
  await c.env.DB.prepare(`UPDATE lien_waivers SET status = 'void' WHERE id = ? AND status = 'requested'`)
    .bind(w.id).run();
  await c.env.DB.prepare(`UPDATE lien_waivers SET status = 'void' WHERE parent_id = ? AND status = 'requested'`)
    .bind(w.id).run();
  await logEvent(c.env, accountId, userId, "waiver_voided", w.id, {});
  return c.json({ ok: true });
});

// THE ONE WRITE THAT SIGNS. Every way in -- the app, the link, an upload by
// either side -- comes through here, so the gate cannot tell them apart and
// the record says which it was.
//
// Guarded on `status = 'requested'` in the UPDATE itself, so two presses at
// once sign once, and the second answers `already_answered`.
async function markSigned(c, w, { name, email, userId, scopeKind, hash, docKey, file }) {
  const res = await c.env.DB.prepare(
    `UPDATE lien_waivers SET status = 'signed', signed_at = CURRENT_TIMESTAMP,
       signed_by_name = ?, signed_by_email = ?, signed_ip = ?, scope_kind = ?,
       doc_sha256 = ?, doc_key = COALESCE(?, doc_key)
     WHERE id = ? AND status = 'requested'`
  ).bind(name || null, email || null, c.req.header("CF-Connecting-IP") || null,
    scopeKind, hash, docKey || null, w.id).run();
  if (!res.meta?.changes) return false;
  await c.env.DB.prepare(
    `UPDATE waiver_forms SET answered_at = CURRENT_TIMESTAMP,
       file_name = COALESCE(?, file_name), file_type = COALESCE(?, file_type),
       uploaded_by = COALESCE(?, uploaded_by), uploaded_side = COALESCE(?, uploaded_side)
     WHERE waiver_id = ?`
  ).bind(file?.name || null, file?.type || null, file ? (userId || null) : null,
    file?.side || null, w.id).run();
  await logEvent(c.env, w.account_id, userId || null, "waiver_signed", w.id,
    { tier: w.tier, scopeKind, uploaded: !!file, side: file?.side || "claimant" });
  // A signed link is what makes the chain below it worth asking for.
  if (w.tier === 0) await requestLowerTier(c, { ...w, status: "signed", scope_kind: scopeKind });
  return true;
}

// The declaration that comes with a signature: who else worked on this job.
//
// LABOUR ONLY means nobody, and is sworn to in the text. Anything else needs
// somebody named, or a list already declared on this work order -- because
// "I supplied materials and nobody supplied them to me" is the one answer
// that would read the chain as clear with nobody below it ever asked.
function readDeclaration(b, { declaredCount = 0, tier = 0 } = {}) {
  const scopeKind = SCOPE_KINDS.includes(b.scopeKind) ? b.scopeKind : null;
  if (!scopeKind) return { error: "declaration_required" };
  const parties = (Array.isArray(b.parties) ? b.parties : []).slice(0, 25).map((p) => ({
    name: String(p?.name || "").trim().slice(0, 160),
    email: String(p?.email || "").trim().toLowerCase().slice(0, 200) || null,
    role: ["supplier", "subcontractor", "equipment", "other"].includes(p?.role) ? p.role : "supplier",
    amountCents: Math.max(0, Math.round(Number(p?.amountCents) || 0)),
  })).filter((p) => p.name);
  if (scopeKind === "labor_only" && parties.length) return { error: "labor_only_with_parties" };
  if (parties.some((p) => p.email && !validRecipient(p.email))) return { error: "invalid_email" };
  // Below the first tier, the chain is capped -- a supplier's own suppliers
  // are not asked about here -- so a declaration there needs no list.
  if (tier === 0 && scopeKind !== "labor_only" && !parties.length && !declaredCount) {
    return { error: "parties_required" };
  }
  return { scopeKind, parties: tier === 0 ? parties : [] };
}

async function declaredCountFor(env, w) {
  if (!w.work_order_id || !w.from_company_id) return 0;
  const r = await env.DB.prepare(
    `SELECT COUNT(*) AS n FROM lower_tier_parties WHERE work_order_id = ? AND company_id = ?`
  ).bind(w.work_order_id, w.from_company_id).first();
  return r?.n || 0;
}

async function storeDeclaration(c, w, parties, { userId }) {
  for (const p of parties) {
    // Matched on the address, or the name where there is none, so declaring
    // the same yard twice is one party rather than two waivers in its inbox.
    const dup = await c.env.DB.prepare(
      `SELECT id FROM lower_tier_parties WHERE work_order_id = ? AND company_id = ?
         AND (lower(COALESCE(email, '')) = ? AND ? <> '' OR lower(name) = lower(?))`
    ).bind(w.work_order_id, w.from_company_id, p.email || "", p.email || "", p.name).first();
    if (dup) continue;
    await c.env.DB.prepare(
      `INSERT INTO lower_tier_parties (id, job_id, account_id, work_order_id, company_id,
         name, email, role, declared_by, complete_attested)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1)`
    ).bind(uid(), w.job_id, w.account_id, w.work_order_id, w.from_company_id,
      p.name, p.email, p.role, userId || null).run();
  }
}

// Ask everybody declared below a signed tier-0 waiver for theirs, of the same
// kind and through the same date. Declared once per work order, asked once
// per signed waiver -- a conditional waiver's chain is not an unconditional
// one's, and a supplier who signed the first has not been paid yet.
async function requestLowerTier(c, root) {
  if (root.status !== "signed" || root.scope_kind === "labor_only") return 0;
  const { results: parties } = await c.env.DB.prepare(
    `SELECT * FROM lower_tier_parties WHERE work_order_id = ? AND company_id = ?`
  ).bind(root.work_order_id, root.from_company_id).all();
  const rootForm = await loadWaiverForm(c.env, root.id);
  const rootParties = parseJson(rootForm?.parties, {});
  const forms = formsFor(root.governing_state);
  let made = 0;
  for (const p of parties || []) {
    // Nobody to send it to is still a party: the chain counts them, and the
    // subcontractor can collect theirs on paper and upload it.
    const already = await c.env.DB.prepare(
      `SELECT id FROM lien_waivers WHERE parent_id = ? AND kind = ? AND status IN ('requested', 'signed')
         AND (lower(COALESCE(from_email, '')) = lower(COALESCE(?, '')) AND lower(from_name) = lower(?))`
    ).bind(root.id, root.kind, p.email || "", p.name).first();
    if (already) continue;
    const id = uid();
    const token = shareToken();
    const source = forms.sources[0];
    const tpl = source === "subsub_standard" ? generatedTemplateFor(root.governing_state) : null;
    const parties2 = { claimant: p.name, customer: rootParties.claimant || null,
      job: rootParties.job || null, property: rootParties.property || null };
    await c.env.DB.prepare(
      `INSERT INTO lien_waivers (id, job_id, account_id, from_name, from_email, to_company_id,
         tier, parent_id, work_order_id, kind, through_date, amount_cents, governing_state,
         status, token)
       VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, 0, ?, 'requested', ?)`
    ).bind(id, root.job_id, root.account_id, p.name, p.email || null, root.from_company_id,
      root.id, root.work_order_id, root.kind, root.through_date, root.governing_state, token).run();
    await c.env.DB.prepare(
      `INSERT INTO waiver_forms (waiver_id, source, template_id, template_version, parties)
       VALUES (?, ?, ?, ?, ?)`
    ).bind(id, source, tpl?.templateId || null, tpl?.templateVersion || null, JSON.stringify(parties2)).run();
    await mailWaiverRequest(c.env, { id, token, toEmail: p.email, toName: p.name,
      fromName: rootParties.claimant, kind: root.kind, amountCents: 0,
      through: root.through_date, job: rootParties.job, source, state: root.governing_state });
    made++;
  }
  return made;
}

// Signing SubSub's form: the hash is of the text shown, recomputed from what
// is stored plus the declaration chosen now -- never carried over from the
// request, because a caller who could name the hash could sign one document
// and record another.
async function signStandard(c, w, b, who) {
  const f = await loadWaiverForm(c.env, w.id);
  if (!f) return c.json(waiverMigration(), 503);
  if (f.source !== "subsub_standard") return c.json({ error: "upload_required" }, 409);
  if (w.status !== "requested") return c.json({ error: "already_answered" }, 409);
  const dec = readDeclaration(b, { declaredCount: await declaredCountFor(c.env, w), tier: w.tier });
  if (dec.error) return c.json({ error: dec.error }, 400);
  let rendered;
  try { rendered = renderStoredWaiver(w, f, dec.scopeKind); }
  catch (err) { return c.json({ error: err.code || "unknown_template" }, 409); }
  const hash = await sha256Hex(wvCanonical(rendered));
  if (dec.parties.length) await storeDeclaration(c, w, dec.parties, who);
  const ok = await markSigned(c, w, { ...who, scopeKind: dec.scopeKind, hash });
  if (!ok) return c.json({ error: "already_answered" }, 409);
  return c.json({ ok: true, docSha256: hash });
}

// Uploading a signed copy IS signing it, from whichever side it arrives.
async function signByUpload(c, w, { fileName, side, who, declaration }) {
  if (w.status !== "requested") return c.json({ error: "already_answered" }, 409);
  const type = (c.req.header("Content-Type") || "").split(";")[0].trim().toLowerCase();
  if (!WAIVER_FILE_TYPES.includes(type)) return c.json({ error: "not_a_document", type }, 415);
  if (Number(c.req.header("Content-Length") || 0) > MAX_WAIVER_BYTES) {
    return c.json({ error: "too_big", max: MAX_WAIVER_BYTES }, 413);
  }
  const body = await c.req.arrayBuffer();
  if (!body.byteLength) return c.json({ error: "empty" }, 400);
  if (body.byteLength > MAX_WAIVER_BYTES) return c.json({ error: "too_big", max: MAX_WAIVER_BYTES }, 413);
  // The declaration rides in the query string on an upload, since the body
  // is the file. The paying side uploading a copy it was emailed declares
  // nothing -- it cannot swear to somebody else's suppliers -- so its
  // upload keeps the work order's own scope.
  let scopeKind = w.scope_kind || "labor_materials";
  let dec = null;
  if (declaration) {
    dec = readDeclaration(declaration, { declaredCount: await declaredCountFor(c.env, w), tier: w.tier });
    if (dec.error) return c.json({ error: dec.error }, 400);
    scopeKind = dec.scopeKind;
  } else if (side === "recipient") {
    const wo = w.work_order_id ? await c.env.DB.prepare(`SELECT scope_kind FROM work_orders WHERE id = ?`)
      .bind(w.work_order_id).first() : null;
    scopeKind = wo?.scope_kind || "labor_materials";
  }
  const key = `${w.account_id}/lien-waiver/${uid()}-${safeFileName(fileName)}`;
  await c.env.FILES.put(key, body, { httpMetadata: { contentType: type } });
  const hash = await sha256Bytes(body);
  if (dec?.parties?.length) await storeDeclaration(c, w, dec.parties, who);
  const ok = await markSigned(c, w, { ...who, scopeKind, hash, docKey: key,
    file: { name: safeFileName(fileName), type, side } });
  if (!ok) return c.json({ error: "already_answered" }, 409);
  return c.json({ ok: true, docSha256: hash });
}

async function decline(c, w, note, userId) {
  if (w.status !== "requested") return c.json({ error: "already_answered" }, 409);
  await c.env.DB.prepare(
    `UPDATE lien_waivers SET status = 'declined', declined_note = ? WHERE id = ? AND status = 'requested'`
  ).bind(String(note || "").trim().slice(0, 1000) || null, w.id).run();
  await c.env.DB.prepare(`UPDATE waiver_forms SET answered_at = CURRENT_TIMESTAMP WHERE waiver_id = ?`)
    .bind(w.id).run();
  await logEvent(c.env, w.account_id, userId || null, "waiver_declined", w.id, { tier: w.tier });
  return c.json({ ok: true });
}

// The paying side records a signed copy it was sent some other way -- by
// email, on paper, through the post. Recorded as the RECIPIENT'S upload, so
// nobody later reads it as the subcontractor having signed in the app.
app.put("/api/waivers/:id/file/:fileName", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  try {
    const w = await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE id = ? AND account_id = ? AND tier = 0`)
      .bind(c.req.param("id"), accountId).first();
    if (!w) return c.json({ error: "not_found" }, 404);
    if (!(await payingAccountOnScale(c.env, accountId))) return scaleRequired(c);
    return await signByUpload(c, w, { fileName: c.req.param("fileName"), side: "recipient",
      who: { userId, name: null, email: null } });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

// The signed copy, to either party. The paying account reads its own chain's
// tier-0 rows; the claimant reads its own.
app.get("/api/waivers/:id/file", async (c) => {
  const { accountId, role } = c.get("auth");
  const w = await c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE id = ?`).bind(c.req.param("id")).first();
  let may = false;
  if (w && w.tier === 0 && w.account_id === accountId && (role === "admin" || role === "pm")) may = true;
  if (w && !may) {
    const mine = await seatCompany(c);
    if (mine && (w.from_company_id === mine || (w.tier > 0 && w.to_company_id === mine))) may = true;
  }
  if (!w || !may) return c.json({ error: "not_found" }, 404);
  if (!w.doc_key) return c.json({ error: "no_file" }, 404);
  const obj = await c.env.FILES.get(w.doc_key);
  if (!obj) return c.json({ error: "no_file" }, 404);
  const f = await loadWaiverForm(c.env, w.id);
  return new Response(obj.body, { headers: {
    "Content-Type": f?.file_type || obj.httpMetadata?.contentType || "application/octet-stream",
    "Cache-Control": "private, no-store",
  } });
});

// ---- the side being asked ---------------------------------------------------

// EVERY CLIENT'S WAIVERS, IN ONE LIST, for the reason /api/my-work and
// /api/my-agreements exist: a subcontractor on twenty-five rosters does not
// find a waiver waiting by switching account twenty-five times. Scoped by
// `from_company_id = mine`, read off the seat and never the URL.
//
// Their own lower tier comes with it, BY NAME -- these are their suppliers,
// declared by them, and the only party who may never see this list is the one
// above them.
app.get("/api/my-waivers", async (c) => {
  const companyId = await seatCompany(c);
  if (!companyId) return c.json({ error: await noCompanyReason(c) }, 403);
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT w.*, acc.name AS account_name FROM lien_waivers w
         JOIN accounts acc ON acc.id = w.account_id
        WHERE w.from_company_id = ? AND w.tier = 0 AND w.status IN ('requested', 'signed', 'declined')
        ORDER BY (w.status = 'requested') DESC, w.created_at DESC LIMIT 100`
    ).bind(companyId).all();
    const out = [];
    for (const w of results || []) {
      const f = await loadWaiverForm(c.env, w.id);
      const below = (await c.env.DB.prepare(
        `SELECT id, from_name, from_email, status, signed_at, declined_note FROM lien_waivers
          WHERE parent_id = ? AND status <> 'void' ORDER BY created_at`
      ).bind(w.id).all()).results || [];
      const declared = (await c.env.DB.prepare(
        `SELECT name, email, role FROM lower_tier_parties WHERE work_order_id = ? AND company_id = ?
          ORDER BY created_at`
      ).bind(w.work_order_id, companyId).all()).results || [];
      out.push(waiverToJs(w, f, {
        accountName: w.account_name,
        below: below.map((k) => ({ id: k.id, name: k.from_name, email: k.from_email, status: k.status,
          signedAt: k.signed_at, declinedNote: k.declined_note })),
        declared,
      }));
    }
    return c.json(out);
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

async function myWaiver(c) {
  const companyId = await seatCompany(c);
  if (!companyId) return { res: c.json({ error: await noCompanyReason(c) }, 403) };
  const w = await c.env.DB.prepare(
    `SELECT * FROM lien_waivers WHERE id = ? AND from_company_id = ? AND tier = 0`
  ).bind(c.req.param("id"), companyId).first();
  if (!w) return { res: c.json({ error: "not_found" }, 404) };
  return { w, companyId };
}

app.post("/api/my-waivers/:id/sign", async (c) => {
  const { userId } = c.get("auth");
  try {
    const { w, res } = await myWaiver(c);
    if (res) return res;
    const b = await c.req.json().catch(() => ({}));
    const me = await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(userId).first();
    if (!typedNameMatches(b.typedName, me?.name)) {
      return c.json({ error: "name_mismatch", expected: me?.name || null }, 400);
    }
    return await signStandard(c, w, b, { userId, name: me?.name, email: me?.email });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

app.put("/api/my-waivers/:id/file/:fileName", async (c) => {
  const { userId } = c.get("auth");
  try {
    const { w, res } = await myWaiver(c);
    if (res) return res;
    const me = await c.env.DB.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(userId).first();
    return await signByUpload(c, w, { fileName: c.req.param("fileName"), side: "claimant",
      who: { userId, name: me?.name, email: me?.email },
      declaration: parseJson(c.req.query("declaration"), { scopeKind: null }) });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

app.post("/api/my-waivers/:id/decline", async (c) => {
  const { userId } = c.get("auth");
  try {
    const { w, res } = await myWaiver(c);
    if (res) return res;
    const b = await c.req.json().catch(() => ({}));
    return await decline(c, w, b.note, userId);
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

// ---- by link, for somebody with no account ---------------------------------
//
// The token is the whole of the auth, which is why this is on the public
// exemption list: 32 random bytes, emailed to the party being asked, naming
// one waiver. Nothing here is addressable by an id. Once answered it can no
// longer change anything -- every write is guarded on `requested` -- and it
// still reads, so somebody coming back to the link sees what they signed.

async function waiverByToken(c) {
  const token = c.req.param("token");
  if (!token || token.length < 20) return null;
  return c.env.DB.prepare(`SELECT * FROM lien_waivers WHERE token = ? AND status <> 'void'`)
    .bind(token).first();
}

app.get("/api/waiver/:token", async (c) => {
  try {
    const w = await waiverByToken(c);
    if (!w) return c.json({ error: "not_found" }, 404);
    const f = await loadWaiverForm(c.env, w.id);
    const shape = waiverToJs(w, f);
    // Which side asked, by name: the claimant's customer. Never the account
    // id, never who else was asked.
    return c.json({ ...shape, docSha256: undefined, declaredCount: await declaredCountFor(c.env, w) });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

app.post("/api/waiver/:token/sign", async (c) => {
  const rl = await rateLimit(c.env, "waiver-sign", c.req.header("CF-Connecting-IP") || "ip", { limit: 30, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);
  try {
    const w = await waiverByToken(c);
    if (!w) return c.json({ error: "not_found" }, 404);
    const b = await c.req.json().catch(() => ({}));
    // Nobody here has an account to match a name against, so the name is the
    // signature itself: typed in full, and recorded beside the address the
    // link was sent to.
    const name = String(b.typedName || "").trim().replace(/\s+/g, " ").slice(0, 160);
    if (name.length < 3 || !/\s/.test(name)) return c.json({ error: "full_name_required" }, 400);
    return await signStandard(c, w, b, { userId: null, name, email: w.from_email || null });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

app.put("/api/waiver/:token/file/:fileName", async (c) => {
  const rl = await rateLimit(c.env, "waiver-sign", c.req.header("CF-Connecting-IP") || "ip", { limit: 30, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);
  try {
    const w = await waiverByToken(c);
    if (!w) return c.json({ error: "not_found" }, 404);
    const name = String(c.req.query("name") || "").trim().replace(/\s+/g, " ").slice(0, 160);
    if (name.length < 3 || !/\s/.test(name)) return c.json({ error: "full_name_required" }, 400);
    return await signByUpload(c, w, { fileName: c.req.param("fileName"), side: "claimant",
      who: { userId: null, name, email: w.from_email || null },
      declaration: parseJson(c.req.query("declaration"), { scopeKind: null }) });
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

app.post("/api/waiver/:token/decline", async (c) => {
  try {
    const w = await waiverByToken(c);
    if (!w) return c.json({ error: "not_found" }, 404);
    const b = await c.req.json().catch(() => ({}));
    return await decline(c, w, b.note, null);
  } catch (err) {
    if (missingSchema(err)) return c.json(waiverMigration(), 503);
    throw err;
  }
});

// Money goes out.
//
// Settlement is manual: a cheque number, a transfer reference, whatever they
// already do. `method` is the seam a processor drops into later without this
// route changing shape.
//
// GATED ON THE WAIVER AND ON COVER, which is the point of the whole
// mechanism -- and for most of this ledger's life it was only the first of
// the two. Paying a subcontractor who was uninsured on the day of the work is
// the thing routing payment through here is supposed to prevent, and nothing
// checked it; see shared/paygate.js for which documents count and why the
// date asked about is the job's rather than today's.
//
// An override exists for each because a real business has to be able to pay
// somebody on a Friday afternoon -- but each is recorded as its own event
// with its own reason, so "we always override it" is a visible fact rather
// than a habit nobody can see.
app.post("/api/releases/:id/settle", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  if (r.status === "paid") return c.json({ error: "already_paid" }, 409);
  if (r.status === "void") return c.json({ error: "void" }, 409);
  const { wo, error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  // 066. Not against a job that was cancelled or closed with nothing done.
  // Deliberately BEFORE the two paperwork gates: those are overridable with a
  // recorded reason, and this is not -- no reason makes work that was never
  // done payable, which is the same line `canPay` draws about unfunded money.
  { const no = await jobEndingBlocksPay(c, wo); if (no) return c.json(no, 409); }

  const b = await c.req.json().catch(() => ({}));
  const method = String(b.method || "manual").trim().slice(0, 40);
  const reference = String(b.reference || "").trim().slice(0, 120) || null;

  // TWO GATES, TWO OVERRIDES, TWO REASONS, and they are deliberately not one.
  //
  // A missing waiver and an uninsured job are different problems and somebody
  // paying anyway is saying a different thing about each. One checkbox
  // covering both would let a reason typed about the waiver stand as the
  // recorded justification for paying against lapsed cover -- which is the
  // "a catch wide enough to hide a real error" shape pointed at the one place
  // it costs the most. So each is asked separately and each reason lands
  // against its own event.
  const cover = await coverStateFor(c, { wo, release: r });
  if (!cover.clear && !b.coverOverride) {
    return c.json({ error: "cover_outstanding", cover }, 409);
  }
  if (!cover.clear) {
    // Overridable at all, for the reason the waiver override exists: refusing
    // outright would have SubSub holding a subcontractor's money over a
    // document the HIRING account has not got round to reading. But it is on
    // the record with a name against it.
    const whyCover = String(b.coverOverrideReason || "").trim().slice(0, 500);
    if (!whyCover) return c.json({ error: "cover_reason_required", cover }, 400);
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.cover_override",
      payload: { releaseId: r.id, reason: whyCover, cover } });
  }

  const chain = (await payingAccountOnScale(c.env, r.account_id))
    ? await waiverStateFor(c, { wo, release: r }) : { clear: true, reasons: [], onScale: false };
  if (!chain.clear && !b.override) {
    return c.json({ error: "waiver_outstanding", ...chain }, 409);
  }
  if (!chain.clear) {
    const why = String(b.overrideReason || "").trim().slice(0, 500);
    if (!why) return c.json({ error: "override_reason_required", ...chain }, 400);
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.override",
      payload: { releaseId: r.id, reason: why, chain } });
  }

  // NO FEE ON MONEY THAT DID NOT GO THROUGH SUBSUB. The fee was stamped when
  // the release was verified, because that is when the account needs to see
  // it -- before funding, before paying. Recorded as paid by cheque, nothing
  // moved through us and nothing is charged, so it is zeroed in the same write
  // that closes the release. Not a refund: it was never taken, since only a
  // release paid by `stripe` counts its fee as spent (`woMoney`).
  // `m033_inv_fee_off_platform` in CHECK.sql counts one that slipped past.
  const res = await c.env.DB.prepare(
    `UPDATE wo_releases SET status = 'paid', method = ?, reference = ?, fee_cents = 0,
       settled_at = CURRENT_TIMESTAMP, settled_by = ?
     WHERE id = ? AND status = 'due'`
  ).bind(method, reference, userId, r.id).run();
  // Two people pressing pay at once: the second write changes nothing and
  // must not report success.
  if (!res.meta?.changes) return c.json({ error: "already_paid" }, 409);

  await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.settled",
    payload: { releaseId: r.id, method, reference, netCents: r.net_cents,
      feeCents: 0, feeWaivedCents: r.fee_cents || 0,
      chainClear: chain.clear, coverClear: cover.clear,
      coverProblems: cover.problems },
    idemKey: `settle:${r.id}` });
  return c.json({ ok: true, status: "paid", chainClear: chain.clear, coverClear: cover.clear });
});


// ---------------------------------------------------------------------------
// The funded side: money in against a work order, money out per release
// ---------------------------------------------------------------------------
// 033 left `wo_releases.method` and `.reference` as the seam a payment rail
// drops into. This is the rail. Migration 051 holds the two tables and
// shared/escrow.js holds the arithmetic and the refusals; EASY-PAY.md §10.3
// holds the legal shape, which decided everything about how these routes work.
//
// SEPARATE CHARGES AND TRANSFERS. The account's card funds a PaymentIntent
// with no `transfer_data` and no `on_behalf_of`, so the money lands in the
// platform balance; releasing creates a Transfer to the subcontractor's
// connected account. That is the only Stripe arrangement that HOLDS money
// between funding and release, which is the whole product claim -- and it also
// makes SubSub merchant of record, which is the open question rather than a
// detail under it.
//
// THE FEE IS NOT A STRIPE CONCEPT HERE. The account funds the gross plus the
// fee and the subcontractor is sent the net; the fee is what stays where it
// already is. `application_fee_amount` belongs to destination charges. So the
// fee stamped onto the release when it was verified (shared/fee.js) is the
// whole of it -- spent when that release is paid through here, and zeroed
// when it is recorded as paid somewhere else.
//
// SETTLE AND PAY ARE TWO ROUTES ON PURPOSE. `settle` records money that moved
// somewhere else -- a cheque, a bank transfer, whatever they already do -- and
// `pay` moves it. Folding them together would make one route where a bug
// either records a payment that never happened or makes one that was only
// meant to be written down, which is the worst place in this codebase for that
// ambiguity to live. They share the gates and nothing else.

const fundingMigration = () => ({ error: "migration_needed", migration: "051_escrow" });

// Every figure about one work order's money, from the two tables.
//
// `dueCents` is what is OWED and unpaid, which is what makes `shortfall`
// answerable -- "you have funded $1,500 and owe $4,000" is actionable where
// "insufficient funds" is not.
async function woMoney(c, workOrderId) {
  const f = await c.env.DB.prepare(
    `SELECT COALESCE(SUM(CASE WHEN status IN ('funded','refunded') THEN amount_cents ELSE 0 END), 0) AS funded,
            COALESCE(SUM(refunded_cents), 0) AS refunded
       FROM wo_funding WHERE work_order_id = ?`
  ).bind(workOrderId).first();
  // A pending transfer counts as gone. It is money Stripe has been told to
  // move, and treating it as still available is how the same balance pays two
  // releases.
  const t = await c.env.DB.prepare(
    `SELECT COALESCE(SUM(CASE WHEN status IN ('paid','pending') THEN amount_cents ELSE 0 END), 0) AS out
       FROM wo_transfers WHERE work_order_id = ?`
  ).bind(workOrderId).first();
  // The fee, in two halves. A release paid through SubSub has SPENT its fee:
  // that money is in the platform balance and is no longer the account's to
  // refund or to spend on another release. A release still due will need its
  // fee on hand before it can be sent. A release recorded as paid by cheque
  // carries none -- settle zeroes it -- so it is in neither.
  const d = await c.env.DB.prepare(
    `SELECT COALESCE(SUM(CASE WHEN status = 'due' THEN net_cents ELSE 0 END), 0) AS due,
            COALESCE(SUM(CASE WHEN status = 'due' THEN fee_cents ELSE 0 END), 0) AS fees_due,
            COALESCE(SUM(CASE WHEN status = 'paid' AND method = 'stripe' THEN fee_cents ELSE 0 END), 0) AS fees_taken
       FROM wo_releases WHERE work_order_id = ?`
  ).bind(workOrderId).first();
  return fundingState({
    fundedCents: f?.funded || 0, refundedCents: f?.refunded || 0,
    transferredCents: t?.out || 0, dueCents: d?.due || 0,
    feesDueCents: d?.fees_due || 0, feesTakenCents: d?.fees_taken || 0,
  });
}

// Is this company reachable by money at all? Re-derived from the row rather
// than latched, for the reason pay.js gives: Stripe withdraws a capability as
// readily as it grants one.
async function payeeState(c, companyId) {
  const row = await c.env.DB.prepare(
    `SELECT * FROM payout_accounts WHERE company_id = ? AND processor = 'stripe'`
  ).bind(companyId).first();
  return { row, ...payoutSummary(row) };
}

// What the money panel on a work order draws.
app.get("/api/work-orders/:id/funding", requireRole("admin", "pm"), async (c) => {
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  try {
    const money = await woMoney(c, wo.id);
    const payee = await payeeState(c, wo.company_id);
    const { results: fundings } = await c.env.DB.prepare(
      `SELECT id, amount_cents, status, error, refunded_cents, created_at, funded_at
         FROM wo_funding WHERE work_order_id = ? ORDER BY created_at DESC LIMIT 50`
    ).bind(wo.id).all();
    const { results: transfers } = await c.env.DB.prepare(
      `SELECT t.id, t.release_id, t.amount_cents, t.status, t.error, t.created_at, t.paid_at,
              t.processor_transfer_id
         FROM wo_transfers t WHERE t.work_order_id = ? ORDER BY t.created_at DESC LIMIT 50`
    ).bind(wo.id).all();
    return c.json({
      ...money,
      configured: !!c.env.STRIPE_SECRET_KEY,
      onScale: await payingAccountOnScale(c.env, wo.account_id),
      // The account's fee terms and how much of its free allowance is left,
      // so the fund form and the pay window quote ITS price rather than the
      // default -- a negotiated rate shown as the default 0.5% is the screen naming the
      // wrong price.
      ...(await (async () => {
        const t = await accountFeeTerms(c.env, wo.account_id);
        const processed = await processedCents(c.env, wo.account_id);
        return { feeTerms: { bps: t.bps, capCents: t.capCents, freeCents: t.freeCents },
          processedCents: processed, freeLeftCents: Math.max(0, t.freeCents - processed) };
      })()),
      // The payee's STATUS and nothing else about them. Which requirements
      // Stripe is still asking of a subcontractor is between Stripe and the
      // subcontractor; the hiring account needs to know only whether money
      // can reach them, and the screen says to ask them rather than listing
      // their outstanding identity documents.
      payeeReady: payee.payable === true,
      payeeStatus: payee.status || "none",
      fundings: (fundings || []).map((r) => ({
        id: r.id, amountCents: r.amount_cents, status: r.status, error: r.error,
        refundedCents: r.refunded_cents, createdAt: r.created_at, fundedAt: r.funded_at,
      })),
      transfers: (transfers || []).map((r) => ({
        id: r.id, releaseId: r.release_id, amountCents: r.amount_cents, status: r.status,
        error: r.error, createdAt: r.created_at, paidAt: r.paid_at,
        reference: r.processor_transfer_id,
      })),
    });
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    throw err;
  }
});

// Put money behind a work order.
//
// Returns a client secret. The card is confirmed in the browser by Stripe's
// Payment Element, exactly as the subscription's card change is, so a number
// never comes near us -- and nothing here is believed on the way back: see
// /fund/confirm.
app.post("/api/work-orders/:id/fund", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const { accountId, userId } = c.get("auth");
  // PAYING SUBCONTRACTORS THROUGH SUBSUB IS SCALE, and this is the door the
  // money comes in by, so it is where that is enforced. Only here: paying out
  // money already funded, and refunding it, stay open after a downgrade --
  // money that is in must always have a way out, to the subcontractor or back.
  if (!(await payingAccountOnScale(c.env, accountId))) return scaleRequired(c);

  const b = await c.req.json().catch(() => ({}));
  const amount = Math.round(Number(b.amountCents) || 0);
  if (amount < MIN_FUND_CENTS || amount > MAX_FUND_CENTS) {
    return c.json({ error: "bad_amount", min: MIN_FUND_CENTS, max: MAX_FUND_CENTS }, 400);
  }

  const a = await c.env.DB.prepare(`SELECT stripe_customer_id FROM accounts WHERE id = ?`)
    .bind(accountId).first();

  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO wo_funding (id, work_order_id, account_id, amount_cents, currency, created_by)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(id, wo.id, accountId, amount, CURRENCY, userId || null).run();
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    throw err;
  }

  try {
    const pi = await stripeCall(c.env, "/payment_intents", {
      params: {
        amount, currency: CURRENCY,
        ...(a?.stripe_customer_id ? { customer: a.stripe_customer_id } : {}),
        // NO `transfer_data` and NO `on_behalf_of`. Either one would settle
        // this charge straight into somebody else's balance, which is a
        // destination charge -- money that arrives already spent, and so
        // cannot be held against a milestone that has not been met.
        //
        // `transfer_group` is what ties the later transfers to this charge in
        // Stripe's own reporting, so a reconciliation does not depend on our
        // tables being right.
        transfer_group: `wo:${wo.id}`,
        automatic_payment_methods: { enabled: "true" },
        metadata: { work_order_id: wo.id, account_id: accountId, funding_id: id },
      },
      // Two tabs on one screen must not raise two charges.
      idempotencyKey: `wo-fund:${id}`,
    });
    await c.env.DB.prepare(`UPDATE wo_funding SET processor_intent_id = ? WHERE id = ?`)
      .bind(pi.id, id).run();
    await woEvent(c, { workOrderId: wo.id, kind: "funding.started",
      payload: { fundingId: id, amountCents: amount }, idemKey: `fund-start:${id}` });
    return c.json({ fundingId: id, clientSecret: pi.client_secret, amountCents: amount });
  } catch (err) {
    // The row stays, carrying why. A funding attempt that vanishes is a
    // screen that says nothing happened when a card was refused.
    await c.env.DB.prepare(`UPDATE wo_funding SET status = 'failed', error = ? WHERE id = ?`)
      .bind(String(err?.message || err).slice(0, 500), id).run();
    console.error("[escrow] fund failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// And confirm it.
//
// THE INTENT IS READ BACK FROM STRIPE, never believed from the browser. This is
// the same property `card-confirm` has and for a sharper reason: a route that
// took "it succeeded" from the caller would let anybody mark a work order
// funded without paying, and every gate below this one reads that figure.
app.post("/api/work-orders/:id/fund/confirm", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const b = await c.req.json().catch(() => ({}));

  let row;
  try {
    row = await c.env.DB.prepare(
      `SELECT * FROM wo_funding WHERE id = ? AND work_order_id = ?`
    ).bind(String(b.fundingId || ""), wo.id).first();
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    throw err;
  }
  if (!row) return c.json({ error: "not_found" }, 404);
  if (row.status === "funded") return c.json({ ok: true, status: "funded", already: true });
  if (!row.processor_intent_id) return c.json({ error: "not_started" }, 409);

  try {
    const pi = await stripeCall(c.env, `/payment_intents/${row.processor_intent_id}`,
      { method: "GET", params: { expand: ["latest_charge"] } });
    if (pi?.status !== "succeeded") {
      // Not an error: Stripe returns somebody to us whether they finished or
      // abandoned the sheet, exactly as onboarding does. What it is not is
      // funded, and saying so is the whole job.
      const why = pi?.last_payment_error?.message || null;
      if (why) {
        await c.env.DB.prepare(`UPDATE wo_funding SET error = ? WHERE id = ?`)
          .bind(String(why).slice(0, 500), row.id).run();
      }
      return c.json({ ok: false, status: pi?.status || "unknown", detail: why }, 409);
    }
    const charge = typeof pi.latest_charge === "string" ? pi.latest_charge : pi.latest_charge?.id;
    // Stripe is the authority on the amount too. A caller who could name it
    // could fund a dollar and claim five thousand.
    const landed = Math.round(Number(pi.amount_received ?? pi.amount) || 0);
    const res = await c.env.DB.prepare(
      `UPDATE wo_funding SET status = 'funded', amount_cents = ?, processor_charge_id = ?,
         error = NULL, funded_at = CURRENT_TIMESTAMP
       WHERE id = ? AND status <> 'funded'`
    ).bind(landed, charge || null, row.id).run();
    if (res.meta?.changes) {
      await woEvent(c, { workOrderId: wo.id, kind: "funding.received",
        payload: { fundingId: row.id, amountCents: landed, charge: charge || null },
        idemKey: `fund-ok:${row.id}` });
    }
    return c.json({ ok: true, status: "funded", amountCents: landed, ...(await woMoney(c, wo.id)) });
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    console.error("[escrow] confirm failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// Money out.
//
// Everything `settle` refuses, this refuses, plus the two things only a real
// rail can be refused for. The gates are not re-implemented -- a second
// opinion on whether cover is clear is a second place for it to be wrong.
app.post("/api/releases/:id/pay", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { accountId, userId } = c.get("auth");
  const r = await c.env.DB.prepare(`SELECT * FROM wo_releases WHERE id = ? AND account_id = ?`)
    .bind(c.req.param("id"), accountId).first();
  if (!r) return c.json({ error: "not_found" }, 404);
  const { wo, error } = await loadWorkOrder(c, r.work_order_id);
  if (error) return error;
  // 066. Not against a job that was cancelled or closed with nothing done.
  // `settle` and `pay` are two routes on purpose -- one records money that
  // moved elsewhere, one moves it -- so a gate on one of the two is a door
  // round it rather than a gate.
  { const no = await jobEndingBlocksPay(c, wo); if (no) return c.json(no, 409); }
  const b = await c.req.json().catch(() => ({}));

  let money, payee;
  try {
    money = await woMoney(c, wo.id);
    payee = await payeeState(c, r.company_id);
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    throw err;
  }

  // The facts first, because none of them is overridable and there is no
  // point asking somebody for a reason before saying the money is not there.
  //
  // THE AMOUNT IS THE RELEASE'S, never the body's. Same rule as the draft
  // route refusing `status`: a figure taken from the caller here is a figure
  // somebody chooses.
  // THE FEE THAT IS CHARGED IS WORKED OUT NOW, not the one stamped at verify.
  // The stamp counted releases still owed against the free allowance; this
  // counts only what has actually been paid through SubSub, which is what the
  // allowance is for. Written back before the money is checked, so the check,
  // the screen and the ledger all read the figure charged.
  if (r.status === "due") {
    const terms = await accountFeeTerms(c.env, r.account_id);
    const fee = feeFor({ gross: r.gross_cents, terms,
      processedBefore: await processedCents(c.env, r.account_id, { excludeReleaseId: r.id }) }).fee;
    if (fee !== (r.fee_cents || 0) || terms.bps !== r.fee_bps) {
      await c.env.DB.prepare(`UPDATE wo_releases SET fee_cents = ?, fee_bps = ? WHERE id = ? AND status = 'due'`)
        .bind(fee, terms.bps, r.id).run();
      r.fee_cents = fee; r.fee_bps = terms.bps;
      money = await woMoney(c, wo.id);
    }
  }
  const verdict = canPay({ release: { status: r.status, netCents: r.net_cents,
      feeCents: r.fee_cents || 0 },
    funding: money, payable: payee.payable === true });
  if (!verdict.ok) {
    return c.json({ error: verdict.reason, ...verdict, funding: money,
      payeeStatus: payee.status || "none" }, verdict.reason === "already_paid" ? 409 : 409);
  }

  // Then the two paperwork gates, in the same order and with the same
  // overrides `settle` uses. A /pay that skipped them would be a door round
  // the cover gate rather than a second rail through it.
  const cover = await coverStateFor(c, { wo, release: r });
  if (!cover.clear && !b.coverOverride) return c.json({ error: "cover_outstanding", cover }, 409);
  if (!cover.clear) {
    const whyCover = String(b.coverOverrideReason || "").trim().slice(0, 500);
    if (!whyCover) return c.json({ error: "cover_reason_required", cover }, 400);
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.cover_override",
      payload: { releaseId: r.id, reason: whyCover, cover } });
  }
  const chain = (await payingAccountOnScale(c.env, r.account_id))
    ? await waiverStateFor(c, { wo, release: r }) : { clear: true, reasons: [], onScale: false };
  if (!chain.clear && !b.override) return c.json({ error: "waiver_outstanding", ...chain }, 409);
  if (!chain.clear) {
    const why = String(b.overrideReason || "").trim().slice(0, 500);
    if (!why) return c.json({ error: "override_reason_required", ...chain }, 400);
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.override",
      payload: { releaseId: r.id, reason: why, chain } });
  }

  // The attempt row goes in FIRST, and the partial unique index on it is what
  // makes two people pressing pay at once cost one transfer. The same ordering
  // as the document upload for the same reason: a record that arrives after
  // the thing it records is a record that can be missing.
  const transferId = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO wo_transfers (id, release_id, work_order_id, account_id, company_id,
         amount_cents, currency, processor_destination, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(transferId, r.id, wo.id, accountId, r.company_id, r.net_cents, CURRENCY,
      payee.row?.processor_account_id || null, userId || null).run();
  } catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    if (/UNIQUE constraint failed/i.test(String(err?.message || err))) {
      return c.json({ error: "already_paying" }, 409);
    }
    throw err;
  }

  // Which funding this draws on, for `source_transaction`. Without it the
  // transfer needs the platform balance to be settled already and Stripe
  // refuses with `balance_insufficient`; with it Stripe queues the transfer
  // against that charge's own availability. So it is correctness, not a
  // nicety -- and it is also the link a reconciliation follows.
  const src = await c.env.DB.prepare(
    `SELECT processor_charge_id FROM wo_funding
      WHERE work_order_id = ? AND status = 'funded' AND processor_charge_id IS NOT NULL
      ORDER BY funded_at LIMIT 1`
  ).bind(wo.id).first();

  try {
    const tr = await stripeCall(c.env, "/transfers", {
      params: {
        amount: r.net_cents, currency: CURRENCY,
        destination: payee.row.processor_account_id,
        transfer_group: `wo:${wo.id}`,
        ...(src?.processor_charge_id ? { source_transaction: src.processor_charge_id } : {}),
        metadata: { release_id: r.id, work_order_id: wo.id, account_id: accountId },
      },
      idempotencyKey: `wo-pay:${r.id}`,
    });
    await c.env.DB.prepare(
      `UPDATE wo_transfers SET status = 'paid', processor_transfer_id = ?,
         paid_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(tr.id, transferId).run();

    // The release records the transfer that worked, through the seam 033 left
    // for exactly this: `method` names the rail and `reference` carries its id.
    const done = await c.env.DB.prepare(
      `UPDATE wo_releases SET status = 'paid', method = 'stripe', reference = ?,
         settled_at = CURRENT_TIMESTAMP, settled_by = ?
       WHERE id = ? AND status = 'due'`
    ).bind(tr.id, userId, r.id).run();
    // The money has gone and the release was already closed by somebody else --
    // recorded as paid by cheque, most likely, between the gate and the
    // transfer. It is the one state here that needs a person to look at it, so
    // it is said in three places rather than swallowed: the log, the ledger
    // event, and the reply, because a caller told plainly "paid" would never
    // ask. `m051_inv_transfer_without_paid` in CHECK.sql is the fourth.
    const orphan = !done.meta?.changes;
    if (orphan) {
      console.error("[escrow] transferred against a release that was not due:", r.id, tr.id);
    }
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.paid",
      payload: { releaseId: r.id, transferId, reference: tr.id, netCents: r.net_cents,
        feeCents: r.fee_cents, feeBps: r.fee_bps, retainageCents: r.retainage_cents,
        chainClear: chain.clear, coverClear: cover.clear,
        ...(orphan ? { orphan: true } : {}) },
      idemKey: `pay:${r.id}` });
    return c.json({ ok: true, status: "paid", reference: tr.id,
      netCents: r.net_cents, feeCents: r.fee_cents || 0,
      chainClear: chain.clear, coverClear: cover.clear,
      ...(orphan ? { alreadySettled: true } : {}),
      ...(await woMoney(c, wo.id)) });
  } catch (err) {
    // Failed, and marked failed rather than left pending -- the partial index
    // excludes 'failed' precisely so a refusal can be tried again.
    await c.env.DB.prepare(`UPDATE wo_transfers SET status = 'failed', error = ? WHERE id = ?`)
      .bind(String(err?.message || err).slice(0, 500), transferId).run();
    await woEvent(c, { workOrderId: wo.id, milestoneId: r.milestone_id, kind: "release.pay_failed",
      payload: { releaseId: r.id, transferId, detail: String(err?.message || err).slice(0, 500) } });
    console.error("[escrow] transfer failed:", err?.message || err);
    return c.json({ error: "stripe_failed", detail: String(err?.message || err) }, 502);
  }
});

// Money in with no way out is a trap, so unspent funding comes back.
//
// `refundableCents` is deliberately NOT the available balance: retainage is
// owed, it is simply not owed yet, and offering it back as "unspent" is how
// somebody refunds their way out of a holdback.
app.post("/api/work-orders/:id/refund", requireRole("admin"), async (c) => {
  if (!c.env.STRIPE_SECRET_KEY) return c.json({ error: "billing_not_configured" }, 501);
  const { wo, error } = await loadWorkOrder(c, c.req.param("id"));
  if (error) return error;
  const b = await c.req.json().catch(() => ({}));

  let money;
  try { money = await woMoney(c, wo.id); }
  catch (err) {
    if (missingSchema(err)) return c.json(fundingMigration(), 503);
    throw err;
  }
  const amount = Math.round(Number(b.amountCents) || money.refundableCents);
  if (amount <= 0) return c.json({ error: "nothing_refundable", funding: money }, 409);
  if (amount > money.refundableCents) {
    return c.json({ error: "over_refundable", funding: money }, 409);
  }

  // Newest first: the most recent money in is the least likely to have been
  // what a release already drew on.
  const { results: rows } = await c.env.DB.prepare(
    `SELECT * FROM wo_funding
      WHERE work_order_id = ? AND status = 'funded' AND processor_charge_id IS NOT NULL
      ORDER BY funded_at DESC`
  ).bind(wo.id).all();

  let left = amount;
  const done = [];
  for (const row of rows || []) {
    if (left <= 0) break;
    const spare = Math.max(0, row.amount_cents - row.refunded_cents);
    if (!spare) continue;
    const take = Math.min(spare, left);
    try {
      const rf = await stripeCall(c.env, "/refunds", {
        params: { charge: row.processor_charge_id, amount: take,
          metadata: { work_order_id: wo.id, funding_id: row.id } },
        idempotencyKey: `wo-refund:${row.id}:${row.refunded_cents + take}`,
      });
      await c.env.DB.prepare(
        `UPDATE wo_funding SET refunded_cents = refunded_cents + ?,
           status = CASE WHEN refunded_cents + ? >= amount_cents THEN 'refunded' ELSE status END
         WHERE id = ?`
      ).bind(take, take, row.id).run();
      done.push({ fundingId: row.id, amountCents: take, reference: rf.id });
      left -= take;
    } catch (err) {
      console.error("[escrow] refund failed:", err?.message || err);
      // Partial success is real and has to be reported as such: some money is
      // already on its way back and saying "it failed" would have somebody
      // press it again.
      return c.json({ error: "stripe_failed", detail: String(err?.message || err),
        refunded: done, funding: await woMoney(c, wo.id) }, 502);
    }
  }
  await woEvent(c, { workOrderId: wo.id, kind: "funding.refunded",
    payload: { amountCents: amount - left, parts: done } });
  return c.json({ ok: true, refunded: done, ...(await woMoney(c, wo.id)) });
});


// ---------------------------------------------------------------------------
// Move-in and move-out unit inspections.
//
// A managing agent walks a unit when somebody moves in and again when they
// move out, room by room, with photographs, and then raises the work. The
// rules are in shared/inspection.js so the routes, the screen and the job
// composed off the back of one cannot hold three opinions.
//
// WHO. `requireRole("admin", "pm")`, which is who walks units -- a scoped
// project manager most of all, since the buildings they are narrowed to are
// the buildings they inspect. NOT `canManage`: that is admin-only, and a
// screen stricter than its route is the same lie as looser, which this file
// has now paid for in both directions.
//
// WHOSE BUILDING. Every route resolves the inspection through
// `inspectionFor`, which joins it back to the account AND applies the seat's
// property scope -- one place rather than per route, because a scope added to
// nine places is a scope missing from the tenth.
// ---------------------------------------------------------------------------

// The row shapes the browser reads. Nothing here is derived twice: the tally
// and the flags come off shared/inspection.js wherever they are needed.
const inspectionRowToJs = (r) => ({
  id: r.id, propertyId: r.property_id, unit: r.unit || "", kind: r.kind,
  tenantName: r.tenant_name || "", inspectedOn: r.inspected_on || null,
  status: r.status, finishedAt: r.finished_at || null, jobId: r.job_id || null,
  createdAt: r.created_at, createdBy: r.created_by || null,
});
// `drafts` decides whether the model's unkept drafts travel. THE CAPTION IS
// THE RECORD AND THE DRAFT IS THE TEAM'S WORKING NOTE, so an owner reading
// their own report gets captions and nothing else -- a sentence nobody kept
// is not a thing this account has said about their building, and handing it
// over would make a working note read like a finding. Same line that keeps
// `recipients` and `sends` off a reading seat's copy.
const inspectionRoomToJs = (r, photos = [], { drafts = false } = {}) => ({
  id: r.id, name: r.name, status: r.status, note: r.note || "",
  position: r.position,
  // Ids and names only. The key is an R2 path and handing it to the browser
  // invites somebody to ask for a different one -- the same rule the avatar
  // and the report photo both follow.
  photos: photos.map((p) => ({
    id: p.id, name: p.name || "photo", type: p.content_type || "image/jpeg",
    caption: p.caption || "",
    ...(drafts ? { draft: p.draft || "", draftUnclear: !!p.draft_unclear } : {}),
  })),
});

// The one resolver. Answers `not_found` for an inspection on another account
// AND for one at a building this seat is not scoped to, deliberately the same
// reply: a 403 over a real id confirms which ids exist, which is the oracle
// the job-scope middleware already refuses to be.
async function inspectionFor(c, auth, id) {
  let row;
  try {
    row = await c.env.DB.prepare(
      `SELECT * FROM inspections WHERE id = ? AND account_id = ?`
    ).bind(id, auth.accountId).first();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return { error: "migration_needed", status: 503, migration: "055_inspections" };
    throw err;
  }
  if (!row) return { error: "not_found", status: 404 };
  if (!maySeeProperty(auth, row.property_id)) return { error: "not_found", status: 404 };
  // AN OWNER READS A FINISHED ONE AND NOTHING ELSE. The property scope above
  // already narrows them to their own buildings -- this is the second half:
  // a draft is a half-walked document and the whole reason finishing is gated
  // is that one with blanks in it says nothing while looking like it says
  // everything. The same answer as a building that is not theirs, so this
  // cannot be used to find out which drafts exist.
  // A ROLE THAT CANNOT WRITE ONE, rather than `owner` by name: the same
  // predicate the routes are built from, so a read-only role added later is
  // narrowed by this the day it exists rather than seeing every draft.
  if (!mayWriteInspection(auth.role) && row.status !== "finished") {
    return { error: "not_found", status: 404 };
  }
  return { row };
}

async function inspectionRooms(db, inspectionId, opts = {}) {
  const { results: rooms } = await db.prepare(
    `SELECT * FROM inspection_rooms WHERE inspection_id = ? ORDER BY position, created_at`
  ).bind(inspectionId).all();
  const list = rooms || [];
  if (!list.length) return [];
  // LEFT JOIN, because a photograph with nothing written about it is the
  // ordinary case and an inner join would drop every one of them -- which
  // reads as the photos having been deleted.
  let shots = [];
  try {
    ({ results: shots } = await db.prepare(
      `SELECT p.*, n.caption, n.draft, n.draft_unclear FROM inspection_photos p
         JOIN inspection_rooms r ON r.id = p.room_id
         LEFT JOIN inspection_photo_notes n ON n.photo_id = p.id
        WHERE r.inspection_id = ? ORDER BY p.created_at`
    ).bind(inspectionId).all());
  } catch (err) {
    // A database without 057 has no captions, which is the rooms drawn
    // without them rather than an inspection that will not open.
    if (!missingSchema(err)) throw err;
    ({ results: shots } = await db.prepare(
      `SELECT p.* FROM inspection_photos p
         JOIN inspection_rooms r ON r.id = p.room_id
        WHERE r.inspection_id = ? ORDER BY p.created_at`
    ).bind(inspectionId).all());
  }
  const byRoom = {};
  for (const p of shots || []) (byRoom[p.room_id] ||= []).push(p);
  return list.map((r) => inspectionRoomToJs(r, byRoom[r.id] || [], opts));
}

app.get("/api/inspections", requireRole(...INSPECTION_READ_ROLES), async (c) => {
  const auth = c.get("auth");
  // The property scope, in the SQL rather than after it: a list filtered in
  // the browser is a list the API sent.
  const scope = scopeClause(auth, "property_id");
  // The same rule `inspectionFor` applies one row at a time. In the SQL
  // rather than after it: a list filtered in the browser is a list the API
  // sent, and a draft of somebody's unit is not an owner's to read.
  const onlyDone = mayWriteInspection(auth.role) ? "" : " AND i.status = 'finished' ";
  let results = [];
  try {
    ({ results } = await c.env.DB.prepare(
      `SELECT i.*,
              (SELECT COUNT(*) FROM inspection_sends s WHERE s.inspection_id = i.id) AS n_sent,
              (SELECT COUNT(*) FROM inspection_rooms r WHERE r.inspection_id = i.id) AS n_rooms,
              (SELECT COUNT(*) FROM inspection_rooms r WHERE r.inspection_id = i.id
                 AND r.status IN ('follow_up','fail')) AS n_flagged,
              (SELECT COUNT(*) FROM inspection_rooms r WHERE r.inspection_id = i.id
                 AND r.status = 'unchecked') AS n_unchecked
         FROM inspections i
        WHERE i.account_id = ? ${scope.sql} ${onlyDone}
        ORDER BY COALESCE(i.inspected_on, i.created_at) DESC, i.created_at DESC
        LIMIT 200`
    ).bind(auth.accountId, ...scope.vals).all());
  } catch (err) {
    // A database without 055 has no inspections rather than a broken screen.
    if (!missingSchema(err)) throw err;
    return c.json([]);
  }
  // WHERE THE RAISED JOB GOT TO, which the list could not say.
  //
  // `jobId` is a fact about whether a row exists, so the chip read "Job
  // raised" on the day it was pressed and for ever afterwards -- the same two
  // words over a unit booked for Thursday, a unit whose crew has not answered
  // and a unit whose job was cancelled. Everything 061, 064 and 066 added
  // happens after that chip is earned and none of it reached it.
  //
  // Only the server can answer it: the browser holds no work orders and no
  // visits for a job it is not standing on, so a screen deriving this would be
  // guessing. One extra statement for the whole page rather than one per row.
  const rows = (results || []).map((r) => ({
    ...inspectionRowToJs(r),
    rooms: r.n_rooms, flagged: r.n_flagged, unchecked: r.n_unchecked,
    sent: r.n_sent || 0,
  }));
  return c.json(await withJobProgress(c.env, auth, rows));
});

// The job half of an inspection row. Separate from the query above because it
// reaches three tables the inspection does not know about, and because a
// database behind the code must cost the progress line and never the list.
async function withJobProgress(env, auth, rows) {
  const ids = [...new Set(rows.map((r) => r.jobId).filter(Boolean))];
  if (!ids.length) return rows;
  const marks = ids.map(() => "?").join(",");
  let jobs = [];
  try {
    ({ results: jobs } = await env.DB.prepare(
      `SELECT j.id, j.status, j.date, j.time, j.withdrawn_at, j.declined_at,
              (SELECT COUNT(*) FROM work_orders w
                WHERE w.job_id = j.id AND w.voided_at IS NULL) AS assigned,
              (SELECT COUNT(*) FROM work_orders w
                WHERE w.job_id = j.id AND w.voided_at IS NULL
                  AND w.status = 'accepted') AS accepted
         FROM jobs j
        WHERE j.id IN (${marks}) AND j.account_id = ?`
    ).bind(...ids, auth.accountId).all());
  } catch (err) {
    // A list that still lists is worth more than a line that says where one
    // of them got to, so this degrades to the row with no `job` on it and the
    // screen falls back to saying a job was raised.
    if (!missingSchema(err)) throw err;
    return rows;
  }
  const byId = {};
  for (const j of jobs || []) byId[j.id] = { ...j };
  // The newest LIVE window per job, read exactly as every other reader does
  // -- a job collects superseded proposals behind it, and taking whichever
  // row came back first is a date nobody agreed to drawn as the appointment.
  try {
    const { results: vs } = await env.DB.prepare(
      `SELECT * FROM visits
        WHERE job_id IN (${marks}) AND status IN ('proposed','confirmed')
        ORDER BY created_at ASC, rowid ASC`).bind(...ids).all();
    // Ascending, last-write-wins: the same answer as DESC + LIMIT 1 per job,
    // in one statement.
    for (const v of vs || []) if (byId[v.job_id]) byId[v.job_id].visit = visitRowToJs(v);
  } catch (err) { if (!missingSchema(err)) throw err; }
  try {
    const { results: es } = await env.DB.prepare(
      `SELECT e.job_id, e.kind, e.note, e.until, e.at FROM job_endings e
        WHERE e.job_id IN (${marks})
        ORDER BY e.at ASC, e.rowid ASC`).bind(...ids).all();
    for (const e of es || []) {
      if (!byId[e.job_id]) continue;
      Object.assign(byId[e.job_id], { ending_kind: e.kind, ending_note: e.note,
        ending_until: e.until, ending_at: e.at });
    }
  } catch (err) { if (!missingSchema(err)) throw err; }
  const today = dayKeyUtc();
  return rows.map((r) => {
    const j = r.jobId ? byId[r.jobId] : null;
    if (!j) return r;
    return { ...r, job: jobProgress(j, { today, when: workWhen(j) }) };
  });
}

app.post("/api/inspections", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  if (!isInspectionKind(b.kind)) return c.json({ error: "bad_kind" }, 400);
  // The building is the only thing that decides whose this is, and a id in
  // the body is a claim: joining it back to the account is what makes it
  // true. A building this seat is not scoped to answers identically to one
  // that does not exist.
  const prop = await c.env.DB.prepare(
    `SELECT id FROM properties WHERE id = ? AND account_id = ?`
  ).bind(String(b.propertyId || ""), auth.accountId).first();
  if (!prop || !maySeeProperty(auth, prop.id)) return c.json({ error: "property_not_found" }, 404);

  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO inspections (id, account_id, property_id, unit, kind, tenant_name, inspected_on, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(id, auth.accountId, prop.id,
      String(b.unit || "").trim().slice(0, 40) || null, String(b.kind),
      String(b.tenantName || "").trim().slice(0, 120) || null,
      String(b.inspectedOn || "").trim().slice(0, 10) || null, auth.userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (migration) return c.json({ error: "migration_needed", migration: "055_inspections" }, 503);
    throw err;
  }
  await logActivity(c.env, auth.accountId, auth.userId, "inspection_started",
    `Started a ${INSPECTION_KINDS[b.kind].label.toLowerCase()} inspection${b.unit ? ` of unit ${b.unit}` : ""}`);
  const row = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`).bind(id).first();
  return c.json({ ...inspectionRowToJs(row), rooms: [] }, 201);
});

// Who may be sent this report, and who already has it. Both are read from
// the one place that decides: a seat on THIS account, with the role `owner`,
// scoped to THIS building. An owner reading their own copy gets neither --
// who else was told is the account's record of what it did, not a fact the
// recipient needs, and the shortest way to keep it that way is not to send it.
async function inspectionAudience(db, row) {
  const { results: owners } = await db.prepare(
    `SELECT u.id, u.name, u.email FROM memberships m
       JOIN users u ON u.id = m.user_id
       JOIN membership_properties mp ON mp.membership_id = m.id
      WHERE m.account_id = ? AND m.role = 'owner' AND mp.property_id = ?
      ORDER BY u.name`
  ).bind(row.account_id, row.property_id).all();
  let sends = [];
  try {
    ({ results: sends } = await db.prepare(
      `SELECT user_id, sent_at, emailed FROM inspection_sends
        WHERE inspection_id = ? ORDER BY sent_at DESC`
    ).bind(row.id).all());
  } catch (err) {
    // A database without 056 has sent nobody anything, which is a panel with
    // no history rather than a screen that fails to load.
    if (!missingSchema(err)) throw err;
  }
  return {
    recipients: (owners || []).map((u) => ({ id: u.id, name: u.name, email: realEmail(u.email) })),
    sends: (sends || []).map((r) => ({ userId: r.user_id, at: r.sent_at, emailed: !!r.emailed })),
  };
}

app.get("/api/inspections/:id", requireRole(...INSPECTION_READ_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  const base = { ...inspectionRowToJs(row), rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }),
    // On EVERY copy, the owner's included. A report that was changed after it
    // was finished has to say so to the person who will quote it, or the
    // reopening is exactly the edit-after-the-fact a deposit argument turns on.
    reopens: await inspectionReopens(c.env.DB, row.id) };
  // WHO ELSE WAS TOLD IS THE TEAM'S OWN RECORD. The audience is the other
  // owners' names and addresses, which is not a reading seat's to collect --
  // the same rule that keeps an overflow distribution list server-side.
  if (!mayWriteInspection(auth.role)) return c.json(base);
  // WHETHER DRAFTING CAN WORK AT ALL, so the button is drawn exactly when
  // the route would take it. Without this the screen either offers a press
  // that answers 503 -- a dead end with no explanation on it -- or withholds
  // one that would have worked, and this project calls those the same lie.
  // On the payload rather than derived in the browser, because only the
  // Worker knows whether there is a key: the same reason
  // `mail_not_configured` is reported rather than guessed.
  // THE SUMMARY THE WORK ORDER CARRIES, on the team's copy only. An owner
  // reading their own report gets the rooms, the notes and the captions and
  // deliberately not this: the report is what a deposit argument is run from,
  // and a model's paragraph in it would read as a finding somebody made. The
  // manager sees it because they are answerable for what their work order
  // says. `aiDrafts` is read for this too -- it means "SubSub has a model
  // key", which is one fact, and a second field with the same value in it is
  // two records of one.
  // WHERE THE RAISED JOB GOT TO, through the same one function the list uses.
  // The button under this read *Open the job raised from this* and said
  // nothing about whether anybody is coming, which is the question somebody
  // standing on a finished walk actually has.
  const [withJob] = await withJobProgress(c.env, auth, [base]);
  return c.json({ ...withJob, aiDrafts: aiConfigured(c.env),
    summary: summaryShape(await inspectionSummaryRow(c.env.DB, row.id), inspectionRowToJs(row), base.rooms),
    ...(await inspectionAudience(c.env.DB, row)) });
});

// SENDING THE REPORT TO THE BUILDING'S OWNER.
//
// A move-in and a move-out report are the two documents a deposit argument is
// run from, and the owner of the building is the one person besides the agent
// who has to be able to produce them.
//
// IT IS A LINK INTO THEIR OWN SEAT, not an attachment and not a public token.
// They were invited onto this account scoped to exactly this building, so the
// permission already exists and is already right; minting a token would be a
// second surface, a second expiry and a second thing to revoke, for somebody
// who can already sign in. It also means the record stays live rather than
// being a copy that starts going stale the moment it is sent -- the same
// reason the compliance pack is a link rather than a PDF.
//
// FINISHED ONLY. `whyNotSend` is the shared rule, and it is the same gate
// `whyNotFinish` enforces one step earlier: a half-walked document says
// nothing while looking like it says everything, and sending one would undo
// that by a different door.
app.post("/api/inspections/:id/send", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  const why = whyNotSend(inspectionRowToJs(row));
  if (why) return c.json({ error: why }, 409);

  const { recipients } = await inspectionAudience(c.env.DB, row);
  // Once. A Request body is a stream and reading it twice gets nothing the
  // second time -- which would have read as "you picked nobody".
  const b = await c.req.json().catch(() => ({}));
  const asked = Array.isArray(b.userIds) ? b.userIds.map(String) : [];
  // AN ID IN THE BODY IS A CLAIM. Intersected with the audience rather than
  // trusted, so naming any other user id on the platform sends them nothing
  // -- the report would otherwise reach somebody with no seat to read it on
  // and no relationship to the building.
  const to = recipients.filter((u) => asked.includes(u.id));
  if (!to.length) return c.json({ error: "no_recipients", recipients: recipients.length }, 400);

  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(row.account_id).first();
  const prop = await c.env.DB.prepare(`SELECT name FROM properties WHERE id = ?`).bind(row.property_id).first();
  const rooms = await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) });
  const tally = inspectionTally(rooms);
  const link = `${accountOrigin(account)}/`;

  const done = [];
  for (const u of to) {
    const mail = inspectionReportEmail({
      firstName: String(u.name || "").split(" ")[0],
      account, kindLabel: INSPECTION_KINDS[row.kind]?.label || "Inspection",
      propertyName: prop?.name, unit: row.unit, walkedOn: row.inspected_on,
      tenantName: row.tenant_name, rooms: tally.rooms, flagged: tally.flagged, link,
    });
    const sent = u.email ? await sendEmail(c.env, { to: u.email, ...mail }) : { ok: false, error: "no_recipient" };
    try {
      await c.env.DB.prepare(
        `INSERT INTO inspection_sends (id, inspection_id, user_id, sent_by, emailed)
         VALUES (?, ?, ?, ?, ?)`
      ).bind(uid(), row.id, u.id, auth.userId, sent.ok ? 1 : 0).run();
    } catch (err) {
      const migrationNeeded = missingSchema(err);
      if (!migrationNeeded) throw err;
      return c.json({ error: "migration_needed", migration: "056_inspection_sends" }, 503);
    }
    // THE ROW RECORDS WHETHER IT WENT, rather than that it was pressed. A
    // send marked true over a mail failure is the lie `sent_at` exists to
    // refuse, and it is the reason an owner says they never got it while the
    // screen says they did.
    done.push({ userId: u.id, name: u.name, emailed: !!sent.ok, error: sent.ok ? null : sent.error });
  }
  await logActivity(c.env, row.account_id, auth.userId, "inspection_sent",
    `Sent the ${INSPECTION_KINDS[row.kind]?.label.toLowerCase() || ""} inspection${
      row.unit ? ` of unit ${row.unit}` : ""} to ${done.map((d) => d.name).join(", ")}`);
  return c.json({ ok: true, sent: done, ...(await inspectionAudience(c.env.DB, row)) });
});

// EVERY TIME A FINISHED INSPECTION WAS OPENED AGAIN, oldest first: who, when,
// why, and when it had been finished. Read off the event log rather than a
// table of its own -- `events` is append-only and already keyed by subject,
// and a reopen is an event about the inspection rather than a fact the
// inspection carries. Names are resolved here so the screen never shows an id.
async function inspectionReopens(db, inspectionId) {
  try {
    const { results } = await db.prepare(
      `SELECT e.created_at, e.payload, u.name AS by_name FROM events e
         LEFT JOIN users u ON u.id = e.actor_id
        WHERE e.kind = 'inspection.reopened' AND e.subject_id = ?
        ORDER BY e.created_at, e.id`).bind(inspectionId).all();
    return (results || []).map((r) => {
      const p = parseJson(r.payload, {}) || {};
      return { at: r.created_at, by: r.by_name || "Somebody", reason: p.reason || "",
        finishedAt: p.finishedAt || null };
    });
  } catch (err) {
    console.warn("[inspection] reopen history unavailable:", err?.message || err);
    return [];
  }
}

// REOPENING A FINISHED INSPECTION, which the door below used to refuse for
// ever. Asked for as *"need to be able to edit and go back to original
// inspection, add rooms after you finalize as well"* -- a room missed on the
// walk, a note written in the wrong room, found after Finish was pressed.
//
// What finishing protected is still protected, by a different means. The
// danger was never that a record changes; it is that it changes WITHOUT
// TRACE, so the other side of a deposit argument can say it was edited after
// the fact and nobody can say what changed or when. So a reopen is a recorded
// act: a reason is required, it is written to the event log with the person
// and the time it had been finished, and every copy of the report -- the
// owner's included -- lists it. Re-finishing goes through the same gate as the
// first time.
//
// It goes back to a DRAFT, which means an owner it was sent to cannot open it
// until it is finished again: a half-edited record must not read as the
// report, which is the reason drafts are refused to them at all.
app.post("/api/inspections/:id/reopen", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status !== "finished") return c.json({ error: "not_finished" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const reason = String(b.reason || "").trim().slice(0, 500);
  if (reason.length < 3) return c.json({ error: "reason_required" }, 400);
  // Guarded on the status in the UPDATE, so two presses reopen once and the
  // second answers rather than logging a reopen that did not happen.
  const res = await c.env.DB.prepare(
    `UPDATE inspections SET status = 'draft', finished_at = NULL WHERE id = ? AND status = 'finished'`
  ).bind(row.id).run();
  if (!res.meta?.changes) return c.json({ error: "not_finished" }, 409);
  await logEvent(c.env, row.account_id, auth.userId, "inspection.reopened", row.id,
    { reason, finishedAt: row.finished_at || null });
  await logActivity(c.env, row.account_id, auth.userId, "inspection_reopened",
    `Reopened the ${INSPECTION_KINDS[row.kind]?.label.toLowerCase() || ""} inspection${
      row.unit ? ` of unit ${row.unit}` : ""} to change it: ${reason}`);
  const after = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`).bind(row.id).first();
  return c.json({ ...inspectionRowToJs(after),
    rooms: await inspectionRooms(c.env.DB, row.id, { drafts: true }),
    reopens: await inspectionReopens(c.env.DB, row.id) });
});

// The header fields, and finishing.
//
// FINISHED SHUTS THE RECORD, which is the point of it: an inspection is
// evidence in a deposit argument months later, and a record that can be
// edited after the fact is one the other side can say was edited after the
// fact. Everything stays readable; nothing stays writable -- until somebody
// REOPENS it through the route above, which records who, when and why, and
// is the only way back to a draft.
app.patch("/api/inspections/:id", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const has = (k) => Object.prototype.hasOwnProperty.call(b, k);

  if (b.finish === true) {
    const rooms = await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) });
    // The gate is the shared one, so the screen and the route cannot
    // disagree about what a finished inspection is.
    const why = whyNotFinish(rooms, { jobId: row.job_id });
    if (why) return c.json({ error: why, unchecked: inspectionTally(rooms).unchecked }, 409);
    await c.env.DB.prepare(
      `UPDATE inspections SET status = 'finished', finished_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(row.id).run();
    await logActivity(c.env, auth.accountId, auth.userId, "inspection_finished",
      `Finished a ${INSPECTION_KINDS[row.kind]?.label.toLowerCase() || ""} inspection${row.unit ? ` of unit ${row.unit}` : ""}`);
    // THE SUMMARY, WRITTEN WHEN THE WALK IS DONE.
    //
    // Asked for as *"write a summary automatically when inspection is done"*,
    // and it is the earliest honest moment there is. Finishing is the one-way
    // door: every room is marked, every note is typed, every caption somebody
    // meant to keep is kept, and nothing about the record can change again.
    // Before that the notes are still moving, which is exactly what makes a
    // paragraph go stale.
    //
    // It joins the two doors that already write one -- raising the job, and
    // issuing a work order -- through the same guarded helper, so there are
    // three moments and ONE rule. Writes only when there is nothing there, so
    // a walk finished after the job was raised costs nothing; never blocks,
    // for the reason neither of the others does; and says which it was on the
    // reply rather than leaving a null to be read two ways.
    const summarised = await summariseInspection(c,
      { inspection: row, accountId: auth.accountId, userId: auth.userId });
    const after = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`).bind(row.id).first();
    return c.json({ ...inspectionRowToJs(after), rooms, summarised });
  }

  // Only what was sent, the shape that deleted a W-9 through SubForm.
  const sets = [], vals = [];
  if (has("unit")) { sets.push("unit = ?"); vals.push(String(b.unit || "").trim().slice(0, 40) || null); }
  if (has("tenantName")) { sets.push("tenant_name = ?"); vals.push(String(b.tenantName || "").trim().slice(0, 120) || null); }
  if (has("inspectedOn")) { sets.push("inspected_on = ?"); vals.push(String(b.inspectedOn || "").trim().slice(0, 10) || null); }
  if (has("kind")) {
    if (!isInspectionKind(b.kind)) return c.json({ error: "bad_kind" }, 400);
    sets.push("kind = ?"); vals.push(String(b.kind));
  }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);
  await c.env.DB.prepare(`UPDATE inspections SET ${sets.join(", ")} WHERE id = ?`).bind(...vals, row.id).run();
  const after = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`).bind(row.id).first();
  return c.json({ ...inspectionRowToJs(after), rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

app.delete("/api/inspections/:id", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  // A finished one is a record somebody may be relying on. A draft is
  // somebody's half-written note and deleting it costs nothing.
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  await c.env.DB.prepare(`DELETE FROM inspections WHERE id = ?`).bind(row.id).run();
  return c.json({ ok: true });
});

// A room. The name is free text with a suggested list on the screen; the
// status starts `unchecked`, which is a real answer.
app.post("/api/inspections/:id/rooms", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  const b = await c.req.json().catch(() => ({}));
  const name = String(b.name || "").trim().slice(0, 80);
  if (!name) return c.json({ error: "name_required" }, 400);
  const n = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n, COALESCE(MAX(position), -1) AS last FROM inspection_rooms WHERE inspection_id = ?`
  ).bind(row.id).first();
  if (n.n >= MAX_ROOMS) return c.json({ error: "too_many_rooms", max: MAX_ROOMS }, 409);
  const id = uid();
  await c.env.DB.prepare(
    `INSERT INTO inspection_rooms (id, inspection_id, name, status, note, position)
     VALUES (?, ?, ?, 'unchecked', NULL, ?)`
  ).bind(id, row.id, name, Number(n.last) + 1).run();
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) }, 201);
});

app.patch("/api/inspections/:id/rooms/:roomId", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  // Joined back to THIS inspection, so a room id from another one is a miss
  // rather than a way to edit it.
  const room = await c.env.DB.prepare(
    `SELECT * FROM inspection_rooms WHERE id = ? AND inspection_id = ?`
  ).bind(c.req.param("roomId"), row.id).first();
  if (!room) return c.json({ error: "not_found" }, 404);
  const b = await c.req.json().catch(() => ({}));
  const has = (k) => Object.prototype.hasOwnProperty.call(b, k);
  const sets = [], vals = [];
  if (has("name")) {
    const name = String(b.name || "").trim().slice(0, 80);
    if (!name) return c.json({ error: "name_required" }, 400);
    sets.push("name = ?"); vals.push(name);
  }
  if (has("status")) {
    if (!isRoomStatus(b.status)) return c.json({ error: "bad_status" }, 400);
    sets.push("status = ?"); vals.push(String(b.status));
  }
  if (has("note")) { sets.push("note = ?"); vals.push(String(b.note || "").trim().slice(0, 2000) || null); }
  if (has("position")) { sets.push("position = ?"); vals.push(Math.max(0, Math.min(999, Number(b.position) || 0))); }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);
  await c.env.DB.prepare(`UPDATE inspection_rooms SET ${sets.join(", ")} WHERE id = ?`)
    .bind(...vals, room.id).run();
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

app.delete("/api/inspections/:id/rooms/:roomId", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  const res = await c.env.DB.prepare(
    `DELETE FROM inspection_rooms WHERE id = ? AND inspection_id = ?`
  ).bind(c.req.param("roomId"), row.id).run();
  if (!res.meta?.changes) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

// Photos, attached after the bytes are already in R2 through
// /api/uploads/report-photo/... -- the same kind, deliberately, because it is
// the one upload kind that checks the type and the size, and an inspection
// photo is the same thing from the same phone. A second kind would be a
// second set of limits to keep in step.
app.post("/api/inspections/:id/rooms/:roomId/photos", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  const room = await c.env.DB.prepare(
    `SELECT * FROM inspection_rooms WHERE id = ? AND inspection_id = ?`
  ).bind(c.req.param("roomId"), row.id).first();
  if (!room) return c.json({ error: "not_found" }, 404);
  const have = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM inspection_photos WHERE room_id = ?`).bind(room.id).first();
  if (have.n >= MAX_ROOM_PHOTOS) return c.json({ error: "too_many", max: MAX_ROOM_PHOTOS }, 409);

  const b = await c.req.json().catch(() => ({}));
  const stmts = [];
  let added = 0;
  for (const p of Array.isArray(b.photos) ? b.photos : []) {
    const key = String(p?.key || "");
    // THE KEY IS CHECKED, NEVER TRUSTED. It is a path into R2 and the caller
    // names it, so without this a key under another account's prefix would be
    // attached and then served back by the route below.
    if (!key.startsWith(`${auth.accountId}/report-photo/`) || key.includes("..")) continue;
    const type = String(p?.type || "").toLowerCase();
    stmts.push(c.env.DB.prepare(
      `INSERT INTO inspection_photos (id, room_id, file_key, name, content_type)
       VALUES (?, ?, ?, ?, ?)`
    ).bind(uid(), room.id, key, String(p?.name || "photo").slice(0, 120),
      PHOTO_TYPES.has(type) ? type : "image/jpeg"));
    if (have.n + ++added >= MAX_ROOM_PHOTOS) break;
  }
  if (!stmts.length) return c.json({ error: "nothing_to_add" }, 400);
  await c.env.DB.batch(stmts);
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

app.delete("/api/inspections/:id/rooms/:roomId/photos/:photoId", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  // Pinned three ways, like every other document route here: the token is the
  // inspection, the inspection names the room, and the room names the photo.
  const res = await c.env.DB.prepare(
    `DELETE FROM inspection_photos WHERE id = ? AND room_id IN
       (SELECT id FROM inspection_rooms WHERE id = ? AND inspection_id = ?)`
  ).bind(c.req.param("photoId"), c.req.param("roomId"), row.id).run();
  if (!res.meta?.changes) return c.json({ error: "not_found" }, 404);
  // The object stays in R2. A photo taken off a room is still evidence of
  // what was walked, and an accidental removal a minute after uploading is
  // far the likelier event -- the same reasoning the report photo follows.
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

// KEEPING A CAPTION. The field under a photograph, saved on blur like the
// room's own note.
//
// This is the route that makes a draft into the record, and it is the only
// one: nothing promotes a draft by itself. The caption is written from what
// the browser sends -- which is what the person had in the box, draft or
// their own words or the two mixed -- so keeping an unedited draft and
// typing the same sentence are the same act and produce the same row. The
// draft is left alongside, untouched, because "what did the model say" is a
// question worth being able to answer after somebody has edited it.
app.patch("/api/inspections/:id/rooms/:roomId/photos/:photoId", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.status === "finished") return c.json({ error: "already_finished" }, 409);
  // Pinned three ways, as every other route on a photograph is: the
  // inspection, then the room on it, then the photo in that room. An id in
  // the body or the path is a claim and the join is what makes it true.
  const photo = await c.env.DB.prepare(
    `SELECT p.id FROM inspection_photos p
       JOIN inspection_rooms r ON r.id = p.room_id
      WHERE p.id = ? AND r.id = ? AND r.inspection_id = ?`
  ).bind(c.req.param("photoId"), c.req.param("roomId"), row.id).first();
  if (!photo) return c.json({ error: "not_found" }, 404);

  const b = await c.req.json().catch(() => ({}));
  const caption = String(b.caption ?? "").trim().slice(0, MAX_CAPTION);
  try {
    await c.env.DB.prepare(
      `INSERT INTO inspection_photo_notes (photo_id, caption, updated_at)
       VALUES (?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(photo_id) DO UPDATE SET caption = excluded.caption, updated_at = CURRENT_TIMESTAMP`
    ).bind(photo.id, caption || null).run();
  } catch (err) {
    const migrationNeeded = missingSchema(err);
    if (migrationNeeded) return c.json({ error: "migration_needed", migration: "057_photo_captions" }, 503);
    throw err;
  }
  return c.json({ ok: true, rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

// DRAFTING THE PHOTO NOTES.
//
// A managing agent photographs forty things in a flat and then writes forty
// sentences about them, most of which the photograph already says. So the
// model drafts each line and they correct it.
//
// A DRAFT IS NOT THE RECORD. It is written to `draft`, never to `caption`,
// and the report the owner reads carries captions only -- so a draft nobody
// kept is a working note and not something this account has said about
// somebody's home. The route beside this one is the only way across, and it
// needs a press. Same shape as the document review's own draft, which is
// stored beside `status` rather than as it for the same reason.
//
// FINISHED IS REFUSED, because drafting writes to the inspection and
// finishing is a one-way door -- the gate `whyNotDraft` holds and CHECK.sql
// counts. Everything about the request itself -- the model, the prompt, the
// schema, the size, the caps -- is in `shared/photodraft.js`, so the screen
// and the tests read the same rules the route does.
//
// THE PICTURES ARRIVE FROM THE BROWSER, DOWNSCALED, AND ARE CAPPED HERE.
// Claude bills a photograph by area, so a full-size phone picture costs four
// times what 1120px does for detail nobody needs to see a scuffed wall. A
// Worker cannot resize an image, so the browser does it -- it already holds
// the bytes it drew the thumbnail from. What makes that safe is that none of
// it is trusted: every id must be a photograph OF THIS ROOM, and
// MAX_DRAFT_BYTES is the ceiling, so a hand-made request cannot cost more
// than a real press.
app.post("/api/inspections/:id/rooms/:roomId/drafts", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  // One predicate, the same one the button reads, so the screen cannot offer
  // what this refuses. `photos` and `undrafted` are counted below; what is
  // known here is the two that do not need the room.
  const early = whyNotDraft({
    finished: row.status === "finished",
    configured: aiConfigured(c.env),
    photos: 1, undrafted: 1,
  });
  if (early) return c.json({ error: early }, early === "ai_not_configured" ? 503 : 409);

  const room = await c.env.DB.prepare(
    `SELECT * FROM inspection_rooms WHERE id = ? AND inspection_id = ?`
  ).bind(c.req.param("roomId"), row.id).first();
  if (!room) return c.json({ error: "not_found" }, 404);

  // PER ACCOUNT, because every press spends real money and the one thing a
  // rate limit has to stop is a loop. Forty presses an hour is far more
  // walking than anybody does in one and well short of a bill worth
  // noticing.
  const rl = await rateLimit(c.env, "photo-draft", auth.accountId, { limit: 40, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "rate_limited" }, 429);

  const { results: have } = await c.env.DB.prepare(
    `SELECT id FROM inspection_photos WHERE room_id = ? ORDER BY created_at`
  ).bind(room.id).all();
  const mine = new Set((have || []).map((p) => p.id));

  const b = await c.req.json().catch(() => ({}));
  const want = [];
  for (const p of Array.isArray(b.photos) ? b.photos : []) {
    const id = String(p?.id || "");
    // THE ID IS CHECKED, NEVER TRUSTED -- the same rule the attach route
    // applies to an R2 key. Without this a photograph on another room, or
    // another account's inspection, would be read and captioned.
    if (!mine.has(id)) continue;
    const data = String(p?.data || "");
    if (!data) continue;
    // The ceiling, and it is the whole of what stops a hand-made request
    // costing more than a press. Base64 is 4 characters per 3 bytes.
    if (data.length * 3 / 4 > MAX_DRAFT_BYTES) return c.json({ error: "too_big" }, 413);
    want.push({ id, data });
    if (want.length >= MAX_DRAFT_PHOTOS) break;
  }
  if (!want.length) return c.json({ error: "no_photos" }, 400);

  // Images before the text that asks about them, each introduced by the
  // label the answer refers back to -- which is what makes `ref` mean
  // something rather than a position in an array.
  const content = [];
  want.forEach((p, i) => {
    content.push({ type: "text", text: `Photo ${i + 1}:` });
    // Always JPEG: the browser re-encodes when it downscales, so the type
    // is a fact about our own pipeline rather than something to read off the
    // original -- and the original may be HEIC, which this API does not take.
    content.push({ type: "image", source: { type: "base64", media_type: "image/jpeg", data: p.data } });
  });
  content.push({ type: "text", text: draftContext({
    roomName: room.name, note: room.note || "", count: want.length,
  }) });

  let drafts;
  try {
    const msg = await claudeCall(c.env, {
      model: DRAFT_MODEL,
      // Enough for a sentence or two per photograph and no more. A caption
      // is a line; a cap that allowed an essay would invite one.
      max_tokens: 120 * want.length + 200,
      system: draftSystem({ kindLabel: INSPECTION_KINDS[row.kind]?.label || "Move-in" }),
      messages: [{ role: "user", content }],
      // THINKING OFF, deliberately, and the spelling comes off the model
      // rather than being written here. Describing what is in a photograph
      // is perception rather than reasoning, and thinking is billed as
      // output -- turning it on would multiply what a one-line caption
      // costs for nothing anybody would read. The reason it is not a
      // literal: the models disagree about how to say it, so a model swap
      // with a hard-coded setting beside it is a 400 on the first real
      // press. `draftThinking` answers null where the field must be left
      // off, which the spread below then omits entirely.
      ...(draftThinking() ? { thinking: draftThinking() } : {}),
      // Structured output rather than "reply with only JSON": a caption
      // about a cracked basin carries an apostrophe or a quoted measurement
      // sooner or later, and free-text JSON fails on exactly that.
      output_config: { format: { type: "json_schema", schema: DRAFT_SCHEMA } },
    });
    drafts = readDrafts(replyJson(msg), want.length);
  } catch (err) {
    // NARROW IN WHAT IT PROMISES, WIDE IN WHAT IT CATCHES, and the two are
    // different things. Nothing was written, so "try again" is always true
    // and is what the screen says; what is NOT done is swallow it silently,
    // because the person pressed the button and is waiting.
    console.warn("[photo-draft] not drafted:", err?.code || "", err?.message || err);
    return c.json({ error: err?.message === "ai_not_configured" ? "ai_not_configured" : "ai_unavailable" },
      err?.message === "ai_not_configured" ? 503 : 502);
  }
  if (!drafts.length) return c.json({ error: "ai_unavailable" }, 502);

  const now = new Date().toISOString();
  try {
    await c.env.DB.batch(drafts.map((d) => c.env.DB.prepare(
      `INSERT INTO inspection_photo_notes (photo_id, draft, draft_unclear, drafted_at, drafted_by, updated_at)
       VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(photo_id) DO UPDATE SET
         draft = excluded.draft, draft_unclear = excluded.draft_unclear,
         drafted_at = excluded.drafted_at, drafted_by = excluded.drafted_by,
         updated_at = CURRENT_TIMESTAMP`
    // The caption is deliberately absent from both halves of that upsert. A
    // re-draft must not overwrite a sentence somebody has already kept --
    // which is the one way this feature could destroy the record it exists
    // to help write.
    ).bind(want[d.ref - 1].id, d.draft, d.unclear ? 1 : 0, now, auth.userId)));
  } catch (err) {
    const migrationNeeded = missingSchema(err);
    if (migrationNeeded) return c.json({ error: "migration_needed", migration: "057_photo_captions" }, 503);
    throw err;
  }
  await logActivity(c.env, auth.accountId, auth.userId, "inspection_drafted",
    `Drafted notes for ${drafts.length} photo${drafts.length === 1 ? "" : "s"} in ${room.name}`);
  return c.json({ ok: true, drafted: drafts.length,
    rooms: await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) }) });
});

// ---------------------------------------------------------------------------
// THE SUMMARY A WORK ORDER CARRIES
// ---------------------------------------------------------------------------
//
// Asked for as: *"A work order should also carry a summary of all of the
// comments from the follow up or flagged item to give as a summary for the
// subcontractor. Combine the comments and summarize automatically."*
//
// 062 carries the flagged rooms, their notes and their photographs to whoever
// is going to do the work, which is the record. What a list of rooms cannot
// say about itself is what the job IS, taken together -- that eleven lines
// about scuffing are one repaint across four rooms plus one tap -- and that is
// the first thing somebody pricing it wants. So the comments are combined
// once, at the top.
//
// EVERY RULE ABOUT THE REQUEST IS IN `shared/inspectsummary.js`: the model,
// the prompt, the schema, what gets summarised and the caps. The route calls
// out and stores; what to ask is that module's business.

// WHICH MIGRATIONS CAN BE BEHIND THIS, answered without failing. A database
// without 063 has no summaries, which is a work order drawn without one
// rather than a modal that will not open -- the same degradation
// `inspectionRooms` makes for 057's captions one table along.
async function inspectionSummaryRow(db, inspectionId) {
  try {
    return await db.prepare(
      `SELECT summary, source, model, written_at FROM inspection_summaries WHERE inspection_id = ?`
    ).bind(inspectionId).first();
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return null;
  }
}

// The statuses the refusals answer with. A table rather than a chain of
// ternaries, because the reasons live in the shared module and a reason added
// there must arrive here with a status rather than falling through to 502 --
// which would tell somebody to try again over a gate that will never open.
const SUMMARY_STATUS = {
  ai_not_configured: 503,
  migration_needed: 503,
  nothing_flagged: 409,
  no_comments: 409,
  rate_limited: 429,
  ai_unavailable: 502,
};

// THE ONE WRITER, used by both doors -- the automatic one at raise time and
// the rewrite -- so they cannot disagree about what gets asked, what gets
// stored, or what the activity trail says. Two copies of an outbound call
// this specific is two places for the prompt to rot.
//
// IT ANSWERS RATHER THAN THROWING, because one of its two callers has already
// created a job by the time it runs and must not fail on account of a
// paragraph.
async function writeInspectionSummary(c, auth, row, rooms) {
  const insp = inspectionRowToJs(row);
  const flagged = flaggedRooms(rooms).length;
  // The same predicate the button reads, so the screen cannot offer what this
  // refuses. `no_comments` is the one that matters: with nothing written on
  // any flagged room there is nothing to combine, and a model handed two room
  // names and a status will write a confident sentence about what is wrong
  // with them. An invented fault on a document somebody is about to quote
  // reads exactly like a real one.
  const why = whyNotSummary({
    configured: aiConfigured(c.env),
    flagged,
    comments: countComments(insp, rooms),
  });
  if (why) return { error: why };

  // PER ACCOUNT, because every call spends real money and the one thing a
  // limit has to stop is a loop. Lower than the drafts' forty: a summary is
  // one per inspection rather than one per room.
  const rl = await rateLimit(c.env, "inspection-summary", auth.accountId, { limit: 30, windowMinutes: 60 });
  if (!rl.ok) return { error: "rate_limited" };

  // WHAT IS BEING SUMMARISED, HELD RATHER THAN RE-DERIVED AFTERWARDS. This
  // exact text is both what the model is given and what gets stored, so the
  // staleness comparison is against the thing it actually read -- the rule
  // `agreements` follows by hashing what the signer was shown.
  const source = summarySource(insp, rooms);
  let text;
  try {
    const msg = await claudeCall(c.env, {
      model: SUMMARY_MODEL,
      // Two to four sentences and no more. A cap that allowed an essay would
      // invite one, and a summary longer than the list beneath it has stopped
      // being a summary.
      max_tokens: 500,
      system: summarySystem({ kindLabel: INSPECTION_KINDS[row.kind]?.label || "Move-out" }),
      messages: [{ role: "user", content: summaryUser(insp, rooms) }],
      // Thinking off, and the spelling comes off the model rather than being
      // written here -- the models disagree about how to say it, so a hard
      // coded setting beside a model constant is a 400 on the first press
      // after a swap. `summaryThinking` is the drafts' own table, read rather
      // than copied, because the pairing is one fact.
      ...(summaryThinking() ? { thinking: summaryThinking() } : {}),
      output_config: { format: { type: "json_schema", schema: SUMMARY_SCHEMA } },
    });
    text = readSummary(replyJson(msg));
  } catch (err) {
    // Nothing was written, so "try again" is always true and is what the
    // screen says. What is NOT done is swallow it: somebody is waiting.
    console.warn("[inspection-summary] not written:", err?.code || "", err?.message || err);
    return { error: err?.message === "ai_not_configured" ? "ai_not_configured" : "ai_unavailable" };
  }
  // An empty paragraph is a failure and not a summary. A row with one in it
  // would draw an empty box over the list of rooms, and a blank there reads as
  // "nothing much wrong" -- which is the one thing this must never say by
  // accident, and what CHECK.sql's own invariant counts.
  if (!text) return { error: "ai_unavailable" };

  const now = new Date().toISOString();
  try {
    await c.env.DB.prepare(
      `INSERT INTO inspection_summaries (inspection_id, summary, source, model, written_at, written_by)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(inspection_id) DO UPDATE SET
         summary = excluded.summary, source = excluded.source, model = excluded.model,
         written_at = excluded.written_at, written_by = excluded.written_by`
    ).bind(row.id, text, source, SUMMARY_MODEL, now, auth.userId).run();
  } catch (err) {
    if (missingSchema(err)) return { error: "migration_needed", migration: "063_inspection_summary" };
    throw err;
  }
  // Logged here rather than at each door, so both record it and neither can
  // forget. Asking a third party to read a tenant's condition notes is the
  // sort of thing that gets asked about later -- the same reason the photo
  // drafts log their own press.
  await logActivity(c.env, auth.accountId, auth.userId, "inspection_summary",
    `Wrote the work-order summary from ${flagged} flagged room${flagged === 1 ? "" : "s"}`);
  return { ok: true,
    summary: summaryShape({ summary: text, source, model: SUMMARY_MODEL, written_at: now }, insp, rooms) };
}

// REWRITING IT, which is the way out of the two states the automatic one
// leaves behind: a call that failed, and notes that have moved on since.
//
// NOT GATED ON FINISHED, deliberately, and that is the opposite answer to the
// drafting route. Drafting writes to the inspection, which is a document
// somebody quotes back, so finishing shuts it. This writes a derived
// paragraph in its own table and touches nothing in the record -- and the
// moment it is most wanted is after the job has been raised, which is very
// often after finishing. Gating it would leave a finished inspection whose
// automatic summary failed with no way ever to get one.
app.post("/api/inspections/:id/summary", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  // `drafts: false` is belt and braces rather than the guarantee: the source
  // is built through `contractorInspectionShape`, which drops them. Said twice
  // because a model's unkept sentence reaching a summary the contractor reads
  // is the one way this feature could put a working note on a work order.
  const rooms = await inspectionRooms(c.env.DB, row.id, { drafts: false });
  const made = await writeInspectionSummary(c, auth, row, rooms);
  if (made.error) {
    return c.json({ error: made.error, migration: made.migration || null },
      SUMMARY_STATUS[made.error] || 502);
  }
  return c.json({ ok: true, summary: made.summary });
});

// Serving one back. The caller names an inspection and a photo on it, never a
// key: the key is read from the row after the same check every other route on
// that inspection makes. An <img src> cannot carry an Authorization header,
// so the browser fetches this like any other call and renders the blob.
app.get("/api/inspections/:id/photos/:photoId", requireRole(...INSPECTION_READ_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  const photo = await c.env.DB.prepare(
    `SELECT p.* FROM inspection_photos p
       JOIN inspection_rooms r ON r.id = p.room_id
      WHERE p.id = ? AND r.inspection_id = ?`
  ).bind(c.req.param("photoId"), row.id).first();
  if (!photo) return c.notFound();
  const obj = await c.env.FILES.get(photo.file_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": photo.content_type || "image/jpeg",
      "Cache-Control": "private, max-age=3600",
      "Content-Disposition": `inline; filename="${String(photo.name || "photo").replace(/[^\w.\- ]/g, "_")}"`,
    },
  });
});

// WHAT THE PERSON TURNING UP IS SHOWN, which is the half the scope line
// cannot carry.
//
// Asked for as: *"in the work orders when they are passed over to
// subcontractors the images should be passed along in the full report so they
// can visually see what they are fixing prior"*.
//
// `inspectionJobScope` has composed the WORDS into the job since 055 -- a
// bulleted line per flagged room -- and a paragraph about a cracked basin is
// not a photograph of it. Somebody pricing the work, loading a van and then
// standing in the room is the one reader who needs the picture, and they were
// the one reader who could not reach it: every inspection route is
// `INSPECTION_READ_ROLES`, which is admin, pm and owner, so a contractor
// asking for the photo got a 403 about a job they hold a work order on.
//
// KEYED BY THE WORK ORDER, NEVER THE INSPECTION. That is what makes this safe
// rather than a second door into the Inspections tab: there is no route here
// that takes an inspection id and describes it, so nothing can be walked. The
// work order names the job, the job names the inspection, and a company that
// holds no live work order on that job gets `not_found` -- the same shape, and
// the same refusal, the quote request uses to be a key to one job rather than
// to the list.
//
// A VOIDED WORK ORDER IS NOT A KEY. Reissuing voids the old row, and a
// contractor who was taken off the job keeps no view of the unit they were
// going to walk into.
async function woInspection(c, woId) {
  const auth = c.get("auth");
  // Either side of the work order may read it: the hiring account because the
  // inspection is theirs, the holder because the work is. Scoped by company
  // for a contractor seat and by account for everybody else, which is the
  // split `/api/my-work` and `/api/jobs` already draw.
  const mine = auth.role === "contractor" && auth.companyId
    ? { sql: " AND w.company_id = ? ", val: auth.companyId }
    : { sql: " AND j.account_id = ? ", val: auth.accountId };
  const wo = await c.env.DB.prepare(
    `SELECT w.id, w.job_id, i.id AS insp_id
       FROM work_orders w
       JOIN jobs j ON j.id = w.job_id
       JOIN inspections i ON i.job_id = j.id
      WHERE w.id = ? AND w.voided_at IS NULL ${mine.sql} LIMIT 1`
  ).bind(woId, mine.val).first().catch((err) => {
    if (!missingSchema(err)) throw err;
    return null;
  });
  return wo?.insp_id ? { inspectionId: wo.insp_id, jobId: wo.job_id } : null;
}

// ADMIN, PM AND THE COMPANY HOLDING IT -- deliberately not every seat on the
// account. A TENANT is on the account too, and an inspection is explicitly not
// shown to the tenant it is about: that is a recorded product decision about
// what a deposit conversation looks like, and a route scoped only by account
// id would undo it by a different door. An OWNER reads inspections through
// their own route, which applies their building scope; this one does not have
// one to apply.
// WHAT EACH TRADE ON THIS JOB IS BEING ASKED TO PRICE.
//
// Reported with a nine-trade move-out job on screen: every work order line
// opened with an empty "Scope for plumbing", and the quote request seeded the
// WHOLE walk. So filling nine of them in is nine pieces of typing the
// inspection already answered, and the lazy way out -- sending everybody the
// entire scope -- asks a plumber to find the toilet in eleven rooms.
//
// ONLY THE SERVER CAN ANSWER IT. The browser holds a job's `scope` as one
// string and has never held the rooms behind it, so a screen splitting that
// text per trade would be parsing our own rendered prose -- the second
// implementation this project refuses everywhere. The rooms are here, and the
// rule that maps one to a trade is in `shared/inspection.js` where the chip
// grid already reads it.
//
// KEYED BY THE JOB, and admin or pm only. It answers a slice of the
// inspection, so it is the Inspections tab's own gate rather than the job's:
// a TENANT is on this account and an inspection is explicitly not shown to the
// tenant it is about, and a CONTRACTOR reads the walk through the work-order
// route, which is scoped to work they actually hold.
//
// A job with no inspection answers an EMPTY MAP rather than a 404. Most jobs
// have no walk behind them -- they were typed, or arrived from a CRM -- and a
// 404 on the common case is a modal that has to decide whether a missing
// answer is a fault. Nothing to seed is the ordinary state, not an error.
app.get("/api/jobs/:id/trade-scope", requireRole("admin", "pm"), async (c) => {
  const auth = c.get("auth");
  let insp = null;
  try {
    insp = await c.env.DB.prepare(
      `SELECT * FROM inspections WHERE job_id = ? AND account_id = ? LIMIT 1`
    ).bind(c.req.param("id"), auth.accountId).first();
  } catch (err) {
    // A database behind the code costs the seed and never the modal: the
    // manager types the scope as they did before this existed.
    if (!missingSchema(err)) throw err;
    return c.json({ scopes: {} });
  }
  if (!insp) return c.json({ scopes: {} });
  // `drafts: false`, the same rule the work-order route and the summary both
  // follow: a sentence a model wrote and nobody kept is the team's working
  // note, and this text is pasted onto a document a contractor prices from.
  const rooms = await inspectionRooms(c.env.DB, insp.id, { drafts: false });
  return c.json({ scopes: inspectionTradeScopes(inspectionRowToJs(insp), rooms) });
});

app.get("/api/work-orders/:id/inspection", requireRole("admin", "pm", "contractor"), async (c) => {
  const found = await woInspection(c, c.req.param("id"));
  if (!found) return c.json({ error: "not_found" }, 404);
  const insp = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`)
    .bind(found.inspectionId).first();
  if (!insp) return c.json({ error: "not_found" }, 404);
  // `drafts: false`, which is the rule this project already applies to an
  // owner's copy: a sentence a model wrote and nobody kept is the team's
  // working note, and handing it to the company doing the work would make it
  // read as a finding somebody made.
  const rooms = await inspectionRooms(c.env.DB, insp.id, { drafts: false });
  // AND THE SUMMARY OF ALL OF IT, which is the half a list of rooms cannot
  // give. `stale` comes back with it rather than being hidden: the notes can
  // change after a job is raised, and a paragraph written from the old ones
  // drawn as current is worse than none -- the rooms beneath it are always
  // live, so saying so is what keeps the two readable together.
  return c.json({ ...contractorInspectionShape(inspectionRowToJs(insp), rooms),
    summary: summaryShape(await inspectionSummaryRow(c.env.DB, insp.id), inspectionRowToJs(insp), rooms) });
});

// The bytes. Pinned three ways, the same three the pack file route is: the
// work order names the inspection, the photo must belong to a room OF that
// inspection, and the room must be one the job is actually about -- a
// contractor reading a photograph of the room that was fine is reading the
// report rather than the work.
app.get("/api/work-orders/:id/inspection/photo/:photoId", requireRole("admin", "pm", "contractor"), async (c) => {
  const found = await woInspection(c, c.req.param("id"));
  if (!found) return c.notFound();
  const photo = await c.env.DB.prepare(
    `SELECT p.*, r.status AS room_status FROM inspection_photos p
       JOIN inspection_rooms r ON r.id = p.room_id
      WHERE p.id = ? AND r.inspection_id = ?`
  ).bind(c.req.param("photoId"), found.inspectionId).first();
  // `isFlagged` rather than a comparison written here: one rule for what
  // counts as something to put right, so this cannot start disagreeing with
  // the shape above it about which rooms the job is.
  if (!photo || !isFlagged({ status: photo.room_status })) return c.notFound();
  const obj = await c.env.FILES.get(photo.file_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": photo.content_type || "image/jpeg",
      "Cache-Control": "private, max-age=3600",
      "Content-Disposition": `inline; filename="${String(photo.name || "photo").replace(/[^\w.\- ]/g, "_")}"`,
    },
  });
});
// WHAT THE PEOPLE ASKED TO PRICE IT ARE SHOWN, which is the half 062 gave
// only to the company that won.
//
// `GET /api/work-orders/:id/inspection` carries the rooms, the captions and
// the photographs to the holder of a work order. A quote request is PRE-AWARD
// and there is no work order yet, so the two or three companies actually being
// asked for a number were the ones who could not see the mark -- and a price
// given off a line of text is a price that changes when somebody gets there.
//
// KEYED BY THE INVITE, NEVER BY THE INSPECTION OR THE JOB. Same shape and same
// reasoning as the work-order route: there is no route anywhere that takes an
// inspection id and describes it, so nothing here can be walked. The invite
// names the request, the request names the job, the job names the inspection.
//
// SCOPED EXACTLY AS `/api/my-quotes` IS, clause for clause -- this company's
// invite, not withdrawn, on a job that was not withdrawn. The detail must be
// reachable for precisely the invites the list carries: narrower and a row on
// their own screen opens onto a refusal, wider and there is a door into a job
// their list does not show them. A cancelled or awarded request still answers,
// because it still appears on their list and saying so is the list's job.
async function quoteInspection(c, inviteId) {
  const companyId = await seatCompany(c);
  if (!companyId) return null;
  const row = await c.env.DB.prepare(
    `SELECT qr.trade AS trade, i.id AS insp_id
       FROM quote_invites qi
       JOIN quote_requests qr ON qr.id = qi.request_id
       JOIN jobs j ON j.id = qr.job_id
       JOIN inspections i ON i.job_id = j.id
      WHERE qi.id = ? AND qi.company_id = ? AND qi.status != 'withdrawn'
        AND j.withdrawn_at IS NULL LIMIT 1`
  ).bind(inviteId, companyId).first().catch((err) => {
    if (!missingSchema(err)) throw err;
    return null;
  });
  if (!row?.insp_id) return null;
  const insp = await c.env.DB.prepare(`SELECT * FROM inspections WHERE id = ?`)
    .bind(row.insp_id).first();
  if (!insp) return null;
  // `drafts: false`, the same rule the work-order route, the per-trade scope
  // and the summary all follow: a sentence a model wrote and nobody kept is
  // the team's working note, and this is read by somebody pricing the work.
  const rooms = await inspectionRooms(c.env.DB, insp.id, { drafts: false });
  // ONE SHAPE, computed once here, so the photo route below pins a photograph
  // against exactly the rooms the panel drew rather than asking a second and
  // looser question about it.
  return { shape: quoteInspectionShape(inspectionRowToJs(insp), rooms, row.trade),
    inspectionId: insp.id };
}

// No role gate: `seatCompany` is the gate, because what this answers is keyed
// to a company rather than to a seat's rank -- the same reason `/api/my-quotes`
// and `/api/quotes/:inviteId` beside it take none.
app.get("/api/quotes/:inviteId/inspection", async (c) => {
  const found = await quoteInspection(c, c.req.param("inviteId"));
  // A JOB NOBODY WALKED AND AN INVITE THAT IS NOT THEIRS GIVE THE SAME 404.
  // Most jobs were typed or arrived from a CRM, so "no inspection" is the
  // ordinary answer -- and answering it differently from "not your invite"
  // would say which invite ids are real.
  if (!found) return c.json({ error: "not_found" }, 404);
  return c.json(found.shape);
});

// The bytes. Pinned four ways: the invite names the inspection, the photograph
// must belong to a room OF that inspection, and the room must be one of the
// rooms THIS TRADE is being asked about -- which is read off the shape above
// rather than re-derived, so a picture can never be served from a room the
// panel did not draw.
app.get("/api/quotes/:inviteId/inspection/photo/:photoId", async (c) => {
  const found = await quoteInspection(c, c.req.param("inviteId"));
  if (!found) return c.notFound();
  const photoId = c.req.param("photoId");
  const mine = found.shape.rooms.some((r) => (r.photos || []).some((p) => p.id === photoId));
  if (!mine) return c.notFound();
  const photo = await c.env.DB.prepare(
    `SELECT p.* FROM inspection_photos p
       JOIN inspection_rooms r ON r.id = p.room_id
      WHERE p.id = ? AND r.inspection_id = ?`
  ).bind(photoId, found.inspectionId).first();
  if (!photo) return c.notFound();
  const obj = await c.env.FILES.get(photo.file_key);
  if (!obj) return c.notFound();
  return new Response(obj.body, {
    headers: {
      "Content-Type": photo.content_type || "image/jpeg",
      "Cache-Control": "private, max-age=3600",
      "Content-Disposition": `inline; filename="${String(photo.name || "photo").replace(/[^\w.\- ]/g, "_")}"`,
    },
  });
});

// ---------------------------------------------------------------------------
// AUTO-SCHEDULING A TURNAROUND
// ---------------------------------------------------------------------------
//
// Asked for as: *"upon approval by them of the move-in, move-out job (these
// jobs only) it will auto schedule and assign the job to the most optimized
// qualified tradesman and the best possible time and then automate back and
// forth with tenant and tradesman until it's booked."*
//
// IT CALLS THE REAL ROUTES RATHER THAN REIMPLEMENTING THEM, which is the
// decision the rest of this hangs off. Assigning carries about a dozen gates
// -- roster status, the handyman trade list, documents, cover on the job date,
// the value ceiling, a closed job -- and an automatic path with its own copy
// would be a second set of rules to keep in step. The one that drifted would
// be the one nobody watches, because nobody is standing in front of it.
//
// So the machine does what a person would do: it POSTs to
// `/api/jobs/:id/assign` and `/api/jobs/:id/visits` with the manager's own
// headers. Anything those refuse, this is refused too, in the same words.
//
// WHAT IT DELIBERATELY DOES NOT DO: book a crew's calendar. Auto-schedule --
// the per-engagement flag that writes work as ACCEPTED with no response window
// -- is the subcontractor's to grant, and `autoschedule.js` explains at length
// why the side paying cannot hand it to itself. Where they have granted it the
// assign route books outright, as it always has; where they have not, the work
// order goes out as an offer and the chain runs itself from there. Either way
// the manager does nothing, which is the request.

// The manager's own credentials, forwarded. Built fresh rather than passing
// `c.req.raw.headers` through: that carries the original Content-Length, and a
// body of a different size behind it is a request that cannot be read.
const relayHeaders = (c, as = null) => {
  const h = new Headers({ "Content-Type": "application/json" });
  for (const k of ["authorization", "cookie", "x-user-id", "x-account-id",
    "x-impersonated-by", "x-staff-user-id"]) {
    const v = c.req.header(k);
    if (v) h.set(k, v);
  }
  // 067. OR AS THE ACCOUNT ITSELF, which is what an auto-scheduled window
  // actually is. See `accountSeat` below; `authorization` comes off because a
  // bearer token naming the caller would outrank the headers.
  if (as?.userId) {
    h.set("x-user-id", as.userId);
    h.set("x-account-id", as.accountId);
    h.delete("authorization");
    h.delete("cookie");
  }
  return h;
};

// 067. A TEAM SEAT ON THE ACCOUNT, for the automation to act as.
//
// `autoProposeOnAccept` fires inside the CONTRACTOR's request -- accepting a
// work order is what starts the clock -- and `asSelf` relayed their headers,
// so the propose route read `auth.role === "contractor"` and stamped the
// window as the contractor's own agreement. The hiring side's leg was left
// NULL, so every auto-scheduled job then stopped dead waiting for a manager
// to tick a time a machine had chosen on their behalf.
//
// WHICH IS THE OPPOSITE OF WHAT WAS ASKED FOR: *"automate back and forth with
// tenant and tradesman... until it's booked - this should be fully
// automated"*. The hiring side is deliberately not in that back and forth.
// They agreed by switching it on, and the automation proposing on their behalf
// IS that agreement -- the same rule 064 states, applied to the side that
// delegated the choice.
//
// `pickSeat` rather than the first row back: it prefers an admin, then a pm,
// and an unrecognised role sorts LAST, so a guest seat can never end up
// speaking for the account. Null when there is nobody -- the caller falls back
// to relaying, because an account with no team seat must still be able to
// schedule a repair.
async function accountSeat(env, accountId) {
  try {
    const { results } = await env.DB.prepare(
      `SELECT user_id AS userId, role FROM memberships WHERE account_id = ?`
    ).bind(accountId).all();
    const seat = pickSeat((results || []).filter((r) => isTeamSeat(r.role)));
    return seat?.userId ? { userId: seat.userId, accountId } : null;
  } catch { return null; }
}

const asSelf = async (c, path, body, as = null) => {
  // `executionCtx` throws rather than answering undefined when there is none
  // -- which is every test, and any call that did not arrive through the
  // fetch handler. Reading it through a catch is what lets this be driven at
  // all, and a self-call does not need to wait on anything after it anyway.
  let ctx;
  try { ctx = c.executionCtx; } catch { ctx = undefined; }
  const res = await app.fetch(
    new Request(new URL(path, c.req.url), {
      method: "POST", headers: relayHeaders(c, as), body: JSON.stringify(body),
    }), c.env, ctx);
  return { status: res.status, body: await res.json().catch(() => ({})) };
};

// WHO COULD TAKE IT. The roster, with the three facts the ranking needs that
// are not on the engagement: what they already have on, the days they have
// marked themselves out, and whether their documents are in order.
async function autoCandidates(env, accountId, trade, companyState) {
  const { results } = await env.DB.prepare(
    `SELECT e.company_id, e.categories, e.engaged_as, e.rating, e.doc_review,
            c.company, c.insurance, c.bond, c.contract, c.w9, c.unavailable_days, c.crews
       FROM engagements e JOIN companies c ON c.id = e.company_id
      WHERE e.account_id = ? AND ${onRosterSql("e.status")}`
  ).bind(accountId).all().catch(() => ({ results: [] }));

  const out = [];
  for (const r of results || []) {
    // The documents question the assign route asks, asked here so a candidate
    // is not put forward only to be refused.
    const review = parseJson(r.doc_review, {});
    const shape = { engagedAs: r.engaged_as, docReview: review,
      insurance: !!r.insurance, bond: !!r.bond, contract: !!r.contract, w9: !!r.w9 };
    const blockers = requiredDocsFor(r.engaged_as, ASSIGN_KINDS)
      .filter((k) => review[k]?.status !== "verified");
    // What they already have on, this account's half of it. SubSub cannot see
    // the other four accounts' diaries, which is why the window is an OFFER
    // and the chain is what settles it.
    const { results: busy } = await env.DB.prepare(
      `SELECT DISTINCT v.date FROM visits v
         JOIN work_orders w ON w.job_id = v.job_id
        WHERE w.company_id = ? AND w.voided_at IS NULL
          AND v.status IN ('proposed', 'confirmed')`
    ).bind(r.company_id).all().catch(() => ({ results: [] }));
    const { results: open } = await env.DB.prepare(
      `SELECT COUNT(*) AS n FROM work_orders w JOIN jobs j ON j.id = w.job_id
        WHERE w.company_id = ? AND w.voided_at IS NULL AND j.status = 'active'`
    ).bind(r.company_id).all().catch(() => ({ results: [{ n: 0 }] }));
    out.push({
      companyId: r.company_id, company: r.company,
      categories: parseJson(r.categories, []), engagedAs: r.engaged_as,
      rating: r.rating, blockers, shape,
      busy: (busy || []).map((x) => x.date),
      // The days they cannot be booked, worked out from their CREWS as well
      // as the old company-wide list -- which no screen writes any more, so
      // reading it alone booked a crew on a day every crew had marked off.
      ...(() => {
        const o = offDays({ unavailableDays: parseJson(r.unavailable_days, []),
          crews: parseJson(r.crews, []) });
        return { unavailable: o.days, paused: o.allPaused };
      })(),
      openJobs: (open || [])[0]?.n || 0,
    });
  }
  return out;
}

// THE WHOLE RUN, from an approved turnaround to a window on somebody's
// calendar. Answers rather than throwing: by the time this runs the job
// exists, so a failure here must leave a raised job and a reason -- never a
// 500 over work that is already on the Jobs screen.
async function autoTurnaround(c, { jobId, kind, trades, job }) {
  const auth = c.get("auth");
  const acct = await c.env.DB.prepare(
    `SELECT auto_turnaround FROM accounts WHERE id = ?`).bind(auth.accountId).first()
    .catch((err) => { if (missingSchema(err)) return null; throw err; });
  const why = whyNotAuto({
    on: !!acct?.auto_turnaround, kind, trades,
    assigned: 0,
  });
  if (why) return { skipped: why };

  // The target date the raise form typed is where the search starts: the
  // turnaround is driven by the next tenancy, so the window wants to be on or
  // after it rather than at the first gap in the diary.
  const from = (job?.date || "").slice(0, 10) || new Date().toISOString().slice(0, 10);
  const trade = trades[0];
  const cands = await autoCandidates(c.env, auth.accountId, trade);
  const { picked, skipped } = rankCandidates(cands, { trade, from });
  if (!picked) {
    await logActivity(c.env, auth.accountId, auth.userId, "auto_turnaround",
      `Nobody on the roster could take the ${trade} turnaround — assign it by hand.`
      + (skipped.length ? ` ${skipped.map((x) => `${x.company}: ${AUTO_SKIP[x.why] || x.why}`).join("; ")}.` : ""));
    // WHO WAS LOOKED AT AND WHY EACH WAS OUT. The ranking always worked this
    // out and the reply threw it away, so the screen could only say "assign it
    // by hand" -- reported as a dead end with no reason. Names off this
    // account's own roster, so nothing here is anybody else's to know.
    return { skipped: "no_candidate", considered: cands.length, trade,
      passedOver: skipped.slice(0, 12) };
  }

  const got = await asSelf(c, `/api/jobs/${jobId}/assign`, {
    trade, companyId: picked.companyId, payKind: "fixed", value: "",
    responseWindow: "24h", autoBook: false,
  });
  if (got.status >= 300) {
    await logActivity(c.env, auth.accountId, auth.userId, "auto_turnaround",
      `Could not put ${picked.company} on the ${trade} turnaround (${got.body?.error || got.status}).`);
    return { skipped: "assign_refused", error: got.body?.error || null, trade,
      companyId: picked.companyId, company: picked.company,
      absent: got.body?.absent || [], unreviewed: got.body?.unreviewed || [] };
  }

  // THE WINDOW WAITS UNTIL THEY HAVE TAKEN THE JOB, and getting this wrong is
  // the thing that nearly shipped. A work order sits PENDING until the crew
  // accepts it, and `visitParties` counts a contractor only once they have --
  // deliberately, because somebody who has not said yes to the JOB cannot be
  // waited on for the TIME. So proposing a window straight after assigning
  // settles it on the hiring side alone: booked, with the crew never asked,
  // which is the exact state 061 and 064 exist to stop.
  //
  // Where the crew HAS granted auto-schedule the work order is accepted on
  // issue, so they are a party now and the window goes out now. Where they
  // have not, `autoProposeOnAccept` picks it up the moment they say yes.
  const live = await c.env.DB.prepare(
    `SELECT status FROM work_orders WHERE job_id = ? AND voided_at IS NULL
      ORDER BY issued_at DESC LIMIT 1`).bind(jobId).first().catch(() => null);
  const put = live?.status === "accepted"
    ? await asSelf(c, `/api/jobs/${jobId}/visits`,
      { date: picked.day, startTime: AUTO_START, endTime: AUTO_END })
    : null;
  await logActivity(c.env, auth.accountId, auth.userId, "auto_turnaround",
    `Auto-scheduled: ${autoPickText(picked, { trade, skipped })}`
    + (put ? "" : " A time goes out as soon as they accept."));
  return {
    ok: true, companyId: picked.companyId, company: picked.company,
    trade, date: picked.day, proposed: !!put,
    booked: put?.body?.status === "confirmed",
    considered: cands.length, skipped,
  };
}

// AUTO-SCHEDULED MEANS A TIME, NOT ONLY A YES.
//
// Reported from the crew's own card: a work order issued to a company that has
// granted auto-schedule went out ACCEPTED -- which is what the grant buys --
// and drew "Auto-scheduled, booked to your calendar" over "No date yet", with
// nothing anywhere to press. Accepting the work was automatic and choosing the
// day was nobody's job, so the one thing the setting is named for never
// happened on any job that was not a move-in or move-out turnaround.
//
// So issuing to an auto-scheduled crew puts a window forward on the spot: the
// job's own date when it is still ahead and they are free on it, otherwise
// their next free working day. Only when nothing is live already, so it never
// moves a time somebody has proposed. Proposed AS THE HIRING SIDE, through the
// real route, so every gate there holds and the chain still asks the tenant
// where the tenant is a party -- and the crew's own grant is their agreement,
// which `crewGrantedBooking` reads inside that route.
//
// Never throws. By the time this runs the work order exists and the crew has
// been told; a failure to pick a day must leave the work order standing and
// say why, because the card now offers the crew a way to propose one.
async function autoBookOnIssue(c, { jobId, companyId, accountId }) {
  try {
    const live = await c.env.DB.prepare(
      `SELECT 1 AS yes FROM visits WHERE job_id = ? AND status IN ('proposed','confirmed') LIMIT 1`)
      .bind(jobId).first().catch(() => null);
    if (live?.yes) return { proposed: false, reason: "already_timed" };
    const job = await c.env.DB.prepare(`SELECT date, time FROM jobs WHERE id = ?`)
      .bind(jobId).first().catch(() => null);
    const cands = await autoCandidates(c.env, accountId, null);
    const mine = cands.find((x) => x.companyId === companyId);
    const today = dayKeyUtc();
    if (mine?.paused) return { proposed: false, reason: "paused" };
    const off = new Set([...(mine?.busy || []), ...(mine?.unavailable || [])]);
    const jd = String(job?.date || "").slice(0, 10);
    const day = DATE_RE.test(jd) && jd >= today && !off.has(jd) ? jd
      : slotFor({ from: DATE_RE.test(jd) && jd > today ? jd : today,
        busy: mine?.busy, unavailable: mine?.unavailable });
    if (!day) return { proposed: false, reason: "no_slot" };
    // The time on the job when the window lands on the job's own day, because
    // somebody typed it; the standing morning otherwise.
    const keep = day === jd && TIME_RE.test(String(job?.time || "")) ? job.time : null;
    const startTime = keep || AUTO_START;
    const endTime = keep ? windowEnd(keep) : AUTO_END;
    const auth = c.get("auth");
    const as = ["admin", "pm"].includes(auth?.role) ? null : await accountSeat(c.env, accountId);
    const put = await asSelf(c, `/api/jobs/${jobId}/visits`, { date: day, startTime, endTime }, as);
    if (put.status >= 300) return { proposed: false, reason: put.body?.error || String(put.status) };
    return { proposed: true, date: day, startTime, endTime, status: put.body?.status || null };
  } catch (err) {
    console.warn("[auto-book] could not put a time forward:", err?.message || err);
    return { proposed: false, reason: "error" };
  }
}

// HAS THE CREW ALREADY AGREED TO A TIME THE HIRING SIDE BOOKS? Yes, when every
// crew holding accepted work on the job granted this account auto-schedule and
// the day is not one they marked themselves out of. That grant is exactly
// "you may write work to my calendar without asking" -- so asking them to
// confirm a window on a free day is the round trip they switched off, and a
// card drawing "Can you make it?" under "Auto-scheduled" contradicts itself.
// A day they marked unavailable is still asked, because the grant was never
// for those. Read fresh from the engagement, so withdrawing the grant takes
// effect on the very next window. Declining is still open to them either way.
async function crewGrantedBooking(env, { jobId, accountId, date }) {
  try {
    const { results } = await env.DB.prepare(
      `SELECT w.auto_scheduled, e.auto_schedule, co.unavailable_days, co.crews
         FROM work_orders w
         JOIN engagements e ON e.account_id = ? AND e.company_id = w.company_id
         JOIN companies co ON co.id = w.company_id
        WHERE w.job_id = ? AND w.voided_at IS NULL AND w.status = 'accepted'`
    ).bind(accountId, jobId).all();
    const rows = results || [];
    return rows.length > 0 && rows.every((r) => !!r.auto_scheduled && !!r.auto_schedule
      && !isOffOn({ unavailableDays: parseJson(r.unavailable_days, []),
        crews: parseJson(r.crews, []) }, date));
  } catch { return false; }
}

// THE FIRST WINDOW, ONCE THE CREW HAS TAKEN THE JOB. Only on a turnaround the
// account auto-schedules, only when nothing is already proposed, and only for
// the company that just accepted -- so a second trade accepting later does not
// put a second window on a job that already has one.
async function autoProposeOnAccept(c, wo) {
  const job = await c.env.DB.prepare(
    `SELECT id, date, account_id FROM jobs WHERE id = ?`).bind(wo.job_id).first().catch(() => null);
  if (!job) return null;
  const acct = await c.env.DB.prepare(
    `SELECT auto_turnaround FROM accounts WHERE id = ?`).bind(job.account_id).first()
    .catch((err) => { if (missingSchema(err)) return null; throw err; });
  if (!acct?.auto_turnaround) return null;
  const insp = await c.env.DB.prepare(
    `SELECT kind FROM inspections WHERE job_id = ?`).bind(job.id).first().catch(() => null);
  if (!isTurnaroundKind(insp?.kind)) return null;
  const already = await c.env.DB.prepare(
    `SELECT 1 AS yes FROM visits WHERE job_id = ? AND status IN ('proposed','confirmed') LIMIT 1`)
    .bind(job.id).first().catch(() => null);
  if (already?.yes) return null;

  const cands = await autoCandidates(c.env, job.account_id, null);
  const mine = cands.find((x) => x.companyId === wo.company_id);
  if (mine?.paused) return { stopped: "paused" };
  const from = (job.date || "").slice(0, 10) || new Date().toISOString().slice(0, 10);
  const day = slotFor({ from, busy: mine?.busy, unavailable: mine?.unavailable });
  if (!day) return { stopped: "no_slot" };
  // AS THE ACCOUNT, NOT AS THE CONTRACTOR WHOSE PRESS GOT US HERE. This runs
  // inside their accept, so relaying their headers made the propose route read
  // `auth.role === "contractor"` and record the window as THEIR agreement --
  // leaving the hiring side outstanding on a time the machine chose for them,
  // which stalls every auto-scheduled job on a manual tick.
  const put = await asSelf(c, `/api/jobs/${job.id}/visits`,
    { date: day, startTime: AUTO_START, endTime: AUTO_END },
    await accountSeat(c.env, job.account_id));
  return { ok: put.status < 300, date: day };
}

// AND THE BACK AND FORTH, WHICH IS THE HALF THAT MAKES IT "FULLY AUTOMATED".
// A decline on an auto-scheduled turnaround puts the next free day forward by
// itself, up to `AUTO_TRIES` windows. Bounded, because "until it's booked"
// cannot mean for ever: two people who keep saying no are telling us something
// a fourth date will not fix, and that is where a person has to look at it.
async function autoRepropose(c, visit) {
  const auth = c.get("auth");
  const job = await jobWithEnding(c.env, await c.env.DB.prepare(
    `SELECT j.id, j.date, j.title, j.account_id, j.status,
            j.withdrawn_at, j.declined_at FROM jobs j WHERE j.id = ?`)
    .bind(visit.job_id).first().catch(() => null));
  if (!job) return null;
  // 066. NOT ON WORK THAT IS CANCELLED OR ON HOLD. This is the one auto hook
  // that fires LATER -- a tenant declining a window days afterwards -- so it
  // is the one that can find the job ended underneath it, and a machine
  // proposing times for work somebody called off is the standing-permission
  // failure this file records about a flag nobody is watching.
  //
  // `jobIsLive` rather than `jobIsClosed`, because a hold is deliberately not
  // a closure and a reading of only the second would carry on regardless.
  if (!jobIsLive(job, dayKeyUtc())) return null;
  const acct = await c.env.DB.prepare(
    `SELECT auto_turnaround FROM accounts WHERE id = ?`).bind(job.account_id).first()
    .catch((err) => { if (missingSchema(err)) return null; throw err; });
  if (!acct?.auto_turnaround) return null;
  const insp = await c.env.DB.prepare(
    `SELECT kind FROM inspections WHERE job_id = ?`).bind(job.id).first().catch(() => null);
  if (!isTurnaroundKind(insp?.kind)) return null;

  // How many windows have already been put forward on this job. Counted from
  // the rows rather than held in a column: every proposal is one, which is
  // exactly what the budget is about.
  const seen = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM visits WHERE job_id = ?`).bind(job.id).first().catch(() => null);
  const tries = Number(seen?.n || 0);
  if (tries >= AUTO_TRIES) {
    await logActivity(c.env, job.account_id, auth.userId, "auto_turnaround",
      `${AUTO_TRIES} times nobody could make it for "${job.title}" — pick a time by hand.`);
    return { stopped: "out_of_tries" };
  }
  const wo = await c.env.DB.prepare(
    `SELECT company_id FROM work_orders WHERE job_id = ? AND voided_at IS NULL LIMIT 1`)
    .bind(job.id).first().catch(() => null);
  if (!wo?.company_id) return null;
  const cands = await autoCandidates(c.env, job.account_id, null);
  const mine = cands.find((x) => x.companyId === wo.company_id);
  // The day that was just refused is on the row, so the search starts from it
  // rather than from the job's target -- otherwise the next try offers the
  // same week again.
  if (mine?.paused) return { stopped: "paused" };
  const day = slotFor({ from: visit.date, busy: mine?.busy, unavailable: mine?.unavailable });
  if (!day) return { stopped: "no_slot" };
  // AS THE ACCOUNT, for the reason `autoProposeOnAccept` is: this runs inside
  // the DECLINE of whoever could not make the last window -- a tenant or a
  // contractor -- so relaying their headers would record the replacement as
  // their own agreement to a day they have not seen, and leave the hiring side
  // outstanding on every one of them.
  const put = await asSelf(c, `/api/jobs/${job.id}/visits`,
    { date: day, startTime: AUTO_START, endTime: AUTO_END },
    await accountSeat(c.env, job.account_id));
  await logActivity(c.env, job.account_id, auth.userId, "auto_turnaround",
    `That did not work, so ${day} has gone forward instead (try ${tries + 1} of ${AUTO_TRIES}).`);
  return { ok: put.status < 300, date: day, tries: tries + 1 };
}

// RAISING THE WORK, which is what the whole walk is for.
//
// It creates a JOB and stops there, deliberately. Composing the job from what
// was flagged is bookkeeping; issuing a work order is a price and a date
// committed to a company, and this product's own rule is that the side paying
// cannot commit the side doing the work without them answering. So the job
// lands unassigned with its trade slots open, and Assign, Ask for quotes and
// Overflow are one tap away on it -- the same three doors every other job has,
// with every gate they carry (cover, documents, roster status) intact.
//
// ONE JOB PER INSPECTION. Raising a second would be two contractors asked for
// the same work, found out when both turn up.
app.post("/api/inspections/:id/job", requireRole(...INSPECTION_WRITE_ROLES), async (c) => {
  const auth = c.get("auth");
  const { row, error, status, migration } = await inspectionFor(c, auth, c.req.param("id"));
  if (error) return c.json({ error, migration }, status);
  if (row.job_id) return c.json({ error: "already_raised", jobId: row.job_id }, 409);
  const rooms = await inspectionRooms(c.env.DB, row.id, { drafts: mayWriteInspection(auth.role) });
  const flagged = flaggedRooms(rooms);
  // Nothing was wrong, so there is nothing to do. Said rather than creating
  // an empty job somebody then has to find and close.
  if (!flagged.length) return c.json({ error: "nothing_flagged" }, 409);

  const b = await c.req.json().catch(() => ({}));
  const trades = (Array.isArray(b.trades) ? b.trades : []).filter((t) => TRADE_IDS.has(t));
  if (!trades.length) return c.json({ error: "trades_required" }, 400);

  const prop = await c.env.DB.prepare(
    `SELECT * FROM properties WHERE id = ? AND account_id = ?`
  ).bind(row.property_id, auth.accountId).first();

  // 062. WHO HAS TO BE THERE, PRE-ANSWERED BY WHICH WALK THIS WAS. A move-out
  // unit is being handed back, so the agent opens the door; a move-in unit has
  // somebody moving into it, and a time nobody checked with them is a time
  // they are not in for.
  //
  // THE PERSON RAISING IT SETTLES IT, and the kind only pre-answers.
  // *"A move in doesn't necessarily need a tenant in the unit, only if
  // required"* -- a unit being turned round is often empty on the day the work
  // is done, so forcing a confirmation step onto every move-in job would be
  // the product deciding something the manager is standing in the flat to
  // decide. Validated against ACCESS_KINDS, so a word the picker never offered
  // cannot reach the column.
  const access = isAccess(b.access) ? String(b.access) : suggestedAccessForInspection(row.kind);
  // AND WHICH TENANT, resolved from the UNIT. This is the half 060 recorded as
  // still open -- a job carries a property and a property carries many
  // tenancies, so a manager-raised job had no way to name one. An inspection
  // carries the unit, which is exactly the narrowing that was missing.
  //
  // Matched case-insensitively on trimmed text, because a unit is "3B" in one
  // building and "Apt 12" in the next and a managing agent types what is on
  // the door. Only when the inspection HAS a unit: a whole-building walk has
  // no one tenant, and picking the first on the property would name somebody
  // at random.
  //
  // One row. Two tenants in one flat is an ordinary shape and one of them
  // confirming a window is enough -- the same single answer `notifyTenant` has
  // always written to.
  let accessUser = null;
  if (needsTenantConfirm(access) && String(row.unit || "").trim()) {
    accessUser = (await c.env.DB.prepare(
      `SELECT m.user_id FROM memberships m
         JOIN membership_properties mp ON mp.membership_id = m.id
        WHERE m.account_id = ? AND m.role = 'tenant' AND mp.property_id = ?
          AND LOWER(TRIM(COALESCE(m.unit, ''))) = LOWER(TRIM(?))
        LIMIT 1`
    ).bind(auth.accountId, row.property_id, String(row.unit).trim()).first()
      .catch(() => null))?.user_id || null;
  }

  const jobId = uid();
  // The two scheduling columns are EXTRAS on the insert, newest first, for the
  // reason 060's was: losing the access answer costs a round trip with a
  // tenant: refusing the insert costs the repair. Same cascade the propose
  // route reads them with.
  const extras = [
    { cols: ", access, access_user_id", vals: [access, accessUser] },
    { cols: ", access", vals: [access] },
    { cols: "", vals: [] },
  ];
  let wrote = false;
  for (const e of extras) {
    try {
      await c.env.DB.prepare(
        `INSERT INTO jobs (id, account_id, title, address, area, zip, date, trades, scope,
                           status, property_id, created_by, approved_at${e.cols})
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, CURRENT_TIMESTAMP${e.vals.map(() => ", ?").join("")})`
      ).bind(jobId, auth.accountId,
        inspectionJobTitle(inspectionRowToJs(row)),
        prop?.address || null, prop?.city || null, prop?.zip || null,
        String(b.date || "").trim().slice(0, 10) || null,
        JSON.stringify(trades),
        inspectionJobScope(inspectionRowToJs(row), rooms),
        row.property_id, auth.userId, ...e.vals).run();
      wrote = true;
      break;
    } catch (err) { if (!missingSchema(err)) throw err; }
  }
  if (!wrote) return c.json({ error: "migration_needed", migration: "055_inspections" }, 503);
  await c.env.DB.prepare(`UPDATE inspections SET job_id = ? WHERE id = ?`).bind(jobId, row.id).run();
  await logActivity(c.env, auth.accountId, auth.userId, "inspection_job",
    `Raised a job from the inspection${row.unit ? ` of unit ${row.unit}` : ""}: ${flagged.length} room${flagged.length === 1 ? "" : "s"} to put right`);

  // THE SUMMARY, WRITTEN AUTOMATICALLY, AND NEVER ALLOWED TO BLOCK THE RAISE.
  // *"Combine the comments and summarize automatically"* -- so there is no
  // button for the ordinary case: raising the job is the press.
  //
  // IT RUNS HERE RATHER THAN ON THE CONTRACTOR'S FIRST READ, which is the
  // obvious alternative and is wrong three ways over: it would spend this
  // account's money on a press they did not make, it would fail at the one
  // moment the person needs it with nothing written to fall back on, and
  // three companies on one job would pay for three answers to one question.
  //
  // THE CATCH IS WIDE ON PURPOSE, which this project normally refuses. By the
  // time this runs the job exists and the inspection points at it, so a throw
  // here would answer 500 to a raise that already happened -- the screen
  // would say it failed over work that is on the Jobs screen, which is
  // strictly worse than a work order with no summary on it. Logged rather
  // than swallowed, and the reply says which it was.
  const made = await writeInspectionSummary(c, auth, row, rooms).catch((err) => {
    console.warn("[inspection-summary] threw while raising:", err?.message || err);
    return { error: "ai_unavailable" };
  });
  // Said rather than assumed, the same way the invite route reports whether
  // 059 landed: a screen that cannot tell "the tenant will be asked" from
  // "there was nobody to ask" is a screen that promises a confirmation step
  // that is never going to happen.
  // 065. AND IF THE ACCOUNT HAS ASKED FOR IT, THE REST HAPPENS BY ITSELF.
  //
  // "Upon approval by them" is this moment: a job raised from an inspection is
  // created already approved, so there is no second press to wait for.
  //
  // THE CATCH IS WIDE FOR THE SAME REASON THE SUMMARY'S IS. The job exists by
  // the time this runs, so a throw here would answer 500 to a raise that
  // already happened -- a screen reporting failure over work that is on the
  // Jobs screen, which is worse than a turnaround nobody auto-assigned.
  const auto = await autoTurnaround(c, {
    jobId, kind: row.kind, trades,
    job: { date: String(b.date || "").trim().slice(0, 10) || null },
  }).catch((err) => {
    console.warn("[auto-turnaround] threw while raising:", err?.message || err);
    return { skipped: "threw" };
  });

  // `summaryError` is said rather than left to be inferred from a null, for
  // the reason `engagedAsRecorded` is: a screen that cannot tell "there was
  // nothing to summarise" from "the call failed" cannot offer the one of those
  // that is worth a second press.
  return c.json({ ok: true, jobId, flagged: flagged.length,
    access: access || null, accessUserId: accessUser,
    summary: made.ok ? made.summary : null, summaryError: made.error || null,
    // Said rather than left to be inferred: a screen that cannot tell "the
    // account has not switched this on" from "nobody on the roster could take
    // it" cannot offer the one of those that is worth doing something about.
    auto }, 201);
});

// ---------------------------------------------------------------------------
// The Sub Passport (077). One public page a subcontractor owns and hands out,
// at /p/<slug>. `shared/passport.js` holds every rule -- the address, the
// badge, what the page carries and the access moves -- and this is the I/O.
//
// Three doors, three audiences, and they must not blur:
//   /api/my-passport/...        the sub editing their own page
//   /api/public/passport/:slug  anybody holding the link, no session
//   /api/passport/:slug/...     a signed-in hiring account asking for, and
//                               then opening, the certificate and the W-9
// ---------------------------------------------------------------------------

// Which company this seat's Passport is. The same answer `seatCompany` gives
// every other "my company" route, so a contractor seat and the admin of the
// sub's own account land on the same page.
async function passportCompany(c) {
  const companyId = await seatCompany(c);
  if (companyId) return { companyId };
  const why = await noCompanyReason(c);
  return { error: why === "not_hireable" ? "not_hireable" : why === "migration_needed" ? "migration_needed" : "forbidden" };
}

const passportRowToJs = (r) => ({
  slug: r.slug,
  url: passportUrl(r.slug),
  published: !!r.published_at,
  publishedAt: r.published_at || null,
  trades: parseJson(r.trades, []),
  foundedYear: r.founded_year ?? null,
  about: r.about || null,
  viewCount: r.view_count || 0,
  lastViewedAt: r.last_viewed_at || null,
});

// The trades a new Passport starts with: what the sub's clients already
// engage them for. Their own statement from then on -- this is only a seed,
// and an empty list is fine.
async function seedPassportTrades(env, companyId) {
  const { results } = await env.DB.prepare(
    `SELECT categories FROM engagements WHERE company_id = ? AND status <> 'ended'`).bind(companyId).all();
  const out = [];
  for (const r of results || []) {
    for (const t of parseJson(r.categories, [])) if (TRADE_IDS.has(t) && !out.includes(t)) out.push(t);
  }
  return out.slice(0, 12);
}

// The row, made on first open. The slug is stamped once and never changed,
// because it ends up on decals and flyers. A collision on the random suffix is
// a UNIQUE failure, so it is retried rather than checked first -- a check
// beforehand cannot cover two requests arriving at once.
async function ensurePassport(env, companyId) {
  const read = () => env.DB.prepare(`SELECT * FROM passports WHERE company_id = ?`).bind(companyId).first();
  const have = await read();
  if (have) return have;
  const co = await env.DB.prepare(`SELECT company FROM companies WHERE id = ?`).bind(companyId).first();
  const trades = JSON.stringify(await seedPassportTrades(env, companyId));
  for (let i = 0; i < 6; i++) {
    const slug = mintSlug(co?.company, crypto.getRandomValues(new Uint8Array(8)));
    try {
      await env.DB.prepare(`INSERT INTO passports (company_id, slug, trades) VALUES (?, ?, ?)`)
        .bind(companyId, slug, trades).run();
      return await read();
    } catch (err) {
      if (missingSchema(err)) throw err;
      // Either the slug collided (try another) or a second request made this
      // company's row first (use it). Re-reading tells which.
      const again = await read();
      if (again) return again;
    }
  }
  throw new Error("passport_slug_mint_failed");
}

async function passportPhotos(env, companyId) {
  const { results } = await env.DB.prepare(
    `SELECT id, caption, file_type, position FROM passport_photos
      WHERE company_id = ? AND removed_at IS NULL ORDER BY position, created_at`).bind(companyId).all();
  return results || [];
}

// Everything the public page draws, from the company row as it is now. Read
// live rather than stamped: the whole point of a Passport over an emailed PDF
// is that a renewed certificate shows the day it is uploaded.
async function passportPublicShape(env, passport, { today = new Date().toISOString().slice(0, 10) } = {}) {
  const co = await env.DB.prepare(`SELECT * FROM companies WHERE id = ?`).bind(passport.company_id).first();
  if (!co) return null;
  let docs = {};
  try { docs = docShapeWithLegacy(await currentDocRows(env.DB, co.id), co); }
  catch (err) { if (!missingSchema(err)) throw err; docs = docShapeWithLegacy({}, co); }
  // The sub's own referral code, so a GC pressing "Manage your whole sub
  // network like this" is credited to them. A database without 075 has no
  // codes, and that costs the credit, never the page.
  let refCode = null;
  try { refCode = await ensureReferralCode(env, { kind: "sub", companyId: co.id }); }
  catch (err) { if (!missingSchema(err)) console.warn("[passport] no referral code:", err?.message || err); }
  return publicPassport({
    passport: { slug: passport.slug, trades: parseJson(passport.trades, []),
      foundedYear: passport.founded_year, about: passport.about },
    company: { company: co.company, city: co.city, state: co.state, license: co.license,
      licenseCheck: checkView(parseJson(co.license_check, null), co.license),
      coverage: validCoverage(parseJson(co.coverage, null)) || {},
      insurance: co.insurance, w9: co.w9 },
    photos: await passportPhotos(env, co.id), docs, refCode, today,
  });
}

const accessRowToJs = (r) => ({
  id: r.id, accountId: r.account_id, accountName: r.account_name || null,
  requesterName: r.requester_name || null, message: r.message || null,
  status: r.status, requestedAt: r.requested_at, decidedAt: r.decided_at || null,
});

app.get("/api/my-passport", requireRole("admin", "pm", "contractor"), async (c) => {
  const who = await passportCompany(c);
  if (who.error === "not_hireable") return c.json({ error: "not_hireable" }, 409);
  if (who.error === "migration_needed") return c.json({ error: "migration_needed", migration: "031_account_company" }, 503);
  if (who.error) return c.json({ error: "forbidden" }, 403);
  const row = await ensurePassport(c.env, who.companyId);
  const preview = await passportPublicShape(c.env, row);
  const { results: access } = await c.env.DB.prepare(
    `SELECT pa.*, a.name AS account_name, u.name AS requester_name
       FROM passport_access pa
       LEFT JOIN accounts a ON a.id = pa.account_id
       LEFT JOIN users u ON u.id = pa.requested_by
      WHERE pa.company_id = ?
      ORDER BY CASE pa.status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END, pa.requested_at DESC
      LIMIT 100`).bind(who.companyId).all();
  return c.json({ passport: passportRowToJs(row), preview,
    photos: (await passportPhotos(c.env, who.companyId)).map((p) => ({ id: p.id, caption: p.caption || null })),
    access: (access || []).map(accessRowToJs) });
});

app.put("/api/my-passport", requireRole("admin", "pm", "contractor"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: who.error }, who.error === "not_hireable" ? 409 : 403);
  const b = await c.req.json().catch(() => ({}));
  const v = validPassportEdit(b);
  if (!v.ok) return c.json(v, 400);
  const row = await ensurePassport(c.env, who.companyId);
  const sets = [], binds = [];
  if ("trades" in v.value) { sets.push("trades = ?"); binds.push(JSON.stringify(v.value.trades)); }
  if ("foundedYear" in v.value) { sets.push("founded_year = ?"); binds.push(v.value.foundedYear); }
  if ("about" in v.value) { sets.push("about = ?"); binds.push(v.value.about); }
  // Publishing is a word the sub says, never a side effect of saving. Only a
  // real boolean moves it, so a body that merely omits it changes nothing.
  if (b.published === true && !row.published_at) sets.push("published_at = CURRENT_TIMESTAMP");
  if (b.published === false && row.published_at) sets.push("published_at = NULL");
  if (!sets.length) return c.json({ passport: passportRowToJs(row) });
  sets.push("updated_at = CURRENT_TIMESTAMP");
  await c.env.DB.prepare(`UPDATE passports SET ${sets.join(", ")} WHERE company_id = ?`)
    .bind(...binds, who.companyId).run();
  if (typeof b.published === "boolean" && b.published !== !!row.published_at) {
    await logActivity(c.env, accountId, userId, "passport",
      b.published ? "Published the SubSub Passport" : "Took the SubSub Passport down");
  }
  const fresh = await ensurePassport(c.env, who.companyId);
  return c.json({ passport: passportRowToJs(fresh), preview: await passportPublicShape(c.env, fresh) });
});

// A photograph of their work. Uploaded first through the checked
// passport-photo kind, then attached here. The key is a claim the browser
// makes, so it must sit under this account's own passport-photo prefix --
// without that, any object in the bucket could be published by naming it.
app.post("/api/my-passport/photos", requireRole("admin", "pm", "contractor"), async (c) => {
  const { accountId } = c.get("auth");
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: who.error }, who.error === "not_hireable" ? 409 : 403);
  const b = await c.req.json().catch(() => ({}));
  const key = String(b.key || "");
  if (!key.startsWith(`${accountId}/passport-photo/`) || key.includes("..")) return c.json({ error: "invalid_key" }, 400);
  const caption = String(b.caption ?? "").trim();
  if (caption.length > PASSPORT_CAPTION_MAX) return c.json({ error: "caption_too_long", max: PASSPORT_CAPTION_MAX }, 400);
  const head = await c.env.FILES.head(key);
  if (!head) return c.json({ error: "not_uploaded" }, 400);
  await ensurePassport(c.env, who.companyId);
  const have = await passportPhotos(c.env, who.companyId);
  if (have.length >= PASSPORT_MAX_PHOTOS) return c.json({ error: "too_many_photos", max: PASSPORT_MAX_PHOTOS }, 409);
  const id = uid();
  const position = have.reduce((m, p) => Math.max(m, p.position || 0), 0) + 1;
  await c.env.DB.prepare(
    `INSERT INTO passport_photos (id, company_id, file_key, file_type, caption, position) VALUES (?, ?, ?, ?, ?, ?)`
  ).bind(id, who.companyId, key, head.httpMetadata?.contentType || String(b.type || "") || null,
    caption || null, position).run();
  return c.json({ id, caption: caption || null }, 201);
});

app.patch("/api/my-passport/photos/:id", requireRole("admin", "pm", "contractor"), async (c) => {
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: who.error }, who.error === "not_hireable" ? 409 : 403);
  const b = await c.req.json().catch(() => ({}));
  const caption = String(b.caption ?? "").trim();
  if (caption.length > PASSPORT_CAPTION_MAX) return c.json({ error: "caption_too_long", max: PASSPORT_CAPTION_MAX }, 400);
  const r = await c.env.DB.prepare(
    `UPDATE passport_photos SET caption = ? WHERE id = ? AND company_id = ? AND removed_at IS NULL`
  ).bind(caption || null, c.req.param("id"), who.companyId).run();
  if (!(r?.meta?.changes > 0)) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true, caption: caption || null });
});

// Taken off, never deleted, like every other upload here.
app.delete("/api/my-passport/photos/:id", requireRole("admin", "pm", "contractor"), async (c) => {
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: who.error }, who.error === "not_hireable" ? 409 : 403);
  const r = await c.env.DB.prepare(
    `UPDATE passport_photos SET removed_at = CURRENT_TIMESTAMP WHERE id = ? AND company_id = ? AND removed_at IS NULL`
  ).bind(c.req.param("id"), who.companyId).run();
  if (!(r?.meta?.changes > 0)) return c.json({ error: "not_found" }, 404);
  return c.json({ ok: true });
});

async function servePassportPhoto(c, companyId, photoId, cache) {
  const p = await c.env.DB.prepare(
    `SELECT file_key, file_type FROM passport_photos WHERE id = ? AND company_id = ? AND removed_at IS NULL`
  ).bind(photoId, companyId).first();
  if (!p) return c.json({ error: "not_found" }, 404);
  const obj = await c.env.FILES.get(p.file_key);
  if (!obj) return c.json({ error: "not_found" }, 404);
  return new Response(obj.body, { headers: {
    "Content-Type": obj.httpMetadata?.contentType || p.file_type || "image/jpeg",
    "Cache-Control": cache, "X-Robots-Tag": "noindex",
  } });
}

// The owner's own view of a photo, published or not.
app.get("/api/my-passport/photos/:id", requireRole("admin", "pm", "contractor"), async (c) => {
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: "not_found" }, 404);
  return servePassportPhoto(c, who.companyId, c.req.param("id"), "private, no-store");
});

// The sub answering a request. A yes can be revoked; a no is final for that
// request and a fresh one can be sent. Guarded on the status it is moving
// FROM in the UPDATE itself, so two presses move it once.
app.post("/api/my-passport/access/:id", requireRole("admin", "pm", "contractor"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const who = await passportCompany(c);
  if (who.error) return c.json({ error: who.error }, who.error === "not_hireable" ? 409 : 403);
  const b = await c.req.json().catch(() => ({}));
  const req = await c.env.DB.prepare(
    `SELECT pa.*, a.name AS account_name, u.name AS requester_name, u.email AS requester_email
       FROM passport_access pa
       LEFT JOIN accounts a ON a.id = pa.account_id
       LEFT JOIN users u ON u.id = pa.requested_by
      WHERE pa.id = ? AND pa.company_id = ?`).bind(c.req.param("id"), who.companyId).first();
  if (!req) return c.json({ error: "not_found" }, 404);
  const mv = accessMove(req.status, b.action);
  if (!mv.ok) return c.json(mv, mv.error === "unknown_action" ? 400 : 409);
  const r = await c.env.DB.prepare(
    `UPDATE passport_access SET status = ?, decided_at = CURRENT_TIMESTAMP, decided_by = ?
      WHERE id = ? AND status = ?`).bind(mv.to, userId, req.id, req.status).run();
  if (!(r?.meta?.changes > 0)) return c.json({ error: "not_allowed", from: req.status }, 409);

  const co = await c.env.DB.prepare(`SELECT company FROM companies WHERE id = ?`).bind(who.companyId).first();
  const pp = await c.env.DB.prepare(`SELECT slug FROM passports WHERE company_id = ?`).bind(who.companyId).first();
  // The person who asked is told a yes or a no. A revoke is not mailed: the
  // files simply stop opening, and an email announcing it reads as a dispute.
  if ((mv.to === "approved" || mv.to === "declined") && req.requester_email) {
    const mail = passportAccessDecisionEmail({ firstName: String(req.requester_name || "").split(/\s+/)[0],
      companyName: co?.company, approved: mv.to === "approved", link: passportUrl(pp?.slug) || "https://app.subsub.work" });
    const result = await sendEmail(c.env, { to: req.requester_email, subject: mail.subject, text: mail.text, html: mail.html });
    await logMail(c.env, { accountId: req.account_id, companyId: who.companyId, to: req.requester_email,
      kind: "passport_access_decision", subject: mail.subject, result, sentBy: userId });
  }
  await logActivity(c.env, req.account_id, null, "passport_access",
    `${co?.company || "A subcontractor"} ${mv.to === "approved" ? "approved" : mv.to === "declined" ? "declined" : "withdrew"} access to their insurance and W-9`);
  await logEvent(c.env, accountId, userId, `passport.access_${mv.to}`, req.id,
    { companyId: who.companyId, forAccount: req.account_id });
  return c.json({ ok: true, status: mv.to });
});

// ---- the public page ----------------------------------------------------------

// Published only. An unpublished slug, an unknown one and a malformed one all
// answer the same 404, so the route cannot be used to ask which exist. noindex
// on the reply as well as on the page: SubSub is not a directory, and a crawler
// following a shared link must not turn the Passports into one.
async function publishedPassport(env, slug) {
  if (!isSlug(slug)) return null;
  return await env.DB.prepare(
    `SELECT * FROM passports WHERE slug = ? AND published_at IS NOT NULL`).bind(slug).first();
}

app.get("/api/public/passport/:slug", async (c) => {
  const rl = await rateLimit(c.env, "passport-view", clientIp(c), { limit: 120, windowMinutes: 10 });
  if (!rl.ok) return c.json({ error: "slow_down" }, 429);
  c.header("X-Robots-Tag", "noindex");
  c.header("Cache-Control", "private, no-store");
  let row;
  try { row = await publishedPassport(c.env, c.req.param("slug")); }
  catch (err) { if (missingSchema(err)) return c.json({ error: "not_found" }, 404); throw err; }
  if (!row) return c.json({ error: "not_found" }, 404);
  const shape = await passportPublicShape(c.env, row);
  if (!shape) return c.json({ error: "not_found" }, 404);
  // A count for the sub, not a log of who looked. Nothing about the viewer is
  // kept: no address, no account, no time beyond the last one.
  await c.env.DB.prepare(
    `UPDATE passports SET view_count = view_count + 1, last_viewed_at = CURRENT_TIMESTAMP WHERE company_id = ?`
  ).bind(row.company_id).run();
  return c.json(shape);
});

app.get("/api/public/passport/:slug/photo/:id", async (c) => {
  const rl = await rateLimit(c.env, "passport-photo", clientIp(c), { limit: 600, windowMinutes: 10 });
  if (!rl.ok) return c.json({ error: "slow_down" }, 429);
  let row;
  try { row = await publishedPassport(c.env, c.req.param("slug")); }
  catch (err) { if (missingSchema(err)) return c.json({ error: "not_found" }, 404); throw err; }
  if (!row) return c.json({ error: "not_found" }, 404);
  return servePassportPhoto(c, row.company_id, c.req.param("id"), "public, max-age=300");
});

// ---- a hiring account asking, and opening ------------------------------------

// Who may ask: the team of an account that hires. A tenant, an owner and a
// contractor seat are guests or crew on somebody else's account, and the
// subcontractor kind does not hire, so neither has a reason to hold another
// sub's tax form.
async function passportAsker(c, slug) {
  const { accountId } = c.get("auth");
  const acct = await c.env.DB.prepare(`SELECT id, name, kind, company_id FROM accounts WHERE id = ?`).bind(accountId).first();
  let row;
  try { row = await publishedPassport(c.env, slug); }
  catch (err) { if (missingSchema(err)) return { error: "migration_needed" }; throw err; }
  if (!row) return { error: "not_found" };
  if (acct?.company_id && acct.company_id === row.company_id) return { error: "own_passport", row, acct };
  if (!acct || !HIRING_KINDS.includes(acct.kind)) return { error: "not_a_hiring_account", row, acct };
  return { row, acct };
}

const liveAccess = (env, companyId, accountId) => env.DB.prepare(
  `SELECT * FROM passport_access WHERE company_id = ? AND account_id = ?
    ORDER BY requested_at DESC, rowid DESC LIMIT 1`).bind(companyId, accountId).first();

app.get("/api/passport/:slug/access", requireRole("admin", "pm"), async (c) => {
  const who = await passportAsker(c, c.req.param("slug"));
  if (who.error === "not_found" || who.error === "migration_needed") return c.json({ error: who.error }, 404);
  if (who.error === "own_passport") return c.json({ status: "own", mayRequest: false });
  if (who.error) return c.json({ status: "none", mayRequest: false, reason: who.error });
  const last = await liveAccess(c.env, who.row.company_id, who.acct.id);
  const status = last?.status || "none";
  let files = [];
  if (status === "approved") {
    const docs = await currentDocRows(c.env.DB, who.row.company_id).catch(() => ({}));
    files = PASSPORT_ACCESS_KINDS.filter((k) => docs[k]?.file_key)
      .map((k) => ({ kind: k, fileName: docs[k].file_name, expiresOn: docs[k].expires_on || null }));
  }
  return c.json({ status, requestedAt: last?.requested_at || null, decidedAt: last?.decided_at || null,
    mayRequest: status === "none" || status === "declined" || status === "revoked", files });
});

app.post("/api/passport/:slug/access", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const rl = await rateLimit(c.env, "passport-access", accountId, { limit: 30, windowMinutes: 60 });
  if (!rl.ok) return c.json({ error: "slow_down" }, 429);
  const who = await passportAsker(c, c.req.param("slug"));
  if (who.error === "not_found" || who.error === "migration_needed") return c.json({ error: "not_found" }, 404);
  if (who.error) return c.json({ error: who.error }, 409);
  const b = await c.req.json().catch(() => ({}));
  const message = String(b.message ?? "").trim();
  if (message.length > ACCESS_MESSAGE_MAX) return c.json({ error: "message_too_long", max: ACCESS_MESSAGE_MAX }, 400);
  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO passport_access (id, company_id, account_id, requested_by, message) VALUES (?, ?, ?, ?, ?)`
    ).bind(id, who.row.company_id, accountId, userId, message || null).run();
  } catch (err) {
    // ux_passport_access_live: one pending-or-approved request per pair, held
    // by the index even when two presses arrive at once. The live one is the
    // answer rather than an error.
    if (/UNIQUE constraint failed/i.test(String(err?.message || err))) {
      const last = await liveAccess(c.env, who.row.company_id, accountId);
      return c.json({ error: "already_asked", status: last?.status || "pending" }, 409);
    }
    throw err;
  }
  const co = await c.env.DB.prepare(`SELECT company, contact, email FROM companies WHERE id = ?`)
    .bind(who.row.company_id).first();
  const me = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`).bind(userId).first();
  if (co?.email) {
    const link = "https://app.subsub.work/?open=passport";
    const mail = passportAccessRequestEmail({ company: co, contact: co.contact, accountName: who.acct.name,
      requesterName: me?.name, message, link });
    const result = await sendEmail(c.env, { to: co.email, subject: mail.subject, text: mail.text, html: mail.html });
    await logMail(c.env, { accountId, companyId: who.row.company_id, to: co.email,
      kind: "passport_access_request", subject: mail.subject, result, sentBy: userId });
  }
  await logEvent(c.env, accountId, userId, "passport.access_requested", id, { companyId: who.row.company_id });
  return c.json({ ok: true, id, status: "pending" }, 201);
});

// The two files, once the sub has said yes. Pinned three ways: the access row
// is approved for THIS account and THIS company, the kind is one the request
// covers, and the file is the company's CURRENT row of that kind -- a
// superseded certificate drawn here would be last year's cover under this
// year's Passport. Read from company_docs only: the fallback the roster's own
// file route uses is scoped to the caller's own account prefix, which on
// somebody else's company finds nothing anyway.
app.get("/api/passport/:slug/documents/:kind/file", requireRole("admin", "pm"), async (c) => {
  const { kind } = c.req.param();
  if (!PASSPORT_ACCESS_KINDS.includes(kind)) return c.json({ error: "not_found" }, 404);
  const who = await passportAsker(c, c.req.param("slug"));
  if (who.error) return c.json({ error: "not_found" }, 404);
  const last = await liveAccess(c.env, who.row.company_id, who.acct.id);
  if (last?.status !== "approved") return c.json({ error: "not_approved" }, 403);
  let doc = null;
  try {
    doc = await c.env.DB.prepare(
      `SELECT file_key, file_name FROM company_docs
        WHERE company_id = ? AND kind = ? AND superseded_at IS NULL
        ORDER BY uploaded_at DESC LIMIT 1`).bind(who.row.company_id, kind).first();
  } catch (err) { if (!missingSchema(err)) throw err; }
  if (!doc?.file_key) return c.json({ error: "no_file" }, 404);
  const obj = await c.env.FILES.get(doc.file_key);
  if (!obj) return c.json({ error: "no_file" }, 404);
  return new Response(obj.body, { headers: {
    "Content-Type": obj.httpMetadata?.contentType || "application/octet-stream",
    "Content-Disposition": `inline; filename="${(doc.file_name || "document").replace(/[^\w.\-]/g, "_")}"`,
    // Never a shared cache: revoking has to stop it opening.
    "Cache-Control": "private, no-store", "X-Robots-Tag": "noindex",
  } });
});

// The hiring side's own list: every Passport this account has asked about and
// where each one got to.
app.get("/api/passport-access", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT pa.id, pa.status, pa.requested_at, pa.decided_at, p.slug, co.company
         FROM passport_access pa
         JOIN passports p ON p.company_id = pa.company_id
         JOIN companies co ON co.id = pa.company_id
        WHERE pa.account_id = ? ORDER BY pa.requested_at DESC LIMIT 100`).bind(accountId).all();
    return c.json((results || []).map((r) => ({ id: r.id, status: r.status, company: r.company,
      slug: r.slug, url: passportUrl(r.slug), requestedAt: r.requested_at, decidedAt: r.decided_at })));
  } catch (err) {
    if (missingSchema(err)) return c.json([]);
    throw err;
  }
});

app.put("/api/uploads/:kind/:fileName", async (c) => {
  const { accountId } = c.get("auth");
  const { kind, fileName } = c.req.param();
  const type = (c.req.header("Content-Type") || "application/octet-stream").split(";")[0].trim().toLowerCase();

  // Report photos come from people outside the company -- every tenant in
  // every building -- so this one kind is checked rather than trusted. The
  // declared length is refused early so a large body is never streamed at
  // all; the real length is checked after, because Content-Length can lie
  // and a chunked upload does not send one.
  // An avatar is the same shape of thing from the same kind of person -- a
  // guest seat may upload one -- so it gets the same checks. A Passport photo
  // is published to anybody holding the link, so it is checked the same way.
  if (kind === "report-photo" || kind === "avatar" || kind === "passport-photo") {
    if (!PHOTO_TYPES.has(type)) return c.json({ error: "not_an_image", type }, 415);
    const declared = Number(c.req.header("Content-Length") || 0);
    if (declared > MAX_PHOTO_BYTES) return c.json({ error: "too_big", max: MAX_PHOTO_BYTES }, 413);
    const body = await c.req.arrayBuffer();
    if (body.byteLength > MAX_PHOTO_BYTES) return c.json({ error: "too_big", max: MAX_PHOTO_BYTES }, 413);
    if (body.byteLength === 0) return c.json({ error: "empty" }, 400);
    const key = `${accountId}/${kind}/${uid()}-${safeFileName(fileName)}`;
    await c.env.FILES.put(key, body, { httpMetadata: { contentType: type } });
    return c.json({ key, size: body.byteLength, type });
  }

  const key = `${accountId}/${kind}/${uid()}-${decodeURIComponent(fileName)}`;
  await c.env.FILES.put(key, c.req.raw.body, { httpMetadata: { contentType: type } });
  return c.json({ key });
});

// ---------------------------------------------------------------------------
// Nightly sweep target — re-checks every company with a license on file and
// flags any status change. Wire this up as a Cron Trigger (see wrangler.toml).
// ---------------------------------------------------------------------------
async function licenseSweep(env) {
  const { results: companies } = await env.DB.prepare(
    `SELECT id, license, state, license_check FROM companies WHERE license IS NOT NULL AND license != ''`
  ).all();

  const flagged = [];
  for (const co of companies) {
    const prevStatus = parseJson(co.license_check)?.status;
    const state = (co.state || "WA").trim().toUpperCase();
    const result = await verifyLicenseForState(env, state, co.license);
    if (result.status && result.status !== prevStatus) flagged.push({ companyId: co.id, from: prevStatus, to: result.status });
    await storeLicenseCheck(env.DB, co.id, state, result);
  }
  return { checked: companies.length, flagged };
}

// Every Scale account whose address is not live yet. Two different problems
// look the same from a customer's side -- a certificate still being issued,
// and a provisioning call that failed hours ago and nobody saw -- so this
// retries both. Provisioning is idempotent, which is what makes a blind
// retry the right shape here.
//
// Also catches the reverse: an account that dropped to Basic while the
// Worker was mid-deploy and kept an address it is no longer paying for.
async function hostnameSweep(env) {
  if (!hostnameConfig(env)) return { skipped: "cloudflare_not_configured" };

  const { results } = await env.DB.prepare(
    `SELECT id, subdomain, plan, hostname_status FROM accounts
      WHERE (plan = 'scale' AND (hostname_status IS NULL OR hostname_status IN ('pending','failed')))
         OR (plan != 'scale' AND hostname_status IN ('active','pending','failed'))`
  ).all();

  const changed = [];
  for (const a of results) {
    let res;
    if (a.plan === "scale" && a.hostname_status === "pending") {
      // Already registered and merely waiting on a certificate: ask, do not
      // re-register. Re-posting a pending hostname every few minutes is how
      // you find Cloudflare's rate limit.
      res = await checkHostname(env, a.subdomain);
      await env.DB.prepare(
        `UPDATE accounts SET hostname_status = ?, hostname_error = ?, hostname_checked_at = ? WHERE id = ?`
      ).bind(res.status, res.error || null, new Date().toISOString(), a.id).run();
    } else {
      // Never attempted, failed, or on the wrong side of a plan change.
      // syncHostname records its own outcome.
      res = await syncHostname(env, a, { reason: "sweep" });
    }
    if (res && res.status !== a.hostname_status) {
      changed.push({ subdomain: a.subdomain, from: a.hostname_status, to: res.status });
    }
  }
  return { checked: results.length, changed };
}

// The nightly document chase.
//
// Every current certificate with a date on it, asked one question: is a
// reminder due today that has not been sent? shared/docs.js decides that
// (CHASE_AT = 30, 14, 7, 3, 0) and the doc_reminders table remembers the answer,
// so this can run every night without sending the same warning thirty times.
//
// The -1 case is the one worth reading twice. A certificate that lapses under
// work that is ALREADY BOOKED does not cancel the work: stranding a scheduled
// crew over paperwork helps nobody, and the hiring account cannot fix it
// anyway. It is chased harder instead, and the account is told in their own
// activity feed, because they are the ones with a crew arriving uninsured.
async function docExpirySweep(env) {
  const today = new Date().toISOString().slice(0, 10);
  const horizon = addDaysIso(today, Math.max(...CHASE_AT));

  let rows;
  try {
    ({ results: rows } = await env.DB.prepare(
      `SELECT d.*, co.company, co.contact, co.email, co.notify
         FROM company_docs d JOIN companies co ON co.id = d.company_id
        WHERE d.superseded_at IS NULL AND d.expires_on IS NOT NULL
          AND d.expires_on <= ?`
    ).bind(horizon).all());
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return { skipped: "company_docs not migrated" };
  }

  let sent = 0, urgent = 0, skipped = 0;
  for (const d of rows || []) {
    // What has already gone out for this exact document.
    const { results: prior } = await env.DB.prepare(
      `SELECT days_out FROM doc_reminders WHERE company_doc_id = ?`).bind(d.id).all();
    const alreadySent = (prior || []).map((r) => r.days_out);

    // Work on the books past the expiry. Only a live work order counts: a
    // declined or voided one is not somebody turning up.
    const { results: booked } = await env.DB.prepare(
      `SELECT j.id, j.title, j.date, j.account_id
         FROM work_orders wo JOIN jobs j ON j.id = wo.job_id
        WHERE wo.company_id = ? AND wo.voided_at IS NULL
          AND wo.status IN ('accepted', 'pending')
          AND j.date IS NOT NULL AND j.date > ?
        ORDER BY j.date LIMIT 20`
    ).bind(d.company_id, d.expires_on).all();

    const due = dueReminder({
      doc: { fileName: d.file_name, expiresOn: d.expires_on },
      asOf: today, alreadySent, hasBookedWork: (booked || []).length > 0,
    });
    if (due === null) { skipped++; continue; }

    // Which account to write to them as. A company may be engaged by several;
    // the reminder is about their own certificate, so it goes out under the
    // account whose work is at stake, and failing that any that engaged them.
    const accountId = booked?.[0]?.account_id || (await env.DB.prepare(
      `SELECT account_id FROM engagements WHERE company_id = ? LIMIT 1`
    ).bind(d.company_id).first())?.account_id || null;
    const account = accountId ? await env.DB.prepare(
      `SELECT id, name, subdomain FROM accounts WHERE id = ?`).bind(accountId).first() : null;

    // Recorded BEFORE the send. A row that only exists on success means a
    // provider outage re-sends every night.
    //
    // ux_doc_reminder (company_doc_id, days_out) IS THE CONTROL HERE, not the
    // alreadySent list above: two runs racing, or a run whose milestone was
    // already claimed, both come down to this INSERT failing. The list only
    // saves a pointless failing write. Dropping the index would not show up in
    // any behaviour this file changes, which is why there is a test asserting
    // the index exists rather than a test asserting a second send is refused.
    try {
      await env.DB.prepare(
        `INSERT INTO doc_reminders (id, company_doc_id, company_id, days_out, emailed)
         VALUES (?, ?, ?, ?, 0)`
      ).bind(crypto.randomUUID(), d.id, d.company_id, due).run();
    } catch (err) {
      // Another run claimed it. Not an error.
      if (/UNIQUE constraint failed/i.test(String(err?.message || err))) { skipped++; continue; }
      throw err;
    }

    if (d.email) {
      const mail = docExpiryEmail({
        company: d, contact: d.contact, kind: d.kind, expiresOn: d.expires_on,
        daysOut: due, account, jobs: booked || [],
      });
      const result = await sendEmail(env, { to: d.email, subject: mail.subject, text: mail.text, html: mail.html });
      await logMail(env, { accountId, companyId: d.company_id, to: d.email,
        kind: "doc_expiry", subject: mail.subject, result });
      if (result.ok) {
        await env.DB.prepare(`UPDATE doc_reminders SET emailed = 1 WHERE company_doc_id = ? AND days_out = ?`)
          .bind(d.id, due).run();
      }
    }
    sent++;

    // The account with a crew booked under lapsed cover is told, in the feed
    // they already read. One row per account, not per job.
    if (due === -1) {
      urgent++;
      for (const acc of [...new Set((booked || []).map((b) => b.account_id))]) {
        await logActivity(env, acc, null, "doc_expired",
          `${d.company} has work booked and their ${d.kind} expired ${d.expires_on} — replacement requested`);
      }
    }
  }
  return { considered: (rows || []).length, sent, urgent, skipped };
}

// The licence running out, at 30, 7 and 0 days (077).
//
// The date is the state register's own -- `expirationDate` on the check the
// nightly licenseSweep stored -- never one the sub typed, because a reminder
// about a date nobody checked is a reminder that can be wrong in either
// direction. So today this reaches Washington alone, which is the one register
// SubSub reads; the other states' boards publish no date SubSub can see.
//
// Same ledger rule as the certificate chase: the row is written BEFORE the
// send, and ux_license_reminder (company, expiry, days out) is the control, so
// a night that dies halfway never sends the same reminder twice -- and keyed
// on the expiry, so a renewed licence earns a fresh set.
async function licenseReminderSweep(env) {
  const today = new Date().toISOString().slice(0, 10);
  const horizon = addDaysIso(today, Math.max(...LICENSE_CHASE_AT));
  let rows;
  try {
    ({ results: rows } = await env.DB.prepare(
      `SELECT id, company, contact, email, license, state, license_check FROM companies
        WHERE license IS NOT NULL AND license <> '' AND license_check IS NOT NULL
          AND json_extract(license_check, '$.expirationDate') IS NOT NULL
          AND substr(json_extract(license_check, '$.expirationDate'), 1, 10) <= ?`
    ).bind(horizon).all());
  } catch (err) {
    if (!missingSchema(err)) throw err;
    return { skipped: "not migrated" };
  }
  let sent = 0, skipped = 0;
  for (const co of rows || []) {
    const check = parseJson(co.license_check, null);
    // A registry that answered "not found" has no expiry worth chasing.
    if (!check?.found) { skipped++; continue; }
    const expiresOn = String(check.expirationDate).slice(0, 10);
    let alreadySent;
    try {
      const { results: prior } = await env.DB.prepare(
        `SELECT days_out FROM license_reminders WHERE company_id = ? AND expires_on = ?`).bind(co.id, expiresOn).all();
      alreadySent = (prior || []).map((r) => r.days_out);
    } catch (err) {
      if (!missingSchema(err)) throw err;
      return { skipped: "license_reminders not migrated" };
    }
    // One reminder at most after it has lapsed, and none for a licence that
    // lapsed before anybody here was chasing it: the 0 is "today", not
    // "every night since".
    const due = licenseReminderDue({ expiresOn, today, alreadySent });
    if (due === null || (due === 0 && expiresOn < addDaysIso(today, -7))) { skipped++; continue; }
    try {
      await env.DB.prepare(
        `INSERT INTO license_reminders (id, company_id, expires_on, days_out, emailed) VALUES (?, ?, ?, ?, 0)`
      ).bind(uid(), co.id, expiresOn, due).run();
    } catch (err) {
      if (/UNIQUE constraint failed/i.test(String(err?.message || err))) { skipped++; continue; }
      throw err;
    }
    if (co.email) {
      const st = normalizeState(co.state);
      const pp = await env.DB.prepare(`SELECT slug FROM passports WHERE company_id = ?`).bind(co.id).first()
        .catch(() => null);
      const own = await env.DB.prepare(`SELECT id FROM accounts WHERE company_id = ?`).bind(co.id).first()
        .catch(() => null);
      const mail = licenseExpiryEmail({ company: co, contact: co.contact, number: co.license, expiresOn,
        daysOut: Math.max(0, daysBetween(today, expiresOn)),
        registry: st === "WA" ? "Washington L&I" : st ? `${stateName(st)}'s licensing board` : null,
        link: passportUrl(pp?.slug) || "https://app.subsub.work/?open=passport" });
      const result = await sendEmail(env, { to: co.email, subject: mail.subject, text: mail.text, html: mail.html });
      await logMail(env, { accountId: own?.id || null, companyId: co.id, to: co.email,
        kind: "license_expiry", subject: mail.subject, result });
      if (result.ok) {
        await env.DB.prepare(
          `UPDATE license_reminders SET emailed = 1 WHERE company_id = ? AND expires_on = ? AND days_out = ?`
        ).bind(co.id, expiresOn, due).run();
      }
    }
    sent++;
  }
  return { considered: (rows || []).length, sent, skipped };
}

// ---------------------------------------------------------------------------
// Growth sweeps. Both are nightly, both are idempotent, and both write their
// own suppression before they send -- a sweep that cannot be run twice safely
// is a sweep nobody dares re-run after it fails halfway.

// A renewal reaches the people the subcontractor already sent that document to.
//
// The pack page promises it stays current, and the link expires in SHARE_DAYS,
// so a year later when the certificate actually renews every recipient is
// holding a dead URL. This sends a fresh one. `shared/retouch.js` holds every
// rule about who, how often, and why not; migration 044 holds the ledger.
async function retouchSweep(env) {
  const today = new Date().toISOString().slice(0, 10);
  const skipped = {};
  let sent = 0, considered = 0;
  const skip = (why) => { skipped[why] = (skipped[why] || 0) + 1; };

  let docs;
  try {
    // Current rows, uploaded recently, for a company that has a prior row of
    // the same kind -- which is what makes it a renewal rather than a first.
    ({ results: docs } = await env.DB.prepare(
      `SELECT cd.id, cd.company_id, cd.kind, cd.expires_on, cd.uploaded_at,
              co.company, co.contact,
              (SELECT COUNT(*) FROM company_docs p
                WHERE p.company_id = cd.company_id AND p.kind = cd.kind AND p.id != cd.id) AS priors
         FROM company_docs cd
         JOIN companies co ON co.id = cd.company_id
        WHERE cd.superseded_at IS NULL
          AND date(cd.uploaded_at) >= date(?, '-' || ? || ' days')
        ORDER BY cd.uploaded_at DESC LIMIT 500`
    ).bind(today, RETOUCH_WINDOW_DAYS).all());
  } catch (err) {
    if (missingSchema(err)) return { skipped: "not_migrated" };
    throw err;
  }

  for (const d of docs || []) {
    // Everybody this company ever sent that document to. Distinct by address:
    // somebody sent to twice is one person, and the second share replaced the
    // first anyway.
    const { results: people } = await env.DB.prepare(
      `SELECT ds.to_email, ds.to_name, MAX(ds.revoked_at) AS revoked_at
         FROM doc_shares ds
        WHERE ds.company_id = ?
        GROUP BY ds.to_email`
    ).bind(d.company_id).all();

    for (const p of people || []) {
      considered += 1;
      const already = await env.DB.prepare(
        `SELECT 1 AS yes FROM doc_retouches WHERE to_email = ? AND doc_id = ?`
      ).bind(p.to_email, d.id).first();
      const last = await env.DB.prepare(
        `SELECT MAX(sent_at) AS at FROM doc_retouches WHERE to_email = ?`
      ).bind(p.to_email).first();
      const { results: outs } = await env.DB.prepare(
        `SELECT company_id FROM doc_share_optouts WHERE to_email = ?`
      ).bind(p.to_email).all();

      const may = mayRetouch({
        kind: d.kind, hasPrior: d.priors > 0, expiresOn: d.expires_on,
        uploadedAt: d.uploaded_at, today,
        alreadySentForThisDoc: !!already,
        lastTouchedAt: last?.at || null,
        optedOut: isOptedOut((outs || []).map((o) => ({ companyId: o.company_id })), d.company_id),
        shareRevoked: !!p.revoked_at,
      });
      if (!may.ok) { skip(may.reason); continue; }

      // Write the suppression FIRST. A send that succeeds and a ledger row
      // that does not is how somebody gets the same email every night.
      const retouchId = uid();
      try {
        await env.DB.prepare(
          `INSERT INTO doc_retouches (id, company_id, to_email, doc_id) VALUES (?, ?, ?, ?)`
        ).bind(retouchId, d.company_id, p.to_email, d.id).run();
      } catch (err) {
        // Another pass got there first. That is the index doing its job.
        if (/UNIQUE constraint failed/i.test(String(err?.message || err))) { skip("raced"); continue; }
        throw err;
      }

      // A fresh link, because theirs expired months ago. Same shape as any
      // other share, so it appears in the subcontractor's own sent list and
      // can be revoked with the rest.
      const shareId = uid();
      const token = shareToken();
      const expires = new Date(Date.now() + SHARE_DAYS * 86400000)
        .toISOString().slice(0, 19).replace("T", " ");
      await env.DB.prepare(
        `INSERT INTO doc_shares (id, token, company_id, sent_by, to_email, to_name, note, expires_at)
         VALUES (?, ?, ?, NULL, ?, ?, NULL, ?)`
      ).bind(shareId, token, d.company_id, p.to_email, p.to_name || null, expires).run();
      await env.DB.prepare(`UPDATE doc_retouches SET share_id = ? WHERE id = ?`)
        .bind(shareId, retouchId).run();

      const mail = docRenewedEmail({
        company: d.company, contact: d.contact, toName: p.to_name,
        kind: d.kind, expiresOn: d.expires_on,
        link: `${APP_ORIGIN}/?pack=${encodeURIComponent(token)}`,
        days: SHARE_DAYS,
      });
      const res = await sendEmail(env, { to: p.to_email, ...mail });
      await logMail(env, { accountId: null, companyId: d.company_id, to: p.to_email,
        kind: "doc_renewed", subject: mail.subject, result: res, sentBy: null });
      if (res?.ok) sent += 1;
    }
  }
  return { considered, sent, skipped };
}

// Accounts that have just enough of a roster to want it to fill itself.
//
// The public application form has existed since the start and nobody knows it
// is there. Nudged once, ever -- a growth email that repeats is a growth email
// people filter, and there is no second thing to say.
async function embedNudgeSweep(env) {
  let rows;
  try {
    ({ results: rows } = await env.DB.prepare(
      `SELECT a.id, a.name, a.subdomain, COUNT(en.id) AS subs
         FROM accounts a
         JOIN engagements en ON en.account_id = a.id AND en.status != 'ended'
        WHERE a.subdomain IS NOT NULL AND a.subdomain != 'app'
          AND NOT EXISTS (SELECT 1 FROM events ev
                           WHERE ev.account_id = a.id AND ev.kind = 'growth.embed_nudged')
        GROUP BY a.id
       HAVING COUNT(en.id) >= ?
        LIMIT 200`
    ).bind(EMBED_NUDGE_AT).all());
  } catch (err) {
    if (missingSchema(err)) return { skipped: "not_migrated" };
    throw err;
  }

  let sent = 0;
  for (const a of rows || []) {
    if (!shouldNudgeEmbed(a.subs, false)) continue;
    // Admins only. A project manager does not put things on the website, and
    // a contractor seat in this account is somebody else's company.
    const { results: admins } = await env.DB.prepare(
      `SELECT u.email, u.name FROM memberships m JOIN users u ON u.id = m.user_id
        WHERE m.account_id = ? AND m.role = 'admin' AND u.email IS NOT NULL LIMIT 3`
    ).bind(a.id).all();
    if (!admins?.length) continue;

    // Suppression before the send, as above.
    await logEvent(env, a.id, null, "growth.embed_nudged", null, { subs: a.subs });
    for (const ad of admins) {
      const mail = embedNudgeEmail({ name: ad.name, accountName: a.name,
        subdomain: a.subdomain, subs: a.subs });
      const res = await sendEmail(env, { to: ad.email, ...mail });
      await logMail(env, { accountId: a.id, companyId: null, to: ad.email,
        kind: "embed_nudge", subject: mail.subject, result: res, sentBy: null });
      if (res?.ok) sent += 1;
    }
  }
  return { accounts: (rows || []).length, sent };
}

