// ---------------------------------------------------------------------------
// Properties (portfolio / property managers)
// ---------------------------------------------------------------------------
// Every query is scoped by account_id, so one account can never read or write
// another's buildings even with a guessed id.

const propertyRowToJs = (r) => ({
  id: r.id, accountId: r.account_id, name: r.name, address: r.address,
  city: r.city, state: r.state, zip: r.zip,
  units: r.units == null ? "" : r.units, notes: r.notes || "",
  // Whether somebody else owns this building. A boolean, not the account id:
  // the screen needs to know whether a handover is even possible, and which
  // account it is belongs to the transfer record rather than to every property
  // row every screen loads.
  ownedByAnother: !!(r.owner_account_id && r.owner_account_id !== r.account_id),
  // Whether this account has SAID it owns this one. 039's backfill makes
  // "owner_account_id is mine" true for every building a managing agent typed
  // in, so it cannot answer that question; this is the answer, and it is what
  // lets an agent who really does own a building appoint a manager for it.
  ownerDeclared: !!r.owner_declared_at,
});

app.get("/api/properties", async (c) => {
  const auth = c.get("auth");
  // A building owner is scoped to their own buildings. The filter is here and
  // not only in the browser, because the browser is not the thing being
  // trusted -- this endpoint answers a request, not a page.
  const scope = scopeClause(auth, "id");
  // Buildings this account OPERATES, plus buildings it OWNS but has appointed
  // somebody else to run. Without the second half, an owner who appoints a
  // manager loses sight of their own building the moment they do it -- which
  // would make appointing one feel like giving it away, and it is the opposite.
  //
  // A row that is owned and not operated is marked, because almost nothing on
  // these screens applies to it: the owner does not assign that building's
  // contractors or issue its work orders, their manager does.
  let owned = { results: [] };
  try {
    owned = await c.env.DB.prepare(
      `SELECT p.*, a.name AS operated_by_name FROM properties p
         LEFT JOIN accounts a ON a.id = p.account_id
        WHERE p.owner_account_id = ? AND p.account_id != ? ORDER BY p.name`
    ).bind(auth.accountId, auth.accountId).all();
  } catch (err) {
    // A database without 039 has no owner_account_id and behaves exactly as it
    // did before any of this.
    if (!missingSchema(err)) throw err;
  }
  const { results } = await c.env.DB.prepare(
    `SELECT * FROM properties WHERE account_id = ? ${scope.sql} ORDER BY name`
  ).bind(auth.accountId, ...scope.vals).all();
  return c.json([
    ...results.map(propertyRowToJs),
    // An owner's guest seat is scoped to named buildings and must not pick these
    // up: a scoped seat seeing a building through a second door would defeat
    // the scope.
    ...(auth.role === "owner" || auth.role === "tenant" ? [] :
      (owned.results || []).map((r) => ({
        ...propertyRowToJs(r), managedBy: r.operated_by_name || null, ownedNotOperated: true,
      }))),
  ]);
});

app.post("/api/properties", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const b = await c.req.json();
  const name = (b.name || "").trim();
  if (!name) return c.json({ error: "name_required" }, 400);
  const id = uid();
  // owner_account_id is set here for the same reason 039 backfilled it: a
  // building whose owner is NULL can never be handed over (canHandOver says
  // no_owner_account) and can never have a manager appointed for it. 039 fixed
  // every row that existed and this INSERT did not learn the lesson, so every
  // building added afterwards arrived unowned -- silently, because
  // propertyWithOwner coalesces to account_id on the way out and the screens
  // looked right. CHECK.sql's m039_unowned is the only thing that ever said so.
  const vals = [id, accountId, name, b.address || null, b.city || null, b.state || null,
    b.zip || null, b.units === "" || b.units == null ? null : Number(b.units), b.notes || null];
  try {
    await c.env.DB.prepare(
      `INSERT INTO properties (id, account_id, name, address, city, state, zip, units, notes,
         owner_account_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(...vals, accountId).run();
  } catch (err) {
    // A database without 039 has no such column and behaves as it always did.
    if (!missingSchema(err)) throw err;
    await c.env.DB.prepare(
      `INSERT INTO properties (id, account_id, name, address, city, state, zip, units, notes)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(...vals).run();
  }
  await logEvent(c.env, accountId, c.get("auth").userId, "property.created", id, { name });
  await logActivity(c.env, accountId, c.get("auth").userId, "property_added", `Added property ${name}`);
  return c.json({ id }, 201);
});

app.patch("/api/properties/:id", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const b = await c.req.json();
  const cols = { name: "name", address: "address", city: "city", state: "state",
                 zip: "zip", units: "units", notes: "notes" };
  const sets = [], vals = [];
  for (const [k, col] of Object.entries(cols)) {
    if (b[k] === undefined) continue;
    sets.push(`${col} = ?`);
    vals.push(k === "units" ? (b[k] === "" || b[k] == null ? null : Number(b[k])) : b[k]);
  }
  if (!sets.length) return c.json({ ok: true });
  vals.push(c.req.param("id"), accountId);
  await c.env.DB.prepare(
    `UPDATE properties SET ${sets.join(", ")} WHERE id = ? AND account_id = ?`
  ).bind(...vals).run();
  return c.json({ ok: true });
});

app.delete("/api/properties/:id", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const id = c.req.param("id");
  // engagement_properties cascades; jobs keep their history, so only the
  // forward pointer is cleared.
  await c.env.DB.batch([
    c.env.DB.prepare(
      `DELETE FROM engagement_properties WHERE property_id = ?
        AND engagement_id IN (SELECT id FROM engagements WHERE account_id = ?)`
    ).bind(id, accountId),
    c.env.DB.prepare(
      `UPDATE jobs SET property_id = NULL WHERE property_id = ? AND account_id = ?`
    ).bind(id, accountId),
    c.env.DB.prepare(`DELETE FROM properties WHERE id = ? AND account_id = ?`).bind(id, accountId),
  ]);
  await logEvent(c.env, accountId, c.get("auth").userId, "property.deleted", id, null);
  return c.json({ ok: true });
});

// Which properties a vendor is scoped to, for THIS account's engagement only.
app.put("/api/subs/:companyId/properties", requireRole("admin", "pm"), async (c) => {
  const { accountId } = c.get("auth");
  const companyId = c.req.param("companyId");
  const b = await c.req.json(); // { propertyIds: [...] }
  const en = await c.env.DB.prepare(
    `SELECT id FROM engagements WHERE account_id = ? AND company_id = ?`
  ).bind(accountId, companyId).first();
  if (!en) return c.json({ error: "not_engaged" }, 404);

  const ids = Array.isArray(b.propertyIds) ? b.propertyIds : [];
  // Only properties this account actually owns — a foreign id is dropped
  // rather than trusted.
  const stmts = [c.env.DB.prepare(`DELETE FROM engagement_properties WHERE engagement_id = ?`).bind(en.id)];
  for (const pid of ids) {
    stmts.push(c.env.DB.prepare(
      `INSERT OR IGNORE INTO engagement_properties (engagement_id, property_id)
       SELECT ?, id FROM properties WHERE id = ? AND account_id = ?`
    ).bind(en.id, pid, accountId));
  }
  await c.env.DB.batch(stmts);
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Change orders
// ---------------------------------------------------------------------------
// A work order is never edited once accepted. Each change is a numbered change
// order the other side accepts or declines, and the revised value is derived
// from the accepted ones (see the work_order_revised view).

const changeOrderRowToJs = (r) => ({
  id: r.id, workOrderId: r.work_order_id, seq: r.seq, kind: r.kind, origin: r.origin,
  scope: r.scope, valueDelta: r.value_delta_cents, status: r.status,
  raisedBy: r.raised_by, raisedAt: r.raised_at, respondBy: r.respond_by,
  respondedAt: r.responded_at, note: r.note || "",
  jobId: r.job_id, trade: r.trade, companyId: r.company_id,
});

app.get("/api/change-orders", async (c) => {
  const { accountId } = c.get("auth");
  const { results } = await c.env.DB.prepare(
    `SELECT co.*, w.job_id, w.trade, w.company_id
       FROM change_orders co
       JOIN work_orders w ON w.id = co.work_order_id
       JOIN jobs j ON j.id = w.job_id
      WHERE j.account_id = ?
      ORDER BY co.raised_at DESC`
  ).bind(accountId).all();
  return c.json(results.map(changeOrderRowToJs));
});

// Either side can raise one: the GC, or the sub who finds hidden conditions.
app.post("/api/change-orders", async (c) => {
  const { accountId, userId, role, companyId } = c.get("auth");
  const b = await c.req.json(); // { workOrderId, kind, scope, valueDelta, respondBy, note }
  const wo = await c.env.DB.prepare(
    `SELECT w.id, w.status, w.company_id FROM work_orders w JOIN jobs j ON j.id = w.job_id
      WHERE w.id = ? AND j.account_id = ?`
  ).bind(b.workOrderId, accountId).first();
  if (!wo) return c.json({ error: "work_order_not_found" }, 404);
  // Account scope alone is not enough for a contractor: every sub in the
  // account shares it. They may only touch their own company's work order.
  if (role === "contractor" && wo.company_id !== companyId) {
    return c.json({ error: "forbidden" }, 403);
  }
  // Guardrail from the deployment doc: no change order against a work order
  // that was never accepted — reissue it instead.
  if (wo.status !== "accepted") return c.json({ error: "work_order_not_accepted" }, 409);

  const origin = role === "contractor" ? "sub" : "gc";
  const next = await c.env.DB.prepare(
    `SELECT COALESCE(MAX(seq), 0) + 1 AS n FROM change_orders WHERE work_order_id = ?`
  ).bind(wo.id).first();
  const id = uid();
  await c.env.DB.prepare(
    `INSERT INTO change_orders (id, work_order_id, seq, kind, origin, scope, value_delta_cents, raised_by, respond_by, note)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(id, wo.id, next.n, b.kind || "added", origin, b.scope || "",
    Number(b.valueDelta) || 0, userId, b.respondBy || null, b.note || null).run();
  await logEvent(c.env, accountId, userId, "change_order.raised", id, { workOrderId: wo.id, seq: next.n, origin });
  await logActivity(c.env, accountId, userId, "change_order",
    `Change order #${next.n} raised by the ${origin === "sub" ? "subcontractor" : "general contractor"}`);
  return c.json({ id, seq: next.n }, 201);
});

// The other side responds. Whoever raised it cannot also accept it.
app.post("/api/change-orders/:id/respond", async (c) => {
  const { accountId, role, companyId } = c.get("auth");
  const b = await c.req.json(); // { status: "accepted" | "declined" }
  if (!["accepted", "declined"].includes(b.status)) return c.json({ error: "bad_status" }, 400);
  const co = await c.env.DB.prepare(
    `SELECT co.*, w.company_id AS wo_company_id FROM change_orders co
       JOIN work_orders w ON w.id = co.work_order_id
       JOIN jobs j ON j.id = w.job_id
      WHERE co.id = ? AND j.account_id = ?`
  ).bind(c.req.param("id"), accountId).first();
  if (!co) return c.json({ error: "not_found" }, 404);
  if (role === "contractor" && co.wo_company_id !== companyId) {
    return c.json({ error: "forbidden" }, 403);
  }
  if (co.status !== "pending") return c.json({ error: "already_resolved" }, 409);
  const responderSide = role === "contractor" ? "sub" : "gc";
  if (responderSide === co.origin) return c.json({ error: "cannot_answer_own" }, 403);

  await c.env.DB.prepare(
    `UPDATE change_orders SET status = ?, responded_at = CURRENT_TIMESTAMP WHERE id = ?`
  ).bind(b.status, co.id).run();
  await logEvent(c.env, accountId, c.get("auth").userId, "change_order." + b.status, co.id, { workOrderId: co.work_order_id, seq: co.seq });
  await logActivity(c.env, accountId, c.get("auth").userId, "change_order",
    `Change order #${co.seq} ${b.status}`);
  return c.json({ ok: true });
});

// Original, revised and pending count for one work order — derived, never stored.
app.get("/api/work-orders/:id/revised", async (c) => {
  const { accountId } = c.get("auth");
  const row = await c.env.DB.prepare(
    `SELECT r.* FROM work_order_revised r
       JOIN work_orders w ON w.id = r.id
       JOIN jobs j ON j.id = w.job_id
      WHERE r.id = ? AND j.account_id = ?`
  ).bind(c.req.param("id"), accountId).first();
  if (!row) return c.json({ error: "not_found" }, 404);
  return c.json({ id: row.id, originalCents: row.original_cents,
    revisedCents: row.revised_cents, pendingCount: row.pending_count });
});

// ---------------------------------------------------------------------------
// Platform console — SubSub's own staff

// ---------------------------------------------------------------------------
// The CRM API: scheduled jobs arriving from somebody else's system
// ---------------------------------------------------------------------------
// A job gets scheduled in JobNimbus, their CRM posts it here, and it lands in
// SubSub as a job with unassigned trade slots -- which is what the dashboard
// counts and what the account opened SubSub to do. Nothing here finds or
// assigns a contractor: this is the arrival, and a person still picks.
//
// `app/shared/ingest.js` holds the field rules, because the route, the
// published documentation and the tests all have to agree about them and a
// field required by one and optional in another is an integration that fails
// at 2am against a page saying it should work.
//
// Three properties carry this and each is easy to destroy by accident.
//
// THE TOKEN IS NEVER STORED. `api_tokens.token_hash` is a SHA-256 of it, the
// way a password would be, so a copy of that table is not a working key to
// every customer's integration. It follows that it can be shown exactly once,
// and the screen says so rather than offering a "view" that cannot work.
//
// A RETRY MUST NOT DUPLICATE. A webhook that does not get a 200 sends again,
// and one scheduled job becoming four is four contractors asked to show up on
// a Tuesday. `job_sources` and its unique index are what make the second POST
// return the first job; this is why `externalId` is required.
//
// THE PLAN IS CHECKED ON EVERY CALL, not only when the token is minted. A
// downgrade has to stop the integration, or Scale is a thing you buy once.

const API_TOKEN_PREFIX = "ssk_";
// Shown in the token list so somebody holding three can tell them apart
// without being able to read any of them.
const API_TOKEN_SHOWN = 11;

function mintApiToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  const body = btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  return API_TOKEN_PREFIX + body;
}

async function hashApiToken(raw) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(raw));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// Scale, or comped -- which outranks Stripe and is sometimes exactly right.
// `accounts.plan` is already written to 'scale' for a comped account, so the
// second half is belt and braces rather than the rule.
const accountOnScale = (a) => a?.plan === "scale" || !!a?.comped;

// Everything the API answers has this shape, so an integrator writing error
// handling once handles all of it. `docs` is on every failure because the
// person reading it is looking at a log, not at our website.
const API_DOCS_URL = "https://subsub.work/developers";
const apiError = (c, status, error, message, extra = {}) =>
  c.json({ error, message, docs: API_DOCS_URL, ...extra }, status);

// Resolves the bearer token to an account, or answers. Returns null when it
// has already answered, so callers `if (!ctx) return;` -- there is no second
// place that decides what a bad token means.
async function apiCaller(c) {
  const header = c.req.header("Authorization") || "";
  const raw = /^Bearer\s+(.+)$/i.exec(header.trim())?.[1]?.trim();
  if (!raw) {
    return { res: apiError(c, 401, "missing_token",
      "Send your SubSub API token as: Authorization: Bearer <token>.") };
  }
  return apiCallerForToken(c, raw);
}

// The same caller, with the token read off the PATH instead of a header.
//
// Not a weaker door -- every check below is the one the header route makes.
// It exists because a JobNimbus automation webhook takes a URL and offers no
// field for a header, so a token that can only arrive in a header cannot
// arrive at all. Same shape and same reasoning as /api/pack/:token.
async function apiCallerByPathToken(c) {
  const raw = String(c.req.param("token") || "").trim();
  if (!raw) {
    return { res: apiError(c, 401, "missing_token",
      "The webhook URL must end with your SubSub webhook token.") };
  }
  return apiCallerForToken(c, raw);
}

async function apiCallerForToken(c, raw) {
  let row;
  try {
    row = await c.env.DB.prepare(
      `SELECT t.id, t.account_id, t.revoked_at, t.last_used_at,
              a.plan AS plan, a.comped AS comped, a.kind AS kind
         FROM api_tokens t JOIN accounts a ON a.id = t.account_id
        WHERE t.token_hash = ?`
    ).bind(await hashApiToken(raw)).first();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { res: apiError(c, 503, "migration_needed",
      "This SubSub environment has not had migration 048 applied yet.", { migration }) };
  }

  // A revoked token and one that never existed answer identically. A separate
  // "revoked" reply tells somebody holding a stolen key that it WAS real and
  // which account it belonged to, which is a fact they have no business
  // collecting -- the same rule the connect lookup follows.
  if (!row || row.revoked_at) {
    return { res: apiError(c, 401, "invalid_token", "That token is not valid.") };
  }

  // Checked here rather than only at minting, so a downgrade actually stops
  // the integration. Named plainly, because the person reading this log can
  // do something about it.
  if (!accountOnScale(row)) {
    return { res: apiError(c, 403, "scale_required",
      "The SubSub API is part of the Scale plan. This account is on Basic.") };
  }

  // Creating a job is the hiring side's act, exactly as it is on the screen.
  // A subcontractor account has nobody to assign, so a job posted to one
  // would arrive with slots that can never be filled.
  if (!HIRING_KINDS.includes(row.kind)) {
    return { res: apiError(c, 403, "not_a_hiring_account",
      "This account is not set up to hire subcontractors, so it cannot take jobs.",
      { kind: row.kind }) };
  }

  const limit = await rateLimit(c.env, "api-ingest", row.account_id, { limit: 300, windowMinutes: 1 });
  if (!limit.ok) {
    return { res: apiError(c, 429, "rate_limited",
      "Too many requests. This endpoint accepts 300 per minute per account.") };
  }

  return { token: row, accountId: row.account_id };
}

// Written at most once a minute. A write on every call would make the busiest
// integration the slowest, and the question this answers -- "is this token
// actually being used" -- does not need the second hand.
async function touchApiToken(env, token) {
  const last = token.last_used_at ? Date.parse(token.last_used_at + "Z") : 0;
  if (Number.isFinite(last) && Date.now() - last < 60_000) return;
  try {
    await env.DB.prepare(`UPDATE api_tokens SET last_used_at = datetime('now') WHERE id = ?`)
      .bind(token.id).run();
  } catch (err) {
    // Recording that a token was used must never fail the thing it was used
    // for. Same rule the activity log follows.
    console.warn("[api] last_used not recorded:", err?.message || err);
  }
}

// POST /api/v1/jobs -- the one endpoint a CRM calls.
// Creating the job, and the retry protection. ONE implementation: the generic
// endpoint and every CRM-shaped receiver go through here, because two copies
// of an insert this careful is two places for the duplicate guard to rot.
//
// Answers a plain object rather than a Response, so each caller can shape its
// own reply -- the JobNimbus one has to report the trade mapping too.
async function ingestJob(c, { accountId, token, source, job: j }) {
  if (j.propertyId) {
    const prop = await c.env.DB.prepare(
      `SELECT id FROM properties WHERE id = ? AND account_id = ?`
    ).bind(j.propertyId, accountId).first();
    // not_found for somebody else's building as well as one that does not
    // exist: a 403 would confirm which property ids are real.
    if (!prop) {
      return { error: "property_not_found", status: 404,
        message: "No building with that propertyId on this account." };
    }
  }

  // The retry. Asked before the insert AND enforced by the unique index
  // after it: the index is what is correct when two deliveries arrive at
  // once, this is what makes the ordinary retry cheap and hands back the id.
  let seen;
  try {
    seen = await c.env.DB.prepare(
      `SELECT job_id FROM job_sources
        WHERE account_id = ? AND source = ? AND external_id = ?`
    ).bind(accountId, source, j.externalId).first();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { error: "migration_needed", status: 503,
      message: "This SubSub environment has not had migration 048 applied yet.",
      extra: { migration } };
  }
  if (seen) {
    await touchApiToken(c.env, token);
    return { jobId: seen.job_id, duplicate: true };
  }

  const id = uid();
  // created_by is deliberately NULL: no person created this. Provenance goes
  // on job_sources, where it is true.
  const cols = ["id", "account_id", "title", "client", "address", "area", "zip",
    "sqft", "stories", "date", "time", "trades", "scope", "property_id",
    "materials_paid_by", "material_source", "notes", "created_by"];
  const vals = [id, accountId, j.title, j.client, j.address, j.area, j.zip,
    j.sqft, j.stories, j.date, j.time, JSON.stringify(j.trades || []), j.scope, j.propertyId,
    j.materialsPaidBy, j.materialSource, j.notes, null];

  try {
    await c.env.DB.prepare(
      `INSERT INTO jobs (${cols.join(", ")}) VALUES (${cols.map(() => "?").join(", ")})`
    ).bind(...vals).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { error: "migration_needed", status: 503,
      message: "This SubSub database is behind the code.", extra: { migration } };
  }

  try {
    await c.env.DB.prepare(
      `INSERT INTO job_sources (job_id, account_id, source, external_id, token_id)
       VALUES (?, ?, ?, ?, ?)`
    ).bind(id, accountId, source, j.externalId, token.id).run();
  } catch (err) {
    // The unique index fired: a second delivery landed between the check and
    // here. The other one won; report the job that exists rather than leaving
    // one nothing points at.
    const other = await c.env.DB.prepare(
      `SELECT job_id FROM job_sources WHERE account_id = ? AND source = ? AND external_id = ?`
    ).bind(accountId, source, j.externalId).first().catch(() => null);
    if (other) {
      await c.env.DB.prepare(`DELETE FROM jobs WHERE id = ?`).bind(id).run().catch(() => {});
      await touchApiToken(c.env, token);
      return { jobId: other.job_id, duplicate: true };
    }
    throw err;
  }

  await logEvent(c.env, accountId, null, "job.created", id,
    { title: j.title, via: "api", source, externalId: j.externalId });
  await logActivity(c.env, accountId, null, "job_created",
    (j.trades || []).length
      ? `${j.title} arrived from ${source === "other" ? "your CRM" : source} and needs contractors`
      // Said differently when nothing mapped, because the thing to do is
      // different: this one cannot be assigned until somebody says what
      // trade it is.
      : `${j.title} arrived from ${source === "other" ? "your CRM" : source} and needs a trade`);
  await touchApiToken(c.env, token);
  return { jobId: id, duplicate: false };
}

app.post("/api/v1/jobs", async (c) => {
  const ctx = await apiCaller(c);
  if (ctx.res) return ctx.res;
  const { token, accountId } = ctx;

  let body;
  try { body = await c.req.json(); }
  catch { return apiError(c, 400, "invalid_json", "The request body must be valid JSON."); }

  const check = validateIngest(body, { tradeIds: TRADE_IDS });
  if (!check.ok) {
    return apiError(c, 400, "invalid_request",
      "Some fields were missing or not understood. See `errors` for which.",
      { errors: check.errors });
  }

  const res = await ingestJob(c, { accountId, token, source: check.job.source, job: check.job });
  if (res.error) return apiError(c, res.status, res.error, res.message, res.extra || {});

  return c.json({ ok: true, duplicate: res.duplicate, jobId: res.jobId,
    trades: check.job.trades,
    url: `https://app.subsub.work/?job=${res.jobId}` }, res.duplicate ? 200 : 201);
});

// ---- Two reads, because an integration builder needs them ----------------
//
// Zapier cannot offer "Create a job in SubSub" without them, and neither can
// anybody writing code against this API. Both go through `apiCaller`, so the
// Scale gate, the hash lookup and the revoked-reads-as-invalid rule are the
// ones POST /api/v1/jobs makes -- a read endpoint that is a lighter door is a
// lighter door.

// What this token is for, which is the only way a connection can be labelled.
//
// Zapier's auth test needs an endpoint that fails on a bad key and succeeds on
// a good one; without this, the first thing anybody learns about a wrong token
// is a job that did not arrive. It answers the ACCOUNT, never the person: no
// user created the call and `created_by` on an ingested job is NULL for the
// same reason.
app.get("/api/v1/me", async (c) => {
  const ctx = await apiCaller(c);
  if (ctx.res) return ctx.res;
  const a = await c.env.DB.prepare(
    `SELECT id, name, subdomain, kind, plan FROM accounts WHERE id = ?`
  ).bind(ctx.accountId).first().catch(() => null);
  if (!a) return apiError(c, 404, "not_found", "That token names an account that no longer exists.");
  return c.json({ ok: true, account: { id: a.id, name: a.name,
    subdomain: a.subdomain, kind: a.kind, plan: a.plan } });
});

// The trades, so a dropdown can be a dropdown.
//
// Without it an integration asks somebody to type `windows_doors` from memory,
// and a typo is a job that arrives with a slot nobody can fill -- discovered
// when the crew does not turn up. Read off shared/trades.js, which is also
// what validates the POST, so the list somebody picks from and the list that
// accepts their answer cannot disagree.
//
// Authenticated, not public. It is not a secret, but a token gate keeps the
// public surface at what it has to be, and an integration holds one anyway.
app.get("/api/v1/trades", async (c) => {
  const ctx = await apiCaller(c);
  if (ctx.res) return ctx.res;
  return c.json({ ok: true, trades: TRADES });
});

// The account's own buildings, so `propertyId` can be a dropdown too.
//
// Same reason as the trades: a job carrying a property id typed from memory is
// refused with `property_not_found`, and the integrator is left comparing a
// uuid against a screen. It is a uuid -- nobody holds one in their head, so
// the field was unusable without this.
//
// IT OFFERS EXACTLY WHAT `ingestJob` ACCEPTS, which is why the WHERE clause is
// `account_id = ?` and nothing more. That route takes a building this account
// OPERATES and no other -- deliberately, unlike `POST /api/jobs` on the screen,
// which also takes one the caller owns and somebody else runs. A dropdown
// listing a building the route then refuses is the screen-that-lies rule
// pointed at a picker; so is one that hides a building the route would take.
//
// PAGED, because a dropdown that silently stops at its first page is a
// building that does not exist as far as the person picking is concerned --
// the same failure as the typo this removes, arrived at from the other side.
// Zapier asks for page 0, 1, 2 ... and stops when a page comes back short.
const V1_PAGE = 100;
app.get("/api/v1/properties", async (c) => {
  const ctx = await apiCaller(c);
  if (ctx.res) return ctx.res;
  const page = Math.max(0, Math.min(999, Number(c.req.query("page")) || 0));
  const { results } = await c.env.DB.prepare(
    `SELECT id, name, address, city, state, zip FROM properties
      WHERE account_id = ?
      ORDER BY lower(TRIM(name)) ASC, id ASC
      LIMIT ? OFFSET ?`
  ).bind(ctx.accountId, V1_PAGE, page * V1_PAGE).all();
  return c.json({
    ok: true,
    page,
    properties: (results || []).map((r) => ({
      id: r.id, name: r.name, address: r.address, city: r.city,
      state: r.state, zip: r.zip,
      // Assembled here rather than in the Zapier app, because the app is not
      // the only caller and two of them would label the same building two
      // ways. Address included: two buildings called "Building A" are told
      // apart by where they are, and a picker that cannot distinguish them is
      // a picker somebody guesses in.
      label: [r.name, [r.address, r.city].filter(Boolean).join(", ")]
        .filter(Boolean).join(" -- "),
    })),
  });
});

// ---- The tokens themselves, from inside the account ----------------------
// Admin only. A project manager runs work; wiring the company's CRM to it is
// an account-level decision, and a token is a key to create jobs on it.
app.get("/api/api-tokens", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT id, name, prefix, created_at, last_used_at, revoked_at
         FROM api_tokens WHERE account_id = ? ORDER BY created_at DESC`
    ).bind(accountId).all();
    return c.json((results || []).map((r) => ({
      id: r.id, name: r.name, prefix: r.prefix, createdAt: r.created_at,
      lastUsedAt: r.last_used_at, revokedAt: r.revoked_at,
    })));
  } catch (err) {
    if (missingSchema(err)) return c.json([]);
    throw err;
  }
});

app.post("/api/api-tokens", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const acct = await c.env.DB.prepare(
    `SELECT plan, comped, kind FROM accounts WHERE id = ?`).bind(accountId).first();
  // The same gate the API itself applies, here so the screen and the route
  // cannot disagree about who may have one.
  if (!accountOnScale(acct)) return c.json({ error: "scale_required" }, 403);
  if (!HIRING_KINDS.includes(acct?.kind)) return c.json({ error: "not_a_hiring_account" }, 403);

  const b = await c.req.json().catch(() => ({}));
  const name = String(b?.name || "").trim().slice(0, 60);
  if (!name) return c.json({ error: "name_required" }, 400);

  const raw = mintApiToken();
  const id = uid();
  try {
    await c.env.DB.prepare(
      `INSERT INTO api_tokens (id, account_id, name, prefix, token_hash, created_by)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(id, accountId, name, raw.slice(0, API_TOKEN_SHOWN), await hashApiToken(raw), userId).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }

  await logEvent(c.env, accountId, userId, "api_token.created", id, { name });
  await logActivity(c.env, accountId, userId, "api_token_created", `Created an API token: ${name}`);
  // The only time the token is ever returned. There is no route that reads
  // one back, because there is nothing stored that could answer.
  return c.json({ id, name, prefix: raw.slice(0, API_TOKEN_SHOWN), token: raw }, 201);
});

app.delete("/api/api-tokens/:id", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  // Scoped to the account, so a token id from somewhere else is not found
  // rather than forbidden.
  const row = await c.env.DB.prepare(
    `SELECT id, name FROM api_tokens WHERE id = ? AND account_id = ?`
  ).bind(id, accountId).first().catch(() => null);
  if (!row) return c.json({ error: "not_found" }, 404);

  // Revoked, not deleted. The jobs it created are real work somebody may
  // already be booked for, and "where did these come from" has to stay
  // answerable after the key is turned off.
  await c.env.DB.prepare(
    `UPDATE api_tokens SET revoked_at = datetime('now') WHERE id = ? AND revoked_at IS NULL`
  ).bind(id).run();
  await logEvent(c.env, accountId, userId, "api_token.revoked", id, { name: row.name });
  await logActivity(c.env, accountId, userId, "api_token_revoked", `Revoked an API token: ${row.name}`);
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// JobNimbus, specifically
// ---------------------------------------------------------------------------
// `/api/v1/jobs` is the endpoint for somebody writing code. JobNimbus is not
// somebody writing code, and three things stop it calling that endpoint:
//
//   1. Its automation Webhook action takes a URL and nothing else. There is
//      no field for a header, so `Authorization: Bearer` cannot be set. The
//      token therefore travels in the PATH -- the same reason, and the same
//      shape, as /api/pack/:token, which is in this file for exactly this
//      constraint. It is a 32-byte random value either way; what changes is
//      that a URL is likelier to be written down, so this route is the one
//      place a token can be rotated without touching anything else.
//   2. It sends its own field names: `jnid`, `date_start`, `address_line1`.
//   3. It has NO CONCEPT OF A TRADE. Nothing in the payload says `roofing`.
//
// The third is the one that needs an account decision rather than a rename,
// and `app/shared/crmmap.js` is where it lives.
//
// A job whose words map to nothing STILL ARRIVES. Refusing it is the worst
// available answer: the webhook does not get a 200, so it retries, so it
// keeps not getting one, and nobody is told -- the work simply is not in
// SubSub and the only way to find out is to notice. So it lands with no
// trades and the unrecognised words are counted in `crm_unmapped`, which is
// a question somebody can answer in one tap.

app.post("/api/v1/hooks/:source/:token", async (c) => {
  // The source is named in the URL and looked up in SOURCE_PRESETS, so a new
  // CRM is an entry in that file with a fixture beside it -- not a route, an
  // auth path and a test suite written from nothing. An unknown one is named
  // rather than 404'd: the integrator pasted a URL and a typo in it should
  // say so, with the list of what is available.
  const source = String(c.req.param("source") || "").toLowerCase();
  if (!isSource(source)) {
    return apiError(c, 404, "unknown_source",
      `SubSub has no receiver for "${source}".`,
      { supported: Object.keys(SOURCE_PRESETS) });
  }
  const preset = SOURCE_PRESETS[source];

  const ctx = await apiCallerByPathToken(c);
  if (ctx.res) return ctx.res;
  const { token, accountId } = ctx;

  let body;
  try { body = await c.req.json(); }
  catch { return apiError(c, 400, "invalid_json", "The request body must be valid JSON."); }

  const record = unwrap(body, preset);
  if (!record) return apiError(c, 400, "invalid_body", "The request body must be a JSON object.");

  const { job: j, missing } = translate(record, preset);
  // Named in THEIR vocabulary, because the person reading this error knows
  // their own field names and has never heard of ours. Trades are
  // deliberately not in here: an unmapped job still arrives.
  if (missing.length) {
    return apiError(c, 400, "invalid_request",
      `This ${preset.label} record is missing ${missing.join(", ")}, which SubSub needs to schedule work.`,
      { errors: missing.map((f) => ({ field: f, code: "required" })) });
  }

  let rules = [];
  try {
    const { results } = await c.env.DB.prepare(
      // A rule is for every CRM unless it names one, so this reads both.
      // Reading only `source = ?` is what made a rule saved from the screen
      // -- which names no CRM -- fire for nobody.
      `SELECT match_kind, match_value, trades FROM crm_trade_rules
        WHERE account_id = ? AND (source = ? OR source = ?)`
    ).bind(accountId, source, ANY_SOURCE).all();
    rules = (results || []).map((r) => ({
      match: r.match_kind, value: r.match_value, trades: parseJson(r.trades, []),
    }));
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return apiError(c, 503, "migration_needed",
      "This SubSub environment has not had migration 049 applied yet.", { migration });
  }

  const mapped = tradesFor(record, rules, { tradeIds: TRADE_IDS });

  // Recorded BEFORE the job is created, so a failed insert cannot leave the
  // queue claiming a gap that produced nothing. Never fails the request: a
  // work queue that can break an integration is worse than one with a hole.
  if (!mapped.trades.length) {
    for (const u of mapped.unmatched) {
      try {
        await c.env.DB.prepare(
          `INSERT INTO crm_unmapped (id, account_id, source, match_kind, match_value, hits, last_seen)
           VALUES (?, ?, ?, ?, ?, 1, datetime('now'))
           ON CONFLICT (account_id, source, match_kind, match_value)
             DO UPDATE SET hits = hits + 1, last_seen = datetime('now')`
        ).bind(uid(), accountId, source, u.kind, u.value.slice(0, 120)).run();
      } catch (err) {
        console.warn("[hooks] unmapped not recorded:", err?.message || err);
      }
    }
  }

  const res = await ingestJob(c, {
    accountId, token, source,
    job: {
      externalId: j.externalId, title: j.title, date: j.date,
      trades: mapped.trades,
      time: "07:00",
      address: j.address, area: j.area, zip: j.zip, client: j.client,
      scope: j.scope, propertyId: null, notes: null,
      materialsPaidBy: null, materialSource: null, sqft: null, stories: null,
    },
  });
  if (res.error) return apiError(c, res.status, res.error, res.message, res.extra || {});

  // The reply says what happened to the trades, because whoever is wiring
  // this up needs to see the mapping fail while they are still looking at it
  // rather than a week later.
  return c.json({
    ok: true, source, duplicate: res.duplicate, jobId: res.jobId,
    trades: mapped.trades,
    needsTrades: mapped.trades.length === 0,
    unmapped: mapped.unmatched.map((u) => `${u.kind}:${u.value}`),
    url: `https://app.subsub.work/?job=${res.jobId}`,
  }, res.duplicate ? 200 : 201);
});

// ---------------------------------------------------------------------------
// Move-in and move-out inspections arriving from somebody else's system
// ---------------------------------------------------------------------------
// A managing agent walks the unit in whatever they already walk units in and
// that system posts the walk here. `app/shared/inspectingest.js` holds the
// field rules and the condition vocabulary, because the route, the published
// page and the tests all describe them.
//
// IT LANDS AS A DRAFT, ALWAYS. Finishing is a one-way door -- it is what makes
// the document quotable, what writes the summary and what lets the report go
// to the building's owner -- so a receiver that finished them would bake an
// unrecognised condition word permanently into a record nobody can edit. The
// account presses Finish, which is one tap and is also what writes the
// summary, so nothing is lost by waiting for it.
//
// A WALK WHOSE CONDITION WORDS MAP TO NOTHING STILL ARRIVES, which is 049's
// argument one object along. Refusing is the worst answer available: the
// sender does not get a 200, so it retries, so it keeps not getting one, and
// nobody is told -- the unit has no record of being walked and the only
// symptom is its absence. So those rooms land `unchecked` and the words are
// counted in `inspection_unmapped`, which is a question somebody answers in
// one tap.

// Which building, from an id or from a name the account's own buildings carry.
//
// An inspection has no address of its own -- `inspections.property_id` is NOT
// NULL -- so unlike a job there is nowhere to put a bare street, and a
// building has to be found. Matching a typed name against THIS ACCOUNT'S OWN
// properties is its own data, which is the line CLAUDE.md already draws about
// local name matching; whole value and case-insensitive, never a prefix.
//
// TWO MATCHES ARE REFUSED RATHER THAN RESOLVED. Picking either one files a
// walk of one flat against a different building, which is a job raised at the
// wrong address and a deposit record attached to the wrong tenancy -- and
// nothing downstream would look wrong. Named, so the integrator can send the
// id instead.
async function ingestProperty(db, accountId, { propertyId, property }) {
  if (propertyId) {
    const row = await db.prepare(
      `SELECT id FROM properties WHERE id = ? AND account_id = ?`
    ).bind(propertyId, accountId).first();
    // not_found for somebody else's building as well as one that does not
    // exist: a 403 would confirm which property ids are real.
    return row ? { id: row.id } : { error: "property_not_found", status: 404,
      message: "No building with that propertyId on this account." };
  }
  const { results } = await db.prepare(
    `SELECT id, name FROM properties
      WHERE account_id = ?
        AND (lower(TRIM(name)) = lower(TRIM(?)) OR lower(TRIM(address)) = lower(TRIM(?)))`
  ).bind(accountId, property, property).all();
  const hits = results || [];
  if (!hits.length) {
    return { error: "property_not_found", status: 404,
      message: `No building on this account is called or addressed "${property}". Send propertyId instead, or add the building first.` };
  }
  if (hits.length > 1) {
    return { error: "property_ambiguous", status: 409,
      message: `${hits.length} buildings on this account match "${property}". Send propertyId so the walk lands on the right one.`,
      extra: { matches: hits.length } };
  }
  return { id: hits[0].id };
}

// Creating the inspection, and the retry protection. ONE implementation: the
// header endpoint and the path-token hook both go through here, because two
// copies of an insert this careful is two places for the duplicate guard to
// rot. Answers a plain object rather than a Response, so each caller shapes
// its own reply.
async function ingestInspection(c, { accountId, token, source, inspection: v, rules }) {
  const prop = await ingestProperty(c.env.DB, accountId, v);
  if (prop.error) return prop;

  // The retry. Asked before the insert AND enforced by the unique index after
  // it: the index is what is correct when two deliveries arrive at once, this
  // is what makes the ordinary retry cheap and hands back the id.
  let seen;
  try {
    seen = await c.env.DB.prepare(
      `SELECT inspection_id FROM inspection_sources
        WHERE account_id = ? AND source = ? AND external_id = ?`
    ).bind(accountId, source, v.externalId).first();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { error: "migration_needed", status: 503,
      message: "This SubSub environment has not had migration 068 applied yet.",
      extra: { migration } };
  }
  if (seen) {
    await touchApiToken(c.env, token);
    // Returned BEFORE anything is counted. A redelivered walk is one walk, and
    // climbing `hits` on retries would report nine rooms saying Poor when it
    // was one room delivered nine times.
    return { inspectionId: seen.inspection_id, duplicate: true, rooms: 0,
      unchecked: 0, unmapped: [] };
  }

  const rooms = v.rooms.map((r, i) => {
    const got = roomStatusFor(r.rawStatus, rules);
    return { ...r, position: i, status: got.status, word: got.word, matched: got.matched };
  });
  // ONE ROW PER DISTINCT WORD, COUNTING ROOMS. Twelve rooms saying "Poor" is
  // one question, so it is one queue row -- but the number on it is twelve,
  // because what the panel says is "on N rooms so far" and that is the measure
  // of how much of the walk is unreadable. Counting deliveries instead would
  // report "1 room" over twelve, which is the wrong scale for deciding whether
  // to answer it.
  const counts = new Map();
  for (const r of rooms) {
    if (r.matched || !r.word) continue;
    const key = r.word.toLowerCase();
    const seen = counts.get(key);
    if (seen) seen.rooms += 1;
    else counts.set(key, { word: r.word, rooms: 1 });
  }
  const unmapped = [...counts.values()];

  // Recorded BEFORE the inspection is written, and never allowed to fail the
  // request. The word DID arrive, which is the fact this queue records -- so a
  // row left behind by a failed insert is still a rule worth having, where a
  // word that arrived and was never counted is a room nobody is told about. A
  // work queue that can break an integration is worse than one with a hole.
  for (const u of unmapped) {
    try {
      await c.env.DB.prepare(
        `INSERT INTO inspection_unmapped (id, account_id, source, match_value, hits, last_seen)
         VALUES (?, ?, ?, ?, ?, datetime('now'))
         ON CONFLICT (account_id, source, match_value)
           DO UPDATE SET hits = hits + excluded.hits, last_seen = datetime('now')`
      ).bind(uid(), accountId, source, u.word, u.rooms).run();
    } catch (err) {
      console.warn("[insp-hooks] unmapped not recorded:", err?.message || err);
    }
  }

  const id = uid();
  try {
    // created_by is deliberately NULL: no person walked this into SubSub.
    // Provenance goes on `inspection_sources`, where it is true -- the same
    // reason an ingested job has none.
    await c.env.DB.prepare(
      `INSERT INTO inspections (id, account_id, property_id, unit, kind, tenant_name, inspected_on, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, NULL)`
    ).bind(id, accountId, prop.id, v.unit, v.kind, v.tenantName, v.inspectedOn).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { error: "migration_needed", status: 503,
      message: "This SubSub database is behind the code.", extra: { migration } };
  }

  for (const r of rooms) {
    await c.env.DB.prepare(
      `INSERT INTO inspection_rooms (id, inspection_id, name, status, note, position)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(uid(), id, r.name, r.status, r.note, r.position).run();
  }

  try {
    await c.env.DB.prepare(
      `INSERT INTO inspection_sources (inspection_id, account_id, source, external_id, token_id)
       VALUES (?, ?, ?, ?, ?)`
    ).bind(id, accountId, source, v.externalId, token.id).run();
  } catch (err) {
    // The unique index fired: a second delivery landed between the check and
    // here. The other one won; report the inspection that exists rather than
    // leaving one nothing points at.
    const other = await c.env.DB.prepare(
      `SELECT inspection_id FROM inspection_sources
        WHERE account_id = ? AND source = ? AND external_id = ?`
    ).bind(accountId, source, v.externalId).first().catch(() => null);
    if (other) {
      await c.env.DB.prepare(`DELETE FROM inspections WHERE id = ?`).bind(id).run().catch(() => {});
      await touchApiToken(c.env, token);
      return { inspectionId: other.inspection_id, duplicate: true, rooms: 0,
        unchecked: 0, unmapped: [] };
    }
    throw err;
  }

  const unchecked = rooms.filter((r) => r.status === "unchecked").length;
  const label = INSPECTION_KINDS[v.kind].label.toLowerCase();
  await logEvent(c.env, accountId, null, "inspection.created", id,
    { kind: v.kind, unit: v.unit, via: "api", source, externalId: v.externalId });
  await logActivity(c.env, accountId, null, "inspection_started",
    unchecked
      // Said differently when something did not map, because the thing to do
      // is different: this one cannot be finished until those rooms have an
      // answer, and the queue is where that answer is given.
      ? `A ${label} inspection${v.unit ? ` of unit ${v.unit}` : ""} arrived from your inspection app — ${unchecked} room${unchecked === 1 ? "" : "s"} still need an answer`
      : `A ${label} inspection${v.unit ? ` of unit ${v.unit}` : ""} arrived from your inspection app`);
  await touchApiToken(c.env, token);
  // The reply carries the WORDS, because the reader is an integrator deciding
  // whether their scale is understood; the counts are for the panel.
  return { inspectionId: id, duplicate: false, rooms: rooms.length, unchecked,
    unmapped: unmapped.map((u) => u.word) };
}

// The account's condition dictionary. Read on every arrival rather than
// cached, because answering a queue row has to take effect on the next walk.
async function inspectStatusRules(db, accountId, source) {
  try {
    const { results } = await db.prepare(
      // A rule is for every system unless it names one, so this reads both --
      // 049's lesson taken at the start rather than after a release of rules
      // that fired for nobody.
      `SELECT match_value, status FROM inspection_status_rules
        WHERE account_id = ? AND (source = ? OR source = ?)`
    ).bind(accountId, source, ANY_SOURCE).all();
    return { rules: (results || []).map((r) => ({ value: r.match_value, status: r.status })) };
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return { migration };
  }
}

// Which accounts can take one at all. An inspection is a walk of a UNIT in a
// BUILDING, so this is the account kinds that have buildings -- which is a
// different question from `HIRING_KINDS` above: a general contractor hires
// subcontractors and has no book of buildings to walk, so a walk posted to one
// would have no property to land on. The screen reads the same rule, so the
// panel and the route cannot disagree about who may wire this up.
const inspectKindRefusal = (c, kind) => apiError(c, 403, "no_buildings",
  "This account does not keep buildings, so it has no units to inspect.", { kind });

// The one body-to-reply path, shared by both doors so neither can grow its own
// validation, its own rule lookup or its own reply shape.
//
// `urlSource` is the receiver the hook's own address named, which outranks
// anything in the payload: somebody pasted that URL and it is the one fact
// about this delivery nobody can mistype into a different meaning. Null on the
// header door, where the payload may label its own provenance and `other` is
// what an in-house form gets.
async function inspectIngestCall(c, { ctx, urlSource = null, preset }) {
  const { token, accountId } = ctx;
  if (!ACCOUNT_KINDS_WITH_PROPERTIES.includes(token.kind)) {
    return inspectKindRefusal(c, token.kind);
  }

  let body;
  try { body = await c.req.json(); }
  catch { return apiError(c, 400, "invalid_json", "The request body must be valid JSON."); }

  const check = readInspection(body, { preset });
  if (!check.ok) {
    return apiError(c, 400, "invalid_request",
      `Some fields were missing or not understood on this ${preset.label}. See \`errors\` for which.`,
      { errors: check.errors });
  }
  const source = urlSource || check.inspection.source || "other";

  const got = await inspectStatusRules(c.env.DB, accountId, source);
  if (got.migration) {
    return apiError(c, 503, "migration_needed",
      "This SubSub environment has not had migration 068 applied yet.", { migration: got.migration });
  }

  const res = await ingestInspection(c, {
    accountId, token, source, inspection: check.inspection, rules: got.rules,
  });
  if (res.error) return apiError(c, res.status, res.error, res.message, res.extra || {});

  return c.json({
    ok: true, source, duplicate: res.duplicate,
    inspectionId: res.inspectionId,
    // Said while whoever is wiring this up is still looking at the screen,
    // which is the whole reason the reply carries it rather than leaving them
    // to find out a week later from a walk they cannot finish.
    status: "draft",
    rooms: res.rooms,
    needsAnswers: res.unchecked,
    unmapped: res.unmapped,
    url: `https://app.subsub.work/?inspection=${res.inspectionId}`,
  }, res.duplicate ? 200 : 201);
}

// The header door, for somebody writing code.
app.post("/api/v1/inspections", async (c) => {
  const ctx = await apiCaller(c);
  if (ctx.res) return ctx.res;
  // No source in the URL: the payload may label its own provenance, which
  // `readInspection` validates against INSPECT_SOURCES, and an in-house form
  // that names nothing is `other`. The preset is ours either way, because this
  // door reads SubSub's own field names.
  return inspectIngestCall(c, { ctx, preset: INSPECT_PRESETS.generic });
});

// The path-token door, for an inspection app whose webhook step takes a URL
// and nothing else -- no field for a header, so a token that can only arrive
// in one cannot arrive at all. Same shape and same reasoning as
// /api/pack/:token and the jobs hook above; the object is the last segment so
// the two addresses cannot be mistaken for each other.
app.post("/api/v1/hooks/:source/:token/inspections", async (c) => {
  const source = String(c.req.param("source") || "").toLowerCase();
  if (!isInspectSource(source)) {
    // Named rather than 404'd blankly: the integrator pasted a URL and a typo
    // in it should say so, with the list of what is available.
    return apiError(c, 404, "unknown_source",
      `SubSub has no inspection receiver for "${source}".`,
      { supported: Object.keys(INSPECT_PRESETS) });
  }
  const ctx = await apiCallerByPathToken(c);
  if (ctx.res) return ctx.res;
  return inspectIngestCall(c, { ctx, urlSource: source, preset: INSPECT_PRESETS[source] });
});

// ---- The condition dictionary, from inside the account -------------------
//
// ADMIN ONLY, for the reason the trade rules are: a condition rule is the
// dictionary the receiver reads to decide what every arriving walk SAYS about
// a unit, from then on, and that is the same account-level decision as the
// token that posts it. The panel beside it has been admin-only since it
// shipped, and two halves of one integration behind two different gates is how
// a project manager ends up holding half of it.
//
// AND THE KIND GATE IS THE ROUTE'S, not only the screen's. An account with no
// buildings can never receive an inspection, so a rule on one is a setting
// about nothing -- and a screen stricter than its route is the same lie as
// looser, which this file has paid for in both directions.
const inspectRulesGate = async (c) => {
  const { accountId } = c.get("auth");
  const acct = await c.env.DB.prepare(`SELECT kind FROM accounts WHERE id = ?`)
    .bind(accountId).first().catch(() => null);
  return ACCOUNT_KINDS_WITH_PROPERTIES.includes(acct?.kind || "")
    ? null : c.json({ error: "no_buildings" }, 403);
};

app.get("/api/inspection-rules", requireRole("admin"), async (c) => {
  const gate = await inspectRulesGate(c);
  if (gate) return gate;
  const { accountId } = c.get("auth");
  try {
    const rules = await c.env.DB.prepare(
      `SELECT id, source, match_value, status FROM inspection_status_rules
        WHERE account_id = ? ORDER BY lower(match_value)`
    ).bind(accountId).all();
    const gaps = await c.env.DB.prepare(
      `SELECT id, source, match_value, hits, last_seen FROM inspection_unmapped
        WHERE account_id = ? ORDER BY hits DESC, last_seen DESC LIMIT 50`
    ).bind(accountId).all();
    return c.json({
      rules: (rules.results || []).map((r) => ({
        id: r.id, source: r.source, value: r.match_value, status: r.status,
      })),
      // What arrived meaning nothing, commonest first -- the work queue.
      unmapped: (gaps.results || []).map((r) => ({
        id: r.id, source: r.source, value: r.match_value,
        hits: r.hits, lastSeen: r.last_seen,
      })),
    });
  } catch (err) {
    // A database without 068 has no rules and no queue, which is an empty
    // panel rather than a screen that fails to load.
    if (missingSchema(err)) return c.json({ rules: [], unmapped: [] });
    throw err;
  }
});

app.post("/api/inspection-rules", requireRole("admin"), async (c) => {
  const gate = await inspectRulesGate(c);
  if (gate) return gate;
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const rule = validStatusRule(b);
  if (!rule) return c.json({ error: "invalid_rule" }, 400);
  // Validated against INSPECT_PRESETS, not the provenance list: a rule is only
  // ever read by a RECEIVER, so the sources a rule can name is exactly the set
  // of receivers. REFUSED rather than defaulted -- a rule filed against a
  // source the account does not use fires for nobody, and does not even clear
  // the queue row, because the DELETE below is scoped the same way.
  const asked = String(b?.source || "").toLowerCase();
  if (asked && asked !== ANY_SOURCE && !isInspectSource(asked)) {
    return c.json({ error: "unknown_source", supported: Object.keys(INSPECT_PRESETS) }, 400);
  }
  const source = asked || ANY_SOURCE;

  try {
    await c.env.DB.prepare(
      `INSERT INTO inspection_status_rules (id, account_id, source, match_value, status, created_by)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT (account_id, source, match_value)
         DO UPDATE SET status = excluded.status`
    ).bind(uid(), accountId, source, rule.value, rule.status, userId).run();
    // Answering the question clears it from the queue. Leaving it would make
    // the list read as work still to do, which is how a queue stops meaning
    // anything -- and a row that survives being answered is a button somebody
    // presses again, and again.
    await (source === ANY_SOURCE
      ? c.env.DB.prepare(
        `DELETE FROM inspection_unmapped
          WHERE account_id = ? AND lower(match_value) = lower(?)`
      ).bind(accountId, rule.value)
      : c.env.DB.prepare(
        `DELETE FROM inspection_unmapped
          WHERE account_id = ? AND source = ? AND lower(match_value) = lower(?)`
      ).bind(accountId, source, rule.value)).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }

  await logEvent(c.env, accountId, userId, "inspection_rule.saved", null,
    { source, value: rule.value, status: rule.status });
  return c.json({ ok: true });
});

app.delete("/api/inspection-rules/:id", requireRole("admin"), async (c) => {
  const gate = await inspectRulesGate(c);
  if (gate) return gate;
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const row = await c.env.DB.prepare(
    `SELECT id FROM inspection_status_rules WHERE id = ? AND account_id = ?`
  ).bind(id, accountId).first().catch(() => null);
  if (!row) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`DELETE FROM inspection_status_rules WHERE id = ?`).bind(id).run();
  await logEvent(c.env, accountId, userId, "inspection_rule.removed", id, {});
  return c.json({ ok: true });
});

// ---- The rules, from inside the account ----------------------------------
//
// ADMIN ONLY, ON ALL THREE, and that is a narrowing rather than the original
// reading. These started as `requireRole("admin", "pm")` on the argument that
// answering "Roof Replacement means roofing" is trade knowledge, which a
// project manager has more of than an admin. What that missed is what a rule
// IS: the dictionary the receiver reads to decide what arrives on the account,
// applied to every job from every CRM from then on, for everybody. It is the
// other half of the token panel beside it -- and that has been admin-only
// since it shipped, because a token is a key to create jobs on the account.
// Two halves of one integration behind two different gates is how a project
// manager ends up holding half of an account-level decision.
//
// So both halves are admin, the screen follows in the same change, and the
// queue a pm can no longer answer is still work an admin can: the jobs it is
// about are on the Jobs screen either way, which is the sentence that panel
// leads with.
app.get("/api/crm-rules", requireRole("admin"), async (c) => {
  const { accountId } = c.get("auth");
  try {
    const rules = await c.env.DB.prepare(
      `SELECT id, source, match_kind, match_value, trades FROM crm_trade_rules
        WHERE account_id = ? ORDER BY match_kind, match_value`
    ).bind(accountId).all();
    const gaps = await c.env.DB.prepare(
      `SELECT id, source, match_kind, match_value, hits, last_seen FROM crm_unmapped
        WHERE account_id = ? ORDER BY hits DESC, last_seen DESC LIMIT 50`
    ).bind(accountId).all();
    return c.json({
      rules: (rules.results || []).map((r) => ({
        id: r.id, source: r.source, match: r.match_kind, value: r.match_value,
        trades: parseJson(r.trades, []),
      })),
      // What arrived meaning nothing, commonest first -- the work queue.
      unmapped: (gaps.results || []).map((r) => ({
        id: r.id, source: r.source, match: r.match_kind, value: r.match_value,
        hits: r.hits, lastSeen: r.last_seen,
      })),
    });
  } catch (err) {
    if (missingSchema(err)) return c.json({ rules: [], unmapped: [] });
    throw err;
  }
});

app.post("/api/crm-rules", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const rule = validRule(b, { tradeIds: TRADE_IDS });
  if (!rule) return c.json({ error: "invalid_rule" }, 400);
  // Validated against SOURCE_PRESETS, not the provenance list in ingest.js.
  // A rule is only ever read by a RECEIVER, so the set of sources a rule can
  // name is exactly the set of receivers.
  //
  // REFUSED rather than defaulted. Falling back to jobnimbus for an
  // unrecognised name stores a rule somebody believes is for AccuLynx
  // against JobNimbus, where it does not fire for them and DOES fire on
  // somebody else's words -- the worst of both. Silence is only safe when
  // nothing was asked; here something was, and it was not understood.
  const asked = String(b?.source || "").toLowerCase();
  if (asked && asked !== ANY_SOURCE && !isSource(asked)) {
    return c.json({ error: "unknown_source", supported: Object.keys(SOURCE_PRESETS) }, 400);
  }
  // Every CRM unless one was named. The old default was `jobnimbus`, and
  // since the screen names no source that made every rule an account saved a
  // JobNimbus rule -- firing for nobody who posts through anything else, and
  // not even clearing the queue row, because the DELETE below is scoped the
  // same way. A default that has to be discovered to be corrected is not a
  // default, it is a trap, and this one could not be discovered at all.
  const source = asked || ANY_SOURCE;

  try {
    await c.env.DB.prepare(
      `INSERT INTO crm_trade_rules (id, account_id, source, match_kind, match_value, trades, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT (account_id, source, match_kind, match_value)
         DO UPDATE SET trades = excluded.trades`
    ).bind(uid(), accountId, source, rule.match, rule.value,
      JSON.stringify(rule.trades), userId).run();
    // Answering the question clears it from the queue. Leaving it would make
    // the list read as work still to do, which is how a queue stops meaning
    // anything.
    //
    // An any-CRM rule answers the word wherever it arrived from, so it clears
    // every source's copy of it; a narrowed rule clears only its own. Getting
    // this wrong is not cosmetic: a row that survives being answered is a
    // button somebody presses again, and again.
    await (source === ANY_SOURCE
      ? c.env.DB.prepare(
        `DELETE FROM crm_unmapped
          WHERE account_id = ? AND match_kind = ? AND lower(match_value) = lower(?)`
      ).bind(accountId, rule.match, rule.value)
      : c.env.DB.prepare(
        `DELETE FROM crm_unmapped
          WHERE account_id = ? AND source = ? AND match_kind = ? AND lower(match_value) = lower(?)`
      ).bind(accountId, source, rule.match, rule.value)).run();
  } catch (err) {
    const migration = missingSchema(err);
    if (!migration) throw err;
    return c.json({ error: "migration_needed", migration }, 503);
  }

  await logEvent(c.env, accountId, userId, "crm_rule.saved", null,
    { source, match: rule.match, value: rule.value, trades: rule.trades });
  return c.json({ ok: true });
});

app.delete("/api/crm-rules/:id", requireRole("admin"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const id = c.req.param("id");
  const row = await c.env.DB.prepare(
    `SELECT id FROM crm_trade_rules WHERE id = ? AND account_id = ?`
  ).bind(id, accountId).first().catch(() => null);
  if (!row) return c.json({ error: "not_found" }, 404);
  await c.env.DB.prepare(`DELETE FROM crm_trade_rules WHERE id = ?`).bind(id).run();
  await logEvent(c.env, accountId, userId, "crm_rule.removed", id, {});
  return c.json({ ok: true });
});


// ---------------------------------------------------------------------------
// Staff are deliberately not a role in the app's own role table: they get a
// separate surface on a separate hostname, checked here on every route.
//
// This gate is the whole reason the console can be deployed at all. It refuses
// outright unless real auth is configured, so a console built without Supabase
// cannot be signed into by anyone, and it re-reads the superadmins table on
// every request rather than trusting anything the browser sends.
//
// Still missing before admin.subsub.work should exist: SSO or hardware keys in
// front of this, since it is the one login that can reach every account.
// The access token has already been proven valid by Supabase before this is
// called, so reading its claims without re-verifying the signature is safe.
function decodeJwtClaims(authHeader) {
  try {
    const token = String(authHeader || "").replace(/^Bearer /, "");
    const part = token.split(".")[1];
    if (!part) return null;
    const b64 = part.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(part.length / 4) * 4, "=");
    return JSON.parse(atob(b64));
  } catch { return null; }
}

// Did THIS session authenticate through the identity provider, or is it just an
// account that happens to have a Google identity linked?
//
// The distinction matters for offboarding. If a password on the Supabase user
// is also accepted, suspending someone in Google Workspace does not actually
// revoke their access to the console. `amr` is session-scoped and is the right
// answer; `app_metadata.providers` is account-scoped and only a fallback for
// tokens issued without it.
function sessionUsedFederatedLogin(claims, supaUser) {
  const amr = Array.isArray(claims?.amr) ? claims.amr : [];
  if (amr.length) {
    return amr.some((entry) => {
      const m = String(entry?.method || "").toLowerCase();
      if (m.includes("google") || m.startsWith("sso/") || m === "sso") return true;
      // A bare "oauth" only counts if Google is the linked provider, so another
      // enabled provider cannot stand in for the Workspace login.
      return m === "oauth" && linkedProviders(supaUser).includes("google");
    });
  }
  return linkedProviders(supaUser).includes("google");
}

function linkedProviders(supaUser) {
  const meta = supaUser?.app_metadata || {};
  return Array.isArray(meta.providers) ? meta.providers
    : [meta.provider].filter(Boolean);
}

// Who is asking, for the platform console. Two ways in, and the first is the
// one that should be used:
//
//   1. Cloudflare Access. It sits in front of the console's hostname and
//      will not pass a request through until Google Workspace has vouched
//      for the person, then signs a JWT saying who they are. Nothing
//      unauthenticated reaches this Worker, and the console needs no login
//      screen of its own.
//
//   2. A Supabase session. The original route, kept for a console reached at
//      a hostname Access does not cover -- local development, mainly. It
//      demands a federated login unless STAFF_ALLOW_PASSWORD is set.
//
// Either way, identity is not membership: the superadmins table decides, and
// a customer's perfectly valid login gets nothing here.
async function staffIdentity(c) {
  const accessClaims = await verifyAccessJwt(c.env, c.req.header("Cf-Access-Jwt-Assertion"));
  if (accessClaims) return { email: accessClaims.email, authId: null, via: "access" };

  if (!c.env.SUPABASE_URL || !c.env.SUPABASE_ANON_KEY) return { error: "auth_not_configured" };
  const authHeader = c.req.header("Authorization");
  const supaUser = await verifySupabaseToken(c.env, authHeader);
  if (!supaUser) return { error: "unauthorized" };

  // A password on a staff address is refused, so disabling someone in
  // Workspace actually locks them out. STAFF_ALLOW_PASSWORD is break-glass
  // and should not be set in normal operation — see app/README.md.
  const breakGlass = String(c.env.STAFF_ALLOW_PASSWORD || "") === "1";
  if (!breakGlass && !sessionUsedFederatedLogin(decodeJwtClaims(authHeader), supaUser)) {
    return { error: "sso_required" };
  }
  return { email: supaUser.email || "", authId: supaUser.id, via: "supabase" };
}

async function requireStaff(c) {
  const who = await staffIdentity(c);
  if (who.error) {
    const status = who.error === "auth_not_configured" ? 501
      : who.error === "unauthorized" ? 401 : 403;
    return { error: c.json({ error: who.error }, status) };
  }

  // Anyone with any Google account can complete a Google sign-in, and an
  // Access policy can be widened by mistake, so the staff domain is checked
  // here too — the one place it cannot be skipped.
  const domain = String(c.env.STAFF_EMAIL_DOMAIN || "").trim().toLowerCase();
  const email = String(who.email || "").toLowerCase();
  if (domain && !email.endsWith("@" + domain)) {
    return { error: c.json({ error: "wrong_domain" }, 403) };
  }

  const row = await c.env.DB.prepare(
    `SELECT u.id, u.name, u.email, s.role, s.finance, s.impersonate
       FROM users u JOIN superadmins s ON s.user_id = u.id
      WHERE (? IS NOT NULL AND u.auth_id = ?) OR lower(u.email) = lower(?)`
  ).bind(who.authId, who.authId, email).first();
  // Being signed in is not being staff. Someone with a customer login, or a
  // Workspace account nobody has granted anything to, must get nothing here.
  if (!row) return { error: c.json({ error: "forbidden" }, 403) };

  return { staff: {
    userId: row.id, name: row.name, email: row.email, role: row.role,
    finance: !!row.finance && row.role === "superadmin",
    impersonate: !!row.impersonate && row.role === "superadmin",
    via: who.via,
  } };
}

// Who am I, and what may I see? The console calls this before rendering.
app.get("/api/platform/me", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  return c.json(staff);
});

// Financial figures are superadmin-only, and the check is here rather than in
// the interface: a standard user calling this directly gets 403, not numbers.
// What each licence verifier actually answers, in its own words.
//
// Both provider clients were written without ever having seen a real
// response -- neither vendor was reachable from where this was built -- so
// their field mappings are guesses until somebody looks. This is how
// somebody looks, from a browser, without a terminal: it asks every
// configured provider the same question and returns the HTTP status and the
// first couple of kilobytes of each answer, plus whether readVerify()
// recognised it.
//
// Staff only, and it sends a licence number somebody chose to a vendor
// somebody chose. It is a diagnostic, not a feature, and it is the shortest
// path from "we think this works" to "we watched it work".
app.get("/api/platform/license-probe", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;

  const state = String(c.req.query("state") || "").trim().toUpperCase();
  const license = String(c.req.query("license") || "").trim();
  if (!/^[A-Z]{2}$/.test(state) || !license) return c.json({ error: "state_and_license_required" }, 400);

  const providers = configuredProviders(c.env);
  const out = [];
  for (const p of providers) {
    const { url, headers } = p.request(p.base, p.key, { state, license });
    const started = Date.now();
    let status = 0, body = "", failed = null;
    try {
      const res = await fetch(url, { headers: { accept: "application/json", ...headers } });
      status = res.status;
      body = (await res.text()).slice(0, 2000);
    } catch (err) {
      failed = String(err?.message || err).slice(0, 200);
    }
    const parsed = await askProvider(p, { state, license });
    out.push({
      id: p.id, label: p.label,
      // The key never leaves the Worker. The path is what somebody needs to
      // see when the answer is a 404 from a guessed endpoint.
      url: url.replace(/(key|token|api[-_]?key)=[^&]*/gi, "$1=***"),
      requestShapeIsAGuess: !!p.unverifiedRequest,
      httpStatus: status, unreachable: failed,
      recognised: parsed.ok === true,
      whyNot: parsed.ok ? null : parsed.error,
      readAs: parsed.ok ? { found: parsed.found, status: parsed.status,
        expirationDate: parsed.expirationDate || null, businessName: parsed.businessName || null } : null,
      raw: body,
      ms: Date.now() - started,
    });
  }
  return c.json({
    state, license, by: staff?.email || null,
    configured: providers.map((p) => p.id),
    // Named so an empty result reads as "no key set" rather than "no
    // providers exist", which are very different problems.
    notConfigured: PROVIDERS.filter((p) => !providers.some((q) => q.id === p.id)).map((p) => p.id),
    providers: out,
  });
});

app.get("/api/platform/revenue", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  if (!staff.finance) return c.json({ error: "forbidden" }, 403);

  const [subEvents, invoices, accounts] = await Promise.all([
    c.env.DB.prepare(`SELECT * FROM subscription_events ORDER BY at`).all(),
    c.env.DB.prepare(`SELECT * FROM invoices ORDER BY period_start DESC LIMIT 200`).all(),
    c.env.DB.prepare(`SELECT id, name, plan, billing FROM accounts`).all(),
  ]);
  // Normalized: an annual plan counts as its monthly twelfth, or the number
  // means nothing once the mix moves.
  const mrrCents = accounts.results.reduce((n, a) =>
    n + (a.plan === "scale" ? (a.billing === "annual" ? Math.round(99000 / 12) : 9900) : 0), 0);
  return c.json({
    mrrCents, arrCents: mrrCents * 12,
    subscriptionEvents: subEvents.results,
    invoices: invoices.results,
  });
});

app.get("/api/platform/health", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  if (!staff.finance) return c.json({ error: "forbidden" }, 403);
  const row = await c.env.DB.prepare(
    `SELECT
       (SELECT COUNT(*) FROM accounts)   AS accounts,
       (SELECT COUNT(*) FROM users)      AS users,
       (SELECT COUNT(*) FROM companies)  AS companies,
       (SELECT COUNT(*) FROM jobs WHERE status = 'active')   AS active_jobs,
       (SELECT COUNT(*) FROM work_orders WHERE status = 'pending') AS pending_wos,
       (SELECT COUNT(*) FROM change_orders WHERE status = 'pending') AS pending_cos`
  ).first();
  return c.json(row);
});

// The account list. A standard user may see it, without the money columns.
app.get("/api/platform/accounts", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const { results } = await c.env.DB.prepare(
    `SELECT a.id, a.name, a.subdomain, a.kind, a.plan, a.billing, a.created_at,
            (SELECT COUNT(*) FROM memberships m WHERE m.account_id = a.id AND m.role <> 'contractor') AS users,
            (SELECT COUNT(*) FROM engagements e WHERE e.account_id = a.id) AS subs,
            (SELECT COUNT(*) FROM jobs j WHERE j.account_id = a.id) AS jobs
       FROM accounts a ORDER BY a.created_at DESC`
  ).all();
  const rows = results.map((a) => {
    const base = { id: a.id, name: a.name, subdomain: a.subdomain, kind: a.kind,
      plan: a.plan, billing: a.billing, createdAt: a.created_at,
      users: a.users, subs: a.subs, jobs: a.jobs };
    if (!staff.finance) return base;   // omitted, not hidden in the interface
    return { ...base, mrrCents: a.plan === "scale"
      ? (a.billing === "annual" ? Math.round(99000 / 12) : 9900) : 0 };
  });
  return c.json(rows);
});

// The global company registry — the one place a lapsed license is visible
// across every account engaging that company.
app.get("/api/platform/companies", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  const { results } = await c.env.DB.prepare(
    `SELECT co.id, co.company, co.license, co.state, co.city,
            (SELECT COUNT(*) FROM engagements e WHERE e.company_id = co.id) AS accounts,
            (SELECT lc.status FROM license_checks lc WHERE lc.company_id = co.id
              ORDER BY lc.checked_at DESC LIMIT 1) AS license_status,
            -- Since 031 every account has a company row of its own. They
            -- belong in this list -- they can be hired like any other -- but
            -- staff reading it need to know which ones are customers rather
            -- than contractors somebody typed in.
            (SELECT a.name FROM accounts a WHERE a.company_id = co.id) AS account_name
       FROM companies co ORDER BY co.company`
  ).all();
  return c.json((results || []).map((r) => ({ ...r, accountName: r.account_name || null })));
});

// One account's activity stream. This is the first place support looks when a
// customer says somebody changed something.
app.get("/api/platform/activity/:accountId", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  const { results } = await c.env.DB.prepare(
    `SELECT a.*, u.name AS user_name FROM activity a
       LEFT JOIN users u ON u.id = a.user_id
      WHERE a.account_id = ? ORDER BY a.at DESC LIMIT 200`
  ).bind(c.req.param("accountId")).all();
  return c.json(results.map((r) => ({
    id: r.id, accountId: r.account_id, at: r.at, userId: r.user_id,
    userName: r.user_name, kind: r.kind, text: r.text, meta: parseJson(r.meta),
  })));
});

// Everything the console renders, in the shapes its screens already derive
// from. One call rather than six, because every screen cross-references the
// others (an account row counts its own users, subs and jobs).
//
// This returns the whole platform. That is fine at this size and will not be:
// once there are thousands of accounts this needs pagination, and the per-
// account rollups belong in platform_daily_stats rather than being recomputed
// in the browser on every load.
app.get("/api/platform/bootstrap", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;

  const [accounts, users, memberships, companies, engagements, jobs, subEvents, activity] =
    await Promise.all([
      c.env.DB.prepare(`SELECT * FROM accounts`).all(),
      // created_at so the dashboard can draw how many people have a login
      // over time -- the Users line. It has been on the table since the start.
      c.env.DB.prepare(`SELECT id, name, email, phone, created_at FROM users`).all(),
      c.env.DB.prepare(`SELECT user_id, account_id, role, company_id FROM memberships`).all(),
      // contact/phone/email so staff answering "who do I call about this
      // company" do not have to sit in somebody's account to find out. This
      // is a staff route behind requireStaff, which is the only reason it may
      // read across accounts at all -- never reach for it to serve a
      // customer screen.
      c.env.DB.prepare(`SELECT id, company, contact, phone, email, license, ubi, city, state, zip, warranty FROM companies`).all(),
      // doc_review was missing, and the console computes "docs pending
      // review" from it -- so that number was structurally zero on every
      // account and every screen that showed it was reporting nothing.
      // engaged_as (058) too, because the console's company card is where
      // staff answer "what is this company to that account" -- and a column
      // named in the row shape and not in the SELECT comes back undefined,
      // which reads as `subcontractor` and quietly disagrees with the roster
      // it is meant to explain. That is the same drop this repository already
      // paid for on /api/subs.
      c.env.DB.prepare(`SELECT id, account_id, company_id, status, categories, rating, rated_jobs,
        doc_review, engaged_as FROM engagements`).all()
        // A database behind the code must not blank the whole console. 058 is
        // the one thing this falls back for, and it falls back to the shape
        // the console had before it, which reads as subcontractor everywhere.
        .catch((err) => { if (!missingSchema(err)) throw err;
          console.warn("[platform] 058_engaged_as not applied - relationships read as subcontractor");
          return c.env.DB.prepare(`SELECT id, account_id, company_id, status, categories, rating,
            rated_jobs, doc_review FROM engagements`).all(); }),
      c.env.DB.prepare(`SELECT id, account_id, title, status, date, completed_at, created_at FROM jobs`).all(),
      c.env.DB.prepare(`SELECT * FROM subscription_events ORDER BY at`).all(),
      c.env.DB.prepare(
        `SELECT a.*, u.name AS user_name FROM activity a
           LEFT JOIN users u ON u.id = a.user_id
          ORDER BY a.at DESC LIMIT 500`).all(),
    ]);

  // SMS, rolled up by day rather than row by row. The console only ever
  // reports totals over a window, and a year of individual messages is a
  // payload nobody reads. The table may not exist on a database that has not
  // run migration 011, which must not take the whole console down.
  let smsDaily = [];
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT substr(at, 1, 10) AS day, COUNT(*) AS sent, SUM(segments) AS segments,
              SUM(cost_cents) AS cost, SUM(billed_cents) AS billed
         FROM sms_log WHERE status = 'sent' GROUP BY day ORDER BY day`
    ).all();
    smsDaily = results;
  } catch (err) {
    console.warn("[platform] sms_log unavailable:", err?.message || err);
  }

  // The last work order per job is what the console's "expired response"
  // count walks, so hand back enough of it to compute that.
  const { results: wos } = await c.env.DB.prepare(
    `SELECT id, job_id, trade, company_id, status, respond_by, value_cents FROM work_orders WHERE voided_at IS NULL`
  ).all();
  const byJob = {};
  wos.forEach((w) => {
    (byJob[w.job_id] ||= {})[w.trade] = {
      subId: w.company_id, status: w.status, respondBy: w.respond_by, value: w.value_cents,
    };
  });

  return c.json({
    // Financial figures are omitted for a standard user here too, not just on
    // the dedicated revenue route — otherwise the omission is cosmetic.
    accounts: accounts.results.map((a) => ({
      id: a.id, name: a.name, subdomain: a.subdomain, kind: a.kind,
      plan: a.plan, billing: a.billing, comped: !!a.comped, compNote: a.comp_note,
      // What this account hires out. The console ranks these into "top trades",
      // which is the only demand signal that exists before anyone engages a sub.
      trades: parseJson(a.trades, []),
      hostnameStatus: a.hostname_status, hostnameError: a.hostname_error,
      hostnameCheckedAt: a.hostname_checked_at,
      subscriptionStatus: a.subscription_status, currentPeriodEnd: a.current_period_end,
      createdAt: (a.created_at || "").slice(0, 10),
      status: "active",
    })),
    users: users.results.map(({ created_at, ...u }) => ({ ...u, createdAt: (created_at || "").slice(0, 10) })),
    memberships: memberships.results.map((m) => ({
      userId: m.user_id, accountId: m.account_id, role: m.role, companyId: m.company_id,
    })),
    companies: companies.results,
    engagements: engagements.results.map((e) => ({
      id: e.id, accountId: e.account_id, companyId: e.company_id, status: e.status,
      categories: parseJson(e.categories, []), rating: e.rating, ratedJobs: e.rated_jobs,
      docReview: parseJson(e.doc_review, {}),
      // What this company is to THAT account. Named here or it is silently
      // dropped -- the same whitelist shape that returned `subcontractor` for
      // a handyman on /api/subs, which is a console that quietly disagrees
      // with the roster it is meant to answer questions about.
      engagedAs: engagedAs(e.engaged_as),
    })),
    jobs: jobs.results.map((j) => ({
      id: j.id, accountId: j.account_id, title: j.title, status: j.status,
      date: j.date, completedAt: j.completed_at,
      createdAt: (j.created_at || "").slice(0, 10),
      assignments: byJob[j.id] || {},
    })),
    subEvents: staff.finance ? subEvents.results.map((e) => ({
      id: e.id, accountId: e.account_id, at: e.at, kind: e.kind,
      fromPlan: e.from_plan, toPlan: e.to_plan, cycle: e.cycle, mrrDelta: e.mrr_delta_cents,
    })) : [],
    activity: activity.results.map((r) => ({
      id: r.id, accountId: r.account_id, at: r.at, userId: r.user_id,
      userName: r.user_name, kind: r.kind, text: r.text,
    })),
    // Usage is operational, cost and revenue are not: a standard console user
    // sees how much is being sent and not what it earns.
    smsDaily: smsDaily.map((r) => ({
      day: r.day, sent: r.sent || 0, segments: r.segments || 0,
      ...(staff.finance ? { cost: r.cost || 0, billed: r.billed || 0 } : {}),
    })),
  });
});

// Signing in as a customer is audited before the session is handed over, not
// after. The banner in the interface is not the audit trail.
app.post("/api/platform/impersonate/:accountId", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  if (!staff.impersonate) return c.json({ error: "forbidden" }, 403);
  const accountId = c.req.param("accountId");
  const b = await c.req.json().catch(() => ({}));

  const account = await c.env.DB.prepare(`SELECT id, name FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account) return c.json({ error: "not_found" }, 404);

  // Whose seat. This took an admin and nothing else, which meant support
  // could never see what a SUBCONTRACTOR sees -- and a subcontractor's
  // portal is a different app from an admin's: their jobs, their documents,
  // their availability, their QR code. "It looks wrong on my end" was
  // unanswerable for the half of the users who are contractors.
  //
  // Still a seat on THIS account and still checked from the membership
  // table, so naming a user is choosing among people already there rather
  // than a way to reach anybody else.
  const wanted = String(b.userId || "").trim();
  let target = null;
  // Every seat on the account, whichever branch runs. The named branch could
  // read one row, and then `runsAccount` below would have to ask a second
  // question of the same table -- two reads of one fact, which is how the KPI
  // and this route came to disagree about this very account.
  const { results: allSeats } = await c.env.DB.prepare(
    `SELECT user_id, role FROM memberships WHERE account_id = ?`).bind(accountId).all();
  const seats = allSeats || [];
  if (wanted) {
    target = seats.find((r) => String(r.user_id) === wanted) || null;
    if (!target) return c.json({ error: "not_on_this_account" }, 409);
  } else {
    // PREFER AN ADMIN, THEN FALL BACK -- it used to be `role = 'admin'` and
    // nothing else, so an account with no admin could not be opened at all.
    // That is not a rare shape: the account INSERT above only writes an admin
    // when it is given an owner email, and the console's add-user defaults to
    // `pm`. An account made without an address and then given one person is
    // exactly it, and the header said "1 Team users" over "nobody to sign in
    // as" -- the KPI counts every non-contractor membership and this wanted
    // an admin.
    //
    // It gates nothing to widen it: a named `userId` has always been accepted
    // for ANY role on this account, deliberately, so support can see what a
    // subcontractor sees. The default was only deciding what happened when
    // nobody said.
    target = pickSeat(seats);
    // Only now is it true, and the reply says what IS there so the console can
    // put a number on screen rather than a flat denial over a header that
    // disagrees with it.
    if (!target) return c.json({ error: "no_seat_on_account", seats: 0 }, 409);
  }

  // What the session can actually do, which is not always what the seat says.
  const runs = staffStandsIn(target.role, seats);
  // SAID IN THE AUDIT TRAIL, because that is where it matters most. "(pm
  // seat)" over a session that reached billing and branding is a record that
  // understates what was done; the seat and the fact it was run as an admin
  // are two different things and the row carries both.
  const howFar = target.role === "admin" ? ""
    : runs ? ` (${target.role} seat — no admin on the account, so it ran as one)`
    : ` (${target.role} seat)`;

  await c.env.DB.batch([
    c.env.DB.prepare(
      `INSERT INTO activity (id, account_id, at, user_id, kind, text, meta)
       VALUES (?, ?, datetime('now'), NULL, 'impersonation', ?, ?)`
    ).bind(uid(), accountId,
      `${staff.name} signed in as this account${howFar}`,
      JSON.stringify({ staffUserId: staff.userId, reason: b.reason || null,
        actAsUserId: target.user_id, actAsRole: target.role, ranAsAdmin: runs })),
    c.env.DB.prepare(
      `INSERT INTO events (account_id, actor_id, kind, subject_id, payload)
       VALUES (?, ?, 'impersonation_started', ?, ?)`
    ).bind(accountId, staff.userId, accountId,
      JSON.stringify({ reason: b.reason || null, staffEmail: staff.email,
        actAsUserId: target.user_id, actAsRole: target.role, ranAsAdmin: runs })),
  ]);
  // The session itself. Thirty minutes is long enough to look at a problem
  // and short enough that a forgotten tab is not a standing key to somebody
  // else's business.
  const token = [...crypto.getRandomValues(new Uint8Array(32))]
    .map((b) => b.toString(16).padStart(2, "0")).join("");
  const expires = new Date(Date.now() + 30 * 60000).toISOString().replace("T", " ").slice(0, 19);
  await c.env.DB.prepare(
    `INSERT INTO impersonation_sessions (token, account_id, act_as_user_id, staff_user_id, reason, expires_at)
     VALUES (?, ?, ?, ?, ?, ?)`
  ).bind(token, accountId, target.user_id, staff.userId, b.reason || null, expires).run();

  return c.json({
    ok: true, accountId, accountName: account.name,
    actAsUserId: target.user_id, actAsRole: target.role, token, expiresAt: expires,
    // WHICH SEAT IT LANDED IN, and separately WHAT IT CAN DO IN IT. The two
    // were one field and that was the bug underneath the report: the banner
    // said "you are in a pm seat, Account and billing are not reachable",
    // which was true and is no longer -- a team seat on an account with no
    // admin runs it, because nobody inside the account can grant the role
    // that would. See shared/seats.js.
    //
    // `fellBack` is still about how the seat was CHOSEN; `runsAccount` is
    // about what it reaches. Keeping them apart is what lets the banner name
    // the thing the customer has to fix without also claiming half the
    // product is missing.
    fellBack: !wanted && target.role !== "admin",
    accountHasAdmin: hasAdminSeat(seats),
    standingIn: runs,
  });
});

// Handing the seat back. Deliberately needs no session of its own: revoking
// is not a privileged act, and a staff member closing a tab should never be
// the reason a session outlives its use.
app.post("/api/impersonation/end", async (c) => {
  const token = c.req.header("X-Impersonation-Token")
    || (await c.req.json().catch(() => ({})))?.token;
  if (!token) return c.json({ ok: true });

  const sess = await c.env.DB.prepare(
    `SELECT account_id, staff_user_id FROM impersonation_sessions
      WHERE token = ? AND ended_at IS NULL`).bind(token).first();
  await c.env.DB.prepare(
    `UPDATE impersonation_sessions SET ended_at = datetime('now') WHERE token = ?`
  ).bind(token).run();

  if (sess) {
    await c.env.DB.prepare(
      `INSERT INTO activity (id, account_id, at, user_id, kind, text, meta)
       VALUES (?, ?, datetime('now'), NULL, 'impersonation', ?, ?)`
    ).bind(uid(), sess.account_id, "Staff session ended",
      JSON.stringify({ staffUserId: sess.staff_user_id })).run();
  }
  return c.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Platform writes
// ---------------------------------------------------------------------------
// Everything above this point reads. These change or remove other people's
// data, so each one is gated on top of requireStaff and each one is audited:
// a support action nobody can reconstruct afterwards is indistinguishable
// from an intrusion.
//
// The split is deliberate. `standard` staff run support -- fix a typo, add a
// user, send a reset -- while anything that creates, deletes or touches
// money is `superadmin`. Support work should not require the account that
// can delete a customer.
function requireSuperadmin(c, staff) {
  return staff.role === "superadmin" ? null : c.json({ error: "forbidden" }, 403);
}

// One place, so every one of these writes leaves the same trail.
//
// NOT EVERY STAFF ACTION BELONGS TO AN ACCOUNT, and writing as though it did
// is what made three routes throw. `activity` is the PER-ACCOUNT stream --
// its own comment says so, and `account_id` is NOT NULL because a row in it
// is something that happened to one customer. A company is shared across
// every account that engages it and belongs to none of them, so creating,
// editing or deleting one passed `null` into that column and the whole
// batch failed: a 500 on the console's Companies screen, on all three
// writes, for as long as they have existed.
//
// So the per-account row is written only when there IS an account, and
// `events` -- whose `account_id` is nullable precisely because it is the
// platform-wide log -- always gets one. The trail is what matters here: a
// support action nobody can reconstruct afterwards is indistinguishable
// from an intrusion, and that sentence is three lines up.
//
// Widening `activity.account_id` to nullable was the other way out and is
// refused: it would put rows in every account's stream that belong to no
// account, and that stream is read by the customer-facing feed.
async function auditPlatform(env, staff, accountId, kind, text, meta) {
  const payload = JSON.stringify({ ...(meta || {}), staffEmail: staff.email });
  const stmts = [];
  if (accountId) {
    stmts.push(env.DB.prepare(
      `INSERT INTO activity (id, account_id, at, user_id, kind, text, meta)
       VALUES (?, ?, datetime('now'), NULL, ?, ?, ?)`
    ).bind(uid(), accountId, kind, text,
      JSON.stringify({ ...(meta || {}), staffUserId: staff.userId, staffEmail: staff.email })));
  }
  stmts.push(env.DB.prepare(
    `INSERT INTO events (account_id, actor_id, kind, subject_id, payload)
     VALUES (?, ?, ?, ?, ?)`
  ).bind(accountId || null, staff.userId, kind, accountId || null, payload));
  await env.DB.batch(stmts);
}

app.post("/api/platform/accounts", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;

  const b = await c.req.json().catch(() => ({}));
  const name = String(b.name || "").trim();
  const subdomain = validSubdomain(b.subdomain);
  const kind = ACCOUNT_KINDS.includes(b.kind) ? b.kind : "general_contractor";
  const plan = b.plan === "scale" ? "scale" : "basic";
  const billing = b.billing === "annual" ? "annual" : "monthly";
  if (!name) return c.json({ error: "name_required" }, 400);
  if (!subdomain) return c.json({ error: "invalid_subdomain" }, 400);

  const taken = await c.env.DB.prepare(`SELECT id FROM accounts WHERE subdomain = ?`).bind(subdomain).first();
  if (taken) return c.json({ error: "subdomain_taken" }, 409);

  // The console asks for an owner, because an account with nobody on it is a
  // row, not a customer -- there would be no way in and nothing to reset.
  const ownerName = String(b.ownerName || "").trim();
  const ownerEmail = String(b.ownerEmail || "").trim().toLowerCase();
  const ownerPhoneRaw = String(b.ownerPhone || "").trim();
  const ownerPhone = normalizePhone(ownerPhoneRaw);
  if (ownerEmail && !EMAIL_RE.test(ownerEmail)) return c.json({ error: "invalid_email" }, 400);
  if (ownerEmail && !ownerName) return c.json({ error: "name_required" }, 400);
  if (ownerPhoneRaw && !ownerPhone) return c.json({ error: "invalid_phone" }, 400);

  // Same rule the public signup uses: absent means "never chosen", which the
  // app treats differently from "hires nobody" -- it is what decides whether
  // to ask. An empty list from the console therefore stays null.
  const trades = b.trades === undefined ? null : validTrades(b.trades);
  if (trades === null && b.trades !== undefined) return c.json({ error: "invalid_trades" }, 400);

  const id = uid();
  await c.env.DB.prepare(
    `INSERT INTO accounts (id, name, subdomain, kind, plan, billing, trades, use_default_mark)
     VALUES (?, ?, ?, ?, ?, ?, ?, 1)`
  ).bind(id, name, subdomain, kind, plan, billing,
    trades && trades.length ? JSON.stringify(trades) : null).run();

  // The same row signing up creates. Without it a general contractor made
  // from this console cannot be found by the connect lookup at all -- they
  // exist, and nobody can ask to work with them -- and CHECK.sql counts them
  // in m031_hireable_without. ensureAccountCompany would get there eventually, but
  // only once somebody opened a screen that happened to need it.
  await ensureAccountCompany(c.env, id);

  let ownerId = null;
  let ownerInvite = { invited: false, reason: "no_email" };
  if (ownerEmail) {
    // Reuse the person if this address is already known. Somebody running two
    // companies is one person with two memberships, not two rows.
    const existing = await c.env.DB.prepare(
      `SELECT id FROM users WHERE lower(email) = lower(?)`).bind(ownerEmail).first();
    ownerId = existing?.id || uid();
    if (!existing) {
      await c.env.DB.prepare(`INSERT INTO users (id, name, email, phone) VALUES (?, ?, ?, ?)`)
        .bind(ownerId, ownerName, ownerEmail, ownerPhone).run();
    }
    await c.env.DB.prepare(
      `INSERT INTO memberships (id, user_id, account_id, role) VALUES (?, ?, ?, 'admin')`
    ).bind(uid(), ownerId, id).run();

    // And tell them, because this is the front door. An account set up for
    // a customer by SubSub used to arrive as nothing at all: a row, a
    // subdomain, and an admin who had never heard of any of it and had no
    // password to try. Somebody then read them a URL over the phone and
    // talked them through "forgot password" for a login that did not exist.
    const owner = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(ownerId).first();
    ownerInvite = await inviteAccountUser(c, { accountId: id, user: owner, role: "admin",
      invitedBy: { id: null, name: staff?.name || "SubSub" } });
  }

  if (plan === "scale") {
    syncHostnameAfter(c, { id, subdomain, plan }, { reason: "platform_create" });
  }

  await auditPlatform(c.env, staff, id, "account_created",
    `${staff.name} created this account`, { name, subdomain, plan, ownerEmail: ownerEmail || null });

  return c.json({ id, name, subdomain, kind, plan, billing, trades, ownerId,
    ownerInvite }, 201);
});

// Plan and account type, from the console. Deliberately does NOT touch
// Stripe: moving somebody to Scale here grants the features without charging
// for them, which is what "comped" means and is sometimes exactly right --
// but it must be a decision somebody made, and the subscription_events row
// says so in those words.
app.patch("/api/platform/accounts/:id", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;

  const id = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const account = await c.env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(id).first();
  if (!account) return c.json({ error: "not_found" }, 404);

  const sets = [], vals = [];
  if (b.name != null) { sets.push("name = ?"); vals.push(String(b.name).trim()); }
  if (b.kind != null) {
    if (!ACCOUNT_KINDS.includes(b.kind)) return c.json({ error: "invalid_kind" }, 400);
    sets.push("kind = ?"); vals.push(b.kind);
  }
  if (b.plan != null) {
    if (!["basic", "scale"].includes(b.plan)) return c.json({ error: "invalid_plan" }, 400);
    sets.push("plan = ?"); vals.push(b.plan);
  }
  // Comping is the one plan change that is a decision rather than a
  // consequence, so it carries a note: a comp nobody can explain becomes
  // permanent, because nobody can tell whether it still applies.
  if (b.comped !== undefined) {
    const on = !!b.comped;
    const note = String(b.compNote || "").trim().slice(0, 300);
    if (on && !note) return c.json({ error: "reason_required" }, 400);
    sets.push("comped = ?"); vals.push(on ? 1 : 0);
    sets.push("comp_note = ?"); vals.push(on ? note : null);
    // Granting one sets the plan; withdrawing one hands the account back to
    // whatever Stripe thinks, which is Basic unless they are actually paying.
    if (on) { sets.push("plan = ?"); vals.push("scale"); }
    else if (b.plan == null) {
      sets.push("plan = ?");
      vals.push(ENTITLED.has(account.subscription_status || "") ? "scale" : "basic");
    }
  }
  if (b.billing != null) {
    if (!["monthly", "annual"].includes(b.billing)) return c.json({ error: "invalid_billing" }, 400);
    sets.push("billing = ?"); vals.push(b.billing);
  }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);

  vals.push(id);
  await c.env.DB.prepare(`UPDATE accounts SET ${sets.join(", ")} WHERE id = ?`).bind(...vals).run();

  // A comp earns no revenue, so its delta is zero -- counting one as MRR
  // would inflate the number that decides whether this business works.
  const nextPlan = b.comped ? "scale" : b.plan;
  if (nextPlan && nextPlan !== account.plan) {
    const monthly = (b.billing || account.billing) === "annual" ? 8250 : 9900;
    const comping = b.comped !== undefined;
    await c.env.DB.prepare(
      `INSERT INTO subscription_events (id, account_id, at, kind, from_plan, to_plan, cycle, mrr_delta_cents, source)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'platform_admin')`
    ).bind(uid(), id, new Date().toISOString(),
      comping ? "comped" : (nextPlan === "scale" ? "upgraded" : "downgraded"),
      account.plan, nextPlan, b.billing || account.billing,
      comping ? 0 : (nextPlan === "scale" ? monthly : -monthly)).run();
  }

  // Comping an account is an upgrade as far as its address is concerned:
  // somebody was given Scale, and Scale includes their own hostname.
  if (nextPlan && nextPlan !== account.plan) {
    syncHostnameAfter(c, { id, subdomain: account.subdomain, plan: nextPlan }, { reason: "platform_patch" });
  }

  const changed = Object.entries(b).map(([k, v]) => `${k} → ${v}`).join(", ");
  await auditPlatform(c.env, staff, id, "plan_changed", `${staff.name} changed ${changed}`, b);
  return c.json({ ok: true });
});

// An account's own fee terms: what staff see, and what they may set.
//
// Read by any staff member, because answering "what is this customer charged"
// is support's question; set by a superadmin only, because it is pricing.
// Every change is audited with who, the old terms and the new, and a reason,
// for the reason a comp carries one: a rate nobody can explain becomes
// permanent. Setting the defaults back is `reset`, which deletes the row, so
// the account follows the defaults again if they ever change.
app.get("/api/platform/accounts/:id/fee-terms", async (c) => {
  const { error } = await requireStaff(c);
  if (error) return error;
  const id = c.req.param("id");
  const a = await c.env.DB.prepare(`SELECT id FROM accounts WHERE id = ?`).bind(id).first();
  if (!a) return c.json({ error: "not_found" }, 404);
  const t = await accountFeeTerms(c.env, id);
  let processed = 0;
  try { processed = await processedCents(c.env, id); }
  catch (err) { if (!missingSchema(err)) throw err; }
  return c.json({
    terms: { bps: t.bps, capCents: t.capCents, freeCents: t.freeCents },
    defaults: DEFAULT_FEE_TERMS, custom: t.custom,
    note: t.row?.note || null, updatedAt: t.row?.updated_at || null, updatedBy: t.row?.updated_by || null,
    processedCents: processed, freeLeftCents: Math.max(0, t.freeCents - processed),
    ...(t.migration ? { migration: t.migration } : {}),
  });
});

app.put("/api/platform/accounts/:id/fee-terms", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;
  const id = c.req.param("id");
  const a = await c.env.DB.prepare(`SELECT id, name FROM accounts WHERE id = ?`).bind(id).first();
  if (!a) return c.json({ error: "not_found" }, 404);
  const b = await c.req.json().catch(() => ({}));
  const before = await accountFeeTerms(c.env, id);
  if (before.migration) return c.json({ error: "migration_needed", migration: before.migration }, 503);

  if (b.reset) {
    await c.env.DB.prepare(`DELETE FROM account_fee_terms WHERE account_id = ?`).bind(id).run();
    await auditPlatform(c.env, staff, id, "fee_terms_changed",
      `${staff.name} put ${a.name} back on the default fee terms`, { from: before, to: DEFAULT_FEE_TERMS });
    return c.json({ ok: true, terms: DEFAULT_FEE_TERMS, custom: false });
  }
  const next = { bps: Number(b.bps), capCents: Number(b.capCents), freeCents: Number(b.freeCents) };
  const why = feeTermsRefusal(next);
  if (why) return c.json({ error: why }, 400);
  const note = String(b.note || "").trim().slice(0, 300);
  if (!note) return c.json({ error: "reason_required" }, 400);
  await c.env.DB.prepare(
    `INSERT INTO account_fee_terms (account_id, fee_bps, cap_cents, free_cents, note, updated_by, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(account_id) DO UPDATE SET fee_bps = excluded.fee_bps, cap_cents = excluded.cap_cents,
       free_cents = excluded.free_cents, note = excluded.note, updated_by = excluded.updated_by,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(id, next.bps, next.capCents, next.freeCents, note, staff.userId).run();
  await auditPlatform(c.env, staff, id, "fee_terms_changed",
    `${staff.name} set ${a.name}'s fee to ${next.bps / 100}%, cap $${next.capCents / 100}, `
    + `first $${next.freeCents / 100} free -- ${note}`,
    { from: { bps: before.bps, capCents: before.capCents, freeCents: before.freeCents }, to: next, note });
  return c.json({ ok: true, terms: next, custom: true });
});

// Irreversible, so the caller has to name the thing it is deleting. That is
// not ceremony: it is what stops a stale id, a mis-tapped row or a copied
// curl from removing a customer nobody meant to touch.
app.delete("/api/platform/accounts/:id", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;

  const id = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const account = await c.env.DB.prepare(`SELECT id, name, subdomain FROM accounts WHERE id = ?`).bind(id).first();
  if (!account) return c.json({ error: "not_found" }, 404);
  if (!typedNameMatches(b.confirmName, account.name)) {
    return c.json({ error: "confirm_name_mismatch" }, 400);
  }

  // Audited before the row goes, because the audit references it.
  await auditPlatform(c.env, staff, id, "account_deleted",
    `${staff.name} deleted account ${account.name}`, { name: account.name });

  // Before the row goes too: once it is gone there is nothing left to say
  // which hostname belonged to it, and an orphaned CNAME pointing at the app
  // is how a deleted customer's address keeps answering.
  if (account.subdomain && hostnameConfig(c.env)) {
    try { await deprovisionHostname(c.env, account.subdomain); }
    catch (err) { console.error("[hostname] delete:", account.subdomain, err?.message || err); }
  }

  // Rows that point at the account but carry no cascade of their own. The
  // rest (memberships, engagements, jobs, properties, invites) cascade.
  //
  // `activity` IS DELIBERATELY NOT IN THIS LIST, and it used to be. The line
  // read `UPDATE activity SET account_id = NULL`, written to keep the trail
  // after the account went -- and `activity.account_id` is NOT NULL, so that
  // statement could never run. **Deleting an account threw a 500 every
  // time**, which is what the console's "that didn't work" was reporting
  // over a customer who was still there.
  //
  // Letting it cascade is the answer rather than widening the column, for
  // the reason `auditPlatform` now gives: `activity` is the per-account
  // stream, so a row in it with no account is a row in nobody's stream. The
  // trail survives in `events`, whose `account_id` is nullable precisely
  // because it is the platform-wide log -- including the `account_deleted`
  // row written a few lines up, which is the one somebody would come looking
  // for.
  await c.env.DB.batch([
    c.env.DB.prepare(`UPDATE events SET account_id = NULL WHERE account_id = ?`).bind(id),
    c.env.DB.prepare(`DELETE FROM accounts WHERE id = ?`).bind(id),
  ]);
  return c.json({ ok: true });
});

app.post("/api/platform/companies", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;

  const b = await c.req.json().catch(() => ({}));
  const company = String(b.company || "").trim();
  if (!company) return c.json({ error: "company_required" }, 400);
  if (b.email && !EMAIL_RE.test(String(b.email).trim())) return c.json({ error: "invalid_email" }, 400);
  const phone = String(b.phone || "").trim() ? normalizePhone(b.phone) : null;
  if (b.phone && String(b.phone).trim() && !phone) return c.json({ error: "invalid_phone" }, 400);

  const id = uid();
  await c.env.DB.prepare(
    `INSERT INTO companies (id, company, contact, phone, email, license, ubi, city, state, zip)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(id, company, b.contact || null, phone, b.email || null, b.license || null,
    b.ubi || null, b.city || null, b.state || null, b.zip || null).run();
  await auditPlatform(c.env, staff, null, "company_created",
    `${staff.name} created company ${company}`, { companyId: id });

  return c.json({ id, company }, 201);
});

// Support work, so standard staff can do it: a wrong phone number on a
// contractor is the sort of thing that should not need a superadmin.
app.patch("/api/platform/companies/:id", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;

  const id = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const co = await c.env.DB.prepare(`SELECT id, company FROM companies WHERE id = ?`).bind(id).first();
  if (!co) return c.json({ error: "not_found" }, 404);

  const allowed = { company: "company", contact: "contact", email: "email", license: "license",
    ubi: "ubi", city: "city", state: "state", zip: "zip" };
  const sets = [], vals = [];
  for (const [key, column] of Object.entries(allowed)) {
    if (b[key] === undefined) continue;
    if (key === "email" && b.email && !EMAIL_RE.test(String(b.email).trim())) {
      return c.json({ error: "invalid_email" }, 400);
    }
    // TRIMMED, which POST has always done and this had never done. A name
    // stored with a trailing space renders identically everywhere -- HTML
    // collapses it -- and then fails every exact comparison made about it,
    // which is how a company became undeletable. Empty after trimming is
    // null, the same as an empty string was.
    const raw = typeof b[key] === "string" ? b[key].trim() : b[key];
    sets.push(`${column} = ?`); vals.push(raw === "" || raw === undefined ? null : raw);
  }
  if (b.phone !== undefined) {
    const phone = String(b.phone || "").trim() ? normalizePhone(b.phone) : null;
    if (String(b.phone || "").trim() && !phone) return c.json({ error: "invalid_phone" }, 400);
    sets.push("phone = ?"); vals.push(phone);
  }
  if (!sets.length) return c.json({ error: "nothing_to_change" }, 400);

  vals.push(id);
  await c.env.DB.prepare(`UPDATE companies SET ${sets.join(", ")} WHERE id = ?`).bind(...vals).run();
  await auditPlatform(c.env, staff, null, "company_edited",
    `${staff.name} edited ${co.company}`, { companyId: id, fields: Object.keys(b) });
  return c.json({ ok: true });
});

// WHAT A COMPANY IS TO ONE ACCOUNT, changed from the console.
//
// Reported as *"we'd [need] to be able to [edit] as well as change their type
// from contractor or subcontractor to handyman"*. 058 put that word on
// `engagements` and the picker on the roster form, which is the right place --
// but support standing in a console looking at a company card could read the
// relationship nowhere and change it nowhere.
//
// ON THE ENGAGEMENT AND NEVER ON THE COMPANY, which is the whole shape of 058
// and is why this is not a field on the company edit panel three functions up.
// One account's handyman is another account's contractor; a control on the
// company row would say it for both. So the console card carries one of these
// per account that engages them, and this route names the engagement.
//
// SUPERADMIN, unlike the company edit beside it. This is the entry that
// excuses somebody their insurance and their licence on a roster -- it is
// closer to the delete button than to correcting a phone number.
app.patch("/api/platform/engagements/:id", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  const denied = requireSuperadmin(c, staff);
  if (denied) return denied;

  const b = await c.req.json().catch(() => ({}));
  if (!isEngagedAs(b.engagedAs)) return c.json({ error: "bad_engaged_as" }, 400);

  const row = await c.env.DB.prepare(
    `SELECT e.id, e.account_id, e.company_id, e.engaged_as,
            a.name AS account_name, a.kind AS account_kind, co.company
       FROM engagements e
       JOIN accounts a ON a.id = e.account_id
       JOIN companies co ON co.id = e.company_id
      WHERE e.id = ?`
  ).bind(c.req.param("id")).first().catch((err) => {
    if (!missingSchema(err)) throw err;
    return null;
  });
  if (!row) return c.json({ error: "not_found" }, 404);

  // THE SAME PREDICATE THE CUSTOMER SIDE READS, not a staff exemption from it.
  // A handyman is a maintenance worker for a building, and an account with no
  // buildings has nothing for one to do -- so letting staff write the word
  // onto a general contractor's roster would put a row in the database that
  // CHECK.sql counts as a fault, from the one screen that exists to fix
  // faults. Being staff is a reason to reach another account's record, not a
  // reason for that record to be wrong.
  const want = engagedAs(b.engagedAs);
  if (isHandyman(want) && !mayEngageHandyman(row.account_kind)) {
    return c.json({ error: "not_a_handyman_account", accountKind: row.account_kind }, 409);
  }
  // NULL for a subcontractor, never the word: that is what every existing row
  // holds, and two spellings of the ordinary state is `engagedAs()` reading
  // one of them by luck.
  const store = isHandyman(want) ? "handyman" : null;
  if ((row.engaged_as || null) === store) return c.json({ error: "nothing_to_change" }, 400);

  await c.env.DB.prepare(`UPDATE engagements SET engaged_as = ? WHERE id = ?`)
    .bind(store, row.id).run();

  // Its own event, naming BOTH sides. "Staff changed a relationship" is not
  // answerable afterwards; which company, on whose roster, from what to what,
  // is -- and this is the edit that decides whether a certificate of insurance
  // is ever asked for again.
  await auditPlatform(c.env, staff, row.account_id, "engagement_relationship_changed",
    `${staff.name} set ${row.company} to ${want} on ${row.account_name}`,
    { engagementId: row.id, companyId: row.company_id,
      from: engagedAs(row.engaged_as), to: want });
  return c.json({ ok: true, engagedAs: want });
});

