app.post("/api/platform/accounts/:id/users", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;

  const accountId = c.req.param("id");
  const b = await c.req.json().catch(() => ({}));
  const name = String(b.name || "").trim();
  const email = String(b.email || "").trim().toLowerCase();
  let role = ["admin", "pm", "contractor"].includes(b.role) ? b.role : "pm";
  if (!name) return c.json({ error: "name_required" }, 400);
  if (!EMAIL_RE.test(email)) return c.json({ error: "invalid_email" }, 400);

  const account = await c.env.DB.prepare(`SELECT id FROM accounts WHERE id = ?`).bind(accountId).first();
  if (!account) return c.json({ error: "not_found" }, 404);

  // THE FIRST PERSON ON AN ACCOUNT IS ITS ADMIN, whatever the form said.
  //
  // This defaulted to `pm` and the console's form opened on `pm` too, so
  // adding the owner of a new account and not touching the dropdown gave them
  // a project manager seat -- on an account that had no admin, because the
  // account INSERT only writes one when it is given an owner email. That is
  // how Sound Property Management ended up with one person who could not
  // reach Account, billing or branding, and nobody who could grant it: every
  // door to making somebody an admin is `requireRole("admin")`, so the
  // account had locked itself out of its own settings on the day it was made.
  //
  // Forced rather than merely defaulted. A default that produces an account
  // nobody can administer is not a default, it is a trap -- and the person
  // who would discover it is the customer, weeks later, looking for billing.
  // Contractor seats are deliberately exempt: that is a roster seat with a
  // company behind it, not a member of this team, and promoting one would put
  // a subcontractor in charge of the account that hires them.
  let forcedAdmin = false;
  if (role !== "contractor") {
    const anyAdmin = await c.env.DB.prepare(
      `SELECT 1 AS yes FROM memberships WHERE account_id = ? AND role = 'admin' LIMIT 1`
    ).bind(accountId).first();
    if (!anyAdmin) { forcedAdmin = role !== "admin"; role = "admin"; }
  }

  // Somebody may already exist here from an application or another account;
  // reuse the person rather than creating a second row for the same address.
  let user = await c.env.DB.prepare(`SELECT id FROM users WHERE lower(email) = lower(?)`).bind(email).first();
  if (!user) {
    const userId = uid();
    await c.env.DB.prepare(`INSERT INTO users (id, name, email) VALUES (?, ?, ?)`)
      .bind(userId, name, email).run();
    user = { id: userId };
  }
  const existing = await c.env.DB.prepare(
    `SELECT id FROM memberships WHERE user_id = ? AND account_id = ?`).bind(user.id, accountId).first();
  if (existing) return c.json({ error: "already_a_member" }, 409);

  await c.env.DB.prepare(
    `INSERT INTO memberships (id, user_id, account_id, role) VALUES (?, ?, ?, ?)`
  ).bind(uid(), user.id, accountId, role).run();
  await auditPlatform(c.env, staff, accountId, "user_added",
    `${staff.name} added ${name} as ${role}${forcedAdmin ? " (first person on the account)" : ""}`,
    { userId: user.id, email, role, forcedAdmin });

  // Same rule as everywhere else: added is not the same as able to get in.
  // Somebody added from the console had a seat and no way to reach it.
  const full = await c.env.DB.prepare(`SELECT * FROM users WHERE id = ?`).bind(user.id).first();
  const invite = await inviteAccountUser(c, { accountId, user: full, role,
    invitedBy: { id: null, name: staff?.name || "SubSub" } });

  // `forcedAdmin` so the console can say the role was overridden. A route that
  // quietly stores something other than what the form showed is the
  // screen-that-lies rule with the lie on the server side.
  return c.json({ id: user.id, name, email, role, forcedAdmin, invite }, 201);
});

// Change a team member's role.
//
// THERE WAS NO WAY TO DO THIS ANYWHERE, and that is what made an account with
// no admin a dead end rather than a nuisance. Every door to granting the role
// is `requireRole("admin")` on the customer side, so an account whose only
// person is a project manager could not produce an admin from inside itself,
// and the console -- which exists precisely to answer what a customer cannot
// -- could add people and reset passwords and not change this one field. The
// only remaining remedy was SQL against D1.
//
// Admin and pm only. A contractor seat carries a `company_id` and belongs to
// a company on the roster; turning one into an admin would hand the account
// to a subcontractor it hires, and turning an admin into one would invent a
// company that is not there.
app.patch("/api/platform/accounts/:id/users/:userId", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;

  const accountId = c.req.param("id");
  const userId = c.req.param("userId");
  const b = await c.req.json().catch(() => ({}));
  const role = String(b.role || "");
  if (!["admin", "pm"].includes(role)) return c.json({ error: "bad_role" }, 400);

  const m = await c.env.DB.prepare(
    `SELECT id, role FROM memberships WHERE account_id = ? AND user_id = ?`
  ).bind(accountId, userId).first();
  if (!m) return c.json({ error: "not_on_this_account" }, 404);
  // A SEAT THAT IS NOT A TEAM SEAT IS NOT CHANGEABLE HERE, and the first
  // version of this refused only `contractor` -- which missed the two that
  // matter most. A building owner and a tenant hold GUEST seats on somebody
  // else's account, scoped to named buildings; promoting one hands a client,
  // or a tenant, admin of their agent's whole business. The console's Team
  // panel lists every non-contractor membership, so both were on screen with
  // a role control beside them.
  if (!isTeamSeat(m.role)) return c.json({ error: "not_a_team_seat", seat: m.role }, 409);

  // The last admin may not be demoted, for the reason `cannot_remove_self`
  // refuses on the customer side: an account with nobody who can administer
  // it cannot get itself back, and this route is the only thing that could
  // undo it. Refusing here is what keeps that true.
  if (m.role === "admin" && role !== "admin") {
    const others = await c.env.DB.prepare(
      `SELECT COUNT(*) AS n FROM memberships
        WHERE account_id = ? AND role = 'admin' AND user_id <> ?`
    ).bind(accountId, userId).first();
    if (!others?.n) return c.json({ error: "last_admin" }, 409);
  }

  if (m.role === role) return c.json({ ok: true, role, changed: false });

  await c.env.DB.prepare(
    `UPDATE memberships SET role = ? WHERE account_id = ? AND user_id = ?`
  ).bind(role, accountId, userId).run();
  // AND THE SCOPES GO WITH THE ROLE, which this route did not do and the
  // customer-side one has always done.
  //
  // Writing `memberships.role` alone left a promoted project manager's
  // buildings and jobs behind. The Worker ignores them -- `propertyScope`
  // answers null for an admin -- but `GET /api/account-users` hands the raw
  // rows to the browser, where `isScoped` saw a list and `runsTheAccount`
  // shut the account down around somebody the API would let do anything:
  // "Your buildings" instead of Properties, no Edit, no Remove, no vendor
  // list, no owners panel. Reported as exactly that, on an admin.
  //
  // Through the same two helpers the customer side uses, so what a role may
  // carry is decided in one place. Passing an empty list is what clears them:
  // each one deletes first and only writes back for a role that may hold one.
  await setMembershipProperties(c.env.DB, m.id, accountId, role, []);
  await setMembershipJobs(c.env.DB, m.id, accountId, role, []);
  const who = await c.env.DB.prepare(`SELECT name FROM users WHERE id = ?`).bind(userId).first();
  await auditPlatform(c.env, staff, accountId, "user_role_changed",
    `${staff.name} changed ${who?.name || "a user"} from ${m.role} to ${role}`,
    { userId, from: m.role, to: role });

  return c.json({ ok: true, role, changed: true, from: m.role });
});

// Staff never see or set a password. This starts the same reset the person
// could start themselves, on their behalf -- Supabase sends the mail and owns
// the token, so there is nothing here to leak and nothing to expire ourselves.
app.post("/api/platform/users/:id/reset-password", async (c) => {
  const { error, staff } = await requireStaff(c);
  if (error) return error;
  if (!c.env.SUPABASE_URL || !c.env.SUPABASE_ANON_KEY) {
    return c.json({ error: "auth_not_configured" }, 501);
  }

  const b = await c.req.json().catch(() => ({}));
  const accountId = b.accountId || null;
  const user = await c.env.DB.prepare(`SELECT id, email, name, auth_id FROM users WHERE id = ?`)
    .bind(c.req.param("id")).first();
  if (!user?.email) return c.json({ error: "not_found" }, 404);

  // Somebody added from the console has no Supabase account yet, and recover
  // on an unknown address succeeds without sending anything -- so one has to
  // be created first or the mail has nowhere to go.
  //
  // Only when there is no evidence of one, though. An auth_id means they have
  // signed in before, and signing them up again would send a confirmation
  // mail nobody asked for and spend a send against the project's hourly
  // limit -- the limit the reset itself needs.
  let created = false, authNote = null;
  if (!user.auth_id) {
    const auth = await ensureAuthUser(c.env, user.email);
    if (auth.ok) {
      created = auth.created;
      if (auth.authId) {
        await c.env.DB.prepare(`UPDATE users SET auth_id = ? WHERE id = ?`)
          .bind(auth.authId, user.id).run();
      }
    } else {
      // Not fatal. The account may well exist already and this may have
      // failed for an unrelated reason -- a send limit, most likely -- in
      // which case recover below still works. Let the recover decide, and
      // keep the reason in case it does not.
      authNote = [auth.error, auth.detail].filter(Boolean).join(": ");
      console.warn("[reset] could not ensure auth user:", user.email, authNote);
    }
  }

  // Send them back to their own company's address when it is live, and to
  // the shared one otherwise. A reset that lands on a generic sign-in page is
  // a worse first impression than the problem that caused it, and landing on
  // a branded hostname that is not serving yet is worse still.
  const acct = accountId
    ? await c.env.DB.prepare(`SELECT subdomain, hostname_status FROM accounts WHERE id = ?`)
        .bind(accountId).first().catch(() => null)
    : null;
  const redirectTo = acct?.hostname_status === "active"
    ? `https://${acct.subdomain}.${(c.env.APP_DOMAIN || "subsub.work")}`
    : `https://app.${(c.env.APP_DOMAIN || "subsub.work")}`;

  const res = await fetch(`${c.env.SUPABASE_URL}/auth/v1/recover`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: c.env.SUPABASE_ANON_KEY },
    body: JSON.stringify({ email: user.email, redirect_to: redirectTo }),
  }).catch(() => null);

  if (!res || !res.ok) {
    // Supabase's own words. "supabase_429" is not something anyone can act
    // on; "email rate limit exceeded" tells you to wait rather than to go
    // looking for a bug.
    let said = null;
    if (res) {
      const body = await res.json().catch(() => null);
      said = body?.msg || body?.error_description || body?.error || null;
    }
    const why = [said || (res ? `HTTP ${res.status}` : "Supabase was unreachable"), authNote]
      .filter(Boolean).join(" · ");
    // A durable record, because "did they get it?" is the first thing anyone
    // asks and a message in a panel is gone the moment the page is closed.
    await logMail(c.env, {
      accountId, companyId: null, to: user.email, kind: "password_reset",
      subject: "Password reset", sentBy: staff.userId,
      result: { ok: false, error: "supabase", detail: why },
    });
    return c.json({
      error: "reset_failed",
      detail: why,
      // A send limit is worth naming as itself: it is the one failure here
      // that fixes itself, and the answer is to wait rather than to retry.
      rateLimited: !!(res && (res.status === 429 || /rate limit/i.test(said || ""))),
    }, 502);
  }

  await logMail(c.env, {
    accountId, companyId: null, to: user.email,
    kind: "password_reset", subject: "Password reset", sentBy: staff.userId,
    // Supabase accepted it. That is not the same as it arriving, which is
    // why the row says who, when and what was handed over rather than
    // claiming delivery.
    result: { ok: true },
  });
  await auditPlatform(c.env, staff, accountId, "password_reset",
    `${staff.name} sent a password reset to ${user.email}`, { userId: user.id, email: user.email });

  // No link comes back: the token is in the email and nowhere else, which is
  // the property that makes this safe to do on somebody's behalf. `created`
  // says a Supabase account had to be made first, which is worth telling the
  // operator: with confirmation on, that sends a second mail of its own.
  return c.json({ ok: true, email: user.email, created });
});

// ---------------------------------------------------------------------------
// Outbound email
// ---------------------------------------------------------------------------

// Record every attempt, including the failures — "did they get it?" is the
// first thing support asks, and a send that quietly failed is worse than one
// that visibly did.
async function logMail(env, { accountId, companyId, to, kind, subject, result, sentBy }) {
  try {
    await env.DB.prepare(
      `INSERT INTO email_log (id, account_id, company_id, to_email, kind, subject, status, provider_id, error, sent_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(crypto.randomUUID(), accountId ?? null, companyId ?? null, to, kind, subject,
      result.ok ? "sent" : "failed", result.id ?? null,
      result.ok ? null : [result.error, result.detail].filter(Boolean).join(": "), sentBy ?? null).run();
  } catch (err) {
    console.error("[email_log] write failed:", err?.message || err);
  }
}

// The same for text messages. Segments matter: carriers bill per 160
// characters, not per message, so a long one is several and counting messages
// would understate the bill the console reports.
async function logSms(env, { accountId, companyId, to, kind, result }) {
  try {
    const segments = Math.max(1, Math.ceil(String(result.body || "").length / 160)) || 1;
    await env.DB.prepare(
      `INSERT INTO sms_log (id, account_id, company_id, to_phone, kind, segments, status, provider_id, error)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(crypto.randomUUID(), accountId ?? null, companyId ?? null, to, kind, segments,
      result.ok ? "sent" : "failed", result.id ?? null,
      result.ok ? null : [result.error, result.detail].filter(Boolean).join(": ")).run();
  } catch (err) {
    console.error("[sms_log] write failed:", err?.message || err);
  }
}

// What this account may text this month, how much of it is gone, and whether
// there is anything to bill an overage to.
//
// Read off the account row and sms_log every time rather than kept as a
// counter: a counter is a second record of what sms_log already says, and the
// one that drifts is the one that decides.
//
// BILLABLE means a real subscription and customer at Stripe for the overage to
// land on. A comped Scale account has the plan and no subscription, so it gets
// the included 2,500 and then pauses -- charging an account we gave the plan
// to is not a decision a sweep should make.
async function smsUsage(env, accountId, now = new Date()) {
  const a = await env.DB.prepare(
    `SELECT plan, comped, stripe_customer_id, stripe_subscription_id, subscription_status
       FROM accounts WHERE id = ?`).bind(accountId).first();
  const used = await env.DB.prepare(
    `SELECT COUNT(*) AS n FROM sms_log WHERE account_id = ? AND status = 'sent' AND at >= ?`
  ).bind(accountId, monthStart(now)).first();
  const onScale = accountOnScale(a);
  return {
    onScale,
    billable: onScale && a?.plan === "scale" && !!a?.stripe_customer_id && !!a?.stripe_subscription_id,
    allowance: smsAllowance({ onScale }),
    used: Number(used?.n) || 0,
    off: await smsOff(env, accountId),
  };
}

// Whether the account has turned text messages off. A database without 070
// reads as ON, which is what every account was before the switch existed --
// a missing table must not silently stop every text in the product.
async function smsOff(env, accountId) {
  try {
    const r = await env.DB.prepare(`SELECT sms_off FROM account_sms_settings WHERE account_id = ?`)
      .bind(accountId).first();
    return !!r?.sms_off;
  } catch (err) {
    if (missingSchema(err)) return false;
    throw err;
  }
}

// EVERY TEXT AN ACCOUNT SENDS GOES THROUGH HERE, which is what makes the
// allowance true. Seven call sites used to pair sendSms with logSms by hand; a
// count checked at six of them is a count with a door round it, and the
// seventh -- the emergency call-out -- was not even logged, so it was missing
// from the console's figure and would have been missing from the bill.
//
// Past the included 2,500 a text STILL GOES on a billable account: the month
// is charged on the 1st by `smsOverageSweep`, in $50 blocks of 5,000. What
// stops a text is the account having turned texts off, Basic (no texts), an
// account with nothing to bill, or the runaway ceiling -- see
// shared/smsquota.js.
//
// The order is deliberate. Unconfigured first, because "texting isn't set up"
// is the more useful answer and spending a database read to give a worse one
// is backwards. A refusal is LOGGED as failed with its reason, because "did
// they get a text?" is the first thing support asks; and a failed row is not
// counted, so a refusal is never billed.
async function sendAccountSms(env, { accountId, companyId = null, to, body, kind }) {
  if (!smsConfig(env)) {
    const result = { ok: false, error: "sms_not_configured" };
    if (accountId) await logSms(env, { accountId, companyId, to, kind, result: { ...result, body } });
    return result;
  }
  let verdict = { ok: true };
  if (accountId) {
    try {
      const u = await smsUsage(env, accountId);
      verdict = smsVerdict({ allowance: u.allowance, used: u.used, kind, billable: u.billable, off: u.off });
    } catch (err) {
      // A count that cannot be read must not stop a text. Logged, and sent:
      // failing closed here would turn a database hiccup into nobody being
      // told their work order was issued.
      console.error("[sms] usage read failed:", err?.message || err);
    }
    if (!verdict.ok) {
      const result = { ok: false, error: verdict.reason,
        detail: `${verdict.used} of ${verdict.allowance} this month` };
      await logSms(env, { accountId, companyId, to, kind, result: { ...result, body } });
      return result;
    }
  }
  const result = await sendSms(env, { to, body });
  await logSms(env, { accountId, companyId, to, kind, result: { ...result, body } });
  // The text that opens a new $50 block is the moment the account is told,
  // once -- not on every text after it, and not at the end of the month when
  // the charge has already happened. Only if it actually went: a failed send
  // is not counted, so it opens nothing.
  if (result.ok && verdict.overage && verdict.startsBlock) {
    await logActivity(env, accountId, null, "sms_overage",
      `Text messages passed ${(verdict.blocks === 1 ? verdict.allowance : (verdict.blocks - 1) * SMS_BLOCK_MESSAGES).toLocaleString("en-US")} this month. `
      + `Texts keep going and are charged on the 1st: ${SMS_OVERAGE_TERMS}. `
      + `They can be turned off in Account, Subscription.`).catch(() => {});
  }
  return result;
}

// Bill last month's texts on the 1st. Nightly, and idempotent by
// construction: one sms_overage row per account per month (the unique index),
// written BEFORE Stripe is asked, so a night that dies halfway leaves a
// pending row the next night finishes rather than a charge nobody recorded.
// The 1st is simply the first night the month is over; a row that failed is
// retried on the 2nd.
//
// HOW IT REACHES THE BILL. An invoice item on the customer and an invoice of
// its own, charged automatically to the card on file. The SAME shape for a
// monthly and a yearly plan -- an earlier version rode a monthly plan's next
// subscription invoice, which lands on whatever day the plan renews rather
// than on the 1st, and gave a yearly one its own invoice. One path is one
// thing to get right, and "charged on the 1st" is then true for everybody.
//
// Not exercised against live Stripe from here: the request shapes are the
// documented ones, the suite asserts them at fetch, and the first real month
// past 2,500 is the real test -- the same thing this repository records about
// every other Stripe call it could not see.
async function smsOverageSweep(env, now = new Date()) {
  const { month, from, to } = previousMonth(now);
  let rows;
  try {
    ({ results: rows } = await env.DB.prepare(
      `SELECT account_id, COUNT(*) AS n FROM sms_log
        WHERE status = 'sent' AND account_id IS NOT NULL AND at >= ? AND at < ?
        GROUP BY account_id HAVING COUNT(*) > ?`
    ).bind(from, to, SMS_INCLUDED_SCALE).all());
  } catch (err) {
    if (missingSchema(err)) return { month, skipped: "no sms_log" };
    throw err;
  }
  const out = { month, accounts: (rows || []).length, billed: 0, notBillable: 0, failed: 0, already: 0 };
  for (const r of rows || []) {
    const a = await env.DB.prepare(`SELECT * FROM accounts WHERE id = ?`).bind(r.account_id).first();
    if (!a) continue;
    const onScale = accountOnScale(a);
    const allowance = smsAllowance({ onScale });
    const blocks = smsOverageBlocks({ allowance, used: r.n });
    if (!blocks) continue;
    const amount = smsOverageCents(blocks);
    const billable = onScale && a.plan === "scale" && !!a.stripe_customer_id && !!a.stripe_subscription_id;

    let row;
    try {
      await env.DB.prepare(
        `INSERT OR IGNORE INTO sms_overage (id, account_id, month, used, allowance, blocks, amount_cents, status)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(uid(), a.id, month, r.n, allowance, blocks, amount, billable ? "pending" : "not_billable").run();
      row = await env.DB.prepare(`SELECT * FROM sms_overage WHERE account_id = ? AND month = ?`)
        .bind(a.id, month).first();
    } catch (err) {
      if (missingSchema(err)) return { ...out, migration: "070_sms_overage" };
      throw err;
    }
    if (!row || row.status === "billed") { out.already += 1; continue; }
    if (row.status === "not_billable") { out.notBillable += 1; continue; }
    if (!env.STRIPE_SECRET_KEY) { out.failed += 1; continue; }

    const label = new Date(`${month}-01T12:00:00Z`).toLocaleString("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
    const description = `Extra text messages, ${label}: ${row.used.toLocaleString("en-US")} sent, `
      + `${row.allowance.toLocaleString("en-US")} included — ${row.blocks} × ${SMS_BLOCK_MESSAGES.toLocaleString("en-US")} texts`;
    try {
      // The invoice first, EXCLUDING whatever else is pending on the customer
      // -- a proration from a plan change is not ours to charge on the 1st --
      // then the one line put on it by id. auto_advance finalises it and
      // charges the card on file within the hour.
      const inv = await stripeCall(env, "/invoices", {
        params: { customer: a.stripe_customer_id, collection_method: "charge_automatically",
          auto_advance: true, pending_invoice_items_behavior: "exclude", description,
          metadata: { account_id: a.id, sms_overage_id: row.id, month } },
        idempotencyKey: `sms-overage-invoice:${a.id}:${month}`,
      });
      const item = await stripeCall(env, "/invoiceitems", {
        params: {
          customer: a.stripe_customer_id, invoice: inv.id, amount: row.amount_cents, currency: "usd", description,
          metadata: { account_id: a.id, sms_overage_id: row.id, month },
        },
        idempotencyKey: `sms-overage:${a.id}:${month}`,
      });
      const ref = `${item.id} ${inv.id}`;
      await env.DB.prepare(
        `UPDATE sms_overage SET status = 'billed', processor_ref = ?, error = NULL,
           billed_at = CURRENT_TIMESTAMP WHERE id = ?`
      ).bind(ref, row.id).run();
      await logActivity(env, a.id, null, "sms_overage_billed",
        `${label}: ${row.used.toLocaleString("en-US")} texts sent. `
        + `$${(row.amount_cents / 100).toLocaleString("en-US")} charged to your card on file.`).catch(() => {});
      out.billed += 1;
    } catch (err) {
      console.error("[sms-overage] billing failed:", a.id, err?.message || err);
      await env.DB.prepare(`UPDATE sms_overage SET status = 'failed', error = ? WHERE id = ?`)
        .bind(String(err?.message || err).slice(0, 500), row.id).run();
      out.failed += 1;
    }
  }
  return out;
}

// Everything the document-request template needs, fetched once and shared by
// the preview and the send so the two cannot drift.
async function docRequestContext(c, companyId, jobId, trade, kind) {
  const { accountId } = c.get("auth");
  const row = await c.env.DB.prepare(
    `SELECT co.*, en.doc_review FROM companies co
       JOIN engagements en ON en.company_id = co.id AND en.account_id = ?
      WHERE co.id = ?`
  ).bind(accountId, companyId).first();
  if (!row) return null;
  const account = await c.env.DB.prepare(
    `SELECT id, name, subdomain FROM accounts WHERE id = ?`).bind(accountId).first();
  const job = jobId
    ? await c.env.DB.prepare(
        `SELECT id, title, address, area, zip, date FROM jobs WHERE id = ? AND account_id = ?`
      ).bind(jobId, accountId).first()
    : null;
  return {
    company: row, contact: row.contact, docReview: parseJson(row.doc_review, {}),
    job, trade: trade || null, account, kind: kind || null,
  };
}

// Which of the two mails this is.
//
// A document that is nearly right and a document nobody has sent are different
// news, and for most of this feature's life both got the second one -- a
// reviewer who found the hiring account missing from the additional insured
// schedule could only send "upload your compliance documents", about a
// certificate already on file. The findings decide, not the caller: a preview
// that could be asked for the wrong template is a preview that disagrees with
// what gets sent.
function docMailFor(ctx) {
  const kind = ctx.kind;
  const review = kind ? ctx.docReview?.[kind] : null;
  if (kind && review && problemsIn(review, kind, ctx.account?.name || "our team").length) {
    return { mail: docFindingsEmail({ ...ctx, review, note: review.note || null }), template: "findings" };
  }
  return { mail: docRequestEmail(ctx), template: "request" };
}

// What will be sent, built by the same function that sends it. The admin
// reviews this before pressing send.
app.get("/api/notify/documents/preview", requireRole("admin", "pm"), async (c) => {
  const ctx = await docRequestContext(c, c.req.query("companyId"), c.req.query("jobId"),
    c.req.query("trade"), c.req.query("kind"));
  if (!ctx) return c.json({ error: "not_engaged" }, 404);
  const { mail, template } = docMailFor(ctx);
  return c.json({
    to: ctx.company.email || null, subject: mail.subject, text: mail.text,
    missing: mail.missing || null, template,
    // What the screen needs to head the panel honestly: "3 things to fix on
    // their certificate" rather than "request documents".
    problems: (mail.problems || []).map((p) => ({ id: p.id, label: p.label })),
    kind: ctx.kind || null,
    configured: !!(c.env.RESEND_API_KEY && c.env.MAIL_FROM),
  });
});

app.post("/api/notify/documents", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const ctx = await docRequestContext(c, b.companyId, b.jobId, b.trade, b.kind);
  if (!ctx) return c.json({ error: "not_engaged" }, 404);

  const to = ctx.company.email;
  if (!to) return c.json({ error: "no_email_on_file" }, 400);

  // The same function the preview used, so what was reviewed on screen is what
  // goes out -- including which of the two mails it is.
  const { mail, template } = docMailFor(ctx);
  const result = await sendEmail(c.env, { to, subject: mail.subject, text: mail.text, html: mail.html });
  // Logged under its own kind, because "we told them what was wrong with their
  // certificate" and "we asked them for documents" are different events and the
  // console counts both.
  await logMail(c.env, { accountId, companyId: ctx.company.id, to,
    kind: template === "findings" ? "doc_findings" : "doc_request",
    subject: mail.subject, result, sentBy: userId });

  if (!result.ok) return c.json({ error: result.error, detail: result.detail }, 502);
  await logActivity(c.env, accountId, userId, "email_sent",
    template === "findings"
      ? `Told ${ctx.company.company} what to fix on their ${(ctx.kind || "document").replace("w9", "W-9")}`
      : `Requested documents from ${ctx.company.company}`);
  return c.json({ ok: true, to, id: result.id, template });
});

// Asking a subcontractor to turn auto-schedule on. The account cannot set it
// for them, so this is the only move available from the hiring side -- see
// shared/autoschedule.js. Same preview-then-send shape as the document
// request: the server composes the text, so what the admin reviews is what
// goes out.
//
// There is no request record and no pending state, on purpose. The answer to
// "did they agree?" is the engagement's auto_schedule flag itself; a second
// row saying "asked" could only ever drift from it, and a subcontractor who
// says no says it by leaving the switch alone rather than by pressing
// decline on something.
async function autoScheduleContext(c, companyId) {
  const { accountId } = c.get("auth");
  const row = await c.env.DB.prepare(
    `SELECT co.*, en.auto_schedule FROM companies co
       JOIN engagements en ON en.company_id = co.id AND en.account_id = ?
      WHERE co.id = ?`
  ).bind(accountId, companyId).first();
  if (!row) return null;
  const account = await c.env.DB.prepare(
    `SELECT id, name, subdomain FROM accounts WHERE id = ?`).bind(accountId).first();
  return { company: row, contact: row.contact, autoSchedule: !!row.auto_schedule, account };
}

app.get("/api/notify/auto-schedule/preview", requireRole("admin", "pm"), async (c) => {
  const ctx = await autoScheduleContext(c, c.req.query("companyId"));
  if (!ctx) return c.json({ error: "not_engaged" }, 404);
  const mail = autoScheduleRequestEmail({ ...ctx, note: c.req.query("note") || "" });
  return c.json({
    to: ctx.company.email || null, subject: mail.subject, text: mail.text,
    configured: !!(c.env.RESEND_API_KEY && c.env.MAIL_FROM),
  });
});

app.post("/api/notify/auto-schedule", requireRole("admin", "pm"), async (c) => {
  const { accountId, userId } = c.get("auth");
  const b = await c.req.json().catch(() => ({}));
  const ctx = await autoScheduleContext(c, b.companyId);
  if (!ctx) return c.json({ error: "not_engaged" }, 404);
  // Nothing to ask for. Worth saying rather than sending a mail that tells
  // somebody to switch on what is already on.
  if (ctx.autoSchedule) return c.json({ error: "already_on" }, 409);

  const to = ctx.company.email;
  if (!to) return c.json({ error: "no_email_on_file" }, 400);

  const note = String(b.note || "").trim().slice(0, 400);
  const mail = autoScheduleRequestEmail({ ...ctx, note });
  const result = await sendEmail(c.env, { to, subject: mail.subject, text: mail.text, html: mail.html });
  await logMail(c.env, { accountId, companyId: ctx.company.id, to, kind: "auto_schedule_request",
    subject: mail.subject, result, sentBy: userId });

  if (!result.ok) return c.json({ error: result.error, detail: result.detail }, 502);
  await logActivity(c.env, accountId, userId, "email_sent",
    `Asked ${ctx.company.company} to turn on auto-schedule`);
  return c.json({ ok: true, to, id: result.id });
});

// What has been sent to this subcontractor, for the account that asks.
app.get("/api/notify/log", async (c) => {
  const { accountId } = c.get("auth");
  const companyId = c.req.query("companyId");
  const { results } = await c.env.DB.prepare(
    `SELECT id, company_id, to_email, kind, subject, status, error, at
       FROM email_log
      WHERE account_id = ?${companyId ? " AND company_id = ?" : ""}
      ORDER BY at DESC LIMIT 100`
  ).bind(...(companyId ? [accountId, companyId] : [accountId])).all();
  return c.json(results.map((r) => ({
    id: r.id, companyId: r.company_id, to: r.to_email, kind: r.kind,
    subject: r.subject, status: r.status, error: r.error, at: r.at,
  })));
});

export default {
  fetch: app.fetch,

  // wrangler.toml declares a nightly Cron Trigger, and until this existed
  // there was no `scheduled` handler for it to call -- the schedule fired
  // and the sweeps never ran. The HTTP routes above stay, because being able
  // to run either one by hand is worth keeping.
  async scheduled(event, env, ctx) {
    // Two schedules, two jobs. A certificate is issued in a couple of
    // minutes, so a customer waiting on their address should not wait until
    // 3am to find out it is live; a state licensing register changes at
    // most daily and there is no reason to hammer it.
    const nightly = event.cron === "0 3 * * *";
    const jobs = nightly
      ? [["hostnames", hostnameSweep], ["licenses", licenseSweep],
         ["doc-expiry", docExpirySweep], ["license-reminders", licenseReminderSweep],
         ["retouch", retouchSweep],
         ["embed-nudge", embedNudgeSweep], ["sms-overage", smsOverageSweep],
         ["referrals", referralSweep]]
      : [["hostnames", hostnameSweep]];

    ctx.waitUntil((async () => {
      for (const [name, run] of jobs) {
        try {
          console.log(`[cron] ${name}`, JSON.stringify(await run(env)));
        } catch (err) {
          // One sweep failing must not take the other down with it.
          console.error(`[cron] ${name} failed:`, err?.stack || err?.message || err);
        }
      }
    })());
  },
};
